// ============================================================================
// Model constants
// ============================================================================

// ============================================================================
// Model configuration — runtime values loaded from model_weights.json
// MAX_* constants are compile-time upper bounds for static array sizing.
// g_cfg.* are the actual runtime values for the loaded model.
// ============================================================================

// Compile-time maximums (for static arrays — must be >= any supported model)
#define MAX_LAYERS          64
#define MAX_EXPERTS         512
#define MAX_HIDDEN_DIM      4096
#define MAX_K               8

// Runtime model configuration (populated from config.json / model_weights.json)
typedef struct {
	int hidden_dim;
	int num_layers;
	int num_attn_heads;
	int num_kv_heads;
	int head_dim;
	int vocab_size;
	int num_experts;
	int num_experts_per_tok;
	int moe_intermediate;
	int shared_intermediate;
	int full_attn_interval;
	int group_size;
	int linear_num_v_heads;
	int linear_num_k_heads;
	int linear_key_dim;
	int linear_value_dim;
	int conv_kernel_size;
	float rope_theta;
	float partial_rotary;
	float rms_norm_eps;
	// Derived
	int linear_total_key;    // linear_num_k_heads * linear_key_dim
	int linear_total_value;  // linear_num_v_heads * linear_value_dim
	int linear_conv_dim;     // linear_total_key * 2 + linear_total_value
	int rotary_dim;          // head_dim * partial_rotary
	int num_full_attn_layers;
	int num_linear_layers;
	// 4-bit expert component offsets (computed from hidden_dim, moe_intermediate, group_size)
	size_t gate_w_off_4, gate_s_off_4, gate_b_off_4;
	size_t up_w_off_4, up_s_off_4, up_b_off_4;
	size_t down_w_off_4, down_s_off_4, down_b_off_4;
	size_t expert_size_computed;
	// 2-bit expert component offsets
	size_t gate_w_off_2, gate_s_off_2, gate_b_off_2;
	size_t up_w_off_2, up_s_off_2, up_b_off_2;
	size_t down_w_off_2, down_s_off_2, down_b_off_2;
	size_t expert_size_2bit_computed;
} ModelConfig;

static ModelConfig g_cfg = {0};
static int g_config_loaded = 0;

// Qwen3.5-35B-A3B fallback geometry. A real config.json/model manifest is still
// required below; these values only keep partial-config parsing deterministic.
static void config_init_defaults(void) {
	g_cfg.hidden_dim = 2048;
	g_cfg.num_layers = 40;
	g_cfg.num_attn_heads = 16;
	g_cfg.num_kv_heads = 2;
	g_cfg.head_dim = 256;
	g_cfg.vocab_size = 248320;
	g_cfg.num_experts = 256;
	g_cfg.num_experts_per_tok = 8;
	g_cfg.moe_intermediate = 512;
	g_cfg.shared_intermediate = 512;
	g_cfg.full_attn_interval = 4;
	g_cfg.group_size = 64;
	g_cfg.linear_num_v_heads = 32;
	g_cfg.linear_num_k_heads = 16;
	g_cfg.linear_key_dim = 128;
	g_cfg.linear_value_dim = 128;
	g_cfg.conv_kernel_size = 4;
	g_cfg.rope_theta = 10000000.0f;
	g_cfg.partial_rotary = 0.25f;
	g_cfg.rms_norm_eps = 1e-6f;
	// Derived
	g_cfg.linear_total_key = g_cfg.linear_num_k_heads * g_cfg.linear_key_dim;
	g_cfg.linear_total_value = g_cfg.linear_num_v_heads * g_cfg.linear_value_dim;
	g_cfg.linear_conv_dim = g_cfg.linear_total_key * 2 + g_cfg.linear_total_value;
	g_cfg.rotary_dim = (int)(g_cfg.head_dim * g_cfg.partial_rotary);
	g_cfg.num_full_attn_layers = g_cfg.num_layers / g_cfg.full_attn_interval;
	g_cfg.num_linear_layers = g_cfg.num_layers - g_cfg.num_full_attn_layers;
}

static int validate_config_primitives(const char *source) {
	const char *where = source ? source : "model config";

	if (g_cfg.hidden_dim <= 0 || g_cfg.hidden_dim > MAX_HIDDEN_DIM ||
		g_cfg.num_layers <= 0 || g_cfg.num_layers > MAX_LAYERS ||
		g_cfg.num_attn_heads <= 0 ||
		g_cfg.num_kv_heads <= 0 ||
		g_cfg.head_dim <= 0 ||
		g_cfg.vocab_size <= 0 ||
		g_cfg.num_experts <= 0 || g_cfg.num_experts > MAX_EXPERTS ||
		g_cfg.num_experts_per_tok <= 0 ||
		g_cfg.moe_intermediate <= 0 ||
		g_cfg.shared_intermediate <= 0 ||
		g_cfg.full_attn_interval <= 0 ||
		g_cfg.group_size <= 0 ||
		g_cfg.linear_num_v_heads <= 0 ||
		g_cfg.linear_num_k_heads <= 0 ||
		g_cfg.linear_key_dim <= 0 ||
		g_cfg.linear_value_dim <= 0 ||
		g_cfg.conv_kernel_size < 2) {
		fprintf(stderr, "ERROR: invalid/non-positive model geometry in %s\n", where);
		return 0;
	}

	if (g_cfg.num_attn_heads % g_cfg.num_kv_heads != 0) {
		fprintf(stderr,
				"ERROR: num_attention_heads=%d is not divisible by num_key_value_heads=%d in %s\n",
				g_cfg.num_attn_heads, g_cfg.num_kv_heads, where);
		return 0;
	}
	if (g_cfg.linear_num_v_heads % g_cfg.linear_num_k_heads != 0) {
		fprintf(stderr,
				"ERROR: linear value heads=%d are not divisible by key heads=%d in %s\n",
				g_cfg.linear_num_v_heads, g_cfg.linear_num_k_heads, where);
		return 0;
	}
	if (g_cfg.hidden_dim % g_cfg.group_size != 0 ||
		g_cfg.moe_intermediate % g_cfg.group_size != 0) {
		fprintf(stderr,
				"ERROR: group_size=%d does not divide hidden=%d / moe_dim=%d in %s\n",
				g_cfg.group_size, g_cfg.hidden_dim, g_cfg.moe_intermediate, where);
		return 0;
	}
	if (!isfinite(g_cfg.rms_norm_eps) || g_cfg.rms_norm_eps <= 0.0f ||
		!isfinite(g_cfg.rope_theta) || g_cfg.rope_theta <= 0.0f ||
		!isfinite(g_cfg.partial_rotary) ||
		g_cfg.partial_rotary <= 0.0f || g_cfg.partial_rotary > 1.0f) {
		fprintf(stderr, "ERROR: invalid RMS/RoPE values in %s\n", where);
		return 0;
	}

	// This engine is target-locked. Reject unsupported primitive geometry before
	// config_update_derived() performs any signed dimension arithmetic.
	if (g_cfg.hidden_dim != 2048 || g_cfg.num_layers != 40 ||
		g_cfg.num_attn_heads != 16 || g_cfg.num_kv_heads != 2 ||
		g_cfg.head_dim != 256 || g_cfg.vocab_size != 248320 ||
		g_cfg.num_experts != 256 || g_cfg.num_experts_per_tok != 8 ||
		g_cfg.moe_intermediate != 512 || g_cfg.shared_intermediate != 512 ||
		g_cfg.full_attn_interval != 4 || g_cfg.group_size != 64 ||
		g_cfg.linear_num_v_heads != 32 || g_cfg.linear_num_k_heads != 16 ||
		g_cfg.linear_key_dim != 128 || g_cfg.linear_value_dim != 128 ||
		g_cfg.conv_kernel_size != 4) {
		fprintf(stderr,
				"ERROR: unsupported target geometry in %s; this build requires "
				"Qwen3.5-35B-A3B primitives\n", where);
		return 0;
	}
	return 1;
}

static void config_update_derived(void) {
	g_cfg.linear_total_key = g_cfg.linear_num_k_heads * g_cfg.linear_key_dim;
	g_cfg.linear_total_value = g_cfg.linear_num_v_heads * g_cfg.linear_value_dim;
	g_cfg.linear_conv_dim = g_cfg.linear_total_key * 2 + g_cfg.linear_total_value;
	g_cfg.rotary_dim = (int)(g_cfg.head_dim * g_cfg.partial_rotary);
	g_cfg.num_full_attn_layers = g_cfg.num_layers / g_cfg.full_attn_interval;
	g_cfg.num_linear_layers = g_cfg.num_layers - g_cfg.num_full_attn_layers;

	// Compute expert component offsets (matches iOS compute_expert_offsets)
	int mid = g_cfg.moe_intermediate;
	int hid = g_cfg.hidden_dim;
	int gs = g_cfg.group_size;

	for (int b = 4; b >= 2; b -= 2) {
		int vals_per_u32 = 32 / b;
		// gate_proj [mid, hid]
		size_t gw = (size_t)mid * ((hid + vals_per_u32 - 1) / vals_per_u32) * 4;
		size_t gs_sz = (size_t)mid * ((hid + gs - 1) / gs) * 2;
		size_t gb = gs_sz;
		// up_proj [mid, hid] — same shape
		size_t uw = gw, us = gs_sz, ub = gb;
		// down_proj [hid, mid]
		size_t dw = (size_t)hid * ((mid + vals_per_u32 - 1) / vals_per_u32) * 4;
		size_t ds = (size_t)hid * ((mid + gs - 1) / gs) * 2;
		size_t db = ds;

		size_t off = 0;
		if (b == 4) {
			g_cfg.gate_w_off_4 = off; off += gw;
			g_cfg.gate_s_off_4 = off; off += gs_sz;
			g_cfg.gate_b_off_4 = off; off += gb;
			g_cfg.up_w_off_4   = off; off += uw;
			g_cfg.up_s_off_4   = off; off += us;
			g_cfg.up_b_off_4   = off; off += ub;
			g_cfg.down_w_off_4 = off; off += dw;
			g_cfg.down_s_off_4 = off; off += ds;
			g_cfg.down_b_off_4 = off; off += db;
			g_cfg.expert_size_computed = off;
		} else {
			g_cfg.gate_w_off_2 = off; off += gw;
			g_cfg.gate_s_off_2 = off; off += gs_sz;
			g_cfg.gate_b_off_2 = off; off += gb;
			g_cfg.up_w_off_2   = off; off += uw;
			g_cfg.up_s_off_2   = off; off += us;
			g_cfg.up_b_off_2   = off; off += ub;
			g_cfg.down_w_off_2 = off; off += dw;
			g_cfg.down_s_off_2 = off; off += ds;
			g_cfg.down_b_off_2 = off; off += db;
			g_cfg.expert_size_2bit_computed = off;
		}
	}
	// expert_size_computed is already set above
}

static int validate_target_architecture(void) {
	if (!g_config_loaded) {
		fprintf(stderr,
				"ERROR: No model configuration was loaded. "
				"This build requires Qwen3.5-35B-A3B config.json/model manifest.\n");
		return 0;
	}
	if (g_cfg.hidden_dim != 2048 ||
		g_cfg.num_layers != 40 ||
		g_cfg.num_attn_heads != 16 ||
		g_cfg.num_kv_heads != 2 ||
		g_cfg.head_dim != 256 ||
		g_cfg.vocab_size != 248320 ||
		g_cfg.num_experts != 256 ||
		g_cfg.num_experts_per_tok != 8 ||
		g_cfg.moe_intermediate != 512 ||
		g_cfg.shared_intermediate != 512 ||
		g_cfg.full_attn_interval != 4 ||
		g_cfg.linear_num_v_heads != 32 ||
		g_cfg.linear_num_k_heads != 16 ||
		g_cfg.linear_key_dim != 128 ||
		g_cfg.linear_value_dim != 128 ||
		g_cfg.conv_kernel_size != 4 ||
		g_cfg.group_size != 64 ||
		fabsf(g_cfg.rms_norm_eps - 1.0e-6f) > 1.0e-9f ||
		fabsf(g_cfg.rope_theta - 10000000.0f) > 1.0f ||
		fabsf(g_cfg.partial_rotary - 0.25f) > 1.0e-6f ||
		g_cfg.rotary_dim != 64 ||
		g_cfg.num_full_attn_layers != 10 ||
		g_cfg.num_linear_layers != 30) {
		fprintf(stderr,
				"ERROR: This build targets Qwen3.5-35B-A3B; "
				"loaded model has hidden=%d layers=%d experts=%d K=%d "
				"moe_dim=%d (%d linear + %d full).\n",
				g_cfg.hidden_dim, g_cfg.num_layers, g_cfg.num_experts,
				g_cfg.num_experts_per_tok, g_cfg.moe_intermediate,
				g_cfg.num_linear_layers, g_cfg.num_full_attn_layers);
		return 0;
	}
	return 1;
}


