// expert projections on the non-outlier layers.
#define Q3_OUTLIER_LAYER 27
#define IQ3_XXS_EXPERT_PROJ_SIZE 1605632
#define EXPERT_SIZE_Q3_HYBRID    5439488
#define GATE_W_OFF_Q3  0
#define UP_W_OFF_Q3    (GATE_W_OFF_Q3 + IQ3_XXS_EXPERT_PROJ_SIZE)
#define DOWN_W_OFF_Q3  (UP_W_OFF_Q3   + IQ3_XXS_EXPERT_PROJ_SIZE)
#define DOWN_S_OFF_Q3  DOWN_W_OFF_Q3
#define DOWN_B_OFF_Q3  DOWN_W_OFF_Q3

// Layer-27 streamed Q3 outlier:
//   gate/up   = exact GGUF IQ4_XS bytes
//   down      = exact GGUF Q5_K bytes
#define IQ4_XS_EXPERT_PROJ_SIZE              2228224
#define Q5_K_EXPERT_PROJ_SIZE                2883584
#define EXPERT_SIZE_Q3_OUTLIER               7340032
#define GATE_W_OFF_Q3_OUTLIER  0
#define UP_W_OFF_Q3_OUTLIER    (GATE_W_OFF_Q3_OUTLIER + IQ4_XS_EXPERT_PROJ_SIZE)
#define DOWN_W_OFF_Q3_OUTLIER  (UP_W_OFF_Q3_OUTLIER   + IQ4_XS_EXPERT_PROJ_SIZE)
#define DOWN_S_OFF_Q3_OUTLIER  DOWN_W_OFF_Q3_OUTLIER
#define DOWN_B_OFF_Q3_OUTLIER  DOWN_W_OFF_Q3_OUTLIER

// Qwen3.5-35B-A3B native context ceiling and this engine's GPU KV mirror window.
// The current macOS CPU KV allocation remains intentionally capped below the
// model-native limit; context_preflight() rejects requests before overflow.
#define MAX_SEQ_LEN 262144
#define GPU_KV_SEQ  8192

// Runtime CPU KV sequence limit used by kv_cache_new().
static int g_kv_seq_len = 65536;
static int g_forward_error = 0;

static int context_preflight(const char *where, int current_pos,
							 int input_tokens, int requested_generation) {
	if (current_pos < 0 || input_tokens < 0 || requested_generation < 0) {
		fprintf(stderr, "ERROR: invalid context accounting in %s\n",
				where ? where : "inference");
		return 0;
	}
	long long required = (long long)current_pos +
						 (long long)input_tokens +
						 (long long)requested_generation;
	if (required > (long long)g_kv_seq_len) {
		fprintf(stderr,
				"ERROR: context request exceeds engine KV capacity in %s: "
				"current=%d + input=%d + generation=%d = %lld > %d\n",
				where ? where : "inference",
				current_pos, input_tokens, requested_generation,
				required, g_kv_seq_len);
		return 0;
	}
	return 1;
}
