typedef struct {
	uint16_t d;  // fp16
	int8_t   qs[GGUF_QK8_0];
} GGUFBlockQ8_0;

_Static_assert(sizeof(GGUFBlockQ8_0) == 34, "GGUF Q8_0 block size must stay exact");

typedef struct {
	uint8_t  ql[GGUF_QK_K/2];
	uint8_t  qh[GGUF_QK_K/4];
	int8_t   scales[GGUF_QK_K/16];
	uint16_t d;  // fp16
} GGUFBlockQ6K;

_Static_assert(sizeof(GGUFBlockQ6K) == 210, "GGUF Q6_K block size must stay exact");

// ============================================================================
// Timing helper
// ============================================================================

static double now_ms(void) {
	struct timeval tv;
	gettimeofday(&tv, NULL);
	return tv.tv_sec * 1000.0 + tv.tv_usec / 1000.0;
}

// Metal GPUStartTime/GPUEndTime are host times relative to system mach time.
// Use the same clock domain for exact CPU<->GPU boundary measurements.
static double mach_time_s(void) {
	static mach_timebase_info_data_t tb = {0, 0};
	if (tb.denom == 0) mach_timebase_info(&tb);
	uint64_t t = mach_absolute_time();
	return (double)t * (double)tb.numer / (double)tb.denom / 1.0e9;
}

static void format_eta(double eta_s, char *buf, size_t buf_size) {
	if (eta_s < 0) eta_s = 0;
	int total = (int)(eta_s + 0.5);
	int hours = total / 3600;
	int minutes = (total % 3600) / 60;
	int seconds = total % 60;
	if (hours > 0) {
		snprintf(buf, buf_size, "%d:%02d:%02d", hours, minutes, seconds);
	} else {
		snprintf(buf, buf_size, "%02d:%02d", minutes, seconds);
	}
}

// ============================================================================
// Per-phase timing accumulators for fused_layer_forward
// Tracks time spent in each pipeline phase across all layers per token.
// Reset at token boundary, printed as summary.
// ============================================================================

typedef struct {
	double deferred_wait;    // waiting for previous CMD3 GPU
	double deferred_cpu;     // CPU readback + combine for deferred experts
	double input_norm;       // CPU RMS norm + CMD1 prep
	double cmd1_submit;      // CMD1 encode + commit
	double cmd1_wait;        // CMD1 waitUntilCompleted
	double cpu_attn;         // CPU attention compute (delta-net or full-attn)
	double cmd2_encode;      // CMD2 encode (o_proj + residual + norm + routing)
	double cmd2_wait;        // CMD2 commit + waitUntilCompleted
	double routing_cpu;      // CPU softmax + topK
	double spec_route;       // speculative early routing (gate matvec + topK)
	double expert_io;        // parallel pread + cache lookup
	double cmd3_encode;      // CMD3 encode experts + submit (deferred)
	double lm_head;          // LM head projection (per-token, outside layer loop)
	double total;            // total per-layer time
	double total_linear;     // total time for linear attention layers
	double total_full;       // total time for full attention layers
	int count;               // number of layers timed
	int count_linear;        // linear attention layers timed
	int count_full;          // full attention layers timed
	int token_count;         // number of tokens (for lm_head avg)
} LayerTimingAccum;

static LayerTimingAccum g_timing = {0};
static int g_timing_enabled = 0;

// Low-overhead decode pipeline profiler. GPU timestamps are read only after
// synchronization points that already exist in the production path. I/O task
// timestamps are collected only while --pipeline-profile is active.
typedef struct {
	uint64_t gpu_layers;
	uint64_t gpu_timestamp_layers;
	double cmd1_gpu_ms;
	double cmd2_gpu_ms;
	double cmd12_gap_ms;

	// CMD2 -> CMD3 closes the important router / expert-load dependency gap.
	double cmd23_gap_ms;
	uint64_t cmd23_gap_count;
	double pending_cmd2_end_s;

	// CMD3 is recorded per-layer as well as globally.
	double cmd3_gpu_ms;
	uint64_t cmd3_timestamp_layers;

	// Previous layer CMD3 -> this layer CMD1.
	double prev_cmd3_to_cmd1_gap_ms;
	uint64_t prev_gap_count;

	// CPU/wall sections which are mutually exclusive within a layer call.
	double layer_wall_ms;
	uint64_t layer_wall_count;
	double routing_cpu_wall_ms;
	double expert_cache_lookup_ms;
	double expert_io_wait_ms;
	double expert_post_stage_ms;
	double expert_stage_wall_ms;

	// Exact CMD2 -> CMD3 dependency decomposition.
	double cmd2_gpuend_to_waitreturn_ms;
	double waitreturn_to_route_start_ms;
	double route_end_to_expert_start_ms;
	double expert_end_to_cmd3_commit_ms;
	double cmd3_commit_to_gpustart_ms;
	double cmd3_commit_to_gate_signal_ms;
	double cmd3_gate_signal_to_gpustart_ms;
	uint64_t cmd3_gate_count;

	// Host anchors for the current layer occurrence.
	double pending_wait_return_mach_s;
	double pending_route_start_mach_s;
	double pending_route_end_mach_s;
	double pending_expert_start_mach_s;
	double pending_expert_end_mach_s;
	double pending_cmd3_commit_mach_s;
	double pending_cmd3_gate_signal_mach_s;

	double cmd3_encode_wall_ms;
} PipelineLayerProfile;

typedef struct {
	uint64_t cmd3_count;
	uint64_t cmd3_timestamp_count;
	double cmd3_gpu_ms;

	uint64_t io_tasks;
	uint64_t io_batches;
	uint64_t io_bytes;
	double io_queue_delay_ms;
	double io_service_ms;
	double io_batch_span_ms;
	uint64_t io_timed_tasks;

	// End-to-end decode-token wall clock. These fields partition each token.
	uint64_t tokens;
	double token_wall_ms;
	double embed_wall_ms;
	double layers_wall_ms;
	double final_deferred_wall_ms;
	double final_norm_wall_ms;
	double lm_total_wall_ms;
	double lm_gpu_ms;
	double sample_cpu_ms;
	double output_wall_ms;

	// Token-boundary GPU gaps.
	double last_cmd3_to_lm_gap_ms;
	uint64_t last_cmd3_to_lm_gap_count;
	double lm_to_next_cmd1_gap_ms;
	uint64_t lm_to_next_cmd1_gap_count;
	double pending_last_cmd3_end_s;
	double pending_lm_end_s;

	PipelineLayerProfile layer[MAX_LAYERS];
} PipelineProfile;

static PipelineProfile g_pipeline_profile = {0};
static int g_pipeline_profile_enabled = 0;
static int g_pipeline_profile_decode_active = 0;

// Last LM-head GPU command interval. Populated by the GPU matvec helpers only
// while decode profiling is active; read after lm_head_forward* returns.
static double g_profile_lm_gpu_start_s = 0.0;
static double g_profile_lm_gpu_end_s = 0.0;
static double g_profile_lm_gpu_ms = 0.0;

static inline void pipeline_profile_reset_lm_capture(void) {
	g_profile_lm_gpu_start_s = 0.0;
	g_profile_lm_gpu_end_s = 0.0;
	g_profile_lm_gpu_ms = 0.0;
}

static inline void pipeline_profile_capture_lm_cmd(id<MTLCommandBuffer> cmd) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active || !cmd) return;
	double s = cmd.GPUStartTime, e = cmd.GPUEndTime;
	if (s > 0.0 && e >= s) {
		if (g_profile_lm_gpu_start_s == 0.0 || s < g_profile_lm_gpu_start_s)
			g_profile_lm_gpu_start_s = s;
		if (e > g_profile_lm_gpu_end_s) g_profile_lm_gpu_end_s = e;
		g_profile_lm_gpu_ms += (e - s) * 1000.0;
	}
}

