// ============================================================================
// Tiered quantization: per-expert 2-bit or 4-bit within the same layer file
// ============================================================================

typedef struct {
	size_t offset;   // byte offset in layer_XX.bin
	size_t size;     // bytes to read
	int bits;        // 2 or 4
} TieredExpertInfo;

static TieredExpertInfo *g_tiered_manifest = NULL;  // [num_layers * num_experts]
static int g_use_tiered = 0;
static int g_tiered_cold_nocache = 0;

#define TIERED(l, e) g_tiered_manifest[(l) * g_cfg.num_experts + (e)]

static inline size_t tiered_expected_expert_size_for_bits(int bits) {
	if (bits == 2) return EXPERT_SIZE_2BIT;
	if (bits == 4) return EXPERT_SIZE;
	return 0;
}

static int model_json_number(id value) {
	return [value isKindOfClass:[NSNumber class]] &&
		CFGetTypeID((__bridge CFTypeRef)value) != CFBooleanGetTypeID();
}

static int model_json_uint(id value, uint64_t *out) {
	if (!model_json_number(value) ||
		CFNumberIsFloatType((__bridge CFNumberRef)value) ||
		[value longLongValue] < 0) return 0;
	if (out) *out = [value unsignedLongLongValue];
	return 1;
}

static int model_json_numeric_fields(NSDictionary *dict, NSArray<NSString *> *keys,
									const char *context) {
	for (NSString *key in keys) {
		id value = dict[key];
		if (value && !model_json_number(value)) {
			fprintf(stderr, "ERROR: %s.%s must be a number\n", context, key.UTF8String);
			return 0;
		}
	}
	return 1;
}

static int load_tiered_manifest(const char *model_path) {
	@autoreleasepool {
		char manifest_path[1024];
		snprintf(manifest_path, sizeof(manifest_path),
				 "%s/packed_experts_tiered/tiered_manifest.json", model_path);

		NSData *data = [NSData dataWithContentsOfFile:
			[NSString stringWithUTF8String:manifest_path]];
		if (!data) return 0;

		NSError *err = nil;
		NSDictionary *root = [NSJSONSerialization JSONObjectWithData:data options:0 error:&err];
		if (![root isKindOfClass:[NSDictionary class]] || err) {
			fprintf(stderr, "[tiered] Failed to parse %s\n", manifest_path);
			return 0;
		}

		uint64_t parsed_layers = 0, parsed_experts = 0;
		if (!model_json_uint(root[@"num_layers"], &parsed_layers) ||
			!model_json_uint(root[@"num_experts"], &parsed_experts) ||
			parsed_layers > INT_MAX || parsed_experts > INT_MAX) {
			fprintf(stderr, "[tiered] ERROR: num_layers and num_experts must be integers\n");
			return 0;
		}
		int num_layers = (int)parsed_layers;
		int num_experts = (int)parsed_experts;

		if (num_layers != g_cfg.num_layers || num_experts != g_cfg.num_experts) {
			fprintf(stderr, "[tiered] Manifest mismatch: %dx%d vs config %dx%d\n",
					num_layers, num_experts, g_cfg.num_layers, g_cfg.num_experts);
			return 0;
		}

		g_tiered_manifest = calloc((size_t)num_layers * num_experts, sizeof(TieredExpertInfo));
		if (!g_tiered_manifest) {
			fprintf(stderr, "[tiered] ERROR: unable to allocate tiered manifest table\n");
			return 0;
		}

		NSDictionary *layers = root[@"layers"];
		if (![layers isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[tiered] ERROR: layers must be an object\n");
			free(g_tiered_manifest); g_tiered_manifest = NULL;
			return 0;
		}
		int hot = 0, cold = 0;
		for (int l = 0; l < num_layers; l++) {
			NSString *lk = [NSString stringWithFormat:@"%d", l];
			NSDictionary *layer_info = layers[lk];
			if (layer_info && ![layer_info isKindOfClass:[NSDictionary class]]) {
				fprintf(stderr, "[tiered] ERROR: layer %d must be an object\n", l);
				free(g_tiered_manifest); g_tiered_manifest = NULL;
				return 0;
			}
			NSArray *experts = layer_info[@"experts"];
			if (experts && ![experts isKindOfClass:[NSArray class]]) {
				fprintf(stderr, "[tiered] ERROR: layer %d experts must be an array\n", l);
				free(g_tiered_manifest); g_tiered_manifest = NULL;
				return 0;
			}
			if (!experts || (int)[experts count] != num_experts) {
				// No per-expert info — assume uniform 4-bit, but still use the
				// exact fixed layout size used by the expert kernels.
				size_t expected = tiered_expected_expert_size_for_bits(4);
				for (int e = 0; e < num_experts; e++) {
					if ((size_t)e > SIZE_MAX / expected) {
						fprintf(stderr, "[tiered] ERROR: layer %d expert offset overflow\n", l);
						free(g_tiered_manifest); g_tiered_manifest = NULL;
						return 0;
					}
					TIERED(l, e).offset = (size_t)e * expected;
					TIERED(l, e).size = expected;
					TIERED(l, e).bits = 4;
					hot++;
				}
				continue;
			}
			for (int e = 0; e < num_experts; e++) {
				NSDictionary *exp = experts[e];
				if (![exp isKindOfClass:[NSDictionary class]]) {
					fprintf(stderr, "[tiered] ERROR: layer %d expert %d must be an object\n", l, e);
					free(g_tiered_manifest); g_tiered_manifest = NULL;
					return 0;
				}
				uint64_t parsed_bits = 0, off64 = 0, size64 = 0;
				if (!model_json_uint(exp[@"bits"], &parsed_bits) ||
					!model_json_uint(exp[@"offset"], &off64) ||
					!model_json_uint(exp[@"size"], &size64) ||
					parsed_bits > INT_MAX) {
					fprintf(stderr, "[tiered] ERROR: layer %d expert %d has invalid numeric metadata\n", l, e);
					free(g_tiered_manifest); g_tiered_manifest = NULL;
					return 0;
				}
				int bits = (int)parsed_bits;
				size_t expected = tiered_expected_expert_size_for_bits(bits);
				if (!expected) {
					fprintf(stderr, "[tiered] ERROR: layer %d expert %d has invalid bits=%d\n", l, e, bits);
					free(g_tiered_manifest); g_tiered_manifest = NULL;
					return 0;
				}
				if (size64 != (unsigned long long)expected ||
					off64 > (unsigned long long)SIZE_MAX || off64 > (unsigned long long)LLONG_MAX) {
					fprintf(stderr,
						"[tiered] ERROR: layer %d expert %d invalid layout "
						"(bits=%d offset=%llu size=%llu expected=%zu)\n",
						l, e, bits, off64, size64, expected);
					free(g_tiered_manifest); g_tiered_manifest = NULL;
					return 0;
				}
				TIERED(l, e).offset = (size_t)off64;
				TIERED(l, e).size = expected;
				TIERED(l, e).bits = bits;
				if (bits == 4) hot++; else cold++;
			}
		}

		printf("[tiered] Loaded manifest: %d hot (4-bit), %d cold (2-bit), %.1f%% hot\n",
			   hot, cold, 100.0 * hot / (hot + cold));
		return 1;
	}
}

static int run_tiered_json_self_tests(void) {
	char dir[] = "/tmp/flash-tiered-json.XXXXXX";
	if (!mkdtemp(dir)) return 1;
	NSString *tiered_dir = [[NSString stringWithUTF8String:dir]
		stringByAppendingPathComponent:@"packed_experts_tiered"];
	if (![[NSFileManager defaultManager] createDirectoryAtPath:tiered_dir
		withIntermediateDirectories:YES attributes:nil error:NULL]) return 1;
	NSString *path = [tiered_dir stringByAppendingPathComponent:@"tiered_manifest.json"];
	int passed = 1;
	for (NSString *fixture in @[@"{\"num_layers\":[],\"num_experts\":256}",
		@"{\"num_layers\":40,\"num_experts\":[]}"]) {
		if (![fixture writeToFile:path atomically:NO
			encoding:NSUTF8StringEncoding error:NULL] || load_tiered_manifest(dir))
			passed = 0;
	}
	NSMutableArray *experts = [NSMutableArray arrayWithCapacity:g_cfg.num_experts];
	for (int i = 0; i < g_cfg.num_experts; i++)
		[experts addObject:@{@"bits": @4, @"offset": @0, @"size": @1}];
	for (NSString *field in @[@"bits", @"offset", @"size"]) {
		NSMutableDictionary *bad = [experts[0] mutableCopy];
		bad[field] = @[];
		experts[0] = bad;
		NSDictionary *root = @{@"num_layers": @(g_cfg.num_layers),
			@"num_experts": @(g_cfg.num_experts),
			@"layers": @{@"0": @{@"experts": experts}}};
		NSData *json = [NSJSONSerialization dataWithJSONObject:root options:0 error:NULL];
		if (!json || ![json writeToFile:path atomically:NO] || load_tiered_manifest(dir))
			passed = 0;
		experts[0] = @{@"bits": @4, @"offset": @0, @"size": @1};
	}
	unlink(path.fileSystemRepresentation);
	rmdir(tiered_dir.fileSystemRepresentation);
	rmdir(dir);
	printf("[tiered-json-test] malformed scalar fields: %s\n", passed ? "PASS" : "FAIL");
	return passed ? 0 : 1;
}

static int validate_tiered_layer_file(int layer, int fd, const char *path) {
	if (!g_use_tiered || !g_tiered_manifest || fd < 0) return 1;
	struct stat st;
	if (fstat(fd, &st) != 0 || st.st_size < 0) {
		fprintf(stderr, "[tiered] ERROR: cannot stat layer %d file %s: %s\n",
			layer, path, strerror(errno));
		return 0;
	}
	uint64_t file_size = (uint64_t)st.st_size;
	for (int e = 0; e < g_cfg.num_experts; e++) {
		TieredExpertInfo *ti = &TIERED(layer, e);
		size_t expected = tiered_expected_expert_size_for_bits(ti->bits);
		uint64_t off = (uint64_t)ti->offset, size = (uint64_t)ti->size;
		if (!expected || ti->size != expected || off > file_size || size > file_size - off) {
			fprintf(stderr,
				"[tiered] ERROR: layer %d expert %d outside %s "
				"(offset=%llu size=%llu expected=%zu file=%llu)\n",
				layer, e, path, (unsigned long long)off,
				(unsigned long long)size, expected, (unsigned long long)file_size);
			return 0;
		}
	}
	return 1;
}
static int g_use_q3_experts = 0;         // enabled by --q3-experts flag: use packed_experts_Q3/ with exact GGUF routed experts
static int g_layer_is_q3_hybrid[MAX_LAYERS];  // per-layer quant: 1=Q3 hybrid, 0=4-bit
static int g_use_q3_outlier = 0;  // active layer override: exact layer-27 IQ4_XS gate/up + Q5_K down
static int g_layer_is_q3_outlier[MAX_LAYERS];
static int g_cache_telemetry_enabled = 0;  // enabled by --cache-telemetry flag
static int g_cache_io_split = 1;  // enabled by --cache-io-split N: split each routed expert pread into N page-aligned chunks
// Thinking budget policy.
//   -1 = automatic policy (default)
//    0 = unlimited thinking (explicit --think-budget 0)
//   >0 = explicit fixed thinking cap (explicit --think-budget N)
//
// Automatic policy:
//   rendered prompt < 500 tokens -> native no-thinking mode
//   otherwise size the reasoning budget from max_tokens:
//     max_tokens <= 500   -> native no-thinking mode
//     501..999            -> 30% reasoning
//     1000..5000          -> min(50%, 1000 tokens)
//     >5000               -> 20% reasoning
//
// An explicit --think-budget overrides the automatic prompt-size gate:
//   0  -> unlimited thinking
//   >0 -> fixed reasoning cap
static int g_think_budget = -1;

static int effective_think_budget(int max_gen) {
	if (g_think_budget == 0) return 0;
	if (g_think_budget > 0) {
		int budget = g_think_budget;
		if (budget > max_gen) budget = max_gen;
		return budget;
	}

	if (max_gen <= 500) return -1;
	if (max_gen < 1000) return (max_gen * 30) / 100;
	if (max_gen <= 5000) {
		int budget = max_gen / 2;
		return budget > 1000 ? 1000 : budget;
	}
	// Large output ceilings are capability limits, not a reason to spend an
	// unbounded fraction of them on hidden reasoning. DSH currently advertises
	// max_completion_tokens=32768 even for trivial turns; the old 20%% rule made
	// that 6553 hidden tokens. Keep the proportional policy, but cap the
	// automatic budget at the highest DSH profile budget we intentionally use.
	int budget = max_gen / 5;
	return budget > 3000 ? 3000 : budget;
}

static int automatic_no_think_for_prompt(int prompt_tokens, int max_gen) {
	if (g_think_budget >= 0) return 0;  // explicit override
	if (prompt_tokens < 500) return 1;
	return effective_think_budget(max_gen) < 0;
}
