// temperature <= 0 keeps the original deterministic greedy behavior.
static float g_temperature = 0.0f;
static int g_gpu_argmax_enabled = 0;
static int g_gpu_argmax_active = 0;
static uint32_t g_gpu_argmax_result = 0;
static int g_gpu_argmax_status_printed = 0;
static int g_gpu_resident_moe_enabled = 1;
static int g_gpu_resident_moe_status_printed = 0;
static int g_oproj_v3_enabled = 1;
static int g_tiny_matvec_fast_enabled = 1;       // route only 32x2048 and 1x2048 MLX4 projections to matvec_fast
static int g_tiny_matvec_telemetry_enabled = 0;  // production counts + post-run replay benchmark
static int g_cmd1_profile_enabled = 0;           // decode-only CMD1 family capture + post-run replay
static int g_cmd1_profile_decode_active = 0;     // true only inside autoregressive decode loops
static int g_cmd12_chain_enabled = 1;             // queue GPU-linear CMD2 directly behind CMD1
static int g_cmd12_chain_status_printed = 0;
static uint64_t g_cmd12_chain_layers = 0;
static uint64_t g_cmd12_chain_fast_layers = 0;
static uint64_t g_cmd12_chain_original_layers = 0;
// Full-attention CMD1 -> CMD2 chaining remains independently switchable.
static int g_cmd12_full_chain_enabled = 1;

// Default-on CMD3 I/O overlap: selective-prefetch true misses and ordinary
// malloc-cache misses start asynchronously; CMD3 is encoded+committed behind a
// GPU shared-event wait, then released when I/O ends.
static int g_cmd3_io_gate_enabled = 1;

static int validate_uniform_expert_layer_file(int layer, int fd, const char *path,
										  size_t expected_expert_size) {
	if (fd < 0) return 1;

	struct stat st;
	if (fstat(fd, &st) != 0 || st.st_size < 0) {
		fprintf(stderr, "[experts] ERROR: cannot stat layer %d file %s: %s\n",
				layer, path, strerror(errno));
		return 0;
	}

	uint64_t actual = (uint64_t)st.st_size;
	uint64_t expected = (uint64_t)expected_expert_size * (uint64_t)NUM_EXPERTS;
	if (NUM_EXPERTS <= 0 ||
		actual % (uint64_t)NUM_EXPERTS != 0 ||
		actual != expected) {
		fprintf(stderr,
				"[experts] ERROR: invalid packed layer %d size for %s "
				"(file=%llu, expected=%llu = %zu x %d)\n",
				layer, path,
				(unsigned long long)actual,
				(unsigned long long)expected,
				expected_expert_size, NUM_EXPERTS);
		return 0;
	}
	return 1;
}

static int resolve_expert_storage_mode(const char *model_path) {
	// Resolve auto-detection before cache sizing and compatibility validation.
	if (!g_use_2bit && !g_use_q3_experts && !g_use_tiered) {
		char probe[1024];
		snprintf(probe, sizeof(probe), "%s/packed_experts_tiered/tiered_manifest.json", model_path);
		if (access(probe, F_OK) == 0) {
			if (!load_tiered_manifest(model_path)) return 0;
			g_use_tiered = 1;
		}
	}
	if (g_use_tiered && !g_tiered_manifest) {
		if (!load_tiered_manifest(model_path)) {
			fprintf(stderr, "ERROR: Tiered mode requested but manifest is missing or invalid\n");
			return 0;
		}
	}

	if (!g_use_2bit && !g_use_q3_experts && !g_use_tiered) {
		char probe[1024];
		snprintf(probe, sizeof(probe), "%s/packed_experts_2bit/layer_00.bin", model_path);
		int pfd = open(probe, O_RDONLY);
		if (pfd >= 0) {
			close(pfd);
			snprintf(probe, sizeof(probe), "%s/packed_experts/layer_00.bin", model_path);
			int pfd4 = open(probe, O_RDONLY);
			if (pfd4 < 0) {
				g_use_2bit = 1;
				printf("[auto] Using 2-bit experts (4-bit not found)\n");
			} else {
				close(pfd4);
			}
		}
	}
	return 1;
}

