static inline size_t max_expert_size_for_current_config(void) {
	// Cache slots must survive any per-layer fallback/override that can occur
	// under the selected mode, not merely the currently active layer kind.
	size_t max_size = EXPERT_SIZE;  // 4-bit fallback remains possible in mixed modes
	if (g_use_2bit || g_use_tiered) {
		if ((size_t)EXPERT_SIZE_2BIT > max_size) max_size = (size_t)EXPERT_SIZE_2BIT;
	}
	if (g_use_q3_experts) {
		if (EXPERT_SIZE_Q3_HYBRID > max_size) max_size = EXPERT_SIZE_Q3_HYBRID;
		if (EXPERT_SIZE_Q3_OUTLIER > max_size) max_size = EXPERT_SIZE_Q3_OUTLIER;
	}
	return max_size;
}
static int g_freq_total_tokens = 0;  // total tokens processed while tracking

typedef struct {
	uint64_t token_clock;
	uint64_t unique_experts_touched;
	uint64_t cold_misses;
	uint64_t eviction_misses;
	uint64_t evictions;
	uint64_t reuse_le_1;
	uint64_t reuse_le_4;
	uint64_t reuse_le_16;
	uint64_t reuse_le_64;
	uint64_t reuse_gt_64;
	uint64_t reuse_distance_sum;
	uint64_t reuse_distance_samples;
} CacheTelemetry;

typedef struct {
	uint64_t hits, misses;
	uint64_t cold_misses, eviction_misses;
	uint64_t evictions_caused, evictions_suffered;
	uint64_t reuse_le_1, reuse_le_4, reuse_le_16, reuse_le_64, reuse_gt_64;
	uint64_t reuse_distance_sum, reuse_distance_samples;
	int resident_current, resident_max;
	uint64_t resident_event_sum, resident_event_samples;
} LayerCacheTelemetry;

#define SHADOW_POLICY_COUNT 5
#define SHADOW_MAX_SLOTS_PER_LAYER 32

typedef struct {
	const char *label;
	int total_entries;
	int uniform_per_layer;  // 0 => even distribution of total_entries over layers
	int occupancy[MAX_LAYERS];
	int experts[MAX_LAYERS][SHADOW_MAX_SLOTS_PER_LAYER];
	uint64_t last_used[MAX_LAYERS][SHADOW_MAX_SLOTS_PER_LAYER];
	uint64_t clock, hits, misses;
	uint64_t layer_hits[MAX_LAYERS], layer_misses[MAX_LAYERS];
} ShadowSegmentedCache;

static CacheTelemetry g_cache_telemetry = {0};
static LayerCacheTelemetry g_cache_layer[MAX_LAYERS];
static uint64_t g_cache_eviction_matrix[MAX_LAYERS][MAX_LAYERS]; // requester -> victim
static uint64_t g_cache_same_layer_evictions = 0;
static uint64_t g_cache_cross_layer_evictions = 0;
static int g_cache_real_capacity = 0;
static uint8_t g_cache_seen[MAX_LAYERS][MAX_EXPERTS];
static uint64_t g_cache_last_touch_token[MAX_LAYERS][MAX_EXPERTS];
static uint64_t g_cache_last_evict_token[MAX_LAYERS][MAX_EXPERTS];

static ShadowSegmentedCache g_shadow_cache[SHADOW_POLICY_COUNT] = {
	{ .label="segmented ~512", .total_entries=512,  .uniform_per_layer=0 },
	{ .label="segmented 640",  .total_entries=640,  .uniform_per_layer=16 },
	{ .label="segmented 800",  .total_entries=800,  .uniform_per_layer=20 },
	{ .label="segmented 960",  .total_entries=960,  .uniform_per_layer=24 },
	{ .label="segmented 1280", .total_entries=1280, .uniform_per_layer=32 },
};

static int shadow_layer_capacity(const ShadowSegmentedCache *s, int layer) {
	if (s->uniform_per_layer > 0) return s->uniform_per_layer;
	int base = s->total_entries / NUM_LAYERS;
	int rem = s->total_entries % NUM_LAYERS;
	return base + (layer < rem ? 1 : 0);
}

static void shadow_cache_reset(void) {
	for (int p = 0; p < SHADOW_POLICY_COUNT; p++) {
		ShadowSegmentedCache *s = &g_shadow_cache[p];
		memset(s->occupancy, 0, sizeof(s->occupancy));
		memset(s->last_used, 0, sizeof(s->last_used));
		memset(s->layer_hits, 0, sizeof(s->layer_hits));
		memset(s->layer_misses, 0, sizeof(s->layer_misses));
		for (int l = 0; l < NUM_LAYERS; l++)
			for (int i = 0; i < SHADOW_MAX_SLOTS_PER_LAYER; i++) s->experts[l][i] = -1;
		s->clock = s->hits = s->misses = 0;
	}
}

static void cache_telemetry_reset(void) {
	memset(&g_cache_telemetry, 0, sizeof(g_cache_telemetry));
	memset(g_cache_layer, 0, sizeof(g_cache_layer));
	memset(g_cache_eviction_matrix, 0, sizeof(g_cache_eviction_matrix));
	g_cache_same_layer_evictions = g_cache_cross_layer_evictions = 0;
	memset(g_cache_seen, 0, sizeof(g_cache_seen));
	memset(g_cache_last_touch_token, 0, sizeof(g_cache_last_touch_token));
	memset(g_cache_last_evict_token, 0, sizeof(g_cache_last_evict_token));
	shadow_cache_reset();
}

static void shadow_cache_access(int layer, int expert) {
	if (!g_cache_telemetry_enabled) return;
	if (layer < 0 || layer >= NUM_LAYERS || expert < 0 || expert >= NUM_EXPERTS) return;
	for (int p = 0; p < SHADOW_POLICY_COUNT; p++) {
		ShadowSegmentedCache *s = &g_shadow_cache[p];
		int cap = shadow_layer_capacity(s, layer);
		if (cap <= 0 || cap > SHADOW_MAX_SLOTS_PER_LAYER) continue;
		s->clock++;
		int occ = s->occupancy[layer];
		int slot = -1;
		for (int i = 0; i < occ; i++) if (s->experts[layer][i] == expert) { slot = i; break; }
		if (slot >= 0) {
			s->hits++; s->layer_hits[layer]++;
			s->last_used[layer][slot] = s->clock;
			continue;
		}
		s->misses++; s->layer_misses[layer]++;
		if (occ < cap) {
			slot = occ;
			s->occupancy[layer] = occ + 1;
		} else {
			slot = 0;
			uint64_t oldest = s->last_used[layer][0];
			for (int i = 1; i < cap; i++) if (s->last_used[layer][i] < oldest) {
				oldest = s->last_used[layer][i]; slot = i;
			}
		}
		s->experts[layer][slot] = expert;
		s->last_used[layer][slot] = s->clock;
	}
}

static void cache_telemetry_insert(int layer) {
	if (!g_cache_telemetry_enabled || layer < 0 || layer >= NUM_LAYERS) return;
	LayerCacheTelemetry *lt = &g_cache_layer[layer];
	lt->resident_current++;
	if (lt->resident_current > lt->resident_max) lt->resident_max = lt->resident_current;
	lt->resident_event_sum += (uint64_t)lt->resident_current;
	lt->resident_event_samples++;
}

static void cache_telemetry_note_token(void) {
	if (!g_cache_telemetry_enabled) return;
	g_cache_telemetry.token_clock++;
}

static void cache_telemetry_touch(int layer_idx, int expert_idx) {
	if (!g_cache_telemetry_enabled) return;
	if (layer_idx < 0 || layer_idx >= NUM_LAYERS || expert_idx < 0 || expert_idx >= NUM_EXPERTS) return;
	g_cache_layer[layer_idx].hits++;
	if (!g_cache_seen[layer_idx][expert_idx]) {
		g_cache_seen[layer_idx][expert_idx] = 1;
		g_cache_telemetry.unique_experts_touched++;
	}
	g_cache_last_touch_token[layer_idx][expert_idx] = g_cache_telemetry.token_clock;
}

static void cache_telemetry_miss(int layer_idx, int expert_idx) {
	if (!g_cache_telemetry_enabled) return;
	if (layer_idx < 0 || layer_idx >= NUM_LAYERS || expert_idx < 0 || expert_idx >= NUM_EXPERTS) return;
	LayerCacheTelemetry *lt = &g_cache_layer[layer_idx];
	lt->misses++;
	if (!g_cache_seen[layer_idx][expert_idx]) {
		g_cache_telemetry.cold_misses++; lt->cold_misses++;
		g_cache_seen[layer_idx][expert_idx] = 1;
		g_cache_telemetry.unique_experts_touched++;
	} else {
		g_cache_telemetry.eviction_misses++; lt->eviction_misses++;
		uint64_t dist = 0;
		if (g_cache_last_evict_token[layer_idx][expert_idx] > 0 &&
			g_cache_telemetry.token_clock >= g_cache_last_evict_token[layer_idx][expert_idx])
			dist = g_cache_telemetry.token_clock - g_cache_last_evict_token[layer_idx][expert_idx];
		if (dist <= 1) { g_cache_telemetry.reuse_le_1++; lt->reuse_le_1++; }
		else if (dist <= 4) { g_cache_telemetry.reuse_le_4++; lt->reuse_le_4++; }
		else if (dist <= 16) { g_cache_telemetry.reuse_le_16++; lt->reuse_le_16++; }
		else if (dist <= 64) { g_cache_telemetry.reuse_le_64++; lt->reuse_le_64++; }
		else { g_cache_telemetry.reuse_gt_64++; lt->reuse_gt_64++; }
		g_cache_telemetry.reuse_distance_sum += dist; g_cache_telemetry.reuse_distance_samples++;
		lt->reuse_distance_sum += dist; lt->reuse_distance_samples++;
	}
	g_cache_last_touch_token[layer_idx][expert_idx] = g_cache_telemetry.token_clock;
}

static void cache_telemetry_evict(int victim_layer, int expert_idx, int requesting_layer) {
	if (!g_cache_telemetry_enabled) return;
	if (victim_layer < 0 || victim_layer >= NUM_LAYERS || expert_idx < 0 || expert_idx >= NUM_EXPERTS) return;
	g_cache_telemetry.evictions++;
	g_cache_layer[victim_layer].evictions_suffered++;
	if (requesting_layer >= 0 && requesting_layer < NUM_LAYERS) {
		g_cache_layer[requesting_layer].evictions_caused++;
		g_cache_eviction_matrix[requesting_layer][victim_layer]++;
		if (requesting_layer == victim_layer) g_cache_same_layer_evictions++;
		else g_cache_cross_layer_evictions++;
	}
	if (g_cache_layer[victim_layer].resident_current > 0) g_cache_layer[victim_layer].resident_current--;
	g_cache_layer[victim_layer].resident_event_sum += (uint64_t)g_cache_layer[victim_layer].resident_current;
	g_cache_layer[victim_layer].resident_event_samples++;
	g_cache_last_evict_token[victim_layer][expert_idx] = g_cache_telemetry.token_clock;
}

static void cache_telemetry_print(uint64_t hits, uint64_t misses) {
	if (!g_cache_telemetry_enabled) return;
	uint64_t total = hits + misses;
	fprintf(stderr, "\n=== Cache Telemetry ===\n");
	fprintf(stderr, "Tokens tracked: %llu\n", g_cache_telemetry.token_clock);
	fprintf(stderr, "Unique experts touched: %llu / %d (%.1f%%)\n",
			g_cache_telemetry.unique_experts_touched,
			NUM_LAYERS * NUM_EXPERTS,
			100.0 * g_cache_telemetry.unique_experts_touched / (NUM_LAYERS * NUM_EXPERTS));
	fprintf(stderr, "Miss breakdown: cold %llu (%.1f%% of misses), eviction %llu (%.1f%% of misses)\n",
			g_cache_telemetry.cold_misses,
			misses > 0 ? 100.0 * g_cache_telemetry.cold_misses / misses : 0.0,
			g_cache_telemetry.eviction_misses,
			misses > 0 ? 100.0 * g_cache_telemetry.eviction_misses / misses : 0.0);
	fprintf(stderr, "Evictions: %llu\n", g_cache_telemetry.evictions);
	fprintf(stderr, "Eviction reuse distance: <=1 tok %llu, <=4 %llu, <=16 %llu, <=64 %llu, >64 %llu",
			g_cache_telemetry.reuse_le_1,
			g_cache_telemetry.reuse_le_4,
			g_cache_telemetry.reuse_le_16,
			g_cache_telemetry.reuse_le_64,
			g_cache_telemetry.reuse_gt_64);
	if (g_cache_telemetry.reuse_distance_samples > 0) {
		fprintf(stderr, " (avg %.1f tok)\n",
				(double)g_cache_telemetry.reuse_distance_sum / g_cache_telemetry.reuse_distance_samples);
	} else {
		fprintf(stderr, "\n");
	}
	fprintf(stderr, "Effective hit rate: %.1f%%\n", total > 0 ? 100.0 * hits / total : 0.0);

	fprintf(stderr, "\n[cache eviction analysis]\n");
	uint64_t attributed = g_cache_same_layer_evictions + g_cache_cross_layer_evictions;
	fprintf(stderr, "Same-layer evictions: %llu\n", (unsigned long long)g_cache_same_layer_evictions);
	fprintf(stderr, "Cross-layer evictions: %llu (%.1f%% of attributed evictions)\n",
		(unsigned long long)g_cache_cross_layer_evictions,
		attributed ? 100.0 * g_cache_cross_layer_evictions / attributed : 0.0);
	fprintf(stderr, "Per-layer: layer hits misses hit%% cold evict_miss caused suffered resident_now resident_max event_avg reuse_avg\n");
	for (int l = 0; l < NUM_LAYERS; l++) {
		LayerCacheTelemetry *lt = &g_cache_layer[l];
		uint64_t a = lt->hits + lt->misses;
		double event_avg = lt->resident_event_samples ? (double)lt->resident_event_sum / lt->resident_event_samples : 0.0;
		double reuse_avg = lt->reuse_distance_samples ? (double)lt->reuse_distance_sum / lt->reuse_distance_samples : 0.0;
		fprintf(stderr, "  L%02d %8llu %8llu %6.1f %6llu %10llu %7llu %8llu %12d %12d %9.2f %9.2f\n",
			l, (unsigned long long)lt->hits, (unsigned long long)lt->misses,
			a ? 100.0 * lt->hits / a : 0.0,
			(unsigned long long)lt->cold_misses, (unsigned long long)lt->eviction_misses,
			(unsigned long long)lt->evictions_caused, (unsigned long long)lt->evictions_suffered,
			lt->resident_current, lt->resident_max, event_avg, reuse_avg);
	}

	uint64_t matrix[MAX_LAYERS][MAX_LAYERS];
	memcpy(matrix, g_cache_eviction_matrix, sizeof(matrix));
	fprintf(stderr, "Top cross-layer eviction pairs (requester -> victim):\n");
	for (int rank = 0; rank < 12; rank++) {
		uint64_t best = 0; int br = -1, bv = -1;
		for (int r = 0; r < NUM_LAYERS; r++) for (int v = 0; v < NUM_LAYERS; v++) {
			if (r != v && matrix[r][v] > best) { best = matrix[r][v]; br = r; bv = v; }
		}
		if (br < 0 || best == 0) break;
		fprintf(stderr, "  L%02d -> L%02d : %llu\n", br, bv, (unsigned long long)best);
		matrix[br][bv] = 0;
	}

	fprintf(stderr, "\n[shadow segmented-cache simulation]\n");
	fprintf(stderr, "Actual global: entries=%d hit_rate=%.2f%% hits=%llu misses=%llu\n",
		g_cache_real_capacity, total ? 100.0 * hits / total : 0.0,
		(unsigned long long)hits, (unsigned long long)misses);
	for (int p = 0; p < SHADOW_POLICY_COUNT; p++) {
		ShadowSegmentedCache *s = &g_shadow_cache[p];
		uint64_t st = s->hits + s->misses;
		int c0 = shadow_layer_capacity(s, 0), cN = shadow_layer_capacity(s, NUM_LAYERS - 1);
		long long avoided = (long long)misses - (long long)s->misses;
		fprintf(stderr, "  %-15s total=%4d cap/layer=%d%s%d hit_rate=%6.2f%% hits=%llu misses=%llu misses_avoided=%+lld\n",
			s->label, s->total_entries, cN, c0 == cN ? "" : "..", c0,
			st ? 100.0 * s->hits / st : 0.0,
			(unsigned long long)s->hits, (unsigned long long)s->misses, avoided);
	}
}

static void timing_reset(void) {
	memset(&g_timing, 0, sizeof(g_timing));
	g_cmd12_chain_layers = 0;
	g_cmd12_chain_fast_layers = 0;
	g_cmd12_chain_original_layers = 0;
	g_cmd12_full_chain_layers = 0;
	g_cmd12_full_chain_fast_layers = 0;
	g_cmd12_full_chain_original_layers = 0;
}

static void timing_print(void) {
	if (g_timing.count == 0) return;
	int n = g_timing.count;
	fprintf(stderr, "\n[timing] Per-layer breakdown (avg of %d layers, ms):\n", n);
	fprintf(stderr, "  deferred_wait:  %6.3f\n", g_timing.deferred_wait / n);
	fprintf(stderr, "  deferred_cpu:   %6.3f\n", g_timing.deferred_cpu / n);
	fprintf(stderr, "  input_norm:     %6.3f\n", g_timing.input_norm / n);
	fprintf(stderr, "  cmd1_submit:    %6.3f\n", g_timing.cmd1_submit / n);
	fprintf(stderr, "  cmd1_wait:      %6.3f\n", g_timing.cmd1_wait / n);
	fprintf(stderr, "  spec_route:     %6.3f\n", g_timing.spec_route / n);
	fprintf(stderr, "  cpu_attn:       %6.3f\n", g_timing.cpu_attn / n);
	fprintf(stderr, "  cmd2_encode:    %6.3f\n", g_timing.cmd2_encode / n);
	fprintf(stderr, "  cmd2_wait:      %6.3f\n", g_timing.cmd2_wait / n);
	fprintf(stderr, "  routing_cpu:    %6.3f\n", g_timing.routing_cpu / n);
	fprintf(stderr, "  expert_io:      %6.3f\n", g_timing.expert_io / n);
	fprintf(stderr, "  cmd3_encode:    %6.3f\n", g_timing.cmd3_encode / n);
	if (g_timing.token_count > 0)
		fprintf(stderr, "  lm_head:        %6.3f  (per token, %d tokens)\n",
				g_timing.lm_head / g_timing.token_count, g_timing.token_count);
	fprintf(stderr, "  total_layer:    %6.3f\n", g_timing.total / n);
	if (g_timing.count_linear > 0)
		fprintf(stderr, "  avg_linear:     %6.3f  (GatedDeltaNet, %d layers)\n",
				g_timing.total_linear / g_timing.count_linear, g_timing.count_linear);
	if (g_timing.count_full > 0)
		fprintf(stderr, "  avg_full_attn:  %6.3f  (standard attn, %d layers)\n",
				g_timing.total_full / g_timing.count_full, g_timing.count_full);

	// Per-token decode breakdown
	if (g_timing.token_count > 0) {
		int toks = g_timing.token_count;
		int layers = g_cfg.num_layers > 0 ? g_cfg.num_layers : n;
		int linear_layers = g_cfg.num_linear_layers;
		int full_layers = g_cfg.num_full_attn_layers;
		int experts_per_token = g_cfg.num_experts_per_tok;
		int hidden_dim = g_cfg.hidden_dim;
		int vocab_size = g_cfg.vocab_size;
		// Dense/attention (CMD1 + cpu_attn): Q/K/V projections + attention compute
		double dense_attn_ms = (g_timing.cmd1_submit + g_timing.cmd1_wait + g_timing.cpu_attn) / n * layers;
		// o_proj + norm + routing + shared expert (CMD2)
		double oproj_shared_ms = (g_timing.cmd2_encode + g_timing.cmd2_wait + g_timing.routing_cpu) / n * layers;
		// Routed expert I/O (SSD pread for the configured active expert count)
		double expert_io_ms = g_timing.expert_io / n * layers;
		// Routed expert compute (CMD3 GPU forward)
		double expert_compute_ms = (g_timing.cmd3_encode + g_timing.deferred_wait + g_timing.deferred_cpu) / n * layers;
		// LM head
		double lm_ms = g_timing.lm_head / toks;
		// Total per token
		double total_ms = dense_attn_ms + oproj_shared_ms + expert_io_ms + expert_compute_ms + lm_ms;

		// Linear attn vs full attn time
		double linear_ms = (g_timing.count_linear > 0) ? g_timing.total_linear / g_timing.count_linear * linear_layers : 0;
		double full_ms = (g_timing.count_full > 0) ? g_timing.total_full / g_timing.count_full * full_layers : 0;

		fprintf(stderr, "\n[decode breakdown per token]\n");
		fprintf(stderr, "  Dense/attn (CMD1):    %6.1f ms  %4.1f%%  (Q/K/V proj + attn, %d layers)\n",
				dense_attn_ms, 100*dense_attn_ms/total_ms, layers);
		fprintf(stderr, "  o_proj+shared (CMD2): %6.1f ms  %4.1f%%  (o_proj, norm, routing, shared expert)\n",
				oproj_shared_ms, 100*oproj_shared_ms/total_ms);
		fprintf(stderr, "  Expert I/O (SSD):     %6.1f ms  %4.1f%%  (pread K=%d experts × %d layers)\n",
				expert_io_ms, 100*expert_io_ms/total_ms, experts_per_token, layers);
		fprintf(stderr, "  Expert compute (CMD3):%6.1f ms  %4.1f%%  (GPU forward K=%d × %d layers)\n",
				expert_compute_ms, 100*expert_compute_ms/total_ms, experts_per_token, layers);
		fprintf(stderr, "  LM head:              %6.1f ms  %4.1f%%  (%dK × %d matvec)\n",
				lm_ms, 100*lm_ms/total_ms, (vocab_size + 500) / 1000, hidden_dim);
		fprintf(stderr, "  ─────────────────────────────────\n");
		fprintf(stderr, "  Total per token:      %6.1f ms  (%.1f tok/s)\n",
				total_ms, 1000.0/total_ms);
		fprintf(stderr, "\n[layer-type totals — whole layers]\n");
		if (g_timing.count_linear > 0)
			fprintf(stderr, "  Linear layers:        %6.1f ms  (%d × %.3f ms)\n",
					linear_ms, linear_layers,
					g_timing.total_linear / g_timing.count_linear);
		if (g_timing.count_full > 0)
			fprintf(stderr, "  Full-attn layers:     %6.1f ms  (%d × %.3f ms)\n",
					full_ms, full_layers,
					g_timing.total_full / g_timing.count_full);
	}
	fprintf(stderr, "  sum_phases:     %6.3f\n",
			(g_timing.deferred_wait + g_timing.deferred_cpu + g_timing.input_norm +
			 g_timing.cmd1_submit + g_timing.cmd1_wait + g_timing.spec_route +
			 g_timing.cpu_attn +
			 g_timing.cmd2_encode + g_timing.cmd2_wait + g_timing.routing_cpu +
			 g_timing.expert_io + g_timing.cmd3_encode) / n);
	fprintf(stderr, "  cmd_buffers:    %d (3 per layer: CMD1+CMD2+CMD3)\n", n * 3);
	if (g_cmd12_chain_enabled || g_cmd12_full_chain_enabled) {
		unsigned long long linear_removed = (unsigned long long)g_cmd12_chain_layers;
		unsigned long long full_removed = (unsigned long long)g_cmd12_full_chain_layers;
		unsigned long long removed = linear_removed + full_removed;
		long long waits = (long long)n * 2 - (long long)removed;
		if (waits < 0) waits = 0;
		fprintf(stderr,
				"  sync_waits:     %lld (%llu total CMD1 waits removed)\n",
				waits, removed);
		if (g_cmd12_chain_enabled) {
			fprintf(stderr,
					"  [cmd12-chain]   linear removed=%llu fast=%llu original=%llu\n",
					linear_removed,
					(unsigned long long)g_cmd12_chain_fast_layers,
					(unsigned long long)g_cmd12_chain_original_layers);
		}
		if (g_cmd12_full_chain_enabled) {
			fprintf(stderr,
					"  [cmd12-full]    full-attn removed=%llu fast=%llu original=%llu "
					"(eligible seq_len 32..%d)\n",
					full_removed,
					(unsigned long long)g_cmd12_full_chain_fast_layers,
					(unsigned long long)g_cmd12_full_chain_original_layers,
					GPU_KV_SEQ);
		}
	} else {
		fprintf(stderr, "  sync_waits:     %d (2 per layer: CMD1+CMD2, CMD3 deferred)\n", n * 2);
	}
	fprintf(stderr, "  gpu_encoders:   ~%d per layer (CMD1:3-4, CMD2:8-12, CMD3:~10)\n",
			22);  // approximate
	if (g_pred_enabled && g_pred_layers > 0) {
		uint64_t total = g_pred_hits + g_pred_misses;
		double hit_rate = total > 0 ? (double)g_pred_hits / total * 100.0 : 0;
		fprintf(stderr, "  [predict] hits=%llu misses=%llu rate=%.1f%% layers=%llu\n",
				g_pred_hits, g_pred_misses, hit_rate, g_pred_layers);
	}
}

// ============================================================================
// bf16 <-> f32 conversion (CPU side)
// ============================================================================

static float bf16_to_f32(uint16_t bf16) {
	uint32_t bits = (uint32_t)bf16 << 16;
	float f;
	memcpy(&f, &bits, 4);
	return f;
}

static float f16_to_f32(uint16_t fp16_bits) {
	__fp16 h;
	memcpy(&h, &fp16_bits, sizeof(h));
	return (float)h;
}

__attribute__((unused))
static uint16_t f32_to_bf16(float f) {
	uint32_t bits;
	memcpy(&bits, &f, 4);
	return (uint16_t)(bits >> 16);
}

// ============================================================================
// JSON parser (minimal, for model_weights.json)
// ============================================================================

// We use NSJSONSerialization via ObjC since we already link Foundation
#define TENSOR_HT_SIZE 8192  // power of 2; reserve one empty lookup sentinel

typedef struct {
	const char *name;
	size_t offset;
	size_t size;
	int ndim;
	int shape[4];
	char dtype[8];  // "U32", "BF16", "F32"
} TensorInfo;

typedef struct {
	TensorInfo *tensors;
	int num_tensors;
	int capacity;
} TensorManifest;

static void free_tensor_manifest(TensorManifest *m) {
	if (!m) return;
	if (m->tensors) {
		for (int i = 0; i < m->capacity; i++)
			free((void *)m->tensors[i].name);
		free(m->tensors);
	}
	free(m);
}

static TensorManifest *load_manifest(const char *json_path) {
	@autoreleasepool {
		NSData *data = [NSData dataWithContentsOfFile:
			[NSString stringWithUTF8String:json_path]];
		if (!data) {
			fprintf(stderr, "ERROR: Cannot read %s\n", json_path);
			return NULL;
		}

		NSError *error = nil;
		NSDictionary *root = [NSJSONSerialization JSONObjectWithData:data
															 options:0
															   error:&error];
		if (![root isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "ERROR: manifest root must be an object: %s\n",
					error ? [[error localizedDescription] UTF8String] : "wrong JSON type");
			return NULL;
		}

		NSDictionary *tensors = root[@"tensors"];
		if (![tensors isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "ERROR: 'tensors' must be an object in manifest\n");
			return NULL;
		}
		if ([tensors count] >= TENSOR_HT_SIZE) {
			fprintf(stderr, "ERROR: tensor manifest exceeds lookup-table capacity\n");
			return NULL;
		}

		TensorManifest *m = calloc(1, sizeof(TensorManifest));
		if (!m) {
			fprintf(stderr, "ERROR: Cannot allocate tensor manifest\n");
			return NULL;
		}
		m->capacity = (int)[tensors count] + 16;
		m->tensors = calloc((size_t)m->capacity, sizeof(TensorInfo));
		if (!m->tensors) {
			fprintf(stderr, "ERROR: Cannot allocate tensor manifest entries\n");
			free(m);
			return NULL;
		}
		m->num_tensors = 0;

		for (NSString *key in tensors) {
			NSDictionary *info = tensors[key];
			if (![key isKindOfClass:[NSString class]] ||
				![info isKindOfClass:[NSDictionary class]]) {
				fprintf(stderr, "ERROR: malformed tensor manifest entry\n");
				goto manifest_fail;
			}
			TensorInfo *t = &m->tensors[m->num_tensors];

			const char *name = [key UTF8String];
			NSNumber *offset_obj = info[@"offset"];
			NSNumber *size_obj = info[@"size"];
			NSArray *shape = info[@"shape"];
			NSString *dtype_obj = info[@"dtype"];
			const char *dtype = [dtype_obj isKindOfClass:[NSString class]]
				? [dtype_obj UTF8String] : NULL;
			uint64_t parsed_offset = 0, parsed_size = 0;

			if (!name || !*name ||
				!model_json_uint(offset_obj, &parsed_offset) ||
				!model_json_uint(size_obj, &parsed_size) ||
				![shape isKindOfClass:[NSArray class]] ||
				[shape count] > 4 ||
				!dtype || !*dtype) {
				fprintf(stderr, "ERROR: malformed tensor metadata for '%s'\n",
						name ? name : "(null)");
				goto manifest_fail;
			}

			t->name = strdup(name);
			if (!t->name) goto manifest_fail;
			t->offset = (size_t)parsed_offset;
			t->size = (size_t)parsed_size;
			t->ndim = (int)[shape count];
			for (int i = 0; i < t->ndim; i++) {
				uint64_t dim = 0;
				if (!model_json_uint(shape[i], &dim) || dim == 0 || dim > INT_MAX) {
					fprintf(stderr, "ERROR: invalid shape for tensor '%s'\n", name);
					goto manifest_fail;
				}
				t->shape[i] = [shape[i] intValue];
			}
			strncpy(t->dtype, dtype, sizeof(t->dtype) - 1);
			t->dtype[sizeof(t->dtype) - 1] = '\0';

			m->num_tensors++;
		}

		printf("[manifest] Loaded %d tensors from %s\n", m->num_tensors, json_path);
		return m;

manifest_fail:
		free_tensor_manifest(m);
		return NULL;
	}
}

static int model_config_scalars_valid(NSDictionary *cfg, const char *context) {
	NSArray<NSString *> *integer_keys = @[
		@"hidden_size", @"num_hidden_layers", @"num_attention_heads",
		@"num_key_value_heads", @"head_dim", @"vocab_size", @"num_experts",
		@"num_experts_per_tok", @"moe_intermediate_size",
		@"shared_expert_intermediate_size", @"full_attention_interval",
		@"linear_num_value_heads", @"linear_num_key_heads",
		@"linear_key_head_dim", @"linear_value_head_dim",
		@"linear_conv_kernel_dim"];
	for (NSString *key in integer_keys) {
		id value = cfg[key];
		uint64_t parsed = 0;
		if (value && (!model_json_uint(value, &parsed) || parsed > INT_MAX)) {
			fprintf(stderr, "ERROR: %s.%s must be a non-negative integer <= INT_MAX\n",
				context, key.UTF8String);
			return 0;
		}
	}
	return model_json_numeric_fields(cfg,
		@[@"rms_norm_eps", @"rope_theta", @"partial_rotary_factor"], context);
}

// Load model config from model_weights.json "config" section
static void load_config_from_manifest(const char *json_path) {
	@autoreleasepool {
		NSData *data = [NSData dataWithContentsOfFile:
			[NSString stringWithUTF8String:json_path]];
		if (!data) return;

		NSError *error = nil;
		NSDictionary *root = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
		if (![root isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[config] ERROR: manifest root must be an object\n");
			g_config_loaded = 0;
			return;
		}

		NSDictionary *cfg = root[@"config"];
		if (cfg && ![cfg isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[config] ERROR: manifest config must be an object\n");
			g_config_loaded = 0;
			return;
		}
		if (!cfg) {
			fprintf(stderr, "[config] No 'config' section in manifest, using defaults\n");
			return;
		}
		if (!model_config_scalars_valid(cfg, "manifest.config")) {
			g_config_loaded = 0;
			return;
		}

		// Read values with defaults
		if (cfg[@"hidden_size"])         g_cfg.hidden_dim = [cfg[@"hidden_size"] intValue];
		if (cfg[@"num_hidden_layers"])   g_cfg.num_layers = [cfg[@"num_hidden_layers"] intValue];
		if (cfg[@"num_attention_heads"]) g_cfg.num_attn_heads = [cfg[@"num_attention_heads"] intValue];
		if (cfg[@"num_key_value_heads"]) g_cfg.num_kv_heads = [cfg[@"num_key_value_heads"] intValue];
		if (cfg[@"head_dim"])            g_cfg.head_dim = [cfg[@"head_dim"] intValue];
		if (cfg[@"vocab_size"])          g_cfg.vocab_size = [cfg[@"vocab_size"] intValue];
		if (cfg[@"num_experts"])         g_cfg.num_experts = [cfg[@"num_experts"] intValue];
		if (cfg[@"num_experts_per_tok"]) g_cfg.num_experts_per_tok = [cfg[@"num_experts_per_tok"] intValue];
		if (cfg[@"moe_intermediate_size"]) g_cfg.moe_intermediate = [cfg[@"moe_intermediate_size"] intValue];
		if (cfg[@"shared_expert_intermediate_size"]) g_cfg.shared_intermediate = [cfg[@"shared_expert_intermediate_size"] intValue];
		if (cfg[@"full_attention_interval"]) g_cfg.full_attn_interval = [cfg[@"full_attention_interval"] intValue];
		if (cfg[@"rms_norm_eps"])        g_cfg.rms_norm_eps = [cfg[@"rms_norm_eps"] floatValue];
		if (cfg[@"rope_theta"])          g_cfg.rope_theta = [cfg[@"rope_theta"] floatValue];
		if (cfg[@"partial_rotary_factor"]) g_cfg.partial_rotary = [cfg[@"partial_rotary_factor"] floatValue];

		// Linear attention
		if (cfg[@"linear_num_value_heads"]) g_cfg.linear_num_v_heads = [cfg[@"linear_num_value_heads"] intValue];
		if (cfg[@"linear_num_key_heads"])   g_cfg.linear_num_k_heads = [cfg[@"linear_num_key_heads"] intValue];
		if (cfg[@"linear_key_head_dim"])    g_cfg.linear_key_dim = [cfg[@"linear_key_head_dim"] intValue];
		if (cfg[@"linear_value_head_dim"])  g_cfg.linear_value_dim = [cfg[@"linear_value_head_dim"] intValue];
		if (cfg[@"linear_conv_kernel_dim"]) g_cfg.conv_kernel_size = [cfg[@"linear_conv_kernel_dim"] intValue];

		if (!validate_config_primitives(json_path)) {
			g_config_loaded = 0;
			return;
		}
		config_update_derived();
		g_config_loaded = 1;

		// Validate against MAX_* bounds
		if (g_cfg.num_layers > MAX_LAYERS) {
			fprintf(stderr, "ERROR: num_layers %d exceeds MAX_LAYERS %d\n", g_cfg.num_layers, MAX_LAYERS);
			exit(1);
		}
		if (g_cfg.num_experts > MAX_EXPERTS) {
			fprintf(stderr, "ERROR: num_experts %d exceeds MAX_EXPERTS %d\n", g_cfg.num_experts, MAX_EXPERTS);
			exit(1);
		}
		if (g_cfg.hidden_dim > MAX_HIDDEN_DIM) {
			fprintf(stderr, "ERROR: hidden_dim %d exceeds MAX_HIDDEN_DIM %d\n", g_cfg.hidden_dim, MAX_HIDDEN_DIM);
			exit(1);
		}

		printf("[config] Model: hidden=%d, layers=%d (%d linear + %d full), "
			   "experts=%d (K=%d), moe_dim=%d, vocab=%d\n",
			   g_cfg.hidden_dim, g_cfg.num_layers,
			   g_cfg.num_linear_layers, g_cfg.num_full_attn_layers,
			   g_cfg.num_experts, g_cfg.num_experts_per_tok,
			   g_cfg.moe_intermediate, g_cfg.vocab_size);
	}
}

// Also load from standalone config.json (e.g. from iOS model package)
static void load_config_from_config_json(const char *model_path) {
	@autoreleasepool {
		char path[1024];
		snprintf(path, sizeof(path), "%s/config.json", model_path);
		NSData *data = [NSData dataWithContentsOfFile:
			[NSString stringWithUTF8String:path]];
		if (!data) return;

		NSError *error = nil;
		NSDictionary *root = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
		if (![root isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[config] ERROR: config.json root must be an object\n");
			g_config_loaded = 0;
			return;
		}

		// Check for text_config (multimodal models nest config there)
		NSDictionary *cfg = root[@"text_config"];
		if (cfg && ![cfg isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[config] ERROR: text_config must be an object\n");
			g_config_loaded = 0;
			return;
		}
		if (!cfg) cfg = root;
		if (!model_config_scalars_valid(cfg, "config")) {
			g_config_loaded = 0;
			return;
		}

		if (cfg[@"hidden_size"])         g_cfg.hidden_dim = [cfg[@"hidden_size"] intValue];
		if (cfg[@"num_hidden_layers"])   g_cfg.num_layers = [cfg[@"num_hidden_layers"] intValue];
		if (cfg[@"num_attention_heads"]) g_cfg.num_attn_heads = [cfg[@"num_attention_heads"] intValue];
		if (cfg[@"num_key_value_heads"]) g_cfg.num_kv_heads = [cfg[@"num_key_value_heads"] intValue];
		if (cfg[@"head_dim"])            g_cfg.head_dim = [cfg[@"head_dim"] intValue];
		if (cfg[@"vocab_size"])          g_cfg.vocab_size = [cfg[@"vocab_size"] intValue];
		if (cfg[@"num_experts"])         g_cfg.num_experts = [cfg[@"num_experts"] intValue];
		if (cfg[@"num_experts_per_tok"]) g_cfg.num_experts_per_tok = [cfg[@"num_experts_per_tok"] intValue];
		if (cfg[@"moe_intermediate_size"]) g_cfg.moe_intermediate = [cfg[@"moe_intermediate_size"] intValue];
		if (cfg[@"shared_expert_intermediate_size"]) g_cfg.shared_intermediate = [cfg[@"shared_expert_intermediate_size"] intValue];
		if (cfg[@"full_attention_interval"]) g_cfg.full_attn_interval = [cfg[@"full_attention_interval"] intValue];
		if (cfg[@"rms_norm_eps"])        g_cfg.rms_norm_eps = [cfg[@"rms_norm_eps"] floatValue];
		if (cfg[@"linear_num_value_heads"]) g_cfg.linear_num_v_heads = [cfg[@"linear_num_value_heads"] intValue];
		if (cfg[@"linear_num_key_heads"])   g_cfg.linear_num_k_heads = [cfg[@"linear_num_key_heads"] intValue];
		if (cfg[@"linear_key_head_dim"])    g_cfg.linear_key_dim = [cfg[@"linear_key_head_dim"] intValue];
		if (cfg[@"linear_value_head_dim"])  g_cfg.linear_value_dim = [cfg[@"linear_value_head_dim"] intValue];
		if (cfg[@"linear_conv_kernel_dim"]) g_cfg.conv_kernel_size = [cfg[@"linear_conv_kernel_dim"] intValue];

		// rope_theta may be in rope_parameters
		NSDictionary *rope = cfg[@"rope_parameters"];
		if (!rope) rope = cfg[@"rope_scaling"];
		if (rope && ![rope isKindOfClass:[NSDictionary class]]) {
			fprintf(stderr, "[config] ERROR: rope parameters must be an object\n");
			g_config_loaded = 0;
			return;
		}
		if (rope && !model_json_numeric_fields(rope,
			@[@"rope_theta", @"partial_rotary_factor"], "config.rope")) {
			g_config_loaded = 0;
			return;
		}
		if (rope && rope[@"rope_theta"]) g_cfg.rope_theta = [rope[@"rope_theta"] floatValue];
		if (cfg[@"partial_rotary_factor"]) g_cfg.partial_rotary = [cfg[@"partial_rotary_factor"] floatValue];
		if (rope && rope[@"partial_rotary_factor"]) g_cfg.partial_rotary = [rope[@"partial_rotary_factor"] floatValue];

		if (!validate_config_primitives(path)) {
			g_config_loaded = 0;
			return;
		}
		config_update_derived();
		g_config_loaded = 1;
		printf("[config] Loaded from %s\n", path);
	}
}

// Hash table for O(1) tensor lookup (replaces O(N) linear scan).
// FNV-1a hash, open addressing with linear probing.
typedef struct {
	const char *key;     // tensor name (pointer into TensorInfo)
	TensorInfo *value;   // pointer to tensor info
} TensorHTEntry;

static TensorHTEntry tensor_ht[TENSOR_HT_SIZE];
static int tensor_ht_built = 0;

static uint32_t fnv1a(const char *s) {
	uint32_t h = 2166136261u;
	for (; *s; s++) {
		h ^= (uint8_t)*s;
		h *= 16777619u;
	}
	return h;
}

static int build_tensor_ht(TensorManifest *m) {
	if (tensor_ht_built) return 1;
	if (!m || m->num_tensors < 0 || m->num_tensors >= TENSOR_HT_SIZE) return 0;
	memset(tensor_ht, 0, sizeof(tensor_ht));
	for (int i = 0; i < m->num_tensors; i++) {
		uint32_t idx = fnv1a(m->tensors[i].name) & (TENSOR_HT_SIZE - 1);
		uint32_t probes = 0;
		while (tensor_ht[idx].key && probes++ < TENSOR_HT_SIZE) {
			idx = (idx + 1) & (TENSOR_HT_SIZE - 1);
		}
		if (probes >= TENSOR_HT_SIZE) return 0;
		tensor_ht[idx].key = m->tensors[i].name;
		tensor_ht[idx].value = &m->tensors[i];
	}
	tensor_ht_built = 1;
	return 1;
}

static TensorInfo *find_tensor(TensorManifest *m, const char *name) {
	if (!tensor_ht_built && !build_tensor_ht(m)) return NULL;
	uint32_t idx = fnv1a(name) & (TENSOR_HT_SIZE - 1);
	for (uint32_t probes = 0; probes < TENSOR_HT_SIZE && tensor_ht[idx].key; probes++) {
		if (strcmp(tensor_ht[idx].key, name) == 0) {
			return tensor_ht[idx].value;
		}
		idx = (idx + 1) & (TENSOR_HT_SIZE - 1);
	}
	return NULL;
}

static int run_manifest_lookup_self_tests(void) {
	TensorManifest overfull = {.num_tensors = TENSOR_HT_SIZE};
	tensor_ht_built = 0;
	int passed = !build_tensor_ht(&overfull);
	TensorInfo one = {.name = "present"};
	TensorManifest small = {.tensors = &one, .num_tensors = 1};
	passed = passed && find_tensor(&small, "present") == &one &&
		find_tensor(&small, "absent") == NULL;
	TensorInfo *near_capacity = calloc(TENSOR_HT_SIZE - 1, sizeof(*near_capacity));
	if (!near_capacity) return 1;
	for (int i = 0; i < TENSOR_HT_SIZE - 1; i++) near_capacity[i].name = "collision";
	TensorManifest nearly_full = {.tensors = near_capacity, .num_tensors = TENSOR_HT_SIZE - 1};
	tensor_ht_built = 0;
	passed = passed && build_tensor_ht(&nearly_full) &&
		find_tensor(&nearly_full, "missing") == NULL;
	free(near_capacity);
	// A full table must terminate even if the requested tensor is absent.
	for (int i = 0; i < TENSOR_HT_SIZE; i++) {
		tensor_ht[i].key = "occupied";
		tensor_ht[i].value = &one;
	}
	tensor_ht_built = 1;
	passed = passed && find_tensor(&small, "absent") == NULL;
	memset(tensor_ht, 0, sizeof(tensor_ht));
	tensor_ht_built = 0;
	printf("[manifest-test] bounded lookup and capacity: %s\n", passed ? "PASS" : "FAIL");
	return passed ? 0 : 1;
}

static int run_model_json_container_self_tests(void) {
	char path[] = "/tmp/flash-model-json-test.XXXXXX";
	int fd = mkstemp(path);
	if (fd < 0) return 1;
	const char *invalid_roots[] = {"[]", "{\"tensors\":[]}"};
	int passed = 1;
	for (int i = 0; i < 2; i++) {
		const char *body = invalid_roots[i];
		if (ftruncate(fd, 0) != 0 || lseek(fd, 0, SEEK_SET) < 0 ||
			write(fd, body, strlen(body)) != (ssize_t)strlen(body) ||
			load_manifest(path) != NULL) passed = 0;
	}
	const char *bad_manifest_config = "{\"config\":[]}";
	if (ftruncate(fd, 0) != 0 || lseek(fd, 0, SEEK_SET) < 0 ||
		write(fd, bad_manifest_config, strlen(bad_manifest_config)) !=
			(ssize_t)strlen(bad_manifest_config)) passed = 0;
	g_config_loaded = 1;
	load_config_from_manifest(path);
	if (g_config_loaded) passed = 0;
	const char *bad_manifest_scalar = "{\"config\":{\"hidden_size\":{}}}";
	if (ftruncate(fd, 0) != 0 || lseek(fd, 0, SEEK_SET) < 0 ||
		write(fd, bad_manifest_scalar, strlen(bad_manifest_scalar)) !=
			(ssize_t)strlen(bad_manifest_scalar)) passed = 0;
	g_config_loaded = 1;
	load_config_from_manifest(path);
	if (g_config_loaded) passed = 0;
	close(fd);
	unlink(path);
	char dir[] = "/tmp/flash-model-config-test.XXXXXX";
	if (!mkdtemp(dir)) return 1;
	NSString *config_path = [[NSString stringWithUTF8String:dir]
		stringByAppendingPathComponent:@"config.json"];
	for (NSString *json in @[@"{\"text_config\":[]}",
		@"{\"text_config\":{\"rope_parameters\":[]}}",
		@"{\"text_config\":{\"hidden_size\":{}}}",
		@"{\"text_config\":{\"rope_parameters\":{\"rope_theta\":[]}}}"]) {
		if (![json writeToFile:config_path atomically:NO
			encoding:NSUTF8StringEncoding error:NULL]) passed = 0;
		g_config_loaded = 1;
		load_config_from_config_json(dir);
		if (g_config_loaded) passed = 0;
	}
	unlink(config_path.fileSystemRepresentation);
	rmdir(dir);
	printf("[manifest-test] JSON root and tensor container types: %s\n",
		passed ? "PASS" : "FAIL");
	return passed ? 0 : 1;
}

// ============================================================================
// Weight file: mmap'd binary blob
// ============================================================================

typedef struct {
	void *data;
	size_t size;
	TensorManifest *manifest;
	void *gguf_embedding_data;
	size_t gguf_embedding_size;
	char *gguf_embedding_path;
	void *gguf_full_attn_data;
	size_t gguf_full_attn_size;
	char *gguf_full_attn_path;
	char *gguf_full_attn_json_path;
	void *gguf_full_attn_q_layers[MAX_LAYERS];
	void *gguf_full_attn_k_layers[MAX_LAYERS];
	void *gguf_full_attn_v_layers[MAX_LAYERS];
	void *gguf_full_attn_o_layers[MAX_LAYERS];
	void *gguf_qkv_data;
	size_t gguf_qkv_size;
	char *gguf_qkv_path;
	char *gguf_qkv_json_path;
	void *gguf_qkv_layers[MAX_LAYERS];
	void *gguf_linear_data;
	size_t gguf_linear_size;
	char *gguf_linear_path;
	char *gguf_linear_json_path;
	void *gguf_linear_z_layers[MAX_LAYERS];
	void *gguf_linear_out_layers[MAX_LAYERS];
	void *gguf_shared_data;
	size_t gguf_shared_size;
	char *gguf_shared_path;
	char *gguf_shared_json_path;
	void *gguf_shared_gate_layers[MAX_LAYERS];
	void *gguf_shared_up_layers[MAX_LAYERS];
	void *gguf_shared_down_layers[MAX_LAYERS];
	void *gguf_lm_head_data;
	size_t gguf_lm_head_size;
	char *gguf_lm_head_path;
} WeightFile;

static int validate_manifest_bounds(TensorManifest *m, size_t weight_size) {
	if (!m || !m->tensors || weight_size == 0) return 0;

	for (int i = 0; i < m->num_tensors; i++) {
		TensorInfo *t = &m->tensors[i];
		if (!t->name || t->size == 0 ||
			t->offset > weight_size ||
			t->size > weight_size - t->offset) {
			fprintf(stderr,
					"ERROR: tensor '%s' is outside model_weights.bin "
					"(offset=%zu size=%zu file=%zu)\n",
					t->name ? t->name : "(null)",
					t->offset, t->size, weight_size);
			return 0;
		}
	}
	return 1;
}

static WeightFile *open_weights(const char *bin_path, const char *json_path) {
	// mmap the binary file
	int fd = open(bin_path, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "ERROR: Cannot open %s: %s\n", bin_path, strerror(errno));
		return NULL;
	}

	struct stat st;
	if (fstat(fd, &st) != 0 || st.st_size <= 0) {
		fprintf(stderr, "ERROR: Cannot stat/validate %s: %s\n",
				bin_path, strerror(errno));
		close(fd);
		return NULL;
	}
	size_t size = (size_t)st.st_size;

	void *data = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
	close(fd);
	if (data == MAP_FAILED) {
		fprintf(stderr, "ERROR: mmap failed: %s\n", strerror(errno));
		return NULL;
	}

	// Advise sequential access
	madvise(data, size, MADV_SEQUENTIAL);

	TensorManifest *manifest = load_manifest(json_path);
	if (!manifest || !validate_manifest_bounds(manifest, size)) {
		free_tensor_manifest(manifest);
		munmap(data, size);
		return NULL;
	}

	WeightFile *wf = calloc(1, sizeof(WeightFile));
	if (!wf) {
		fprintf(stderr, "ERROR: Cannot allocate WeightFile\n");
		free_tensor_manifest(manifest);
		munmap(data, size);
		return NULL;
	}
	wf->data = data;
	wf->size = size;
	wf->manifest = manifest;

	printf("[weights] mmap'd %.2f GB from %s\n", size / 1e9, bin_path);
	return wf;
}

static void *get_tensor_ptr(WeightFile *wf, const char *name) {
	if (!wf || !wf->manifest || !wf->data || !name) return NULL;
	TensorInfo *t = find_tensor(wf->manifest, name);
	if (!t) {
		fprintf(stderr, "WARNING: tensor '%s' not found\n", name);
		return NULL;
	}
	if (t->offset > wf->size || t->size > wf->size - t->offset) {
		fprintf(stderr, "ERROR: tensor '%s' points outside mapped weights\n", name);
		g_forward_error = 1;
		return NULL;
	}
	return (char *)wf->data + t->offset;
}

static TensorInfo *get_tensor_info(WeightFile *wf, const char *name) {
	return find_tensor(wf->manifest, name);
}

#include "tensor_layout_validation.inc"

static int attach_gguf_embedding(WeightFile *wf, const char *bin_path) {
	if (!bin_path || !*bin_path) {
		return 1;
	}

	int fd = open(bin_path, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "ERROR: Cannot open GGUF embedding %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	struct stat st;
	if (fstat(fd, &st) != 0) {
		fprintf(stderr, "ERROR: Cannot stat GGUF embedding %s: %s\n", bin_path, strerror(errno));
		close(fd);
		return 0;
	}

	const size_t expected_size = (size_t)VOCAB_SIZE * (HIDDEN_DIM / GGUF_QK8_0) * sizeof(GGUFBlockQ8_0);
	if ((size_t)st.st_size != expected_size) {
		fprintf(stderr,
				"ERROR: GGUF embedding size mismatch for %s: got %zu bytes, expected %zu bytes\n",
				bin_path, (size_t)st.st_size, expected_size);
		close(fd);
		return 0;
	}

	void *data = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
	close(fd);
	if (data == MAP_FAILED) {
		fprintf(stderr, "ERROR: mmap failed for GGUF embedding %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	madvise(data, (size_t)st.st_size, MADV_RANDOM);
	wf->gguf_embedding_data = data;
	wf->gguf_embedding_size = (size_t)st.st_size;
	wf->gguf_embedding_path = strdup(bin_path);

	printf("[embedding] Using GGUF Q8_0 embedding from %s (%.2f GB)\n",
		   bin_path, wf->gguf_embedding_size / 1e9);
	return 1;
}

static NSArray *validated_gguf_overlay_entries(const char *json_path,
									const char *kind, int needs_role) {
	NSData *data = [NSData dataWithContentsOfFile:[NSString stringWithUTF8String:json_path]];
	if (!data) {
		fprintf(stderr, "ERROR: cannot read GGUF %s overlay manifest %s\n", kind, json_path);
		return nil;
	}
	NSError *error = nil;
	id root = [NSJSONSerialization JSONObjectWithData:data options:0 error:&error];
	if (![root isKindOfClass:[NSDictionary class]]) {
		fprintf(stderr, "ERROR: GGUF %s manifest root must be an object: %s\n",
			kind, json_path);
		return nil;
	}
	id entries = ((NSDictionary *)root)[@"entries"];
	if (![entries isKindOfClass:[NSArray class]]) {
		fprintf(stderr, "ERROR: GGUF %s manifest entries must be an array: %s\n",
			kind, json_path);
		return nil;
	}
	NSUInteger index = 0;
	for (id entry in (NSArray *)entries) {
		NSDictionary *item = [entry isKindOfClass:[NSDictionary class]] ? entry : nil;
		uint64_t layer = 0, offset = 0, size = 0, in_dim = 0, out_dim = 0;
		id shape = item[@"shape"];
		if (!item || !model_json_uint(item[@"layer"], &layer) || layer > INT_MAX ||
			!model_json_uint(item[@"offset"], &offset) ||
			!model_json_uint(item[@"size"], &size) ||
			![item[@"tensor_type"] isKindOfClass:[NSString class]] ||
			(needs_role && ![item[@"role"] isKindOfClass:[NSString class]]) ||
			![shape isKindOfClass:[NSArray class]] || [shape count] != 2 ||
			!model_json_uint(shape[0], &in_dim) ||
			!model_json_uint(shape[1], &out_dim) ||
			in_dim == 0 || out_dim == 0 || in_dim % GGUF_QK8_0 != 0 ||
			in_dim > INT_MAX || out_dim > INT_MAX ||
			out_dim > SIZE_MAX / (in_dim / GGUF_QK8_0) / sizeof(GGUFBlockQ8_0))
			goto invalid_entry;
		index++;
		continue;
invalid_entry:
		fprintf(stderr, "ERROR: GGUF %s manifest entry %lu has invalid types or shape: %s\n",
			kind, (unsigned long)index, json_path);
		return nil;
	}
	return entries;
}

static int gguf_overlay_expected_geometry(const char *kind, int layer,
		NSString *role, size_t *expected_in, size_t *expected_out) {
	if (!kind || layer < 0 || layer >= NUM_LAYERS || !expected_in || !expected_out)
		return 0;
	int is_full = ((layer + 1) % FULL_ATTN_INTERVAL == 0);
	if (strcmp(kind, "full-attn") == 0) {
		if (!is_full || !role) return 0;
		*expected_in = HIDDEN_DIM;
		if ([role isEqualToString:@"q"])
			*expected_out = (size_t)NUM_ATTN_HEADS * HEAD_DIM * 2u;
		else if ([role isEqualToString:@"k"] || [role isEqualToString:@"v"])
			*expected_out = (size_t)NUM_KV_HEADS * HEAD_DIM;
		else if ([role isEqualToString:@"o"]) {
			*expected_in = (size_t)NUM_ATTN_HEADS * HEAD_DIM;
			*expected_out = HIDDEN_DIM;
		} else return 0;
		return 1;
	}
	if (strcmp(kind, "qkv") == 0) {
		if (is_full) return 0;
		*expected_in = HIDDEN_DIM;
		*expected_out = LINEAR_CONV_DIM;
		return 1;
	}
	if (strcmp(kind, "linear") == 0) {
		if (is_full || !role) return 0;
		if ([role isEqualToString:@"gate"]) {
			*expected_in = HIDDEN_DIM;
			*expected_out = LINEAR_TOTAL_VALUE;
		} else if ([role isEqualToString:@"out"]) {
			*expected_in = LINEAR_TOTAL_VALUE;
			*expected_out = HIDDEN_DIM;
		} else return 0;
		return 1;
	}
	if (strcmp(kind, "shared") == 0) {
		if (!role) return 0;
		if ([role isEqualToString:@"gate"] || [role isEqualToString:@"up"]) {
			*expected_in = HIDDEN_DIM;
			*expected_out = SHARED_INTERMEDIATE;
		} else if ([role isEqualToString:@"down"]) {
			*expected_in = SHARED_INTERMEDIATE;
			*expected_out = HIDDEN_DIM;
		} else return 0;
		return 1;
	}
	return 0;
}

static int attach_gguf_full_attn_overlay(WeightFile *wf, const char *bin_path, const char *json_path) {
	if (!bin_path || !*bin_path) {
		return 1;
	}
	if (!json_path || !*json_path) {
		fprintf(stderr, "ERROR: GGUF full-attn overlay requires both --gguf-full-attn-bin and --gguf-full-attn-json\n");
		return 0;
	}

	int fd = open(bin_path, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "ERROR: Cannot open GGUF full-attn overlay %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	struct stat st;
	if (fstat(fd, &st) != 0) {
		fprintf(stderr, "ERROR: Cannot stat GGUF full-attn overlay %s: %s\n", bin_path, strerror(errno));
		close(fd);
		return 0;
	}

	void *data = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
	close(fd);
	if (data == MAP_FAILED) {
		fprintf(stderr, "ERROR: mmap failed for GGUF full-attn overlay %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	memset(wf->gguf_full_attn_q_layers, 0, sizeof(wf->gguf_full_attn_q_layers));
	memset(wf->gguf_full_attn_k_layers, 0, sizeof(wf->gguf_full_attn_k_layers));
	memset(wf->gguf_full_attn_v_layers, 0, sizeof(wf->gguf_full_attn_v_layers));
	memset(wf->gguf_full_attn_o_layers, 0, sizeof(wf->gguf_full_attn_o_layers));

	@autoreleasepool {
		NSArray *entries = validated_gguf_overlay_entries(json_path, "full-attn", 1);
		if (!entries) {
			munmap(data, (size_t)st.st_size);
			return 0;
		}

		for (NSDictionary *entry in entries) {
			int layer = [entry[@"layer"] intValue];
			NSString *role = entry[@"role"];
			uint64_t offset = [entry[@"offset"] unsignedLongLongValue];
			uint64_t size = [entry[@"size"] unsignedLongLongValue];
			NSArray *shape = entry[@"shape"];
			NSString *tensor_type = entry[@"tensor_type"];

			if (layer < 0 || layer >= NUM_LAYERS) {
				fprintf(stderr, "ERROR: GGUF full-attn overlay layer out of range in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (offset > (uint64_t)st.st_size || size > (uint64_t)st.st_size - offset) {
				fprintf(stderr, "ERROR: GGUF full-attn overlay entry out of bounds in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (![tensor_type isEqualToString:@"Q8_0"]) {
				fprintf(stderr, "ERROR: GGUF full-attn overlay expected Q8_0 entries in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (![shape isKindOfClass:[NSArray class]] || [shape count] != 2) {
				fprintf(stderr, "ERROR: GGUF full-attn overlay expected 2D shapes in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}

			size_t in_dim = (size_t)[shape[0] unsignedLongLongValue];
			size_t out_dim = (size_t)[shape[1] unsignedLongLongValue];
			size_t expected_size = out_dim * (in_dim / GGUF_QK8_0) * sizeof(GGUFBlockQ8_0);
			if ((size_t)size != expected_size) {
				fprintf(stderr,
						"ERROR: GGUF full-attn overlay size mismatch for layer %d role %s: got %llu bytes, expected %zu\n",
						layer, [role UTF8String], size, expected_size);
				munmap(data, (size_t)st.st_size);
				return 0;
			}

			size_t required_in = 0, required_out = 0;
			if (!gguf_overlay_expected_geometry("full-attn", layer, role,
					&required_in, &required_out) ||
				in_dim != required_in || out_dim != required_out) {
				fprintf(stderr,
						"ERROR: GGUF full-attn geometry mismatch at layer %d role %s: got [%zu,%zu], expected [%zu,%zu]\n",
						layer, (role ? [role UTF8String] : ""),
						in_dim, out_dim, required_in, required_out);
				munmap(data, (size_t)st.st_size);
				return 0;
			}

			void **slot = NULL;
			if ([role isEqualToString:@"q"]) {
				slot = &wf->gguf_full_attn_q_layers[layer];
			} else if ([role isEqualToString:@"k"]) {
				slot = &wf->gguf_full_attn_k_layers[layer];
			} else if ([role isEqualToString:@"v"]) {
				slot = &wf->gguf_full_attn_v_layers[layer];
			} else if ([role isEqualToString:@"o"]) {
				slot = &wf->gguf_full_attn_o_layers[layer];
			} else {
				fprintf(stderr, "ERROR: GGUF full-attn overlay unknown role '%s' in %s\n",
						[role UTF8String], json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			*slot = (char *)data + offset;
		}
	}

	madvise(data, (size_t)st.st_size, MADV_RANDOM);
	wf->gguf_full_attn_data = data;
	wf->gguf_full_attn_size = (size_t)st.st_size;
	wf->gguf_full_attn_path = strdup(bin_path);
	wf->gguf_full_attn_json_path = strdup(json_path);

	printf("[full-attn] Using GGUF Q8_0 overlay from %s (%.2f GB)\n",
		   bin_path, wf->gguf_full_attn_size / 1e9);
	return 1;
}

static int attach_gguf_qkv_overlay(WeightFile *wf, const char *bin_path, const char *json_path) {
	if (!bin_path || !*bin_path) {
		return 1;
	}
	if (!json_path || !*json_path) {
		fprintf(stderr, "ERROR: GGUF qkv overlay requires both --gguf-qkv-bin and --gguf-qkv-json\n");
		return 0;
	}

	int fd = open(bin_path, O_RDONLY);
	if (fd < 0) {
		fprintf(stderr, "ERROR: Cannot open GGUF qkv overlay %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	struct stat st;
	if (fstat(fd, &st) != 0) {
		fprintf(stderr, "ERROR: Cannot stat GGUF qkv overlay %s: %s\n", bin_path, strerror(errno));
		close(fd);
		return 0;
	}

	void *data = mmap(NULL, (size_t)st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
	close(fd);
	if (data == MAP_FAILED) {
		fprintf(stderr, "ERROR: mmap failed for GGUF qkv overlay %s: %s\n", bin_path, strerror(errno));
		return 0;
	}

	memset(wf->gguf_qkv_layers, 0, sizeof(wf->gguf_qkv_layers));

	@autoreleasepool {
		NSArray *entries = validated_gguf_overlay_entries(json_path, "qkv", 0);
		if (!entries) {
			munmap(data, (size_t)st.st_size);
			return 0;
		}

		for (NSDictionary *entry in entries) {
			int layer = [entry[@"layer"] intValue];
			uint64_t offset = [entry[@"offset"] unsignedLongLongValue];
			uint64_t size = [entry[@"size"] unsignedLongLongValue];
			NSArray *shape = entry[@"shape"];
			NSString *tensor_type = entry[@"tensor_type"];
			if (layer < 0 || layer >= NUM_LAYERS) {
				fprintf(stderr, "ERROR: GGUF qkv overlay layer out of range in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (offset > (uint64_t)st.st_size || size > (uint64_t)st.st_size - offset) {
				fprintf(stderr, "ERROR: GGUF qkv overlay entry out of bounds in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (!tensor_type || strcmp([tensor_type UTF8String], "Q8_0") != 0) {
				fprintf(stderr, "ERROR: GGUF qkv overlay expected Q8_0 entries in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			if (!shape || [shape count] != 2) {
				fprintf(stderr, "ERROR: GGUF qkv overlay expected 2D shapes in %s\n", json_path);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			size_t in_dim = (size_t)[shape[0] unsignedLongLongValue];
			size_t out_dim = (size_t)[shape[1] unsignedLongLongValue];
			size_t expected_size = out_dim * (in_dim / GGUF_QK8_0) * sizeof(GGUFBlockQ8_0);
			if ((size_t)size != expected_size) {
				fprintf(stderr,
						"ERROR: GGUF qkv overlay size mismatch for layer %d: got %llu bytes, expected %zu\n",
						layer, (unsigned long long)size, expected_size);
				munmap(data, (size_t)st.st_size);
				return 0;
			}

			size_t required_in = 0, required_out = 0;
			if (!gguf_overlay_expected_geometry("qkv", layer, nil,
					&required_in, &required_out) ||
				in_dim != required_in || out_dim != required_out) {
				fprintf(stderr,
						"ERROR: GGUF qkv geometry mismatch at layer %d: got [%zu,%zu], expected [%zu,%zu]\n",
						layer,
						in_dim, out_dim, required_in, required_out);
				munmap(data, (size_t)st.st_size);
				return 0;
			}
			wf->gguf_qkv_layers[layer] = (char *)data + offset;
		}
	}

	madvise(data, (size_t)st.st_size, MADV_SEQUENTIAL);
	wf->gguf_qkv_data = data;
	wf->gguf_qkv_size = (size_t)st.st_size;
	wf->gguf_qkv_path = strdup(bin_path);
	wf->gguf_qkv_json_path = strdup(json_path);

	printf("[qkv] Using GGUF Q8_0 qkv overlay from %s (%.2f GB)\n",
		   bin_path, wf->gguf_qkv_size / 1e9);
	return 1;
}

