// GPU dequant matvec: out[out_dim] = W_4bit * x[in_dim]
// W_packed, scales, biases are pointers into mmap'd weight file
// x_f32 is CPU float array, result written back to out_f32
//
// We wrap the ENTIRE mmap'd weight file as a single Metal buffer and use
// byte offsets to point each shader argument at the right tensor.
// This avoids per-tensor buffer creation and the page-alignment constraint.
static void gpu_dequant_matvec(
	MetalCtx *ctx,
	const void *W_packed, const void *scales, const void *biases,
	const float *x_f32, float *out_f32,
	uint32_t out_dim, uint32_t in_dim, uint32_t group_size
) {
	// Copy input to Metal buffer
	memcpy([ctx->buf_input contents], x_f32, in_dim * sizeof(float));

	size_t o_size = (size_t)out_dim * sizeof(float);

	// Compute offsets into the mmap'd weight buffer
	NSUInteger w_off = (NSUInteger)((const char *)W_packed - (const char *)[ctx->wf_buf contents]);
	NSUInteger s_off = (NSUInteger)((const char *)scales   - (const char *)[ctx->wf_buf contents]);
	NSUInteger b_off = (NSUInteger)((const char *)biases   - (const char *)[ctx->wf_buf contents]);

	// Ensure output buffer is large enough
	id<MTLBuffer> o_buf = ctx->buf_output;
	if (o_size > [o_buf length]) {
		o_buf = [ctx->device newBufferWithLength:o_size options:MTLResourceStorageModeShared];
	}

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];

	// v3 shader uses x_shared[4096], so can only handle in_dim <= 4096
	// For larger in_dim (e.g. o_proj with in_dim=8192), use matvec_fast
	int use_v3 = (in_dim <= 4096);
	[enc setComputePipelineState: use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
	[enc setBuffer:ctx->wf_buf  offset:w_off atIndex:0];
	[enc setBuffer:ctx->wf_buf  offset:s_off atIndex:1];
	[enc setBuffer:ctx->wf_buf  offset:b_off atIndex:2];
	[enc setBuffer:ctx->buf_input offset:0   atIndex:3];
	[enc setBuffer:o_buf        offset:0     atIndex:4];
	[enc setBytes:&out_dim      length:4     atIndex:5];
	[enc setBytes:&in_dim       length:4     atIndex:6];
	[enc setBytes:&group_size   length:4     atIndex:7];

	if (use_v3) {
		// v3: tiled threadgroups, 256 threads, 8 rows per TG
		uint32_t num_tgs = (out_dim + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	} else {
		// fast: one threadgroup per output row, 64 threads per TG
		NSUInteger tg_size = 64;
		[enc dispatchThreadgroups:MTLSizeMake(out_dim, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(tg_size, 1, 1)];
	}
	[enc endEncoding];
	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];
	if (out_dim == (uint32_t)VOCAB_SIZE) pipeline_profile_capture_lm_cmd(cmdbuf);

	if (g_gpu_argmax_active && ctx->argmax && o_buf == ctx->buf_output) {
		id<MTLCommandBuffer> reduce = [ctx->queue commandBuffer];
		id<MTLComputeCommandEncoder> renc = [reduce computeCommandEncoder];
		uint32_t dim = out_dim;
		[renc setComputePipelineState:ctx->argmax];
		[renc setBuffer:o_buf offset:0 atIndex:0];
		[renc setBuffer:ctx->argmax_result offset:0 atIndex:1];
		[renc setBytes:&dim length:sizeof(dim) atIndex:2];
		[renc dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
		[renc endEncoding];
		[reduce commit];
		[reduce waitUntilCompleted];
		if (out_dim == (uint32_t)VOCAB_SIZE) pipeline_profile_capture_lm_cmd(reduce);
		g_gpu_argmax_result = *(const uint32_t *)[ctx->argmax_result contents];
		return;
	}
	memcpy(out_f32, [o_buf contents], o_size);
}

typedef struct {
	const char *name;
	id<MTLBuffer> weight_buf;
	NSUInteger weight_off, scale_off, bias_off;
} MatvecBenchTensor;

typedef struct {
	const char *label;
	uint32_t out_dim, in_dim;
	MatvecBenchTensor tensors[MAX_LAYERS * 4];
	int tensor_count;
	int rejection_reported;
} MatvecBenchShape;

static void matvec_bench_encode_block(MetalCtx *ctx, const MatvecBenchShape *shape,
								 int use_v3, int dispatches) {
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
	for (int i = 0; i < dispatches; i++) {
		const MatvecBenchTensor *t = &shape->tensors[i % shape->tensor_count];
		[enc setComputePipelineState:use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
		[enc setBuffer:t->weight_buf offset:t->weight_off atIndex:0];
		[enc setBuffer:t->weight_buf offset:t->scale_off atIndex:1];
		[enc setBuffer:t->weight_buf offset:t->bias_off atIndex:2];
		[enc setBuffer:ctx->buf_input offset:0 atIndex:3];
		[enc setBuffer:ctx->buf_output offset:0 atIndex:4];
		[enc setBytes:&shape->out_dim length:4 atIndex:5];
		[enc setBytes:&shape->in_dim length:4 atIndex:6];
		uint32_t group_size = GROUP_SIZE;
		[enc setBytes:&group_size length:4 atIndex:7];
		if (use_v3) {
			uint32_t num_tgs = (shape->out_dim + 7) / 8;
			[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		} else {
			[enc dispatchThreadgroups:MTLSizeMake(shape->out_dim, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
		}
	}
	[enc endEncoding];
	[cmd commit];
	[cmd waitUntilCompleted];
}

static void matvec_bench_encode_single(MetalCtx *ctx, const MatvecBenchShape *shape, int use_v3) {
	matvec_bench_encode_block(ctx, shape, use_v3, 1);
}

static int matvec_bench_double_cmp(const void *a, const void *b) {
	double da = *(const double *)a, db = *(const double *)b;
	return da < db ? -1 : (da > db ? 1 : 0);
}

static void matvec_bench_compare(const float *a, const float *b, uint32_t n,
							 double *max_abs, double *rms) {
	double max_diff = 0.0, sum_sq = 0.0;
	for (uint32_t i = 0; i < n; i++) {
		double d = (double)a[i] - b[i];
		if (fabs(d) > max_diff) max_diff = fabs(d);
		sum_sq += d * d;
	}
	*max_abs = max_diff;
	*rms = sqrt(sum_sq / (double)n);
}


#ifdef TARGET_VERIFY_MULTIROW_AFFINE
// Phase-1 target-verifier falsifier: compare two exact production V3 MLX4
// matvecs against one M2 kernel that reuses each packed Q4 weight/dequant for
// two independent FP32 activation rows. This code is absent from normal builds.
static id<MTLComputePipelineState> target_verify_affine_m2_pipeline(MetalCtx *ctx) {
	if (!ctx || !ctx->device) return nil;

	NSString *executable_dir = infer_executable_directory();
	NSMutableArray<NSString *> *paths = [NSMutableArray array];
	if (executable_dir.length > 0) {
		[paths addObject:[executable_dir
			stringByAppendingPathComponent:@"prefill_probe/target_verify_affine_m2.metal"]];

		// Benchmark binaries normally live under
		// Testing/Temporary Testing Files/Apps. Climb back to the repo root.
		NSString *repo_root = executable_dir;
		for (int i = 0; i < 3 && repo_root.length > 1; i++)
			repo_root = [repo_root stringByDeletingLastPathComponent];
		[paths addObject:[repo_root
			stringByAppendingPathComponent:@"metal_infer/prefill_probe/target_verify_affine_m2.metal"]];
	}
	[paths addObject:@"prefill_probe/target_verify_affine_m2.metal"];
	[paths addObject:@"metal_infer/prefill_probe/target_verify_affine_m2.metal"];

	NSString *source = nil;
	NSString *source_path = nil;
	for (NSString *candidate in paths) {
		source = [NSString stringWithContentsOfFile:candidate
			encoding:NSUTF8StringEncoding error:NULL];
		if (source) {
			source_path = candidate;
			break;
		}
	}
	if (!source) {
		fprintf(stderr,
			"ERROR: target verifier affine benchmark cannot find "
			"prefill_probe/target_verify_affine_m2.metal\n");
		return nil;
	}

	NSError *error = nil;
	id<MTLLibrary> library = [ctx->device newLibraryWithSource:source
		options:nil error:&error];
	if (!library) {
		fprintf(stderr, "ERROR: target verifier M2 shader compile failed (%s): %s\n",
			source_path.UTF8String,
			error.localizedDescription.UTF8String ?: "unknown error");
		return nil;
	}
	id<MTLFunction> fn = [library newFunctionWithName:@"dense_affine_q4_m2"];
	if (!fn) {
		fprintf(stderr,
			"ERROR: target verifier M2 shader source has no dense_affine_q4_m2\n");
		return nil;
	}
	id<MTLComputePipelineState> pipeline =
		[ctx->device newComputePipelineStateWithFunction:fn error:&error];
	if (!pipeline) {
		fprintf(stderr, "ERROR: target verifier M2 pipeline creation failed: %s\n",
			error.localizedDescription.UTF8String ?: "unknown error");
		return nil;
	}
	printf("[target-verify-affine] shader source=%s\n", source_path.UTF8String);
	return pipeline;
}

static void target_verify_affine_encode_m1_pair(
	MetalCtx *ctx,
	id<MTLComputeCommandEncoder> enc,
	const MatvecBenchShape *shape,
	const MatvecBenchTensor *tensor,
	id<MTLBuffer> input,
	id<MTLBuffer> output
) {
	uint32_t group_size = GROUP_SIZE;
	uint32_t num_tgs = (shape->out_dim + 7u) / 8u;
	[enc setComputePipelineState:ctx->matvec_v3];
	[enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
	[enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
	[enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
	[enc setBytes:&shape->out_dim length:4 atIndex:5];
	[enc setBytes:&shape->in_dim length:4 atIndex:6];
	[enc setBytes:&group_size length:4 atIndex:7];

	for (uint32_t row = 0; row < 2; row++) {
		[enc setBuffer:input
			offset:(NSUInteger)row * shape->in_dim * sizeof(float) atIndex:3];
		[enc setBuffer:output
			offset:(NSUInteger)row * shape->out_dim * sizeof(float) atIndex:4];
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	}
}

static void target_verify_affine_encode_m2(
	id<MTLComputePipelineState> pipeline,
	id<MTLComputeCommandEncoder> enc,
	const MatvecBenchShape *shape,
	const MatvecBenchTensor *tensor,
	id<MTLBuffer> input,
	id<MTLBuffer> output
) {
	uint32_t group_size = GROUP_SIZE;
	uint32_t input_stride = shape->in_dim;
	uint32_t output_stride = shape->out_dim;
	uint32_t num_tgs = (shape->out_dim + 7u) / 8u;

	[enc setComputePipelineState:pipeline];
	[enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
	[enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
	[enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
	[enc setBuffer:input offset:0 atIndex:3];
	[enc setBuffer:output offset:0 atIndex:4];
	[enc setBytes:&shape->out_dim length:4 atIndex:5];
	[enc setBytes:&shape->in_dim length:4 atIndex:6];
	[enc setBytes:&group_size length:4 atIndex:7];
	[enc setBytes:&input_stride length:4 atIndex:8];
	[enc setBytes:&output_stride length:4 atIndex:9];
	[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
		threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
}

static int target_verify_affine_run_block(
	MetalCtx *ctx,
	id<MTLComputePipelineState> m2_pipeline,
	const MatvecBenchShape *shape,
	id<MTLBuffer> input,
	id<MTLBuffer> output,
	int use_m2,
	int pairs,
	double *wall_ms_per_pair,
	double *gpu_ms_per_pair
) {
	if (!ctx || !shape || shape->tensor_count <= 0 || !input || !output ||
		pairs <= 0 || (use_m2 && !m2_pipeline)) return 0;

	double wall_start = now_ms();
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
	if (!cmd || !enc) return 0;

	for (int i = 0; i < pairs; i++) {
		const MatvecBenchTensor *tensor =
			&shape->tensors[i % shape->tensor_count];
		if (use_m2)
			target_verify_affine_encode_m2(
				m2_pipeline, enc, shape, tensor, input, output);
		else
			target_verify_affine_encode_m1_pair(
				ctx, enc, shape, tensor, input, output);
	}
	[enc endEncoding];
	[cmd commit];
	[cmd waitUntilCompleted];
	double wall_ms = now_ms() - wall_start;

	if (cmd.status != MTLCommandBufferStatusCompleted) {
		NSString *detail = cmd.error.localizedDescription;
		fprintf(stderr,
			"ERROR: target verifier affine %s command failed: status=%ld%s%s\n",
			use_m2 ? "M2" : "2xM1", (long)cmd.status,
			detail.length ? " error=" : "",
			detail.length ? detail.UTF8String : "");
		return 0;
	}

	if (wall_ms_per_pair) *wall_ms_per_pair = wall_ms / (double)pairs;
	if (gpu_ms_per_pair) {
		double start = cmd.GPUStartTime, end = cmd.GPUEndTime;
		*gpu_ms_per_pair =
			(start > 0.0 && end >= start) ? ((end - start) * 1000.0 / pairs) : 0.0;
	}
	return 1;
}

static uint64_t target_verify_affine_exact_count(
	const float *a, const float *b, size_t n
) {
	uint64_t exact = 0;
	for (size_t i = 0; i < n; i++) {
		uint32_t ua = 0, ub = 0;
		memcpy(&ua, &a[i], sizeof(ua));
		memcpy(&ub, &b[i], sizeof(ub));
		if (ua == ub) exact++;
	}
	return exact;
}

static int run_target_verify_affine_m2_benchmark(
	MetalCtx *ctx,
	MatvecBenchShape *shapes,
	int shape_count,
	int samples
) {
	if (!ctx || !ctx->matvec_v3 || samples <= 0) return 1;

	id<MTLComputePipelineState> m2_pipeline =
		target_verify_affine_m2_pipeline(ctx);
	if (!m2_pipeline) return 1;

	const int block_pairs = 32;
	const int warmup_blocks = 6;
	id<MTLBuffer> input = [ctx->device
		newBufferWithLength:2u * 2048u * sizeof(float)
		options:MTLResourceStorageModeShared];
	id<MTLBuffer> ref_output = [ctx->device
		newBufferWithLength:2u * 8192u * sizeof(float)
		options:MTLResourceStorageModeShared];
	id<MTLBuffer> m2_output = [ctx->device
		newBufferWithLength:2u * 8192u * sizeof(float)
		options:MTLResourceStorageModeShared];
	if (!input || !ref_output || !m2_output) {
		fprintf(stderr, "ERROR: target verifier affine benchmark buffer allocation failed\n");
		return 1;
	}

	printf("=== Exact M2 Target-Verifier Affine Benchmark ===\n");
	printf("Device: %s\n", ctx->device.name.UTF8String);
	printf("Reference: 2 x production dequant_matvec_4bit_v3, GPU-ordered in one command buffer\n");
	printf("Candidate: dense_affine_q4_m2, one packed-weight traversal for two FP32 rows\n");
	printf("Format gate: resident MLX4 Q4, group_size=64, in_dim<=2048 only\n");
	printf("Measured block: %d verification pairs; samples=%d; warmup blocks=%d\n\n",
		block_pairs, samples, warmup_blocks);

	int tested_shapes = 0;
	for (int si = 0; si < shape_count; si++) {
		MatvecBenchShape *shape = &shapes[si];
		if (shape->tensor_count == 0) {
			printf("%-11s SKIPPED — no real resident MLX4 tensor resolved\n",
				shape->label);
			continue;
		}
		if (shape->in_dim > 2048u || GROUP_SIZE != 64) {
			printf("%-11s SKIPPED — M2 phase-1 kernel supports in_dim<=2048/group64\n",
				shape->label);
			continue;
		}
		if (shape->out_dim > 8192u) {
			printf("%-11s SKIPPED — benchmark scratch output capacity\n",
				shape->label);
			continue;
		}

		float *rows = (float *)input.contents;
		for (uint32_t i = 0; i < shape->in_dim; i++) {
			rows[i] = sinf((float)i * 0.017f) * 0.25f;
			rows[shape->in_dim + i] =
				cosf((float)i * 0.013f + 0.37f) * 0.20f +
				sinf((float)i * 0.003f) * 0.05f;
		}

		double ignored_wall = 0.0, ignored_gpu = 0.0;
		if (!target_verify_affine_run_block(
				ctx, m2_pipeline, shape, input, ref_output, 0, 1,
				&ignored_wall, &ignored_gpu) ||
			!target_verify_affine_run_block(
				ctx, m2_pipeline, shape, input, m2_output, 1, 1,
				&ignored_wall, &ignored_gpu)) {
			return 1;
		}

		const size_t values = 2u * (size_t)shape->out_dim;
		double max_abs = 0.0, rms = 0.0;
		matvec_bench_compare(
			(const float *)ref_output.contents,
			(const float *)m2_output.contents,
			(uint32_t)values, &max_abs, &rms);
		uint64_t exact = target_verify_affine_exact_count(
			(const float *)ref_output.contents,
			(const float *)m2_output.contents, values);

		for (int w = 0; w < warmup_blocks; w++) {
			if (!target_verify_affine_run_block(
					ctx, m2_pipeline, shape, input, ref_output, 0, block_pairs,
					NULL, NULL) ||
				!target_verify_affine_run_block(
					ctx, m2_pipeline, shape, input, m2_output, 1, block_pairs,
					NULL, NULL)) {
				return 1;
			}
		}

		double *m1_wall = calloc((size_t)samples, sizeof(double));
		double *m2_wall = calloc((size_t)samples, sizeof(double));
		double *m1_gpu = calloc((size_t)samples, sizeof(double));
		double *m2_gpu = calloc((size_t)samples, sizeof(double));
		double *wall_ratio = calloc((size_t)samples, sizeof(double));
		double *gpu_ratio = calloc((size_t)samples, sizeof(double));
		if (!m1_wall || !m2_wall || !m1_gpu || !m2_gpu ||
			!wall_ratio || !gpu_ratio) {
			free(m1_wall); free(m2_wall); free(m1_gpu); free(m2_gpu);
			free(wall_ratio); free(gpu_ratio);
			return 1;
		}

		int gpu_valid = 1;
		for (int sample = 0; sample < samples; sample++) {
			int m2_first = sample & 1;
			for (int order = 0; order < 2; order++) {
				int use_m2 = m2_first ? (order == 0) : (order == 1);
				double *wall = use_m2 ? &m2_wall[sample] : &m1_wall[sample];
				double *gpu = use_m2 ? &m2_gpu[sample] : &m1_gpu[sample];
				id<MTLBuffer> output = use_m2 ? m2_output : ref_output;
				if (!target_verify_affine_run_block(
						ctx, m2_pipeline, shape, input, output, use_m2,
						block_pairs, wall, gpu)) {
					free(m1_wall); free(m2_wall); free(m1_gpu); free(m2_gpu);
					free(wall_ratio); free(gpu_ratio);
					return 1;
				}
			}
			wall_ratio[sample] =
				m1_wall[sample] > 0.0 ? m2_wall[sample] / m1_wall[sample] : 0.0;
			if (m1_gpu[sample] > 0.0 && m2_gpu[sample] > 0.0) {
				gpu_ratio[sample] = m2_gpu[sample] / m1_gpu[sample];
			} else {
				gpu_valid = 0;
				gpu_ratio[sample] = 0.0;
			}
		}

		qsort(m1_wall, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m2_wall, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(wall_ratio, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m1_gpu, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m2_gpu, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(gpu_ratio, (size_t)samples, sizeof(double), matvec_bench_double_cmp);

		const int mid = samples / 2;
		printf("%-11s real tensors=%d\n", shape->label, shape->tensor_count);
		printf("  correctness: max_abs=%.9g rms=%.9g bitwise_equal=%llu/%llu\n",
			max_abs, rms,
			(unsigned long long)exact,
			(unsigned long long)values);
		if (gpu_valid) {
			printf("  GPU median: 2xM1=%.6f ms M2=%.6f ms ratio=%.4f\n",
				m1_gpu[mid], m2_gpu[mid], gpu_ratio[mid]);
		} else {
			printf("  GPU median: unavailable (invalid Metal timestamps in sample set)\n");
		}
		printf("  wall median: 2xM1=%.6f ms M2=%.6f ms ratio=%.4f\n",
			m1_wall[mid], m2_wall[mid], wall_ratio[mid]);

		free(m1_wall); free(m2_wall); free(m1_gpu); free(m2_gpu);
		free(wall_ratio); free(gpu_ratio);
		tested_shapes++;
	}

	if (tested_shapes == 0) {
		fprintf(stderr,
			"ERROR: target verifier affine benchmark found no compatible real MLX4 tensors\n");
		return 1;
	}
	return 0;
}
#endif

#ifdef TARGET_VERIFY_MULTIROW_AFFINE_M4
// Phase-1 target-verifier falsifier: compare four exact production V3 MLX4
// matvecs against one M4 kernel that reuses each packed Q4 weight/dequant for
// four independent FP32 activation rows. This code is absent from normal builds.
static id<MTLComputePipelineState> target_verify_affine_m4_pipeline(MetalCtx *ctx) {
	if (!ctx || !ctx->device) return nil;

	NSString *executable_dir = infer_executable_directory();
	NSMutableArray<NSString *> *paths = [NSMutableArray array];
	if (executable_dir.length > 0) {
		[paths addObject:[executable_dir
			stringByAppendingPathComponent:@"prefill_probe/target_verify_affine_m4.metal"]];

		// Benchmark binaries normally live under
		// Testing/Temporary Testing Files/Apps. Climb back to the repo root.
		NSString *repo_root = executable_dir;
		for (int i = 0; i < 3 && repo_root.length > 1; i++)
			repo_root = [repo_root stringByDeletingLastPathComponent];
		[paths addObject:[repo_root
			stringByAppendingPathComponent:@"metal_infer/prefill_probe/target_verify_affine_m4.metal"]];
	}
	[paths addObject:@"prefill_probe/target_verify_affine_m4.metal"];
	[paths addObject:@"metal_infer/prefill_probe/target_verify_affine_m4.metal"];

	NSString *source = nil;
	NSString *source_path = nil;
	for (NSString *candidate in paths) {
		source = [NSString stringWithContentsOfFile:candidate
			encoding:NSUTF8StringEncoding error:NULL];
		if (source) {
			source_path = candidate;
			break;
		}
	}
	if (!source) {
		fprintf(stderr,
			"ERROR: target verifier affine benchmark cannot find "
			"prefill_probe/target_verify_affine_m4.metal\n");
		return nil;
	}

	NSError *error = nil;
	id<MTLLibrary> library = [ctx->device newLibraryWithSource:source
		options:nil error:&error];
	if (!library) {
		fprintf(stderr, "ERROR: target verifier M4 shader compile failed (%s): %s\n",
			source_path.UTF8String,
			error.localizedDescription.UTF8String ?: "unknown error");
		return nil;
	}
	id<MTLFunction> fn = [library newFunctionWithName:@"dense_affine_q4_m4"];
	if (!fn) {
		fprintf(stderr,
			"ERROR: target verifier M4 shader source has no dense_affine_q4_m4\n");
		return nil;
	}
	id<MTLComputePipelineState> pipeline =
		[ctx->device newComputePipelineStateWithFunction:fn error:&error];
	if (!pipeline) {
		fprintf(stderr, "ERROR: target verifier M4 pipeline creation failed: %s\n",
			error.localizedDescription.UTF8String ?: "unknown error");
		return nil;
	}
	printf("[target-verify-affine] shader source=%s\n", source_path.UTF8String);
	return pipeline;
}

static void target_verify_affine_encode_m1_quad(
	MetalCtx *ctx,
	id<MTLComputeCommandEncoder> enc,
	const MatvecBenchShape *shape,
	const MatvecBenchTensor *tensor,
	id<MTLBuffer> input,
	id<MTLBuffer> output
) {
	uint32_t group_size = GROUP_SIZE;
	uint32_t num_tgs = (shape->out_dim + 7u) / 8u;
	[enc setComputePipelineState:ctx->matvec_v3];
	[enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
	[enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
	[enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
	[enc setBytes:&shape->out_dim length:4 atIndex:5];
	[enc setBytes:&shape->in_dim length:4 atIndex:6];
	[enc setBytes:&group_size length:4 atIndex:7];

	for (uint32_t row = 0; row < 4; row++) {
		[enc setBuffer:input
			offset:(NSUInteger)row * shape->in_dim * sizeof(float) atIndex:3];
		[enc setBuffer:output
			offset:(NSUInteger)row * shape->out_dim * sizeof(float) atIndex:4];
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	}
}

static void target_verify_affine_encode_m4(
	id<MTLComputePipelineState> pipeline,
	id<MTLComputeCommandEncoder> enc,
	const MatvecBenchShape *shape,
	const MatvecBenchTensor *tensor,
	id<MTLBuffer> input,
	id<MTLBuffer> output
) {
	uint32_t group_size = GROUP_SIZE;
	uint32_t input_stride = shape->in_dim;
	uint32_t output_stride = shape->out_dim;
	uint32_t num_tgs = (shape->out_dim + 7u) / 8u;

	[enc setComputePipelineState:pipeline];
	[enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
	[enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
	[enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
	[enc setBuffer:input offset:0 atIndex:3];
	[enc setBuffer:output offset:0 atIndex:4];
	[enc setBytes:&shape->out_dim length:4 atIndex:5];
	[enc setBytes:&shape->in_dim length:4 atIndex:6];
	[enc setBytes:&group_size length:4 atIndex:7];
	[enc setBytes:&input_stride length:4 atIndex:8];
	[enc setBytes:&output_stride length:4 atIndex:9];
	[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
		threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
}

static int target_verify_affine_run_block_m4(
	MetalCtx *ctx,
	id<MTLComputePipelineState> m4_pipeline,
	const MatvecBenchShape *shape,
	id<MTLBuffer> input,
	id<MTLBuffer> output,
	int use_m4,
	int pairs,
	double *wall_ms_per_pair,
	double *gpu_ms_per_pair
) {
	if (!ctx || !shape || shape->tensor_count <= 0 || !input || !output ||
		pairs <= 0 || (use_m4 && !m4_pipeline)) return 0;

	double wall_start = now_ms();
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
	if (!cmd || !enc) return 0;

	for (int i = 0; i < pairs; i++) {
		const MatvecBenchTensor *tensor =
			&shape->tensors[i % shape->tensor_count];
		if (use_m4)
			target_verify_affine_encode_m4(
				m4_pipeline, enc, shape, tensor, input, output);
		else
			target_verify_affine_encode_m1_quad(
				ctx, enc, shape, tensor, input, output);
	}
	[enc endEncoding];
	[cmd commit];
	[cmd waitUntilCompleted];
	double wall_ms = now_ms() - wall_start;

	if (cmd.status != MTLCommandBufferStatusCompleted) {
		NSString *detail = cmd.error.localizedDescription;
		fprintf(stderr,
			"ERROR: target verifier affine %s command failed: status=%ld%s%s\n",
			use_m4 ? "M4" : "4xM1", (long)cmd.status,
			detail.length ? " error=" : "",
			detail.length ? detail.UTF8String : "");
		return 0;
	}

	if (wall_ms_per_pair) *wall_ms_per_pair = wall_ms / (double)pairs;
	if (gpu_ms_per_pair) {
		double start = cmd.GPUStartTime, end = cmd.GPUEndTime;
		*gpu_ms_per_pair =
			(start > 0.0 && end >= start) ? ((end - start) * 1000.0 / pairs) : 0.0;
	}
	return 1;
}

static uint64_t target_verify_affine_exact_count_m4(
	const float *a, const float *b, size_t n
) {
	uint64_t exact = 0;
	for (size_t i = 0; i < n; i++) {
		uint32_t ua = 0, ub = 0;
		memcpy(&ua, &a[i], sizeof(ua));
		memcpy(&ub, &b[i], sizeof(ub));
		if (ua == ub) exact++;
	}
	return exact;
}

static int run_target_verify_affine_m4_benchmark(
	MetalCtx *ctx,
	MatvecBenchShape *shapes,
	int shape_count,
	int samples
) {
	if (!ctx || !ctx->matvec_v3 || samples <= 0) return 1;

	id<MTLComputePipelineState> m4_pipeline =
		target_verify_affine_m4_pipeline(ctx);
	if (!m4_pipeline) return 1;

	const int block_pairs = 32;
	const int warmup_blocks = 6;
	id<MTLBuffer> input = [ctx->device
		newBufferWithLength:4u * 2048u * sizeof(float)
		options:MTLResourceStorageModeShared];
	id<MTLBuffer> ref_output = [ctx->device
		newBufferWithLength:4u * 8192u * sizeof(float)
		options:MTLResourceStorageModeShared];
	id<MTLBuffer> m4_output = [ctx->device
		newBufferWithLength:4u * 8192u * sizeof(float)
		options:MTLResourceStorageModeShared];
	if (!input || !ref_output || !m4_output) {
		fprintf(stderr, "ERROR: target verifier affine benchmark buffer allocation failed\n");
		return 1;
	}

	printf("=== Exact M4 Target-Verifier Affine Benchmark ===\n");
	printf("Device: %s\n", ctx->device.name.UTF8String);
	printf("Reference: 4 x production dequant_matvec_4bit_v3, GPU-ordered in one command buffer\n");
	printf("Candidate: dense_affine_q4_m4, one packed-weight traversal for four FP32 rows\n");
	printf("Format gate: resident MLX4 Q4, group_size=64, in_dim<=2048 only\n");
	printf("Measured block: %d verification quads; samples=%d; warmup blocks=%d\n\n",
		block_pairs, samples, warmup_blocks);

	int tested_shapes = 0;
	for (int si = 0; si < shape_count; si++) {
		MatvecBenchShape *shape = &shapes[si];
		if (shape->tensor_count == 0) {
			printf("%-11s SKIPPED — no real resident MLX4 tensor resolved\n",
				shape->label);
			continue;
		}
		if (shape->in_dim > 2048u || GROUP_SIZE != 64) {
			printf("%-11s SKIPPED — M4 phase-1 kernel supports in_dim<=2048/group64\n",
				shape->label);
			continue;
		}
		if (shape->out_dim > 8192u) {
			printf("%-11s SKIPPED — benchmark scratch output capacity\n",
				shape->label);
			continue;
		}

		float *rows = (float *)input.contents;
		for (uint32_t i = 0; i < shape->in_dim; i++) {
			rows[i] = sinf((float)i * 0.017f) * 0.25f;
			rows[shape->in_dim + i] =
				cosf((float)i * 0.013f + 0.37f) * 0.20f +
				sinf((float)i * 0.003f) * 0.05f;
			rows[2u * shape->in_dim + i] =
				sinf((float)i * 0.011f + 0.91f) * 0.18f +
				cosf((float)i * 0.005f) * 0.04f;
			rows[3u * shape->in_dim + i] =
				cosf((float)i * 0.019f + 0.23f) * 0.16f -
				sinf((float)i * 0.007f + 0.41f) * 0.06f;
		}

		double ignored_wall = 0.0, ignored_gpu = 0.0;
		if (!target_verify_affine_run_block_m4(
				ctx, m4_pipeline, shape, input, ref_output, 0, 1,
				&ignored_wall, &ignored_gpu) ||
			!target_verify_affine_run_block_m4(
				ctx, m4_pipeline, shape, input, m4_output, 1, 1,
				&ignored_wall, &ignored_gpu)) {
			return 1;
		}

		const size_t values = 4u * (size_t)shape->out_dim;
		double max_abs = 0.0, rms = 0.0;
		matvec_bench_compare(
			(const float *)ref_output.contents,
			(const float *)m4_output.contents,
			(uint32_t)values, &max_abs, &rms);
		uint64_t exact = target_verify_affine_exact_count_m4(
			(const float *)ref_output.contents,
			(const float *)m4_output.contents, values);

		for (int w = 0; w < warmup_blocks; w++) {
			if (!target_verify_affine_run_block_m4(
					ctx, m4_pipeline, shape, input, ref_output, 0, block_pairs,
					NULL, NULL) ||
				!target_verify_affine_run_block_m4(
					ctx, m4_pipeline, shape, input, m4_output, 1, block_pairs,
					NULL, NULL)) {
				return 1;
			}
		}

		double *m1_wall = calloc((size_t)samples, sizeof(double));
		double *m4_wall = calloc((size_t)samples, sizeof(double));
		double *m1_gpu = calloc((size_t)samples, sizeof(double));
		double *m4_gpu = calloc((size_t)samples, sizeof(double));
		double *wall_ratio = calloc((size_t)samples, sizeof(double));
		double *gpu_ratio = calloc((size_t)samples, sizeof(double));
		if (!m1_wall || !m4_wall || !m1_gpu || !m4_gpu ||
			!wall_ratio || !gpu_ratio) {
			free(m1_wall); free(m4_wall); free(m1_gpu); free(m4_gpu);
			free(wall_ratio); free(gpu_ratio);
			return 1;
		}

		int gpu_valid = 1;
		for (int sample = 0; sample < samples; sample++) {
			int m4_first = sample & 1;
			for (int order = 0; order < 2; order++) {
				int use_m4 = m4_first ? (order == 0) : (order == 1);
				double *wall = use_m4 ? &m4_wall[sample] : &m1_wall[sample];
				double *gpu = use_m4 ? &m4_gpu[sample] : &m1_gpu[sample];
				id<MTLBuffer> output = use_m4 ? m4_output : ref_output;
				if (!target_verify_affine_run_block_m4(
						ctx, m4_pipeline, shape, input, output, use_m4,
						block_pairs, wall, gpu)) {
					free(m1_wall); free(m4_wall); free(m1_gpu); free(m4_gpu);
					free(wall_ratio); free(gpu_ratio);
					return 1;
				}
			}
			wall_ratio[sample] =
				m1_wall[sample] > 0.0 ? m4_wall[sample] / m1_wall[sample] : 0.0;
			if (m1_gpu[sample] > 0.0 && m4_gpu[sample] > 0.0) {
				gpu_ratio[sample] = m4_gpu[sample] / m1_gpu[sample];
			} else {
				gpu_valid = 0;
				gpu_ratio[sample] = 0.0;
			}
		}

		qsort(m1_wall, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m4_wall, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(wall_ratio, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m1_gpu, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(m4_gpu, (size_t)samples, sizeof(double), matvec_bench_double_cmp);
		qsort(gpu_ratio, (size_t)samples, sizeof(double), matvec_bench_double_cmp);

		const int mid = samples / 2;
		printf("%-11s real tensors=%d\n", shape->label, shape->tensor_count);
		printf("  correctness: max_abs=%.9g rms=%.9g bitwise_equal=%llu/%llu\n",
			max_abs, rms,
			(unsigned long long)exact,
			(unsigned long long)values);
		if (gpu_valid) {
			printf("  GPU median: 4xM1=%.6f ms M4=%.6f ms ratio=%.4f\n",
				m1_gpu[mid], m4_gpu[mid], gpu_ratio[mid]);
		} else {
			printf("  GPU median: unavailable (invalid Metal timestamps in sample set)\n");
		}
		printf("  wall median: 4xM1=%.6f ms M4=%.6f ms ratio=%.4f\n",
			m1_wall[mid], m4_wall[mid], wall_ratio[mid]);

		free(m1_wall); free(m4_wall); free(m1_gpu); free(m4_gpu);
		free(wall_ratio); free(gpu_ratio);
		tested_shapes++;
	}

	if (tested_shapes == 0) {
		fprintf(stderr,
			"ERROR: target verifier affine benchmark found no compatible real MLX4 tensors\n");
		return 1;
	}
	return 0;
}
#endif

#ifdef TARGET_VERIFY_MULTIROW_AFFINE_MMA
typedef enum {
    TARGET_VERIFY_M8_REF_M1 = 0,
    TARGET_VERIFY_M8_M2 = 1,
    TARGET_VERIFY_M8_M4 = 2,
    TARGET_VERIFY_M8_MMA = 3
} TargetVerifyM8Mode;

static id<MTLComputePipelineState> target_verify_load_benchmark_pipeline(
    MetalCtx *ctx, NSString *filename, NSString *function_name
) {
    if (!ctx || !ctx->device || !filename || !function_name) return nil;
    NSString *executable_dir = infer_executable_directory();
    NSMutableArray<NSString *> *paths = [NSMutableArray array];
    if (executable_dir.length > 0) {
        [paths addObject:[executable_dir
            stringByAppendingPathComponent:[@"prefill_probe" stringByAppendingPathComponent:filename]]];
        NSString *repo_root = executable_dir;
        for (int i = 0; i < 3 && repo_root.length > 1; i++)
            repo_root = [repo_root stringByDeletingLastPathComponent];
        [paths addObject:[repo_root
            stringByAppendingPathComponent:[@"metal_infer/prefill_probe"
                stringByAppendingPathComponent:filename]]];
    }
    [paths addObject:[@"prefill_probe" stringByAppendingPathComponent:filename]];
    [paths addObject:[@"metal_infer/prefill_probe" stringByAppendingPathComponent:filename]];

    NSString *source = nil;
    NSString *source_path = nil;
    for (NSString *candidate in paths) {
        source = [NSString stringWithContentsOfFile:candidate
            encoding:NSUTF8StringEncoding error:NULL];
        if (source) { source_path = candidate; break; }
    }
    if (!source) {
        fprintf(stderr, "ERROR: verifier MMA benchmark cannot find %s\n",
            filename.UTF8String);
        return nil;
    }

    NSError *error = nil;
    id<MTLLibrary> library = [ctx->device newLibraryWithSource:source
        options:nil error:&error];
    if (!library) {
        fprintf(stderr, "ERROR: verifier MMA shader compile failed (%s): %s\n",
            source_path.UTF8String,
            error.localizedDescription.UTF8String ?: "unknown error");
        return nil;
    }
    id<MTLFunction> fn = [library newFunctionWithName:function_name];
    if (!fn) {
        fprintf(stderr, "ERROR: verifier MMA source %s has no function %s\n",
            source_path.UTF8String, function_name.UTF8String);
        return nil;
    }
    id<MTLComputePipelineState> pipeline =
        [ctx->device newComputePipelineStateWithFunction:fn error:&error];
    if (!pipeline) {
        fprintf(stderr, "ERROR: verifier MMA pipeline creation failed (%s): %s\n",
            function_name.UTF8String,
            error.localizedDescription.UTF8String ?: "unknown error");
        return nil;
    }
    printf("[target-verify-mma] %s source=%s\n",
        function_name.UTF8String, source_path.UTF8String);
    return pipeline;
}

static void target_verify_m8_encode_m1(
    MetalCtx *ctx, id<MTLComputeCommandEncoder> enc,
    const MatvecBenchShape *shape, const MatvecBenchTensor *tensor,
    id<MTLBuffer> input, id<MTLBuffer> output
) {
    uint32_t group_size = GROUP_SIZE;
    uint32_t num_tgs = (shape->out_dim + 7u) / 8u;
    [enc setComputePipelineState:ctx->matvec_v3];
    [enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
    [enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
    [enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
    [enc setBytes:&shape->out_dim length:4 atIndex:5];
    [enc setBytes:&shape->in_dim length:4 atIndex:6];
    [enc setBytes:&group_size length:4 atIndex:7];
    for (uint32_t row = 0; row < 8u; row++) {
        [enc setBuffer:input
            offset:(NSUInteger)row * shape->in_dim * sizeof(float) atIndex:3];
        [enc setBuffer:output
            offset:(NSUInteger)row * shape->out_dim * sizeof(float) atIndex:4];
        [enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    }
}

static void target_verify_m8_encode_smallm(
    id<MTLComputePipelineState> pipeline,
    id<MTLComputeCommandEncoder> enc,
    const MatvecBenchShape *shape, const MatvecBenchTensor *tensor,
    id<MTLBuffer> input, id<MTLBuffer> output,
    uint32_t rows_per_dispatch
) {
    uint32_t group_size = GROUP_SIZE;
    uint32_t input_stride = shape->in_dim;
    uint32_t output_stride = shape->out_dim;
    uint32_t num_tgs = (shape->out_dim + 7u) / 8u;
    uint32_t dispatches = 8u / rows_per_dispatch;

    [enc setComputePipelineState:pipeline];
    [enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
    [enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
    [enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
    [enc setBytes:&shape->out_dim length:4 atIndex:5];
    [enc setBytes:&shape->in_dim length:4 atIndex:6];
    [enc setBytes:&group_size length:4 atIndex:7];
    [enc setBytes:&input_stride length:4 atIndex:8];
    [enc setBytes:&output_stride length:4 atIndex:9];

    for (uint32_t d = 0; d < dispatches; d++) {
        [enc setBuffer:input
            offset:(NSUInteger)d * rows_per_dispatch * shape->in_dim * sizeof(float)
            atIndex:3];
        [enc setBuffer:output
            offset:(NSUInteger)d * rows_per_dispatch * shape->out_dim * sizeof(float)
            atIndex:4];
        [enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    }
}

static void target_verify_m8_encode_mma(
    id<MTLComputePipelineState> pipeline,
    id<MTLComputeCommandEncoder> enc,
    const MatvecBenchShape *shape, const MatvecBenchTensor *tensor,
    id<MTLBuffer> input, id<MTLBuffer> output
) {
    uint32_t group_size = GROUP_SIZE;
    uint32_t input_stride = shape->in_dim;
    uint32_t output_stride = shape->out_dim;
    uint32_t num_tgs = (shape->out_dim + 31u) / 32u;

    [enc setComputePipelineState:pipeline];
    [enc setBuffer:tensor->weight_buf offset:tensor->weight_off atIndex:0];
    [enc setBuffer:tensor->weight_buf offset:tensor->scale_off atIndex:1];
    [enc setBuffer:tensor->weight_buf offset:tensor->bias_off atIndex:2];
    [enc setBuffer:input offset:0 atIndex:3];
    [enc setBuffer:output offset:0 atIndex:4];
    [enc setBytes:&shape->out_dim length:4 atIndex:5];
    [enc setBytes:&shape->in_dim length:4 atIndex:6];
    [enc setBytes:&group_size length:4 atIndex:7];
    [enc setBytes:&input_stride length:4 atIndex:8];
    [enc setBytes:&output_stride length:4 atIndex:9];
    [enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
}

static int target_verify_m8_run_block(
    MetalCtx *ctx,
    id<MTLComputePipelineState> m2_pipeline,
    id<MTLComputePipelineState> m4_pipeline,
    id<MTLComputePipelineState> mma_pipeline,
    const MatvecBenchShape *shape,
    id<MTLBuffer> input,
    id<MTLBuffer> output,
    TargetVerifyM8Mode mode,
    int windows,
    double *wall_ms_per_window,
    double *gpu_ms_per_window
) {
    if (!ctx || !shape || shape->tensor_count <= 0 || !input || !output ||
        windows <= 0 || !m2_pipeline || !m4_pipeline || !mma_pipeline) return 0;

    double wall_start = now_ms();
    id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
    id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
    if (!cmd || !enc) return 0;

    for (int i = 0; i < windows; i++) {
        const MatvecBenchTensor *tensor =
            &shape->tensors[i % shape->tensor_count];
        switch (mode) {
            case TARGET_VERIFY_M8_REF_M1:
                target_verify_m8_encode_m1(ctx, enc, shape, tensor, input, output);
                break;
            case TARGET_VERIFY_M8_M2:
                target_verify_m8_encode_smallm(
                    m2_pipeline, enc, shape, tensor, input, output, 2u);
                break;
            case TARGET_VERIFY_M8_M4:
                target_verify_m8_encode_smallm(
                    m4_pipeline, enc, shape, tensor, input, output, 4u);
                break;
            case TARGET_VERIFY_M8_MMA:
                target_verify_m8_encode_mma(
                    mma_pipeline, enc, shape, tensor, input, output);
                break;
        }
    }

    [enc endEncoding];
    [cmd commit];
    [cmd waitUntilCompleted];
    double wall_ms = now_ms() - wall_start;

    if (cmd.status != MTLCommandBufferStatusCompleted) {
        NSString *detail = cmd.error.localizedDescription;
        const char *names[] = {"8xM1", "4xM2", "2xM4", "M8-MMA"};
        fprintf(stderr,
            "ERROR: target verifier %s command failed: status=%ld%s%s\n",
            names[(int)mode], (long)cmd.status,
            detail.length ? " error=" : "",
            detail.length ? detail.UTF8String : "");
        return 0;
    }

    if (wall_ms_per_window) *wall_ms_per_window = wall_ms / (double)windows;
    if (gpu_ms_per_window) {
        double start = cmd.GPUStartTime, end = cmd.GPUEndTime;
        *gpu_ms_per_window =
            (start > 0.0 && end >= start)
            ? ((end - start) * 1000.0 / (double)windows) : 0.0;
    }
    return 1;
}

static uint64_t target_verify_m8_exact_count(
    const float *a, const float *b, size_t n
) {
    uint64_t exact = 0;
    for (size_t i = 0; i < n; i++) {
        uint32_t ua = 0, ub = 0;
        memcpy(&ua, &a[i], sizeof(ua));
        memcpy(&ub, &b[i], sizeof(ub));
        if (ua == ub) exact++;
    }
    return exact;
}

static int run_target_verify_affine_m8_mma_benchmark(
    MetalCtx *ctx, MatvecBenchShape *shapes, int shape_count, int samples
) {
    if (!ctx || !ctx->matvec_v3 || samples <= 0) return 1;

    id<MTLComputePipelineState> m2_pipeline =
        target_verify_load_benchmark_pipeline(
            ctx, @"target_verify_affine_m2.metal", @"dense_affine_q4_m2");
    id<MTLComputePipelineState> m4_pipeline =
        target_verify_load_benchmark_pipeline(
            ctx, @"target_verify_affine_m4.metal", @"dense_affine_q4_m4");
    id<MTLComputePipelineState> mma_pipeline =
        target_verify_load_benchmark_pipeline(
            ctx, @"target_verify_affine_m8_mma.metal", @"dense_affine_q4_m8_mma");
    if (!m2_pipeline || !m4_pipeline || !mma_pipeline) return 1;

    const int block_windows = 16;
    const int warmup_blocks = 4;
    id<MTLBuffer> input = [ctx->device
        newBufferWithLength:8u * 2048u * sizeof(float)
        options:MTLResourceStorageModeShared];
    id<MTLBuffer> ref_output = [ctx->device
        newBufferWithLength:8u * 8192u * sizeof(float)
        options:MTLResourceStorageModeShared];
    id<MTLBuffer> m2_output = [ctx->device
        newBufferWithLength:8u * 8192u * sizeof(float)
        options:MTLResourceStorageModeShared];
    id<MTLBuffer> m4_output = [ctx->device
        newBufferWithLength:8u * 8192u * sizeof(float)
        options:MTLResourceStorageModeShared];
    id<MTLBuffer> mma_output = [ctx->device
        newBufferWithLength:8u * 8192u * sizeof(float)
        options:MTLResourceStorageModeShared];
    if (!input || !ref_output || !m2_output || !m4_output || !mma_output) {
        fprintf(stderr, "ERROR: target verifier M8 MMA benchmark buffer allocation failed\n");
        return 1;
    }

    printf("=== M8 Simdgroup-Matrix Target-Verifier Affine Benchmark ===\n");
    printf("Device: %s\n", ctx->device.name.UTF8String);
    printf("Reference: 8 x production dequant_matvec_4bit_v3 in one command buffer\n");
    printf("Controls: 4 x exact M2 and 2 x exact M4 shared-weight kernels\n");
    printf("Candidate: one Q4 simdgroup_matrix M8 dispatch (S=8, NT=4, RT=1)\n");
    printf("Contract: Flash Q4/group64 layout, BF16 scale+bias, FP32 inputs/outputs\n");
    printf("Exactness: M2/M4 expected bitwise; MMA numerical gap is measured, not assumed exact\n");
    printf("Shapes: large affine ceiling test only (8192x2048, 4096x2048)\n");
    printf("Measured block: %d M8 windows; samples=%d; warmup blocks=%d\n\n",
        block_windows, samples, warmup_blocks);

    int tested_shapes = 0;
    for (int si = 0; si < shape_count; si++) {
        MatvecBenchShape *shape = &shapes[si];
        if (strcmp(shape->label, "8192x2048") != 0 &&
            strcmp(shape->label, "4096x2048") != 0)
            continue;
        if (shape->tensor_count == 0) {
            printf("%-11s SKIPPED — no real resident MLX4 tensor resolved\n",
                shape->label);
            continue;
        }
        if (shape->in_dim != 2048u || (shape->out_dim & 31u) != 0u ||
            GROUP_SIZE != 64) {
            printf("%-11s SKIPPED — M8 MMA phase-1 requires K=2048, N%%32=0, group64\n",
                shape->label);
            continue;
        }

        float *rows = (float *)input.contents;
        for (uint32_t row = 0; row < 8u; row++) {
            float a = 0.009f + 0.0013f * (float)row;
            float b = 0.004f + 0.0007f * (float)row;
            float p = 0.21f + 0.031f * (float)row;
            float q = 0.05f + 0.006f * (float)row;
            for (uint32_t i = 0; i < shape->in_dim; i++) {
                rows[(size_t)row * shape->in_dim + i] =
                    sinf((float)i * a + 0.37f * (float)row) * p +
                    cosf((float)i * b + 0.19f * (float)row) * q;
            }
        }

        double ignored_wall = 0.0, ignored_gpu = 0.0;
        id<MTLBuffer> outputs[4] =
            {ref_output, m2_output, m4_output, mma_output};
        for (int mode = 0; mode < 4; mode++) {
            if (!target_verify_m8_run_block(
                    ctx, m2_pipeline, m4_pipeline, mma_pipeline,
                    shape, input, outputs[mode], (TargetVerifyM8Mode)mode, 1,
                    &ignored_wall, &ignored_gpu))
                return 1;
        }

        const size_t values = 8u * (size_t)shape->out_dim;
        double m2_max = 0.0, m2_rms = 0.0;
        double m4_max = 0.0, m4_rms = 0.0;
        double mma_max = 0.0, mma_rms = 0.0;
        matvec_bench_compare(
            (const float *)ref_output.contents,
            (const float *)m2_output.contents,
            (uint32_t)values, &m2_max, &m2_rms);
        matvec_bench_compare(
            (const float *)ref_output.contents,
            (const float *)m4_output.contents,
            (uint32_t)values, &m4_max, &m4_rms);
        matvec_bench_compare(
            (const float *)ref_output.contents,
            (const float *)mma_output.contents,
            (uint32_t)values, &mma_max, &mma_rms);
        uint64_t m2_exact = target_verify_m8_exact_count(
            (const float *)ref_output.contents,
            (const float *)m2_output.contents, values);
        uint64_t m4_exact = target_verify_m8_exact_count(
            (const float *)ref_output.contents,
            (const float *)m4_output.contents, values);
        uint64_t mma_exact = target_verify_m8_exact_count(
            (const float *)ref_output.contents,
            (const float *)mma_output.contents, values);
        size_t mma_nonfinite = 0;
        double ref_peak = 0.0, mma_peak = 0.0, row_max[8] = {0};
        const float *ref_values = (const float *)ref_output.contents;
        const float *mma_values = (const float *)mma_output.contents;
        for (size_t v = 0; v < values; v++) {
            if (!isfinite(ref_values[v]) || !isfinite(mma_values[v])) {
                mma_nonfinite++;
                continue;
            }
            double ra = fabs((double)ref_values[v]);
            double ma = fabs((double)mma_values[v]);
            double delta = fabs((double)ref_values[v] - (double)mma_values[v]);
            if (ra > ref_peak) ref_peak = ra;
            if (ma > mma_peak) mma_peak = ma;
            if (delta > row_max[v / shape->out_dim])
                row_max[v / shape->out_dim] = delta;
        }
        if (mma_nonfinite) {
            fprintf(stderr, "ERROR: M8 MMA output contains %zu nonfinite values\n",
                mma_nonfinite);
            return 1;
        }

        for (int w = 0; w < warmup_blocks; w++) {
            for (int mode = 0; mode < 4; mode++) {
                if (!target_verify_m8_run_block(
                        ctx, m2_pipeline, m4_pipeline, mma_pipeline,
                        shape, input, outputs[mode], (TargetVerifyM8Mode)mode,
                        block_windows, NULL, NULL))
                    return 1;
            }
        }

        double *wall[4] = {0}, *gpu[4] = {0};
        for (int mode = 0; mode < 4; mode++) {
            wall[mode] = calloc((size_t)samples, sizeof(double));
            gpu[mode] = calloc((size_t)samples, sizeof(double));
            if (!wall[mode] || !gpu[mode]) return 1;
        }

        int gpu_valid = 1;
        for (int sample = 0; sample < samples; sample++) {
            // Rotate first mode to reduce thermal/order bias.
            for (int order = 0; order < 4; order++) {
                int mode = (sample + order) & 3;
                if (!target_verify_m8_run_block(
                        ctx, m2_pipeline, m4_pipeline, mma_pipeline,
                        shape, input, outputs[mode], (TargetVerifyM8Mode)mode,
                        block_windows, &wall[mode][sample], &gpu[mode][sample]))
                    return 1;
                if (gpu[mode][sample] <= 0.0) gpu_valid = 0;
            }
        }

        for (int mode = 0; mode < 4; mode++) {
            qsort(wall[mode], (size_t)samples, sizeof(double), matvec_bench_double_cmp);
            qsort(gpu[mode], (size_t)samples, sizeof(double), matvec_bench_double_cmp);
        }
        int mid = samples / 2;

        printf("%-11s real tensors=%d\n", shape->label, shape->tensor_count);
        printf("  M2 correctness:  max_abs=%.9g rms=%.9g bitwise_equal=%llu/%llu\n",
            m2_max, m2_rms, (unsigned long long)m2_exact,
            (unsigned long long)values);
        printf("  M4 correctness:  max_abs=%.9g rms=%.9g bitwise_equal=%llu/%llu\n",
            m4_max, m4_rms, (unsigned long long)m4_exact,
            (unsigned long long)values);
        printf("  MMA vs M1:       max_abs=%.9g rms=%.9g bitwise_equal=%llu/%llu\n",
            mma_max, mma_rms, (unsigned long long)mma_exact,
            (unsigned long long)values);
        printf("  MMA sanity:      nonfinite=%zu ref_peak=%.9g mma_peak=%.9g row_max=[%.3g %.3g %.3g %.3g %.3g %.3g %.3g %.3g]\n",
            mma_nonfinite, ref_peak, mma_peak, row_max[0], row_max[1],
            row_max[2], row_max[3], row_max[4], row_max[5], row_max[6],
            row_max[7]);

        if (gpu_valid) {
            double ref = gpu[TARGET_VERIFY_M8_REF_M1][mid];
            printf("  GPU median/window:\n");
            printf("    8xM1   %.6f ms  ratio=1.0000\n", ref);
            printf("    4xM2   %.6f ms  ratio=%.4f\n",
                gpu[TARGET_VERIFY_M8_M2][mid],
                gpu[TARGET_VERIFY_M8_M2][mid] / ref);
            printf("    2xM4   %.6f ms  ratio=%.4f\n",
                gpu[TARGET_VERIFY_M8_M4][mid],
                gpu[TARGET_VERIFY_M8_M4][mid] / ref);
            printf("    M8-MMA %.6f ms  ratio=%.4f  effective speedup=%.2fx\n",
                gpu[TARGET_VERIFY_M8_MMA][mid],
                gpu[TARGET_VERIFY_M8_MMA][mid] / ref,
                ref / gpu[TARGET_VERIFY_M8_MMA][mid]);
        } else {
            printf("  GPU median: unavailable (invalid Metal timestamps in sample set)\n");
        }

        double ref_wall = wall[TARGET_VERIFY_M8_REF_M1][mid];
        printf("  wall median/window:\n");
        printf("    8xM1   %.6f ms  ratio=1.0000\n", ref_wall);
        printf("    4xM2   %.6f ms  ratio=%.4f\n",
            wall[TARGET_VERIFY_M8_M2][mid],
            wall[TARGET_VERIFY_M8_M2][mid] / ref_wall);
        printf("    2xM4   %.6f ms  ratio=%.4f\n",
            wall[TARGET_VERIFY_M8_M4][mid],
            wall[TARGET_VERIFY_M8_M4][mid] / ref_wall);
        printf("    M8-MMA %.6f ms  ratio=%.4f  effective speedup=%.2fx\n",
            wall[TARGET_VERIFY_M8_MMA][mid],
            wall[TARGET_VERIFY_M8_MMA][mid] / ref_wall,
            ref_wall / wall[TARGET_VERIFY_M8_MMA][mid]);

        for (int mode = 0; mode < 4; mode++) {
            free(wall[mode]);
            free(gpu[mode]);
        }
        tested_shapes++;
    }

    if (tested_shapes == 0) {
        fprintf(stderr, "ERROR: M8 MMA benchmark found no compatible real MLX4 tensors\n");
        return 1;
    }
    return 0;
}
#endif

#include "target_verify_affine_exactness_probe.inc"

static void matvec_bench_discover_cached(WeightFile *wf, MetalCtx *ctx,
									 MatvecBenchShape *shapes,
									 char names[7][MAX_LAYERS * 4][160]);

static int run_matvec_benchmark(WeightFile *wf, MetalCtx *ctx, int pairs) {
	if (!wf || !ctx || !ctx->matvec_v3 || !ctx->matvec_fast) {
		fprintf(stderr, "ERROR: matvec benchmark requires Metal and both MLX4 pipelines\n");
		return 1;
	}
	if (pairs < 1) pairs = 100;
	const int block_size = 64, warmup_blocks = 10, shape_count = 7;
	MatvecBenchShape shapes[7] = {
		{ "8192x2048", 8192, 2048, {{0}}, 0, 0 },
		{ "4096x2048", 4096, 2048, {{0}}, 0, 0 },
		{ "2048x4096", 2048, 4096, {{0}}, 0, 0 },
		{ "512x2048", 512, 2048, {{0}}, 0, 0 },
		{ "256x2048", 256, 2048, {{0}}, 0, 0 },
		{ "32x2048", 32, 2048, {{0}}, 0, 0 },
		{ "1x2048", 1, 2048, {{0}}, 0, 0 }
	};
	static char names[7][MAX_LAYERS * 4][160];
	memset(names, 0, sizeof(names));
	matvec_bench_discover_cached(wf, ctx, shapes, names);
#if defined(TARGET_VERIFY_AFFINE_EXACTNESS_PROBE) && defined(TARGET_VERIFY_MULTIROW_AFFINE_MMA)
	return target_verify_exactness_probe(ctx, shapes, shape_count);
#elif defined(TARGET_VERIFY_MULTIROW_AFFINE_MMA)
	return run_target_verify_affine_m8_mma_benchmark(ctx, shapes, shape_count, pairs);
#elif defined(TARGET_VERIFY_MULTIROW_AFFINE_M4)
	return run_target_verify_affine_m4_benchmark(ctx, shapes, shape_count, pairs);
#elif defined(TARGET_VERIFY_MULTIROW_AFFINE)
	return run_target_verify_affine_m2_benchmark(ctx, shapes, shape_count, pairs);
#endif
	float *input = malloc(4096 * sizeof(float));
	float *out_v3 = malloc(8192 * sizeof(float));
	float *out_fast = malloc(8192 * sizeof(float));
	double *v3_wall = malloc((size_t)pairs * sizeof(double));
	double *fast_wall = malloc((size_t)pairs * sizeof(double));
	double *v3_gpu = malloc((size_t)pairs * sizeof(double));
	double *fast_gpu = malloc((size_t)pairs * sizeof(double));
	double *paired_delta = malloc((size_t)pairs * sizeof(double));
	if (!input || !out_v3 || !out_fast || !v3_wall || !fast_wall || !v3_gpu || !fast_gpu || !paired_delta) return 1;
	for (int i = 0; i < 4096; i++) input[i] = sinf((float)i * 0.017f) * 0.25f;
	printf("=== MLX4 Dense Matvec Benchmark ===\nDevice: %s\n", [[ctx->device name] UTF8String]);
	printf("Measured block size: %d dispatches\nMeasured pairs: %d\nWarmup blocks: %d\n", block_size, pairs, warmup_blocks);
	printf("Timing: GPU timestamps when valid, plus wall-clock block timing\nTensor source: real model tensors only\n\n");
	printf("[matvec-bench] resolved real MLX4 tensors:\n");
	for (int i = 0; i < shape_count; i++) printf("  %-10s: %d\n", shapes[i].label, shapes[i].tensor_count);
	int gpu_timestamp_valid = 0;
	for (int i = 0; i < shape_count; i++) {
		MatvecBenchShape *s = &shapes[i];
		if (s->tensor_count == 0) {
			printf("%-11s  SKIPPED — no real MLX4 tensor resolved (matching weight/scales/biases unavailable)\n", s->label);
			continue;
		}
		printf("%-11s  real tensors: %d\n", s->label, s->tensor_count);
		for (int w = 0; w < warmup_blocks; w++) {
			memcpy([ctx->buf_input contents], input, (size_t)s->in_dim * sizeof(float));
			matvec_bench_encode_block(ctx, s, 0, block_size);
			matvec_bench_encode_block(ctx, s, 1, block_size);
		}
		for (int p = 0; p < pairs; p++) {
			int first_v3 = (p & 1) == 0;
			for (int order = 0; order < 2; order++) {
				int use_v3 = first_v3 ? (order == 0) : (order == 1);
				memcpy([ctx->buf_input contents], input, (size_t)s->in_dim * sizeof(float));
				double wall_start = now_ms();
				id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
				id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
				for (int d = 0; d < block_size; d++) {
					const MatvecBenchTensor *t = &s->tensors[d % s->tensor_count];
					[enc setComputePipelineState:use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
					[enc setBuffer:t->weight_buf offset:t->weight_off atIndex:0]; [enc setBuffer:t->weight_buf offset:t->scale_off atIndex:1]; [enc setBuffer:t->weight_buf offset:t->bias_off atIndex:2];
					[enc setBuffer:ctx->buf_input offset:0 atIndex:3]; [enc setBuffer:ctx->buf_output offset:0 atIndex:4];
					[enc setBytes:&s->out_dim length:4 atIndex:5]; [enc setBytes:&s->in_dim length:4 atIndex:6]; uint32_t gs = GROUP_SIZE; [enc setBytes:&gs length:4 atIndex:7];
					if (use_v3) { uint32_t tgs = (s->out_dim + 7) / 8; [enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)]; }
					else [enc dispatchThreadgroups:MTLSizeMake(s->out_dim, 1, 1) threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
				}
				[enc endEncoding]; [cmd commit]; [cmd waitUntilCompleted];
				double wall_ms = now_ms() - wall_start;
				double gpu_ms = (cmd.GPUStartTime > 0.0 && cmd.GPUEndTime >= cmd.GPUStartTime) ? (cmd.GPUEndTime - cmd.GPUStartTime) * 1000.0 : 0.0;
				if (gpu_ms > 0.0) gpu_timestamp_valid = 1;
				if (use_v3) { v3_wall[p] = wall_ms / block_size; v3_gpu[p] = gpu_ms / block_size; }
				else { fast_wall[p] = wall_ms / block_size; fast_gpu[p] = gpu_ms / block_size; }
			}
		}
		for (int p = 0; p < pairs; p++) paired_delta[p] = v3_wall[p] - fast_wall[p];
		qsort(v3_wall, (size_t)pairs, sizeof(double), matvec_bench_double_cmp); qsort(fast_wall, (size_t)pairs, sizeof(double), matvec_bench_double_cmp); qsort(paired_delta, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
		qsort(v3_gpu, (size_t)pairs, sizeof(double), matvec_bench_double_cmp); qsort(fast_gpu, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
		printf("  Kernel   GPU median ms   Wall median ms\n  v3       %10.3f       %10.3f\n  fast     %10.3f       %10.3f\n", v3_gpu[pairs/2], v3_wall[pairs/2], fast_gpu[pairs/2], fast_wall[pairs/2]);
		printf("  paired delta: %.4f ms, %.2f%% (negative means V3 faster)\n", paired_delta[pairs/2], 100.0 * paired_delta[pairs/2] / fast_wall[pairs/2]);
		memcpy([ctx->buf_input contents], input, (size_t)s->in_dim * sizeof(float)); matvec_bench_encode_single(ctx, s, 1); memcpy(out_v3, [ctx->buf_output contents], (size_t)s->out_dim * sizeof(float));
		memcpy([ctx->buf_input contents], input, (size_t)s->in_dim * sizeof(float)); matvec_bench_encode_single(ctx, s, 0); memcpy(out_fast, [ctx->buf_output contents], (size_t)s->out_dim * sizeof(float));
		double max_abs, rms; matvec_bench_compare(out_v3, out_fast, s->out_dim, &max_abs, &rms);
		printf("  correctness: max_abs_diff=%.6g rms_diff=%.6g; best wall kernel: %s\n", max_abs, rms, v3_wall[pairs/2] <= fast_wall[pairs/2] ? "v3" : "fast");
	}
	if (!gpu_timestamp_valid) printf("GPU timestamps unavailable or invalid; wall-clock block timing is used.\n");
	free(paired_delta); free(fast_gpu); free(v3_gpu); free(fast_wall); free(v3_wall); free(out_fast); free(out_v3); free(input);
	return 0;
}

static void gpu_q6_k_matvec(
	MetalCtx *ctx,
	const GGUFBlockQ6K *W_q6_k,
	const float *x_f32, float *out_f32,
	uint32_t out_dim, uint32_t in_dim
) {
	memcpy([ctx->buf_input contents], x_f32, in_dim * sizeof(float));

	size_t o_size = (size_t)out_dim * sizeof(float);
	id<MTLBuffer> o_buf = ctx->buf_output;
	if (o_size > [o_buf length]) {
		o_buf = [ctx->device newBufferWithLength:o_size options:MTLResourceStorageModeShared];
	}

	NSUInteger w_off = 0;
	if (ctx->gguf_lm_head_buf) {
		w_off = (NSUInteger)((const char *)W_q6_k - (const char *)[ctx->gguf_lm_head_buf contents]);
	}

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
	[enc setComputePipelineState:ctx->matvec_q6_k];
	[enc setBuffer:ctx->gguf_lm_head_buf offset:w_off atIndex:0];
	[enc setBuffer:ctx->buf_input        offset:0     atIndex:1];
	[enc setBuffer:o_buf                 offset:0     atIndex:2];
	[enc setBytes:&out_dim               length:4     atIndex:3];
	[enc setBytes:&in_dim                length:4     atIndex:4];
	[enc dispatchThreadgroups:MTLSizeMake(out_dim, 1, 1)
		threadsPerThreadgroup:MTLSizeMake(32, 1, 1)];
	[enc endEncoding];
	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];
	if (out_dim == (uint32_t)VOCAB_SIZE) pipeline_profile_capture_lm_cmd(cmdbuf);

	memcpy(out_f32, [o_buf contents], o_size);
}

// Track whether LM head weights have been dequantized to nax_w_half
static int g_nax_lmhead_dequantized = 0;

// NAX 2-pass dispatch: dequant weights to half (cached), convert input to half, then NAX GEMM
// Only used for large projections (LM head) where NAX provides significant speedup
static void gpu_nax_dequant_gemm(
	MetalCtx *ctx,
	const void *W_packed, const void *scales, const void *biases,
	const float *x_f32, float *out_f32,
	uint32_t out_dim, uint32_t in_dim, uint32_t group_size
) {
	uint32_t num_groups = in_dim / group_size;
	NSUInteger w_off = (NSUInteger)((const char *)W_packed - (const char *)[ctx->wf_buf contents]);
	NSUInteger s_off = (NSUInteger)((const char *)scales   - (const char *)[ctx->wf_buf contents]);
	NSUInteger b_off = (NSUInteger)((const char *)biases   - (const char *)[ctx->wf_buf contents]);

	// Pad M to NAX tile size (32) to avoid cooperative tensor store overflow
	const uint32_t NAX_BM = 32;
	uint32_t M_padded = NAX_BM;  // always pad to at least one full tile

	// Ensure NAX buffers are large enough
	size_t w_half_size = (size_t)out_dim * in_dim * sizeof(uint16_t);
	if ([ctx->nax_w_half length] < w_half_size) {
		ctx->nax_w_half = [ctx->device newBufferWithLength:w_half_size options:MTLResourceStorageModeShared];
	}
	size_t x_half_size = (size_t)M_padded * in_dim * sizeof(uint16_t);
	if ([ctx->nax_x_half length] < x_half_size) {
		ctx->nax_x_half = [ctx->device newBufferWithLength:x_half_size options:MTLResourceStorageModeShared];
	}
	size_t c_size = (size_t)M_padded * out_dim * sizeof(float);
	if ([ctx->buf_output length] < c_size) {
		// Need a larger output buffer for padded M
		// Use a temporary buffer
	}

	// Copy input to buf_input (only 1 row of actual data, zero-pad rest for M_padded=32)
	size_t input_padded_size = (size_t)M_padded * in_dim * sizeof(float);
	if ([ctx->buf_input length] < input_padded_size) {
		ctx->buf_input = [ctx->device newBufferWithLength:input_padded_size options:MTLResourceStorageModeShared];
	}
	memcpy([ctx->buf_input contents], x_f32, in_dim * sizeof(float));
	memset((char *)[ctx->buf_input contents] + in_dim * sizeof(float), 0,
		   (M_padded - 1) * in_dim * sizeof(float));

	// Pass 1: Dequantize 4-bit weights → half (cached after first call)
	if (!g_nax_lmhead_dequantized) {
		id<MTLCommandBuffer> deq_cmd = [ctx->queue commandBuffer];
		id<MTLComputeCommandEncoder> enc = [deq_cmd computeCommandEncoder];
		[enc setComputePipelineState:ctx->nax_dequant];
		[enc setBuffer:ctx->wf_buf    offset:w_off atIndex:0];
		[enc setBuffer:ctx->wf_buf    offset:s_off atIndex:1];
		[enc setBuffer:ctx->wf_buf    offset:b_off atIndex:2];
		[enc setBuffer:ctx->nax_w_half offset:0    atIndex:3];
		[enc setBytes:&out_dim length:4 atIndex:4];
		[enc setBytes:&in_dim  length:4 atIndex:5];
		uint32_t total_groups = out_dim * num_groups;
		uint32_t tg_size = 256;
		uint32_t num_tgs = (total_groups + tg_size - 1) / tg_size;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(tg_size, 1, 1)];
		[enc endEncoding];
		[deq_cmd commit]; [deq_cmd waitUntilCompleted];
		g_nax_lmhead_dequantized = 1;
		fprintf(stderr, "[nax] LM head weights dequantized to half (cached, %.1f MB)\n",
				(double)out_dim * in_dim * 2 / 1e6);
	}

	// NAX GEMM: C[M_padded, N] = x_f32[M_padded, K] @ W_half[N, K]^T
	// nax_gemm_f32_input converts f32→half inline (no separate pass)
	id<MTLBuffer> c_buf = ctx->nax_c_buf;

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
	[enc setComputePipelineState:ctx->nax_gemm];
	[enc setBuffer:ctx->buf_input  offset:0 atIndex:0];  // A[M_padded, K] float32
	[enc setBuffer:ctx->nax_w_half offset:0 atIndex:1];  // B[N, K] half (cached)
	[enc setBuffer:c_buf           offset:0 atIndex:2];  // C[M_padded, N] float32
	[enc setBytes:&M_padded length:4 atIndex:3];
	[enc setBytes:&out_dim  length:4 atIndex:4];
	[enc setBytes:&in_dim   length:4 atIndex:5];
	int gx = (out_dim + 31) / 32;
	int gy = (M_padded + 31) / 32;
	[enc dispatchThreadgroups:MTLSizeMake(gx, gy, 1)
		threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
	[enc endEncoding];

	// Extract row 0 from column-major output on GPU (avoids slow strided CPU readback)
	{
		id<MTLComputeCommandEncoder> enc2 = [cmdbuf computeCommandEncoder];
		[enc2 setComputePipelineState:ctx->nax_extract];
		[enc2 setBuffer:c_buf          offset:0 atIndex:0];  // column-major input
		[enc2 setBuffer:ctx->buf_output offset:0 atIndex:1]; // row-major output
		[enc2 setBytes:&out_dim  length:4 atIndex:2];
		[enc2 setBytes:&M_padded length:4 atIndex:3];
	[enc2 dispatchThreads:MTLSizeMake(out_dim, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(MIN(out_dim, (uint32_t)1024), 1, 1)];
		[enc2 endEncoding];
	}
	if (g_gpu_argmax_active && ctx->argmax) {
		id<MTLComputeCommandEncoder> enc3 = [cmdbuf computeCommandEncoder];
		uint32_t dim = out_dim;
		[enc3 setComputePipelineState:ctx->argmax];
		[enc3 setBuffer:ctx->buf_output offset:0 atIndex:0];
		[enc3 setBuffer:ctx->argmax_result offset:0 atIndex:1];
		[enc3 setBytes:&dim length:sizeof(dim) atIndex:2];
		[enc3 dispatchThreadgroups:MTLSizeMake(1, 1, 1) threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
		[enc3 endEncoding];
	}

	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];
	if (out_dim == (uint32_t)VOCAB_SIZE) pipeline_profile_capture_lm_cmd(cmdbuf);

	if (g_gpu_argmax_active && ctx->argmax)
		g_gpu_argmax_result = *(const uint32_t *)[ctx->argmax_result contents];
	else
		memcpy(out_f32, [ctx->buf_output contents], out_dim * sizeof(float));
}

// Wrapper: use GPU if available and weight buffer is set, CPU otherwise
static void fast_dequant_matvec(
	const uint32_t *W, const uint16_t *scales, const uint16_t *biases,
	const float *x, float *out,
	int out_dim, int in_dim, int group_size
) {
	if (g_metal && g_metal->wf_buf) {
		// Use NAX for LM head only (248320 × 4096) — largest projection
		// NAX tile is 32×32; M is padded to 32 for single-token decode
		if (g_metal->has_nax && !g_nax_disabled && out_dim > 100000) {
			gpu_nax_dequant_gemm(g_metal, W, scales, biases, x, out,
								 (uint32_t)out_dim, (uint32_t)in_dim, (uint32_t)group_size);
		} else {
			gpu_dequant_matvec(g_metal, W, scales, biases, x, out,
							   (uint32_t)out_dim, (uint32_t)in_dim, (uint32_t)group_size);
		}
	} else {
		cpu_dequant_matvec(W, scales, biases, x, out, out_dim, in_dim, group_size);
	}
}

static void fast_q6_k_matvec(
	const GGUFBlockQ6K *W,
	const float *x, float *out,
	int out_dim, int in_dim
) {
	if (g_metal && g_metal->gguf_lm_head_buf && g_metal->matvec_q6_k) {
		gpu_q6_k_matvec(g_metal, W, x, out, (uint32_t)out_dim, (uint32_t)in_dim);
	} else {
		cpu_q6_k_matvec(W, x, out, out_dim, in_dim);
	}
}

// ============================================================================
// Batched GPU matmul: encode N independent matmuls sharing the same input
// into ONE command buffer, reducing dispatch overhead by N-1 round-trips.
// ============================================================================

typedef struct {
	const void *W;           // packed weights (pointer into mmap'd file)
	const void *scales;      // scales (pointer into mmap'd file)
	const void *biases;      // biases (pointer into mmap'd file)
	float *out_cpu;          // CPU output pointer (result copied here after GPU finishes)
	uint32_t out_dim;
	uint32_t in_dim;
	uint32_t group_size;
	int batch_slot;          // which batch_out[slot] to use for GPU output
	uint8_t kind;
	uint8_t source;
} BatchMatvecSpec;

enum {
	MATVEC_KIND_MLX4 = 0,
	MATVEC_KIND_GGUF_Q8_0 = 1,
};

enum {
	MATVEC_SOURCE_WF = 0,
	MATVEC_SOURCE_GGUF_QKV = 1,
	MATVEC_SOURCE_GGUF_FULL_ATTN = 2,
	MATVEC_SOURCE_GGUF_LINEAR = 3,
	MATVEC_SOURCE_GGUF_SHARED = 4,
};

static inline int tiny_matvec_target_shape(const BatchMatvecSpec *s) {
	if (!s || s->kind != MATVEC_KIND_MLX4 || s->source != MATVEC_SOURCE_WF) return 0;
	if (s->out_dim == 32 && s->in_dim == 2048) return 32;
	if (s->out_dim == 1 && s->in_dim == 2048) return 1;
	return 0;
}

static inline int tiny_matvec_select_v3(const BatchMatvecSpec *s) {
	int use_v3 = (s->in_dim <= 4096);
	if (g_tiny_matvec_fast_enabled && tiny_matvec_target_shape(s)) {
		use_v3 = 0;
	}
	return use_v3;
}

static inline void tiny_matvec_count_production(const BatchMatvecSpec *s, int use_v3) {
	if (!g_tiny_matvec_telemetry_enabled) return;
	int shape = tiny_matvec_target_shape(s);
	TinyMatvecTelemetry *t = (shape == 32) ? &tiny_telem_32x2048 :
							 (shape == 1) ? &tiny_telem_1x2048 : NULL;
	if (!t) return;
	if (use_v3) t->calls_v3++;
	else t->calls_fast++;
}

static void tiny_matvec_capture_sample(
	MetalCtx *ctx,
	TinyMatvecReplaySample *dst,
	const BatchMatvecSpec *s,
	const float *input,
	const char *label
) {
	if (!g_tiny_matvec_telemetry_enabled || !ctx || !ctx->wf_buf ||
		!dst || dst->valid || !s || !input) return;
	if (!tiny_matvec_target_shape(s)) return;

	const char *base = (const char *)[ctx->wf_buf contents];
	const char *end = base + [ctx->wf_buf length];
	if ((const char *)s->W < base || (const char *)s->W >= end ||
		(const char *)s->scales < base || (const char *)s->scales >= end ||
		(const char *)s->biases < base || (const char *)s->biases >= end) return;

	dst->out_dim = s->out_dim;
	dst->in_dim = s->in_dim;
	dst->group_size = s->group_size;
	dst->weight_off = (size_t)((const char *)s->W - base);
	dst->scale_off = (size_t)((const char *)s->scales - base);
	dst->bias_off = (size_t)((const char *)s->biases - base);
	memcpy(dst->input, input, 2048 * sizeof(float));
	snprintf(dst->label, sizeof(dst->label), "%s", label ? label : "production");
	dst->valid = 1;
}

static id<MTLBuffer> matvec_source_buffer(MetalCtx *ctx, uint8_t source, const char **base_out) {
	if (base_out) {
		*base_out = NULL;
	}
	id<MTLBuffer> buf = nil;
	switch (source) {
		case MATVEC_SOURCE_WF:
			buf = ctx->wf_buf;
			break;
		case MATVEC_SOURCE_GGUF_QKV:
			buf = ctx->gguf_qkv_buf;
			break;
		case MATVEC_SOURCE_GGUF_FULL_ATTN:
			buf = ctx->gguf_full_attn_buf;
			break;
		case MATVEC_SOURCE_GGUF_LINEAR:
			buf = ctx->gguf_linear_buf;
			break;
		case MATVEC_SOURCE_GGUF_SHARED:
			buf = ctx->gguf_shared_buf;
			break;
		default:
			buf = nil;
			break;
	}
	if (buf && base_out) {
		*base_out = (const char *)[buf contents];
	}
	return buf;
}


enum {
	CMD1_LINEAR_QKV = 0, CMD1_LINEAR_Z, CMD1_LINEAR_BETA, CMD1_LINEAR_ALPHA,
	CMD1_FULL_Q, CMD1_FULL_K, CMD1_FULL_V, CMD1_FAMILY_COUNT
};

typedef struct {
	int valid;
	const char *label;
	uint8_t kind, source;
	uint32_t out_dim, in_dim, group_size;
	size_t weight_off, scale_off, bias_off;
	float input[2048];
	uint64_t production_calls;
} Cmd1ProfileSample;

static Cmd1ProfileSample g_cmd1_sample[CMD1_FAMILY_COUNT] = {
	{.label="linear qkv"}, {.label="linear z"}, {.label="linear beta"}, {.label="linear alpha"},
	{.label="full-attn q"}, {.label="full-attn k"}, {.label="full-attn v"}
};
static uint64_t g_cmd1_profile_tokens = 0;

typedef struct {
	uint64_t count;
	uint64_t gpu_timestamp_count;
	double commit_to_complete_ms;
	double gpu_duration_ms;
	double outside_gpu_ms;
	double first_gpu_start_s;
	double last_gpu_end_s;
} Cmd1ProductionTimingBucket;

// [0]=linear/GatedDeltaNet, [1]=full attention
// [0]=original path, [1]=fast path queued directly behind previous GPU-combined CMD3
static Cmd1ProductionTimingBucket g_cmd1_prod_timing[2][2];

static void cmd1_production_timing_note(
	id<MTLCommandBuffer> cmd,
	int is_full,
	int fast_path,
	double commit_to_complete_ms
) {
	if (!g_cmd1_profile_enabled || !g_cmd1_profile_decode_active || !cmd) return;

	int type_idx = is_full ? 1 : 0;
	int path_idx = fast_path ? 1 : 0;
	Cmd1ProductionTimingBucket *b = &g_cmd1_prod_timing[type_idx][path_idx];

	b->count++;
	b->commit_to_complete_ms += commit_to_complete_ms;

	double gpu_start = cmd.GPUStartTime;
	double gpu_end = cmd.GPUEndTime;
	if (gpu_start > 0.0 && gpu_end >= gpu_start) {
		double gpu_ms = (gpu_end - gpu_start) * 1000.0;
		double outside_ms = commit_to_complete_ms - gpu_ms;
		if (outside_ms < 0.0) outside_ms = 0.0;

		if (b->gpu_timestamp_count == 0)
			b->first_gpu_start_s = gpu_start;
		b->last_gpu_end_s = gpu_end;
		b->gpu_timestamp_count++;
		b->gpu_duration_ms += gpu_ms;
		b->outside_gpu_ms += outside_ms;
	}
}

static void cmd1_production_timing_print(void) {
	if (!g_cmd1_profile_enabled) return;

	printf("\n[CMD1 production command-buffer timing]\n");
	printf("  Whole-command-buffer GPU timestamps measured after the existing production wait.\n");
	printf("  commit->complete includes queue backlog + CMD1 GPU execution + host completion overhead.\n");
	printf("  outside-GPU = commit->complete - GPU duration; on the fast path it can include prior queued CMD3 work.\n");

	const char *type_name[2] = { "linear", "full-attn" };
	const char *path_name[2] = { "original", "fast-path" };

	double total_wall_ms = 0.0;
	double total_gpu_ms = 0.0;
	double total_outside_ms = 0.0;
	uint64_t total_count = 0;
	uint64_t total_gpu_count = 0;
	double first_gpu_start_s = 0.0;
	double last_gpu_end_s = 0.0;

	for (int type_idx = 0; type_idx < 2; type_idx++) {
		for (int path_idx = 0; path_idx < 2; path_idx++) {
			Cmd1ProductionTimingBucket *b = &g_cmd1_prod_timing[type_idx][path_idx];
			if (b->count == 0) continue;

			double avg_wall = b->commit_to_complete_ms / (double)b->count;
			double avg_gpu = b->gpu_timestamp_count
				? b->gpu_duration_ms / (double)b->gpu_timestamp_count : 0.0;
			double avg_outside = b->gpu_timestamp_count
				? b->outside_gpu_ms / (double)b->gpu_timestamp_count : 0.0;

			double wall_per_token = g_cmd1_profile_tokens
				? b->commit_to_complete_ms / (double)g_cmd1_profile_tokens : 0.0;
			double gpu_per_token = g_cmd1_profile_tokens
				? b->gpu_duration_ms / (double)g_cmd1_profile_tokens : 0.0;
			double outside_per_token = g_cmd1_profile_tokens
				? b->outside_gpu_ms / (double)g_cmd1_profile_tokens : 0.0;

			printf("  %-9s %-9s count=%llu",
				   type_name[type_idx], path_name[path_idx],
				   (unsigned long long)b->count);
			if (b->gpu_timestamp_count != b->count) {
				printf(" gpu_ts=%llu/%llu",
					   (unsigned long long)b->gpu_timestamp_count,
					   (unsigned long long)b->count);
			}
			printf("\n");
			printf("    avg/layer: commit->complete %.3f ms",
				   avg_wall);
			if (b->gpu_timestamp_count) {
				printf(" | GPU %.3f ms | outside-GPU %.3f ms",
					   avg_gpu, avg_outside);
			} else {
				printf(" | GPU timestamps unavailable");
			}
			printf("\n");
			printf("    contribution/token: wall %.3f ms",
				   wall_per_token);
			if (b->gpu_timestamp_count) {
				printf(" | GPU %.3f ms | outside-GPU %.3f ms",
					   gpu_per_token, outside_per_token);
			}
			printf("\n");
			if (b->gpu_timestamp_count) {
				printf("    first GPUStartTime: %.6f s | last GPUEndTime: %.6f s\n",
					   b->first_gpu_start_s, b->last_gpu_end_s);
				if (first_gpu_start_s == 0.0 || b->first_gpu_start_s < first_gpu_start_s)
					first_gpu_start_s = b->first_gpu_start_s;
				if (b->last_gpu_end_s > last_gpu_end_s)
					last_gpu_end_s = b->last_gpu_end_s;
			}

			total_count += b->count;
			total_gpu_count += b->gpu_timestamp_count;
			total_wall_ms += b->commit_to_complete_ms;
			total_gpu_ms += b->gpu_duration_ms;
			total_outside_ms += b->outside_gpu_ms;
		}
	}

	if (total_count == 0) {
		printf("  SKIPPED — no decode-time production CMD1 command buffers recorded\n");
		return;
	}

	double toks = g_cmd1_profile_tokens ? (double)g_cmd1_profile_tokens : 1.0;
	printf("  ----------------------------------------------------------------\n");
	printf("  all CMD1 production buffers: count=%llu, decode_tokens=%llu\n",
		   (unsigned long long)total_count,
		   (unsigned long long)g_cmd1_profile_tokens);
	printf("    commit->complete: %.3f ms/token\n", total_wall_ms / toks);
	if (total_gpu_count) {
		printf("    actual CMD1 GPU duration: %.3f ms/token\n", total_gpu_ms / toks);
		printf("    outside CMD1 GPU duration: %.3f ms/token\n", total_outside_ms / toks);
		printf("    GPU timestamp coverage: %llu/%llu command buffers\n",
			   (unsigned long long)total_gpu_count,
			   (unsigned long long)total_count);
		printf("    first GPUStartTime: %.6f s\n", first_gpu_start_s);
		printf("    last GPUEndTime:    %.6f s\n", last_gpu_end_s);
	}
	if (g_timing_enabled && g_timing.count > 0) {
		double reported_wait = g_timing.cmd1_wait / (double)g_timing.count *
			(g_cfg.num_layers > 0 ? g_cfg.num_layers : g_timing.count);
		printf("    existing cmd1_wait report: %.3f ms/token\n", reported_wait);
	}
}

typedef struct {
	uint64_t count;
	uint64_t gpu_timestamp_count;
	double commit_to_complete_ms;
	double gpu_duration_ms;
	double outside_gpu_ms;
	double first_gpu_start_s;
	double last_gpu_end_s;
} Cmd2ProductionTimingBucket;

// [0]=linear/GatedDeltaNet, [1]=full attention
// [0]=normal fused CMD2, [1]=full-attention GPU attention included in CMD2.
static Cmd2ProductionTimingBucket g_cmd2_prod_timing[2][2];

static void cmd2_production_timing_note(
	id<MTLCommandBuffer> cmd,
	int is_full,
	int gpu_attn_fuse,
	double commit_to_complete_ms
) {
	if (!g_cmd1_profile_enabled || !g_cmd1_profile_decode_active || !cmd) return;

	int type_idx = is_full ? 1 : 0;
	int path_idx = gpu_attn_fuse ? 1 : 0;
	Cmd2ProductionTimingBucket *b = &g_cmd2_prod_timing[type_idx][path_idx];

	b->count++;
	b->commit_to_complete_ms += commit_to_complete_ms;

	double gpu_start = cmd.GPUStartTime;
	double gpu_end = cmd.GPUEndTime;
	if (gpu_start > 0.0 && gpu_end >= gpu_start) {
		double gpu_ms = (gpu_end - gpu_start) * 1000.0;
		double outside_ms = commit_to_complete_ms - gpu_ms;
		if (outside_ms < 0.0) outside_ms = 0.0;

		if (b->gpu_timestamp_count == 0)
			b->first_gpu_start_s = gpu_start;
		b->last_gpu_end_s = gpu_end;
		b->gpu_timestamp_count++;
		b->gpu_duration_ms += gpu_ms;
		b->outside_gpu_ms += outside_ms;
	}
}

static void cmd2_production_timing_print(void) {
	if (!g_cmd1_profile_enabled) return;

	printf("\n[CMD2 production command-buffer timing]\n");
	printf("  Whole-command-buffer GPUStartTime/GPUEndTime measured after the existing CMD2 wait.\n");
	printf("  No additional synchronization is introduced by this telemetry.\n");
	printf("  commit->complete ends immediately after the existing wait; post-wait readback is excluded.\n");

	const char *type_name[2] = { "linear", "full-attn" };
	const char *path_name[2] = { "fused", "gpu-attn" };

	double total_wall_ms = 0.0;
	double total_gpu_ms = 0.0;
	double total_outside_ms = 0.0;
	uint64_t total_count = 0;
	uint64_t total_gpu_count = 0;
	double first_gpu_start_s = 0.0;
	double last_gpu_end_s = 0.0;

	for (int type_idx = 0; type_idx < 2; type_idx++) {
		for (int path_idx = 0; path_idx < 2; path_idx++) {
			Cmd2ProductionTimingBucket *b = &g_cmd2_prod_timing[type_idx][path_idx];
			if (b->count == 0) continue;

			double avg_wall = b->commit_to_complete_ms / (double)b->count;
			double avg_gpu = b->gpu_timestamp_count
				? b->gpu_duration_ms / (double)b->gpu_timestamp_count : 0.0;
			double avg_outside = b->gpu_timestamp_count
				? b->outside_gpu_ms / (double)b->gpu_timestamp_count : 0.0;

			double wall_per_token = g_cmd1_profile_tokens
				? b->commit_to_complete_ms / (double)g_cmd1_profile_tokens : 0.0;
			double gpu_per_token = g_cmd1_profile_tokens
				? b->gpu_duration_ms / (double)g_cmd1_profile_tokens : 0.0;
			double outside_per_token = g_cmd1_profile_tokens
				? b->outside_gpu_ms / (double)g_cmd1_profile_tokens : 0.0;

			printf("  %-9s %-9s count=%llu",
				   type_name[type_idx], path_name[path_idx],
				   (unsigned long long)b->count);
			if (b->gpu_timestamp_count != b->count) {
				printf(" gpu_ts=%llu/%llu",
					   (unsigned long long)b->gpu_timestamp_count,
					   (unsigned long long)b->count);
			}
			printf("\n");

			printf("    avg/layer: commit->complete %.3f ms",
				   avg_wall);
			if (b->gpu_timestamp_count) {
				printf(" | GPU %.3f ms | outside-GPU %.3f ms",
					   avg_gpu, avg_outside);
			} else {
				printf(" | GPU timestamps unavailable");
			}
			printf("\n");

			printf("    contribution/token: wall %.3f ms",
				   wall_per_token);
			if (b->gpu_timestamp_count) {
				printf(" | GPU %.3f ms | outside-GPU %.3f ms",
					   gpu_per_token, outside_per_token);
			}
			printf("\n");

			if (b->gpu_timestamp_count) {
				printf("    first GPUStartTime: %.6f s | last GPUEndTime: %.6f s\n",
					   b->first_gpu_start_s, b->last_gpu_end_s);
				if (first_gpu_start_s == 0.0 || b->first_gpu_start_s < first_gpu_start_s)
					first_gpu_start_s = b->first_gpu_start_s;
				if (b->last_gpu_end_s > last_gpu_end_s)
					last_gpu_end_s = b->last_gpu_end_s;
			}

			total_count += b->count;
			total_gpu_count += b->gpu_timestamp_count;
			total_wall_ms += b->commit_to_complete_ms;
			total_gpu_ms += b->gpu_duration_ms;
			total_outside_ms += b->outside_gpu_ms;
		}
	}

	if (total_count == 0) {
		printf("  SKIPPED — no decode-time fused CMD2 command buffers recorded\n");
		return;
	}

	double toks = g_cmd1_profile_tokens ? (double)g_cmd1_profile_tokens : 1.0;
	printf("  ----------------------------------------------------------------\n");
	printf("  all CMD2 production buffers: count=%llu, decode_tokens=%llu\n",
		   (unsigned long long)total_count,
		   (unsigned long long)g_cmd1_profile_tokens);
	printf("    commit->complete: %.3f ms/token\n", total_wall_ms / toks);
	if (total_gpu_count) {
		printf("    actual CMD2 GPU duration: %.3f ms/token\n", total_gpu_ms / toks);
		printf("    outside CMD2 GPU duration: %.3f ms/token\n", total_outside_ms / toks);
		printf("    GPU timestamp coverage: %llu/%llu command buffers\n",
			   (unsigned long long)total_gpu_count,
			   (unsigned long long)total_count);
		printf("    first GPUStartTime: %.6f s\n", first_gpu_start_s);
		printf("    last GPUEndTime:    %.6f s\n", last_gpu_end_s);
	}
	if (g_timing_enabled && g_timing.count > 0) {
		double reported_wait = g_timing.cmd2_wait / (double)g_timing.count *
			(g_cfg.num_layers > 0 ? g_cfg.num_layers : g_timing.count);
		printf("    existing cmd2_wait report: %.3f ms/token (includes post-wait readback)\n",
			   reported_wait);
	}
}

static void cmd1_profile_capture(MetalCtx *ctx, Cmd1ProfileSample *dst,
	const BatchMatvecSpec *s, const float *input) {
	if (!ctx || !dst || dst->valid || !s || !input || s->in_dim != 2048) return;
	const char *base = NULL;
	id<MTLBuffer> src = matvec_source_buffer(ctx, s->source, &base);
	if (!src || !base) return;
	dst->kind=s->kind; dst->source=s->source; dst->out_dim=s->out_dim; dst->in_dim=s->in_dim; dst->group_size=s->group_size;
	dst->weight_off=(size_t)((const char *)s->W-base);
	if (s->kind == MATVEC_KIND_MLX4) {
		if (s->source != MATVEC_SOURCE_WF || !s->scales || !s->biases) return;
		dst->scale_off=(size_t)((const char *)s->scales-base);
		dst->bias_off=(size_t)((const char *)s->biases-base);
	}
	memcpy(dst->input,input,2048*sizeof(float));
	dst->valid=1;
}

static void cmd1_profile_note_layer(MetalCtx *ctx, int layer_idx, int is_full,
	BatchMatvecSpec *specs, int num_specs, const float *input) {
	if (!g_cmd1_profile_enabled || !g_cmd1_profile_decode_active || !ctx || !specs || !input) return;
	if (layer_idx == 0) g_cmd1_profile_tokens++;
	int maxn = is_full ? 3 : 4;
	if (num_specs < maxn) maxn = num_specs;
	for (int i=0;i<maxn;i++) {
		int f = is_full ? CMD1_FULL_Q+i : CMD1_LINEAR_QKV+i;
		g_cmd1_sample[f].production_calls++;
		cmd1_profile_capture(ctx,&g_cmd1_sample[f],&specs[i],input);
	}
}

static int batch_spec_can_gpu(MetalCtx *ctx, const BatchMatvecSpec *spec) {
	if (!ctx) {
		return 0;
	}
	if (spec->kind == MATVEC_KIND_GGUF_Q8_0) {
		return (ctx->matvec_q8_0 != nil && matvec_source_buffer(ctx, spec->source, NULL) != nil);
	}
	return (ctx->wf_buf != nil);
}

static void gpu_q8_0_matvec(
	MetalCtx *ctx,
	id<MTLBuffer> w_buf,
	const char *w_base,
	const GGUFBlockQ8_0 *W_q8,
	const float *x_f32, float *out_f32,
	uint32_t out_dim, uint32_t in_dim
) {
	memcpy([ctx->buf_input contents], x_f32, in_dim * sizeof(float));

	size_t o_size = (size_t)out_dim * sizeof(float);
	id<MTLBuffer> o_buf = ctx->buf_output;
	if (o_size > [o_buf length]) {
		o_buf = [ctx->device newBufferWithLength:o_size options:MTLResourceStorageModeShared];
	}

	NSUInteger w_off = (NSUInteger)((const char *)W_q8 - w_base);

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
	[enc setComputePipelineState:ctx->matvec_q8_0];
	[enc setBuffer:w_buf                  offset:w_off atIndex:0];
	[enc setBuffer:ctx->buf_input         offset:0     atIndex:1];
	[enc setBuffer:o_buf                  offset:0     atIndex:2];
	[enc setBytes:&out_dim                length:4     atIndex:3];
	[enc setBytes:&in_dim                 length:4     atIndex:4];
	uint32_t num_tgs = (out_dim + 7) / 8;
	[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
		threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	[enc endEncoding];
	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];

	memcpy(out_f32, [o_buf contents], o_size);
}

static void fast_kind_matvec(
	const void *W, const void *scales, const void *biases, uint8_t kind, uint8_t source,
	const float *x, float *out,
	int out_dim, int in_dim, int group_size
) {
	if (kind == MATVEC_KIND_GGUF_Q8_0) {
		const char *w_base = NULL;
		id<MTLBuffer> w_buf = g_metal ? matvec_source_buffer(g_metal, source, &w_base) : nil;
		if (g_metal && g_metal->matvec_q8_0 && w_buf && w_base) {
			gpu_q8_0_matvec(g_metal, w_buf, w_base, (const GGUFBlockQ8_0 *)W, x, out,
							(uint32_t)out_dim, (uint32_t)in_dim);
		} else {
			cpu_q8_0_matvec((const GGUFBlockQ8_0 *)W, x, out, out_dim, in_dim);
		}
	} else {
		fast_dequant_matvec(W, scales, biases, x, out, out_dim, in_dim, group_size);
	}
}

static int batch_specs_have_q8(BatchMatvecSpec *specs, int num_specs) {
	for (int i = 0; i < num_specs; i++) {
		if (specs[i].kind == MATVEC_KIND_GGUF_Q8_0) {
			return 1;
		}
	}
	return 0;
}

// Run N matmuls in a single command buffer. All share the same input vector.
// The input is copied once; all outputs go to preallocated batch_out slots.
static void gpu_batch_matvec(
	MetalCtx *ctx,
	const float *x_f32, uint32_t x_dim,  // shared input
	BatchMatvecSpec *specs, int num_specs
) {
	// Capture one safe real production input for replay when this synchronous
	// path is used. x_f32 is CPU-owned and stable before the command buffer runs.
	if (g_tiny_matvec_telemetry_enabled && x_dim == 2048) {
		for (int i = 0; i < num_specs; i++) {
			BatchMatvecSpec *s = &specs[i];
			int shape = tiny_matvec_target_shape(s);
			if (shape == 32 && !tiny_replay_32x2048.valid)
				tiny_matvec_capture_sample(ctx, &tiny_replay_32x2048, s, x_f32, "beta/alpha");
			else if (shape == 1 && !tiny_replay_1x2048.valid)
				tiny_matvec_capture_sample(ctx, &tiny_replay_1x2048, s, x_f32, "shared_gate_score");
		}
	}

	// Copy input once
	memcpy([ctx->buf_input contents], x_f32, x_dim * sizeof(float));

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];

	for (int i = 0; i < num_specs; i++) {
		BatchMatvecSpec *s = &specs[i];
		id<MTLBuffer> o_buf = ctx->batch_out[s->batch_slot];
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		if (s->kind == MATVEC_KIND_GGUF_Q8_0) {
			const char *w_base = NULL;
			id<MTLBuffer> w_buf = matvec_source_buffer(ctx, s->source, &w_base);
			NSUInteger w_off = (NSUInteger)((const char *)s->W - w_base);
			[enc setComputePipelineState:ctx->matvec_q8_0];
			[enc setBuffer:w_buf         offset:w_off atIndex:0];
			[enc setBuffer:ctx->buf_input offset:0     atIndex:1];
			[enc setBuffer:o_buf          offset:0     atIndex:2];
			[enc setBytes:&s->out_dim     length:4     atIndex:3];
			[enc setBytes:&s->in_dim      length:4     atIndex:4];
			uint32_t num_tgs = (s->out_dim + 7) / 8;
			[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		} else {
			NSUInteger w_off = (NSUInteger)((const char *)s->W      - (const char *)[ctx->wf_buf contents]);
			NSUInteger s_off = (NSUInteger)((const char *)s->scales  - (const char *)[ctx->wf_buf contents]);
			NSUInteger b_off = (NSUInteger)((const char *)s->biases  - (const char *)[ctx->wf_buf contents]);
			int use_v3 = tiny_matvec_select_v3(s);
			tiny_matvec_count_production(s, use_v3);
			[enc setComputePipelineState: use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
			[enc setBuffer:ctx->wf_buf    offset:w_off atIndex:0];
			[enc setBuffer:ctx->wf_buf    offset:s_off atIndex:1];
			[enc setBuffer:ctx->wf_buf    offset:b_off atIndex:2];
			[enc setBuffer:ctx->buf_input offset:0     atIndex:3];
			[enc setBuffer:o_buf          offset:0     atIndex:4];
			[enc setBytes:&s->out_dim     length:4     atIndex:5];
			[enc setBytes:&s->in_dim      length:4     atIndex:6];
			[enc setBytes:&s->group_size  length:4     atIndex:7];
			if (use_v3) {
				uint32_t num_tgs = (s->out_dim + 7) / 8;
				[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			} else {
				[enc dispatchThreadgroups:MTLSizeMake(s->out_dim, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
			}
		}
		[enc endEncoding];
	}

	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];

	// Copy results back to CPU
	for (int i = 0; i < num_specs; i++) {
		BatchMatvecSpec *s = &specs[i];
		memcpy(s->out_cpu, [ctx->batch_out[s->batch_slot] contents],
			   s->out_dim * sizeof(float));
	}
}

// ============================================================================
// Encode-only variants: add dispatches to an EXISTING command buffer.
// These do NOT commit — the caller batches multiple encode calls into one
// command buffer and commits once, eliminating per-dispatch overhead.
// ============================================================================

// Encode N matmuls into cmdbuf. Input must already be in ctx->buf_input.
static void gpu_encode_batch_matvec(
	MetalCtx *ctx,
	id<MTLCommandBuffer> cmdbuf,
	BatchMatvecSpec *specs, int num_specs
) {
	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
	for (int i = 0; i < num_specs; i++) {
		BatchMatvecSpec *s = &specs[i];
		id<MTLBuffer> o_buf = ctx->batch_out[s->batch_slot];
		if (s->kind == MATVEC_KIND_GGUF_Q8_0) {
			const char *w_base = NULL;
			id<MTLBuffer> w_buf = matvec_source_buffer(ctx, s->source, &w_base);
			NSUInteger w_off = (NSUInteger)((const char *)s->W - w_base);
			[enc setComputePipelineState:ctx->matvec_q8_0];
			[enc setBuffer:w_buf         offset:w_off atIndex:0];
			[enc setBuffer:ctx->buf_input offset:0     atIndex:1];
			[enc setBuffer:o_buf          offset:0     atIndex:2];
			[enc setBytes:&s->out_dim     length:4     atIndex:3];
			[enc setBytes:&s->in_dim      length:4     atIndex:4];
			uint32_t num_tgs = (s->out_dim + 7) / 8;
			[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		} else {
			NSUInteger w_off = (NSUInteger)((const char *)s->W      - (const char *)[ctx->wf_buf contents]);
			NSUInteger s_off = (NSUInteger)((const char *)s->scales  - (const char *)[ctx->wf_buf contents]);
			NSUInteger b_off = (NSUInteger)((const char *)s->biases  - (const char *)[ctx->wf_buf contents]);
			int use_v3 = tiny_matvec_select_v3(s);
			tiny_matvec_count_production(s, use_v3);
			[enc setComputePipelineState: use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
			[enc setBuffer:ctx->wf_buf    offset:w_off atIndex:0];
			[enc setBuffer:ctx->wf_buf    offset:s_off atIndex:1];
			[enc setBuffer:ctx->wf_buf    offset:b_off atIndex:2];
			[enc setBuffer:ctx->buf_input offset:0     atIndex:3];
			[enc setBuffer:o_buf          offset:0     atIndex:4];
			[enc setBytes:&s->out_dim     length:4     atIndex:5];
			[enc setBytes:&s->in_dim      length:4     atIndex:6];
			[enc setBytes:&s->group_size  length:4     atIndex:7];
			if (use_v3) {
				uint32_t num_tgs = (s->out_dim + 7) / 8;
				[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			} else {
				[enc dispatchThreadgroups:MTLSizeMake(s->out_dim, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
			}
		}
	}
	[enc endEncoding];
}

// Copy batch results from GPU buffers back to CPU pointers.
static void gpu_flush_batch_results(MetalCtx *ctx, BatchMatvecSpec *specs, int num_specs) {
	for (int i = 0; i < num_specs; i++) {
		BatchMatvecSpec *s = &specs[i];
		memcpy(s->out_cpu, [ctx->batch_out[s->batch_slot] contents],
			   s->out_dim * sizeof(float));
	}
}

typedef struct {
	double v3_gpu_us;
	double fast_gpu_us;
	double v3_wall_us;
	double fast_wall_us;
	double paired_wall_us;
	int gpu_timestamps_valid;
	double max_abs_diff;
	double rms_diff;
} TinyReplayResult;

static void tiny_replay_encode_dispatch(
	MetalCtx *ctx,
	id<MTLComputeCommandEncoder> enc,
	const TinyMatvecReplaySample *s,
	int use_v3
) {
	[enc setComputePipelineState:use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
	[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->weight_off atIndex:0];
	[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->scale_off atIndex:1];
	[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->bias_off atIndex:2];
	[enc setBuffer:ctx->buf_input offset:0 atIndex:3];
	[enc setBuffer:ctx->buf_output offset:0 atIndex:4];
	[enc setBytes:&s->out_dim length:4 atIndex:5];
	[enc setBytes:&s->in_dim length:4 atIndex:6];
	[enc setBytes:&s->group_size length:4 atIndex:7];
	if (use_v3) {
		uint32_t num_tgs = (s->out_dim + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	} else {
		[enc dispatchThreadgroups:MTLSizeMake(s->out_dim, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
	}
}

static void tiny_replay_run_block(
	MetalCtx *ctx,
	const TinyMatvecReplaySample *s,
	int use_v3,
	int dispatches,
	double *wall_ms_per_dispatch,
	double *gpu_ms_per_dispatch
) {
	memcpy([ctx->buf_input contents], s->input, s->in_dim * sizeof(float));
	double wall_start = now_ms();
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];
	id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
	for (int d = 0; d < dispatches; d++) {
		tiny_replay_encode_dispatch(ctx, enc, s, use_v3);
	}
	[enc endEncoding];
	[cmd commit];
	[cmd waitUntilCompleted];
	double wall_ms = now_ms() - wall_start;
	double gpu_ms = (cmd.GPUStartTime > 0.0 && cmd.GPUEndTime >= cmd.GPUStartTime)
		? (cmd.GPUEndTime - cmd.GPUStartTime) * 1000.0 : 0.0;
	if (wall_ms_per_dispatch) *wall_ms_per_dispatch = wall_ms / dispatches;
	if (gpu_ms_per_dispatch) *gpu_ms_per_dispatch = gpu_ms / dispatches;
}

static int tiny_replay_measure_sample(
	MetalCtx *ctx,
	const TinyMatvecReplaySample *s,
	TinyReplayResult *r
) {
	if (!ctx || !s || !s->valid || !r) return 0;
	const int block_size = 64;
	const int warmup_blocks = 10;
	const int pairs = 100;

	double *v3_wall = calloc((size_t)pairs, sizeof(double));
	double *fast_wall = calloc((size_t)pairs, sizeof(double));
	double *v3_gpu = calloc((size_t)pairs, sizeof(double));
	double *fast_gpu = calloc((size_t)pairs, sizeof(double));
	double *paired_wall = calloc((size_t)pairs, sizeof(double));
	float *out_v3 = calloc((size_t)s->out_dim, sizeof(float));
	float *out_fast = calloc((size_t)s->out_dim, sizeof(float));
	if (!v3_wall || !fast_wall || !v3_gpu || !fast_gpu || !paired_wall ||
		!out_v3 || !out_fast) {
		free(v3_wall); free(fast_wall); free(v3_gpu); free(fast_gpu);
		free(paired_wall); free(out_v3); free(out_fast);
		return 0;
	}

	for (int w = 0; w < warmup_blocks; w++) {
		tiny_replay_run_block(ctx, s, 0, block_size, NULL, NULL);
		tiny_replay_run_block(ctx, s, 1, block_size, NULL, NULL);
	}

	int gpu_valid_count = 0;
	for (int p = 0; p < pairs; p++) {
		int first_v3 = ((p & 1) == 0);
		for (int order = 0; order < 2; order++) {
			int use_v3 = first_v3 ? (order == 0) : (order == 1);
			double wall_ms = 0.0, gpu_ms = 0.0;
			tiny_replay_run_block(ctx, s, use_v3, block_size, &wall_ms, &gpu_ms);
			if (gpu_ms > 0.0) gpu_valid_count++;
			if (use_v3) {
				v3_wall[p] = wall_ms;
				v3_gpu[p] = gpu_ms;
			} else {
				fast_wall[p] = wall_ms;
				fast_gpu[p] = gpu_ms;
			}
		}
		// Positive means fast was faster.
		paired_wall[p] = v3_wall[p] - fast_wall[p];
	}

	qsort(v3_wall, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
	qsort(fast_wall, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
	qsort(v3_gpu, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
	qsort(fast_gpu, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);
	qsort(paired_wall, (size_t)pairs, sizeof(double), matvec_bench_double_cmp);

	r->v3_wall_us = v3_wall[pairs / 2] * 1000.0;
	r->fast_wall_us = fast_wall[pairs / 2] * 1000.0;
	r->v3_gpu_us = v3_gpu[pairs / 2] * 1000.0;
	r->fast_gpu_us = fast_gpu[pairs / 2] * 1000.0;
	r->paired_wall_us = paired_wall[pairs / 2] * 1000.0;
	r->gpu_timestamps_valid = (gpu_valid_count == pairs * 2 &&
		r->v3_gpu_us > 0.0 && r->fast_gpu_us > 0.0);

	// One real-input correctness comparison.
	tiny_replay_run_block(ctx, s, 1, 1, NULL, NULL);
	memcpy(out_v3, [ctx->buf_output contents], s->out_dim * sizeof(float));
	tiny_replay_run_block(ctx, s, 0, 1, NULL, NULL);
	memcpy(out_fast, [ctx->buf_output contents], s->out_dim * sizeof(float));
	matvec_bench_compare(out_v3, out_fast, s->out_dim, &r->max_abs_diff, &r->rms_diff);

	free(v3_wall); free(fast_wall); free(v3_gpu); free(fast_gpu);
	free(paired_wall); free(out_v3); free(out_fast);
	return 1;
}

static void tiny_matvec_replay_benchmark(MetalCtx *ctx) {
	if (!ctx || !ctx->matvec_v3 || !ctx->matvec_fast) {
		printf("Production-replay benchmark: SKIPPED — Metal V3/fast pipelines unavailable\n");
		return;
	}

	printf("\nProduction-replay benchmark (real captured production tensors/inputs)\n");
	printf("  methodology: 10 warmup blocks, 100 measured pairs, 64 dispatches/block, alternating order\n");

	const TinyMatvecReplaySample *samples[2] = {
		&tiny_replay_32x2048,
		&tiny_replay_1x2048
	};
	const char *shape_names[2] = { "32x2048", "1x2048" };

	for (int i = 0; i < 2; i++) {
		const TinyMatvecReplaySample *s = samples[i];
		if (!s->valid) {
			printf("  %s: SKIPPED — no safe real production sample captured\n", shape_names[i]);
			continue;
		}

		TinyReplayResult r = {0};
		if (!tiny_replay_measure_sample(ctx, s, &r)) {
			printf("  %s (%s): SKIPPED — replay allocation/measurement failed\n",
				   shape_names[i], s->label);
			continue;
		}

		printf("  %s (%s):\n", shape_names[i], s->label);
		printf("    Kernel   GPU median us   Wall median us\n");
		if (r.gpu_timestamps_valid) {
			printf("    v3       %13.3f   %14.3f\n", r.v3_gpu_us, r.v3_wall_us);
			printf("    fast     %13.3f   %14.3f\n", r.fast_gpu_us, r.fast_wall_us);
			double gpu_delta = r.v3_gpu_us - r.fast_gpu_us;
			double gpu_pct = r.v3_gpu_us > 0.0 ? 100.0 * gpu_delta / r.v3_gpu_us : 0.0;
			printf("    GPU delta: %+8.3f us (%s %.2f%%)\n",
				   gpu_delta, gpu_delta >= 0.0 ? "fast faster by" : "V3 faster by", fabs(gpu_pct));
		} else {
			printf("    v3       %13s   %14.3f\n", "n/a", r.v3_wall_us);
			printf("    fast     %13s   %14.3f\n", "n/a", r.fast_wall_us);
			printf("    GPU timestamps unavailable/invalid; compare wall medians.\n");
		}
		double wall_pct = r.v3_wall_us > 0.0 ? 100.0 * r.paired_wall_us / r.v3_wall_us : 0.0;
		printf("    paired wall delta: %+8.3f us (%s %.2f%%)\n",
			   r.paired_wall_us,
			   r.paired_wall_us >= 0.0 ? "fast faster by" : "V3 faster by",
			   fabs(wall_pct));
		printf("    correctness: max_abs_diff=%.6g rms_diff=%.6g\n",
			   r.max_abs_diff, r.rms_diff);
	}
}

typedef struct { double gpu_us, wall_us; int gpu_valid; } Cmd1OneKernelResult;

static void cmd1_q8_block(MetalCtx *ctx, const Cmd1ProfileSample *s, int n, double *wall_ms, double *gpu_ms) {
	const char *base=NULL; id<MTLBuffer> wb=matvec_source_buffer(ctx,s->source,&base);
	if (!wb || !base) { if(wall_ms)*wall_ms=0; if(gpu_ms)*gpu_ms=0; return; }
	memcpy([ctx->buf_input contents],s->input,s->in_dim*sizeof(float));
	double t0=now_ms(); id<MTLCommandBuffer> cmd=[ctx->queue commandBuffer]; id<MTLComputeCommandEncoder> enc=[cmd computeCommandEncoder];
	for(int d=0;d<n;d++) {
		[enc setComputePipelineState:ctx->matvec_q8_0]; [enc setBuffer:wb offset:(NSUInteger)s->weight_off atIndex:0];
		[enc setBuffer:ctx->buf_input offset:0 atIndex:1]; [enc setBuffer:ctx->buf_output offset:0 atIndex:2];
		[enc setBytes:&s->out_dim length:4 atIndex:3]; [enc setBytes:&s->in_dim length:4 atIndex:4];
		uint32_t tg=(s->out_dim+7)/8; [enc dispatchThreadgroups:MTLSizeMake(tg,1,1) threadsPerThreadgroup:MTLSizeMake(256,1,1)];
	}
	[enc endEncoding]; [cmd commit]; [cmd waitUntilCompleted];
	double w=now_ms()-t0; double g=(cmd.GPUStartTime>0 && cmd.GPUEndTime>=cmd.GPUStartTime)?(cmd.GPUEndTime-cmd.GPUStartTime)*1000.0:0.0;
	if(wall_ms)*wall_ms=w/n; if(gpu_ms)*gpu_ms=g/n;
}

static int cmd1_q8_measure(MetalCtx *ctx,const Cmd1ProfileSample *s,Cmd1OneKernelResult *r) {
	if(!ctx || !ctx->matvec_q8_0 || !s || !s->valid || !r) return 0;
	const int N=64,W=10,B=100; double *wall=calloc(B,sizeof(double)),*gpu=calloc(B,sizeof(double)); if(!wall||!gpu){free(wall);free(gpu);return 0;}
	for(int i=0;i<W;i++) cmd1_q8_block(ctx,s,N,NULL,NULL); int valid=0;
	for(int i=0;i<B;i++){cmd1_q8_block(ctx,s,N,&wall[i],&gpu[i]);if(gpu[i]>0)valid++;}
	qsort(wall,B,sizeof(double),matvec_bench_double_cmp); qsort(gpu,B,sizeof(double),matvec_bench_double_cmp);
	r->wall_us=wall[B/2]*1000.0; r->gpu_us=gpu[B/2]*1000.0; r->gpu_valid=(valid==B && r->gpu_us>0); free(wall);free(gpu);return 1;
}

static void cmd1_profile_replay(MetalCtx *ctx) {
	if(!g_cmd1_profile_enabled) return;
	printf("\n[CMD1 production-replay profile]\n");
	printf("Decode tokens observed: %llu\n",(unsigned long long)g_cmd1_profile_tokens);
	printf("Methodology: real decode tensor/input; 10 warmup blocks; 64 dispatches/block; 100 measured blocks/pairs\n");
	double cur_sum=0,best_sum=0;
	for(int f=0;f<CMD1_FAMILY_COUNT;f++) {
		Cmd1ProfileSample *s=&g_cmd1_sample[f]; double cpt=g_cmd1_profile_tokens?(double)s->production_calls/g_cmd1_profile_tokens:0.0;
		printf("  %s: shape=%ux%u kind=%s calls=%llu (%.2f/token)\n",s->label,s->out_dim,s->in_dim,
			s->kind==MATVEC_KIND_GGUF_Q8_0?"Q8_0":"MLX4",(unsigned long long)s->production_calls,cpt);
		if(!s->valid){printf("    SKIPPED — no real decode sample captured\n");continue;}
		if(s->kind==MATVEC_KIND_MLX4) {
			TinyMatvecReplaySample tmp={0}; tmp.valid=1;tmp.out_dim=s->out_dim;tmp.in_dim=s->in_dim;tmp.group_size=s->group_size;
			tmp.weight_off=s->weight_off;tmp.scale_off=s->scale_off;tmp.bias_off=s->bias_off;memcpy(tmp.input,s->input,sizeof(tmp.input));
			TinyReplayResult r={0}; if(!tiny_replay_measure_sample(ctx,&tmp,&r)){printf("    SKIPPED — replay failed\n");continue;}
			int cur_v3=(s->in_dim<=4096); if(g_tiny_matvec_fast_enabled && s->out_dim==32 && s->in_dim==2048) cur_v3=0;
			double cur=cur_v3?r.v3_gpu_us:r.fast_gpu_us,best=fmin(r.v3_gpu_us,r.fast_gpu_us);
			printf("    V3 GPU %.3f us wall %.3f us | fast GPU %.3f us wall %.3f us\n",r.v3_gpu_us,r.v3_wall_us,r.fast_gpu_us,r.fast_wall_us);
			printf("    correctness max_abs=%.6g rms=%.6g\n",r.max_abs_diff,r.rms_diff);
			printf("    current=%s contribution=%.3f ms/token best=%.3f potential=%.3f ms/token\n",cur_v3?"V3":"fast",cur*cpt/1000.0,best*cpt/1000.0,(cur-best)*cpt/1000.0);
			cur_sum+=cur*cpt/1000.0;best_sum+=best*cpt/1000.0;
		} else {
			Cmd1OneKernelResult r={0}; if(!cmd1_q8_measure(ctx,s,&r)){printf("    SKIPPED — Q8 replay failed\n");continue;}
			if(r.gpu_valid){double c=r.gpu_us*cpt/1000.0;printf("    Q8 GPU %.3f us wall %.3f us contribution=%.3f ms/token\n",r.gpu_us,r.wall_us,c);cur_sum+=c;best_sum+=c;}
			else printf("    Q8 GPU timestamp unavailable; wall %.3f us\n",r.wall_us);
		}
	}
	printf("  replay-estimated projection subtotal: current %.3f ms/token best-known %.3f potential %.3f ms/token\n",cur_sum,best_sum,cur_sum-best_sum);
	printf("  Note: projection subtotal excludes attention/linear-attention kernels, encoder boundaries, and other CMD1 work.\n");
}


// Encode a single matvec reading from buf_expert_act into buf_expert_out,
// using weight pointers into the mmap'd weight file.
// Used for shared expert down_proj which reads from a different input than
// the attention projections.
static void gpu_encode_dequant_matvec_with_io_bufs(
	MetalCtx *ctx,
	id<MTLCommandBuffer> cmdbuf,
	const void *W, const void *scales, const void *biases,
	id<MTLBuffer> in_buf, id<MTLBuffer> out_buf,
	uint32_t out_dim, uint32_t in_dim, uint32_t group_size
) {
	NSUInteger w_off = (NSUInteger)((const char *)W      - (const char *)[ctx->wf_buf contents]);
	NSUInteger s_off = (NSUInteger)((const char *)scales  - (const char *)[ctx->wf_buf contents]);
	NSUInteger b_off = (NSUInteger)((const char *)biases  - (const char *)[ctx->wf_buf contents]);

	id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
	int use_v3 = (in_dim <= 4096);
	[enc setComputePipelineState: use_v3 ? ctx->matvec_v3 : ctx->matvec_fast];
	[enc setBuffer:ctx->wf_buf offset:w_off atIndex:0];
	[enc setBuffer:ctx->wf_buf offset:s_off atIndex:1];
	[enc setBuffer:ctx->wf_buf offset:b_off atIndex:2];
	[enc setBuffer:in_buf      offset:0     atIndex:3];
	[enc setBuffer:out_buf     offset:0     atIndex:4];
	[enc setBytes:&out_dim     length:4     atIndex:5];
	[enc setBytes:&in_dim      length:4     atIndex:6];
	[enc setBytes:&group_size  length:4     atIndex:7];

	if (use_v3) {
		uint32_t num_tgs = (out_dim + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
	} else {
		[enc dispatchThreadgroups:MTLSizeMake(out_dim, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
	}
	[enc endEncoding];
}

static inline id<MTLComputePipelineState> expert_pipe_for_projection(
	MetalCtx *ctx,
	ExpertQuantKind kind,
	ExpertProjectionKind proj_kind
) {
	if (proj_kind == EXPERT_PROJ_IQ3_XXS) return ctx->matvec_iq3_xxs;
	if (proj_kind == EXPERT_PROJ_IQ4_XS) return ctx->matvec_iq4_xs;
	if (proj_kind == EXPERT_PROJ_Q5_K) return ctx->matvec_q5_k;
	if (kind == EXPERT_QUANT_2BIT) return ctx->matvec_2bit;
	return ctx->matvec_v3;
}

static inline MTLSize expert_threads_per_threadgroup(ExpertProjectionKind proj_kind) {
	if (proj_kind == EXPERT_PROJ_IQ3_XXS ||
		proj_kind == EXPERT_PROJ_IQ4_XS ||
		proj_kind == EXPERT_PROJ_Q5_K) {
		return MTLSizeMake(64, 1, 1);
	}
	return MTLSizeMake(256, 1, 1);
}

static inline uint32_t expert_rows_per_threadgroup(ExpertProjectionKind proj_kind) {
	if (proj_kind == EXPERT_PROJ_IQ3_XXS) return 8;
	if (proj_kind == EXPERT_PROJ_IQ4_XS) return 4;
	if (proj_kind == EXPERT_PROJ_Q5_K)   return 2;
	return 8;
}

static inline NSUInteger expert_threadgroup_memory_length(ExpertProjectionKind proj_kind) {
	if (proj_kind == EXPERT_PROJ_IQ3_XXS) {
		return 256 * sizeof(uint32_t) + 128 * sizeof(uint8_t);
	}
	if (proj_kind == EXPERT_PROJ_IQ4_XS) {
		return 64 * sizeof(float);
	}
	return 0;
}

static inline void expert_dispatch_matvec(
	id<MTLComputeCommandEncoder> enc,
	ExpertProjectionKind proj_kind,
	uint32_t out_dim
) {
	uint32_t rows_per_tg = expert_rows_per_threadgroup(proj_kind);
	uint32_t num_threadgroups = (out_dim + rows_per_tg - 1) / rows_per_tg;
	NSUInteger tg_mem = expert_threadgroup_memory_length(proj_kind);
	if (tg_mem > 0) {
		[enc setThreadgroupMemoryLength:tg_mem atIndex:0];
	}
	[enc dispatchThreadgroups:MTLSizeMake(num_threadgroups, 1, 1)
		threadsPerThreadgroup:expert_threads_per_threadgroup(proj_kind)];
}

