// Batched expert encoding: encode K experts using 2 encoders per expert
// (gate+up fused, SwiGLU+down fused) + 2 for shared = K*2 + 2 encoders total.
// With K=4: 10 encoders (vs. old 4*K + 2 = 18 with per-operation encoding).
// Each expert gets its own encoder pair for GPU parallelism across experts.
// Within each encoder, gate+up (or SwiGLU+down) are serialized but share
// encoder creation overhead. Net win: fewer encoders, same parallelism.
static void gpu_encode_experts_batched(
	MetalCtx *ctx,
	id<MTLCommandBuffer> cmdbuf,
	int K,                       // number of experts to encode
	const int *valid,            // which experts are valid [MAX_K]
	id<MTLBuffer> __strong *expert_bufs,  // per-expert weight data buffers [MAX_K]
	int layer_idx,               // layer index (for tiered per-expert quant)
	const int *expert_indices,   // expert indices (for tiered per-expert quant)
	id<MTLBuffer> input_buf
) {
	// Default quant kind (used when not tiered, or for initial pipe selection)
	ExpertQuantKind quant_kind = active_expert_quant_kind();
	ExpertLayout layout = expert_layout_for_kind(quant_kind);
	id<MTLComputePipelineState> gate_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.gate_kind);
	id<MTLComputePipelineState> up_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.up_kind);
	id<MTLComputePipelineState> down_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.down_kind);

	uint32_t gate_up_out = MOE_INTERMEDIATE;
	uint32_t gate_up_in  = HIDDEN_DIM;
	uint32_t down_out    = HIDDEN_DIM;
	uint32_t down_in     = MOE_INTERMEDIATE;
	uint32_t gs          = GROUP_SIZE;
	uint32_t swiglu_tgs  = (gate_up_out + 255) / 256;

	// Per-expert: Encoder A (gate+up), Encoder B (SwiGLU+down)
	// Separate encoders per expert enables GPU parallelism across experts.
	// Within each encoder, operations serialize (gate then up, SwiGLU then down).
	for (int k = 0; k < K; k++) {
		if (!valid[k]) continue;

		// Per-expert quant override for tiered mode
		if (g_use_tiered && g_tiered_manifest && expert_indices) {
			ExpertQuantKind ek = tiered_expert_quant_kind(layer_idx, expert_indices[k]);
			if (ek != quant_kind) {
				layout = expert_layout_for_kind(ek);
				gate_pipe = expert_pipe_for_projection(ctx, ek, layout.gate_kind);
				up_pipe = expert_pipe_for_projection(ctx, ek, layout.up_kind);
				down_pipe = expert_pipe_for_projection(ctx, ek, layout.down_kind);
				quant_kind = ek;
			}
		}

		// Encoder A: gate_proj + up_proj (both read same input, write different outputs)
		{
			id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
			// gate_proj
			[enc setComputePipelineState:gate_pipe];
			[enc setBuffer:expert_bufs[k]                  offset:layout.gate_w_off  atIndex:0];
			[enc setBuffer:expert_bufs[k]                  offset:layout.gate_s_off  atIndex:1];
			[enc setBuffer:expert_bufs[k]                  offset:layout.gate_b_off  atIndex:2];
			[enc setBuffer:input_buf                         offset:0           atIndex:3];
			[enc setBuffer:ctx->buf_multi_expert_gate[k]   offset:0           atIndex:4];
			[enc setBytes:&gate_up_out length:4 atIndex:5];
			[enc setBytes:&gate_up_in  length:4 atIndex:6];
			[enc setBytes:&gs          length:4 atIndex:7];
			expert_dispatch_matvec(enc, layout.gate_kind, gate_up_out);
			// up_proj (same encoder, serialized after gate — shares encoder overhead)
			[enc setComputePipelineState:up_pipe];
			[enc setBuffer:expert_bufs[k]                  offset:layout.up_w_off  atIndex:0];
			[enc setBuffer:expert_bufs[k]                  offset:layout.up_s_off  atIndex:1];
			[enc setBuffer:expert_bufs[k]                  offset:layout.up_b_off  atIndex:2];
			[enc setBuffer:ctx->buf_multi_expert_up[k]     offset:0          atIndex:4];
			expert_dispatch_matvec(enc, layout.up_kind, gate_up_out);
			[enc endEncoding];
		}

		// Encoder B: SwiGLU + down_proj (SwiGLU depends on gate+up from Enc A)
		{
			id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
			// SwiGLU
			[enc setComputePipelineState:ctx->swiglu];
			[enc setBuffer:ctx->buf_multi_expert_gate[k] offset:0 atIndex:0];
			[enc setBuffer:ctx->buf_multi_expert_up[k]   offset:0 atIndex:1];
			[enc setBuffer:ctx->buf_multi_expert_act[k]  offset:0 atIndex:2];
			[enc setBytes:&gate_up_out length:4 atIndex:3];
			[enc dispatchThreadgroups:MTLSizeMake(swiglu_tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			// down_proj (same encoder, serialized after SwiGLU)
			[enc setComputePipelineState:down_pipe];
			[enc setBuffer:expert_bufs[k]                  offset:layout.down_w_off  atIndex:0];
			[enc setBuffer:expert_bufs[k]                  offset:layout.down_s_off  atIndex:1];
			[enc setBuffer:expert_bufs[k]                  offset:layout.down_b_off  atIndex:2];
			[enc setBuffer:ctx->buf_multi_expert_act[k]    offset:0           atIndex:3];
			[enc setBuffer:ctx->buf_multi_expert_out[k]    offset:0           atIndex:4];
			[enc setBytes:&down_out length:4 atIndex:5];
			[enc setBytes:&down_in  length:4 atIndex:6];
			[enc setBytes:&gs       length:4 atIndex:7];
			expert_dispatch_matvec(enc, layout.down_kind, down_out);
			[enc endEncoding];
		}
	}
}

// Encode one expert forward (gate+up+swiglu+down) into cmdbuf.
// Expert data must already be in buf_expert_data.
// Input must already be in buf_expert_input.
__attribute__((unused))
static void gpu_encode_expert_forward(
	MetalCtx *ctx,
	id<MTLCommandBuffer> cmdbuf
) {
	ExpertQuantKind quant_kind = active_expert_quant_kind();
	ExpertLayout layout = expert_layout_for_kind(quant_kind);
	id<MTLComputePipelineState> gate_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.gate_kind);
	id<MTLComputePipelineState> up_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.up_kind);
	id<MTLComputePipelineState> down_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.down_kind);

	uint32_t gate_up_out = MOE_INTERMEDIATE;
	uint32_t gate_up_in  = HIDDEN_DIM;
	uint32_t down_out    = HIDDEN_DIM;
	uint32_t down_in     = MOE_INTERMEDIATE;
	uint32_t gs          = GROUP_SIZE;

	// gate_proj
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:gate_pipe];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_input offset:0           atIndex:3];
		[enc setBuffer:ctx->buf_expert_gate  offset:0           atIndex:4];
		[enc setBytes:&gate_up_out length:4 atIndex:5];
		[enc setBytes:&gate_up_in  length:4 atIndex:6];
		[enc setBytes:&gs          length:4 atIndex:7];
		expert_dispatch_matvec(enc, layout.gate_kind, gate_up_out);
		[enc endEncoding];
	}
	// up_proj
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:up_pipe];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_input offset:0          atIndex:3];
		[enc setBuffer:ctx->buf_expert_up    offset:0          atIndex:4];
		[enc setBytes:&gate_up_out length:4 atIndex:5];
		[enc setBytes:&gate_up_in  length:4 atIndex:6];
		[enc setBytes:&gs          length:4 atIndex:7];
		expert_dispatch_matvec(enc, layout.up_kind, gate_up_out);
		[enc endEncoding];
	}
	// SwiGLU
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:ctx->swiglu];
		[enc setBuffer:ctx->buf_expert_gate offset:0 atIndex:0];
		[enc setBuffer:ctx->buf_expert_up   offset:0 atIndex:1];
		[enc setBuffer:ctx->buf_expert_act  offset:0 atIndex:2];
		[enc setBytes:&gate_up_out length:4 atIndex:3];
		uint32_t swiglu_tgs = (gate_up_out + 255) / 256;
		[enc dispatchThreadgroups:MTLSizeMake(swiglu_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		[enc endEncoding];
	}
	// down_proj
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:down_pipe];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_act  offset:0           atIndex:3];
		[enc setBuffer:ctx->buf_expert_out  offset:0           atIndex:4];
		[enc setBytes:&down_out length:4 atIndex:5];
		[enc setBytes:&down_in  length:4 atIndex:6];
		[enc setBytes:&gs       length:4 atIndex:7];
		expert_dispatch_matvec(enc, layout.down_kind, down_out);
		[enc endEncoding];
	}
}

// Batched wrapper: takes N matmul specs sharing the same input, dispatches
// via GPU batch if available, otherwise falls back to CPU.
static void fast_batch_matvec(
	const float *x, uint32_t x_dim,
	BatchMatvecSpec *specs, int num_specs
) {
	if (g_metal) {
		BatchMatvecSpec gpu_specs[8];
		int num_gpu_specs = 0;
		for (int i = 0; i < num_specs; i++) {
			BatchMatvecSpec *s = &specs[i];
			if (!batch_spec_can_gpu(g_metal, s)) {
				continue;
			}
			gpu_specs[num_gpu_specs++] = *s;
		}
		if (num_gpu_specs > 0) {
			gpu_batch_matvec(g_metal, x, x_dim, gpu_specs, num_gpu_specs);
		}
		for (int i = 0; i < num_specs; i++) {
			BatchMatvecSpec *s = &specs[i];
			if (batch_spec_can_gpu(g_metal, s)) {
				continue;
			}
			fast_kind_matvec(s->W, s->scales, s->biases, s->kind, s->source,
							 x, s->out_cpu,
							 (int)s->out_dim, (int)s->in_dim, (int)s->group_size);
		}
	} else {
		for (int i = 0; i < num_specs; i++) {
			BatchMatvecSpec *s = &specs[i];
			fast_kind_matvec(s->W, s->scales, s->biases, s->kind, s->source,
							 x, s->out_cpu,
							 (int)s->out_dim, (int)s->in_dim, (int)s->group_size);
		}
	}
}

// ============================================================================
// GPU expert forward: gate+up matvec -> SwiGLU -> down matvec
// All 3 matmuls + activation in a single command buffer submission.
// Expert data is copied into a reusable Metal buffer.
// ============================================================================

// expert_data_already_in_buffer: if true, expert data is already in buf_expert_data
//   (pread'd directly into it), skip the copy.
__attribute__((unused))
static void gpu_expert_forward(
	MetalCtx *ctx,
	const void *expert_data,     // EXPERT_SIZE bytes (may be buf_expert_data contents)
	const float *h_post,         // [HIDDEN_DIM] input
	float *expert_out,           // [HIDDEN_DIM] output
	int expert_data_already_in_buffer
) {
	ExpertQuantKind quant_kind = active_expert_quant_kind();
	ExpertLayout layout = expert_layout_for_kind(quant_kind);
	id<MTLComputePipelineState> gate_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.gate_kind);
	id<MTLComputePipelineState> up_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.up_kind);
	id<MTLComputePipelineState> down_pipe = expert_pipe_for_projection(ctx, quant_kind, layout.down_kind);

	// Copy expert weights into Metal buffer only if not already there
	if (!expert_data_already_in_buffer) {
		memcpy([ctx->buf_expert_data contents], expert_data, active_expert_size());
	}
	memcpy([ctx->buf_expert_input contents], h_post, HIDDEN_DIM * sizeof(float));

	uint32_t gate_up_out = MOE_INTERMEDIATE;  // 1024
	uint32_t gate_up_in  = HIDDEN_DIM;        // 4096
	uint32_t down_out    = HIDDEN_DIM;        // 4096
	uint32_t down_in     = MOE_INTERMEDIATE;  // 1024
	uint32_t gs          = GROUP_SIZE;        // 64

	// Build one command buffer with all 4 dispatches:
	// 1. gate_proj matvec (h_post -> gate_out)
	// 2. up_proj matvec (h_post -> up_out)
	// 3. SwiGLU (gate_out, up_out -> act_out)
	// 4. down_proj matvec (act_out -> expert_out)

	id<MTLCommandBuffer> cmdbuf = [ctx->queue commandBuffer];

	// --- Dispatch 1: gate_proj [4096] -> [1024] ---
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:gate_pipe];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.gate_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_input offset:0           atIndex:3];
		[enc setBuffer:ctx->buf_expert_gate  offset:0           atIndex:4];
		[enc setBytes:&gate_up_out length:4 atIndex:5];
		[enc setBytes:&gate_up_in  length:4 atIndex:6];
		[enc setBytes:&gs          length:4 atIndex:7];
		uint32_t num_tgs = (gate_up_out + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		[enc endEncoding];
	}

	// --- Dispatch 2: up_proj [4096] -> [1024] ---
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:up_pipe];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data  offset:layout.up_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_input offset:0          atIndex:3];
		[enc setBuffer:ctx->buf_expert_up    offset:0          atIndex:4];
		[enc setBytes:&gate_up_out length:4 atIndex:5];
		[enc setBytes:&gate_up_in  length:4 atIndex:6];
		[enc setBytes:&gs          length:4 atIndex:7];
		uint32_t num_tgs = (gate_up_out + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		[enc endEncoding];
	}

	// --- Dispatch 3: SwiGLU(gate, up) -> act ---
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:ctx->swiglu];
		[enc setBuffer:ctx->buf_expert_gate offset:0 atIndex:0];
		[enc setBuffer:ctx->buf_expert_up   offset:0 atIndex:1];
		[enc setBuffer:ctx->buf_expert_act  offset:0 atIndex:2];
		[enc setBytes:&gate_up_out length:4 atIndex:3];
		uint32_t swiglu_tgs = (gate_up_out + 255) / 256;
		[enc dispatchThreadgroups:MTLSizeMake(swiglu_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		[enc endEncoding];
	}

	// --- Dispatch 4: down_proj [1024] -> [4096] ---
	{
		id<MTLComputeCommandEncoder> enc = [cmdbuf computeCommandEncoder];
		[enc setComputePipelineState:down_pipe];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_w_off  atIndex:0];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_s_off  atIndex:1];
		[enc setBuffer:ctx->buf_expert_data offset:layout.down_b_off  atIndex:2];
		[enc setBuffer:ctx->buf_expert_act  offset:0           atIndex:3];
		[enc setBuffer:ctx->buf_expert_out  offset:0           atIndex:4];
		[enc setBytes:&down_out length:4 atIndex:5];
		[enc setBytes:&down_in  length:4 atIndex:6];
		[enc setBytes:&gs       length:4 atIndex:7];
		uint32_t num_tgs = (down_out + 7) / 8;
		[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
			threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
		[enc endEncoding];
	}

	[cmdbuf commit];
	[cmdbuf waitUntilCompleted];

	// Copy result back to CPU
	memcpy(expert_out, [ctx->buf_expert_out contents], HIDDEN_DIM * sizeof(float));
}

// ============================================================================
// Rotary position embedding (for full attention layers)
// ============================================================================

static void apply_rotary_emb(float *q, float *k, int pos, int num_heads, int num_kv_heads,
							  int head_dim, int rotary_dim) {
	// Apply RoPE to the first rotary_dim dimensions of each head
	// NON-TRADITIONAL (MLX default): pairs are (x[i], x[i + half_dim])
	// where half_dim = rotary_dim / 2
	int half = rotary_dim / 2;
	for (int h = 0; h < num_heads; h++) {
		float *qh = q + h * head_dim;
		for (int i = 0; i < half; i++) {
			float freq = 1.0f / powf(ROPE_THETA, (float)(2 * i) / rotary_dim);
			float angle = (float)pos * freq;
			float cos_a = cosf(angle);
			float sin_a = sinf(angle);

			float q0 = qh[i];
			float q1 = qh[i + half];
			qh[i]        = q0 * cos_a - q1 * sin_a;
			qh[i + half]  = q0 * sin_a + q1 * cos_a;
		}
	}
	for (int h = 0; h < num_kv_heads; h++) {
		float *kh = k + h * head_dim;
		for (int i = 0; i < half; i++) {
			float freq = 1.0f / powf(ROPE_THETA, (float)(2 * i) / rotary_dim);
			float angle = (float)pos * freq;
			float cos_a = cosf(angle);
			float sin_a = sinf(angle);

			float k0 = kh[i];
			float k1 = kh[i + half];
			kh[i]        = k0 * cos_a - k1 * sin_a;
			kh[i + half]  = k0 * sin_a + k1 * cos_a;
		}
	}
}

// ============================================================================
// KV Cache for full attention layers
// ============================================================================

typedef struct {
	float *k_cache;  // [max_seq, num_kv_heads * head_dim]
	float *v_cache;  // [max_seq, num_kv_heads * head_dim]
	int len;         // current number of cached entries
} KVCache;

static KVCache *kv_cache_new(void) {
	KVCache *c = calloc(1, sizeof(KVCache));
	if (!c) {
		fprintf(stderr, "ERROR: KVCache structure allocation failed\n");
		return NULL;
	}
	int seq = g_kv_seq_len;
	c->k_cache = calloc((size_t)seq * NUM_KV_HEADS * HEAD_DIM, sizeof(float));
	c->v_cache = calloc((size_t)seq * NUM_KV_HEADS * HEAD_DIM, sizeof(float));
	c->len = 0;
	if (!c->k_cache || !c->v_cache) {
		fprintf(stderr, "ERROR: KV cache alloc failed (seq=%d, %.1f MB each)\n",
				seq, (double)seq * NUM_KV_HEADS * HEAD_DIM * sizeof(float) / 1e6);
		free(c->k_cache);
		free(c->v_cache);
		free(c);
		return NULL;
	}
	return c;
}

static void kv_cache_free(KVCache *c) {
	if (c) {
		free(c->k_cache);
		free(c->v_cache);
		free(c);
	}
}

// ============================================================================
// Linear attention state (GatedDeltaNet recurrent state)
// ============================================================================

typedef struct {
	float *conv_state;  // [(kernel_size-1) * conv_dim] for conv1d
	float *ssm_state;   // [num_v_heads, head_v_dim, head_k_dim] recurrent state
} LinearAttnState;

static LinearAttnState *linear_attn_state_new(void) {
	LinearAttnState *s = calloc(1, sizeof(LinearAttnState));
	if (!s) {
		fprintf(stderr, "ERROR: LinearAttnState structure allocation failed\n");
		return NULL;
	}
	s->conv_state = calloc((CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM, sizeof(float));
	s->ssm_state = calloc(LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM, sizeof(float));
	if (!s->conv_state || !s->ssm_state) {
		fprintf(stderr, "ERROR: LinearAttnState buffer allocation failed\n");
		free(s->conv_state);
		free(s->ssm_state);
		free(s);
		return NULL;
	}
	return s;
}

static void linear_attn_state_free(LinearAttnState *s) {
	if (s) {
		free(s->conv_state);
		free(s->ssm_state);
		free(s);
	}
}


typedef struct {
    int valid;
    int pos;
    float *k_snapshot[MAX_LAYERS];
    float *v_snapshot[MAX_LAYERS];
    int kv_len[MAX_LAYERS];
    float *la_conv_snapshot[MAX_LAYERS];
    float *la_ssm_snapshot[MAX_LAYERS];
    void *gpu_delta_snapshot[48];
    void *gpu_conv_snapshot[48];
} ServeStateSnapshot;

#define TOOL_PREFIX_CACHE_SLOTS 5
#define TOOL_PREFIX_CACHE_MAX_TOKENS 8192
#define TOOL_PREFIX_CACHE_DEFAULT_MB 768
static size_t g_tool_prefix_cache_budget_bytes =
    (size_t)TOOL_PREFIX_CACHE_DEFAULT_MB * 1024 * 1024;

typedef struct {
    ServeStateSnapshot snapshot;
    uint64_t tool_sig;
    uint64_t token_sig;
    int token_count;
    uint64_t last_used;
    int pinned;
} ToolPrefixCacheEntry;

static int tool_prefix_cache_find(ToolPrefixCacheEntry cache[TOOL_PREFIX_CACHE_SLOTS],
                                  uint64_t tool_sig,
                                  uint64_t token_sig,
                                  int token_count) {
    for (int i = 0; i < TOOL_PREFIX_CACHE_SLOTS; i++) {
        if (cache[i].snapshot.valid &&
            cache[i].tool_sig == tool_sig &&
            cache[i].token_sig == token_sig &&
            cache[i].token_count == token_count) {
            return i;
        }
    }
    return -1;
}

static int tool_prefix_cache_choose_victim(
    ToolPrefixCacheEntry cache[TOOL_PREFIX_CACHE_SLOTS]) {
    // Prefer an unused slot.
    for (int i = 0; i < TOOL_PREFIX_CACHE_SLOTS; i++) {
        if (!cache[i].snapshot.valid && !cache[i].pinned) return i;
    }

    // Otherwise evict the least-recently-used non-pinned slot.
    int victim = -1;
    uint64_t oldest = UINT64_MAX;
    for (int i = 0; i < TOOL_PREFIX_CACHE_SLOTS; i++) {
        if (cache[i].pinned) continue;
        if (cache[i].last_used < oldest) {
            oldest = cache[i].last_used;
            victim = i;
        }
    }
    return victim;
}



static void serve_state_snapshot_free(ServeStateSnapshot *snap) {
    if (!snap) return;
    for (int i = 0; i < NUM_LAYERS; i++) {
        free(snap->k_snapshot[i]);
        free(snap->v_snapshot[i]);
        free(snap->la_conv_snapshot[i]);
        free(snap->la_ssm_snapshot[i]);
        snap->k_snapshot[i] = NULL;
        snap->v_snapshot[i] = NULL;
        snap->la_conv_snapshot[i] = NULL;
        snap->la_ssm_snapshot[i] = NULL;
        snap->kv_len[i] = 0;
    }
    for (int i = 0; i < 48; i++) {
        free(snap->gpu_delta_snapshot[i]);
        free(snap->gpu_conv_snapshot[i]);
        snap->gpu_delta_snapshot[i] = NULL;
        snap->gpu_conv_snapshot[i] = NULL;
    }
    snap->valid = 0;
    snap->pos = 0;
}

static int snapshot_uses_gpu_linear_state(void) {
    return gpu_linear_state_requested() &&
        g_metal && g_metal->delta_net_step;
}

static size_t tool_prefix_size_add(size_t total, size_t amount) {
    return amount > SIZE_MAX - total ? SIZE_MAX : total + amount;
}

static size_t serve_state_snapshot_bytes(const ServeStateSnapshot *snap) {
    size_t bytes = 0;
    const size_t kv_unit = (size_t)NUM_KV_HEADS * HEAD_DIM * sizeof(float);
    const size_t conv = (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float);
    const size_t ssm = LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float);
    for (int i = 0; i < NUM_LAYERS; i++) {
        if (snap->kv_len[i] > 0) {
            size_t section = (size_t)snap->kv_len[i] * kv_unit;
            if (snap->k_snapshot[i]) bytes = tool_prefix_size_add(bytes, section);
            if (snap->v_snapshot[i]) bytes = tool_prefix_size_add(bytes, section);
        }
        if (snap->la_conv_snapshot[i]) bytes = tool_prefix_size_add(bytes, conv);
        if (snap->la_ssm_snapshot[i]) bytes = tool_prefix_size_add(bytes, ssm);
    }
    for (int i = 0; i < 48; i++) {
        if (snap->gpu_delta_snapshot[i])
            bytes = tool_prefix_size_add(bytes, 64ULL * 128 * 128 * sizeof(float));
        if (snap->gpu_conv_snapshot[i])
            bytes = tool_prefix_size_add(bytes, 3ULL * 12288 * sizeof(float));
    }
    return bytes;
}

static size_t serve_state_snapshot_expected_bytes(KVCache **kv_caches,
                                                   void **layer_states) {
    size_t bytes = 0;
    const size_t kv_unit = (size_t)NUM_KV_HEADS * HEAD_DIM * sizeof(float);
    const size_t conv = (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float);
    const size_t ssm = LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float);
    for (int i = 0; i < NUM_LAYERS; i++) {
        if (kv_caches[i]) {
            int len = kv_caches[i]->len;
            if (len < 0 || len > g_kv_seq_len ||
                (size_t)len > SIZE_MAX / (2 * kv_unit)) return SIZE_MAX;
            bytes = tool_prefix_size_add(bytes, 2 * (size_t)len * kv_unit);
        }
        if (layer_states[i]) bytes = tool_prefix_size_add(bytes, conv + ssm);
    }
    if (snapshot_uses_gpu_linear_state()) {
        for (int i = 0; i < g_cfg.num_linear_layers && i < 48; i++) {
            if (g_metal->buf_delta_state[i])
                bytes = tool_prefix_size_add(bytes, 64ULL * 128 * 128 * sizeof(float));
            if (g_metal->buf_conv_state[i])
                bytes = tool_prefix_size_add(bytes, 3ULL * 12288 * sizeof(float));
        }
    }
    return bytes;
}

static size_t tool_prefix_dynamic_bytes(ToolPrefixCacheEntry cache[TOOL_PREFIX_CACHE_SLOTS]) {
    size_t bytes = 0;
    for (int i = 0; i < TOOL_PREFIX_CACHE_SLOTS; i++)
        if (!cache[i].pinned && cache[i].snapshot.valid)
            bytes = tool_prefix_size_add(bytes, serve_state_snapshot_bytes(&cache[i].snapshot));
    return bytes;
}

static int tool_prefix_cache_reserve(ToolPrefixCacheEntry cache[TOOL_PREFIX_CACHE_SLOTS],
                                     size_t expected_bytes, size_t budget_bytes) {
    if (expected_bytes == SIZE_MAX || expected_bytes > budget_bytes) return -1;
    int slot = tool_prefix_cache_choose_victim(cache);
    if (slot < 0) return -1;
    if (cache[slot].snapshot.valid) serve_state_snapshot_free(&cache[slot].snapshot);
    while (tool_prefix_dynamic_bytes(cache) > budget_bytes - expected_bytes) {
        int oldest = -1;
        uint64_t oldest_tick = UINT64_MAX;
        for (int i = 0; i < TOOL_PREFIX_CACHE_SLOTS; i++) {
            if (cache[i].pinned || !cache[i].snapshot.valid) continue;
            if (cache[i].last_used < oldest_tick) {
                oldest_tick = cache[i].last_used;
                oldest = i;
            }
        }
        if (oldest < 0) return -1;
        serve_state_snapshot_free(&cache[oldest].snapshot);
    }
    return slot;
}

static int serve_state_snapshot_capture(ServeStateSnapshot *snap,
                                        KVCache **kv_caches,
                                        void **layer_states,
                                        int pos) {
    if (!snap || !kv_caches || !layer_states || pos < 0) return 0;
    if (NUM_LAYERS > MAX_LAYERS) {
        fprintf(stderr, "[serve] ERROR: snapshot layer count %d exceeds MAX_LAYERS %d\n",
                NUM_LAYERS, MAX_LAYERS);
        return 0;
    }
    serve_state_snapshot_free(snap);

    const size_t kv_dim = (size_t)NUM_KV_HEADS * HEAD_DIM;
    const size_t conv_state_size =
        (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float);
    const size_t ssm_state_size =
        LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float);

    for (int i = 0; i < NUM_LAYERS; i++) {
        if (kv_caches[i]) {
            int len = kv_caches[i]->len;
            if (len < 0 || len > g_kv_seq_len) goto fail;
            snap->kv_len[i] = len;
            size_t sz = (size_t)len * kv_dim * sizeof(float);
            if (sz > 0) {
                snap->k_snapshot[i] = malloc(sz);
                snap->v_snapshot[i] = malloc(sz);
                if (!snap->k_snapshot[i] || !snap->v_snapshot[i]) goto fail;
                memcpy(snap->k_snapshot[i], kv_caches[i]->k_cache, sz);
                memcpy(snap->v_snapshot[i], kv_caches[i]->v_cache, sz);
            }
        }

        if (layer_states[i]) {
            LinearAttnState *la = (LinearAttnState *)layer_states[i];
            snap->la_conv_snapshot[i] = malloc(conv_state_size);
            snap->la_ssm_snapshot[i] = malloc(ssm_state_size);
            if (!snap->la_conv_snapshot[i] || !snap->la_ssm_snapshot[i]) goto fail;
            memcpy(snap->la_conv_snapshot[i], la->conv_state, conv_state_size);
            memcpy(snap->la_ssm_snapshot[i], la->ssm_state, ssm_state_size);
        }
    }

    if (snapshot_uses_gpu_linear_state()) {
        for (int i = 0; i < g_cfg.num_linear_layers && i < 48; i++) {
            if (g_metal->buf_delta_state[i]) {
                size_t sz = 64 * 128 * 128 * sizeof(float);
                snap->gpu_delta_snapshot[i] = malloc(sz);
                if (!snap->gpu_delta_snapshot[i]) goto fail;
                memcpy(snap->gpu_delta_snapshot[i],
                       [g_metal->buf_delta_state[i] contents], sz);
            }
            if (g_metal->buf_conv_state[i]) {
                size_t sz = 3 * 12288 * sizeof(float);
                snap->gpu_conv_snapshot[i] = malloc(sz);
                if (!snap->gpu_conv_snapshot[i]) goto fail;
                memcpy(snap->gpu_conv_snapshot[i],
                       [g_metal->buf_conv_state[i] contents], sz);
            }
        }
    }

    snap->pos = pos;
    snap->valid = 1;
    return 1;

fail:
    fprintf(stderr, "[serve] ERROR: tool-prefix snapshot allocation failed\n");
    serve_state_snapshot_free(snap);
    return 0;
}

static int serve_state_snapshot_restore(const ServeStateSnapshot *snap,
                                        KVCache **kv_caches,
                                        void **layer_states) {
    if (!snap || !snap->valid || !kv_caches || !layer_states) return 0;

    const size_t kv_dim = (size_t)NUM_KV_HEADS * HEAD_DIM;
    const size_t conv_state_size =
        (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float);
    const size_t ssm_state_size =
        LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float);

    for (int i = 0; i < NUM_LAYERS; i++) {
        if (kv_caches[i]) {
            int len = snap->kv_len[i];
            if (len < 0 || len > g_kv_seq_len) return 0;
            size_t sz = (size_t)len * kv_dim * sizeof(float);
            if (sz > 0) {
                if (!snap->k_snapshot[i] || !snap->v_snapshot[i]) return 0;
                memcpy(kv_caches[i]->k_cache, snap->k_snapshot[i], sz);
                memcpy(kv_caches[i]->v_cache, snap->v_snapshot[i], sz);
            }
            kv_caches[i]->len = len;

            if (g_metal) {
                int fa_idx = (i + 1) / FULL_ATTN_INTERVAL - 1;
                if (fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers) {
                    size_t gpu_tokens = (size_t)len;
                    if (gpu_tokens > GPU_KV_SEQ) gpu_tokens = GPU_KV_SEQ;
                    size_t gpu_sz = gpu_tokens * kv_dim * sizeof(float);
                    if (gpu_sz > 0) {
                        memcpy([g_metal->buf_kv_k[fa_idx] contents],
                               snap->k_snapshot[i], gpu_sz);
                        memcpy([g_metal->buf_kv_v[fa_idx] contents],
                               snap->v_snapshot[i], gpu_sz);
                    }
                }
            }
        }

        if (layer_states[i]) {
            if (!snap->la_conv_snapshot[i] || !snap->la_ssm_snapshot[i]) return 0;
            LinearAttnState *la = (LinearAttnState *)layer_states[i];
            memcpy(la->conv_state, snap->la_conv_snapshot[i], conv_state_size);
            memcpy(la->ssm_state, snap->la_ssm_snapshot[i], ssm_state_size);
        }
    }

    if (snapshot_uses_gpu_linear_state()) {
        for (int i = 0; i < g_cfg.num_linear_layers && i < 48; i++) {
            if (g_metal->buf_delta_state[i]) {
                if (!snap->gpu_delta_snapshot[i]) return 0;
                memcpy([g_metal->buf_delta_state[i] contents],
                       snap->gpu_delta_snapshot[i],
                       64 * 128 * 128 * sizeof(float));
            }
            if (g_metal->buf_conv_state[i]) {
                if (!snap->gpu_conv_snapshot[i]) return 0;
                memcpy([g_metal->buf_conv_state[i] contents],
                       snap->gpu_conv_snapshot[i],
                       3 * 12288 * sizeof(float));
            }
        }
    }
    return 1;
}

static int g_warm_state_zstd_enabled = 1;
#include "warm_state_cache.inc"

// Recover the path spelling used to invoke the executable without resolving
// symlinks.  Older warm identities included the absolute shaders.metal path, so
// moving/symlinking an otherwise identical tree can change compatibility even
// when the shader bytes are identical.  This is used only as a migration
// candidate; new checkpoints continue to use the current resolved identity.
static NSString *warm_state_invocation_shader_identity(void) {
    NSArray<NSString *> *args = [NSProcessInfo processInfo].arguments;
    if (args.count == 0) return nil;
    NSString *argv0 = args[0];
    if (argv0.length == 0) return nil;
    NSString *exe = argv0;
    if (![exe isAbsolutePath]) {
        NSString *cwd = [NSFileManager defaultManager].currentDirectoryPath;
        if (cwd.length == 0) return nil;
        exe = [cwd stringByAppendingPathComponent:exe];
    }
    exe = [exe stringByStandardizingPath];
    NSString *dir = [exe stringByDeletingLastPathComponent];
    if (dir.length == 0) return nil;
    return [dir stringByAppendingPathComponent:@"shaders.metal"];
}

// A legacy checkpoint is accepted only if its full former identity can be
// reproduced either from the previous shader path spelling or from a plausible
// pre-remount device ID; the normal loader then checks every independent
// header, prefix, size and payload invariant.
static int warm_state_migrate_legacy(NSString *legacy_path,
                                     ToolPrefixCacheEntry *entry,
                                     KVCache **kv_caches, void **layer_states,
                                     const char *weights, const char *manifest,
                                     const char *vocab, WeightFile *wf,
                                     int *layer_fds, int K,
                                     uint64_t source_hash, uint64_t profile_hash,
                                     const ToolPrefixCacheEntry *expected_prefix) {
    int fd = open(legacy_path.fileSystemRepresentation, O_RDONLY | O_NOFOLLOW);
    if (fd < 0) return 0;
    WarmStateHeader old = {0};
    struct stat st = {0}, weights_st = {0};
    int candidate_file = fstat(fd, &st) == 0 && S_ISREG(st.st_mode) &&
        warm_read_all(fd, &old, sizeof(old), NULL) &&
        memcmp(old.magic, "FWSTATE1", 8) == 0 &&
        old.version == WARM_STATE_VERSION &&
        old.header_bytes == sizeof(old) &&
        old.source_hash == source_hash && old.profile_hash == profile_hash &&
        expected_prefix && old.tool_sig == expected_prefix->tool_sig &&
        old.token_sig == expected_prefix->token_sig &&
        old.token_count == (uint32_t)expected_prefix->token_count &&
        stat(weights, &weights_st) == 0;
    close(fd);
    if (!candidate_file) return 0;

    // Path-relocation migration.  warm_hash_small_file historically included
    // the absolute path string as well as file content.  If the executable is
    // now reached through a symlink/Drive location, reproduce the old shader
    // identity using the invocation path while hashing the current shader
    // bytes.  An explicit environment override exists only for one-time
    // migration/testing when argv[0] cannot preserve the historical spelling.
    NSMutableArray<NSString *> *shader_identities = [NSMutableArray array];
    NSString *invocation_shader = warm_state_invocation_shader_identity();
    if (invocation_shader.length > 0)
        [shader_identities addObject:invocation_shader];
    const char *legacy_shader_env = getenv("FLASH_WARM_STATE_LEGACY_SHADER_PATH");
    if (legacy_shader_env && *legacy_shader_env) {
        NSString *env_shader = [NSString stringWithUTF8String:legacy_shader_env];
        if (env_shader.length > 0 && ![shader_identities containsObject:env_shader])
            [shader_identities addObject:env_shader];
    }
    NSString *resolved_shader = [infer_executable_directory()
        stringByAppendingPathComponent:@"shaders.metal"];
    for (NSString *shader_identity in shader_identities) {
        if (resolved_shader && [shader_identity isEqualToString:resolved_shader])
            continue;
        uint64_t relocated_hash = 0;
        if (!warm_state_compatibility_identity_ex(weights, manifest, vocab, wf,
                layer_fds, K, 0, 0, shader_identity.fileSystemRepresentation, 1,
                &relocated_hash) ||
            relocated_hash != old.compatibility)
            continue;
        if (!warm_state_load(legacy_path, entry, kv_caches, layer_states,
                relocated_hash, source_hash, profile_hash, expected_prefix))
            return 0;
        fprintf(stderr,
            "[warm-state] relocated shader identity validated (%s); migrating without recapture\n",
            shader_identity.fileSystemRepresentation);
        uint64_t current_hash = 0;
        if (!warm_state_compatibility(weights, manifest, vocab, wf,
                layer_fds, K, &current_hash) ||
            !warm_state_save_selected(legacy_path, entry, kv_caches,
                layer_states, current_hash, source_hash, profile_hash))
            fprintf(stderr,
                "[warm-state] WARNING: relocated state loaded, current-identity save failed\n");
        return 1;
    }

    const int custom_gguf_mapping_active = wf &&
        (wf->gguf_full_attn_json_path || wf->gguf_qkv_json_path ||
         wf->gguf_linear_json_path || wf->gguf_shared_json_path);

    // Pre-hardening GGUF mapping migration.  A checkpoint whose historical
    // identity predates mapping hashes cannot establish that today's custom
    // JSON mapping is the one that created its serialized state. Refuse that
    // migration when any custom mapping overlay is active; one recapture is safer.
    // Checkpoints created before
    // GGUF JSON manifests were added to the compatibility identity legitimately
    // lack those manifest hashes.  Reproduce that exact former identity first;
    // the normal loader still validates all checkpoint payload/header invariants,
    // then the state is re-saved under the current identity that *does* hash the
    // active mapping manifests.  This is a one-way compatibility migration, not
    // a relaxation of the current identity.
    if (!custom_gguf_mapping_active) {
    NSMutableArray<NSString *> *legacy_shader_candidates = [NSMutableArray array];
    if (resolved_shader.length > 0)
        [legacy_shader_candidates addObject:resolved_shader];
    for (NSString *candidate in shader_identities) {
        if (candidate.length > 0 &&
            ![legacy_shader_candidates containsObject:candidate])
            [legacy_shader_candidates addObject:candidate];
    }
    for (NSString *shader_identity in legacy_shader_candidates) {
        uint64_t pre_json_hash = 0;
        if (!warm_state_compatibility_identity_ex(weights, manifest, vocab, wf,
                layer_fds, K, 0, 0, shader_identity.fileSystemRepresentation, 0,
                &pre_json_hash))
            continue;
        fprintf(stderr,
            "[warm-state] compatibility candidate pre-gguf-json shader=%s hash=%016llx stored=%016llx\n",
            shader_identity.fileSystemRepresentation,
            (unsigned long long)pre_json_hash,
            (unsigned long long)old.compatibility);
        if (pre_json_hash != old.compatibility)
            continue;
        if (!warm_state_load(legacy_path, entry, kv_caches, layer_states,
                pre_json_hash, source_hash, profile_hash, expected_prefix))
            return 0;
        fprintf(stderr,
            "[warm-state] pre-GGUF-JSON identity validated (%s); migrating without recapture\n",
            shader_identity.fileSystemRepresentation);
        uint64_t current_hash = 0;
        if (!warm_state_compatibility(weights, manifest, vocab, wf,
                layer_fds, K, &current_hash) ||
            !warm_state_save_selected(legacy_path, entry, kv_caches,
                layer_states, current_hash, source_hash, profile_hash))
            fprintf(stderr,
                "[warm-state] WARNING: pre-GGUF-JSON state loaded, current-identity save failed\n");
        return 1;
    }

    } else {
        fprintf(stderr,
            "[warm-state] skipping pre-GGUF-JSON migration because custom mapping JSON is active\n");
    }

    uint64_t current_dev = (uint64_t)weights_st.st_dev;
    for (int distance = 0; distance <= 64; distance++) {
        for (int sign = 1; sign >= -1; sign -= 2) {
            if (distance == 0 && sign < 0) continue;
            if (sign < 0 && current_dev < (uint64_t)distance) continue;
            uint64_t device = sign > 0 ? current_dev + (uint64_t)distance
                                       : current_dev - (uint64_t)distance;
            uint64_t legacy_hash = 0;
            int legacy_match = warm_state_compatibility_identity_ex(
                    weights, manifest, vocab, wf, layer_fds, K,
                    1, device, NULL, 1, &legacy_hash) &&
                legacy_hash == old.compatibility;
            if (!legacy_match && !custom_gguf_mapping_active) {
                legacy_match = warm_state_compatibility_identity_ex(
                        weights, manifest, vocab, wf, layer_fds, K,
                        1, device, NULL, 0, &legacy_hash) &&
                    legacy_hash == old.compatibility;
            }
            if (!legacy_match) continue;
            if (!warm_state_load(legacy_path, entry, kv_caches, layer_states,
                    legacy_hash, source_hash, profile_hash, expected_prefix))
                return 0;
            fprintf(stderr,
                "[warm-state] legacy identity validated with device=%llu; migrating without changing source\n",
                (unsigned long long)device);
            uint64_t current_hash = 0;
            if (!warm_state_compatibility(weights, manifest, vocab, wf,
                    layer_fds, K, &current_hash) ||
                !warm_state_save_selected(legacy_path, entry, kv_caches,
                    layer_states, current_hash, source_hash, profile_hash))
                fprintf(stderr,
                    "[warm-state] WARNING: legacy state loaded, new identity checkpoint save failed\n");
            return 1;
        }
    }
    fprintf(stderr,
        "[warm-state] legacy identity mismatch; checkpoint remains untouched\n");
    return 0;
}

// ============================================================================
// Full attention layer forward (single token, incremental)
// ============================================================================

static int fa_debug_count = 0;

static float vec_rms(const float *v, int n) {
	float sum = 0.0f;
	for (int i = 0; i < n; i++) sum += v[i] * v[i];
	return sqrtf(sum / n);
}

static float vec_cosine(const float *a, const float *b, int n) {
	double dot = 0.0;
	double aa = 0.0;
	double bb = 0.0;
	for (int i = 0; i < n; i++) {
		dot += (double)a[i] * (double)b[i];
		aa += (double)a[i] * (double)a[i];
		bb += (double)b[i] * (double)b[i];
	}
	if (aa <= 0.0 || bb <= 0.0) return 0.0f;
	return (float)(dot / (sqrt(aa) * sqrt(bb)));
}

static float vec_max_abs_diff(const float *a, const float *b, int n, int *idx_out) {
	float max_diff = 0.0f;
	int max_idx = -1;
	for (int i = 0; i < n; i++) {
		float diff = fabsf(a[i] - b[i]);
		if (diff > max_diff) {
			max_diff = diff;
			max_idx = i;
		}
	}
	if (idx_out) *idx_out = max_idx;
	return max_diff;
}

static int full_attn_o_debug_enabled(void) {
	static int init = 0;
	static int enabled = 0;
	if (!init) {
		const char *env = getenv("FLASH_MOE_DEBUG_FULL_ATTN_O");
		enabled = (env && atoi(env) != 0);
		init = 1;
	}
	return enabled;
}

static int full_attn_o_debug_target_layer(void) {
	static int init = 0;
	static int target = 3;
	if (!init) {
		const char *env = getenv("FLASH_MOE_DEBUG_FULL_ATTN_LAYER");
		if (env && *env) target = atoi(env);
		init = 1;
	}
	return target;
}

