// ============================================================================
// Persistent I/O Thread Pool — eliminates pthread_create/join per layer
// ============================================================================

typedef struct {
	pthread_t threads[NUM_IO_THREADS];
	pthread_mutex_t mutex;
	pthread_cond_t work_ready;
	pthread_cond_t work_done;
	InferPreadTask *tasks;
	int num_tasks;
	int tasks_completed;
	int next_task;
	int tasks_done;
	int generation;          // incremented each dispatch — workers wait for new gen
	int completed_generation;
	volatile int shutdown;
} IOThreadPool;

static IOThreadPool g_io_pool;
static int g_io_pool_initialized = 0;
static int g_io_pool_thread_count = 0;

static void *io_pool_worker(void *arg) {
    (void)arg;
    int my_gen = 0;

    pthread_mutex_lock(&g_io_pool.mutex);

    while (1) {
        while (g_io_pool.generation == my_gen && !g_io_pool.shutdown)
            pthread_cond_wait(&g_io_pool.work_ready, &g_io_pool.mutex);

        if (g_io_pool.shutdown)
            break;

        my_gen = g_io_pool.generation;
        pthread_mutex_unlock(&g_io_pool.mutex);

        for (;;) {
            pthread_mutex_lock(&g_io_pool.mutex);

            if (g_io_pool.generation != my_gen ||
                g_io_pool.next_task >= g_io_pool.num_tasks) {
                break;
            }

            int task_idx = g_io_pool.next_task++;
            InferPreadTask *t = &g_io_pool.tasks[task_idx];

            pthread_mutex_unlock(&g_io_pool.mutex);

            const int profile_io_task =
                g_pipeline_profile_enabled && g_pipeline_profile_decode_active;
            if (profile_io_task)
                t->profile_start_ms = now_ms();

            if (t->lz4_comp_buf && t->lz4_comp_size > 0) {
                if ((size_t)t->lz4_comp_size > t->lz4_comp_capacity || t->offset < 0) {
                    t->result = -1;
                    t->error_no = EINVAL;
                } else {
                    errno = 0;
                    ssize_t nr = pread(t->fd, t->lz4_comp_buf, t->lz4_comp_size, t->offset);
                    t->error_no = (nr < 0) ? errno : 0;
                    if (nr == (ssize_t)t->lz4_comp_size) {
                        size_t dec = compression_decode_buffer(
                            t->dst, t->size, t->lz4_comp_buf, t->lz4_comp_size,
                            NULL, COMPRESSION_LZ4);
                        t->result = (ssize_t)dec;
                    } else {
                        t->result = -1;
                    }
                }
            } else if (t->mmap_base) {
                if (t->offset < 0 ||
                    (uint64_t)t->offset > (uint64_t)t->mmap_size ||
                    t->size > t->mmap_size - (size_t)t->offset) {
                    t->result = -1;
                    t->error_no = EINVAL;
                } else {
                    memcpy(t->dst, (const char *)t->mmap_base + t->offset, t->size);
                    t->result = (ssize_t)t->size;
                    t->error_no = 0;
                }
            } else {
                errno = 0;
                t->result = pread(t->fd, t->dst, t->size, t->offset);
                t->error_no = (t->result < 0) ? errno : 0;
            }

            if (profile_io_task)
                t->profile_end_ms = now_ms();

            pthread_mutex_lock(&g_io_pool.mutex);

            g_io_pool.tasks_done++;

            if (g_io_pool.tasks_done == g_io_pool.num_tasks) {
                g_io_pool.completed_generation = my_gen;
                pthread_cond_signal(&g_io_pool.work_done);
            }

            pthread_mutex_unlock(&g_io_pool.mutex);
        }

        /*
         * IMPORTANT:
         * The inner-loop break occurs while mutex is still locked.
         * The outer loop expects to own it before pthread_cond_wait().
         */
    }

    pthread_mutex_unlock(&g_io_pool.mutex);
    return NULL;
}

static int io_pool_init(void) {
	if (g_io_pool_initialized) return 1;

	int rc = pthread_mutex_init(&g_io_pool.mutex, NULL);
	if (rc != 0) {
		fprintf(stderr, "ERROR: pthread_mutex_init(io_pool) failed: %s\n", strerror(rc));
		return 0;
	}
	rc = pthread_cond_init(&g_io_pool.work_ready, NULL);
	if (rc != 0) {
		fprintf(stderr, "ERROR: pthread_cond_init(io_pool work_ready) failed: %s\n", strerror(rc));
		pthread_mutex_destroy(&g_io_pool.mutex);
		return 0;
	}
	rc = pthread_cond_init(&g_io_pool.work_done, NULL);
	if (rc != 0) {
		fprintf(stderr, "ERROR: pthread_cond_init(io_pool work_done) failed: %s\n", strerror(rc));
		pthread_cond_destroy(&g_io_pool.work_ready);
		pthread_mutex_destroy(&g_io_pool.mutex);
		return 0;
	}

	g_io_pool.shutdown = 0;
	g_io_pool.generation = 0;
	g_io_pool.completed_generation = 0;
	g_io_pool.tasks = NULL;
	g_io_pool_thread_count = 0;

	for (int i = 0; i < NUM_IO_THREADS; i++) {
		rc = pthread_create(&g_io_pool.threads[i], NULL, io_pool_worker,
			(void*)(intptr_t)i);
		if (rc != 0) {
			fprintf(stderr,
				"ERROR: pthread_create(io_pool worker %d/%d) failed: %s\n",
				i + 1, NUM_IO_THREADS, strerror(rc));

			pthread_mutex_lock(&g_io_pool.mutex);
			g_io_pool.shutdown = 1;
			pthread_cond_broadcast(&g_io_pool.work_ready);
			pthread_mutex_unlock(&g_io_pool.mutex);

			for (int j = 0; j < g_io_pool_thread_count; j++)
				pthread_join(g_io_pool.threads[j], NULL);

			pthread_cond_destroy(&g_io_pool.work_done);
			pthread_cond_destroy(&g_io_pool.work_ready);
			pthread_mutex_destroy(&g_io_pool.mutex);
			g_io_pool_thread_count = 0;
			return 0;
		}
		g_io_pool_thread_count++;
	}

	g_io_pool_initialized = 1;
	return 1;
}

static dispatch_queue_t g_io_gcd_queue = NULL;

static int io_pool_start(InferPreadTask *tasks, int num_tasks) {
    if (num_tasks == 0)
        return 0;

    pthread_mutex_lock(&g_io_pool.mutex);

    g_io_pool.tasks = tasks;
    g_io_pool.num_tasks = num_tasks;
    g_io_pool.tasks_completed = 0;
    g_io_pool.next_task = 0;
    g_io_pool.tasks_done = 0;

    if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active) {
        double dispatch_ms = now_ms();
        for (int i = 0; i < num_tasks; i++) {
            tasks[i].profile_dispatch_ms = dispatch_ms;
            tasks[i].profile_start_ms = 0.0;
            tasks[i].profile_end_ms = 0.0;
        }
    }

    g_io_pool.generation++;
    int my_gen = g_io_pool.generation;

    int wake =
        num_tasks < NUM_IO_THREADS ? num_tasks : NUM_IO_THREADS;

    for (int i = 0; i < wake; i++)
        pthread_cond_signal(&g_io_pool.work_ready);

    pthread_mutex_unlock(&g_io_pool.mutex);

    return my_gen;
}

static void io_pool_wait_generation(int target_gen) {
	if (target_gen <= 0) return;
	pthread_mutex_lock(&g_io_pool.mutex);
	while (g_io_pool.completed_generation < target_gen) {
		pthread_cond_wait(&g_io_pool.work_done, &g_io_pool.mutex);
	}
	InferPreadTask *profile_tasks = g_io_pool.tasks;
	int profile_num_tasks = g_io_pool.num_tasks;
	pthread_mutex_unlock(&g_io_pool.mutex);

	if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active &&
		profile_tasks && profile_num_tasks > 0) {
		double batch_first = 0.0, batch_last = 0.0;
		g_pipeline_profile.io_batches++;
		for (int i = 0; i < profile_num_tasks; i++) {
			InferPreadTask *t = &profile_tasks[i];
			g_pipeline_profile.io_tasks++;
			g_pipeline_profile.io_bytes += t->size;
			if (t->profile_start_ms > 0.0 && t->profile_end_ms >= t->profile_start_ms) {
				g_pipeline_profile.io_timed_tasks++;
				if (t->profile_dispatch_ms > 0.0 && t->profile_start_ms >= t->profile_dispatch_ms)
					g_pipeline_profile.io_queue_delay_ms += t->profile_start_ms - t->profile_dispatch_ms;
				g_pipeline_profile.io_service_ms += t->profile_end_ms - t->profile_start_ms;
				if (batch_first == 0.0 || t->profile_start_ms < batch_first) batch_first = t->profile_start_ms;
				if (t->profile_end_ms > batch_last) batch_last = t->profile_end_ms;
			}
		}
		if (batch_first > 0.0 && batch_last >= batch_first)
			g_pipeline_profile.io_batch_span_ms += batch_last - batch_first;
	}
}

static void io_pool_dispatch(InferPreadTask *tasks, int num_tasks) {
	if (num_tasks == 0) return;
	int my_gen = io_pool_start(tasks, num_tasks);
	io_pool_wait_generation(my_gen);
}

// ---- Async expert pread pipeline ----
// Starts pread on background pool threads immediately after routing.
// The pread overlaps with shared expert prep + next layer's CMD1+attn+CMD2.
// Wait for completion right before CMD3 needs the expert data.
#define MAX_CACHE_IO_SPLIT 8

static inline int active_cache_io_split(size_t esz) {
	int chunks = g_cache_io_split;
	if (chunks < 1) chunks = 1;
	if (chunks > MAX_CACHE_IO_SPLIT) chunks = MAX_CACHE_IO_SPLIT;

	// Expert blobs are page-cache-backed. Keep chunk boundaries page aligned
	// so fanout mode still matches the underlying VM layout.
	const size_t page_bytes = 16 * 1024;
	if (esz == 0 || (esz % page_bytes) != 0) return 1;

	size_t pages = esz / page_bytes;
	if ((size_t)chunks > pages) chunks = (int)pages;
	if (chunks < 1) chunks = 1;
	return chunks;
}

typedef struct {
	InferPreadTask tasks[MAX_K * MAX_CACHE_IO_SPLIT];
	int num_tasks;
	int num_experts;
	int chunks_per_expert;
	int generation;
	int valid[MAX_K];
	int active;
} AsyncPreadState;
static AsyncPreadState g_async_pread = {0};

static void async_pread_start(int packed_fd, int *expert_indices, int K,
							   id<MTLBuffer> __strong *dst_bufs, const void *mmap_base,
							   int layer_idx) {
	size_t esz = active_expert_size();
	int chunks = active_cache_io_split(esz);
	const size_t page_bytes = 16 * 1024;

	g_async_pread.num_experts = K;
	g_async_pread.chunks_per_expert = chunks;
	g_async_pread.num_tasks = K * chunks;
	g_async_pread.active = 1;

	for (int k = 0; k < K; k++) {
		// Per-expert offset and size (tiered: variable, uniform: computed from index)
		size_t this_esz;
		off_t this_offset;
		if (g_use_tiered && g_tiered_manifest) {
			TieredExpertInfo *ti = &TIERED(layer_idx, expert_indices[k]);
			this_esz = ti->size;
			this_offset = (off_t)ti->offset;
		} else {
			this_esz = esz;
			this_offset = (off_t)expert_indices[k] * esz;
		}

		size_t total_pages = (chunks > 1) ? (this_esz / page_bytes) : 0;
		char *dst_base = (char *)[dst_bufs[k] contents];
		size_t page_cursor = 0;
		for (int c = 0; c < chunks; c++) {
			size_t chunk_off = 0;
			size_t chunk_sz = this_esz;
			if (chunks > 1) {
				size_t pages_this_chunk = total_pages / (size_t)chunks;
				if ((size_t)c < (total_pages % (size_t)chunks)) pages_this_chunk++;
				chunk_off = page_cursor * page_bytes;
				chunk_sz = pages_this_chunk * page_bytes;
				if (c == chunks - 1) chunk_sz = this_esz - chunk_off;
				page_cursor += pages_this_chunk;
			}

			int task_idx = k * chunks + c;
			g_async_pread.tasks[task_idx].fd = expert_pick_fd(layer_idx, expert_indices[k], packed_fd);
			g_async_pread.tasks[task_idx].dst = dst_base + chunk_off;
			g_async_pread.tasks[task_idx].offset = this_offset + (off_t)chunk_off;
			g_async_pread.tasks[task_idx].size = chunk_sz;
			g_async_pread.tasks[task_idx].result = 0;
			if (mmap_base && g_async_pread.tasks[task_idx].fd == packed_fd) {
				g_async_pread.tasks[task_idx].mmap_base = mmap_base;
				g_async_pread.tasks[task_idx].mmap_size = g_layer_mmap_sizes[layer_idx];
			} else {
				g_async_pread.tasks[task_idx].mmap_base = NULL;
				g_async_pread.tasks[task_idx].mmap_size = 0;
			}
			g_async_pread.tasks[task_idx].lz4_comp_buf = NULL;
			g_async_pread.tasks[task_idx].lz4_comp_size = 0;
			g_async_pread.tasks[task_idx].lz4_comp_capacity = 0;
		}
	}

	// Fire off async preads on the persistent pool — returns immediately.
	g_async_pread.generation = io_pool_start(g_async_pread.tasks, g_async_pread.num_tasks);
}

static void async_pread_wait(void) {
	if (!g_async_pread.active) return;

	io_pool_wait_generation(g_async_pread.generation);

	for (int k = 0; k < g_async_pread.num_experts; k++) {
		ssize_t total = 0;
		size_t expected = 0;
		int failed = 0;

		for (int c = 0; c < g_async_pread.chunks_per_expert; c++) {
			int task_idx =
				k * g_async_pread.chunks_per_expert + c;

			InferPreadTask *task =
				&g_async_pread.tasks[task_idx];

			expected += task->size;

			if (task->result < 0) {
				failed = 1;
			} else {
				total += task->result;
			}
		}

		g_async_pread.valid[k] =
			(!failed && total == (ssize_t)expected);

		if (!g_async_pread.valid[k]) {
			int error_no = 0;
			for (int c = 0; c < g_async_pread.chunks_per_expert; c++) {
				InferPreadTask *task = &g_async_pread.tasks[k * g_async_pread.chunks_per_expert + c];
				if (task->result < 0) { error_no = task->error_no; break; }
			}
			if (error_no)
				fprintf(stderr, "WARNING: async pread expert slot %d: %zd/%zu bytes (errno %d: %s)\n",
					k, total, expected, error_no, strerror(error_no));
			else
				fprintf(stderr, "WARNING: async pread expert slot %d: %zd/%zu bytes\n",
					k, total, expected);
		}
	}

	g_async_pread.active = 0;
}

static void io_pool_shutdown(void) {
	if (!g_io_pool_initialized) return;
	pthread_mutex_lock(&g_io_pool.mutex);
	g_io_pool.shutdown = 1;
	pthread_cond_broadcast(&g_io_pool.work_ready);
	pthread_mutex_unlock(&g_io_pool.mutex);
	for (int i = 0; i < g_io_pool_thread_count; i++)
		pthread_join(g_io_pool.threads[i], NULL);
	g_io_pool_thread_count = 0;
	pthread_mutex_destroy(&g_io_pool.mutex);
	pthread_cond_destroy(&g_io_pool.work_ready);
	pthread_cond_destroy(&g_io_pool.work_done);
	g_io_pool_initialized = 0;
}

