	g_prefetch = calloc(1, sizeof(InferPrefetchCtx));
	pthread_mutex_init(&g_prefetch->mutex, NULL);
	pthread_cond_init(&g_prefetch->cond, NULL);
	g_prefetch->shutdown = 0;
	pthread_create(&g_prefetch_tid, NULL, infer_prefetch_thread_fn, g_prefetch);
}
#endif

// NOT CURRENTLY USED:
// This helper is not referenced by the current inference path and is disabled
// because it generates an -Wunused-function compiler warning.
#if 0
static void infer_prefetch_shutdown(void) {
	if (!g_prefetch) return;
	pthread_mutex_lock(&g_prefetch->mutex);
	g_prefetch->shutdown = 1;
	pthread_cond_signal(&g_prefetch->cond);
	pthread_mutex_unlock(&g_prefetch->mutex);
	pthread_join(g_prefetch_tid, NULL);
	pthread_mutex_destroy(&g_prefetch->mutex);
	pthread_cond_destroy(&g_prefetch->cond);
	free(g_prefetch);
	g_prefetch = NULL;
}
#endif

// ============================================================================
// Per-layer weight pointer cache — built once, eliminates 40+ snprintf+lookup
// per layer per token, avoiding repeated manifest scans in the hot path.
// ============================================================================

typedef struct {
	uint8_t q_kind;
	uint8_t k_kind;
	uint8_t v_kind;
	uint8_t o_kind;
	uint8_t qkv_kind;
	uint8_t z_kind;
	uint8_t out_proj_kind;
	uint8_t sg_kind;
	uint8_t su_kind;
	uint8_t sd_kind;
	uint8_t q_source;
	uint8_t k_source;
	uint8_t v_source;
	uint8_t o_source;
	uint8_t qkv_source;
	uint8_t z_source;
	uint8_t out_proj_source;
	uint8_t sg_source;
	uint8_t su_source;
	uint8_t sd_source;
	// Input/post-attention layer norms
	uint16_t *input_norm_w;
	uint16_t *post_attn_norm_w;

	// Full attention weights (non-NULL only for full attention layers)
	uint32_t *q_w; uint16_t *q_s, *q_b;
	uint32_t *k_w; uint16_t *k_s, *k_b;
	uint32_t *v_w; uint16_t *v_s, *v_b;
	uint32_t *o_w; uint16_t *o_s, *o_b;
	uint16_t *q_norm_w, *k_norm_w;

	// Linear attention weights (non-NULL only for linear attention layers)
	uint32_t *qkv_w; uint16_t *qkv_s, *qkv_b;
	uint32_t *z_w;   uint16_t *z_s, *z_b;
	uint32_t *b_w;   uint16_t *b_s, *b_b;
	uint32_t *a_w;   uint16_t *a_s, *a_b;
	uint16_t *conv1d_w;
	float *A_log;
	uint16_t *dt_bias;
	uint16_t *gated_norm_w;
	uint32_t *out_proj_w; uint16_t *out_proj_s, *out_proj_b;

	// MoE routing + shared expert weights
	uint32_t *gate_w; uint16_t *gate_s, *gate_b;
	uint32_t *sg_w;   uint16_t *sg_s, *sg_b;   // shared gate_proj
	uint32_t *su_w;   uint16_t *su_s, *su_b;   // shared up_proj
	uint32_t *sd_w;   uint16_t *sd_s, *sd_b;   // shared down_proj
	uint32_t *seg_w;  uint16_t *seg_s, *seg_b; // shared_expert_gate
} LayerWeightCache;

static LayerWeightCache layer_cache[MAX_LAYERS];
static int layer_cache_built = 0;

typedef struct {
	uint32_t cache_pos;
	uint32_t kv_dim;
	uint32_t head_dim;
	uint32_t rotary_dim;
	uint32_t num_q_heads;
	uint32_t num_kv_heads;
	float eps;
	float rope_cos[64];
	float rope_sin[64];
} FullAttnPrepareParams;

// Precompute RoPE trigonometry once per token position. All ten full-attention
// layers at a given token use the same values.
static void fill_full_attn_rope(FullAttnPrepareParams *p, int pos) {
	static int cached_pos = INT_MIN;
	static int cached_rotary = -1;
	static float cached_theta = 0.0f;
	static float cos_cache[64];
	static float sin_cache[64];
	int half = ROTARY_DIM / 2;
	if (half > 64) half = 64;
	if (cached_pos != pos || cached_rotary != ROTARY_DIM || cached_theta != ROPE_THETA) {
		for (int i = 0; i < half; i++) {
			float freq = 1.0f / powf(ROPE_THETA, (float)(2 * i) / ROTARY_DIM);
			float angle = (float)pos * freq;
			cos_cache[i] = cosf(angle);
			sin_cache[i] = sinf(angle);
		}
		cached_pos = pos;
		cached_rotary = ROTARY_DIM;
		cached_theta = ROPE_THETA;
	}
	memset(p->rope_cos, 0, sizeof(p->rope_cos));
	memset(p->rope_sin, 0, sizeof(p->rope_sin));
	memcpy(p->rope_cos, cos_cache, (size_t)half * sizeof(float));
	memcpy(p->rope_sin, sin_cache, (size_t)half * sizeof(float));
}

static int full_attn_chain_cmd2_prereqs(const LayerWeightCache *lc) {
	if (!lc || !g_metal || !g_metal->wf_buf || !g_metal->full_attn_prepare_pipe ||
		!g_metal->attn_scores_pipe || !g_metal->attn_softmax_pipe ||
		!g_metal->attn_values_pipe || !g_metal->sigmoid_gate_pipe ||
		!g_metal->residual_add || !g_metal->rms_norm_sum ||
		!g_metal->rms_norm_apply_bf16 || !lc->post_attn_norm_w ||
		!lc->q_norm_w || !lc->k_norm_w) return 0;

	// Initial experiment stays on native MLX4 projections/o_proj and the same
	// fused shared-expert path already proven in CMD2.
	if (lc->q_kind == MATVEC_KIND_GGUF_Q8_0 || lc->k_kind == MATVEC_KIND_GGUF_Q8_0 ||
		lc->v_kind == MATVEC_KIND_GGUF_Q8_0 || lc->o_kind == MATVEC_KIND_GGUF_Q8_0)
		return 0;
	if (!lc->o_w || !lc->o_s || !lc->o_b ||
		!lc->gate_w || !lc->gate_s || !lc->gate_b ||
		!lc->sg_w || !lc->sg_s || !lc->sg_b ||
		!lc->su_w || !lc->su_s || !lc->su_b ||
		!lc->seg_w || !lc->seg_s || !lc->seg_b) return 0;
	if (lc->sg_source == MATVEC_SOURCE_GGUF_SHARED ||
		lc->su_source == MATVEC_SOURCE_GGUF_SHARED ||
		lc->sd_source == MATVEC_SOURCE_GGUF_SHARED) return 0;
	if (full_attn_force_cmd2_fallback()) return 0;
	return 1;
}

static void encode_full_attn_prepare(
	id<MTLCommandBuffer> cmd,
	const LayerWeightCache *lc,
	int fa_idx,
	int cache_pos,
	int pos
) {
	FullAttnPrepareParams p;
	memset(&p, 0, sizeof(p));
	p.cache_pos = (uint32_t)cache_pos;
	p.kv_dim = (uint32_t)(NUM_KV_HEADS * HEAD_DIM);
	p.head_dim = (uint32_t)HEAD_DIM;
	p.rotary_dim = (uint32_t)ROTARY_DIM;
	p.num_q_heads = (uint32_t)NUM_ATTN_HEADS;
	p.num_kv_heads = (uint32_t)NUM_KV_HEADS;
	p.eps = RMS_NORM_EPS;
	fill_full_attn_rope(&p, pos);

	NSUInteger qnorm_off = (NSUInteger)((const char *)lc->q_norm_w -
										 (const char *)[g_metal->wf_buf contents]);
	NSUInteger knorm_off = (NSUInteger)((const char *)lc->k_norm_w -
										 (const char *)[g_metal->wf_buf contents]);
	id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
	[enc setComputePipelineState:g_metal->full_attn_prepare_pipe];
	[enc setBuffer:g_metal->batch_out[0] offset:0 atIndex:0];
	[enc setBuffer:g_metal->batch_out[1] offset:0 atIndex:1];
	[enc setBuffer:g_metal->batch_out[2] offset:0 atIndex:2];
	[enc setBuffer:g_metal->wf_buf offset:qnorm_off atIndex:3];
	[enc setBuffer:g_metal->wf_buf offset:knorm_off atIndex:4];
	[enc setBuffer:g_metal->buf_attn_q offset:0 atIndex:5];
	[enc setBuffer:g_metal->buf_attn_gate offset:0 atIndex:6];
	[enc setBuffer:g_metal->buf_kv_k[fa_idx] offset:0 atIndex:7];
	[enc setBuffer:g_metal->buf_kv_v[fa_idx] offset:0 atIndex:8];
	[enc setBytes:&p length:sizeof(p) atIndex:9];
	[enc dispatchThreadgroups:MTLSizeMake(NUM_ATTN_HEADS + NUM_KV_HEADS, 1, 1)
		threadsPerThreadgroup:MTLSizeMake(1, 1, 1)];
	[enc endEncoding];
}

static void sync_full_attn_cpu_kv_from_gpu(KVCache *kv, int fa_idx, int cache_pos) {
	if (!kv || !g_metal || fa_idx < 0 || fa_idx >= g_cfg.num_full_attn_layers || cache_pos < 0)
		return;
	size_t kv_dim = (size_t)NUM_KV_HEADS * HEAD_DIM;
	size_t off = (size_t)cache_pos * kv_dim;
	memcpy(kv->k_cache + off,
		   (const float *)[g_metal->buf_kv_k[fa_idx] contents] + off,
		   kv_dim * sizeof(float));
	memcpy(kv->v_cache + off,
		   (const float *)[g_metal->buf_kv_v[fa_idx] contents] + off,
		   kv_dim * sizeof(float));
}

// ---------------------------------------------------------------------------
// Detailed CMD1 linear-attention replay profiler.
// Captures one real decode-time GPU-linear sample after CMD1 has completed,
// then replays the five post-projection kernels in isolated command buffers
// after generation. Production inference scheduling is unchanged.
// ---------------------------------------------------------------------------

typedef struct {
	int valid;
	int layer_idx;
	int linear_layer_idx;

	size_t conv_w_off;
	size_t a_log_off;
	size_t dt_bias_off;
	size_t gated_norm_w_off;

	size_t conv_state_bytes;
	size_t delta_state_bytes;

	float *qkv;
	float *z;
	float *beta;
	float *alpha;
	float *conv_output;
	float *g_decay;
	float *beta_gate;
	float *delta_output;
	void *conv_state;
	void *delta_state;
} Cmd1LinearDetailSample;

static Cmd1LinearDetailSample g_cmd1_linear_detail = {0};

static void cmd1_linear_detail_free_sample(void) {
	free(g_cmd1_linear_detail.qkv);
	free(g_cmd1_linear_detail.z);
	free(g_cmd1_linear_detail.beta);
	free(g_cmd1_linear_detail.alpha);
	free(g_cmd1_linear_detail.conv_output);
	free(g_cmd1_linear_detail.g_decay);
	free(g_cmd1_linear_detail.beta_gate);
	free(g_cmd1_linear_detail.delta_output);
	free(g_cmd1_linear_detail.conv_state);
	free(g_cmd1_linear_detail.delta_state);
	memset(&g_cmd1_linear_detail, 0, sizeof(g_cmd1_linear_detail));
}

static void cmd1_linear_detail_capture(
	MetalCtx *ctx,
	LayerWeightCache *lc,
	int layer_idx,
	int linear_layer_idx
) {
	if (!g_cmd1_profile_enabled || !g_cmd1_profile_decode_active) return;
	if (g_cmd1_linear_detail.valid) return;
	if (!ctx || !ctx->wf_buf || !lc) return;
	if (linear_layer_idx < 0 || linear_layer_idx >= g_cfg.num_linear_layers) return;
	if (!lc->conv1d_w || !lc->A_log || !lc->dt_bias || !lc->gated_norm_w) return;
	if (!ctx->buf_conv_state[linear_layer_idx] || !ctx->buf_delta_state[linear_layer_idx]) return;

	const size_t qkv_bytes = (size_t)LINEAR_CONV_DIM * sizeof(float);
	const size_t z_bytes = (size_t)LINEAR_TOTAL_VALUE * sizeof(float);
	const size_t small_bytes = (size_t)LINEAR_NUM_V_HEADS * sizeof(float);
	const size_t conv_out_bytes = (size_t)LINEAR_CONV_DIM * sizeof(float);
	const size_t delta_out_bytes = (size_t)LINEAR_TOTAL_VALUE * sizeof(float);

	Cmd1LinearDetailSample *s = &g_cmd1_linear_detail;
	s->qkv = malloc(qkv_bytes);
	s->z = malloc(z_bytes);
	s->beta = malloc(small_bytes);
	s->alpha = malloc(small_bytes);
	s->conv_output = malloc(conv_out_bytes);
	s->g_decay = malloc(small_bytes);
	s->beta_gate = malloc(small_bytes);
	s->delta_output = malloc(delta_out_bytes);

	s->conv_state_bytes = [ctx->buf_conv_state[linear_layer_idx] length];
	s->delta_state_bytes = [ctx->buf_delta_state[linear_layer_idx] length];
	s->conv_state = malloc(s->conv_state_bytes);
	s->delta_state = malloc(s->delta_state_bytes);

	if (!s->qkv || !s->z || !s->beta || !s->alpha ||
		!s->conv_output || !s->g_decay || !s->beta_gate || !s->delta_output ||
		!s->conv_state || !s->delta_state) {
		cmd1_linear_detail_free_sample();
		return;
	}

	memcpy(s->qkv, [ctx->batch_out[0] contents], qkv_bytes);
	memcpy(s->z, [ctx->batch_out[1] contents], z_bytes);
	memcpy(s->beta, [ctx->batch_out[2] contents], small_bytes);
	memcpy(s->alpha, [ctx->batch_out[3] contents], small_bytes);
	memcpy(s->conv_output, [ctx->buf_conv_output contents], conv_out_bytes);
	memcpy(s->g_decay, [ctx->buf_delta_g_decay contents], small_bytes);
	memcpy(s->beta_gate, [ctx->buf_delta_beta contents], small_bytes);
	memcpy(s->delta_output, [ctx->buf_delta_output contents], delta_out_bytes);
	memcpy(s->conv_state, [ctx->buf_conv_state[linear_layer_idx] contents], s->conv_state_bytes);
	memcpy(s->delta_state, [ctx->buf_delta_state[linear_layer_idx] contents], s->delta_state_bytes);

	const char *wf_base = (const char *)[ctx->wf_buf contents];
	s->conv_w_off = (size_t)((const char *)lc->conv1d_w - wf_base);
	s->a_log_off = (size_t)((const char *)lc->A_log - wf_base);
	s->dt_bias_off = (size_t)((const char *)lc->dt_bias - wf_base);
	s->gated_norm_w_off = (size_t)((const char *)lc->gated_norm_w - wf_base);
	s->layer_idx = layer_idx;
	s->linear_layer_idx = linear_layer_idx;
	s->valid = 1;
}

enum {
	CMD1_DETAIL_CONV1D = 0,
	CMD1_DETAIL_RMS_QK,
	CMD1_DETAIL_DECAY_BETA,
	CMD1_DETAIL_DELTA_STEP,
	CMD1_DETAIL_GATED_RMS,
	CMD1_DETAIL_KERNEL_COUNT
};

typedef struct {
	id<MTLBuffer> conv_state;
	id<MTLBuffer> delta_state;
	id<MTLBuffer> qkv;
	id<MTLBuffer> z;
	id<MTLBuffer> beta;
	id<MTLBuffer> alpha;
	id<MTLBuffer> conv_output;
	id<MTLBuffer> g_decay;
	id<MTLBuffer> beta_gate;
	id<MTLBuffer> delta_output;
	id<MTLBuffer> gated_output;
} Cmd1LinearReplayBuffers;

static int cmd1_linear_detail_alloc_buffers(
	MetalCtx *ctx,
	Cmd1LinearReplayBuffers *b
) {
	Cmd1LinearDetailSample *s = &g_cmd1_linear_detail;
	if (!ctx || !b || !s->valid) return 0;
	b->conv_state = nil;
	b->delta_state = nil;
	b->qkv = nil;
	b->z = nil;
	b->beta = nil;
	b->alpha = nil;
	b->conv_output = nil;
	b->g_decay = nil;
	b->beta_gate = nil;
	b->delta_output = nil;
	b->gated_output = nil;

	b->conv_state = [ctx->device newBufferWithLength:s->conv_state_bytes
											 options:MTLResourceStorageModeShared];
	b->delta_state = [ctx->device newBufferWithLength:s->delta_state_bytes
											  options:MTLResourceStorageModeShared];
	b->qkv = [ctx->device newBufferWithLength:(size_t)LINEAR_CONV_DIM * sizeof(float)
									   options:MTLResourceStorageModeShared];
	b->z = [ctx->device newBufferWithLength:(size_t)LINEAR_TOTAL_VALUE * sizeof(float)
									 options:MTLResourceStorageModeShared];
	b->beta = [ctx->device newBufferWithLength:(size_t)LINEAR_NUM_V_HEADS * sizeof(float)
										options:MTLResourceStorageModeShared];
	b->alpha = [ctx->device newBufferWithLength:(size_t)LINEAR_NUM_V_HEADS * sizeof(float)
										 options:MTLResourceStorageModeShared];
	b->conv_output = [ctx->device newBufferWithLength:(size_t)LINEAR_CONV_DIM * sizeof(float)
											  options:MTLResourceStorageModeShared];
	b->g_decay = [ctx->device newBufferWithLength:(size_t)LINEAR_NUM_V_HEADS * sizeof(float)
										  options:MTLResourceStorageModeShared];
	b->beta_gate = [ctx->device newBufferWithLength:(size_t)LINEAR_NUM_V_HEADS * sizeof(float)
											options:MTLResourceStorageModeShared];
	b->delta_output = [ctx->device newBufferWithLength:(size_t)LINEAR_TOTAL_VALUE * sizeof(float)
											   options:MTLResourceStorageModeShared];
	b->gated_output = [ctx->device newBufferWithLength:(size_t)LINEAR_TOTAL_VALUE * sizeof(float)
											   options:MTLResourceStorageModeShared];

	return b->conv_state && b->delta_state && b->qkv && b->z &&
		   b->beta && b->alpha && b->conv_output && b->g_decay &&
		   b->beta_gate && b->delta_output && b->gated_output;
}

static void cmd1_linear_detail_reset_inputs(Cmd1LinearReplayBuffers *b) {
	Cmd1LinearDetailSample *s = &g_cmd1_linear_detail;
	memcpy([b->conv_state contents], s->conv_state, s->conv_state_bytes);
	memcpy([b->delta_state contents], s->delta_state, s->delta_state_bytes);
	memcpy([b->qkv contents], s->qkv, (size_t)LINEAR_CONV_DIM * sizeof(float));
	memcpy([b->z contents], s->z, (size_t)LINEAR_TOTAL_VALUE * sizeof(float));
	memcpy([b->beta contents], s->beta, (size_t)LINEAR_NUM_V_HEADS * sizeof(float));
	memcpy([b->alpha contents], s->alpha, (size_t)LINEAR_NUM_V_HEADS * sizeof(float));
	memcpy([b->conv_output contents], s->conv_output, (size_t)LINEAR_CONV_DIM * sizeof(float));
	memcpy([b->g_decay contents], s->g_decay, (size_t)LINEAR_NUM_V_HEADS * sizeof(float));
	memcpy([b->beta_gate contents], s->beta_gate, (size_t)LINEAR_NUM_V_HEADS * sizeof(float));
	memcpy([b->delta_output contents], s->delta_output, (size_t)LINEAR_TOTAL_VALUE * sizeof(float));
}

static void cmd1_linear_detail_encode_kernel(
	MetalCtx *ctx,
	id<MTLCommandBuffer> cmd,
	Cmd1LinearReplayBuffers *b,
	int which
) {
	Cmd1LinearDetailSample *s = &g_cmd1_linear_detail;

	switch (which) {
		case CMD1_DETAIL_CONV1D: {
			uint32_t conv_dim = LINEAR_CONV_DIM;
			id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
			[enc setComputePipelineState:ctx->conv1d_step];
			[enc setBuffer:b->conv_state offset:0 atIndex:0];
			[enc setBuffer:b->qkv offset:0 atIndex:1];
			[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->conv_w_off atIndex:2];
			[enc setBuffer:b->conv_output offset:0 atIndex:3];
			[enc setBytes:&conv_dim length:4 atIndex:4];
			uint32_t tgs = (conv_dim + 255) / 256;
			[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			[enc endEncoding];
			break;
		}
		case CMD1_DETAIL_RMS_QK: {
			uint32_t key_dim = LINEAR_KEY_DIM;
			float inv_scale = 1.0f / sqrtf((float)LINEAR_KEY_DIM);
			id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
			[enc setComputePipelineState:ctx->rms_norm_qk];
			[enc setBuffer:b->conv_output offset:0 atIndex:0];
			[enc setBuffer:b->conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:1];
			[enc setBytes:&key_dim length:4 atIndex:2];
			[enc setBytes:&inv_scale length:4 atIndex:3];
			[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_K_HEADS, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(LINEAR_KEY_DIM, 1, 1)];
			[enc endEncoding];
			break;
		}
		case CMD1_DETAIL_DECAY_BETA: {
			id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
			[enc setComputePipelineState:ctx->compute_decay_beta];
			[enc setBuffer:b->alpha offset:0 atIndex:0];
			[enc setBuffer:b->beta offset:0 atIndex:1];
			[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->a_log_off atIndex:2];
			[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->dt_bias_off atIndex:3];
			[enc setBuffer:b->g_decay offset:0 atIndex:4];
			[enc setBuffer:b->beta_gate offset:0 atIndex:5];
			[enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)];
			[enc endEncoding];
			break;
		}
		case CMD1_DETAIL_DELTA_STEP: {
			uint32_t khpv = LINEAR_NUM_V_HEADS / LINEAR_NUM_K_HEADS;
			id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
			[enc setComputePipelineState:ctx->delta_net_step];
			[enc setBuffer:b->delta_state offset:0 atIndex:0];
			[enc setBuffer:b->conv_output offset:0 atIndex:1];
			[enc setBuffer:b->conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:2];
			[enc setBuffer:b->conv_output offset:2 * LINEAR_TOTAL_KEY * sizeof(float) atIndex:3];
			[enc setBuffer:b->g_decay offset:0 atIndex:4];
			[enc setBuffer:b->beta_gate offset:0 atIndex:5];
			[enc setBuffer:b->delta_output offset:0 atIndex:6];
			[enc setBytes:&khpv length:sizeof(khpv) atIndex:7];
			[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
			[enc endEncoding];
			break;
		}
		case CMD1_DETAIL_GATED_RMS: {
			uint32_t value_dim = LINEAR_VALUE_DIM;
			float eps = RMS_NORM_EPS;
			id<MTLComputeCommandEncoder> enc = [cmd computeCommandEncoder];
			[enc setComputePipelineState:ctx->gated_rms_norm];
			[enc setBuffer:b->delta_output offset:0 atIndex:0];
			[enc setBuffer:b->z offset:0 atIndex:1];
			[enc setBuffer:ctx->wf_buf offset:(NSUInteger)s->gated_norm_w_off atIndex:2];
			[enc setBuffer:b->gated_output offset:0 atIndex:3];
			[enc setBytes:&value_dim length:4 atIndex:4];
			[enc setBytes:&eps length:4 atIndex:5];
			[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(LINEAR_VALUE_DIM, 1, 1)];
			[enc endEncoding];
			break;
		}
	}
}

static void cmd1_linear_detail_run_block(
	MetalCtx *ctx,
	Cmd1LinearReplayBuffers *b,
	int which,
	int dispatches,
	double *wall_us_per_dispatch,
	double *gpu_us_per_dispatch
) {
	cmd1_linear_detail_reset_inputs(b);

	double t0 = now_ms();
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];

	for (int i = 0; i < dispatches; i++) {
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, which);
	}

	[cmd commit];
	[cmd waitUntilCompleted];

	double wall_ms = now_ms() - t0;
	double gpu_ms = (cmd.GPUStartTime > 0.0 && cmd.GPUEndTime >= cmd.GPUStartTime)
		? (cmd.GPUEndTime - cmd.GPUStartTime) * 1000.0 : 0.0;

	if (wall_us_per_dispatch) *wall_us_per_dispatch = wall_ms * 1000.0 / dispatches;
	if (gpu_us_per_dispatch) *gpu_us_per_dispatch = gpu_ms * 1000.0 / dispatches;
}

static void cmd1_linear_detail_run_chain_block(
	MetalCtx *ctx,
	Cmd1LinearReplayBuffers *b,
	int chains,
	double *wall_us_per_chain,
	double *gpu_us_per_chain
) {
	cmd1_linear_detail_reset_inputs(b);

	double t0 = now_ms();
	id<MTLCommandBuffer> cmd = [ctx->queue commandBuffer];

	for (int i = 0; i < chains; i++) {
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, CMD1_DETAIL_CONV1D);
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, CMD1_DETAIL_RMS_QK);
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, CMD1_DETAIL_DECAY_BETA);
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, CMD1_DETAIL_DELTA_STEP);
		cmd1_linear_detail_encode_kernel(ctx, cmd, b, CMD1_DETAIL_GATED_RMS);
	}

	[cmd commit];
	[cmd waitUntilCompleted];

	double wall_ms = now_ms() - t0;
	double gpu_ms = (cmd.GPUStartTime > 0.0 && cmd.GPUEndTime >= cmd.GPUStartTime)
		? (cmd.GPUEndTime - cmd.GPUStartTime) * 1000.0 : 0.0;

	if (wall_us_per_chain) *wall_us_per_chain = wall_ms * 1000.0 / chains;
	if (gpu_us_per_chain) *gpu_us_per_chain = gpu_ms * 1000.0 / chains;
}

static double cmd1_detail_median(double *v, int n) {
	qsort(v, (size_t)n, sizeof(double), matvec_bench_double_cmp);
	return v[n / 2];
}

static void cmd1_linear_detail_replay(MetalCtx *ctx) {
	if (!g_cmd1_profile_enabled) return;

	printf("\n[CMD1 detailed linear-attention replay]\n");

	Cmd1LinearDetailSample *s = &g_cmd1_linear_detail;
	if (!ctx || !s->valid) {
		printf("  SKIPPED — no decode-time GPU linear-attention sample captured\n");
		return;
	}
	if (!ctx->conv1d_step || !ctx->rms_norm_qk || !ctx->compute_decay_beta ||
		!ctx->delta_net_step || !ctx->gated_rms_norm) {
		printf("  SKIPPED — one or more linear-attention Metal pipelines unavailable\n");
		return;
	}

	printf("  captured production layer=%d linear_layer=%d\n",
		   s->layer_idx, s->linear_layer_idx);
	printf("  shapes: conv=%d, key_total=%d, value_total=%d, k_heads=%d, v_heads=%d\n",
		   LINEAR_CONV_DIM, LINEAR_TOTAL_KEY, LINEAR_TOTAL_VALUE,
		   LINEAR_NUM_K_HEADS, LINEAR_NUM_V_HEADS);
	printf("  methodology: isolated real-buffer replay; 10 warmup blocks; 100 measured blocks; 64 dispatches/block\n");

	Cmd1LinearReplayBuffers b;
	if (!cmd1_linear_detail_alloc_buffers(ctx, &b)) {
		printf("  SKIPPED — unable to allocate replay buffers\n");
		return;
	}

	const char *names[CMD1_DETAIL_KERNEL_COUNT] = {
		"conv1d_step",
		"rms_norm_qk",
		"compute_decay_beta",
		"gated_delta_net_step",
		"gated_rms_norm"
	};

	enum { WARMUP = 10, BLOCKS = 100, REPEATS = 64 };

	double isolated_gpu_sum = 0.0;
	double isolated_wall_sum = 0.0;

	for (int k = 0; k < CMD1_DETAIL_KERNEL_COUNT; k++) {
		for (int w = 0; w < WARMUP; w++)
			cmd1_linear_detail_run_block(ctx, &b, k, REPEATS, NULL, NULL);

		double wall[BLOCKS];
		double gpu[BLOCKS];
		int gpu_valid = 1;

		for (int m = 0; m < BLOCKS; m++) {
			cmd1_linear_detail_run_block(ctx, &b, k, REPEATS, &wall[m], &gpu[m]);
			if (gpu[m] <= 0.0) gpu_valid = 0;
		}

		double wall_med = cmd1_detail_median(wall, BLOCKS);
		double gpu_med = cmd1_detail_median(gpu, BLOCKS);
		double contribution = gpu_valid ? gpu_med * g_cfg.num_linear_layers / 1000.0 : 0.0;

		printf("  %-23s GPU ", names[k]);
		if (gpu_valid) printf("%8.3f us", gpu_med);
		else printf("%8s", "n/a");
		printf("  wall %8.3f us", wall_med);
		if (gpu_valid)
			printf("  est %.3f ms/token (%d layers)", contribution, g_cfg.num_linear_layers);
		printf("\n");

		if (gpu_valid) isolated_gpu_sum += gpu_med;
		isolated_wall_sum += wall_med;
	}

	// Replay the exact five-kernel post-projection sequence as one production-like
	// command buffer. This exposes encoder/between-kernel effects that the sum of
	// isolated kernels can miss.
	for (int w = 0; w < WARMUP; w++)
		cmd1_linear_detail_run_chain_block(ctx, &b, REPEATS, NULL, NULL);

	double chain_wall[BLOCKS];
	double chain_gpu[BLOCKS];
	int chain_gpu_valid = 1;

	for (int m = 0; m < BLOCKS; m++) {
		cmd1_linear_detail_run_chain_block(ctx, &b, REPEATS,
										  &chain_wall[m], &chain_gpu[m]);
		if (chain_gpu[m] <= 0.0) chain_gpu_valid = 0;
	}

	double chain_wall_med = cmd1_detail_median(chain_wall, BLOCKS);
	double chain_gpu_med = cmd1_detail_median(chain_gpu, BLOCKS);

	printf("  ----------------------------------------------------------------\n");
	printf("  isolated-kernel sum:       GPU %.3f us  wall %.3f us  est %.3f ms/token\n",
		   isolated_gpu_sum, isolated_wall_sum,
		   isolated_gpu_sum * g_cfg.num_linear_layers / 1000.0);

	printf("  five-kernel chain:         GPU ");
	if (chain_gpu_valid) printf("%.3f us", chain_gpu_med);
	else printf("n/a");
	printf("  wall %.3f us", chain_wall_med);
	if (chain_gpu_valid)
		printf("  est %.3f ms/token",
			   chain_gpu_med * g_cfg.num_linear_layers / 1000.0);
	printf("\n");

	if (chain_gpu_valid) {
		double gap = chain_gpu_med - isolated_gpu_sum;
		printf("  chain minus isolated sum:  %+0.3f us/layer (%+0.3f ms/token)\n",
			   gap, gap * g_cfg.num_linear_layers / 1000.0);
	}
	printf("  This replay covers the five GPU GatedDeltaNet kernels after QKV/Z/beta/alpha projections.\n");
	printf("  Projection matvecs remain reported separately by [CMD1 production-replay profile].\n");
}

static void build_layer_cache(WeightFile *wf) {
	if (layer_cache_built) return;
	char name[256];

	for (int i = 0; i < NUM_LAYERS; i++) {
		LayerWeightCache *lc = &layer_cache[i];
		int is_full = ((i + 1) % FULL_ATTN_INTERVAL == 0);

		// Norms
		snprintf(name, sizeof(name), "model.layers.%d.input_layernorm.weight", i);
		lc->input_norm_w = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.post_attention_layernorm.weight", i);
		lc->post_attn_norm_w = get_tensor_ptr(wf, name);

		if (is_full) {
			// Full attention
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.q_proj.weight", i);
			lc->q_w = get_tensor_ptr(wf, name);
			if (wf->gguf_full_attn_q_layers[i]) {
				lc->q_w = (uint32_t *)wf->gguf_full_attn_q_layers[i];
				lc->q_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->q_source = MATVEC_SOURCE_GGUF_FULL_ATTN;
			}
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.q_proj.scales", i);
			lc->q_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.q_proj.biases", i);
			lc->q_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.k_proj.weight", i);
			lc->k_w = get_tensor_ptr(wf, name);
			if (wf->gguf_full_attn_k_layers[i]) {
				lc->k_w = (uint32_t *)wf->gguf_full_attn_k_layers[i];
				lc->k_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->k_source = MATVEC_SOURCE_GGUF_FULL_ATTN;
			}
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.k_proj.scales", i);
			lc->k_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.k_proj.biases", i);
			lc->k_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.v_proj.weight", i);
			lc->v_w = get_tensor_ptr(wf, name);
			if (wf->gguf_full_attn_v_layers[i]) {
				lc->v_w = (uint32_t *)wf->gguf_full_attn_v_layers[i];
				lc->v_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->v_source = MATVEC_SOURCE_GGUF_FULL_ATTN;
			}
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.v_proj.scales", i);
			lc->v_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.v_proj.biases", i);
			lc->v_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.o_proj.weight", i);
			lc->o_w = get_tensor_ptr(wf, name);
			if (wf->gguf_full_attn_o_layers[i]) {
				lc->o_w = (uint32_t *)wf->gguf_full_attn_o_layers[i];
				lc->o_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->o_source = MATVEC_SOURCE_GGUF_FULL_ATTN;
			}
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.o_proj.scales", i);
			lc->o_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.o_proj.biases", i);
			lc->o_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.q_norm.weight", i);
			lc->q_norm_w = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.self_attn.k_norm.weight", i);
			lc->k_norm_w = get_tensor_ptr(wf, name);
		} else {
			// Linear attention
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_qkv.weight", i);
			lc->qkv_w = get_tensor_ptr(wf, name);
			if (wf->gguf_qkv_layers[i]) {
				lc->qkv_w = (uint32_t *)wf->gguf_qkv_layers[i];
				lc->qkv_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->qkv_source = MATVEC_SOURCE_GGUF_QKV;
			}
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_qkv.scales", i);
			lc->qkv_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_qkv.biases", i);
			lc->qkv_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_z.weight", i);
			lc->z_w = get_tensor_ptr(wf, name);
			if (wf->gguf_linear_z_layers[i]) {
				lc->z_w = (uint32_t *)wf->gguf_linear_z_layers[i];
				lc->z_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->z_source = MATVEC_SOURCE_GGUF_LINEAR;
			}
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_z.scales", i);
			lc->z_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_z.biases", i);
			lc->z_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_b.weight", i);
			lc->b_w = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_b.scales", i);
			lc->b_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_b.biases", i);
			lc->b_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_a.weight", i);
			lc->a_w = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_a.scales", i);
			lc->a_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.in_proj_a.biases", i);
			lc->a_b = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.conv1d.weight", i);
			lc->conv1d_w = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.A_log", i);
			lc->A_log = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.dt_bias", i);
			lc->dt_bias = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.norm.weight", i);
			lc->gated_norm_w = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.out_proj.weight", i);
			lc->out_proj_w = get_tensor_ptr(wf, name);
			if (wf->gguf_linear_out_layers[i]) {
				lc->out_proj_w = (uint32_t *)wf->gguf_linear_out_layers[i];
				lc->out_proj_kind = MATVEC_KIND_GGUF_Q8_0;
				lc->out_proj_source = MATVEC_SOURCE_GGUF_LINEAR;
			}
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.out_proj.scales", i);
			lc->out_proj_s = get_tensor_ptr(wf, name);
			snprintf(name, sizeof(name), "model.layers.%d.linear_attn.out_proj.biases", i);
			lc->out_proj_b = get_tensor_ptr(wf, name);
		}

		// MoE weights (same for all layers)
		snprintf(name, sizeof(name), "model.layers.%d.mlp.gate.weight", i);
		lc->gate_w = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.gate.scales", i);
		lc->gate_s = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.gate.biases", i);
		lc->gate_b = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.gate_proj.weight", i);
		lc->sg_w = get_tensor_ptr(wf, name);
		if (wf->gguf_shared_gate_layers[i]) {
			lc->sg_w = (uint32_t *)wf->gguf_shared_gate_layers[i];
			lc->sg_kind = MATVEC_KIND_GGUF_Q8_0;
			lc->sg_source = MATVEC_SOURCE_GGUF_SHARED;
		}
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.gate_proj.scales", i);
		lc->sg_s = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.gate_proj.biases", i);
		lc->sg_b = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.up_proj.weight", i);
		lc->su_w = get_tensor_ptr(wf, name);
		if (wf->gguf_shared_up_layers[i]) {
			lc->su_w = (uint32_t *)wf->gguf_shared_up_layers[i];
			lc->su_kind = MATVEC_KIND_GGUF_Q8_0;
			lc->su_source = MATVEC_SOURCE_GGUF_SHARED;
		}
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.up_proj.scales", i);
		lc->su_s = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.up_proj.biases", i);
		lc->su_b = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.down_proj.weight", i);
		lc->sd_w = get_tensor_ptr(wf, name);
		if (wf->gguf_shared_down_layers[i]) {
			lc->sd_w = (uint32_t *)wf->gguf_shared_down_layers[i];
			lc->sd_kind = MATVEC_KIND_GGUF_Q8_0;
			lc->sd_source = MATVEC_SOURCE_GGUF_SHARED;
		}
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.down_proj.scales", i);
		lc->sd_s = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert.down_proj.biases", i);
		lc->sd_b = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert_gate.weight", i);
		lc->seg_w = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert_gate.scales", i);
		lc->seg_s = get_tensor_ptr(wf, name);
		snprintf(name, sizeof(name), "model.layers.%d.mlp.shared_expert_gate.biases", i);
		lc->seg_b = get_tensor_ptr(wf, name);
	}

	layer_cache_built = 1;
	printf("[cache] Pre-computed weight pointers for %d layers\n", NUM_LAYERS);
}

static int require_mlx_triplet(const char *label, const void *w,
							   const void *s, const void *b, int kind) {
	if (!w || (kind != MATVEC_KIND_GGUF_Q8_0 && (!s || !b))) {
		fprintf(stderr, "ERROR: required tensor group missing: %s\n", label);
		return 0;
	}
	return 1;
}

static int validate_required_model_tensors(WeightFile *wf) {
	if (!wf) return 0;
	if (!layer_cache_built) build_layer_cache(wf);

	int ok = 1;
	char label[256];

	if (!get_tensor_ptr(wf, "model.norm.weight")) ok = 0;
	if (!wf->gguf_embedding_data &&
		(!get_tensor_ptr(wf, "model.embed_tokens.weight") ||
		 !get_tensor_ptr(wf, "model.embed_tokens.scales") ||
		 !get_tensor_ptr(wf, "model.embed_tokens.biases"))) {
		fprintf(stderr, "ERROR: required embedding tensors are incomplete\n");
		ok = 0;
	}
	if (!wf->gguf_lm_head_data &&
		(!get_tensor_ptr(wf, "lm_head.weight") ||
		 !get_tensor_ptr(wf, "lm_head.scales") ||
		 !get_tensor_ptr(wf, "lm_head.biases"))) {
		fprintf(stderr, "ERROR: required lm_head tensors are incomplete\n");
		ok = 0;
	}

	for (int i = 0; i < NUM_LAYERS; i++) {
		LayerWeightCache *lc = &layer_cache[i];
		int is_full = ((i + 1) % FULL_ATTN_INTERVAL == 0);

		if (!lc->input_norm_w || !lc->post_attn_norm_w) {
			fprintf(stderr, "ERROR: layer %d is missing normalization weights\n", i);
			ok = 0;
		}

		snprintf(label, sizeof(label), "layer %d MoE gate", i);
		ok &= require_mlx_triplet(label, lc->gate_w, lc->gate_s, lc->gate_b, MATVEC_KIND_MLX4);
		snprintf(label, sizeof(label), "layer %d shared gate_proj", i);
		ok &= require_mlx_triplet(label, lc->sg_w, lc->sg_s, lc->sg_b, lc->sg_kind);
		snprintf(label, sizeof(label), "layer %d shared up_proj", i);
		ok &= require_mlx_triplet(label, lc->su_w, lc->su_s, lc->su_b, lc->su_kind);
		snprintf(label, sizeof(label), "layer %d shared down_proj", i);
		ok &= require_mlx_triplet(label, lc->sd_w, lc->sd_s, lc->sd_b, lc->sd_kind);
		snprintf(label, sizeof(label), "layer %d shared expert gate", i);
		ok &= require_mlx_triplet(label, lc->seg_w, lc->seg_s, lc->seg_b, MATVEC_KIND_MLX4);

		if (is_full) {
			snprintf(label, sizeof(label), "layer %d q_proj", i);
			ok &= require_mlx_triplet(label, lc->q_w, lc->q_s, lc->q_b, lc->q_kind);
			snprintf(label, sizeof(label), "layer %d k_proj", i);
			ok &= require_mlx_triplet(label, lc->k_w, lc->k_s, lc->k_b, lc->k_kind);
			snprintf(label, sizeof(label), "layer %d v_proj", i);
			ok &= require_mlx_triplet(label, lc->v_w, lc->v_s, lc->v_b, lc->v_kind);
			snprintf(label, sizeof(label), "layer %d o_proj", i);
			ok &= require_mlx_triplet(label, lc->o_w, lc->o_s, lc->o_b, lc->o_kind);
			if (!lc->q_norm_w || !lc->k_norm_w) {
				fprintf(stderr, "ERROR: full-attention layer %d is missing q/k norm weights\n", i);
				ok = 0;
			}
		} else {
			snprintf(label, sizeof(label), "layer %d linear qkv", i);
			ok &= require_mlx_triplet(label, lc->qkv_w, lc->qkv_s, lc->qkv_b, lc->qkv_kind);
			snprintf(label, sizeof(label), "layer %d linear z", i);
			ok &= require_mlx_triplet(label, lc->z_w, lc->z_s, lc->z_b, lc->z_kind);
			snprintf(label, sizeof(label), "layer %d linear beta", i);
			ok &= require_mlx_triplet(label, lc->b_w, lc->b_s, lc->b_b, MATVEC_KIND_MLX4);
			snprintf(label, sizeof(label), "layer %d linear alpha", i);
			ok &= require_mlx_triplet(label, lc->a_w, lc->a_s, lc->a_b, MATVEC_KIND_MLX4);
			snprintf(label, sizeof(label), "layer %d linear out_proj", i);
			ok &= require_mlx_triplet(label, lc->out_proj_w, lc->out_proj_s, lc->out_proj_b, lc->out_proj_kind);
			if (!lc->conv1d_w || !lc->A_log || !lc->dt_bias || !lc->gated_norm_w) {
				fprintf(stderr, "ERROR: linear-attention layer %d is missing recurrent weights\n", i);
				ok = 0;
			}
		}
	}
	return ok ? 1 : 0;
}

static int matvec_bench_add_cached_tensor(WeightFile *wf, MetalCtx *ctx,
								 MatvecBenchShape *shape,
								 char *name, size_t name_size,
								 const char *base, int layer,
								 void *w, void *s, void *b,
								 uint8_t kind, uint8_t source,
								 int special_mlx4) {
	if (shape->tensor_count >= MAX_LAYERS * 4 || !w || !s || !b) return 0;
	if ((!special_mlx4 && (kind != MATVEC_KIND_MLX4 || source != MATVEC_SOURCE_WF)) ||
		((const char *)w < (const char *)[ctx->wf_buf contents]) ||
		((const char *)w >= (const char *)[ctx->wf_buf contents] + [ctx->wf_buf length]) ||
		((const char *)s < (const char *)[ctx->wf_buf contents]) ||
		((const char *)s >= (const char *)[ctx->wf_buf contents] + [ctx->wf_buf length]) ||
		((const char *)b < (const char *)[ctx->wf_buf contents]) ||
		((const char *)b >= (const char *)[ctx->wf_buf contents] + [ctx->wf_buf length])) return 0;
	snprintf(name, name_size, base, layer);
	TensorInfo *tw = get_tensor_info(wf, name);
	if (!tw || tw->ndim < 2 || tw->shape[0] != (int)shape->out_dim) return 0;

	// MLX4 weights are packed: 8 four-bit values per uint32.
	if ((int)shape->in_dim % 8 != 0) return 0;
	if (tw->shape[1] != (int)(shape->in_dim / 8)) return 0;

	// Scales/biases are one value per quantization group.
	int packed_cols = tw->shape[1];
	int num_groups = packed_cols * 8 / GROUP_SIZE;
	if (num_groups <= 0) return 0;

	size_t wlen = strlen(name);
	if (wlen < 7 || strcmp(name + wlen - 7, ".weight") != 0) return 0;
	char sname[160], bname[160];
	snprintf(sname, sizeof(sname), "%.*s.scales", (int)(wlen - 7), name);
	snprintf(bname, sizeof(bname), "%.*s.biases", (int)(wlen - 7), name);
	TensorInfo *ts = get_tensor_info(wf, sname);
	TensorInfo *tb = get_tensor_info(wf, bname);
	if (!ts || !tb || ts->ndim < 2 || tb->ndim < 2 ||
		ts->shape[0] != (int)shape->out_dim || tb->shape[0] != (int)shape->out_dim ||
		ts->shape[1] != num_groups || tb->shape[1] != num_groups) {
		if (!shape->rejection_reported) {
			shape->rejection_reported = 1;
			printf("[matvec-bench] reject %s %s:\n", shape->label, name);
			printf("  weight manifest shape [%d,%d], expected packed [%d,%d]\n",
				tw->shape[0], tw->shape[1], (int)shape->out_dim, (int)(shape->in_dim / 8));
			if (ts) printf("  scale shape [%d,%d], expected [%d,%d]\n",
				ts->shape[0], ts->shape[1], (int)shape->out_dim, num_groups);
			else printf("  scale manifest entry not found\n");
			if (tb) printf("  bias shape [%d,%d], expected [%d,%d]\n",
				tb->shape[0], tb->shape[1], (int)shape->out_dim, num_groups);
			else printf("  bias manifest entry not found\n");
		}
		return 0;
	}

	MatvecBenchTensor *t = &shape->tensors[shape->tensor_count++];
	t->name = name;
	t->weight_buf = ctx->wf_buf;
	t->weight_off = (NSUInteger)((const char *)w - (const char *)[ctx->wf_buf contents]);
	t->scale_off = (NSUInteger)((const char *)s - (const char *)[ctx->wf_buf contents]);
	t->bias_off = (NSUInteger)((const char *)b - (const char *)[ctx->wf_buf contents]);
	return 1;
}

static void matvec_bench_discover_cached(WeightFile *wf, MetalCtx *ctx,
									 MatvecBenchShape *shapes,
									 char names[7][MAX_LAYERS * 4][160]) {
	for (int i = 0; i < g_cfg.num_layers; i++) {
		LayerWeightCache *lc = &layer_cache[i];
		int full = g_cfg.full_attn_interval > 0 && (i + 1) % g_cfg.full_attn_interval == 0;
		if (full) {
			matvec_bench_add_cached_tensor(wf, ctx, &shapes[0], names[0][shapes[0].tensor_count], sizeof(names[0][0]), "model.layers.%d.self_attn.q_proj.weight", i, lc->q_w, lc->q_s, lc->q_b, lc->q_kind, lc->q_source, 0);
			matvec_bench_add_cached_tensor(wf, ctx, &shapes[3], names[3][shapes[3].tensor_count], sizeof(names[3][0]), "model.layers.%d.self_attn.k_proj.weight", i, lc->k_w, lc->k_s, lc->k_b, lc->k_kind, lc->k_source, 0);
			matvec_bench_add_cached_tensor(wf, ctx, &shapes[3], names[3][shapes[3].tensor_count], sizeof(names[3][0]), "model.layers.%d.self_attn.v_proj.weight", i, lc->v_w, lc->v_s, lc->v_b, lc->v_kind, lc->v_source, 0);
		} else {
			matvec_bench_add_cached_tensor(wf, ctx, &shapes[1], names[1][shapes[1].tensor_count], sizeof(names[1][0]), "model.layers.%d.linear_attn.in_proj_z.weight", i, lc->z_w, lc->z_s, lc->z_b, lc->z_kind, lc->z_source, 0);
			matvec_bench_add_cached_tensor(wf, ctx, &shapes[0], names[0][shapes[0].tensor_count], sizeof(names[0][0]), "model.layers.%d.linear_attn.in_proj_qkv.weight", i, lc->qkv_w, lc->qkv_s, lc->qkv_b, lc->qkv_kind, lc->qkv_source, 0);
		}
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[2], names[2][shapes[2].tensor_count], sizeof(names[2][0]), full ? "model.layers.%d.self_attn.o_proj.weight" : "model.layers.%d.linear_attn.out_proj.weight", i, full ? lc->o_w : lc->out_proj_w, full ? lc->o_s : lc->out_proj_s, full ? lc->o_b : lc->out_proj_b, full ? lc->o_kind : lc->out_proj_kind, full ? lc->o_source : lc->out_proj_source, 0);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[4], names[4][shapes[4].tensor_count], sizeof(names[4][0]), "model.layers.%d.mlp.gate.weight", i, lc->gate_w, lc->gate_s, lc->gate_b, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF, 1);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[3], names[3][shapes[3].tensor_count], sizeof(names[3][0]), "model.layers.%d.mlp.shared_expert.gate_proj.weight", i, lc->sg_w, lc->sg_s, lc->sg_b, lc->sg_kind, lc->sg_source, 0);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[3], names[3][shapes[3].tensor_count], sizeof(names[3][0]), "model.layers.%d.mlp.shared_expert.up_proj.weight", i, lc->su_w, lc->su_s, lc->su_b, lc->su_kind, lc->su_source, 0);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[5], names[5][shapes[5].tensor_count], sizeof(names[5][0]), "model.layers.%d.linear_attn.in_proj_b.weight", i, lc->b_w, lc->b_s, lc->b_b, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF, 1);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[5], names[5][shapes[5].tensor_count], sizeof(names[5][0]), "model.layers.%d.linear_attn.in_proj_a.weight", i, lc->a_w, lc->a_s, lc->a_b, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF, 1);
		matvec_bench_add_cached_tensor(wf, ctx, &shapes[6], names[6][shapes[6].tensor_count], sizeof(names[6][0]), "model.layers.%d.mlp.shared_expert_gate.weight", i, lc->seg_w, lc->seg_s, lc->seg_b, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF, 1);
	}
}

// ============================================================================
// Deferred expert state: holds state for async GPU expert compute.
// GPU experts are submitted async (commit without wait), and the wait+combine
// happens at the start of the NEXT layer. This overlaps ~1ms of GPU expert
// compute with the next layer's attention+routing CPU/GPU work.
// ============================================================================

typedef struct {
	int active;                         // 1 if there's a deferred GPU expert to wait for
	int gpu_combined;                   // 1 if CMD3 includes combine+residual+norm on GPU
										// (next layer can skip deferred_wait+finalize+input_norm
										//  and submit CMD1 immediately -- buf_input is ready)
	id<MTLCommandBuffer> cmd_experts;   // the async command buffer (committed but not waited)
	float expert_weights[MAX_K];        // routing weights for weighted accumulation
	int valid[MAX_K];                   // which experts loaded successfully
	int actual_K;                       // number of experts
	float h_mid[MAX_HIDDEN_DIM];        // saved h_mid for final combine
	float shared_gate_score;            // saved shared expert gate score
	float *hidden;                      // pointer to hidden state (for writing final result)
	int layer_idx;                      // which layer produced this deferred state
} DeferredExpertState;

static DeferredExpertState g_deferred = { .active = 0 };

static void pipeline_profile_reset(void) {
	memset(&g_pipeline_profile, 0, sizeof(g_pipeline_profile));
}

static void pipeline_profile_note_cmd3(id<MTLCommandBuffer> cmd, int layer_idx) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active || !cmd ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS) return;

	PipelineLayerProfile *p = &g_pipeline_profile.layer[layer_idx];
	g_pipeline_profile.cmd3_count++;

	double start = cmd.GPUStartTime, end = cmd.GPUEndTime;
	if (start > 0.0 && end >= start) {
		double dur_ms = (end - start) * 1000.0;
		g_pipeline_profile.cmd3_timestamp_count++;
		g_pipeline_profile.cmd3_gpu_ms += dur_ms;
		p->cmd3_timestamp_layers++;
		p->cmd3_gpu_ms += dur_ms;
		if (layer_idx == g_cfg.num_layers - 1)
			g_pipeline_profile.pending_last_cmd3_end_s = end;

		if (p->pending_cmd2_end_s > 0.0 && start >= p->pending_cmd2_end_s) {
			p->cmd23_gap_ms += (start - p->pending_cmd2_end_s) * 1000.0;
			p->cmd23_gap_count++;
		}
		if (p->pending_cmd3_commit_mach_s > 0.0 &&
			start >= p->pending_cmd3_commit_mach_s)
			p->cmd3_commit_to_gpustart_ms +=
				(start - p->pending_cmd3_commit_mach_s) * 1000.0;
		if (p->pending_cmd3_gate_signal_mach_s > 0.0 &&
			start >= p->pending_cmd3_gate_signal_mach_s)
			p->cmd3_gate_signal_to_gpustart_ms +=
				(start - p->pending_cmd3_gate_signal_mach_s) * 1000.0;
	}
	p->pending_cmd2_end_s = 0.0;
	p->pending_wait_return_mach_s = 0.0;
	p->pending_route_start_mach_s = 0.0;
	p->pending_route_end_mach_s = 0.0;
	p->pending_expert_start_mach_s = 0.0;
	p->pending_expert_end_mach_s = 0.0;
	p->pending_cmd3_commit_mach_s = 0.0;
	p->pending_cmd3_gate_signal_mach_s = 0.0;
}

static void pipeline_profile_note_cmd12(int layer_idx, id<MTLCommandBuffer> cmd1,
		id<MTLCommandBuffer> cmd2, id<MTLCommandBuffer> prev_cmd3) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS || !cmd1 || !cmd2) return;
	PipelineLayerProfile *p = &g_pipeline_profile.layer[layer_idx];
	p->gpu_layers++;
	double s1 = cmd1.GPUStartTime, e1 = cmd1.GPUEndTime;
	double s2 = cmd2.GPUStartTime, e2 = cmd2.GPUEndTime;
	if (layer_idx == 0 && g_pipeline_profile.pending_lm_end_s > 0.0 &&
		s1 > 0.0 && s1 >= g_pipeline_profile.pending_lm_end_s) {
		g_pipeline_profile.lm_to_next_cmd1_gap_ms +=
			(s1 - g_pipeline_profile.pending_lm_end_s) * 1000.0;
		g_pipeline_profile.lm_to_next_cmd1_gap_count++;
		g_pipeline_profile.pending_lm_end_s = 0.0;
	}
	if (s1 > 0.0 && e1 >= s1 && s2 > 0.0 && e2 >= s2) {
		p->gpu_timestamp_layers++;
		p->cmd1_gpu_ms += (e1 - s1) * 1000.0;
		p->cmd2_gpu_ms += (e2 - s2) * 1000.0;
		if (s2 >= e1) p->cmd12_gap_ms += (s2 - e1) * 1000.0;
		p->pending_cmd2_end_s = e2;
		if (prev_cmd3) {
			double e3 = prev_cmd3.GPUEndTime;
			if (e3 > 0.0 && s1 >= e3) {
				p->prev_cmd3_to_cmd1_gap_ms += (s1 - e3) * 1000.0;
				p->prev_gap_count++;
			}
		}
	}
}

static inline void pipeline_profile_note_layer_wall(int layer_idx, double ms) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS) return;
	PipelineLayerProfile *p = &g_pipeline_profile.layer[layer_idx];
	p->layer_wall_ms += ms;
	p->layer_wall_count++;
}

static inline void pipeline_profile_note_routing_wall(int layer_idx, double ms) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS) return;
	g_pipeline_profile.layer[layer_idx].routing_cpu_wall_ms += ms;
}

static inline void pipeline_profile_note_expert_split(int layer_idx,
		double lookup_ms, double io_wait_ms, double post_ms, double total_ms) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS) return;
	PipelineLayerProfile *p = &g_pipeline_profile.layer[layer_idx];
	p->expert_cache_lookup_ms += lookup_ms;
	p->expert_io_wait_ms += io_wait_ms;
	p->expert_post_stage_ms += post_ms;
	p->expert_stage_wall_ms += total_ms;
}

static inline void pipeline_profile_note_cmd3_encode_wall(int layer_idx, double ms) {
	if (!g_pipeline_profile_enabled || !g_pipeline_profile_decode_active ||
		layer_idx < 0 || layer_idx >= MAX_LAYERS) return;
	g_pipeline_profile.layer[layer_idx].cmd3_encode_wall_ms += ms;
}

static void pipeline_profile_print(void) {
	if (!g_pipeline_profile_enabled) return;

	double toks = g_pipeline_profile.tokens ? (double)g_pipeline_profile.tokens : 1.0;
	double cmd1=0, cmd2=0, cmd3=0, gap12=0, gap23=0, gap31=0;
	double layer_wall=0, routing=0, lookup=0, io_wait=0, post=0, expert_total=0, c3encode=0;
	double e_gpu2wait=0, e_wait2route=0, e_route2expert=0, e_expert2commit=0, e_commit2gpu3=0;
	double e_commit2gate=0, e_gate2gpu3=0;
	uint64_t gate_count=0;
	uint64_t gpu_layers=0, gpu_ts=0, gap23_count=0, layer_count=0;

	for (int i=0; i<g_cfg.num_layers; i++) {
		PipelineLayerProfile *p=&g_pipeline_profile.layer[i];
		cmd1 += p->cmd1_gpu_ms; cmd2 += p->cmd2_gpu_ms; cmd3 += p->cmd3_gpu_ms;
		gap12 += p->cmd12_gap_ms; gap23 += p->cmd23_gap_ms; gap31 += p->prev_cmd3_to_cmd1_gap_ms;
		layer_wall += p->layer_wall_ms; routing += p->routing_cpu_wall_ms;
		lookup += p->expert_cache_lookup_ms; io_wait += p->expert_io_wait_ms;
		post += p->expert_post_stage_ms; expert_total += p->expert_stage_wall_ms;
		c3encode += p->cmd3_encode_wall_ms;
		e_gpu2wait += p->cmd2_gpuend_to_waitreturn_ms;
		e_wait2route += p->waitreturn_to_route_start_ms;
		e_route2expert += p->route_end_to_expert_start_ms;
		e_expert2commit += p->expert_end_to_cmd3_commit_ms;
		e_commit2gpu3 += p->cmd3_commit_to_gpustart_ms;
		e_commit2gate += p->cmd3_commit_to_gate_signal_ms;
		e_gate2gpu3 += p->cmd3_gate_signal_to_gpustart_ms;
		gate_count += p->cmd3_gate_count;
		gpu_layers += p->gpu_layers; gpu_ts += p->gpu_timestamp_layers;
		gap23_count += p->cmd23_gap_count; layer_count += p->layer_wall_count;
	}

	fprintf(stderr, "\n[pipeline-profile — FINAL CLOSED decode timeline]\n");
	fprintf(stderr, "  decode tokens:                  %llu\n",
		(unsigned long long)g_pipeline_profile.tokens);

	fprintf(stderr, "\n  [GPU serial timeline]\n");
	fprintf(stderr, "  CMD1 actual GPU:                %7.3f ms/token\n", cmd1/toks);
	fprintf(stderr, "  CMD1 -> CMD2 idle:              %7.3f ms/token\n", gap12/toks);
	fprintf(stderr, "  CMD2 actual GPU:                %7.3f ms/token\n", cmd2/toks);
	fprintf(stderr, "  CMD2 -> CMD3 idle/dependency:   %7.3f ms/token\n", gap23/toks);
	fprintf(stderr, "  CMD3 actual GPU:                %7.3f ms/token\n", cmd3/toks);
	fprintf(stderr, "  CMD3 -> next CMD1 idle:         %7.3f ms/token\n", gap31/toks);
	fprintf(stderr, "  last CMD3 -> LM GPU start:      %7.3f ms/token  (%llu samples)\n",
		g_pipeline_profile.last_cmd3_to_lm_gap_ms/toks,
		(unsigned long long)g_pipeline_profile.last_cmd3_to_lm_gap_count);
	fprintf(stderr, "  LM head actual GPU:             %7.3f ms/token\n",
		g_pipeline_profile.lm_gpu_ms/toks);
	fprintf(stderr, "  LM GPU end -> next CMD1:        %7.3f ms/token  (%llu samples)\n",
		g_pipeline_profile.lm_to_next_cmd1_gap_ms/toks,
		(unsigned long long)g_pipeline_profile.lm_to_next_cmd1_gap_count);
	fprintf(stderr, "  GPU timestamp coverage:         %llu/%llu CMD1+CMD2, %llu/%llu CMD3\n",
		(unsigned long long)gpu_ts,(unsigned long long)gpu_layers,
		(unsigned long long)g_pipeline_profile.cmd3_timestamp_count,
		(unsigned long long)g_pipeline_profile.cmd3_count);
	fprintf(stderr, "  CMD2->CMD3 gap coverage:        %llu/%llu layers\n",
		(unsigned long long)gap23_count,
		(unsigned long long)g_pipeline_profile.cmd3_timestamp_count);

	double focused_sum = e_gpu2wait + e_wait2route + routing +
		e_route2expert + expert_total + e_expert2commit + e_commit2gpu3;
	fprintf(stderr, "\n  [CMD2 -> CMD3 exact decomposition]\n");
	fprintf(stderr, "  CMD2 GPU end -> wait return:    %7.3f ms/token\n", e_gpu2wait/toks);
	fprintf(stderr, "  wait return -> routing start:   %7.3f ms/token\n", e_wait2route/toks);
	fprintf(stderr, "  routing CPU:                    %7.3f ms/token\n", routing/toks);
	fprintf(stderr, "  routing end -> expert start:    %7.3f ms/token\n", e_route2expert/toks);
	fprintf(stderr, "  expert stage total:             %7.3f ms/token\n", expert_total/toks);
	fprintf(stderr, "  expert end -> CMD3 commit:      %7.3f ms/token\n", e_expert2commit/toks);
	fprintf(stderr, "  CMD3 commit -> GPU start:       %7.3f ms/token\n", e_commit2gpu3/toks);
	fprintf(stderr, "  ---------------------------------------\n");
	fprintf(stderr, "  decomposed sum:                 %7.3f ms/token\n", focused_sum/toks);
	fprintf(stderr, "  measured CMD2->CMD3 GPU gap:    %7.3f ms/token\n", gap23/toks);
	fprintf(stderr, "  decomposition residual:         %7.3f ms/token\n", (gap23-focused_sum)/toks);
	if (gate_count > 0) {
		fprintf(stderr, "  [CMD3 expert-I/O event gate]\n");
		fprintf(stderr, "  gated layer occurrences:        %llu\n", (unsigned long long)gate_count);
		fprintf(stderr, "  CMD3 commit -> CPU gate signal: %7.3f ms/token (overlaps I/O)\n", e_commit2gate/toks);
		fprintf(stderr, "  gate signal -> CMD3 GPU start:  %7.3f ms/token\n", e_gate2gpu3/toks);
		fprintf(stderr, "  note: the old serial decomposition double-counts overlap on gated layers;\n");
		fprintf(stderr, "        measured CMD2->CMD3 gap and token wall are authoritative.\n");
	}

	fprintf(stderr, "\n  [Layer-call wall clock]\n");
	fprintf(stderr, "  transformer layer calls:        %7.3f ms/token (%llu samples)\n",
		layer_wall/toks,(unsigned long long)layer_count);
	fprintf(stderr, "    routing CPU:                   %7.3f ms/token\n", routing/toks);
	fprintf(stderr, "    expert lookup/bookkeeping:     %7.3f ms/token\n", lookup/toks);
	fprintf(stderr, "    expert blocking I/O wait:      %7.3f ms/token\n", io_wait/toks);
	fprintf(stderr, "    expert post-I/O staging:       %7.3f ms/token\n", post/toks);
	fprintf(stderr, "    expert stage total:            %7.3f ms/token\n", expert_total/toks);
	fprintf(stderr, "    CMD3 CPU encode+commit:        %7.3f ms/token\n", c3encode/toks);
	fprintf(stderr, "  I/O pool batch span:             %7.3f ms/token\n",
		g_pipeline_profile.io_batch_span_ms/toks);

	double token_sum =
		g_pipeline_profile.embed_wall_ms +
		g_pipeline_profile.layers_wall_ms +
		g_pipeline_profile.final_deferred_wall_ms +
		g_pipeline_profile.final_norm_wall_ms +
		g_pipeline_profile.lm_total_wall_ms +
		g_pipeline_profile.output_wall_ms;
	double residual = g_pipeline_profile.token_wall_ms - token_sum;

	fprintf(stderr, "\n  [End-to-end token wall clock]\n");
	fprintf(stderr, "  embedding:                       %7.3f ms/token\n", g_pipeline_profile.embed_wall_ms/toks);
	fprintf(stderr, "  all 40 transformer layers:      %7.3f ms/token\n", g_pipeline_profile.layers_wall_ms/toks);
	fprintf(stderr, "  final deferred CMD3 completion: %7.3f ms/token\n", g_pipeline_profile.final_deferred_wall_ms/toks);
	fprintf(stderr, "  final RMSNorm:                   %7.3f ms/token\n", g_pipeline_profile.final_norm_wall_ms/toks);
	fprintf(stderr, "  LM head + sampling wall:         %7.3f ms/token\n", g_pipeline_profile.lm_total_wall_ms/toks);
	fprintf(stderr, "    LM actual GPU (overlapping):   %7.3f ms/token\n", g_pipeline_profile.lm_gpu_ms/toks);
	fprintf(stderr, "    CPU sampling subset:           %7.3f ms/token\n", g_pipeline_profile.sample_cpu_ms/toks);
	fprintf(stderr, "  decode/printf/fflush:            %7.3f ms/token\n", g_pipeline_profile.output_wall_ms/toks);
	fprintf(stderr, "  residual loop overhead:          %7.3f ms/token\n", residual/toks);
	fprintf(stderr, "  ---------------------------------------\n");
	fprintf(stderr, "  measured token wall clock:       %7.3f ms/token (%.2f tok/s)\n",
		g_pipeline_profile.token_wall_ms/toks,
		g_pipeline_profile.token_wall_ms>0 ? 1000.0*toks/g_pipeline_profile.token_wall_ms : 0.0);
	fprintf(stderr, "  partition closure error:         %7.6f ms/token\n",
		(g_pipeline_profile.token_wall_ms - token_sum - residual)/toks);

	if (g_pipeline_profile.io_timed_tasks) {
		fprintf(stderr, "\n  [I/O pool]\n");
		fprintf(stderr, "  %llu batches, %llu tasks, %.1f MiB total\n",
			(unsigned long long)g_pipeline_profile.io_batches,
			(unsigned long long)g_pipeline_profile.io_tasks,
			(double)g_pipeline_profile.io_bytes/1048576.0);
		fprintf(stderr, "  avg queue delay/task:            %7.3f ms\n",
			g_pipeline_profile.io_queue_delay_ms/(double)g_pipeline_profile.io_timed_tasks);
		fprintf(stderr, "  avg service/task:                %7.3f ms\n",
			g_pipeline_profile.io_service_ms/(double)g_pipeline_profile.io_timed_tasks);
		fprintf(stderr, "  aggregate batch span:            %7.3f ms/token\n",
			g_pipeline_profile.io_batch_span_ms/toks);
	}

	fprintf(stderr, "\n  [Per-layer averages — ms/layer occurrence]\n");
	fprintf(stderr,
		"  layer type    C1GPU C2GPU g2-3 e2wait w2route route r2exp expert e2commit commit2g3 C3GPU layerWall\n");
	for (int i=0;i<g_cfg.num_layers;i++) {
		PipelineLayerProfile *p=&g_pipeline_profile.layer[i];
		if (!p->gpu_timestamp_layers && !p->layer_wall_count) continue;
		double gc=p->gpu_timestamp_layers?(double)p->gpu_timestamp_layers:1.0;
		double c3=p->cmd3_timestamp_layers?(double)p->cmd3_timestamp_layers:1.0;
		double g23=p->cmd23_gap_count?(double)p->cmd23_gap_count:1.0;
		double wc=p->layer_wall_count?(double)p->layer_wall_count:1.0;
		fprintf(stderr,
			"  %3d %-7s %6.3f %5.3f %5.3f %6.3f %7.3f %5.3f %5.3f %6.3f %8.3f %8.3f %5.3f %8.3f\n",
			i,((i+1)%FULL_ATTN_INTERVAL==0)?"full":"linear",
			p->cmd1_gpu_ms/gc,p->cmd2_gpu_ms/gc,p->cmd23_gap_ms/g23,
			p->cmd2_gpuend_to_waitreturn_ms/wc,p->waitreturn_to_route_start_ms/wc,
			p->routing_cpu_wall_ms/wc,p->route_end_to_expert_start_ms/wc,
			p->expert_stage_wall_ms/wc,p->expert_end_to_cmd3_commit_ms/wc,
			p->cmd3_commit_to_gpustart_ms/wc,p->cmd3_gpu_ms/c3,p->layer_wall_ms/wc);
	}
}

typedef struct {
	uint64_t count;
	uint64_t gpu_timestamp_count;
	double gpu_duration_ms;
	double first_gpu_start_s;
	double last_gpu_end_s;
} Cmd3ProductionTimingBucket;

// [0] = linear/GatedDeltaNet layer, [1] = full-attention layer.
static Cmd3ProductionTimingBucket g_cmd3_prod_timing[2];

static void cmd3_production_timing_note_completed(void) {
	if (g_deferred.active && g_deferred.cmd_experts)
		pipeline_profile_note_cmd3(g_deferred.cmd_experts, g_deferred.layer_idx);
	if (!g_cmd1_profile_enabled || !g_cmd1_profile_decode_active) return;
	if (!g_deferred.active || !g_deferred.cmd_experts) return;

	int is_full = ((g_deferred.layer_idx + 1) % FULL_ATTN_INTERVAL == 0);
	Cmd3ProductionTimingBucket *b = &g_cmd3_prod_timing[is_full ? 1 : 0];
	b->count++;

	double gpu_start = g_deferred.cmd_experts.GPUStartTime;
	double gpu_end = g_deferred.cmd_experts.GPUEndTime;
	if (gpu_start > 0.0 && gpu_end >= gpu_start) {
		if (b->gpu_timestamp_count == 0)
			b->first_gpu_start_s = gpu_start;
		b->last_gpu_end_s = gpu_end;
		b->gpu_timestamp_count++;
		b->gpu_duration_ms += (gpu_end - gpu_start) * 1000.0;
	}
}

static void cmd3_production_timing_print(void) {
	if (!g_cmd1_profile_enabled) return;

	printf("\n[CMD3 production command-buffer timing]\n");
	printf("  GPUStartTime/GPUEndTime are read only after existing pipeline synchronization; no new waits are added.\n");

	const char *type_name[2] = { "linear", "full-attn" };
	double total_gpu_ms = 0.0;
	uint64_t total_count = 0;
	uint64_t total_gpu_count = 0;
	double first_start = 0.0;
	double last_end = 0.0;

	for (int i = 0; i < 2; i++) {
		Cmd3ProductionTimingBucket *b = &g_cmd3_prod_timing[i];
		if (b->count == 0) continue;

		double avg_gpu = b->gpu_timestamp_count
			? b->gpu_duration_ms / (double)b->gpu_timestamp_count : 0.0;
		double per_token = g_cmd1_profile_tokens
			? b->gpu_duration_ms / (double)g_cmd1_profile_tokens : 0.0;

		printf("  %-9s count=%llu", type_name[i], (unsigned long long)b->count);
		if (b->gpu_timestamp_count != b->count) {
			printf(" gpu_ts=%llu/%llu",
				   (unsigned long long)b->gpu_timestamp_count,
				   (unsigned long long)b->count);
		}
		printf("\n");

		if (b->gpu_timestamp_count) {
			printf("    avg CMD3 GPU duration/layer: %.3f ms\n", avg_gpu);
			printf("    contribution/token:         %.3f ms\n", per_token);
			printf("    first GPUStartTime:         %.6f s\n", b->first_gpu_start_s);
			printf("    last GPUEndTime:            %.6f s\n", b->last_gpu_end_s);
		} else {
			printf("    GPU timestamps unavailable\n");
		}

		total_count += b->count;
		total_gpu_count += b->gpu_timestamp_count;
		total_gpu_ms += b->gpu_duration_ms;
		if (b->gpu_timestamp_count) {
			if (first_start == 0.0 || b->first_gpu_start_s < first_start)
				first_start = b->first_gpu_start_s;
			if (b->last_gpu_end_s > last_end)
				last_end = b->last_gpu_end_s;
		}
	}

	if (total_count == 0) {
		printf("  SKIPPED — no decode-time CMD3 command buffers recorded\n");
		return;
	}

	double toks = g_cmd1_profile_tokens ? (double)g_cmd1_profile_tokens : 1.0;
	printf("  ----------------------------------------------------------------\n");
	printf("  all CMD3 production buffers: count=%llu, decode_tokens=%llu\n",
		   (unsigned long long)total_count,
		   (unsigned long long)g_cmd1_profile_tokens);

	if (total_gpu_count) {
		double cmd3_per_token = total_gpu_ms / toks;
		printf("    actual CMD3 GPU duration: %.3f ms/token\n", cmd3_per_token);
		printf("    GPU timestamp coverage:   %llu/%llu command buffers\n",
			   (unsigned long long)total_gpu_count,
			   (unsigned long long)total_count);
		printf("    first GPUStartTime:       %.6f s\n", first_start);
		printf("    last GPUEndTime:          %.6f s\n", last_end);

		double cmd1_outside_ms = 0.0;
		for (int type_idx = 0; type_idx < 2; type_idx++) {
			for (int path_idx = 0; path_idx < 2; path_idx++) {
				cmd1_outside_ms += g_cmd1_prod_timing[type_idx][path_idx].outside_gpu_ms;
			}
		}
		double cmd1_outside_per_token = cmd1_outside_ms / toks;
		printf("    CMD1 outside-GPU duration: %.3f ms/token\n", cmd1_outside_per_token);
		printf("    CMD3 GPU - CMD1 outside:   %+.3f ms/token\n",
			   cmd3_per_token - cmd1_outside_per_token);
	}
}

static int metal_wait_command_buffer_checked(id<MTLCommandBuffer> cmd, const char *label) {
	if (!cmd) {
		fprintf(stderr, "ERROR: Metal command buffer is nil (%s)\n", label ? label : "unknown");
		g_forward_error = 1;
		return 0;
	}
	[cmd waitUntilCompleted];
	if (cmd.status != MTLCommandBufferStatusCompleted) {
		NSString *detail = cmd.error.localizedDescription;
		fprintf(stderr, "ERROR: Metal command buffer failed (%s): status=%ld%s%s\n",
				label ? label : "unknown", (long)cmd.status,
				detail.length ? " error=" : "",
				detail.length ? detail.UTF8String : "");
		g_forward_error = 1;
		return 0;
	}
	return 1;
}

// Wait for the deferred GPU expert command buffer to complete.
// Split from finalize so timing can be measured independently.
static int wait_deferred_experts_gpu(void) {
	if (!g_deferred.active) return 1;
	if (!metal_wait_command_buffer_checked(g_deferred.cmd_experts, "CMD3 experts")) {
		g_deferred.active = 0;
		g_deferred.gpu_combined = 0;
		g_deferred.cmd_experts = nil;
		return 0;
	}
	cmd3_production_timing_note_completed();
	return 1;
}

// CPU readback + accumulate + combine after GPU is done.
// Must be called after wait_deferred_experts_gpu().
// When gpu_combined=1, the GPU already computed the combine+residual+norm
// in CMD3, so we just need to read back the hidden state from buf_moe_hidden.
static void finalize_deferred_experts(void) {
	if (!g_deferred.active) return;

	if (g_deferred.gpu_combined) {
		// GPU-side combine: hidden state is already in buf_moe_hidden.
		// buf_input already has the normalized input for the next layer's CMD1.
		// Just read back hidden (needed for the residual connection in future layers).
		memcpy(g_deferred.hidden, [g_metal->buf_moe_hidden contents],
			   HIDDEN_DIM * sizeof(float));
	} else {
		// CPU-side combine (original path)
		// Read back and accumulate routed expert outputs
		float moe_out[HIDDEN_DIM];
		memset(moe_out, 0, sizeof(moe_out));
		for (int k = 0; k < g_deferred.actual_K; k++) {
			if (!g_deferred.valid[k]) continue;
			float *expert_result = (float *)[g_metal->buf_multi_expert_out[k] contents];
			cpu_vec_madd(moe_out, expert_result, g_deferred.expert_weights[k], HIDDEN_DIM);
		}

		// Read shared expert result
		float shared_out[HIDDEN_DIM];
		memcpy(shared_out, [g_metal->buf_shared_out contents], HIDDEN_DIM * sizeof(float));

		// Apply shared expert gate
		float shared_weight = cpu_sigmoid(g_deferred.shared_gate_score);
		for (int i = 0; i < HIDDEN_DIM; i++) {
			shared_out[i] *= shared_weight;
		}

		// Final combine: hidden = h_mid + moe_out + shared_out
		for (int i = 0; i < HIDDEN_DIM; i++) {
			g_deferred.hidden[i] = g_deferred.h_mid[i] + moe_out[i] + shared_out[i];
		}
	}

	g_deferred.active = 0;
	g_deferred.gpu_combined = 0;
	g_deferred.cmd_experts = nil;
}

// Complete the deferred GPU expert compute: wait for GPU, read back, accumulate, combine.
// Must be called before the next layer modifies static scratch buffers.
static int complete_deferred_experts(void) {
	if (!wait_deferred_experts_gpu()) return 0;
	finalize_deferred_experts();
	return !g_forward_error;
}

// Discard the deferred GPU expert result: wait for GPU to finish (for buffer safety)
// but skip the CPU readback/combine. Used during prefill for intermediate tokens
// where the hidden state will be immediately overwritten by the next token's embedding.
// This saves ~0.1-0.2ms per prefill token (avoids unnecessary memcpy + combine work).
static int discard_deferred_experts(void) {
	int ok = wait_deferred_experts_gpu();
	// Clear deferred state without reading back results
	if (g_deferred.active) {
		g_deferred.active = 0;
		g_deferred.gpu_combined = 0;
		g_deferred.cmd_experts = nil;
	}
	return ok && !g_forward_error;
}

// ============================================================================
// Fused layer forward: GPU/CPU overlap + deferred expert pipeline
//
// Pipeline per layer (3 cmd buffers, GPU-side combine in CMD3):
//
//   FAST PATH (when previous CMD3 did GPU-side combine):
//     CMD1: submit immediately (buf_input already populated by CMD3(N-1))
//     WAIT: CMD1 complete (implies CMD3(N-1) also done, queue is serial)
//     CPU:  finalize deferred (read back hidden from buf_moe_hidden)
//
//   SLOW PATH (first layer, or last layer's CMD3 without GPU combine):
//     [DEFERRED] Wait for PREVIOUS layer's CMD3 (if any) + CPU combine
//     CPU:  input_norm(hidden) -> normed -> buf_input
//     CMD1: attention projections (commit)
//     WAIT: CMD1 complete
//
//   Then (both paths):
//     CPU:  attention compute (RoPE/softmax/delta-net)
//     CMD2: o_proj + residual + norm + routing + shared expert projs (8 encoders, 1 commit)
//     WAIT: CMD2 complete
//     CPU:  softmax + top-K routing
//     I/O:  parallel pread K experts (4 pthreads)
//     CMD3: K expert forwards + shared SwiGLU + shared down
//           + moe_combine_residual + rms_norm -> buf_input (ASYNC commit, NO wait)
//     RETURN: GPU experts + combine running async
//
// GPU-side combine eliminates the 0.83ms deferred_wait + CPU combine + input_norm
// at the start of each layer, allowing CMD1 to be submitted immediately.
//
// Key optimizations:
//   1. Parallel pread (4 threads) instead of sequential: ~4x I/O speedup
//   2. o_proj fused into CMD2 with routing (saves 1 commit+wait)
//   3. Deferred CMD3 (expert GPU compute overlapped with next layer)
//   4. GPU-side combine in CMD3 (eliminates CPU deferred_wait + combine + norm)
// ============================================================================

// Static scratch buffers — allocated once, reused across all transformer layers per token.
// Eliminates ~20 malloc/free per layer = ~1200 alloc/free per token.
static float *s_normed    = NULL;   // [HIDDEN_DIM]
static float *s_residual  = NULL;   // [HIDDEN_DIM]
static float *s_attn_proj = NULL;   // [HIDDEN_DIM]
static float *s_h_post    = NULL;   // [HIDDEN_DIM]
static float *s_h_mid     = NULL;   // [HIDDEN_DIM]
static float *s_gate_scores = NULL; // [NUM_EXPERTS]
static float *s_spec_gate_scores = NULL; // [NUM_EXPERTS] speculative routing scratch
static int s_spec_indices[MAX_K];         // speculative routing predicted expert indices
static int s_spec_count = 0;              // number of speculative predictions this layer
static float *s_shared_gate = NULL; // [SHARED_INTERMEDIATE]
static float *s_shared_up  = NULL;  // [SHARED_INTERMEDIATE]
static float *s_moe_out   = NULL;   // [HIDDEN_DIM]
static float *s_shared_out = NULL;  // [HIDDEN_DIM]
// Full attention scratch
static float *s_q_proj_out = NULL;  // [NUM_ATTN_HEADS * HEAD_DIM * 2]
static float *s_k_proj_out = NULL;  // [NUM_KV_HEADS * HEAD_DIM]
static float *s_v_proj_out = NULL;  // [NUM_KV_HEADS * HEAD_DIM]
static float *s_q         = NULL;   // [NUM_ATTN_HEADS * HEAD_DIM]
static float *s_q_gate    = NULL;   // [NUM_ATTN_HEADS * HEAD_DIM]
static float *s_attn_out  = NULL;   // [NUM_ATTN_HEADS * HEAD_DIM]
// Linear attention scratch
static float *s_qkv_proj_out = NULL;   // [LINEAR_CONV_DIM]
static float *s_z_proj_out   = NULL;   // [LINEAR_TOTAL_VALUE]
static float *s_beta_proj_out = NULL;  // [LINEAR_NUM_V_HEADS]
static float *s_alpha_proj_out = NULL; // [LINEAR_NUM_V_HEADS]
static float *s_conv_out  = NULL;   // [LINEAR_CONV_DIM]
static float *s_out_vals  = NULL;   // [LINEAR_TOTAL_VALUE]
static float *s_gated_out = NULL;   // [LINEAR_TOTAL_VALUE]

