#ifdef TARGET_VERIFY_COLD_CACHE
// Benchmark-only per-layer cold-weight staging. A four-position block has at
// most 32 routed experts per layer. Reuse never crosses a layer boundary.
static id<MTLBuffer> g_target_cold_buffers[32];
static int g_target_cold_experts[32];
static int g_target_cold_layer = -1, g_target_cold_count = 0;
static int g_target_cold_active = 0;
static uint64_t g_target_cold_reuses = 0, g_target_cold_loads = 0;

static id<MTLBuffer> target_cold_buffer_for(int layer, int expert, int *hit) {
	*hit = 0;
	if (!g_target_cold_active || !g_metal) return nil;
	if (g_target_cold_layer != layer) {
		g_target_cold_layer = layer;
		g_target_cold_count = 0;
	}
	for (int i = 0; i < g_target_cold_count; i++) {
		if (g_target_cold_experts[i] == expert) {
			*hit = 1;
			g_target_cold_reuses++;
			return g_target_cold_buffers[i];
		}
	}
	if (g_target_cold_count == 32) return nil;
	int slot = g_target_cold_count;
	if (!g_target_cold_buffers[slot]) {
		g_target_cold_buffers[slot] = [g_metal->device
			newBufferWithLength:EXPERT_SIZE_2BIT
			options:MTLResourceStorageModeShared];
		if (!g_target_cold_buffers[slot]) return nil;
	}
	g_target_cold_experts[slot] = expert;
	g_target_cold_count++;
	g_target_cold_loads++;
	return g_target_cold_buffers[slot];
}
#endif

static int init_layer_scratch(void) {
	if (s_normed) return 1;  // already initialized
	s_normed     = calloc(HIDDEN_DIM, sizeof(float));
	s_residual   = calloc(HIDDEN_DIM, sizeof(float));
	s_attn_proj  = calloc(HIDDEN_DIM, sizeof(float));
	s_h_post     = calloc(HIDDEN_DIM, sizeof(float));
	s_h_mid      = calloc(HIDDEN_DIM, sizeof(float));
	s_gate_scores = calloc(NUM_EXPERTS, sizeof(float));
	s_spec_gate_scores = calloc(NUM_EXPERTS, sizeof(float));
	s_shared_gate = calloc(SHARED_INTERMEDIATE, sizeof(float));
	s_shared_up  = calloc(SHARED_INTERMEDIATE, sizeof(float));
	s_moe_out    = calloc(HIDDEN_DIM, sizeof(float));
	s_shared_out = calloc(HIDDEN_DIM, sizeof(float));
	s_q_proj_out = calloc(NUM_ATTN_HEADS * HEAD_DIM * 2, sizeof(float));
	s_k_proj_out = calloc(NUM_KV_HEADS * HEAD_DIM, sizeof(float));
	s_v_proj_out = calloc(NUM_KV_HEADS * HEAD_DIM, sizeof(float));
	s_q          = calloc(NUM_ATTN_HEADS * HEAD_DIM, sizeof(float));
	s_q_gate     = calloc(NUM_ATTN_HEADS * HEAD_DIM, sizeof(float));
	s_attn_out   = calloc(NUM_ATTN_HEADS * HEAD_DIM, sizeof(float));
	s_cpu_attn_scores_capacity = (size_t)(g_kv_seq_len > 0 ? g_kv_seq_len : MAX_SEQ_LEN);
	s_cpu_attn_scores = calloc(s_cpu_attn_scores_capacity, sizeof(float));
	s_qkv_proj_out = calloc(LINEAR_CONV_DIM, sizeof(float));
	s_z_proj_out   = calloc(LINEAR_TOTAL_VALUE, sizeof(float));
	s_beta_proj_out = calloc(LINEAR_NUM_V_HEADS, sizeof(float));
	s_alpha_proj_out = calloc(LINEAR_NUM_V_HEADS, sizeof(float));
	s_conv_out   = calloc(LINEAR_CONV_DIM, sizeof(float));
	s_out_vals   = calloc(LINEAR_TOTAL_VALUE, sizeof(float));
	s_gated_out  = calloc(LINEAR_TOTAL_VALUE, sizeof(float));
	if (s_normed && s_residual && s_attn_proj && s_h_post && s_h_mid &&
		s_gate_scores && s_spec_gate_scores && s_shared_gate && s_shared_up &&
		s_moe_out && s_shared_out && s_q_proj_out && s_k_proj_out &&
		s_v_proj_out && s_q && s_q_gate && s_attn_out && s_cpu_attn_scores &&
		s_qkv_proj_out && s_z_proj_out && s_beta_proj_out && s_alpha_proj_out &&
		s_conv_out && s_out_vals && s_gated_out) {
		return 1;
	}

	fprintf(stderr, "ERROR: layer scratch allocation failed\n");
	free(s_normed); s_normed = NULL;
	free(s_residual); s_residual = NULL;
	free(s_attn_proj); s_attn_proj = NULL;
	free(s_h_post); s_h_post = NULL;
	free(s_h_mid); s_h_mid = NULL;
	free(s_gate_scores); s_gate_scores = NULL;
	free(s_spec_gate_scores); s_spec_gate_scores = NULL;
	free(s_shared_gate); s_shared_gate = NULL;
	free(s_shared_up); s_shared_up = NULL;
	free(s_moe_out); s_moe_out = NULL;
	free(s_shared_out); s_shared_out = NULL;
	free(s_q_proj_out); s_q_proj_out = NULL;
	free(s_k_proj_out); s_k_proj_out = NULL;
	free(s_v_proj_out); s_v_proj_out = NULL;
	free(s_q); s_q = NULL;
	free(s_q_gate); s_q_gate = NULL;
	free(s_attn_out); s_attn_out = NULL;
	free(s_cpu_attn_scores); s_cpu_attn_scores = NULL;
	s_cpu_attn_scores_capacity = 0;
	free(s_qkv_proj_out); s_qkv_proj_out = NULL;
	free(s_z_proj_out); s_z_proj_out = NULL;
	free(s_beta_proj_out); s_beta_proj_out = NULL;
	free(s_alpha_proj_out); s_alpha_proj_out = NULL;
	free(s_conv_out); s_conv_out = NULL;
	free(s_out_vals); s_out_vals = NULL;
	free(s_gated_out); s_gated_out = NULL;
	return 0;
}

static void fused_layer_forward(
	WeightFile *wf,
	int layer_idx,
	float *hidden,           // [HIDDEN_DIM] in/out
	KVCache *kv,             // non-NULL for full attention layers
	LinearAttnState *la_state, // non-NULL for linear attention layers
	int pos,                 // position for RoPE
	const void *mmap_base,   // mmap'd layer file (NULL if not available)
	int K,                   // number of active experts
	int packed_fd            // fd for packed expert file
) {
	// Per-layer quant: temporarily switch to the per-layer expert format
	int saved_use_2bit = g_use_2bit;
	int saved_use_q3_experts = g_use_q3_experts;
	int saved_use_q3_outlier = g_use_q3_outlier;
	if (saved_use_2bit) g_use_2bit = g_layer_is_2bit[layer_idx];
	if (saved_use_q3_experts) {
		g_use_q3_outlier = g_layer_is_q3_outlier[layer_idx];
		g_use_q3_experts = g_layer_is_q3_hybrid[layer_idx] || g_layer_is_q3_outlier[layer_idx];
	}

	double t_layer_start = 0, t0 = 0, t1 = 0;
	if (g_timing_enabled) { t_layer_start = now_ms(); }

	// Detailed pipeline profiling is opt-in. Cache the state once per layer so
	// the normal hot path avoids repeated global checks and performs no profile
	// clocks/GPU-timestamp/decomposition bookkeeping.
	const int pipeline_profile_active =
		g_pipeline_profile_enabled && g_pipeline_profile_decode_active;
	double pipeline_layer_start_ms =
		pipeline_profile_active ? now_ms() : 0.0;
	int pred_started = 0;  // legacy --predict path
	int expert_prefetch_started = 0;
	int expert_prefetch_count = 0;
	int expert_prefetch_experts[MAX_K] = {0};

	if (!init_layer_scratch()) {
		g_forward_error = 1;
		g_use_2bit = saved_use_2bit;
		g_use_q3_outlier = saved_use_q3_outlier;
		g_use_q3_experts = saved_use_q3_experts;
		return;
	}
	if (!layer_cache_built) build_layer_cache(wf);
	LayerWeightCache *lc = &layer_cache[layer_idx];
	int is_full = (kv != NULL);

	// EXPERIMENTAL CONFIDENCE-GATED TEMPORAL PREFETCH.
	// Require a stable expert across recent exact routes before issuing an SSD
	// read, and cap speculative reads per layer. Wrong predictions never enter
	// the cache.
	if (g_expert_prefetch_enabled && g_expert_prefetch_generating &&
		packed_fd >= 0 && g_malloc_cache && g_metal &&
		g_metal->buf_multi_expert_data_B[0] && !g_use_lz4) {
		int selected[MAX_K] = {0};
		int selected_n = expert_prefetch_select(layer_idx, selected, MAX_K);
		g_prefetch_candidates += selected_n;

		for (int p = 0; p < selected_n; p++) {
			int e = selected[p];
			int already_cached = 0;

			// Tiered cold (2-bit) experts intentionally bypass the hot malloc
			// cache, so they remain eligible for scratch prefetch.
			int tiered_cold =
				(g_use_tiered && g_tiered_manifest && TIERED(layer_idx, e).bits == 2);
			if (!tiered_cold) {
				int ci = g_malloc_cache->entry_idx[layer_idx][e];
				already_cached =
					(ci >= 0 && ci < g_malloc_cache->num_entries &&
					 g_malloc_cache->layer_idx[ci] == layer_idx &&
					 g_malloc_cache->expert_idx[ci] == e);
			}

			if (already_cached) {
				g_prefetch_cache_skipped++;
				continue;
			}
			expert_prefetch_experts[expert_prefetch_count++] = e;
		}

		if (expert_prefetch_count > 0) {
			g_prefetch_confident += expert_prefetch_count;
			g_prefetch_predicted += expert_prefetch_count;
			async_pread_start(packed_fd, expert_prefetch_experts,
				expert_prefetch_count, g_metal->buf_multi_expert_data_B,
				mmap_base, layer_idx);
			expert_prefetch_started = 1;
			g_prefetch_reads_started += expert_prefetch_count;
			g_prefetch_layers++;
		}
	}

	// =====================================================================
	// PHASE 1: Deferred completion + CMD1 (attention projections)
	// =====================================================================

	// ---- Prepare attention projection specs (doesn't depend on hidden) ----
	int num_attn_specs = 0;
	BatchMatvecSpec attn_specs[5];
	float *q_proj_out = NULL, *k_out = NULL, *v_out = NULL;
	float *qkv_out = NULL, *z_out = NULL, *beta_out = NULL, *alpha_out = NULL;

	if (is_full) {
		int q_proj_dim = NUM_ATTN_HEADS * HEAD_DIM * 2;
		int kv_dim = NUM_KV_HEADS * HEAD_DIM;

		q_proj_out = s_q_proj_out;
		k_out = s_k_proj_out;
		v_out = s_v_proj_out;

#ifdef FLASH_PREFILL_NROW_ENABLED
		// V4 benchmark hook: Q/K/V for all 16 rows were projected once before
		// entering the row-wise full-attention loop. Consume this row's disjoint
		// slices and suppress CMD1 projection work. Downstream attention/cache
		// semantics remain the ordinary one-row implementation.
		if (g_prefill_nrow_full_qproj && g_prefill_nrow_full_k &&
			g_prefill_nrow_full_v && g_prefill_nrow_capture) {
			int row = g_prefill_nrow_capture->row;
			if (row >= 0 && row < g_prefill_nrow_capture->count) {
				q_proj_out = g_prefill_nrow_full_qproj +
					(size_t)row * q_proj_dim;
				k_out = g_prefill_nrow_full_k + (size_t)row * kv_dim;
				v_out = g_prefill_nrow_full_v + (size_t)row * kv_dim;
			}
		}
#endif

		if (lc->q_w && lc->q_s && lc->q_b && lc->k_w && lc->k_s && lc->k_b &&
			lc->v_w && lc->v_s && lc->v_b) {
			attn_specs[0] = (BatchMatvecSpec){ lc->q_w, lc->q_s, lc->q_b, q_proj_out, (uint32_t)q_proj_dim, HIDDEN_DIM, GROUP_SIZE, 0, lc->q_kind, lc->q_source };
			attn_specs[1] = (BatchMatvecSpec){ lc->k_w, lc->k_s, lc->k_b, k_out,      (uint32_t)kv_dim,     HIDDEN_DIM, GROUP_SIZE, 1, lc->k_kind, lc->k_source };
			attn_specs[2] = (BatchMatvecSpec){ lc->v_w, lc->v_s, lc->v_b, v_out,      (uint32_t)kv_dim,     HIDDEN_DIM, GROUP_SIZE, 2, lc->v_kind, lc->v_source };
			num_attn_specs = 3;
#ifdef FLASH_PREFILL_NROW_ENABLED
			if (g_prefill_nrow_full_qproj && g_prefill_nrow_full_k &&
				g_prefill_nrow_full_v && g_prefill_nrow_capture)
				num_attn_specs = 0;
#endif
		}
	} else {
		int qkv_dim = LINEAR_CONV_DIM;
		int z_dim = LINEAR_TOTAL_VALUE;

		qkv_out = s_qkv_proj_out;
		z_out = s_z_proj_out;
		beta_out = s_beta_proj_out;
		alpha_out = s_alpha_proj_out;

		if (lc->qkv_w && lc->qkv_s && lc->qkv_b && lc->z_w && lc->z_s && lc->z_b &&
			lc->b_w && lc->b_s && lc->b_b && lc->a_w && lc->a_s && lc->a_b) {
			attn_specs[0] = (BatchMatvecSpec){ lc->qkv_w, lc->qkv_s, lc->qkv_b, qkv_out, (uint32_t)qkv_dim, HIDDEN_DIM, GROUP_SIZE, 0, lc->qkv_kind, lc->qkv_source };
			attn_specs[1] = (BatchMatvecSpec){ lc->z_w,   lc->z_s,   lc->z_b,   z_out,      (uint32_t)z_dim,              HIDDEN_DIM, GROUP_SIZE, 1, lc->z_kind, lc->z_source };
			attn_specs[2] = (BatchMatvecSpec){ lc->b_w,   lc->b_s,   lc->b_b,   beta_out,   (uint32_t)LINEAR_NUM_V_HEADS, HIDDEN_DIM, GROUP_SIZE, 2, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF };
			attn_specs[3] = (BatchMatvecSpec){ lc->a_w,   lc->a_s,   lc->a_b,   alpha_out,  (uint32_t)LINEAR_NUM_V_HEADS, HIDDEN_DIM, GROUP_SIZE, 3, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF };
			num_attn_specs = 4;
		}
	}

	// ---- Deferred completion + CMD1 (sequential) ----
	float *normed = s_normed;
	float *residual = s_residual;
	id<MTLCommandBuffer> cmd1 = nil;
	int gpu_linear_attn = 0;  // set to 1 if GPU handles entire linear attention pipeline
	double cmd1_profile_commit_start_ms = 0.0;
	int cmd12_chain_pending = 0;
	int cmd12_chain_from_fast_path = 0;
	int cmd12_full_chain_pending = 0;
	int cmd12_full_chain_from_fast_path = 0;
	int cmd12_full_chain_cache_pos = -1;
	int cmd12_full_chain_fa_idx = -1;

	// Pre-compute linear_layer_idx for GPU linear attention encoding in CMD1
	int linear_layer_idx = -1;
	if (!is_full) {
		linear_layer_idx = layer_idx - (layer_idx + 1) / FULL_ATTN_INTERVAL;
	}
	#ifdef FLASH_PREFILL_NROW_ENABLED
	// The N-row probe already projected QKV and advanced convolution/GDN.
	if (g_prefill_nrow_linear_output && !is_full) num_attn_specs = 0;
	#endif
	// Can we run the full linear attention pipeline on GPU in CMD1?
	int attn_specs_have_q8 = batch_specs_have_q8(attn_specs, num_attn_specs);

	int can_gpu_linear = (gpu_linear_attn_enabled &&
						  !is_full && g_metal && g_metal->delta_net_step &&
						  g_metal->conv1d_step && g_metal->rms_norm_qk &&
						  g_metal->compute_decay_beta && g_metal->gated_rms_norm &&
						  g_metal->wf_buf &&
						  linear_layer_idx >= 0 && linear_layer_idx < g_cfg.num_linear_layers &&
						  lc->conv1d_w && lc->A_log && lc->dt_bias && lc->gated_norm_w &&
						  !attn_specs_have_q8 &&
						  !linear_attn_bypass);

	// Check if previous layer's CMD3 already computed combine+residual+norm on GPU.
	// If so, buf_input already contains the normalized input for this layer's CMD1.
	// We can submit CMD1 immediately — the GPU queue serializes CMD3(N-1) then CMD1(N).
	int prev_gpu_combined = (g_deferred.active && g_deferred.gpu_combined);

	// Full-attention chaining is eligible only when the complete GPU-attention
	// + fused-CMD2 route is known up front. This lets us safely skip the CMD1
	// wait without needing to speculate about a later CPU fallback.
	int can_cmd12_full_chain = 0;
	if (g_cmd12_full_chain_enabled && g_gpu_resident_moe_enabled && is_full && kv &&
		num_attn_specs == 3 && !attn_specs_have_q8 && full_attn_chain_cmd2_prereqs(lc) &&
		kv->k_cache && kv->v_cache && ROTARY_DIM <= 128) {
		int cache_pos = kv->len;
		int seq_len = cache_pos + 1;
		int fa_idx = (layer_idx + 1) / FULL_ATTN_INTERVAL - 1;
		if (cache_pos >= 0 && cache_pos < g_kv_seq_len && cache_pos < GPU_KV_SEQ &&
			seq_len >= 32 && seq_len <= GPU_KV_SEQ &&
			fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers) {
			can_cmd12_full_chain = 1;
			cmd12_full_chain_cache_pos = cache_pos;
			cmd12_full_chain_fa_idx = fa_idx;
		}
	}

	if (prev_gpu_combined && g_metal && g_metal->wf_buf && num_attn_specs > 0 && !attn_specs_have_q8) {
		// ---- FAST PATH: GPU-combined previous CMD3 ----
		// buf_input already has the normalized hidden state from CMD3(N-1).
		// Submit CMD1 immediately — GPU runs CMD3(N-1) then CMD1(N) back-to-back.
		if (g_timing_enabled) { t0 = now_ms(); }

		cmd1 = [g_metal->queue commandBuffer];
		gpu_encode_batch_matvec(g_metal, cmd1, attn_specs, num_attn_specs);

		if (can_cmd12_full_chain) {
			encode_full_attn_prepare(cmd1, lc, cmd12_full_chain_fa_idx,
				cmd12_full_chain_cache_pos, pos);
			cmd12_full_chain_pending = 1;
			cmd12_full_chain_from_fast_path = 1;
		}

		// GPU linear attention: encode conv1d + normalize + decay/beta + delta-net + gated_norm into CMD1
		if (can_gpu_linear && num_attn_specs == 4) {
			// batch_out[0]=qkv(12288), [1]=z(8192), [2]=beta(64), [3]=alpha(64)
			uint32_t conv_dim = LINEAR_CONV_DIM;
			NSUInteger conv_w_off = (NSUInteger)((const char *)lc->conv1d_w - (const char *)[g_metal->wf_buf contents]);

			// Enc L1: conv1d_step — input=batch_out[0], weights=conv1d_w, state=buf_conv_state, output=buf_conv_output
			{
				id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
				[enc setComputePipelineState:g_metal->conv1d_step];
				[enc setBuffer:g_metal->buf_conv_state[linear_layer_idx] offset:0 atIndex:0];
				[enc setBuffer:g_metal->batch_out[0]    offset:0            atIndex:1]; // qkv projection output
				[enc setBuffer:g_metal->wf_buf          offset:conv_w_off   atIndex:2]; // conv weights (bf16)
				[enc setBuffer:g_metal->buf_conv_output offset:0            atIndex:3]; // conv output
				[enc setBytes:&conv_dim length:4 atIndex:4];
				uint32_t tgs = (conv_dim + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}

			// Enc L2: rms_norm_qk — normalize q and k in conv_output in-place
			{
				uint32_t key_dim = LINEAR_KEY_DIM;  // 128
				float inv_scale = 1.0f / sqrtf((float)LINEAR_KEY_DIM);
				id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
				[enc setComputePipelineState:g_metal->rms_norm_qk];
				[enc setBuffer:g_metal->buf_conv_output offset:0 atIndex:0];  // q at offset 0
				[enc setBuffer:g_metal->buf_conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:1];  // k at offset 2048 floats
				[enc setBytes:&key_dim   length:4 atIndex:2];
				[enc setBytes:&inv_scale length:4 atIndex:3];
				[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_K_HEADS, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(LINEAR_KEY_DIM, 1, 1)];
				[enc endEncoding];
			}

			// Enc L3: compute_decay_beta — alpha=batch_out[3], beta=batch_out[2], A_log+dt_bias from wf_buf
			{
				NSUInteger a_log_off   = (NSUInteger)((const char *)lc->A_log   - (const char *)[g_metal->wf_buf contents]);
				NSUInteger dt_bias_off = (NSUInteger)((const char *)lc->dt_bias  - (const char *)[g_metal->wf_buf contents]);
				id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
				[enc setComputePipelineState:g_metal->compute_decay_beta];
				[enc setBuffer:g_metal->batch_out[3]       offset:0          atIndex:0]; // alpha
				[enc setBuffer:g_metal->batch_out[2]       offset:0          atIndex:1]; // beta
				[enc setBuffer:g_metal->wf_buf             offset:a_log_off  atIndex:2]; // A_log
				[enc setBuffer:g_metal->wf_buf             offset:dt_bias_off atIndex:3]; // dt_bias (bf16)
				[enc setBuffer:g_metal->buf_delta_g_decay  offset:0          atIndex:4]; // g_decay output
				[enc setBuffer:g_metal->buf_delta_beta     offset:0          atIndex:5]; // beta_gate output
				[enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)];
				[enc endEncoding];
			}

			// Enc L4: gated_delta_net_step — the main recurrence
			{
				uint32_t khpv = LINEAR_NUM_V_HEADS / LINEAR_NUM_K_HEADS;  // 4
				id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
				[enc setComputePipelineState:g_metal->delta_net_step];
				[enc setBuffer:g_metal->buf_delta_state[linear_layer_idx] offset:0 atIndex:0]; // persistent state
				[enc setBuffer:g_metal->buf_conv_output offset:0 atIndex:1]; // q (first 2048 floats)
				[enc setBuffer:g_metal->buf_conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:2]; // k (next 2048)
				[enc setBuffer:g_metal->buf_conv_output offset:2 * LINEAR_TOTAL_KEY * sizeof(float) atIndex:3]; // v (next 8192)
				[enc setBuffer:g_metal->buf_delta_g_decay offset:0 atIndex:4];
				[enc setBuffer:g_metal->buf_delta_beta    offset:0 atIndex:5];
				[enc setBuffer:g_metal->buf_delta_output  offset:0 atIndex:6]; // output [8192]
				[enc setBytes:&khpv length:sizeof(khpv) atIndex:7];
				[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
				[enc endEncoding];
			}

			// Enc L5: gated_rms_norm — normalize+gate delta-net output -> batch_out[6] for CMD2 o_proj
			{
				NSUInteger gnorm_w_off = (NSUInteger)((const char *)lc->gated_norm_w - (const char *)[g_metal->wf_buf contents]);
				uint32_t value_dim = LINEAR_VALUE_DIM;  // 128
				float eps = RMS_NORM_EPS;
				id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
				[enc setComputePipelineState:g_metal->gated_rms_norm];
				[enc setBuffer:g_metal->buf_delta_output offset:0          atIndex:0]; // values [8192]
				[enc setBuffer:g_metal->batch_out[1]     offset:0          atIndex:1]; // z (z projection output) [8192]
				[enc setBuffer:g_metal->wf_buf           offset:gnorm_w_off atIndex:2]; // weight (bf16)
				[enc setBuffer:g_metal->batch_out[6]     offset:0          atIndex:3]; // output -> batch_out[6] for CMD2
				[enc setBytes:&value_dim length:4 atIndex:4];
				[enc setBytes:&eps       length:4 atIndex:5];
				[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(LINEAR_VALUE_DIM, 1, 1)];
				[enc endEncoding];
			}

			gpu_linear_attn = 1;
		}

		if (g_cmd1_profile_enabled && g_cmd1_profile_decode_active)
			cmd1_profile_commit_start_ms = now_ms();
		[cmd1 commit];

		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_submit += t1 - t0; }

		cmd12_chain_pending =
			g_cmd12_chain_enabled &&
			gpu_linear_attn &&
			g_gpu_resident_moe_enabled;
		cmd12_chain_from_fast_path = cmd12_chain_pending ? 1 : 0;

		if (!cmd12_chain_pending && !cmd12_full_chain_pending) {
			// Normal behavior: CMD1 wait also completes preceding CMD3 on this serial queue.
			if (g_timing_enabled) { t0 = now_ms(); }
			if (!metal_wait_command_buffer_checked(cmd1, "CMD1")) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
			if (cmd1_profile_commit_start_ms > 0.0) {
				double cmd1_profile_complete_ms = now_ms();
				cmd1_production_timing_note(
					cmd1, is_full, 1,
					cmd1_profile_complete_ms - cmd1_profile_commit_start_ms);
				cmd1_profile_commit_start_ms = 0.0;
			}
			if (!gpu_linear_attn) {
				gpu_flush_batch_results(g_metal, attn_specs, num_attn_specs);
			}
			if (g_tiny_matvec_telemetry_enabled && !tiny_replay_32x2048.valid &&
				num_attn_specs == 4 && tiny_matvec_target_shape(&attn_specs[2]) == 32) {
				tiny_matvec_capture_sample(g_metal, &tiny_replay_32x2048,
					&attn_specs[2], (const float *)[g_metal->buf_input contents], "beta");
			}
			if (gpu_linear_attn) {
				cmd1_linear_detail_capture(g_metal, lc, layer_idx, linear_layer_idx);
			}
			cmd1_profile_note_layer(g_metal, layer_idx, is_full, attn_specs, num_attn_specs,
				(const float *)[g_metal->buf_input contents]);
			if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_wait += t1 - t0; }

			if (g_timing_enabled) { t0 = now_ms(); }
			if (!complete_deferred_experts()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
			if (g_pred_enabled && g_pred_generating && g_pred_valid && packed_fd >= 0 &&
				g_metal->buf_multi_expert_data_B[0] && g_pred_count[layer_idx] > 0) {
				async_pread_start(packed_fd, g_pred_experts[layer_idx],
								  g_pred_count[layer_idx],
								  g_metal->buf_multi_expert_data_B, mmap_base, layer_idx);
				pred_started = 1;
			}
			cpu_vec_copy(residual, hidden, HIDDEN_DIM);
			if (g_timing_enabled) { t1 = now_ms(); g_timing.deferred_cpu += t1 - t0; }
		}
		// Chained case intentionally leaves previous CMD3 deferred. CMD2 reads
		// its GPU-resident residual directly and the existing CMD2 wait later
		// establishes completion of CMD3(N-1) -> CMD1(N) -> CMD2(N).
	} else {
		// ---- ORIGINAL PATH: CPU deferred completion + input norm ----
		// Complete deferred experts from previous layer
		if (g_timing_enabled) { t0 = now_ms(); }
		if (!wait_deferred_experts_gpu()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.deferred_wait += t1 - t0; }

		if (g_timing_enabled) { t0 = now_ms(); }
		finalize_deferred_experts();
		if (g_timing_enabled) { t1 = now_ms(); g_timing.deferred_cpu += t1 - t0; }

		// Input norm
		if (g_timing_enabled) { t0 = now_ms(); }
		cpu_vec_copy(residual, hidden, HIDDEN_DIM);
		cpu_rms_norm(hidden, lc->input_norm_w, normed, HIDDEN_DIM, RMS_NORM_EPS);
		if (g_tiny_matvec_telemetry_enabled && !tiny_replay_32x2048.valid &&
			num_attn_specs == 4 && tiny_matvec_target_shape(&attn_specs[2]) == 32) {
			// Race-free: normed is a CPU array and is exactly what is copied to
			// buf_input immediately below for this production CMD1.
			tiny_matvec_capture_sample(g_metal, &tiny_replay_32x2048,
				&attn_specs[2], normed, "beta");
		}
		cmd1_profile_note_layer(g_metal, layer_idx, is_full, attn_specs, num_attn_specs, normed);
		if (g_timing_enabled) { t1 = now_ms(); g_timing.input_norm += t1 - t0; }

		// Submit CMD1: attention projections
		if (g_timing_enabled) { t0 = now_ms(); }
		if (g_metal && g_metal->wf_buf && num_attn_specs > 0 && !attn_specs_have_q8) {
			memcpy([g_metal->buf_input contents], normed, HIDDEN_DIM * sizeof(float));
			cmd1 = [g_metal->queue commandBuffer];
			gpu_encode_batch_matvec(g_metal, cmd1, attn_specs, num_attn_specs);

			if (can_cmd12_full_chain) {
				encode_full_attn_prepare(cmd1, lc, cmd12_full_chain_fa_idx,
					cmd12_full_chain_cache_pos, pos);
				cmd12_full_chain_pending = 1;
				cmd12_full_chain_from_fast_path = 0;
			}

			// GPU linear attention: encode conv1d + normalize + decay/beta + delta-net + gated_norm into CMD1
			if (can_gpu_linear && num_attn_specs == 4) {
				uint32_t conv_dim = LINEAR_CONV_DIM;
				NSUInteger conv_w_off = (NSUInteger)((const char *)lc->conv1d_w - (const char *)[g_metal->wf_buf contents]);

				// Enc L1: conv1d_step
				{
					id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
					[enc setComputePipelineState:g_metal->conv1d_step];
					[enc setBuffer:g_metal->buf_conv_state[linear_layer_idx] offset:0 atIndex:0];
					[enc setBuffer:g_metal->batch_out[0]    offset:0            atIndex:1];
					[enc setBuffer:g_metal->wf_buf          offset:conv_w_off   atIndex:2];
					[enc setBuffer:g_metal->buf_conv_output offset:0            atIndex:3];
					[enc setBytes:&conv_dim length:4 atIndex:4];
					uint32_t tgs = (conv_dim + 255) / 256;
					[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
					[enc endEncoding];
				}

				// Enc L2: rms_norm_qk
				{
					uint32_t key_dim = LINEAR_KEY_DIM;
					float inv_scale = 1.0f / sqrtf((float)LINEAR_KEY_DIM);
					id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
					[enc setComputePipelineState:g_metal->rms_norm_qk];
					[enc setBuffer:g_metal->buf_conv_output offset:0 atIndex:0];
					[enc setBuffer:g_metal->buf_conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:1];
					[enc setBytes:&key_dim   length:4 atIndex:2];
					[enc setBytes:&inv_scale length:4 atIndex:3];
					[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_K_HEADS, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(LINEAR_KEY_DIM, 1, 1)];
					[enc endEncoding];
				}

				// Enc L3: compute_decay_beta
				{
					NSUInteger a_log_off   = (NSUInteger)((const char *)lc->A_log   - (const char *)[g_metal->wf_buf contents]);
					NSUInteger dt_bias_off = (NSUInteger)((const char *)lc->dt_bias  - (const char *)[g_metal->wf_buf contents]);
					id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
					[enc setComputePipelineState:g_metal->compute_decay_beta];
					[enc setBuffer:g_metal->batch_out[3]       offset:0          atIndex:0];
					[enc setBuffer:g_metal->batch_out[2]       offset:0          atIndex:1];
					[enc setBuffer:g_metal->wf_buf             offset:a_log_off  atIndex:2];
					[enc setBuffer:g_metal->wf_buf             offset:dt_bias_off atIndex:3];
					[enc setBuffer:g_metal->buf_delta_g_decay  offset:0          atIndex:4];
					[enc setBuffer:g_metal->buf_delta_beta     offset:0          atIndex:5];
					[enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)];
					[enc endEncoding];
				}

				// Enc L4: gated_delta_net_step
				{
					uint32_t khpv = LINEAR_NUM_V_HEADS / LINEAR_NUM_K_HEADS;
					id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
					[enc setComputePipelineState:g_metal->delta_net_step];
					[enc setBuffer:g_metal->buf_delta_state[linear_layer_idx] offset:0 atIndex:0];
					[enc setBuffer:g_metal->buf_conv_output offset:0 atIndex:1];
					[enc setBuffer:g_metal->buf_conv_output offset:LINEAR_TOTAL_KEY * sizeof(float) atIndex:2];
					[enc setBuffer:g_metal->buf_conv_output offset:2 * LINEAR_TOTAL_KEY * sizeof(float) atIndex:3];
					[enc setBuffer:g_metal->buf_delta_g_decay offset:0 atIndex:4];
					[enc setBuffer:g_metal->buf_delta_beta    offset:0 atIndex:5];
					[enc setBuffer:g_metal->buf_delta_output  offset:0 atIndex:6];
					[enc setBytes:&khpv length:sizeof(khpv) atIndex:7];
					[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
					[enc endEncoding];
				}

				// Enc L5: gated_rms_norm -> batch_out[6]
				{
					NSUInteger gnorm_w_off = (NSUInteger)((const char *)lc->gated_norm_w - (const char *)[g_metal->wf_buf contents]);
					uint32_t value_dim = LINEAR_VALUE_DIM;
					float eps = RMS_NORM_EPS;
					id<MTLComputeCommandEncoder> enc = [cmd1 computeCommandEncoder];
					[enc setComputePipelineState:g_metal->gated_rms_norm];
					[enc setBuffer:g_metal->buf_delta_output offset:0          atIndex:0];
					[enc setBuffer:g_metal->batch_out[1]     offset:0          atIndex:1];
					[enc setBuffer:g_metal->wf_buf           offset:gnorm_w_off atIndex:2];
					[enc setBuffer:g_metal->batch_out[6]     offset:0          atIndex:3];
					[enc setBytes:&value_dim length:4 atIndex:4];
					[enc setBytes:&eps       length:4 atIndex:5];
					[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(LINEAR_VALUE_DIM, 1, 1)];
					[enc endEncoding];
				}

				gpu_linear_attn = 1;
			}

			if (g_cmd1_profile_enabled && g_cmd1_profile_decode_active)
				cmd1_profile_commit_start_ms = now_ms();
			[cmd1 commit];
		} else {
			fast_batch_matvec(normed, HIDDEN_DIM, attn_specs, num_attn_specs);
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_submit += t1 - t0; }

		if (cmd1 &&
			g_cmd12_chain_enabled &&
			gpu_linear_attn &&
			g_gpu_resident_moe_enabled) {
			cmd12_chain_pending = 1;
			cmd12_chain_from_fast_path = 0;
		}
		if (!cmd12_chain_pending && !cmd12_full_chain_pending) {
			if (g_timing_enabled) { t0 = now_ms(); }
			if (cmd1) {
				if (!metal_wait_command_buffer_checked(cmd1, "CMD1")) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
				if (cmd1_profile_commit_start_ms > 0.0) {
					double cmd1_profile_complete_ms = now_ms();
					cmd1_production_timing_note(
						cmd1, is_full, 0,
						cmd1_profile_complete_ms - cmd1_profile_commit_start_ms);
					cmd1_profile_commit_start_ms = 0.0;
				}
				if (!gpu_linear_attn) {
					gpu_flush_batch_results(g_metal, attn_specs, num_attn_specs);
				}
				if (gpu_linear_attn) {
					cmd1_linear_detail_capture(g_metal, lc, layer_idx, linear_layer_idx);
				}
			}
			if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_wait += t1 - t0; }
		}
	}

	// =====================================================================
	// SPECULATIVE EARLY ROUTING — overlap expert I/O with CPU attention
	// =====================================================================
	// Compute approximate routing using the PRE-attention normed hidden state.
	// The real routing (in CMD2/PHASE 3) uses the POST-attention state, so this
	// is an approximation. Fire off async pread for predicted cache misses via
	// dispatch_group so the I/O runs concurrently with CPU attention compute.
	// After CPU attention, we wait for the group to finish. When the real routing
	// happens later, predicted experts are already in the LRU cache as hits.

	dispatch_group_t spec_group = NULL;
	int spec_preload_count = 0;
	int spec_routing_enabled = 0;  // DISABLED: cache pollution + overhead makes it slower

	if (g_timing_enabled) { t0 = now_ms(); }
	s_spec_count = 0;

	if (spec_routing_enabled && (g_expert_cache || g_malloc_cache) && packed_fd >= 0 && lc->gate_w) {
		float *spec_scores = s_spec_gate_scores;
		memset(spec_scores, 0, NUM_EXPERTS * sizeof(float));

		// Gate projection matvec on pre-attention normed input (CPU, ~0.1ms for 512x4096)
		cpu_dequant_matvec(lc->gate_w, lc->gate_s, lc->gate_b,
						   normed, spec_scores,
						   NUM_EXPERTS, HIDDEN_DIM, GROUP_SIZE);
		int spec_K = (K > MAX_K) ? MAX_K : K;
		float spec_weights[MAX_K];
		cpu_topk_softmax_raw(spec_scores, NUM_EXPERTS, spec_K, s_spec_indices, spec_weights);
		s_spec_count = spec_K;

		g_spec_route_attempts += spec_K;

		// Initialize GCD queue if needed
		if (!g_io_gcd_queue)
			g_io_gcd_queue = dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0);

		// Check cache for each predicted expert, start async I/O for misses
		size_t spec_esz = active_expert_size();
		if (g_malloc_cache) {
			spec_group = dispatch_group_create();
			for (int k = 0; k < spec_K; k++) {
				int eidx = s_spec_indices[k];
				id<MTLBuffer> cached = malloc_cache_lookup(g_malloc_cache, layer_idx, eidx);
				if (!cached) {
					int cidx = -1;
					id<MTLBuffer> buf = malloc_cache_insert(g_malloc_cache, layer_idx, eidx, &cidx);
					if (buf && cidx >= 0) {
						int fd_copy = packed_fd;
						void *dst = g_malloc_cache->data[cidx];
						off_t offset = (off_t)eidx * spec_esz;
						size_t sz = spec_esz;
						dispatch_group_async(spec_group, g_io_gcd_queue, ^{
							pread(fd_copy, dst, sz, offset);
						});
						spec_preload_count++;
						g_spec_route_preloads++;
					}
				}
			}
		} else if (g_expert_cache) {
			spec_group = dispatch_group_create();
			for (int k = 0; k < spec_K; k++) {
				int eidx = s_spec_indices[k];
				id<MTLBuffer> cached = expert_cache_lookup(g_expert_cache, layer_idx, eidx);
				if (!cached) {
					id<MTLBuffer> buf = expert_cache_insert(g_expert_cache, layer_idx, eidx);
					if (buf) {
						int fd_copy = packed_fd;
						void *dst = [buf contents];
						off_t offset = (off_t)eidx * spec_esz;
						size_t sz = spec_esz;
						dispatch_group_async(spec_group, g_io_gcd_queue, ^{
							pread(fd_copy, dst, sz, offset);
						});
						spec_preload_count++;
						g_spec_route_preloads++;
					}
				}
			}
		}
	}
	(void)spec_preload_count;  // tracked via g_spec_route_preloads

	if (g_timing_enabled) { t1 = now_ms(); g_timing.spec_route += t1 - t0; }

	// =====================================================================
	// PHASE 2: CPU attention compute
	// =====================================================================

	if (g_timing_enabled) { t0 = now_ms(); }

	float *attn_projected = s_attn_proj;
	memset(attn_projected, 0, HIDDEN_DIM * sizeof(float));

	// Pre-lookup o_proj / out_proj weights (used after attention compute)
	// These are looked up NOW to avoid repeated snprintf later.
	uint32_t *oproj_w = NULL;
	uint16_t *oproj_s = NULL, *oproj_b = NULL;
	int oproj_in_dim = 0;
	uint8_t oproj_kind = MATVEC_KIND_MLX4;
	uint8_t oproj_source = MATVEC_SOURCE_WF;

	if (is_full) {
		oproj_w = lc->o_w; oproj_s = lc->o_s; oproj_b = lc->o_b;
		oproj_in_dim = NUM_ATTN_HEADS * HEAD_DIM;
		oproj_kind = lc->o_kind;
		oproj_source = lc->o_source;
	} else if (!linear_attn_bypass) {
		oproj_w = lc->out_proj_w; oproj_s = lc->out_proj_s; oproj_b = lc->out_proj_b;
		oproj_in_dim = LINEAR_TOTAL_VALUE;
		oproj_kind = lc->out_proj_kind;
		oproj_source = lc->out_proj_source;
	}

	// All MoE weight pointers from cache (zero snprintf overhead)
	uint32_t *gate_w = lc->gate_w; uint16_t *gate_s = lc->gate_s, *gate_b = lc->gate_b;
	uint32_t *sgw = lc->sg_w;     uint16_t *sgs = lc->sg_s,       *sgb = lc->sg_b;
	uint32_t *suw = lc->su_w;     uint16_t *sus = lc->su_s,       *sub = lc->su_b;
	uint32_t *seg_w = lc->seg_w;  uint16_t *seg_s = lc->seg_s,   *seg_b = lc->seg_b;
	uint32_t *sdw = lc->sd_w;     uint16_t *sds = lc->sd_s,       *sdb = lc->sd_b;
	uint8_t sg_kind = lc->sg_kind;
	uint8_t su_kind = lc->su_kind;
	uint8_t sd_kind = lc->sd_kind;
	uint8_t sg_source = lc->sg_source;
	uint8_t su_source = lc->su_source;
	uint8_t sd_source = lc->sd_source;
	int shared_override_active =
		(sg_source == MATVEC_SOURCE_GGUF_SHARED) ||
		(su_source == MATVEC_SOURCE_GGUF_SHARED) ||
		(sd_source == MATVEC_SOURCE_GGUF_SHARED);

	// ---- CPU attention compute (produces attn_out for o_proj) ----
	float *attn_out_for_oproj = NULL;
	int full_attn_seq_pos = -1;

#ifdef FLASH_PREFILL_NROW_ENABLED
	if (is_full && g_prefill_nrow_full_attn_out && g_prefill_nrow_capture) {
		// N128 candidate: causal attention for all slab rows was computed once
		// before the row-wise o_proj/residual/routing path. Consume this row's
		// pre-gated attention vector and do not mutate KV length again here.
		int row = g_prefill_nrow_capture->row;
		if (row < 0 || row >= g_prefill_nrow_capture->count) {
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		attn_out_for_oproj = g_prefill_nrow_full_attn_out +
			(size_t)row * (NUM_ATTN_HEADS * HEAD_DIM);
		full_attn_seq_pos = kv->len - g_prefill_nrow_capture->count + row;
	}
	else
#endif
	if (is_full && cmd12_full_chain_pending) {
		// ---- Full attention GPU-prepared path ----
		// CMD1 writes normalized/rotated Q, Q gate, and this token's K/V into
		// the GPU mirror. Publish the logical length now so CMD2 attends through
		// the current token. CPU K/V is synchronized only after CMD2 completes.
		full_attn_seq_pos = cmd12_full_chain_cache_pos;
		kv->len = cmd12_full_chain_cache_pos + 1;
		attn_out_for_oproj = NULL;
	} else if (is_full) {
		// ---- Full attention CPU compute ----
#ifdef FLASH_PREFILL_NROW_ENABLED
		double nrow_fa_qk_started = g_prefill_nrow_capture ? now_ms() : 0.0;
#endif
		int q_proj_dim = NUM_ATTN_HEADS * HEAD_DIM * 2;
		int q_dim = NUM_ATTN_HEADS * HEAD_DIM;
		int kv_dim = NUM_KV_HEADS * HEAD_DIM;
		(void)q_proj_dim;

		float *q = s_q;
		float *q_gate = s_q_gate;
		for (int h = 0; h < NUM_ATTN_HEADS; h++) {
			float *src = q_proj_out + h * (2 * HEAD_DIM);
			memcpy(q + h * HEAD_DIM, src, HEAD_DIM * sizeof(float));
			memcpy(q_gate + h * HEAD_DIM, src + HEAD_DIM, HEAD_DIM * sizeof(float));
		}

		// Q/K RMSNorm
		uint16_t *qnorm_w = lc->q_norm_w;
		uint16_t *knorm_w = lc->k_norm_w;
		if (qnorm_w) {
			for (int h = 0; h < NUM_ATTN_HEADS; h++) {
				float *qh = q + h * HEAD_DIM;
				float sum_sq = 0.0f;
				for (int i = 0; i < HEAD_DIM; i++) sum_sq += qh[i] * qh[i];
				float inv_rms = 1.0f / sqrtf(sum_sq / HEAD_DIM + RMS_NORM_EPS);
				for (int i = 0; i < HEAD_DIM; i++) qh[i] = qh[i] * inv_rms * bf16_to_f32(qnorm_w[i]);
			}
		}
		if (knorm_w) {
			for (int h = 0; h < NUM_KV_HEADS; h++) {
				float *kh = k_out + h * HEAD_DIM;
				float sum_sq = 0.0f;
				for (int i = 0; i < HEAD_DIM; i++) sum_sq += kh[i] * kh[i];
				float inv_rms = 1.0f / sqrtf(sum_sq / HEAD_DIM + RMS_NORM_EPS);
				for (int i = 0; i < HEAD_DIM; i++) kh[i] = kh[i] * inv_rms * bf16_to_f32(knorm_w[i]);
			}
		}

		// RoPE
		apply_rotary_emb(q, k_out, pos, NUM_ATTN_HEADS, NUM_KV_HEADS, HEAD_DIM, ROTARY_DIM);
#ifdef FLASH_PREFILL_NROW_ENABLED
		if (g_prefill_nrow_capture)
			g_prefill_nrow_prof_qk_rope_ms += now_ms() - nrow_fa_qk_started;
		double nrow_fa_kv_started = g_prefill_nrow_capture ? now_ms() : 0.0;
#endif

		// Update KV cache (CPU + GPU mirror)
		int cache_pos = kv->len;
		if (!kv->k_cache || !kv->v_cache) {
			fprintf(stderr, "ERROR: KV cache is NULL (allocation failed)\n");
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		if (cache_pos >= g_kv_seq_len) {
			fprintf(stderr, "ERROR: KV cache overflow (pos=%d >= max=%d)\n", cache_pos, g_kv_seq_len);
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		full_attn_seq_pos = cache_pos;
		memcpy(kv->k_cache + cache_pos * kv_dim, k_out, kv_dim * sizeof(float));
		memcpy(kv->v_cache + cache_pos * kv_dim, v_out, kv_dim * sizeof(float));

		int fa_idx = (layer_idx + 1) / FULL_ATTN_INTERVAL - 1;
		if (g_metal && g_metal->attn_scores_pipe && fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers && cache_pos < GPU_KV_SEQ) {
			memcpy((float *)[g_metal->buf_kv_k[fa_idx] contents] + cache_pos * kv_dim,
				   k_out, kv_dim * sizeof(float));
			memcpy((float *)[g_metal->buf_kv_v[fa_idx] contents] + cache_pos * kv_dim,
				   v_out, kv_dim * sizeof(float));
		}
		kv->len++;
#ifdef FLASH_PREFILL_NROW_ENABLED
		if (g_prefill_nrow_capture)
			g_prefill_nrow_prof_kv_publish_ms += now_ms() - nrow_fa_kv_started;
		double nrow_fa_attn_started = g_prefill_nrow_capture ? now_ms() : 0.0;
#endif

		// Scaled dot-product attention (GQA) — GPU or CPU
		int heads_per_kv = NUM_ATTN_HEADS / NUM_KV_HEADS;
		float scale = 1.0f / sqrtf((float)HEAD_DIM);
		float *attn_out = s_attn_out;
		memset(attn_out, 0, q_dim * sizeof(float));

		// GPU attention: defer dispatches to CMD2 (fused into single cmd buffer).
		// Only enabled when seq_len >= 32 (below that, CPU is faster).
		int gpu_attn_ready = (g_metal && g_metal->attn_scores_pipe &&
							  lc->o_kind != MATVEC_KIND_GGUF_Q8_0 &&
							  fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers &&
							  kv->len >= 32 && kv->len <= GPU_KV_SEQ);

		if (gpu_attn_ready) {
			// Copy Q and gate to GPU; attention dispatches will be in CMD2
			memcpy([g_metal->buf_attn_q contents], q, q_dim * sizeof(float));
			memcpy([g_metal->buf_attn_gate contents], q_gate, q_dim * sizeof(float));
			// attn_out_for_oproj will be set to NULL below — CMD2 reads buf_attn_out
		} else {
			// CPU fallback
			for (int h = 0; h < NUM_ATTN_HEADS; h++) {
				int kv_h = h / heads_per_kv;
				float *qh = q + h * HEAD_DIM;
		if ((size_t)kv->len > s_cpu_attn_scores_capacity) {
			s_cpu_attn_scores_capacity = (size_t)kv->len;
			float *new_scores = realloc(s_cpu_attn_scores,
										  s_cpu_attn_scores_capacity * sizeof(float));
			if (!new_scores) {
				fprintf(stderr, "ERROR: CPU attention score realloc failed\n");
				g_forward_error = 1;
				g_use_2bit = saved_use_2bit;
				g_use_q3_outlier = saved_use_q3_outlier;
				g_use_q3_experts = saved_use_q3_experts;
				return;
			}
			s_cpu_attn_scores = new_scores;
		}
		float *scores = s_cpu_attn_scores;
				for (int p = 0; p < kv->len; p++) {
					float *kp = kv->k_cache + p * kv_dim + kv_h * HEAD_DIM;
					float dot = 0.0f;
					for (int d = 0; d < HEAD_DIM; d++) dot += qh[d] * kp[d];
					scores[p] = dot * scale;
				}
				cpu_softmax(scores, kv->len);
				float *oh = attn_out + h * HEAD_DIM;
				for (int p = 0; p < kv->len; p++) {
					float *vp = kv->v_cache + p * kv_dim + kv_h * HEAD_DIM;
					for (int d = 0; d < HEAD_DIM; d++) oh[d] += scores[p] * vp[d];
				}
			}
			for (int i = 0; i < q_dim; i++) {
				float g = 1.0f / (1.0f + expf(-q_gate[i]));
				attn_out[i] *= g;
			}
		}

		if (gpu_attn_ready) {
			attn_out_for_oproj = NULL;  // signal CMD2 to use GPU buf_attn_out
		} else {
			attn_out_for_oproj = attn_out;
		}
#ifdef FLASH_PREFILL_NROW_ENABLED
		if (g_prefill_nrow_capture) {
			g_prefill_nrow_prof_attn_prep_ms += now_ms() - nrow_fa_attn_started;
			g_prefill_nrow_prof_full_rows++;
			if (gpu_attn_ready) g_prefill_nrow_prof_gpu_attn_rows++;
			else g_prefill_nrow_prof_cpu_attn_rows++;
		}
#endif
		// q_proj_out, k_out, v_out, q, q_gate, attn_out are static scratch.
	}
	#ifdef FLASH_PREFILL_NROW_ENABLED
	else if (g_prefill_nrow_linear_output) {
		attn_out_for_oproj = g_prefill_nrow_linear_output +
			(size_t)g_prefill_nrow_capture->row * LINEAR_TOTAL_VALUE;
	}
	#endif
	else if (gpu_linear_attn) {
		// ---- GPU linear attention: already computed in CMD1 ----
		// batch_out[6] already contains gated_rms_norm output (8192 floats)
		// Set a non-NULL sentinel so CMD2 enters fused path, but skip the memcpy
		static float gpu_linear_sentinel;
		attn_out_for_oproj = &gpu_linear_sentinel;
	} else {
		// ---- Linear attention CPU compute ----
		if (!linear_attn_bypass) {
			int qkv_dim = LINEAR_CONV_DIM;

			// Conv1d step
			uint16_t *conv_w = lc->conv1d_w;
			float *conv_out = s_conv_out;
			memset(conv_out, 0, qkv_dim * sizeof(float));
			if (conv_w) {
				cpu_conv1d_step(la_state->conv_state, qkv_out, conv_w, conv_out,
								qkv_dim, CONV_KERNEL_SIZE);
			}
			// Update conv state
			memmove(la_state->conv_state, la_state->conv_state + qkv_dim,
					(CONV_KERNEL_SIZE - 2) * qkv_dim * sizeof(float));
			memcpy(la_state->conv_state + (CONV_KERNEL_SIZE - 2) * qkv_dim, qkv_out,
				   qkv_dim * sizeof(float));

			// Split into q, k, v
			float *lin_q = conv_out;
			float *lin_k = conv_out + LINEAR_TOTAL_KEY;
			float *lin_v = conv_out + 2 * LINEAR_TOTAL_KEY;

			// RMS normalize q and k
			float inv_scale = 1.0f / sqrtf((float)LINEAR_KEY_DIM);
			for (int h = 0; h < LINEAR_NUM_K_HEADS; h++) {
				float *qh = lin_q + h * LINEAR_KEY_DIM;
				cpu_rms_norm_bare(qh, qh, LINEAR_KEY_DIM, 1e-6f);
				float q_scale = inv_scale * inv_scale;
				for (int d = 0; d < LINEAR_KEY_DIM; d++) qh[d] *= q_scale;
			}
			for (int h = 0; h < LINEAR_NUM_K_HEADS; h++) {
				float *kh = lin_k + h * LINEAR_KEY_DIM;
				cpu_rms_norm_bare(kh, kh, LINEAR_KEY_DIM, 1e-6f);
				for (int d = 0; d < LINEAR_KEY_DIM; d++) kh[d] *= inv_scale;
			}

			// Gated delta net recurrence
			float *A_log = lc->A_log;
			uint16_t *dt_bias_bf16 = lc->dt_bias;

			float *out_values = s_out_vals;
			memset(out_values, 0, LINEAR_TOTAL_VALUE * sizeof(float));
			int k_heads_per_v = LINEAR_NUM_V_HEADS / LINEAR_NUM_K_HEADS;

			float g_decay[LINEAR_NUM_V_HEADS];
			float beta_gate_arr[LINEAR_NUM_V_HEADS];
			for (int vh = 0; vh < LINEAR_NUM_V_HEADS; vh++) {
				float a_val = alpha_out[vh];
				float dt_b = dt_bias_bf16 ? bf16_to_f32(dt_bias_bf16[vh]) : 0.0f;
				float A_val = A_log ? expf(A_log[vh]) : 1.0f;
				float softplus_val = softplusf_stable(a_val + dt_b);
				g_decay[vh] = expf(-A_val * softplus_val);
				beta_gate_arr[vh] = cpu_sigmoid(beta_out[vh]);
			}

			// Compute linear_layer_idx: count of non-full-attention layers before this one.
			// Full attention at (layer_idx+1) % 4 == 0, i.e. layers 3,7,11,...
			// linear_layer_idx = layer_idx - number_of_full_layers_at_or_before
			//                  = layer_idx - (layer_idx + 1) / FULL_ATTN_INTERVAL
			int linear_layer_idx = layer_idx - (layer_idx + 1) / FULL_ATTN_INTERVAL;

			// GPU delta-net path (falls back to CPU if pipeline unavailable)
			if (snapshot_uses_gpu_linear_state() &&
				linear_layer_idx >= 0 && linear_layer_idx < g_cfg.num_linear_layers) {
				// Upload CPU-computed data to GPU scratch buffers
				memcpy([g_metal->buf_delta_q contents], lin_q, LINEAR_TOTAL_KEY * sizeof(float));
				memcpy([g_metal->buf_delta_k contents], lin_k, LINEAR_TOTAL_KEY * sizeof(float));
				memcpy([g_metal->buf_delta_v contents], lin_v, LINEAR_TOTAL_VALUE * sizeof(float));
				memcpy([g_metal->buf_delta_g_decay contents], g_decay, LINEAR_NUM_V_HEADS * sizeof(float));
				memcpy([g_metal->buf_delta_beta contents], beta_gate_arr, LINEAR_NUM_V_HEADS * sizeof(float));

				id<MTLCommandBuffer> cmd_dn = [g_metal->queue commandBuffer];
				id<MTLComputeCommandEncoder> enc = [cmd_dn computeCommandEncoder];
				[enc setComputePipelineState:g_metal->delta_net_step];
				[enc setBuffer:g_metal->buf_delta_state[linear_layer_idx] offset:0 atIndex:0];
				[enc setBuffer:g_metal->buf_delta_q       offset:0 atIndex:1];
				[enc setBuffer:g_metal->buf_delta_k       offset:0 atIndex:2];
				[enc setBuffer:g_metal->buf_delta_v       offset:0 atIndex:3];
				[enc setBuffer:g_metal->buf_delta_g_decay offset:0 atIndex:4];
				[enc setBuffer:g_metal->buf_delta_beta    offset:0 atIndex:5];
				[enc setBuffer:g_metal->buf_delta_output  offset:0 atIndex:6];
				uint32_t khpv = (uint32_t)k_heads_per_v;
				[enc setBytes:&khpv length:sizeof(khpv) atIndex:7];
				[enc dispatchThreadgroups:MTLSizeMake(LINEAR_NUM_V_HEADS, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(128, 1, 1)];
				[enc endEncoding];
				[cmd_dn commit];
				[cmd_dn waitUntilCompleted];

				// Read back GPU result
				memcpy(out_values, [g_metal->buf_delta_output contents], LINEAR_TOTAL_VALUE * sizeof(float));
			} else {
				// CPU delta-net with Accelerate BLAS
				for (int vh = 0; vh < LINEAR_NUM_V_HEADS; vh++) {
					int kh = vh / k_heads_per_v;
					float g = g_decay[vh];
					float b_gate = beta_gate_arr[vh];
					float *S = la_state->ssm_state + vh * LINEAR_VALUE_DIM * LINEAR_KEY_DIM;
					float *v_h = lin_v + vh * LINEAR_VALUE_DIM;
					float *k_h = lin_k + kh * LINEAR_KEY_DIM;

					// Step 1: Decay S *= g (BLAS sscal on entire state matrix)
					cblas_sscal(LINEAR_VALUE_DIM * LINEAR_KEY_DIM, g, S, 1);

					// Step 2: kv_mem = S @ k (each row dot k)
					// S is [VALUE_DIM x KEY_DIM] row-major, k is [KEY_DIM]
					// kv_mem[vi] = sum_ki(S[vi,ki] * k[ki]) = matrix-vector: S @ k
					float kv_mem_vec[LINEAR_VALUE_DIM];
					cblas_sgemv(CblasRowMajor, CblasNoTrans,
								LINEAR_VALUE_DIM, LINEAR_KEY_DIM,
								1.0f, S, LINEAR_KEY_DIM, k_h, 1,
								0.0f, kv_mem_vec, 1);

					// Step 3: delta = (v - kv_mem) * beta, then rank-1 update S += k * delta^T
					// delta[vi] = (v[vi] - kv_mem[vi]) * beta
					float delta_vec[LINEAR_VALUE_DIM];
					for (int vi = 0; vi < LINEAR_VALUE_DIM; vi++) {
						delta_vec[vi] = (v_h[vi] - kv_mem_vec[vi]) * b_gate;
					}
					// S += delta @ k^T (rank-1 update: sger)
					// S[vi,ki] += delta[vi] * k[ki]
					cblas_sger(CblasRowMajor, LINEAR_VALUE_DIM, LINEAR_KEY_DIM,
							   1.0f, delta_vec, 1, k_h, 1, S, LINEAR_KEY_DIM);

					// Step 4: output = S @ q (matrix-vector multiply)
					float *q_h = lin_q + kh * LINEAR_KEY_DIM;
					float *o_h = out_values + vh * LINEAR_VALUE_DIM;
					cblas_sgemv(CblasRowMajor, CblasNoTrans,
								LINEAR_VALUE_DIM, LINEAR_KEY_DIM,
								1.0f, S, LINEAR_KEY_DIM, q_h, 1,
								0.0f, o_h, 1);
				}
			}

			// RMSNormGated
			uint16_t *gated_norm_w = lc->gated_norm_w;
			float *gated_out = s_gated_out;
			memset(gated_out, 0, LINEAR_TOTAL_VALUE * sizeof(float));
			for (int vh = 0; vh < LINEAR_NUM_V_HEADS; vh++) {
				float *oh = out_values + vh * LINEAR_VALUE_DIM;
				float *zh = z_out + vh * LINEAR_VALUE_DIM;
				float *gh = gated_out + vh * LINEAR_VALUE_DIM;
				if (gated_norm_w) {
					cpu_rms_norm_gated(oh, zh, gated_norm_w, gh, LINEAR_VALUE_DIM, RMS_NORM_EPS);
				} else {
					memcpy(gh, oh, LINEAR_VALUE_DIM * sizeof(float));
				}
			}

			attn_out_for_oproj = gated_out;

			// conv_out, out_values are static — no free needed
			// gated_out is static — freed/released after CMD2 submission below
		}
		// else: linear_attn_bypass — attn_projected stays zero
		// qkv_out, z_out, beta_out, alpha_out are static scratch.
	}

	// =====================================================================
	// PHASE 3: FULLY FUSED CMD2 — o_proj + residual + norm + routing (1 cmd buffer)
	//   Eliminates 1 GPU round-trip vs old 2-buffer approach.
	//   GPU handles residual_add + rms_norm between o_proj and routing,
	//   so no CPU intervention is needed. 8 encoders, 1 commit+wait.
	//   Buffer flow: batch_out[6]->buf_output->buf_h_mid->buf_input->batch_out[0-3]
	// =====================================================================

	if (g_timing_enabled) { t1 = now_ms(); g_timing.cpu_attn += t1 - t0; }

	// Wait for speculative expert I/O to complete (overlapped with CPU attention)
	if (spec_group) {
		dispatch_group_wait(spec_group, DISPATCH_TIME_FOREVER);
		spec_group = NULL;  // ARC releases the group
	}

	if (g_timing_enabled) { t0 = now_ms(); }

	float *h_post = s_h_post;
	float *h_mid = s_h_mid;
	float *gate_scores = s_gate_scores;
	memset(gate_scores, 0, NUM_EXPERTS * sizeof(float));
	float *shared_gate = s_shared_gate;
	memset(shared_gate, 0, SHARED_INTERMEDIATE * sizeof(float));
	float *shared_up = s_shared_up;
	memset(shared_up, 0, SHARED_INTERMEDIATE * sizeof(float));
	float shared_gate_score = 0.0f;
	int used_fused_cmd2 = 0;
	int gpu_resident_this_layer = 0;

	int shared_gate_ok = (sgw && ((sg_kind == MATVEC_KIND_GGUF_Q8_0) || (sgs && sgb)));
	int shared_up_ok = (suw && ((su_kind == MATVEC_KIND_GGUF_Q8_0) || (sus && sub)));
	int have_moe_weights = (gate_w && gate_s && gate_b &&
							shared_gate_ok && shared_up_ok &&
							seg_w && seg_s && seg_b);
	// The resident handoff is only valid when CMD3 can consume h_mid directly
	// and produce the next layer's normalized input on the GPU.
	int gpu_resident_fused_candidate =
		g_gpu_resident_moe_enabled && !shared_override_active &&
		!disable_gpu_combine_debug() && g_metal &&
		g_metal->moe_combine_residual && g_metal->rms_norm_sum &&
		g_metal->rms_norm_apply_bf16 && g_metal->wf_buf &&
		layer_idx < NUM_LAYERS - 1 &&
		layer_cache[layer_idx + 1].input_norm_w != NULL;

	// gpu_attn_fuse: attention dispatches fused into CMD2 (full-attn layers only).
	// Only enabled when seq_len >= 32 — below that, CPU attention is faster
	// because GPU command encoder overhead dominates at short sequences.
	int gpu_attn_fuse = (is_full && lc->o_kind != MATVEC_KIND_GGUF_Q8_0 &&
						 !attn_out_for_oproj && g_metal && g_metal->attn_scores_pipe
						 && kv && kv->len >= 32 && kv->len <= GPU_KV_SEQ);

	int disable_fused_cmd2 = full_attn_force_cmd2_fallback() || shared_override_active;

	int cmd12_chain_this_layer =
		cmd12_chain_pending &&
		!is_full &&
		gpu_linear_attn &&
		gpu_resident_fused_candidate &&
		!disable_fused_cmd2 &&
		attn_out_for_oproj &&
		oproj_w &&
		(oproj_kind == MATVEC_KIND_GGUF_Q8_0 || (oproj_s && oproj_b)) &&
		g_metal && g_metal->wf_buf && have_moe_weights &&
		(oproj_kind != MATVEC_KIND_GGUF_Q8_0 ||
		 matvec_source_buffer(g_metal, oproj_source, NULL) != nil) &&
		g_metal->residual_add &&
		g_metal->rms_norm_sum &&
		g_metal->rms_norm_apply_bf16 &&
		lc->post_attn_norm_w;

	int cmd12_full_chain_this_layer =
		cmd12_full_chain_pending && is_full && gpu_attn_fuse &&
		!disable_fused_cmd2 && oproj_w && oproj_s && oproj_b &&
		g_metal && g_metal->wf_buf && have_moe_weights &&
		g_metal->residual_add && g_metal->rms_norm_sum &&
		g_metal->rms_norm_apply_bf16 && lc->post_attn_norm_w;

	if (cmd12_chain_pending && !cmd12_chain_this_layer) {
		// Safety fallback: finish CMD1 before taking any non-fused/CPU path.
		if (g_timing_enabled) { t0 = now_ms(); }
		if (!metal_wait_command_buffer_checked(cmd1, "CMD1")) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_wait += t1 - t0; }

		if (cmd12_chain_from_fast_path) {
			if (g_timing_enabled) { t0 = now_ms(); }
			if (!complete_deferred_experts()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
			cpu_vec_copy(residual, hidden, HIDDEN_DIM);
			if (g_timing_enabled) { t1 = now_ms(); g_timing.deferred_cpu += t1 - t0; }
		}
		cmd12_chain_pending = 0;
	}

	if (cmd12_full_chain_pending && !cmd12_full_chain_this_layer) {
		// This should be unreachable because eligibility is established before
		// CMD1 submission. Do not silently continue with stale CPU Q/K/V state.
		if (g_timing_enabled) { t0 = now_ms(); }
		if (!metal_wait_command_buffer_checked(cmd1, "CMD1")) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd1_wait += t1 - t0; }
		sync_full_attn_cpu_kv_from_gpu(kv, cmd12_full_chain_fa_idx,
			cmd12_full_chain_cache_pos);
		if (cmd12_full_chain_from_fast_path) {
			if (!complete_deferred_experts()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		}
		fprintf(stderr,
				"ERROR: --cmd12-full-chain lost fused-CMD2 eligibility at layer %d; aborting safely\n",
				layer_idx);
		g_forward_error = 1;
		g_use_2bit = saved_use_2bit;
		g_use_q3_outlier = saved_use_q3_outlier;
		g_use_q3_experts = saved_use_q3_experts;
		return;
	}

	if (!disable_fused_cmd2 &&
		(attn_out_for_oproj || gpu_attn_fuse) && oproj_w &&
		(oproj_kind == MATVEC_KIND_GGUF_Q8_0 || (oproj_s && oproj_b)) &&
		g_metal && g_metal->wf_buf && have_moe_weights &&
		(oproj_kind != MATVEC_KIND_GGUF_Q8_0 || matvec_source_buffer(g_metal, oproj_source, NULL) != nil) &&
		g_metal->residual_add && g_metal->rms_norm_sum &&
		g_metal->rms_norm_apply_bf16 && lc->post_attn_norm_w) {
		used_fused_cmd2 = 1;
		gpu_resident_this_layer = gpu_resident_fused_candidate;
		if (gpu_resident_this_layer && !g_gpu_resident_moe_status_printed) {
			printf("[gpu-resident-moe] enabled\n");
			g_gpu_resident_moe_status_printed = 1;
		}
		// ---- FULLY FUSED CMD2 ----
		// For GPU attention (full-attn layers): attention dispatches are prepended,
		//   o_proj reads from buf_attn_out instead of batch_out[6].
		// For CPU attention / linear attn: o_proj reads from batch_out[6] as before.
		//
		// GPU attn path (12 encoders):
		//   Enc 1-4: attn_scores + softmax + values + sigmoid -> buf_attn_out
		//   Enc 5:   o_proj (buf_attn_out -> buf_output)
		//   Enc 6-8: residual + norm -> buf_input
		//   Enc 9-12: routing + shared expert
		//
		// CPU attn path (8 encoders, unchanged):
		//   Enc 1:   o_proj (batch_out[6] -> buf_output)
		//   Enc 2-4: residual + norm -> buf_input
		//   Enc 5-8: routing + shared expert

		if (!gpu_attn_fuse && !gpu_linear_attn) {
			// CPU/linear attn: copy attention output to GPU input buffer
			memcpy([g_metal->batch_out[6] contents], attn_out_for_oproj,
				   oproj_in_dim * sizeof(float));
		}
		// gpu_linear_attn: batch_out[6] already has the result from CMD1 gated_rms_norm
		// Reuse the previous GPU-combined hidden state as the residual when
		// the serial queue guarantees CMD3(N-1) has completed before CMD2(N).
		id<MTLBuffer> residual_buf = g_metal->buf_residual;
		if (g_gpu_resident_moe_enabled && prev_gpu_combined && g_metal->buf_moe_hidden) {
			residual_buf = g_metal->buf_moe_hidden;
		} else {
			memcpy([g_metal->buf_residual contents], residual, HIDDEN_DIM * sizeof(float));
		}

		attn_out_for_oproj = NULL;

		id<MTLCommandBuffer> cmd_fused = [g_metal->queue commandBuffer];

		// ---- GPU attention dispatches (only for full-attn layers with GPU path) ----
		if (gpu_attn_fuse) {
			int fa_idx = (layer_idx + 1) / FULL_ATTN_INTERVAL - 1;
			int kv_dim = NUM_KV_HEADS * HEAD_DIM;
			int heads_per_kv = NUM_ATTN_HEADS / NUM_KV_HEADS;
			float scale = 1.0f / sqrtf((float)HEAD_DIM);
			uint32_t hd = HEAD_DIM;
			uint32_t kvd = (uint32_t)kv_dim;
			uint32_t sl = (uint32_t)kv->len;
			uint32_t seq_stride = GPU_KV_SEQ;
			uint32_t hpkv = (uint32_t)heads_per_kv;

			// Enc A1: attn_scores_batched
			{
				id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
				[enc setComputePipelineState:g_metal->attn_scores_pipe];
				[enc setBuffer:g_metal->buf_attn_q          offset:0 atIndex:0];
				[enc setBuffer:g_metal->buf_kv_k[fa_idx]    offset:0 atIndex:1];
				[enc setBuffer:g_metal->buf_attn_scores     offset:0 atIndex:2];
				[enc setBytes:&hd        length:4 atIndex:3];
				[enc setBytes:&kvd       length:4 atIndex:4];
				[enc setBytes:&sl        length:4 atIndex:5];
				[enc setBytes:&seq_stride length:4 atIndex:6];
				[enc setBytes:&scale     length:4 atIndex:7];
				[enc setBytes:&hpkv      length:4 atIndex:8];
				[enc setBytes:&sl        length:4 atIndex:9];
				uint32_t total_tgs = sl * NUM_ATTN_HEADS;
				[enc dispatchThreadgroups:MTLSizeMake(total_tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}
			// Enc A2: attn_softmax_batched
			{
				id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
				[enc setComputePipelineState:g_metal->attn_softmax_pipe];
				[enc setBuffer:g_metal->buf_attn_scores offset:0 atIndex:0];
				[enc setBytes:&sl         length:4 atIndex:1];
				[enc setBytes:&seq_stride  length:4 atIndex:2];
				[enc dispatchThreadgroups:MTLSizeMake(NUM_ATTN_HEADS, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}
			// Enc A3: attn_values_batched
			{
				id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
				[enc setComputePipelineState:g_metal->attn_values_pipe];
				[enc setBuffer:g_metal->buf_attn_scores   offset:0 atIndex:0];
				[enc setBuffer:g_metal->buf_kv_v[fa_idx]  offset:0 atIndex:1];
				[enc setBuffer:g_metal->buf_attn_out      offset:0 atIndex:2];
				[enc setBytes:&hd        length:4 atIndex:3];
				[enc setBytes:&kvd       length:4 atIndex:4];
				[enc setBytes:&sl        length:4 atIndex:5];
				[enc setBytes:&seq_stride length:4 atIndex:6];
				[enc setBytes:&hpkv      length:4 atIndex:7];
				uint32_t total_threads = HEAD_DIM * NUM_ATTN_HEADS;
				uint32_t tgs = (total_threads + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}
			// Enc A4: sigmoid_gate
			{
				uint32_t qdim = NUM_ATTN_HEADS * HEAD_DIM;
				id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
				[enc setComputePipelineState:g_metal->sigmoid_gate_pipe];
				[enc setBuffer:g_metal->buf_attn_out  offset:0 atIndex:0];
				[enc setBuffer:g_metal->buf_attn_gate offset:0 atIndex:1];
				[enc setBytes:&qdim length:4 atIndex:2];
				uint32_t tgs = (qdim + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}
		}

		// ---- o_proj matvec ----
		{
			// For GPU attention: o_proj reads from buf_attn_out
			// For CPU attention: o_proj reads from batch_out[6]
			id<MTLBuffer> oproj_input = gpu_attn_fuse ? g_metal->buf_attn_out : g_metal->batch_out[6];

			id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
			uint32_t o_out_dim = HIDDEN_DIM;
			uint32_t o_in_dim = (uint32_t)oproj_in_dim;
			if (oproj_kind == MATVEC_KIND_GGUF_Q8_0) {
				const char *w_base = NULL;
				id<MTLBuffer> q8_buf = matvec_source_buffer(g_metal, oproj_source, &w_base);
				NSUInteger w_off = (NSUInteger)((const char *)oproj_w - w_base);
				[enc setComputePipelineState:g_metal->matvec_q8_0];
				[enc setBuffer:q8_buf                      offset:w_off atIndex:0];
				[enc setBuffer:oproj_input                 offset:0     atIndex:1];
				[enc setBuffer:g_metal->buf_output         offset:0     atIndex:2];
				[enc setBytes:&o_out_dim                   length:4     atIndex:3];
				[enc setBytes:&o_in_dim                    length:4     atIndex:4];
				uint32_t num_tgs = (o_out_dim + 7) / 8;
				[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			} else {
				NSUInteger w_off = (NSUInteger)((const char *)oproj_w - (const char *)[g_metal->wf_buf contents]);
				NSUInteger s_off = (NSUInteger)((const char *)oproj_s - (const char *)[g_metal->wf_buf contents]);
				NSUInteger b_off = (NSUInteger)((const char *)oproj_b - (const char *)[g_metal->wf_buf contents]);
				uint32_t o_gs = GROUP_SIZE;
				int use_v3 = (g_oproj_v3_enabled && o_in_dim <= 4096 && g_metal->matvec_v3);
				[enc setComputePipelineState:use_v3 ? g_metal->matvec_v3 : g_metal->matvec_fast];
				if (use_v3 && !g_oproj_v3_status_printed) {
					printf("[oproj-v3] using V3 for o_proj %u -> %u\n", o_in_dim, o_out_dim);
					g_oproj_v3_status_printed = 1;
				}
				[enc setBuffer:g_metal->wf_buf       offset:w_off atIndex:0];
				[enc setBuffer:g_metal->wf_buf       offset:s_off atIndex:1];
				[enc setBuffer:g_metal->wf_buf       offset:b_off atIndex:2];
				[enc setBuffer:oproj_input           offset:0     atIndex:3];
				[enc setBuffer:g_metal->buf_output   offset:0     atIndex:4];
				[enc setBytes:&o_out_dim             length:4     atIndex:5];
				[enc setBytes:&o_in_dim              length:4     atIndex:6];
				[enc setBytes:&o_gs                  length:4     atIndex:7];
				if (use_v3) {
					uint32_t num_tgs = (o_out_dim + 7) / 8;
					[enc dispatchThreadgroups:MTLSizeMake(num_tgs, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				} else {
					[enc dispatchThreadgroups:MTLSizeMake(o_out_dim, 1, 1)
						threadsPerThreadgroup:MTLSizeMake(64, 1, 1)];
				}
			}
			[enc endEncoding];
		}

		// ---- Enc 2: residual_add (buf_output + buf_residual -> buf_h_mid) ----
		{
			id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
			uint32_t dim = HIDDEN_DIM;
			[enc setComputePipelineState:g_metal->residual_add];
			[enc setBuffer:residual_buf             offset:0 atIndex:0];  // a = residual
			[enc setBuffer:g_metal->buf_output   offset:0 atIndex:1];  // b = o_proj result
			[enc setBuffer:g_metal->buf_h_mid    offset:0 atIndex:2];  // out = h_mid
			[enc setBytes:&dim length:4 atIndex:3];
			uint32_t tgs = (dim + 255) / 256;
			[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			[enc endEncoding];
		}

		// ---- Enc 3: rms_norm_sum_sq (buf_h_mid -> buf_sum_sq) ----
		{
			id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
			uint32_t dim = HIDDEN_DIM;
			[enc setComputePipelineState:g_metal->rms_norm_sum];
			[enc setBuffer:g_metal->buf_h_mid  offset:0 atIndex:0];
			[enc setBuffer:g_metal->buf_sum_sq offset:0 atIndex:1];
			[enc setBytes:&dim length:4 atIndex:2];
			[enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			[enc endEncoding];
		}

		// ---- Enc 4: rms_norm_apply_bf16 (buf_h_mid + norm_w -> buf_input) ----
		{
			NSUInteger norm_off = (NSUInteger)((const char *)lc->post_attn_norm_w -
											   (const char *)[g_metal->wf_buf contents]);
			id<MTLComputeCommandEncoder> enc = [cmd_fused computeCommandEncoder];
			uint32_t dim = HIDDEN_DIM;
			float eps = RMS_NORM_EPS;
			[enc setComputePipelineState:g_metal->rms_norm_apply_bf16];
			[enc setBuffer:g_metal->buf_h_mid  offset:0       atIndex:0];  // x
			[enc setBuffer:g_metal->wf_buf     offset:norm_off atIndex:1]; // weight (bf16)
			[enc setBuffer:g_metal->buf_sum_sq offset:0       atIndex:2];  // sum_sq
			[enc setBuffer:g_metal->buf_input  offset:0       atIndex:3];  // out = h_post
			[enc setBytes:&dim length:4 atIndex:4];
			[enc setBytes:&eps length:4 atIndex:5];
			uint32_t tgs = (dim + 255) / 256;
			[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
				threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
			[enc endEncoding];
		}

		// ---- Enc 5-8: routing + shared expert projections (read buf_input) ----
		BatchMatvecSpec moe_specs[4] = {
			{ gate_w, gate_s, gate_b, gate_scores,        (uint32_t)NUM_EXPERTS,        HIDDEN_DIM, GROUP_SIZE, 0, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF },
			{ sgw,    sgs,    sgb,    shared_gate,         (uint32_t)SHARED_INTERMEDIATE, HIDDEN_DIM, GROUP_SIZE, 1, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF },
			{ suw,    sus,    sub,    shared_up,           (uint32_t)SHARED_INTERMEDIATE, HIDDEN_DIM, GROUP_SIZE, 2, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF },
			{ seg_w,  seg_s,  seg_b,  &shared_gate_score,  1,                            HIDDEN_DIM, GROUP_SIZE, 3, MATVEC_KIND_MLX4, MATVEC_SOURCE_WF },
		};
		// buf_input already contains h_post from Enc 4 output -- no memcpy needed
		gpu_encode_batch_matvec(g_metal, cmd_fused, moe_specs, 4);

		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd2_encode += t1 - t0; }

		// ---- Single commit+wait for all 8 encoders ----
		double cmd2_profile_commit_start_ms = 0.0;
		if (g_cmd1_profile_enabled && g_cmd1_profile_decode_active)
			cmd2_profile_commit_start_ms = now_ms();
		if (g_timing_enabled) { t0 = now_ms(); }
#ifdef FLASH_PREFILL_NROW_ENABLED
		double nrow_fa_cmd2_started =
			(is_full && g_prefill_nrow_capture) ? now_ms() : 0.0;
#endif
		[cmd_fused commit];
		if (!metal_wait_command_buffer_checked(cmd_fused, "CMD2 fused")) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
#ifdef FLASH_PREFILL_NROW_ENABLED
		if (nrow_fa_cmd2_started > 0.0)
			g_prefill_nrow_prof_cmd2_ms += now_ms() - nrow_fa_cmd2_started;
#endif

		id<MTLCommandBuffer> profile_prev_cmd3 = nil;
		if ((cmd12_chain_from_fast_path || cmd12_full_chain_from_fast_path) &&
			g_deferred.active && g_deferred.cmd_experts)
			profile_prev_cmd3 = g_deferred.cmd_experts;
		if (pipeline_profile_active)
			pipeline_profile_note_cmd12(layer_idx, cmd1, cmd_fused, profile_prev_cmd3);
		if (pipeline_profile_active) {
			PipelineLayerProfile *_pp = &g_pipeline_profile.layer[layer_idx];
			double _wait_return_s = mach_time_s();
			_pp->pending_wait_return_mach_s = _wait_return_s;
			double _cmd2_end_s = cmd_fused.GPUEndTime;
			if (_cmd2_end_s > 0.0 && _wait_return_s >= _cmd2_end_s)
				_pp->cmd2_gpuend_to_waitreturn_ms +=
					(_wait_return_s - _cmd2_end_s) * 1000.0;
		}

		if (cmd12_chain_this_layer) {
			// This one existing CMD2 wait completed queued CMD1 as well and, on
			// the fast path, the preceding deferred CMD3.
			if (cmd12_chain_from_fast_path) {
				if (!complete_deferred_experts()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
			}
			g_cmd12_chain_layers++;
			if (cmd12_chain_from_fast_path)
				g_cmd12_chain_fast_layers++;
			else
				g_cmd12_chain_original_layers++;

			if (!g_cmd12_chain_status_printed) {
				printf("[cmd12-chain] active — GPU-linear CMD1 -> CMD2 uses one synchronization point\n");
				g_cmd12_chain_status_printed = 1;
			}
		}


		if (cmd12_full_chain_this_layer) {
			// The CMD2 wait also completed full-attention preparation in CMD1.
			// Publish this token's prepared GPU K/V to the CPU cache now, after
			// attention no longer depends on eliminating the synchronization point.
			if (cmd12_full_chain_from_fast_path) {
				if (!complete_deferred_experts()) {
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}
			}
			sync_full_attn_cpu_kv_from_gpu(kv, cmd12_full_chain_fa_idx,
				cmd12_full_chain_cache_pos);
			g_cmd12_full_chain_layers++;
			if (cmd12_full_chain_from_fast_path)
				g_cmd12_full_chain_fast_layers++;
			else
				g_cmd12_full_chain_original_layers++;
			if (!g_cmd12_full_chain_status_printed) {
				printf("[cmd12-full] active — GPU full-attn prepare + CMD1 -> CMD2 chaining enabled\n");
				g_cmd12_full_chain_status_printed = 1;
			}
		}

		if (cmd2_profile_commit_start_ms > 0.0) {
			double cmd2_profile_complete_ms = now_ms();
			cmd2_production_timing_note(
				cmd_fused, is_full, gpu_attn_fuse,
				cmd2_profile_complete_ms - cmd2_profile_commit_start_ms);
		}

		// Safe replay capture: the existing CMD2 wait has completed Enc 4, which
		// produced h_post in buf_input. Enc 5-8 only read buf_input, so it still
		// contains the exact vector consumed by shared gate-score.
		if (g_tiny_matvec_telemetry_enabled && !tiny_replay_1x2048.valid &&
			tiny_matvec_target_shape(&moe_specs[3]) == 1) {
			tiny_matvec_capture_sample(g_metal, &tiny_replay_1x2048,
				&moe_specs[3], (const float *)[g_metal->buf_input contents],
				"shared_gate_score");
		}

		// Read back results
		if (gpu_resident_this_layer) {
			memcpy(gate_scores, [g_metal->batch_out[0] contents],
				   NUM_EXPERTS * sizeof(float));
			memcpy(&shared_gate_score, [g_metal->batch_out[3] contents], sizeof(float));
			// Routing logs record the pre-MoE hidden state on the CPU. Keep that
			// optional consumer synchronized without making it part of the fast path.
			if (g_routing_log) {
				memcpy(hidden, [g_metal->buf_h_mid contents], HIDDEN_DIM * sizeof(float));
			}
		} else {
			gpu_flush_batch_results(g_metal, moe_specs, 4);
			memcpy(h_mid, [g_metal->buf_h_mid contents], HIDDEN_DIM * sizeof(float));
			memcpy(h_post, [g_metal->buf_input contents], HIDDEN_DIM * sizeof(float));
			memcpy(hidden, h_mid, HIDDEN_DIM * sizeof(float));
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd2_wait += t1 - t0; }

	} else {
		// ---- Non-fused fallback path ----
		// O projection
		if (attn_out_for_oproj && oproj_w &&
			(oproj_kind == MATVEC_KIND_GGUF_Q8_0 || (oproj_s && oproj_b))) {
			fast_kind_matvec(oproj_w, oproj_s, oproj_b, oproj_kind, oproj_source,
							 attn_out_for_oproj, attn_projected,
							 HIDDEN_DIM, oproj_in_dim, GROUP_SIZE);
			if (is_full &&
				oproj_kind == MATVEC_KIND_GGUF_Q8_0 &&
				oproj_source == MATVEC_SOURCE_GGUF_FULL_ATTN) {
				maybe_debug_full_attn_o_proj_compare(
					wf,
					layer_idx,
					full_attn_seq_pos,
					attn_out_for_oproj,
					attn_projected,
					(const GGUFBlockQ8_0 *)oproj_w,
					oproj_in_dim
				);
			}
		}
		// attn_out_for_oproj is static — no free needed
		attn_out_for_oproj = NULL;

		// Residual connection
		for (int i = 0; i < HIDDEN_DIM; i++) {
			hidden[i] = residual[i] + attn_projected[i];
		}
		// attn_projected, normed, residual are static — no free needed

		cpu_vec_copy(h_mid, hidden, HIDDEN_DIM);

		// Post-attention norm
		cpu_rms_norm(hidden, lc->post_attn_norm_w, h_post, HIDDEN_DIM, RMS_NORM_EPS);

		// Routing + shared expert batch
		if (have_moe_weights) {
			BatchMatvecSpec moe_specs[4] = {
				{ gate_w, gate_s, gate_b, gate_scores,        (uint32_t)NUM_EXPERTS,        HIDDEN_DIM, GROUP_SIZE, 0, MATVEC_KIND_MLX4,        MATVEC_SOURCE_WF },
				{ sgw,    sgs,    sgb,    shared_gate,         (uint32_t)SHARED_INTERMEDIATE, HIDDEN_DIM, GROUP_SIZE, 1, sg_kind,                 sg_source },
				{ suw,    sus,    sub,    shared_up,           (uint32_t)SHARED_INTERMEDIATE, HIDDEN_DIM, GROUP_SIZE, 2, su_kind,                 su_source },
				{ seg_w,  seg_s,  seg_b,  &shared_gate_score,  1,                            HIDDEN_DIM, GROUP_SIZE, 3, MATVEC_KIND_MLX4,        MATVEC_SOURCE_WF },
			};
			fast_batch_matvec(h_post, HIDDEN_DIM, moe_specs, 4);
		}
		if (g_timing_enabled) { t1 = now_ms(); g_timing.cmd2_encode += t1 - t0; }
	}

	// ---- Softmax + top-K (CPU) ----
	if (g_timing_enabled) { t0 = now_ms(); }
	double pipeline_route_start_ms =
		pipeline_profile_active ? now_ms() : 0.0;
	if (pipeline_route_start_ms > 0.0) {
		PipelineLayerProfile *_pp = &g_pipeline_profile.layer[layer_idx];
		double _route_start_s = mach_time_s();
		_pp->pending_route_start_mach_s = _route_start_s;
		if (_pp->pending_wait_return_mach_s > 0.0 &&
			_route_start_s >= _pp->pending_wait_return_mach_s)
			_pp->waitreturn_to_route_start_ms +=
				(_route_start_s - _pp->pending_wait_return_mach_s) * 1000.0;
	}

	int expert_indices[64];
	float expert_weights[64];
	cpu_topk_softmax_raw(gate_scores, NUM_EXPERTS, K, expert_indices, expert_weights);
#ifdef TARGET_VERIFY_ROUTE_STATS
	if (g_target_verify_route_stats_active) {
		int tracked_k = K > MAX_K ? MAX_K : K;
		for (int k = 0; k < tracked_k; k++) {
			int e = expert_indices[k];
			uint16_t *count = &g_target_verify_route_stats.count[layer_idx][e];
			if (g_use_tiered && g_tiered_manifest && TIERED(layer_idx, e).bits == 2) {
				g_target_verify_route_stats.cold_occurrences++;
				g_target_verify_route_stats.cold_routed_bytes += TIERED(layer_idx, e).size;
				if (*count == 0) {
					g_target_verify_route_stats.cold_unique++;
					g_target_verify_route_stats.cold_unique_bytes += TIERED(layer_idx, e).size;
				}
			}
			if (*count < UINT16_MAX) (*count)++;
		}
	}
#endif
	if (g_freq_tracking) {
		for (int k = 0; k < K; k++) {
			g_expert_freq[layer_idx][expert_indices[k]]++;
		}
		if (layer_idx == 0) g_freq_total_tokens++;
	}

	// Track speculative routing prediction accuracy
	if (s_spec_count > 0) {
		int cmp_K = (K > MAX_K) ? MAX_K : K;
		for (int s = 0; s < s_spec_count; s++) {
			for (int r = 0; r < cmp_K; r++) {
				if (s_spec_indices[s] == expert_indices[r]) {
					g_spec_route_hits++;
					break;
				}
			}
		}
	}

	if (g_timing_enabled) { t1 = now_ms(); g_timing.routing_cpu += t1 - t0; }
	if (pipeline_route_start_ms > 0.0) {
		double _route_end_ms = now_ms();
		pipeline_profile_note_routing_wall(layer_idx, _route_end_ms - pipeline_route_start_ms);
		g_pipeline_profile.layer[layer_idx].pending_route_end_mach_s = mach_time_s();
	}

	// Log routing data for predictor training
	if (g_routing_log) {
		int32_t li = layer_idx;
		int32_t ki = (K > MAX_K) ? MAX_K : K;
		fwrite(&li, sizeof(int32_t), 1, g_routing_log);
		fwrite(&ki, sizeof(int32_t), 1, g_routing_log);
		fwrite(hidden, sizeof(float), HIDDEN_DIM, g_routing_log);
		fwrite(expert_indices, sizeof(int32_t), ki, g_routing_log);
		g_routing_log_samples++;
	}

#ifdef FLASH_PREFILL_NROW_ENABLED
	if (g_prefill_nrow_capture) {
		PrefillNRowCapture *cap = g_prefill_nrow_capture;
		int row = cap->row;
		if (row < 0 || row >= cap->count || cap->count > PREFILL_NROW_CAPTURE_ROWS || K != 8) {
			g_forward_error = 1;
		} else {
			const float *mid_src = gpu_resident_this_layer
				? (const float *)[g_metal->buf_h_mid contents] : h_mid;
			const float *post_src = gpu_resident_this_layer
				? (const float *)[g_metal->buf_input contents] : h_post;
			const float *sg_src = gpu_resident_this_layer
				? (const float *)[g_metal->batch_out[1] contents] : shared_gate;
			const float *su_src = gpu_resident_this_layer
				? (const float *)[g_metal->batch_out[2] contents] : shared_up;
			memcpy(cap->h_mid[row], mid_src, HIDDEN_DIM * sizeof(float));
			memcpy(cap->h_post[row], post_src, HIDDEN_DIM * sizeof(float));
			memcpy(cap->shared_gate[row], sg_src, SHARED_INTERMEDIATE * sizeof(float));
			memcpy(cap->shared_up[row], su_src, SHARED_INTERMEDIATE * sizeof(float));
			cap->shared_score[row] = shared_gate_score;
			memcpy(cap->expert_id[row], expert_indices, 8 * sizeof(int));
			memcpy(cap->expert_weight[row], expert_weights, 8 * sizeof(float));
		}
		g_use_2bit = saved_use_2bit;
		g_use_q3_outlier = saved_use_q3_outlier;
		g_use_q3_experts = saved_use_q3_experts;
		return;
	}
#endif

	// ---- Parallel expert-cache lookup / pread / staging ----
	double pipeline_expert_stage_start_ms =
		pipeline_profile_active ? now_ms() : 0.0;
	double expert_stage_timing_start_ms = g_timing_enabled ? now_ms() : 0.0;
	if (pipeline_expert_stage_start_ms > 0.0) {
		PipelineLayerProfile *_pp = &g_pipeline_profile.layer[layer_idx];
		double _expert_start_s = mach_time_s();
		_pp->pending_expert_start_mach_s = _expert_start_s;
		if (_pp->pending_route_end_mach_s > 0.0 &&
			_expert_start_s >= _pp->pending_route_end_mach_s)
			_pp->route_end_to_expert_start_ms +=
				(_expert_start_s - _pp->pending_route_end_mach_s) * 1000.0;
	}
	double pipeline_expert_io_wait_ms = 0.0;
	double pipeline_last_io_end_ms = 0.0;
	if (g_timing_enabled) { t0 = now_ms(); }
	float *moe_out = s_moe_out;
	memset(moe_out, 0, HIDDEN_DIM * sizeof(float));
	float *shared_out = s_shared_out;
	memset(shared_out, 0, HIDDEN_DIM * sizeof(float));

	int actual_K = (K > MAX_K) ? MAX_K : K;

	if (packed_fd >= 0 && g_metal && g_metal->buf_multi_expert_data[0]) {
		// GPU multi-expert path with LRU cache + parallel I/O:
		// For each expert:
		//   - Cache HIT:  dispatch directly from cached Metal buffer (skip pread)
		//   - Cache MISS: pread into cache buffer, then dispatch from it
		// Falls back to original parallel_pread_experts when cache is disabled.

		int valid[MAX_K];
		id<MTLBuffer> expert_bufs[MAX_K];  // buffer to dispatch from per expert
		InferPreadTask gated_miss_tasks[MAX_K] = {0};
		int gated_miss_k[MAX_K] = {0};
		int gated_miss_cache_idx[MAX_K];
		int gated_miss_count = 0;
		int gated_io_generation = 0;
		int cmd3_io_gate_this_layer = 0;
		uint64_t cmd3_io_gate_value = 0;

		if (expert_prefetch_started) {
			// Let the early reads overlap CMD1 + CMD2. We only block here for
			// whatever portion is still unfinished when true routing arrives.
			do {
				double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
				async_pread_wait();
				if (_pio > 0.0) {
					pipeline_expert_io_wait_ms += now_ms() - _pio;
					pipeline_last_io_end_ms = now_ms();
				}
			} while (0);

			int pref_used[MAX_K] = {0};
			int true_miss_count = 0;

			for (int k = 0; k < actual_K; k++) {
				int e = expert_indices[k];
				int pslot = -1;
				for (int p = 0; p < expert_prefetch_count; p++) {
					if (!pref_used[p] && expert_prefetch_experts[p] == e &&
						g_async_pread.valid[p]) {
						pslot = p;
						break;
					}
				}

				int tiered_cold =
					(g_use_tiered && g_tiered_manifest && TIERED(layer_idx, e).bits == 2);

				if (!tiered_cold) {
					// Preserve normal cache statistics: this is the real routing
					// lookup, not the speculative peek done before CMD1.
					id<MTLBuffer> cached =
						malloc_cache_lookup(g_malloc_cache, layer_idx, e);
					if (cached) {
						expert_bufs[k] = cached;
						valid[k] = 1;
						continue;
					}

					if (pslot >= 0) {
						int cidx = -1;
						id<MTLBuffer> buf =
							malloc_cache_insert(g_malloc_cache, layer_idx, e, &cidx);
						if (buf && cidx >= 0) {
							size_t copy_sz = (g_use_tiered && g_tiered_manifest)
								? TIERED(layer_idx, e).size : active_expert_size();
							memcpy(g_malloc_cache->data[cidx],
								   [g_metal->buf_multi_expert_data_B[pslot] contents],
								   copy_sz);
							expert_bufs[k] = buf;
							valid[k] = 1;
							pref_used[pslot] = 1;
							g_prefetch_useful++;
							continue;
						}
					}

					// Prediction missed: populate the real cache exactly as the
					// normal malloc-cache path would.
					int cidx = -1;
					id<MTLBuffer> buf =
						malloc_cache_insert(g_malloc_cache, layer_idx, e, &cidx);
					expert_bufs[k] = buf;
					valid[k] = 0;
					gated_miss_k[true_miss_count] = k;
					gated_miss_cache_idx[true_miss_count] = cidx;
					InferPreadTask *t = &gated_miss_tasks[true_miss_count];
					t->fd = expert_pick_fd(layer_idx, e, packed_fd);
					t->dst = cidx >= 0 ? g_malloc_cache->data[cidx] : [buf contents];
					if (g_use_tiered && g_tiered_manifest) {
						TieredExpertInfo *ti = &TIERED(layer_idx, e);
						t->offset = (off_t)ti->offset;
						t->size = ti->size;
					} else {
						t->offset = (off_t)e * active_expert_size();
						t->size = active_expert_size();
					}
					t->mmap_base = NULL;
					true_miss_count++;
				} else {
					// Cold tiered experts bypass the hot cache. Copy useful
					// prefetched bytes into scratch-A so the next layer can
					// safely reuse scratch-B while this layer's CMD3 executes.
					expert_bufs[k] = g_metal->buf_multi_expert_data[k];
#ifdef TARGET_VERIFY_COLD_CACHE
					if (g_target_cold_active) {
						int hit = 0;
						id<MTLBuffer> grouped = target_cold_buffer_for(layer_idx, e, &hit);
						if (grouped) expert_bufs[k] = grouped;
						if (hit) {
							valid[k] = 1;
							continue;
						}
					}
#endif
					valid[k] = 0;
					if (pslot >= 0) {
						size_t copy_sz = TIERED(layer_idx, e).size;
						memcpy([expert_bufs[k] contents],
							   [g_metal->buf_multi_expert_data_B[pslot] contents],
							   copy_sz);
						valid[k] = 1;
						pref_used[pslot] = 1;
						g_prefetch_useful++;
						continue;
					}

					gated_miss_k[true_miss_count] = k;
					gated_miss_cache_idx[true_miss_count] = -1;
					InferPreadTask *t = &gated_miss_tasks[true_miss_count];
					t->fd = expert_pick_fd(layer_idx, e, packed_fd);
					t->dst = [expert_bufs[k] contents];
					TieredExpertInfo *ti = &TIERED(layer_idx, e);
					t->offset = (off_t)ti->offset;
					t->size = ti->size;
					t->mmap_base = NULL;
					true_miss_count++;
				}
			}

			g_prefetch_blocking_misses += true_miss_count;

			if (true_miss_count > 0) {
				int gate_safe = g_cmd3_io_gate_enabled && g_metal->pipeline_event &&
					gpu_resident_this_layer && !shared_override_active;
				if (gate_safe) {
					gated_miss_count = true_miss_count;
					gated_io_generation = io_pool_start(gated_miss_tasks, gated_miss_count);
					cmd3_io_gate_this_layer = (gated_io_generation > 0);
					for (int m = 0; m < gated_miss_count; m++)
						valid[gated_miss_k[m]] = 1; // provisional; GPU is event-gated
				} else {
					double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
					io_pool_dispatch(gated_miss_tasks, true_miss_count);
					if (_pio > 0.0) {
						pipeline_expert_io_wait_ms += now_ms() - _pio;
						pipeline_last_io_end_ms = now_ms();
					}
					for (int m = 0; m < true_miss_count; m++) {
						int k = gated_miss_k[m];
						InferPreadTask *t = &gated_miss_tasks[m];
						valid[k] = (t->result == (ssize_t)t->size);
						if (!valid[k]) {
							int cidx = gated_miss_cache_idx[m];
							if (cidx >= 0) {
								int e = expert_indices[k];
								g_malloc_cache->entry_idx[layer_idx][e] = -1;
								g_malloc_cache->layer_idx[cidx] = -1;
								g_malloc_cache->expert_idx[cidx] = -1;
								g_malloc_cache->last_used[cidx] = 0;
								if (g_malloc_cache->eviction_policy == 1)
									malloc_cache_lru_unlink(g_malloc_cache, cidx);
								if (g_malloc_cache->eviction_policy == 2)
									g_malloc_cache->clock_ref[cidx] = 0;
								g_malloc_cache->free_next[cidx] = g_malloc_cache->free_head;
								g_malloc_cache->free_head = cidx;
							}
						}
					}
				}
			}

			for (int p = 0; p < expert_prefetch_count; p++) {
				if (g_async_pread.valid[p] && !pref_used[p])
					g_prefetch_wasted++;
			}
		} else if (g_malloc_cache) {
			// ---- Malloc cache path (zero-copy Metal buffer wrappers) ----
			// Generalized CMD3 I/O gating: ordinary cache misses use the same
			// final buffers as the selective-prefetch true-miss path, so they can
			// safely be filled asynchronously while CMD3 is already queued behind
			// the shared-event gate.
			int num_misses = 0;

			for (int k = 0; k < actual_K; k++) {
				if (g_use_tiered && g_tiered_manifest && TIERED(layer_idx, expert_indices[k]).bits == 2) {
					// Cold experts bypass the hot-only cache and use the normal read buffer.
					expert_bufs[k] = g_metal->buf_multi_expert_data[k];
#ifdef TARGET_VERIFY_COLD_CACHE
					if (g_target_cold_active) {
						int hit = 0;
						id<MTLBuffer> grouped = target_cold_buffer_for(layer_idx,
							expert_indices[k], &hit);
						if (grouped) expert_bufs[k] = grouped;
						if (hit) {
							valid[k] = 1;
							continue;
						}
					}
#endif
					gated_miss_k[num_misses] = k;
					gated_miss_cache_idx[num_misses++] = -1;
					valid[k] = 0;
					continue;
				}
				id<MTLBuffer> cached = malloc_cache_lookup(g_malloc_cache, layer_idx, expert_indices[k]);
				if (cached) {
					expert_bufs[k] = cached;
					valid[k] = 1;
				} else {
					int cidx = -1;
					id<MTLBuffer> buf = malloc_cache_insert(g_malloc_cache, layer_idx, expert_indices[k], &cidx);
					expert_bufs[k] = buf;
					gated_miss_k[num_misses] = k;
					gated_miss_cache_idx[num_misses] = cidx;
					num_misses++;
					valid[k] = 0;
				}
			}

			if (num_misses > 0) {
				size_t esz = active_expert_size();
				for (int m = 0; m < num_misses; m++) {
					int k = gated_miss_k[m];
					int cidx = gated_miss_cache_idx[m];
					InferPreadTask *task = &gated_miss_tasks[m];
					task->fd = expert_pick_fd(layer_idx, expert_indices[k], packed_fd);
					task->dst = cidx >= 0 ? g_malloc_cache->data[cidx] : [expert_bufs[k] contents];
					if (g_use_tiered && g_tiered_manifest) {
						TieredExpertInfo *ti = &TIERED(layer_idx, expert_indices[k]);
						task->offset = (off_t)ti->offset;
						task->size = ti->size;
					} else {
						task->offset = (off_t)expert_indices[k] * esz;
						task->size = esz;
					}
					task->result = 0;
					task->mmap_base = NULL;
				}

				int gate_safe =
					g_cmd3_io_gate_enabled &&
					g_metal->pipeline_event &&
					gpu_resident_this_layer &&
					!shared_override_active;

				if (gate_safe) {
					gated_miss_count = num_misses;
					gated_io_generation =
						io_pool_start(gated_miss_tasks, gated_miss_count);
					cmd3_io_gate_this_layer = (gated_io_generation > 0);
					for (int m = 0; m < gated_miss_count; m++)
						valid[gated_miss_k[m]] = 1; // provisional; GPU is event-gated
				} else {
					double _pio =
						pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
					io_pool_dispatch(gated_miss_tasks, num_misses);
					if (_pio > 0.0) {
						pipeline_expert_io_wait_ms += now_ms() - _pio;
						pipeline_last_io_end_ms = now_ms();
					}

					for (int m = 0; m < num_misses; m++) {
						int k = gated_miss_k[m];
						InferPreadTask *task = &gated_miss_tasks[m];
						valid[k] = (task->result == (ssize_t)task->size);
						if (!valid[k]) {
							if (task->result < 0)
								fprintf(stderr, "WARNING: expert %d pread: -1/%zu (errno %d: %s)\n",
									expert_indices[k], task->size, task->error_no,
									strerror(task->error_no));
							else
								fprintf(stderr, "WARNING: expert %d pread: %zd/%zu\n",
									expert_indices[k], task->result, task->size);
							int failed_cidx = gated_miss_cache_idx[m];
							if (failed_cidx >= 0) {
								g_malloc_cache->entry_idx[layer_idx][expert_indices[k]] = -1;
								g_malloc_cache->layer_idx[failed_cidx] = -1;
								g_malloc_cache->expert_idx[failed_cidx] = -1;
								g_malloc_cache->last_used[failed_cidx] = 0;
								if (g_malloc_cache->eviction_policy == 1)
									malloc_cache_lru_unlink(g_malloc_cache, failed_cidx);
								if (g_malloc_cache->eviction_policy == 2)
									g_malloc_cache->clock_ref[failed_cidx] = 0;
								g_malloc_cache->free_next[failed_cidx] = g_malloc_cache->free_head;
								g_malloc_cache->free_head = failed_cidx;
							}
						}
					}
				}
			}
		} else if (g_expert_cache) {
			// ---- Metal buffer LRU cache path ----
			// Phase 1: check cache for each expert, collect misses
			int miss_indices[MAX_K];       // indices into expert_indices[] for misses
			id<MTLBuffer> miss_bufs[MAX_K]; // cache buffers to pread into
			int num_misses = 0;

			for (int k = 0; k < actual_K; k++) {
				id<MTLBuffer> cached = expert_cache_lookup(g_expert_cache, layer_idx, expert_indices[k]);
				if (cached) {
					// Cache hit: use this buffer directly for GPU dispatch
					expert_bufs[k] = cached;
					valid[k] = 1;
				} else {
					// Cache miss: insert into cache (allocates or evicts), will pread below
					id<MTLBuffer> buf = expert_cache_insert(g_expert_cache, layer_idx, expert_indices[k]);
					if (buf) {
						expert_bufs[k] = buf;
						miss_indices[num_misses] = k;
						miss_bufs[num_misses] = buf;
						num_misses++;
						valid[k] = 0;  // not yet loaded
					} else {
						expert_bufs[k] = nil;
						valid[k] = 0;
					}
				}
			}

			// Phase 2: parallel pread all cache misses
			if (num_misses > 0) {
				size_t esz = active_expert_size();
				InferPreadTask tasks[MAX_K] = {0};
				for (int m = 0; m < num_misses; m++) {
					int k = miss_indices[m];
					tasks[m].fd = expert_pick_fd(layer_idx, expert_indices[k], packed_fd);
					tasks[m].dst = [miss_bufs[m] contents];
					tasks[m].offset = (off_t)expert_indices[k] * esz;
					tasks[m].size = esz;
					tasks[m].result = 0;
					if (mmap_base && tasks[m].fd == packed_fd) {
						tasks[m].mmap_base = mmap_base;
						tasks[m].mmap_size = g_layer_mmap_sizes[layer_idx];
					} else {
						tasks[m].mmap_base = NULL;
						tasks[m].mmap_size = 0;
					}
				}

				do {
					double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
					io_pool_dispatch(tasks, num_misses);
					if (_pio > 0.0) { pipeline_expert_io_wait_ms += now_ms() - _pio; pipeline_last_io_end_ms = now_ms(); }
				} while (0);

				// Mark successfully loaded misses as valid
				for (int m = 0; m < num_misses; m++) {
					int k = miss_indices[m];
					valid[k] = (tasks[m].result == (ssize_t)esz);
					if (!valid[k]) {
						fprintf(stderr, "WARNING: expert %d pread: %zd/%zu\n",
								expert_indices[k], tasks[m].result, esz);
						expert_cache_invalidate(g_expert_cache, layer_idx, expert_indices[k]);
					}
				}
			}
		} else if (pred_started) {
			// ---- Prediction path: predicted experts already loading into buf_B ----
			// Wait for predicted preads (they've had ~1.6ms: CMD1_wait + attn + CMD2 + routing)
			do {
				double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
				async_pread_wait();
				if (_pio > 0.0) { pipeline_expert_io_wait_ms += now_ms() - _pio; pipeline_last_io_end_ms = now_ms(); }
			} while (0);
			g_pred_layers++;

			// Match predictions against actual routing
			int miss_ei[MAX_K];       // actual expert indices for misses
			int miss_k_slots[MAX_K];  // which k-slot each miss maps to
			int miss_count = 0;
			int hit_count = 0;

			for (int k = 0; k < actual_K; k++) {
				int found = 0;
				for (int p = 0; p < g_pred_count[layer_idx]; p++) {
					if (expert_indices[k] == g_pred_experts[layer_idx][p] &&
						g_async_pread.valid[p]) {
						// Hit! This expert was pre-loaded into buf_B[p]
						expert_bufs[k] = g_metal->buf_multi_expert_data_B[p];
						valid[k] = 1;
						found = 1;
						hit_count++;
						break;
					}
				}
				if (!found) {
					miss_ei[miss_count] = expert_indices[k];
					miss_k_slots[miss_count] = k;
					expert_bufs[k] = g_metal->buf_multi_expert_data[k];
					miss_count++;
				}
			}
			g_pred_hits += hit_count;
			g_pred_misses += miss_count;

			// Parallel sync-pread misses into buf_A
			if (miss_count > 0) {
				InferPreadTask tasks[MAX_K] = {0};
				size_t esz = active_expert_size();
				for (int m = 0; m < miss_count; m++) {
					int k = miss_k_slots[m];
					tasks[m].fd = packed_fd;
					tasks[m].dst = [g_metal->buf_multi_expert_data[k] contents];
					tasks[m].offset = (off_t)miss_ei[m] * esz;
					tasks[m].size = esz;
					tasks[m].result = 0;
					tasks[m].mmap_base = mmap_base;
					tasks[m].mmap_size = mmap_base ? g_layer_mmap_sizes[layer_idx] : 0;
				}
				do {
					double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
					io_pool_dispatch(tasks, miss_count);
					if (_pio > 0.0) { pipeline_expert_io_wait_ms += now_ms() - _pio; pipeline_last_io_end_ms = now_ms(); }
				} while (0);
				for (int m = 0; m < miss_count; m++) {
					int k = miss_k_slots[m];
					valid[k] = (tasks[m].result == (ssize_t)active_expert_size());
				}
			}
		} else if (g_use_lz4 && g_lz4_index[layer_idx]) {
			// ---- LZ4 compressed path: read compressed + decompress via io_pool ----
			size_t esz = active_expert_size();
				InferPreadTask tasks[MAX_K] = {0};
			for (int k = 0; k < actual_K; k++) {
				LZ4IndexEntry *ie = &g_lz4_index[layer_idx][expert_indices[k]];
				uint64_t file_size = g_lz4_file_sizes[layer_idx];
				if (ie->raw_size != esz || ie->comp_size == 0 ||
					(size_t)ie->comp_size > g_lz4_comp_capacity ||
					(uint64_t)ie->offset > file_size ||
					(uint64_t)ie->comp_size > file_size - (uint64_t)ie->offset ||
					!g_lz4_comp_bufs[k]) {
					fprintf(stderr,
							"ERROR: invalid LZ4 expert entry layer=%d expert=%d "
							"(offset=%llu comp=%u raw=%u file=%llu capacity=%zu)\n",
							layer_idx, expert_indices[k],
							(unsigned long long)ie->offset, ie->comp_size, ie->raw_size,
							(unsigned long long)file_size, g_lz4_comp_capacity);
					g_forward_error = 1;
					g_use_2bit = saved_use_2bit;
					g_use_q3_outlier = saved_use_q3_outlier;
					g_use_q3_experts = saved_use_q3_experts;
					return;
				}
				tasks[k].fd = packed_fd;
				tasks[k].dst = [g_metal->buf_multi_expert_data[k] contents];
				tasks[k].offset = (off_t)ie->offset;
				tasks[k].size = esz;
				tasks[k].result = 0;
				tasks[k].mmap_base = NULL;
				tasks[k].mmap_size = 0;
				tasks[k].lz4_comp_buf = g_lz4_comp_bufs[k];
				tasks[k].lz4_comp_size = ie->comp_size;
				tasks[k].lz4_comp_capacity = g_lz4_comp_capacity;
				expert_bufs[k] = g_metal->buf_multi_expert_data[k];
			}
			do {
				double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
				io_pool_dispatch(tasks, actual_K);
				if (_pio > 0.0) { pipeline_expert_io_wait_ms += now_ms() - _pio; pipeline_last_io_end_ms = now_ms(); }
			} while (0);
			for (int k = 0; k < actual_K; k++) {
				valid[k] = (tasks[k].result == (ssize_t)esz);
			}
		} else {
			// ---- No cache, no prediction, no LZ4: ASYNC parallel pread ----
			async_pread_start(packed_fd, expert_indices, actual_K,
							  g_metal->buf_multi_expert_data, mmap_base, layer_idx);
			for (int k = 0; k < actual_K; k++) {
				expert_bufs[k] = g_metal->buf_multi_expert_data[k];
			}
		}

		// Shared expert prep (doesn't need expert data — can overlap with async pread)
		if (!gpu_resident_this_layer) {
			memcpy([g_metal->buf_multi_expert_input contents], h_post, HIDDEN_DIM * sizeof(float));
			memcpy([g_metal->buf_shared_gate contents], shared_gate,
				   SHARED_INTERMEDIATE * sizeof(float));
			memcpy([g_metal->buf_shared_up contents], shared_up,
				   SHARED_INTERMEDIATE * sizeof(float));
		}

		// Wait for non-prediction async pread to complete
		if (!pred_started && g_async_pread.active) {
			do {
				double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
				async_pread_wait();
				if (_pio > 0.0) { pipeline_expert_io_wait_ms += now_ms() - _pio; pipeline_last_io_end_ms = now_ms(); }
			} while (0);
			for (int k = 0; k < actual_K; k++) {
				valid[k] = g_async_pread.valid[k];
			}
		}

		if (!cmd3_io_gate_this_layer) {
			if (g_timing_enabled) { t1 = now_ms(); g_timing.expert_io += t1 - t0; }
			if (pipeline_expert_stage_start_ms > 0.0) {
				double _stage_end = now_ms();
				g_pipeline_profile.layer[layer_idx].pending_expert_end_mach_s = mach_time_s();
				double _total = _stage_end - pipeline_expert_stage_start_ms;
				double _post = pipeline_last_io_end_ms > 0.0 ? _stage_end - pipeline_last_io_end_ms : 0.0;
				double _lookup = _total - pipeline_expert_io_wait_ms - _post;
				if (_lookup < 0.0) _lookup = 0.0;
				pipeline_profile_note_expert_split(layer_idx, _lookup,
					pipeline_expert_io_wait_ms, _post, _total);
			}
			for (int k = 0; k < actual_K; k++) {
				if (!valid[k]) {
					fprintf(stderr,
							"ERROR: layer %d routed expert %d failed to load; aborting exact inference\n",
							layer_idx, expert_indices[k]);
					g_forward_error = 1;
					g_use_2bit = saved_use_2bit;
					g_use_q3_outlier = saved_use_q3_outlier;
					g_use_q3_experts = saved_use_q3_experts;
					return;
				}
			}
		}

		// Legacy previous-token predictor state.
		if (g_pred_enabled && g_pred_generating) {
			for (int k = 0; k < actual_K; k++)
				g_pred_experts[layer_idx][k] = expert_indices[k];
			g_pred_count[layer_idx] = actual_K;
			if (layer_idx == NUM_LAYERS - 1) g_pred_valid = 1;
		}

		// Independent confidence-gated prefetch history.
		expert_prefetch_history_record(layer_idx, expert_indices, actual_K);

		if (g_timing_enabled) { t0 = now_ms(); }
		double pipeline_cmd3_encode_start_ms =
			pipeline_profile_active ? now_ms() : 0.0;

		if (shared_override_active) {
			float *shared_act = calloc(SHARED_INTERMEDIATE, sizeof(float));
			if (!shared_act) {
				fprintf(stderr, "ERROR: OOM allocating CPU shared-expert activation at layer %d\n", layer_idx);
				g_forward_error = 1;
				g_use_2bit = saved_use_2bit; g_use_q3_outlier = saved_use_q3_outlier; g_use_q3_experts = saved_use_q3_experts;
				return;
			}
			cpu_swiglu(shared_gate, shared_up, shared_act, SHARED_INTERMEDIATE);
			if (sdw) {
				fast_kind_matvec(sdw, sds, sdb, sd_kind, sd_source,
								 shared_act, shared_out,
								 HIDDEN_DIM, SHARED_INTERMEDIATE, GROUP_SIZE);
				memcpy([g_metal->buf_shared_out contents], shared_out, HIDDEN_DIM * sizeof(float));
			}
			free(shared_act);
		}

		// Step 3: encode ALL experts + shared expert into ONE command buffer.
		// Batched encoding: 4 encoders for K experts + 2 for shared = 6 total
		// (vs. 4*K + 2 = 18 with old per-expert encoding).
		id<MTLCommandBuffer> cmd_experts = [g_metal->queue commandBuffer];
		if (cmd3_io_gate_this_layer) {
			cmd3_io_gate_value = ++g_metal->event_value;
			[cmd_experts encodeWaitForEvent:g_metal->pipeline_event value:cmd3_io_gate_value];
		}

		gpu_encode_experts_batched(g_metal, cmd_experts, actual_K, valid, expert_bufs,
								   layer_idx, expert_indices,
								   gpu_resident_this_layer
										 ? g_metal->buf_input : g_metal->buf_multi_expert_input);

		// Shared expert SwiGLU + down_proj (2 more encoders)
		// Note: shared_gate/up already copied to GPU buffers above (before async pread wait)
		if (!shared_override_active) {
			// SwiGLU dispatch
			{
				id<MTLComputeCommandEncoder> enc = [cmd_experts computeCommandEncoder];
				[enc setComputePipelineState:g_metal->swiglu];
				[enc setBuffer:(gpu_resident_this_layer ? g_metal->batch_out[1] : g_metal->buf_shared_gate) offset:0 atIndex:0];
				[enc setBuffer:(gpu_resident_this_layer ? g_metal->batch_out[2] : g_metal->buf_shared_up) offset:0 atIndex:1];
				[enc setBuffer:g_metal->buf_shared_act  offset:0 atIndex:2];
				uint32_t dim = SHARED_INTERMEDIATE;
				[enc setBytes:&dim length:4 atIndex:3];
				uint32_t swiglu_tgs = (dim + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(swiglu_tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}

			// Shared down_proj dispatch
			if (sdw && sds && sdb) {
				gpu_encode_dequant_matvec_with_io_bufs(
					g_metal, cmd_experts, sdw, sds, sdb,
					g_metal->buf_shared_act, g_metal->buf_shared_out,
					HIDDEN_DIM, SHARED_INTERMEDIATE, GROUP_SIZE);
			}
		}

		// Step 4: GPU-side combine + residual + norm (if not last layer)
		// Appends dispatches to CMD3 so the next layer's CMD1 can submit immediately
		// without waiting for CMD3 to complete + CPU readback.
		//
		// For non-last layers with the combine pipeline available:
		//   Enc C1: moe_combine_residual (expert_outs + h_mid + shared_out -> buf_moe_hidden)
		//   Enc C2: rms_norm_sum_sq (buf_moe_hidden -> buf_cmd3_sum_sq)
		//   Enc C3: rms_norm_apply_bf16 (buf_moe_hidden + next_layer_norm_w -> buf_input)
		//
		// This makes CMD3 self-contained: it produces buf_input for the next layer's CMD1.
		// The next layer skips deferred_wait + finalize + input_norm entirely at layer start.

		int gpu_combine = (!shared_override_active &&
						   g_metal->moe_combine_residual &&
						   g_metal->rms_norm_sum &&
						   g_metal->rms_norm_apply_bf16 &&
						   g_metal->wf_buf &&
						   layer_idx < NUM_LAYERS - 1 &&
						   layer_cache[layer_idx + 1].input_norm_w != NULL);
		if (disable_gpu_combine_debug()) {
			gpu_combine = 0;
		}

		if (gpu_combine) {
			if (!used_fused_cmd2) {
				memcpy([g_metal->buf_h_mid contents], h_mid, HIDDEN_DIM * sizeof(float));
			}
			// Copy h_mid from buf_h_mid (populated by CMD2) — it's still valid on GPU.
			// h_mid is already in buf_h_mid from CMD2's residual_add dispatch.

			// Prepare combine params: expert_weights[0..K-1] + shared_gate_score
			{
				float *params = (float *)[g_metal->buf_combine_params contents];
				// Zero all 10 slots first (unused experts get weight=0)
				memset(params, 0, 10 * sizeof(float));
				for (int k = 0; k < actual_K; k++) {
					params[k] = valid[k] ? expert_weights[k] : 0.0f;
				}
				params[8] = shared_gate_score;
			}

			// Enc C1: moe_combine_residual
			{
				id<MTLComputeCommandEncoder> enc = [cmd_experts computeCommandEncoder];
				[enc setComputePipelineState:g_metal->moe_combine_residual];
				[enc setBuffer:g_metal->buf_h_mid         offset:0 atIndex:0];   // h_mid
				[enc setBuffer:g_metal->buf_shared_out    offset:0 atIndex:1];   // shared_out
				[enc setBuffer:g_metal->buf_moe_hidden    offset:0 atIndex:2];   // output: hidden
				// Bind all 8 expert output buffers (unused ones have weight=0 in params)
				for (int k = 0; k < MAX_K; k++) {
					[enc setBuffer:g_metal->buf_multi_expert_out[k] offset:0 atIndex:(3 + k)];
				}
				[enc setBuffer:g_metal->buf_combine_params offset:0 atIndex:11]; // params
				uint32_t dim = HIDDEN_DIM;
				uint32_t k_val = (uint32_t)actual_K;
				[enc setBytes:&dim   length:4 atIndex:12];
				[enc setBytes:&k_val length:4 atIndex:13];
				uint32_t tgs = (dim + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}

			// Enc C2: rms_norm_sum_sq (buf_moe_hidden -> buf_cmd3_sum_sq)
			{
				id<MTLComputeCommandEncoder> enc = [cmd_experts computeCommandEncoder];
				uint32_t dim = HIDDEN_DIM;
				[enc setComputePipelineState:g_metal->rms_norm_sum];
				[enc setBuffer:g_metal->buf_moe_hidden  offset:0 atIndex:0];
				[enc setBuffer:g_metal->buf_cmd3_sum_sq offset:0 atIndex:1];
				[enc setBytes:&dim length:4 atIndex:2];
				[enc dispatchThreadgroups:MTLSizeMake(1, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}

			// Enc C3: rms_norm_apply_bf16 (buf_moe_hidden + next_norm_w -> buf_input)
			{
				uint16_t *next_norm_w = layer_cache[layer_idx + 1].input_norm_w;
				NSUInteger norm_off = (NSUInteger)((const char *)next_norm_w -
												   (const char *)[g_metal->wf_buf contents]);
				id<MTLComputeCommandEncoder> enc = [cmd_experts computeCommandEncoder];
				uint32_t dim = HIDDEN_DIM;
				float eps = RMS_NORM_EPS;
				[enc setComputePipelineState:g_metal->rms_norm_apply_bf16];
				[enc setBuffer:g_metal->buf_moe_hidden  offset:0       atIndex:0]; // x
				[enc setBuffer:g_metal->wf_buf          offset:norm_off atIndex:1]; // weight (bf16)
				[enc setBuffer:g_metal->buf_cmd3_sum_sq offset:0       atIndex:2]; // sum_sq
				[enc setBuffer:g_metal->buf_input       offset:0       atIndex:3]; // out = normed
				[enc setBytes:&dim length:4 atIndex:4];
				[enc setBytes:&eps length:4 atIndex:5];
				uint32_t tgs = (dim + 255) / 256;
				[enc dispatchThreadgroups:MTLSizeMake(tgs, 1, 1)
					threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
				[enc endEncoding];
			}
		}

		// DEFERRED commit — on gated layers this enters the queue before expert I/O ends.
		[cmd_experts commit];
		double cmd3_commit_mach_s = 0.0;
		if (pipeline_profile_active) {
			PipelineLayerProfile *_pp = &g_pipeline_profile.layer[layer_idx];
			cmd3_commit_mach_s = mach_time_s();
			_pp->pending_cmd3_commit_mach_s = cmd3_commit_mach_s;
			if (_pp->pending_expert_end_mach_s > 0.0 &&
				cmd3_commit_mach_s >= _pp->pending_expert_end_mach_s)
				_pp->expert_end_to_cmd3_commit_ms +=
					(cmd3_commit_mach_s - _pp->pending_expert_end_mach_s) * 1000.0;
		}
		double cmd3_encode_done_ms = now_ms();
		if (pipeline_cmd3_encode_start_ms > 0.0)
			pipeline_profile_note_cmd3_encode_wall(
				layer_idx, cmd3_encode_done_ms - pipeline_cmd3_encode_start_ms);
		if (g_timing_enabled)
			g_timing.cmd3_encode += cmd3_encode_done_ms - t0;

		if (cmd3_io_gate_this_layer) {
			double _pio = pipeline_expert_stage_start_ms > 0.0 ? now_ms() : 0.0;
			io_pool_wait_generation(gated_io_generation);
			if (_pio > 0.0) {
				pipeline_expert_io_wait_ms += now_ms() - _pio;
				pipeline_last_io_end_ms = now_ms();
			}

			int gated_read_failed = 0;
			for (int m = 0; m < gated_miss_count; m++) {
				int k = gated_miss_k[m];
				InferPreadTask *task = &gated_miss_tasks[m];
				valid[k] = (task->result == (ssize_t)task->size);
				if (!valid[k]) {
					gated_read_failed = 1;
					int cidx = gated_miss_cache_idx[m];
					if (cidx >= 0) {
						int e = expert_indices[k];
						g_malloc_cache->entry_idx[layer_idx][e] = -1;
						g_malloc_cache->layer_idx[cidx] = -1;
						g_malloc_cache->expert_idx[cidx] = -1;
						g_malloc_cache->last_used[cidx] = 0;
						if (g_malloc_cache->eviction_policy == 1)
							malloc_cache_lru_unlink(g_malloc_cache, cidx);
						if (g_malloc_cache->eviction_policy == 2)
							g_malloc_cache->clock_ref[cidx] = 0;
						g_malloc_cache->free_next[cidx] = g_malloc_cache->free_head;
						g_malloc_cache->free_head = cidx;
					}
				}
			}

			if (g_timing_enabled)
				g_timing.expert_io += now_ms() - expert_stage_timing_start_ms;

			if (pipeline_expert_stage_start_ms > 0.0) {
				double _stage_end = now_ms();
				PipelineLayerProfile *_pp = &g_pipeline_profile.layer[layer_idx];
				_pp->pending_expert_end_mach_s = mach_time_s();
				double _total = _stage_end - pipeline_expert_stage_start_ms;
				double _post = pipeline_last_io_end_ms > 0.0 ? _stage_end - pipeline_last_io_end_ms : 0.0;
				double _lookup = _total - pipeline_expert_io_wait_ms - _post;
				if (_lookup < 0.0) _lookup = 0.0;
				pipeline_profile_note_expert_split(layer_idx, _lookup,
					pipeline_expert_io_wait_ms, _post, _total);

				double _signal_s = mach_time_s();
				_pp->pending_cmd3_gate_signal_mach_s = _signal_s;
				if (cmd3_commit_mach_s > 0.0 && _signal_s >= cmd3_commit_mach_s)
					_pp->cmd3_commit_to_gate_signal_ms +=
						(_signal_s - cmd3_commit_mach_s) * 1000.0;
				_pp->cmd3_gate_count++;
			}

			// Release the queued CMD3 only after all expert bytes are valid.
			g_metal->pipeline_event.signaledValue = cmd3_io_gate_value;

			if (gated_read_failed) {
				[cmd_experts waitUntilCompleted];
				g_forward_error = 1;
				g_use_2bit = saved_use_2bit;
				g_use_q3_outlier = saved_use_q3_outlier;
				g_use_q3_experts = saved_use_q3_experts;
				return;
			}
		}

		if (pipeline_layer_start_ms > 0.0)
			pipeline_profile_note_layer_wall(
				layer_idx, now_ms() - pipeline_layer_start_ms);
		if (g_timing_enabled) {
			t1 = now_ms();
			g_timing.count++;
			double layer_time = t1 - t_layer_start;
			g_timing.total += layer_time;
			if (kv) { g_timing.total_full += layer_time; g_timing.count_full++; }
			else    { g_timing.total_linear += layer_time; g_timing.count_linear++; }
		}

		// Save state for deferred completion
		g_deferred.active = 1;
		g_deferred.gpu_combined = gpu_combine;
		g_deferred.cmd_experts = cmd_experts;
		g_deferred.actual_K = actual_K;
		g_deferred.shared_gate_score = shared_gate_score;
		g_deferred.hidden = hidden;
		g_deferred.layer_idx = layer_idx;
		if (!gpu_combine) {
			// Only need to save h_mid for CPU-side combine path
			memcpy(g_deferred.h_mid, h_mid, HIDDEN_DIM * sizeof(float));
		}
		for (int k = 0; k < actual_K; k++) {
			g_deferred.expert_weights[k] = expert_weights[k];
			g_deferred.valid[k] = valid[k];
		}

		// Return immediately — GPU experts are running async.
		// The next call to fused_layer_forward() or complete_deferred_experts()
		// will wait for the GPU and apply the final combine.
		g_use_2bit = saved_use_2bit;
		g_use_q3_outlier = saved_use_q3_outlier;
		g_use_q3_experts = saved_use_q3_experts;
		return;

	} else if (packed_fd >= 0) {
		// The generic CPU fallback assumes a single uniform expert layout and
		// expert_index * expert_size addressing. Tiered experts use per-expert
		// offsets/layouts, while LZ4 layer_fds point at compressed data.
		if (g_use_tiered || g_use_lz4) {
			fprintf(stderr,
					"ERROR: CPU expert fallback is unsupported for %s storage at layer %d; Metal is required\n",
					g_use_tiered ? "tiered" : "LZ4", layer_idx);
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit;
			g_use_q3_outlier = saved_use_q3_outlier;
			g_use_q3_experts = saved_use_q3_experts;
			return;
		}

		// CPU fallback for uniform, uncompressed experts
		size_t esz = active_expert_size();
		float *expert_out_cpu = malloc(HIDDEN_DIM * sizeof(float));
		if (!expert_out_cpu) {
			fprintf(stderr, "ERROR: OOM allocating CPU expert output at layer %d\n", layer_idx);
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit; g_use_q3_outlier = saved_use_q3_outlier; g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		for (int k = 0; k < K; k++) {
			int eidx = expert_indices[k];
			off_t expert_offset = (off_t)eidx * esz;
			void *expert_data = malloc(esz);
			if (!expert_data) {
				fprintf(stderr, "ERROR: OOM loading layer %d expert %d\n", layer_idx, eidx);
				free(expert_out_cpu);
				g_forward_error = 1;
				g_use_2bit = saved_use_2bit;
				g_use_q3_outlier = saved_use_q3_outlier;
				g_use_q3_experts = saved_use_q3_experts;
				return;
			}
			ssize_t nread = pread(packed_fd, expert_data, esz, expert_offset);
			if (nread != (ssize_t)esz) {
				fprintf(stderr, "ERROR: layer %d expert %d pread: %zd/%zu\n",
						layer_idx, eidx, nread, esz);
				free(expert_data);
				free(expert_out_cpu);
				g_forward_error = 1;
				g_use_2bit = saved_use_2bit;
				g_use_q3_outlier = saved_use_q3_outlier;
				g_use_q3_experts = saved_use_q3_experts;
				return;
			}
			cpu_forward_expert_blob(expert_data, h_post, expert_out_cpu);
			free(expert_data);

			cpu_vec_madd(moe_out, expert_out_cpu, expert_weights[k], HIDDEN_DIM);
		}
		free(expert_out_cpu);

		// CPU shared expert
		float *shared_act = calloc(SHARED_INTERMEDIATE, sizeof(float));
		if (!shared_act) {
			fprintf(stderr, "ERROR: OOM allocating CPU shared-expert activation at layer %d\n", layer_idx);
			g_forward_error = 1;
			g_use_2bit = saved_use_2bit; g_use_q3_outlier = saved_use_q3_outlier; g_use_q3_experts = saved_use_q3_experts;
			return;
		}
		cpu_swiglu(shared_gate, shared_up, shared_act, SHARED_INTERMEDIATE);
		if (sdw) {
			fast_kind_matvec(sdw, sds, sdb, sd_kind, sd_source,
							 shared_act, shared_out,
							 HIDDEN_DIM, SHARED_INTERMEDIATE, GROUP_SIZE);
		}
		free(shared_act);
	} else {
		fprintf(stderr, "ERROR: no packed expert file available for layer %d\n", layer_idx);
		g_forward_error = 1;
		g_use_2bit = saved_use_2bit;
		g_use_q3_outlier = saved_use_q3_outlier;
		g_use_q3_experts = saved_use_q3_experts;
		return;
	}

	// ---- Shared expert gate ----
	float shared_weight = cpu_sigmoid(shared_gate_score);
	for (int i = 0; i < HIDDEN_DIM; i++) {
		shared_out[i] *= shared_weight;
	}

	// ---- Final combine: hidden = h_mid + moe_out + shared_out ----
	for (int i = 0; i < HIDDEN_DIM; i++) {
		hidden[i] = h_mid[i] + moe_out[i] + shared_out[i];
	}

	if (g_timing_enabled) {
		t1 = now_ms();
		g_timing.cmd3_encode += t1 - t0;  // includes CPU expert compute for non-GPU paths
		g_timing.count++;
		double layer_time_cpu = t1 - t_layer_start;
		g_timing.total += layer_time_cpu;
		if (kv) { g_timing.total_full += layer_time_cpu; g_timing.count_full++; }
		else    { g_timing.total_linear += layer_time_cpu; g_timing.count_linear++; }
	}

	// h_post, h_mid, gate_scores, moe_out, shared_out, shared_gate, shared_up
	// are all static scratch buffers — no free needed.

	// Restore global expert quant flag(s)
	g_use_2bit = saved_use_2bit;
	g_use_q3_outlier = saved_use_q3_outlier;
	g_use_q3_experts = saved_use_q3_experts;
}

static int run_all_layers_checked(
	WeightFile *wf,
	float *hidden,
	KVCache **kv_caches,
	void **layer_states,
	void **layer_mmaps,
	int *layer_fds,
	int pos,
	int K
) {
	g_forward_error = 0;
	for (int layer = 0; layer < NUM_LAYERS; layer++) {
		int is_full = ((layer + 1) % FULL_ATTN_INTERVAL == 0);
		fused_layer_forward(wf, layer, hidden,
							is_full ? kv_caches[layer] : NULL,
							is_full ? NULL : layer_states[layer],
							pos,
							layer_mmaps[layer] != MAP_FAILED ? layer_mmaps[layer] : NULL,
							K, layer_fds[layer]);
		if (g_forward_error) {
			discard_deferred_experts();
			return 0;
		}
	}
	return 1;
}


// ============================================================================
// Main inference loop
// ============================================================================

// ============================================================================
// Expert frequency analysis (--freq)
// ============================================================================

static int freq_cmp_desc(const void *a, const void *b) {
	return *(const int *)b - *(const int *)a;
}

static void freq_print_analysis(int K) {
	if (!g_freq_tracking || g_freq_total_tokens == 0) return;

	int total_activations_per_layer = g_freq_total_tokens * K;

	fprintf(stderr, "\n=== Expert Frequency Analysis ===\n");
	fprintf(stderr, "Tokens tracked: %d, K=%d, activations/layer=%d\n\n",
			g_freq_total_tokens, K, total_activations_per_layer);

	// Per-layer analysis
	int experts_for_80_total = 0;  // sum across layers for overall estimate

	for (int l = 0; l < NUM_LAYERS; l++) {
		// Count unique experts and sort frequencies descending
		int sorted[NUM_EXPERTS];
		memcpy(sorted, g_expert_freq[l], NUM_EXPERTS * sizeof(int));
		qsort(sorted, NUM_EXPERTS, sizeof(int), freq_cmp_desc);

		int unique = 0;
		for (int e = 0; e < NUM_EXPERTS; e++) {
			if (sorted[e] > 0) unique++;
		}

		// Compute cumulative coverage thresholds
		int cum = 0;
		int top10_cov = 0, top30_cov = 0, top60_cov = 0;
		int n_for_50 = 0, n_for_80 = 0, n_for_90 = 0;
		for (int e = 0; e < NUM_EXPERTS; e++) {
			cum += sorted[e];
			if (e == 9)  top10_cov = cum;
			if (e == 29) top30_cov = cum;
			if (e == 59) top60_cov = cum;
			if (n_for_50 == 0 && cum * 100 >= total_activations_per_layer * 50)
				n_for_50 = e + 1;
			if (n_for_80 == 0 && cum * 100 >= total_activations_per_layer * 80)
				n_for_80 = e + 1;
			if (n_for_90 == 0 && cum * 100 >= total_activations_per_layer * 90)
				n_for_90 = e + 1;
		}

		double pct10 = 100.0 * top10_cov / total_activations_per_layer;
		double pct30 = 100.0 * top30_cov / total_activations_per_layer;
		double pct60 = 100.0 * top60_cov / total_activations_per_layer;

		fprintf(stderr, "Layer %2d: %3d unique experts, "
				"top-10 cover %.0f%%, top-30 cover %.0f%%, top-60 cover %.0f%% "
				"(50%%@%d, 80%%@%d, 90%%@%d)\n",
				l, unique, pct10, pct30, pct60, n_for_50, n_for_80, n_for_90);

		experts_for_80_total += n_for_80;
	}

	// Overall summary: average experts needed for 80% across all layers
	double avg_experts_80 = (double)experts_for_80_total / NUM_LAYERS;
	// Expert size in GB: each expert is active_expert_size() bytes
	double expert_gb = (double)active_expert_size() / (1024.0 * 1024.0 * 1024.0);
	double total_pin_gb = avg_experts_80 * NUM_LAYERS * expert_gb;

	fprintf(stderr, "\n--- Overall Summary ---\n");
	fprintf(stderr, "To achieve 80%% hit rate across all layers, need %d experts pinned "
			"(avg %.0f/layer, %.2f GB)\n",
			experts_for_80_total, avg_experts_80, total_pin_gb);
	fprintf(stderr, "Expert size: %zu bytes (%.3f MB), %d layers x %d experts = %d total\n",
			active_expert_size(), (double)active_expert_size() / (1024.0 * 1024.0),
			NUM_LAYERS, NUM_EXPERTS, NUM_LAYERS * NUM_EXPERTS);
}

#ifndef CHAT_MODE

// ============================================================================
#ifdef FLASH_PREFILL_NROW_PRODUCTION
typedef int (*PrefillNRowPollFn)(void *ctx);
static int prefill_nrow_runtime_cache_range_eligible(KVCache **kv_caches);
static int prefill_nrow_runtime_prepare(int K);
static int prefill_nrow_runtime_chunk(
    WeightFile *wf, KVCache **kv_caches, void **layer_states,
    void **layer_mmaps, int *layer_fds, int K, int base_pos,
    const uint32_t *token_ids, const float *embedded_rows,
    float *last_hidden, PrefillNRowPollFn poll_fn, void *poll_ctx);
#endif

// HTTP Serve Mode — OpenAI-compatible /v1/chat/completions (SSE streaming)
// ============================================================================

// Deadline-aware socket read. Returns bytes, -1 on transport failure, -2 on timeout.
static ssize_t read_with_deadline(int fd, void *buf, size_t len, double deadline_ms) {
	for (;;) {
		double remain = deadline_ms - now_ms();
		if (remain <= 0.0) { errno = ETIMEDOUT; return -2; }
		int timeout_ms = (remain > (double)INT_MAX) ? INT_MAX : (int)ceil(remain);
		struct pollfd pfd = { .fd = fd, .events = POLLIN, .revents = 0 };
		int pr = poll(&pfd, 1, timeout_ms);
		if (pr == 0) { errno = ETIMEDOUT; return -2; }
		if (pr < 0) { if (errno == EINTR) continue; return -1; }
		ssize_t r = read(fd, buf, len);
		if (r < 0 && errno == EINTR) continue;
		return r;
	}
}

// Read HTTP request into buf (up to bufsz-1) under one absolute request deadline.
// Returns >=0 bytes on success, -1 transport/EOF, -2 malformed request,
// -3 oversized request, and -4 when the overall request deadline expires.
static int read_http_request(int fd, char *buf, int bufsz, double deadline_ms) {
	int total = 0;
	int header_end = -1;

	while (total < bufsz - 1 && header_end < 0) {
		size_t room = (size_t)(bufsz - 1 - total);
		if (room > 4096) room = 4096;
		ssize_t r = read_with_deadline(fd, buf + total, room, deadline_ms);
		if (r == -2) return -4;
		if (r <= 0) return -1;
		total += (int)r;
		buf[total] = '\0';
		char *sep = strstr(buf, "\r\n\r\n");
		if (sep) header_end = (int)(sep - buf) + 4;
	}
	if (header_end < 0) return -3;

	// Parse framing headers by exact field name. This avoids accepting
	// X-Content-Length/value substrings and rejects ambiguous framing.
	size_t content_len = 0;
	int content_length_seen = 0;
	const char *header_stop = buf + header_end - 4; // start of final CRLFCRLF
	const char *line = strstr(buf, "\r\n");
	if (!line || line >= header_stop) return -2;
	line += 2; // skip request line
	while (line < header_stop) {
		const char *eol = strstr(line, "\r\n");
		if (!eol || eol > header_stop) return -2;
		if (eol == line) break;
		const char *colon = memchr(line, ':', (size_t)(eol - line));
		if (!colon || colon == line) return -2;
		size_t name_len = (size_t)(colon - line);
		const char *value = colon + 1;
		while (value < eol && (*value == ' ' || *value == '\t')) value++;

		int is_content_length = name_len == strlen("Content-Length");
		if (is_content_length) {
			for (size_t i = 0; i < name_len; i++) {
				if (tolower((unsigned char)line[i]) !=
					tolower((unsigned char)"Content-Length"[i])) {
					is_content_length = 0;
					break;
				}
			}
		}
		int is_transfer_encoding = name_len == strlen("Transfer-Encoding");
		if (is_transfer_encoding) {
			for (size_t i = 0; i < name_len; i++) {
				if (tolower((unsigned char)line[i]) !=
					tolower((unsigned char)"Transfer-Encoding"[i])) {
					is_transfer_encoding = 0;
					break;
				}
			}
		}
		if (is_transfer_encoding) return -2; // unsupported framing
		if (is_content_length) {
			if (content_length_seen++) return -2;
			if (value == eol) return -2;
			size_t parsed = 0;
			const char *p = value;
			for (; p < eol && *p >= '0' && *p <= '9'; p++) {
				size_t digit = (size_t)(*p - '0');
				if (parsed > (SIZE_MAX - digit) / 10u) return -3;
				parsed = parsed * 10u + digit;
			}
			while (p < eol && (*p == ' ' || *p == '\t')) p++;
			if (p != eol) return -2;
			if (parsed > (size_t)(bufsz - 1 - header_end)) return -3;
			content_len = parsed;
		}
		line = eol + 2;
	}

	size_t have_body = (total > header_end) ? (size_t)(total - header_end) : 0;
	if (have_body > content_len) {
		// Ignore pipelined bytes; this server handles one request per connection.
		total = header_end + (int)content_len;
		have_body = content_len;
	}
	while (have_body < content_len) {
		size_t need = content_len - have_body;
		ssize_t r = read_with_deadline(fd, buf + header_end + have_body, need, deadline_ms);
		if (r == -2) return -4;
		if (r <= 0) return -1;
		have_body += (size_t)r;
		total += (int)r;
	}
	buf[total] = '\0';
	return total;
}

// Parse OpenAI chat messages, including assistant tool_calls and role:"tool"
// results. Developer instructions are merged into the leading system message.
static NSArray<NSDictionary *> *parse_chat_messages(NSDictionary *request) {
    NSArray *input = request[@"messages"];
    if (![input isKindOfClass:[NSArray class]] || input.count == 0) return nil;

    NSMutableArray<NSDictionary *> *messages = [NSMutableArray array];
    NSMutableArray<NSString *> *instructions = [NSMutableArray array];
    BOOL conversation_started = NO;

    for (id item in input) {
        if (![item isKindOfClass:[NSDictionary class]]) return nil;
        NSString *role = item[@"role"];
        if (![role isKindOfClass:[NSString class]]) return nil;

        if ([role isEqualToString:@"developer"] || [role isEqualToString:@"system"]) {
            if (conversation_started) return nil;
            NSString *content = qwen_text_content(item[@"content"]);
            if (!content) return nil;
            if (content.length > 0) [instructions addObject:content];
            continue;
        }

        if (!conversation_started) {
            conversation_started = YES;
            if (instructions.count) {
                [messages addObject:@{
                    @"role": @"system",
                    @"content": [instructions componentsJoinedByString:@"\n\n"]
                }];
            }
        }

        if ([role isEqualToString:@"user"]) {
            NSString *content = qwen_text_content(item[@"content"]);
            if (!content) return nil;
            [messages addObject:@{@"role": @"user", @"content": content}];
            continue;
        }

        if ([role isEqualToString:@"assistant"]) {
            NSString *content = qwen_text_content(item[@"content"]);
            NSArray *tool_calls = [item[@"tool_calls"] isKindOfClass:[NSArray class]]
                ? item[@"tool_calls"] : nil;
            if (!content || (content.length == 0 && tool_calls.count == 0)) return nil;

            // Historical assistant tool-call arguments must be valid JSON
            // objects. Never silently reconstruct malformed arguments as {}.
            for (id raw_call in tool_calls) {
                if (![raw_call isKindOfClass:[NSDictionary class]]) return nil;
                NSDictionary *call = raw_call;
                NSDictionary *fn = [call[@"function"] isKindOfClass:[NSDictionary class]]
                    ? call[@"function"] : call;
                NSString *name = fn[@"name"];
                if (!qwen_wire_identifier_valid(name)) return nil;
                id raw_args = fn[@"arguments"];
                NSDictionary *parsed_args = nil;
                if (raw_args && raw_args != [NSNull null]) {
                    if ([raw_args isKindOfClass:[NSString class]]) {
                        NSString *args_text = (NSString *)raw_args;
                        if (qwen_json_has_trailing_comma(args_text)) return nil;
                        NSData *args_data = [args_text dataUsingEncoding:NSUTF8StringEncoding];
                        id decoded_args = args_data
                            ? [NSJSONSerialization JSONObjectWithData:args_data options:0 error:NULL]
                            : nil;
                        if (![decoded_args isKindOfClass:[NSDictionary class]]) return nil;
                        parsed_args = decoded_args;
                    } else if ([raw_args isKindOfClass:[NSDictionary class]]) {
                        parsed_args = raw_args;
                    } else {
                        return nil;
                    }
                }
                for (id key in parsed_args) {
                    if (!qwen_wire_parameter_name_valid(key)) return nil;
                }
            }

            NSMutableDictionary *message = [@{
                @"role": @"assistant",
                @"content": content ?: @""
            } mutableCopy];
            if (tool_calls.count > 0) message[@"tool_calls"] = tool_calls;
            if ([item[@"reasoning_content"] isKindOfClass:[NSString class]])
                message[@"reasoning_content"] = item[@"reasoning_content"];
            [messages addObject:message];
            continue;
        }

        if ([role isEqualToString:@"tool"]) {
            NSString *content = qwen_text_content(item[@"content"]);
            if (!content) return nil;
            NSMutableDictionary *message = [@{
                @"role": @"tool",
                @"content": content
            } mutableCopy];
            if ([item[@"tool_call_id"] isKindOfClass:[NSString class]])
                message[@"tool_call_id"] = item[@"tool_call_id"];
            if ([item[@"name"] isKindOfClass:[NSString class]])
                message[@"name"] = item[@"name"];
            [messages addObject:message];
            continue;
        }

        return nil;
    }

    return messages.count ? messages : nil;
}

// Validate full-history OpenAI tool sequencing before Qwen rendering. Qwen's
// <tool_response> representation does not carry tool_call_id, so the ID/order
// relationship must be proven while the OpenAI structure is still available.
static BOOL validate_chat_tool_history(NSArray<NSDictionary *> *messages,
                                       NSString **error_out) {
    if (error_out) *error_out = nil;
    if (![messages isKindOfClass:[NSArray class]]) {
        if (error_out) *error_out = @"messages must be an array";
        return NO;
    }

    NSMutableArray<NSString *> *pending = [NSMutableArray array];

    for (NSUInteger mi = 0; mi < messages.count; mi++) {
        NSDictionary *message = messages[mi];
        NSString *role = [message[@"role"] isKindOfClass:[NSString class]]
            ? message[@"role"] : nil;
        if (!role) {
            if (error_out) *error_out = @"invalid message role";
            return NO;
        }

        if (pending.count > 0) {
            if (![role isEqualToString:@"tool"]) {
                if (error_out) *error_out =
                    @"assistant tool calls must be resolved before the next non-tool message";
                return NO;
            }

            NSString *tool_call_id =
                [message[@"tool_call_id"] isKindOfClass:[NSString class]]
                    ? message[@"tool_call_id"] : nil;
            NSString *expected = pending.firstObject;
            if (!tool_call_id || tool_call_id.length == 0 ||
                ![tool_call_id isEqualToString:expected]) {
                if (error_out) *error_out =
                    @"tool result does not match next pending tool call in required order";
                return NO;
            }
            [pending removeObjectAtIndex:0];
            continue;
        }

        if ([role isEqualToString:@"tool"]) {
            if (error_out) *error_out = @"orphan tool result with no pending assistant tool call";
            return NO;
        }

        if ([role isEqualToString:@"assistant"]) {
            NSArray *tool_calls = [message[@"tool_calls"] isKindOfClass:[NSArray class]]
                ? message[@"tool_calls"] : nil;
            if (tool_calls.count == 0) continue;

            NSMutableSet<NSString *> *batch_ids = [NSMutableSet set];
            for (id raw_call in tool_calls) {
                if (![raw_call isKindOfClass:[NSDictionary class]]) {
                    if (error_out) *error_out = @"assistant tool_call must be an object";
                    return NO;
                }
                NSDictionary *call = (NSDictionary *)raw_call;
                NSString *call_id = [call[@"id"] isKindOfClass:[NSString class]]
                    ? call[@"id"] : nil;
                if (!call_id || call_id.length == 0) {
                    if (error_out) *error_out = @"assistant tool_call is missing id";
                    return NO;
                }
                if ([batch_ids containsObject:call_id]) {
                    if (error_out) *error_out = @"duplicate assistant tool_call id";
                    return NO;
                }
                [batch_ids addObject:call_id];
                [pending addObject:call_id];
            }
        }
    }

    if (pending.count > 0) {
        if (error_out) *error_out =
            @"full message history ends with unresolved assistant tool calls";
        return NO;
    }
    return YES;
}

static BOOL qwen_wire_identifier_valid(NSString *name) {
    if (![name isKindOfClass:[NSString class]] || name.length == 0 || name.length > 64)
        return NO;
    for (NSUInteger i = 0; i < name.length; i++) {
        unichar c = [name characterAtIndex:i];
        BOOL ok = (c >= 'A' && c <= 'Z') ||
                  (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') ||
                  c == '_' || c == '-';
        if (!ok) return NO;
    }
    return YES;
}

// Parameter names are embedded in <parameter=...> tags. Permit the broad
// JSON-name space that is safe in that tag, rather than imposing tool-name
// identifier rules on schema property names.
static BOOL qwen_wire_parameter_name_valid(NSString *name) {
    if (![name isKindOfClass:[NSString class]] || name.length == 0 || name.length > 128)
        return NO;
    for (NSUInteger i = 0; i < name.length; i++) {
        unichar c = [name characterAtIndex:i];
        if (c <= 0x20 || c == '<' || c == '>' || c == '=') return NO;
    }
    return YES;
}

static BOOL tool_schema_type_name_supported(NSString *type) {
    if (![type isKindOfClass:[NSString class]]) return NO;
    return [type isEqualToString:@"string"] ||
           [type isEqualToString:@"integer"] ||
           [type isEqualToString:@"number"] ||
           [type isEqualToString:@"boolean"] ||
           [type isEqualToString:@"object"] ||
           [type isEqualToString:@"array"] ||
           [type isEqualToString:@"null"];
}

// Validate only the JSON-Schema features the native Qwen argument decoder can
// faithfully preserve. In particular, nullable ["T","null"] is supported,
// while general unions/anyOf/oneOf are rejected instead of silently coercing.
static BOOL validate_supported_tool_schema(NSDictionary *schema,
                                           NSString *path,
                                           NSString **error_out) {
    if (![schema isKindOfClass:[NSDictionary class]]) {
        if (error_out) *error_out =
            [NSString stringWithFormat:@"schema at %@ must be an object", path ?: @"$"];
        return NO;
    }

    if (schema[@"anyOf"] && schema[@"anyOf"] != [NSNull null]) {
        if (error_out) *error_out =
            [NSString stringWithFormat:@"unsupported anyOf in tool schema at %@", path ?: @"$"];
        return NO;
    }
    if (schema[@"oneOf"] && schema[@"oneOf"] != [NSNull null]) {
        if (error_out) *error_out =
            [NSString stringWithFormat:@"unsupported oneOf in tool schema at %@", path ?: @"$"];
        return NO;
    }

    id raw_type = schema[@"type"];
    if (raw_type && raw_type != [NSNull null]) {
        if ([raw_type isKindOfClass:[NSString class]]) {
            if (!tool_schema_type_name_supported((NSString *)raw_type)) {
                if (error_out) *error_out =
                    [NSString stringWithFormat:@"unsupported schema type '%@' at %@",
                                               raw_type, path ?: @"$"];
                return NO;
            }
        } else if ([raw_type isKindOfClass:[NSArray class]]) {
            NSArray *types = (NSArray *)raw_type;
            if (types.count == 0 || types.count > 2) {
                if (error_out) *error_out =
                    [NSString stringWithFormat:@"unsupported multi-type schema at %@", path ?: @"$"];
                return NO;
            }

            NSMutableSet<NSString *> *seen = [NSMutableSet set];
            NSUInteger null_count = 0;
            NSUInteger nonnull_count = 0;
            for (id item in types) {
                if (![item isKindOfClass:[NSString class]] ||
                    !tool_schema_type_name_supported((NSString *)item) ||
                    [seen containsObject:item]) {
                    if (error_out) *error_out =
                        [NSString stringWithFormat:@"invalid schema type union at %@", path ?: @"$"];
                    return NO;
                }
                [seen addObject:item];
                if ([(NSString *)item isEqualToString:@"null"]) null_count++;
                else nonnull_count++;
            }

            // A one-element type array is harmless. A two-element type array is
            // supported only for the common nullable form ["T","null"].
            if (types.count == 2 && !(null_count == 1 && nonnull_count == 1)) {
                if (error_out) *error_out =
                    [NSString stringWithFormat:
                        @"unsupported multi-type schema at %@; only nullable [\"type\",\"null\"] is supported",
                        path ?: @"$"];
                return NO;
            }
        } else {
            if (error_out) *error_out =
                [NSString stringWithFormat:@"schema type at %@ must be a string or array", path ?: @"$"];
            return NO;
        }
    }

    id raw_properties = schema[@"properties"];
    if (raw_properties && raw_properties != [NSNull null]) {
        if (![raw_properties isKindOfClass:[NSDictionary class]]) {
            if (error_out) *error_out =
                [NSString stringWithFormat:@"properties at %@ must be an object", path ?: @"$"];
            return NO;
        }
        NSDictionary *properties = (NSDictionary *)raw_properties;
        for (id raw_key in properties) {
            if (![raw_key isKindOfClass:[NSString class]]) {
                if (error_out) *error_out =
                    [NSString stringWithFormat:@"property name at %@ must be a string", path ?: @"$"];
                return NO;
            }
            id child = properties[raw_key];
            if (![child isKindOfClass:[NSDictionary class]]) {
                if (error_out) *error_out =
                    [NSString stringWithFormat:@"schema for %@.%@ must be an object",
                                               path ?: @"$", raw_key];
                return NO;
            }
            NSString *child_path =
                [NSString stringWithFormat:@"%@.%@", path ?: @"$", raw_key];
            if (!validate_supported_tool_schema((NSDictionary *)child, child_path, error_out))
                return NO;
        }
    }

    id items = schema[@"items"];
    if (items && items != [NSNull null]) {
        if (![items isKindOfClass:[NSDictionary class]]) {
            if (error_out) *error_out =
                [NSString stringWithFormat:
                    @"array items schema at %@ must be a single object", path ?: @"$"];
            return NO;
        }
        NSString *items_path = [NSString stringWithFormat:@"%@[]", path ?: @"$"];
        if (!validate_supported_tool_schema((NSDictionary *)items, items_path, error_out))
            return NO;
    }

    // A schema-valued additionalProperties would require recursively typing
    // otherwise-unknown native Qwen parameters. That is not implemented yet.
    id additional = schema[@"additionalProperties"];
    if ([additional isKindOfClass:[NSDictionary class]]) {
        if (error_out) *error_out =
            [NSString stringWithFormat:
                @"schema-valued additionalProperties is not supported at %@", path ?: @"$"];
        return NO;
    }

    return YES;
}

static NSArray<NSDictionary *> *parse_request_tools(NSDictionary *request,
                                                     BOOL *valid,
                                                     NSString **error_out) {
    if (valid) *valid = YES;
    if (error_out) *error_out = nil;
    id raw = request[@"tools"];
    if (!raw || raw == [NSNull null]) return nil;
    if (![raw isKindOfClass:[NSArray class]]) {
        if (valid) *valid = NO;
        if (error_out) *error_out = @"tools must be an array";
        return nil;
    }

    NSMutableArray *tools = [NSMutableArray array];
    NSMutableSet<NSString *> *seen_names = [NSMutableSet set];

    for (id item in (NSArray *)raw) {
        if (![item isKindOfClass:[NSDictionary class]]) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"each tool must be an object";
            return nil;
        }

        NSDictionary *tool = item;
        NSString *type = [tool[@"type"] isKindOfClass:[NSString class]] ? tool[@"type"] : nil;
        NSDictionary *fn = [tool[@"function"] isKindOfClass:[NSDictionary class]]
            ? tool[@"function"] : nil;
        NSString *name = [fn[@"name"] isKindOfClass:[NSString class]] ? fn[@"name"] : nil;

        if (![type isEqualToString:@"function"] || !fn || !qwen_wire_identifier_valid(name)) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"tool type/name is invalid for Qwen wire format";
            return nil;
        }
        if ([seen_names containsObject:name]) {
            if (valid) *valid = NO;
            if (error_out) *error_out = [NSString stringWithFormat:@"duplicate tool name '%@'", name];
            return nil;
        }
        [seen_names addObject:name];

        if ([fn[@"strict"] isKindOfClass:[NSNumber class]] && [fn[@"strict"] boolValue]) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"strict tool schemas not yet supported";
            return nil;
        }

        id raw_params = fn[@"parameters"];
        if (raw_params && raw_params != [NSNull null] &&
            ![raw_params isKindOfClass:[NSDictionary class]]) {
            if (valid) *valid = NO;
            if (error_out) *error_out = [NSString stringWithFormat:
                @"parameters for tool '%@' must be an object", name];
            return nil;
        }

        BOOL parameters_omitted = !raw_params || raw_params == [NSNull null];
        NSDictionary *params = [raw_params isKindOfClass:[NSDictionary class]]
            ? raw_params : @{};
        if (params.count > 0) {
            id root_type = params[@"type"];
            if (![root_type isKindOfClass:[NSString class]] ||
                ![(NSString *)root_type isEqualToString:@"object"]) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:
                    @"parameters for tool '%@' must have root type object", name];
                return nil;
            }
        }
        if (parameters_omitted || params.count == 0) {
            params = @{@"type": @"object", @"properties": @{},
                       @"additionalProperties": @NO};
        }
        NSString *schema_error = nil;
        if (!validate_supported_tool_schema(params,
                [NSString stringWithFormat:@"tool '%@'.parameters", name],
                &schema_error)) {
            if (valid) *valid = NO;
            if (error_out) *error_out = schema_error ?: @"unsupported tool schema";
            return nil;
        }

        id raw_properties = params[@"properties"];
        if (raw_properties && raw_properties != [NSNull null] &&
            ![raw_properties isKindOfClass:[NSDictionary class]]) {
            if (valid) *valid = NO;
            if (error_out) *error_out = [NSString stringWithFormat:
                @"properties for tool '%@' must be an object", name];
            return nil;
        }

        NSDictionary *properties = [raw_properties isKindOfClass:[NSDictionary class]]
            ? raw_properties : @{};
        for (id raw_key in properties) {
            if (![raw_key isKindOfClass:[NSString class]] ||
                !qwen_wire_parameter_name_valid((NSString *)raw_key)) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:
                    @"unsafe parameter name in tool '%@'", name];
                return nil;
            }
        }

        id required = params[@"required"];
        if (required && required != [NSNull null]) {
            if (![required isKindOfClass:[NSArray class]]) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:
                    @"required for tool '%@' must be an array", name];
                return nil;
            }
            for (id req_name in (NSArray *)required) {
                if (![req_name isKindOfClass:[NSString class]] ||
                    !qwen_wire_parameter_name_valid((NSString *)req_name) ||
                    properties[req_name] == nil) {
                    if (valid) *valid = NO;
                    if (error_out) *error_out = [NSString stringWithFormat:
                        @"invalid required parameter in tool '%@'", name];
                    return nil;
                }
            }
        }

        NSMutableDictionary *normalized_fn = [fn mutableCopy];
        normalized_fn[@"parameters"] = params;
        NSMutableDictionary *normalized_tool = [tool mutableCopy];
        normalized_tool[@"function"] = normalized_fn;
        [tools addObject:normalized_tool];
    }
    return tools;
}

// Canonical JSON bytes for cache-signature purposes. Tool order is intentionally
// preserved because it also changes the prompt text; dictionary keys are sorted.
static NSData *canonical_tools_json(NSArray<NSDictionary *> *tools) {
    NSArray *safe_tools = [tools isKindOfClass:[NSArray class]]
        ? tools_in_effective_order(tools) : @[];
    return [NSJSONSerialization dataWithJSONObject:safe_tools
                                               options:NSJSONWritingSortedKeys
                                                 error:NULL];
}

static uint64_t fnv1a64_bytes(const void *bytes, NSUInteger length) {
    const uint8_t *p = (const uint8_t *)bytes;
    uint64_t h = UINT64_C(14695981039346656037);
    for (NSUInteger i = 0; i < length; i++) {
        h ^= (uint64_t)p[i];
        h *= UINT64_C(1099511628211);
    }
    return h;
}

static uint64_t tool_context_signature(NSArray<NSDictionary *> *tools, NSString *tool_mode) {
    NSData *tools_data = canonical_tools_json(tools);
    if (!tools_data) return 0;
    NSString *mode = [tool_mode isKindOfClass:[NSString class]] ? tool_mode : @"auto";
    NSMutableData *combined = [NSMutableData dataWithData:tools_data];
    const uint8_t sep = 0;
    [combined appendBytes:&sep length:1];
    NSData *mode_data = [mode dataUsingEncoding:NSUTF8StringEncoding];
    if (mode_data) [combined appendData:mode_data];
    return fnv1a64_bytes(combined.bytes, combined.length);
}

// Disk files describe only tools[]. Tool mode still belongs in the separate
// context signature used to validate KV snapshots and active sessions.
static uint64_t tool_set_signature(NSArray<NSDictionary *> *tools) {
    NSData *tools_data = canonical_tools_json(tools);
    return tools_data ? fnv1a64_bytes(tools_data.bytes, tools_data.length) : 0;
}

static NSString *project_tool_set_cache_directory(void) {
    NSString *executable_dir = infer_executable_directory();
    if (![[executable_dir lastPathComponent] isEqualToString:@"metal_infer"])
        return nil;
    NSString *project_dir = [executable_dir stringByDeletingLastPathComponent];
    return [project_dir stringByAppendingPathComponent:@"warm-tools-cache"];
}

#define LEARNED_TOOL_SET_LIMIT 128

static BOOL learned_tool_set_name(NSString *name) {
    if (name.length != 21 || ![name hasSuffix:@".json"]) return NO;
    for (NSUInteger i = 0; i < 16; i++) {
        unichar c = [name characterAtIndex:i];
        if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f'))) return NO;
    }
    return YES;
}

static void prune_learned_tool_sets(NSString *directory, NSString *protected_path) {
    NSArray<NSString *> *names = [[NSFileManager defaultManager]
        contentsOfDirectoryAtPath:directory error:NULL];
    NSMutableArray<NSDictionary *> *files = [NSMutableArray array];
    for (NSString *name in names) {
        if (!learned_tool_set_name(name)) continue;
        NSString *path = [directory stringByAppendingPathComponent:name];
        struct stat st;
        if (lstat(path.fileSystemRepresentation, &st) != 0 || !S_ISREG(st.st_mode)) continue;
        [files addObject:@{@"path": path, @"sec": @(st.st_mtimespec.tv_sec),
                           @"nsec": @(st.st_mtimespec.tv_nsec)}];
    }
    if (files.count <= LEARNED_TOOL_SET_LIMIT) return;
    [files sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
        NSComparisonResult order = [a[@"sec"] compare:b[@"sec"]];
        if (order == NSOrderedSame) order = [a[@"nsec"] compare:b[@"nsec"]];
        if (order == NSOrderedSame) order = [a[@"path"] compare:b[@"path"]];
        return order;
    }];
    NSUInteger excess = files.count - LEARNED_TOOL_SET_LIMIT;
    for (NSDictionary *file in files) {
        if (excess == 0) break;
        NSString *path = file[@"path"];
        if ([path isEqualToString:protected_path]) continue;
        if (unlink(path.fileSystemRepresentation) == 0) excess--;
    }
}

// Persist the original OpenAI tools[] array for a future explicit --warm-tools
// launch. Return 1 when created, 0 when already present or empty, and -1 on an
// I/O error. The supplied identity hashes canonical tools[] without tool mode.
static int remember_requested_tool_set(NSArray *incoming_tools,
                                        uint64_t tool_set_sig,
                                        NSString *directory,
                                        NSString **path_out) {
    if (path_out) *path_out = nil;
    if (![incoming_tools isKindOfClass:[NSArray class]] || incoming_tools.count == 0)
        return 0;

    const char *dir = directory.fileSystemRepresentation;
    if (!dir || (mkdir(dir, 0755) != 0 && errno != EEXIST)) return -1;
    struct stat dir_stat;
    if (lstat(dir, &dir_stat) != 0 || !S_ISDIR(dir_stat.st_mode)) return -1;

    NSString *filename = [NSString stringWithFormat:@"%016llx.json",
                          (unsigned long long)tool_set_sig];
    NSString *final_path = [directory stringByAppendingPathComponent:filename];
    if (path_out) *path_out = final_path;
    const char *final = final_path.fileSystemRepresentation;
    struct stat existing;
    if (lstat(final, &existing) == 0) {
        if (!S_ISREG(existing.st_mode)) return -1;
        int existing_fd = open(final, O_RDONLY | O_NOFOLLOW);
        if (existing_fd >= 0) { futimes(existing_fd, NULL); close(existing_fd); }
        prune_learned_tool_sets(directory, final_path);
        return 0;
    }
    if (errno != ENOENT) return -1;

    NSData *json = [NSJSONSerialization dataWithJSONObject:incoming_tools
        options:NSJSONWritingPrettyPrinted | NSJSONWritingSortedKeys error:NULL];
    if (!json) return -1;
    NSMutableData *file_data = [json mutableCopy];
    const char newline = '\n';
    [file_data appendBytes:&newline length:1];

    NSString *pattern = [directory stringByAppendingPathComponent:
        [NSString stringWithFormat:@".%016llx.XXXXXX.tmp",
         (unsigned long long)tool_set_sig]];
    char *temp = strdup(pattern.fileSystemRepresentation);
    if (!temp) return -1;
    // mkstemps retains the .tmp suffix and creates an exclusive same-directory
    // file. link() publishes it only if no other agent won the same signature.
    int fd = mkstemps(temp, 4);
    if (fd < 0) { free(temp); return -1; }
    const uint8_t *bytes = file_data.bytes;
    size_t remaining = file_data.length;
    BOOL written = YES;
    while (remaining > 0) {
        ssize_t n = write(fd, bytes, remaining);
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) { written = NO; break; }
        bytes += n;
        remaining -= (size_t)n;
    }
    if (written && fsync(fd) != 0) written = NO;
    if (close(fd) != 0) written = NO;
    int result = -1;
    if (written) {
        if (link(temp, final) == 0) result = 1;
        else if (errno == EEXIST) result = 0;
    }
    unlink(temp);
    free(temp);
    if (result >= 0) prune_learned_tool_sets(directory, final_path);
    return result;
}

static NSDictionary *tool_definition_named(NSArray<NSDictionary *> *tools, NSString *name) {
    if (![tools isKindOfClass:[NSArray class]] || ![name isKindOfClass:[NSString class]]) return nil;
    for (id raw in tools) {
        if (![raw isKindOfClass:[NSDictionary class]]) continue;
        NSDictionary *fn = [raw[@"function"] isKindOfClass:[NSDictionary class]] ? raw[@"function"] : nil;
        if ([fn[@"name"] isKindOfClass:[NSString class]] && [fn[@"name"] isEqualToString:name]) return fn;
    }
    return nil;
}

// The Qwen wire format contributes exactly one formatting newline after the
// opening <parameter=...> tag and one before </parameter>. Remove only those
// wrapper newlines; preserve all other spaces/newlines byte-for-byte.
static NSString *strip_qwen_parameter_wrapper_newlines(NSString *raw) {
    if (![raw isKindOfClass:[NSString class]]) return @"";
    NSUInteger start = 0;
    NSUInteger end = raw.length;
    if (end >= 2 && [[raw substringWithRange:NSMakeRange(0, 2)] isEqualToString:@"\r\n"]) start = 2;
    else if (end >= 1 && [raw characterAtIndex:0] == '\n') start = 1;

    if (end > start + 1 && [[raw substringWithRange:NSMakeRange(end - 2, 2)] isEqualToString:@"\r\n"]) end -= 2;
    else if (end > start && [raw characterAtIndex:end - 1] == '\n') end -= 1;
    return [raw substringWithRange:NSMakeRange(start, end - start)];
}

static NSString *schema_primary_type(NSDictionary *schema) {
    id raw = [schema isKindOfClass:[NSDictionary class]] ? schema[@"type"] : nil;
    if ([raw isKindOfClass:[NSString class]]) return raw;
    if ([raw isKindOfClass:[NSArray class]]) {
        for (id item in (NSArray *)raw) {
            if ([item isKindOfClass:[NSString class]] && ![item isEqualToString:@"null"])
                return item;
        }
        // A null-only one-element type array is valid.
        if ([(NSArray *)raw count] == 1 &&
            [[(NSArray *)raw firstObject] isKindOfClass:[NSString class]] &&
            [[(NSArray *)raw firstObject] isEqualToString:@"null"])
            return @"null";
    }
    return nil;
}

static BOOL schema_allows_null(NSDictionary *schema) {
    id raw = [schema isKindOfClass:[NSDictionary class]] ? schema[@"type"] : nil;
    if ([raw isKindOfClass:[NSString class]])
        return [(NSString *)raw isEqualToString:@"null"];
    if ([raw isKindOfClass:[NSArray class]]) {
        for (id item in (NSArray *)raw) {
            if ([item isKindOfClass:[NSString class]] &&
                [(NSString *)item isEqualToString:@"null"])
                return YES;
        }
    }
    return NO;
}

// NSJSONSerialization on Apple platforms is slightly permissive about some
// non-standard JSON (notably trailing commas). Tool arguments must follow
// strict JSON for object/array schema values, so reject a comma immediately
// before ] or } outside of strings before handing the text to Foundation.
static BOOL qwen_json_has_trailing_comma(NSString *text) {
    if (![text isKindOfClass:[NSString class]]) return NO;
    BOOL in_string = NO;
    BOOL escaped = NO;

    for (NSUInteger i = 0; i < text.length; i++) {
        unichar c = [text characterAtIndex:i];

        if (in_string) {
            if (escaped) {
                escaped = NO;
            } else if (c == '\\') {
                escaped = YES;
            } else if (c == '"') {
                in_string = NO;
            }
            continue;
        }

        if (c == '"') {
            in_string = YES;
            continue;
        }

        if (c == ',') {
            NSUInteger j = i + 1;
            while (j < text.length) {
                unichar w = [text characterAtIndex:j];
                if (w == ' ' || w == '\t' || w == '\r' || w == '\n') j++;
                else break;
            }
            if (j < text.length) {
                unichar next = [text characterAtIndex:j];
                if (next == ']' || next == '}') return YES;
            }
        }
    }
    return NO;
}

static id parse_tool_value_for_schema(NSString *raw_value, NSDictionary *schema, BOOL *ok) {
    if (ok) *ok = NO;
    NSString *type = schema_primary_type(schema);
    NSString *trimmed = [(raw_value ?: @"") stringByTrimmingCharactersInSet:
                         [NSCharacterSet whitespaceAndNewlineCharacterSet]];

    // Native Qwen parameter bodies are unquoted text. For nullable schemas,
    // literal JSON null must remain JSON null rather than becoming "null".
    if (schema_allows_null(schema) &&
        ([trimmed isEqualToString:@"null"] || [trimmed isEqualToString:@"None"])) {
        if (ok) *ok = YES;
        return [NSNull null];
    }

    if (!type || [type isEqualToString:@"string"]) {
        if (ok) *ok = YES;
        return raw_value ?: @"";
    }

    if ([type isEqualToString:@"integer"]) {
        NSScanner *scanner = [NSScanner scannerWithString:trimmed];
        long long v = 0;
        if ([scanner scanLongLong:&v] && scanner.isAtEnd) {
            if (ok) *ok = YES;
            return @(v);
        }
        return nil;
    }
    if ([type isEqualToString:@"number"]) {
        NSScanner *scanner = [NSScanner scannerWithString:trimmed];
        double v = 0.0;
        if ([scanner scanDouble:&v] && scanner.isAtEnd) {
            if (ok) *ok = YES;
            return @(v);
        }
        return nil;
    }
    if ([type isEqualToString:@"boolean"]) {
        if ([trimmed isEqualToString:@"true"] || [trimmed isEqualToString:@"True"])  { if (ok) *ok = YES; return @YES; }
        if ([trimmed isEqualToString:@"false"] || [trimmed isEqualToString:@"False"]) { if (ok) *ok = YES; return @NO; }
        return nil;
    }
    if ([type isEqualToString:@"null"]) {
        if ([trimmed isEqualToString:@"null"] || [trimmed isEqualToString:@"None"]) { if (ok) *ok = YES; return [NSNull null]; }
        return nil;
    }
    if ([type isEqualToString:@"object"] || [type isEqualToString:@"array"]) {
        if (qwen_json_has_trailing_comma(trimmed)) return nil;
        NSData *data = [trimmed dataUsingEncoding:NSUTF8StringEncoding];
        id parsed = data ? [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL] : nil;
        BOOL class_ok = [type isEqualToString:@"object"]
            ? [parsed isKindOfClass:[NSDictionary class]]
            : [parsed isKindOfClass:[NSArray class]];
        if (class_ok) { if (ok) *ok = YES; return parsed; }
        return nil;
    }

    // Unsupported/unknown JSON-Schema primitive: preserve exact text rather
    // than applying heuristic JSON coercion.
    if (ok) *ok = YES;
    return raw_value ?: @"";
}

static BOOL parse_request_session_id(NSDictionary *request,
                                     char *out_buf,
                                     size_t out_size,
                                     BOOL *has_session,
                                     NSString **error_out) {
    if (has_session) *has_session = NO;
    if (error_out) *error_out = nil;
    if (out_buf && out_size > 0) out_buf[0] = '\0';

    if (![request isKindOfClass:[NSDictionary class]]) {
        if (error_out) *error_out = @"invalid request";
        return NO;
    }

    id raw = request[@"session_id"];
    if (!raw) return YES;  // absent means stateless

    if (![raw isKindOfClass:[NSString class]]) {
        if (error_out) *error_out = @"session_id must be a non-empty string under 64 UTF-8 bytes";
        return NO;
    }

    NSData *utf8 = [(NSString *)raw dataUsingEncoding:NSUTF8StringEncoding
                                  allowLossyConversion:NO];
    if (!utf8 || utf8.length == 0 || !out_buf || out_size < 2 ||
        utf8.length >= out_size || memchr(utf8.bytes, 0, utf8.length) != NULL) {
        if (error_out) *error_out = @"session_id must be a non-empty string under 64 UTF-8 bytes";
        return NO;
    }

    memcpy(out_buf, utf8.bytes, utf8.length);
    out_buf[utf8.length] = '\0';
    if (has_session) *has_session = YES;
    return YES;
}

// Parse Qwen3.5 native <tool_call> blocks into OpenAI tool_calls, validating
// names, required arguments, and declared primitive types against request_tools.
static BOOL qwen_range_is_whitespace(NSString *text, NSRange range) {
    if (![text isKindOfClass:[NSString class]]) return NO;
    if (NSMaxRange(range) > text.length) return NO;
    for (NSUInteger i = range.location; i < NSMaxRange(range); i++) {
        unichar c = [text characterAtIndex:i];
        if (!(c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\f' || c == '\v'))
            return NO;
    }
    return YES;
}

static NSArray<NSDictionary *> *parse_qwen_tool_calls(NSString *raw_text,
                                                       NSArray<NSDictionary *> *request_tools,
                                                       BOOL *valid,
                                                       NSString **error_out,
                                                       NSUInteger *complete_blocks_out) {
    if (valid) *valid = YES;
    if (error_out) *error_out = nil;
    if (complete_blocks_out) *complete_blocks_out = 0;
    if (![raw_text isKindOfClass:[NSString class]] || raw_text.length == 0) return @[];

    NSRegularExpressionOptions dotall = NSRegularExpressionDotMatchesLineSeparators;
    NSRegularExpression *block_re =
        [NSRegularExpression regularExpressionWithPattern:@"<tool_call>(.*?)</tool_call>"
                                                  options:dotall error:NULL];
    NSRegularExpression *fn_re =
        [NSRegularExpression regularExpressionWithPattern:@"<function=([^>]+)>(.*?)</function>"
                                                  options:dotall error:NULL];
    NSRegularExpression *param_re =
        [NSRegularExpression regularExpressionWithPattern:@"<parameter=([^>]+)>(.*?)</parameter>"
                                                  options:dotall error:NULL];
    if (!block_re || !fn_re || !param_re) {
        if (valid) *valid = NO;
        if (error_out) *error_out = @"tool parser initialization failed";
        return @[];
    }

    NSMutableArray *calls = [NSMutableArray array];
    NSArray<NSTextCheckingResult *> *blocks =
        [block_re matchesInString:raw_text options:0 range:NSMakeRange(0, raw_text.length)];
    if (complete_blocks_out) *complete_blocks_out = blocks.count;

    NSUInteger raw_cursor = 0;
    for (NSTextCheckingResult *bm in blocks) {
        NSRange whole = [bm rangeAtIndex:0];
        if (whole.location < raw_cursor ||
            !qwen_range_is_whitespace(raw_text,
                NSMakeRange(raw_cursor, whole.location - raw_cursor))) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }
        raw_cursor = NSMaxRange(whole);
    }
    if (!qwen_range_is_whitespace(raw_text,
            NSMakeRange(raw_cursor, raw_text.length - raw_cursor))) {
        if (valid) *valid = NO;
        if (error_out) *error_out = @"malformed native tool call";
        return @[];
    }

    for (NSTextCheckingResult *block_match in blocks) {
        if (block_match.numberOfRanges < 2) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }
        NSString *block = [raw_text substringWithRange:[block_match rangeAtIndex:1]];
        NSArray<NSTextCheckingResult *> *fn_matches =
            [fn_re matchesInString:block options:0 range:NSMakeRange(0, block.length)];
        if (fn_matches.count != 1) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }
        NSTextCheckingResult *fn_match = fn_matches.firstObject;
        if (!fn_match || fn_match.numberOfRanges < 3) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }
        NSRange fn_whole = [fn_match rangeAtIndex:0];
        if (!qwen_range_is_whitespace(block, NSMakeRange(0, fn_whole.location)) ||
            !qwen_range_is_whitespace(block,
                NSMakeRange(NSMaxRange(fn_whole), block.length - NSMaxRange(fn_whole)))) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }

        NSString *name = [block substringWithRange:[fn_match rangeAtIndex:1]];
        NSString *fn_body = [block substringWithRange:[fn_match rangeAtIndex:2]];
        if (!qwen_wire_identifier_valid(name)) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }

        NSDictionary *tool_fn = tool_definition_named(request_tools, name);
        if (!tool_fn) {
            if (valid) *valid = NO;
            if (error_out) *error_out = [NSString stringWithFormat:@"unknown tool '%@'", name];
            return @[];
        }
        NSDictionary *params_schema = [tool_fn[@"parameters"] isKindOfClass:[NSDictionary class]]
            ? tool_fn[@"parameters"] : @{};
        NSDictionary *properties = [params_schema[@"properties"] isKindOfClass:[NSDictionary class]]
            ? params_schema[@"properties"] : @{};
        NSArray *required = [params_schema[@"required"] isKindOfClass:[NSArray class]]
            ? params_schema[@"required"] : @[];
        BOOL additional_allowed = ![params_schema[@"additionalProperties"] isKindOfClass:[NSNumber class]] ||
            [params_schema[@"additionalProperties"] boolValue];

        NSMutableDictionary *arguments = [NSMutableDictionary dictionary];
        NSArray<NSTextCheckingResult *> *params =
            [param_re matchesInString:fn_body options:0 range:NSMakeRange(0, fn_body.length)];

        NSUInteger param_cursor = 0;
        for (NSTextCheckingResult *pm in params) {
            NSRange whole = [pm rangeAtIndex:0];
            if (whole.location < param_cursor ||
                !qwen_range_is_whitespace(fn_body,
                    NSMakeRange(param_cursor, whole.location - param_cursor))) {
                if (valid) *valid = NO;
                if (error_out) *error_out = @"malformed native tool call";
                return @[];
            }
            param_cursor = NSMaxRange(whole);
        }
        if (!qwen_range_is_whitespace(fn_body,
                NSMakeRange(param_cursor, fn_body.length - param_cursor))) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }

        for (NSTextCheckingResult *pm in params) {
            if (pm.numberOfRanges < 3) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
            }
            NSString *key = [fn_body substringWithRange:[pm rangeAtIndex:1]];
            NSString *raw_value = [fn_body substringWithRange:[pm rangeAtIndex:2]];
            NSString *value = strip_qwen_parameter_wrapper_newlines(raw_value);
            if (!qwen_wire_parameter_name_valid(key) || arguments[key] != nil) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
            }

            NSDictionary *property_schema = [properties[key] isKindOfClass:[NSDictionary class]]
                ? properties[key] : nil;
            if (!property_schema && !additional_allowed) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:@"unexpected argument '%@' for tool '%@'", key, name];
                return @[];
            }
            BOOL value_ok = YES;
            id typed = parse_tool_value_for_schema(value, property_schema, &value_ok);
            if (!value_ok || !typed) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:@"invalid value for argument '%@' of tool '%@'", key, name];
                return @[];
            }
            arguments[key] = typed;
        }

        for (id req_name in required) {
            if ([req_name isKindOfClass:[NSString class]] && arguments[req_name] == nil) {
                if (valid) *valid = NO;
                if (error_out) *error_out = [NSString stringWithFormat:@"missing required argument '%@' for tool '%@'", req_name, name];
                return @[];
            }
        }

        NSData *args_data = [NSJSONSerialization dataWithJSONObject:arguments options:0 error:NULL];
        if (!args_data) {
            if (valid) *valid = NO;
            if (error_out) *error_out = @"malformed native tool call";
            return @[];
        }
        NSString *args_json = [[NSString alloc] initWithData:args_data encoding:NSUTF8StringEncoding];
        NSString *call_id = [NSString stringWithFormat:@"call_%@",
                             [[[NSUUID UUID] UUIDString] stringByReplacingOccurrencesOfString:@"-" withString:@""]];
        [calls addObject:@{
            @"id": call_id,
            @"type": @"function",
            @"function": @{@"name": name, @"arguments": args_json ?: @"{}"}
        }];
    }
    return calls;
}

// DSH's file tools permit escalation fields in their schema, but their own
// contract allows those fields only after an actual sandbox denial. Remove
// speculative fields from Write calls before the executor sees them. A real
// denial is left intact so the executor's approval flow can work normally.
static BOOL preceding_sandbox_denial(NSArray<NSDictionary *> *messages) {
    NSDictionary *last = messages.lastObject;
    if (![last[@"role"] isEqualToString:@"tool"] ||
        ![last[@"content"] isKindOfClass:[NSString class]]) return NO;
    NSString *content = last[@"content"];
    return [content containsString:@"[sandbox: file access denied under"];
}

static NSArray<NSDictionary *> *remove_speculative_write_escalation(
    NSArray<NSDictionary *> *calls, NSArray<NSDictionary *> *messages,
    BOOL dsh_mode, BOOL *changed) {
    if (changed) *changed = NO;
    if (!dsh_mode || preceding_sandbox_denial(messages)) return calls;
    NSMutableArray<NSDictionary *> *result = [NSMutableArray arrayWithCapacity:calls.count];
    for (NSDictionary *call in calls) {
        NSDictionary *fn = call[@"function"];
        NSString *name = fn[@"name"];
        NSString *json = fn[@"arguments"];
        if (![name isEqualToString:@"write"] || ![json isKindOfClass:[NSString class]]) {
            [result addObject:call];
            continue;
        }
        NSData *data = [json dataUsingEncoding:NSUTF8StringEncoding];
        NSDictionary *parsed = data ? [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL] : nil;
        if (![parsed isKindOfClass:[NSDictionary class]] ||
            (!parsed[@"sandbox_permissions"] && !parsed[@"justification"])) {
            [result addObject:call];
            continue;
        }
        NSMutableDictionary *arguments = [parsed mutableCopy];
        [arguments removeObjectForKey:@"sandbox_permissions"];
        [arguments removeObjectForKey:@"justification"];
        NSData *clean_data = [NSJSONSerialization dataWithJSONObject:arguments options:0 error:NULL];
        NSString *clean_json = clean_data ? [[NSString alloc] initWithData:clean_data
            encoding:NSUTF8StringEncoding] : nil;
        if (!clean_json) { [result addObject:call]; continue; }
        fprintf(stderr, "[tool-decode] removed speculative Write escalation fields\n");
        NSMutableDictionary *clean_call = [call mutableCopy];
        NSMutableDictionary *clean_fn = [fn mutableCopy];
        clean_fn[@"arguments"] = clean_json;
        clean_call[@"function"] = clean_fn;
        [result addObject:clean_call];
        if (changed) *changed = YES;
    }
    return result;
}

// Constrain ordinary DSH Write calls before they enter KV. Keep the original
// request schema for parsing and permit escalation after a real sandbox denial.
static NSArray<NSDictionary *> *dsh_decoder_tools(
    NSArray<NSDictionary *> *tools, NSArray<NSDictionary *> *messages,
    BOOL dsh_mode) {
    if (!dsh_mode || preceding_sandbox_denial(messages)) return tools;
    NSMutableArray<NSDictionary *> *result = [NSMutableArray arrayWithCapacity:tools.count];
    for (NSDictionary *tool in tools) {
        NSDictionary *fn = tool[@"function"];
        if (![fn[@"name"] isEqualToString:@"write"]) {
            [result addObject:tool];
            continue;
        }
        NSMutableDictionary *properties = [fn[@"parameters"][@"properties"] mutableCopy];
        if (!properties) { [result addObject:tool]; continue; }
        [properties removeObjectForKey:@"sandbox_permissions"];
        [properties removeObjectForKey:@"justification"];
        NSMutableDictionary *parameters = [fn[@"parameters"] mutableCopy];
        parameters[@"properties"] = properties;
        parameters[@"additionalProperties"] = @NO;
        NSMutableDictionary *limited_fn = [fn mutableCopy];
        limited_fn[@"parameters"] = parameters;
        NSMutableDictionary *limited_tool = [tool mutableCopy];
        limited_tool[@"function"] = limited_fn;
        [result addObject:limited_tool];
    }
    return result;
}

// Stop a stateless client from replaying the same failed tool strategy into
// another expensive prefill. Only consecutive, single-call failures count.
static NSString *repeated_tool_failure(NSArray<NSDictionary *> *messages) {
    if (messages.count < 4) return nil;
    NSString *first_name = nil, *first_args = nil, *first_error = nil;
    int repeats = 0;
    for (NSInteger i = (NSInteger)messages.count - 1; i >= 1; i -= 2) {
        NSDictionary *result = messages[(NSUInteger)i];
        NSDictionary *assistant = messages[(NSUInteger)(i - 1)];
        if (![result[@"role"] isEqualToString:@"tool"] ||
            ![assistant[@"role"] isEqualToString:@"assistant"]) break;
        NSArray *calls = assistant[@"tool_calls"];
        if (![calls isKindOfClass:[NSArray class]] || calls.count != 1) break;
        NSDictionary *call = calls.firstObject;
        if (![result[@"tool_call_id"] isEqual:call[@"id"]]) break;
        NSDictionary *fn = call[@"function"];
        NSString *name = fn[@"name"];
        BOOL args_ok = NO;
        NSDictionary *args = qwen_arguments_object(fn[@"arguments"], &args_ok);
        NSData *canonical = args_ok ? [NSJSONSerialization dataWithJSONObject:args
            options:NSJSONWritingSortedKeys error:NULL] : nil;
        NSString *args_text = canonical ? [[NSString alloc] initWithData:canonical
            encoding:NSUTF8StringEncoding] : nil;
        NSString *error = [result[@"content"] isKindOfClass:[NSString class]]
            ? [result[@"content"] lowercaseString] : nil;
        if (!name || !args_text || !error) break;
        NSString *signature = nil;
        if ([error containsString:@"not strictly wider"] ||
            [error containsString:@"escalation is unnecessary"])
            signature = @"unnecessary_escalation";
        else if ([error containsString:@"justification requires sandbox_permissions"])
            signature = @"invalid_escalation";
        else if ([error containsString:@"error"] || [error containsString:@"failed"] ||
                 [error containsString:@"denied"])
            signature = [[error componentsSeparatedByCharactersInSet:
                [NSCharacterSet newlineCharacterSet]] firstObject];
        if (!signature) break;
        if (repeats && (![name isEqualToString:first_name] ||
                        ![args_text isEqualToString:first_args] ||
                        ![signature isEqualToString:first_error])) break;
        first_name = name; first_args = args_text; first_error = signature;
        if (++repeats >= 2)
            return [NSString stringWithFormat:
                @"Repeated %@ tool failure with unchanged arguments (%@). Change the call or handle the error before retrying.",
                name, signature];
    }
    return nil;
}

// A literal path in the latest user turn can be copied into a native call
// without asking the model to spell it again. Keep this deliberately narrow:
// exactly one absolute path, one read-like tool, and one required path field.
static NSString *exact_literal_read_call(NSArray<NSDictionary *> *messages,
                                         NSArray<NSDictionary *> *tools) {
    NSDictionary *last_user = nil;
    for (NSDictionary *message in [messages reverseObjectEnumerator]) {
        if ([message[@"role"] isEqualToString:@"user"]) { last_user = message; break; }
    }
    NSString *content = [last_user[@"content"] isKindOfClass:[NSString class]]
        ? last_user[@"content"] : nil;
    if (!content || [content rangeOfString:@"read" options:NSCaseInsensitiveSearch].location == NSNotFound)
        return nil;
    // The exact-path instruction may be on one line or place the path on its
    // own line. An inline path ends at the explicit next sentence, not at a
    // space inside a path component.
    NSRegularExpression *path_re = [NSRegularExpression
        regularExpressionWithPattern:@"(?m)(?:^|\\n|exact path[^:]*:\\s*)(/[^\\r\\n]+?)(?=\\s+Use the Read tool|[\\r\\n]|$)"
        options:NSRegularExpressionCaseInsensitive error:NULL];
    NSArray<NSTextCheckingResult *> *paths = [path_re matchesInString:content options:0
        range:NSMakeRange(0, content.length)];
    if (paths.count != 1) {
        if ([content containsString:@"exact path"])
            fprintf(stderr, "[serve] exact path copy unavailable: %lu path candidates\n",
                (unsigned long)paths.count);
        return nil;
    }
    NSString *path = [content substringWithRange:[paths[0] rangeAtIndex:1]];
    if ([path hasSuffix:@"."] || [path hasSuffix:@","] ||
        [path containsString:@"<"] || [path containsString:@">"]) return nil;
    NSRegularExpression *tool_re = [NSRegularExpression
        regularExpressionWithPattern:@"Use the\\s+([A-Za-z_][A-Za-z_0-9]*)\\s+tool"
        options:NSRegularExpressionCaseInsensitive error:NULL];
    NSTextCheckingResult *tool_match = [tool_re firstMatchInString:content options:0
        range:NSMakeRange(0, content.length)];
    NSString *requested_name = tool_match
        ? [content substringWithRange:[tool_match rangeAtIndex:1]] : nil;
    if (!requested_name) return nil;
    NSString *chosen_name = nil, *chosen_key = nil;
    for (NSDictionary *tool in tools) {
        NSDictionary *fn = tool[@"function"];
        NSString *name = fn[@"name"];
        if (![name isKindOfClass:[NSString class]] ||
            [name rangeOfString:@"read" options:NSCaseInsensitiveSearch].location == NSNotFound)
            continue;
        NSDictionary *schema = fn[@"parameters"];
        NSDictionary *properties = schema[@"properties"];
        NSArray *required = schema[@"required"];
        if (requested_name && [name caseInsensitiveCompare:requested_name] != NSOrderedSame)
            continue;
        if (![properties isKindOfClass:[NSDictionary class]] ||
            ![required isKindOfClass:[NSArray class]] || required.count != 1) continue;
        NSString *key = required.firstObject;
        if (![@[@"file_path", @"path", @"filename"] containsObject:key]) continue;
        NSDictionary *property = properties[key];
        if (![property[@"type"] isEqual:@"string"]) continue;
        if (chosen_name) return nil; // ambiguous tool choice
        chosen_name = name; chosen_key = key;
    }
    if (!chosen_name) return nil;
    return [NSString stringWithFormat:@"\n<function=%@>\n<parameter=%@>\n%@\n</parameter>\n</function>\n",
        chosen_name, chosen_key, path];
}

// Offer a verbatim filename only when the latest user turn contains exactly
// one clear candidate. Multiple paths must remain model-selected.
static NSString *unambiguous_literal_file_path(NSArray<NSDictionary *> *messages) {
    NSString *content = nil;
    for (NSDictionary *message in [messages reverseObjectEnumerator]) {
        if ([message[@"role"] isEqualToString:@"user"]) {
            content = [message[@"content"] isKindOfClass:[NSString class]]
                ? message[@"content"] : nil;
            break;
        }
    }
    if (!content) return nil;
    NSString *extensions = @"(?:txt|json|md|m|h|c|mm|py|js|ts|sh|yaml|yml|xml|csv|log|bak)";
    NSString *absolute_pattern = [NSString stringWithFormat:
        @"(?<![A-Za-z0-9_./-])(/[^\\r\\n<>\\\"'`]+?\\.%@)(?=$|[\\s\\\"'`,;!?]|\\.(?=\\s|$))", extensions];
    NSRegularExpression *absolute_re = [NSRegularExpression
        regularExpressionWithPattern:absolute_pattern
        options:NSRegularExpressionCaseInsensitive error:NULL];
    NSArray<NSTextCheckingResult *> *absolute = [absolute_re matchesInString:content
        options:0 range:NSMakeRange(0, content.length)];
    NSRegularExpression *path_re = [NSRegularExpression
        regularExpressionWithPattern:
            @"(?<![A-Za-z0-9_./-])((?:\\./|[A-Za-z0-9_-]+/)*[A-Za-z0-9_-]+\\.(?:txt|json|md|m|h|c|mm|py|js|ts|sh|yaml|yml|xml|csv|log|bak))(?=$|[\\s\\\"'`,;!?]|\\.(?=\\s|$))"
        options:NSRegularExpressionCaseInsensitive error:NULL];
    NSArray<NSTextCheckingResult *> *matches = [path_re matchesInString:content
        options:0 range:NSMakeRange(0, content.length)];
    if (absolute.count > 1) return nil;
    if (absolute.count == 1) {
        NSRange absolute_range = [absolute[0] rangeAtIndex:1];
        for (NSTextCheckingResult *match in matches) {
            NSRange relative_range = [match rangeAtIndex:1];
            if (!NSLocationInRange(relative_range.location, absolute_range) ||
                NSMaxRange(relative_range) > NSMaxRange(absolute_range)) return nil;
        }
        return [content substringWithRange:absolute_range];
    }
    if (matches.count != 1) return nil;
    NSString *path = [content substringWithRange:[matches[0] rangeAtIndex:1]];
    return path.length > 1 ? path : nil;
}

static NSString *literal_file_path_for_generation(NSArray<NSDictionary *> *messages) {
    if ([messages.lastObject[@"role"] isEqualToString:@"tool"]) return nil;
    return unambiguous_literal_file_path(messages);
}

static BOOL literal_path_is_destination(NSArray<NSDictionary *> *messages,
                                        NSString *path) {
    if (!path || ![messages.lastObject[@"role"] isEqualToString:@"user"]) return NO;
    NSString *content = messages.lastObject[@"content"];
    if (![content isKindOfClass:[NSString class]]) return NO;
    NSRange path_range = [content rangeOfString:path];
    if (path_range.location == NSNotFound) return NO;
    NSString *before = [content substringToIndex:path_range.location];
    NSString *pattern =
        @"(?:\\b(?:write|create|save|output|make|edit|modify|update|replace)\\b[^\\r\\n.;]{0,80}\\b(?:to|as|at|named|called|into)\\s*|"
         "\\b(?:write|create|save|output|make|edit|modify|update|replace)\\s+(?:(?:the|a|an|new)\\s+)?(?:file\\s+)?)$";
    NSRegularExpression *re = [NSRegularExpression
        regularExpressionWithPattern:pattern
        options:NSRegularExpressionCaseInsensitive error:NULL];
    return [re firstMatchInString:before options:0
        range:NSMakeRange(0, before.length)] != nil;
}

static NSString *literal_path_for_tool(NSDictionary *plan, NSString *lower_name) {
    if ([@[@"read", @"read_file", @"stat", @"stat_file"] containsObject:lower_name])
        return plan[@"literal_path"];
    if ([@[@"write", @"write_file", @"create", @"create_file", @"edit", @"edit_file"]
            containsObject:lower_name])
        return plan[@"destination_path"];
    return nil;
}

// Once the model starts a native tool call, select names through a token trie
// built from the request schema. The server supplies the markup around values;
// the model still generates each argument value. This applies to every tool,
// while exact_literal_read_call remains a narrow value-preservation shortcut.
static NSArray<NSNumber *> *tool_wire_tokens(NSString *text) {
    int count = 0;
    uint32_t *ids = encode_internal_text_tokens(text.UTF8String, &count);
    if (!ids || count <= 0) { free(ids); return nil; }
    NSMutableArray<NSNumber *> *tokens = [NSMutableArray arrayWithCapacity:(NSUInteger)count];
    for (int i = 0; i < count; i++) [tokens addObject:@(ids[i])];
    free(ids);
    return tokens;
}

static BOOL tool_wire_force(NSMutableDictionary *plan, NSString *text,
                            NSString *after) {
    NSArray *tokens = tool_wire_tokens(text);
    if (!tokens) return NO;
    plan[@"forced"] = tokens;
    plan[@"forced_index"] = @0;
    plan[@"after_force"] = after;
    plan[@"state"] = @"forced";
    return YES;
}

static BOOL tool_wire_set_choices(NSMutableDictionary *plan,
                                  NSArray<NSDictionary *> *options,
                                  NSString *kind) {
    NSMutableArray *choices = [NSMutableArray arrayWithCapacity:options.count];
    for (NSDictionary *option in options) {
        NSString *label = option[@"label"];
        NSString *text = option[@"text"];
        NSArray *tokens = tool_wire_tokens(text);
        if (!tokens || !label) return NO;
        [choices addObject:@{@"label": label, @"tokens": tokens}];
    }
    if (choices.count == 0) return NO;
    plan[@"choices"] = choices;
    plan[@"choice_depth"] = @0;
    plan[@"choice_kind"] = kind;
    plan[@"state"] = @"choice";
    return YES;
}

static NSArray<NSString *> *tool_wire_available_keys(NSDictionary *tool_fn,
                                                       NSSet<NSString *> *used,
                                                       BOOL required_only) {
    NSDictionary *schema = [tool_fn[@"parameters"] isKindOfClass:[NSDictionary class]]
        ? tool_fn[@"parameters"] : @{};
    NSDictionary *properties = [schema[@"properties"] isKindOfClass:[NSDictionary class]]
        ? schema[@"properties"] : @{};
    NSArray *required = [schema[@"required"] isKindOfClass:[NSArray class]]
        ? schema[@"required"] : @[];
    NSMutableArray<NSString *> *keys = [NSMutableArray array];
    for (NSString *key in properties) {
        BOOL is_required = [required containsObject:key];
        if (![used containsObject:key] && is_required == required_only)
            [keys addObject:key];
    }
    [keys sortUsingSelector:@selector(compare:)];
    return keys;
}

static BOOL tool_wire_parameter_closed(NSString *text) {
    if (![text isKindOfClass:[NSString class]]) return NO;
    NSString *trimmed = [text stringByTrimmingCharactersInSet:
        [NSCharacterSet whitespaceAndNewlineCharacterSet]];
    return [trimmed hasSuffix:@"</parameter>"];
}

static BOOL tool_wire_allows_dynamic_keys(NSDictionary *tool_fn) {
    NSDictionary *schema = [tool_fn[@"parameters"] isKindOfClass:[NSDictionary class]]
        ? tool_fn[@"parameters"] : @{};
    id additional = schema[@"additionalProperties"];
    return ![additional isKindOfClass:[NSNumber class]] || [additional boolValue];
}

static int tool_wire_next_token(NSMutableDictionary *plan,
                                NSArray<NSDictionary *> *tools,
                                const float *logits, int sampled) {
    for (int transition = 0; transition < 12; transition++) {
        NSString *state = plan[@"state"];
        if ([state isEqualToString:@"forced"]) {
            NSArray<NSNumber *> *tokens = plan[@"forced"];
            NSUInteger index = [plan[@"forced_index"] unsignedIntegerValue];
            if (index >= tokens.count) return -1;
            int token = tokens[index].intValue;
            plan[@"forced_index"] = @(index + 1);
            if (index + 1 == tokens.count) plan[@"state"] = plan[@"after_force"];
            return token;
        }
        if ([state isEqualToString:@"function"]) {
            NSMutableArray *options = [NSMutableArray array];
            for (NSDictionary *tool in tools) {
                NSString *name = tool[@"function"][@"name"];
                if (!qwen_wire_identifier_valid(name)) return -1;
                [options addObject:@{@"label": name,
                                     @"text": [name stringByAppendingString:@">\n"]}];
            }
            if (!tool_wire_set_choices(plan, options, @"function")) return -1;
            continue;
        }
        if ([state isEqualToString:@"next"]) {
            NSDictionary *tool_fn = tool_definition_named(tools, plan[@"tool"]);
            if (!tool_fn) return -1;
            NSMutableSet *used = plan[@"used"];
            NSArray *missing = tool_wire_available_keys(tool_fn, used, YES);
            if (missing.count > 0) {
                plan[@"key_mode"] = @"required";
                if (!tool_wire_force(plan, @"<parameter=", @"key")) return -1;
                continue;
            }
            NSArray *optional = tool_wire_available_keys(tool_fn, used, NO);
            if (tool_wire_allows_dynamic_keys(tool_fn)) {
                // A finite key trie cannot represent arbitrary JSON property names.
                // Keep the function name constrained and let Qwen finish the
                // parameter list using its native format and the existing parser.
                plan[@"state"] = @"dynamic_keys";
                continue;
            }
            if (optional.count == 0) {
                if (!tool_wire_force(plan, @"</function>\n", @"call_end")) return -1;
                continue;
            }
            NSArray *options = @[
                @{@"label": @"parameter", @"text": @"<parameter="},
                @{@"label": @"end", @"text": @"</function>\n"},
            ];
            if (!tool_wire_set_choices(plan, options, @"branch")) return -1;
            continue;
        }
        if ([state isEqualToString:@"key"]) {
            NSDictionary *tool_fn = tool_definition_named(tools, plan[@"tool"]);
            if (!tool_fn) return -1;
            BOOL required = [plan[@"key_mode"] isEqualToString:@"required"];
            NSArray<NSString *> *keys = tool_wire_available_keys(
                tool_fn, plan[@"used"], required);
            NSMutableArray *options = [NSMutableArray arrayWithCapacity:keys.count];
            for (NSString *key in keys)
                [options addObject:@{@"label": key,
                                     @"text": [key stringByAppendingString:@">\n"]}];
            if (!tool_wire_set_choices(plan, options, @"key")) return -1;
            continue;
        }
        if ([state isEqualToString:@"choice"]) {
            NSArray<NSDictionary *> *choices = plan[@"choices"];
            NSUInteger depth = [plan[@"choice_depth"] unsignedIntegerValue];
            int selected = -1;
            float best = -INFINITY;
            for (NSDictionary *choice in choices) {
                NSArray<NSNumber *> *ids = choice[@"tokens"];
                if (depth >= ids.count) return -1;
                int token = ids[depth].intValue;
                if (token >= 0 && token < VOCAB_SIZE &&
                    (selected < 0 || logits[token] > best)) {
                    selected = token;
                    best = logits[token];
                }
            }
            if (selected < 0) return -1;
            NSMutableArray *remaining = [NSMutableArray array];
            NSDictionary *complete = nil;
            for (NSDictionary *choice in choices) {
                NSArray<NSNumber *> *ids = choice[@"tokens"];
                if (ids[depth].intValue != selected) continue;
                [remaining addObject:choice];
                if (depth + 1 == ids.count) complete = choice;
            }
            if (complete) {
                NSString *kind = plan[@"choice_kind"];
                NSString *label = complete[@"label"];
                if ([kind isEqualToString:@"function"]) {
                    plan[@"tool"] = label;
                    plan[@"used"] = [NSMutableSet set];
                    plan[@"state"] = @"next";
                } else if ([kind isEqualToString:@"key"]) {
                    [plan[@"used"] addObject:label];
                    plan[@"current_key"] = label;
                    NSDictionary *tool_fn = tool_definition_named(tools, plan[@"tool"]);
                    NSDictionary *properties = tool_fn[@"parameters"][@"properties"];
                    NSDictionary *property = properties[label];
                    BOOL path_key = [@[@"file_path", @"path", @"filename"] containsObject:label];
                    NSString *tool_name = plan[@"tool"];
                    NSString *lower_name = tool_name.lowercaseString;
                    NSString *literal = literal_path_for_tool(plan, lower_name);
                    BOOL can_copy = path_key && [property[@"type"] isEqual:@"string"] &&
                        [literal isKindOfClass:[NSString class]];
                    if (can_copy) plan[@"current_literal_path"] = literal;
                    plan[@"state"] = can_copy ? @"literal_value" : @"value";
                } else if ([kind isEqualToString:@"branch"]) {
                    plan[@"state"] = [label isEqualToString:@"parameter"]
                        ? @"key" : @"call_end";
                    if ([label isEqualToString:@"parameter"])
                        plan[@"key_mode"] = @"optional";
                } else return -1;
                [plan removeObjectForKey:@"choices"];
            } else {
                plan[@"choices"] = remaining;
                plan[@"choice_depth"] = @(depth + 1);
            }
            return selected;
        }
        if ([state isEqualToString:@"value"]) {
            if (sampled == EOS_TOKEN_1 || sampled == EOS_TOKEN_2 ||
                sampled == TOOL_CALL_END_TOKEN || sampled == TOOL_CALL_START_TOKEN ||
                sampled == TOOL_RESP_START_TOKEN || sampled == TOOL_RESP_END_TOKEN ||
                sampled == THINK_START_TOKEN || sampled == THINK_END_TOKEN)
                return -2; // malformed value; never manufacture its closing tag
            return sampled;
        }
        if ([state isEqualToString:@"literal_value"]) {
            NSString *path = plan[@"current_literal_path"];
            NSString *wire = [NSString stringWithFormat:@"%@\n</parameter>\n", path];
            NSArray *tokens = tool_wire_tokens(wire);
            if (!tokens || !tool_wire_force(plan, wire, @"next")) return -1;
            fprintf(stderr, "[tool-decode] literal path matched param=%s value=\"%s\"; forcing %lu tokens\n",
                    [plan[@"current_key"] UTF8String],
                    path.UTF8String, (unsigned long)tokens.count);
            continue;
        }
        if ([state isEqualToString:@"dynamic_keys"]) return sampled;
        if ([state isEqualToString:@"call_end"]) {
            plan[@"state"] = @"done";
            return TOOL_CALL_END_TOKEN;
        }
        return -1;
    }
    return -1;
}

// Temporary audit self-test for tool/schema validation (#5).
// Runs without loading a model: ./infer --self-test-tools
static int run_tool_schema_self_tests(void) {
    __block int failures = 0;

    void (^check_invalid)(NSString *, NSString *, NSArray<NSDictionary *> *, NSString *) =
        ^(NSString *label, NSString *raw, NSArray<NSDictionary *> *tools, NSString *expected_substring) {
            BOOL valid = YES;
            NSString *error = nil;
            NSUInteger complete = 0;
            NSArray *calls = parse_qwen_tool_calls(raw, tools, &valid, &error, &complete);
            BOOL passed = !valid && calls.count == 0 &&
                (!expected_substring || [error rangeOfString:expected_substring].location != NSNotFound);
            printf("[tool-self-test] %s: %s", label.UTF8String, passed ? "PASS" : "FAIL");
            if (!passed) {
                printf(" (valid=%s calls=%lu complete=%lu error=%s)",
                       valid ? "true" : "false",
                       (unsigned long)calls.count,
                       (unsigned long)complete,
                       error ? error.UTF8String : "(nil)");
                failures++;
            }
            printf("\n");
        };

    NSArray<NSDictionary *> *string_tool = @[
        @{
            @"type": @"function",
            @"function": @{
                @"name": @"real_tool",
                @"parameters": @{
                    @"type": @"object",
                    @"properties": @{@"value": @{@"type": @"string"}},
                    @"required": @[@"value"],
                    @"additionalProperties": @NO
                }
            }
        }
    ];

    check_invalid(@"unknown tool",
        @"<tool_call>\n<function=ghost_tool>\n<parameter=value>\nhello\n</parameter>\n</function>\n</tool_call>",
        string_tool, @"unknown tool 'ghost_tool'");

    check_invalid(@"missing required argument",
