        string_tool, @"malformed native tool call");

    check_invalid(@"multiple functions in one call",
        @"<tool_call>\n<function=real_tool>\n<parameter=value>\none\n</parameter>\n</function>\n<function=real_tool>\n<parameter=value>\ntwo\n</parameter>\n</function>\n</tool_call>",
        string_tool, @"malformed native tool call");

    check_invalid(@"unclosed extra parameter",
        @"<tool_call>\n<function=real_tool>\n<parameter=value>\nhello\n</parameter>\n<parameter=other>\nBROKEN\n</function>\n</tool_call>",
        string_tool, @"malformed native tool call");

    // Nullable ["string","null"] must preserve JSON null.
    NSArray<NSDictionary *> *nullable_tool = @[
        @{
            @"type": @"function",
            @"function": @{
                @"name": @"nullable_tool",
                @"parameters": @{
                    @"type": @"object",
                    @"properties": @{@"value": @{@"type": @[@"string", @"null"]}},
                    @"required": @[@"value"],
                    @"additionalProperties": @NO
                }
            }
        }
    ];
    {
        BOOL valid = YES;
        NSString *error = nil;
        NSUInteger complete = 0;
        NSArray *calls = parse_qwen_tool_calls(
            @"<tool_call>\n<function=nullable_tool>\n<parameter=value>\nnull\n</parameter>\n</function>\n</tool_call>",
            nullable_tool, &valid, &error, &complete);
        BOOL passed = valid && calls.count == 1;
        if (passed) {
            NSString *args = calls[0][@"function"][@"arguments"];
            NSData *data = [args dataUsingEncoding:NSUTF8StringEncoding];
            NSDictionary *decoded = data
                ? [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL] : nil;
            passed = [decoded[@"value"] isEqual:[NSNull null]];
        }
        printf("[tool-self-test] nullable null preserved: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    // Unsupported unions must be rejected at request-schema validation time.
    void (^check_schema_invalid)(NSString *, NSDictionary *, NSString *) =
        ^(NSString *label, NSDictionary *schema, NSString *expected) {
            NSDictionary *req = @{@"tools": @[
                @{@"type": @"function",
                  @"function": @{@"name": @"schema_tool",
                                  @"parameters": schema}}
            ]};
            BOOL valid = YES;
            NSString *error = nil;
            NSArray *parsed = parse_request_tools(req, &valid, &error);
            BOOL passed = !valid && parsed == nil &&
                (!expected || [error rangeOfString:expected].location != NSNotFound);
            printf("[tool-self-test] %s: %s\n",
                   label.UTF8String, passed ? "PASS" : "FAIL");
            if (!passed) failures++;
        };

    check_schema_invalid(@"anyOf rejected",
        @{@"type": @"object",
          @"properties": @{@"value": @{@"anyOf": @[
              @{@"type": @"string"}, @{@"type": @"integer"}
          ]}}},
        @"unsupported anyOf");

    check_schema_invalid(@"general multi-type rejected",
        @{@"type": @"object",
          @"properties": @{@"value": @{@"type": @[@"string", @"integer"]}}},
        @"unsupported multi-type");

    check_schema_invalid(@"non-object root rejected",
        @{@"type": @"string"}, @"root type object");

    {
        NSDictionary *req = @{@"tools": @[
            @{@"type": @"function", @"function": @{@"name": @"1-read"}}
        ]};
        BOOL valid = YES;
        NSArray *parsed = parse_request_tools(req, &valid, NULL);
        NSDictionary *params = parsed.firstObject[@"function"][@"parameters"];
        BOOL passed = valid && parsed.count == 1 &&
            [params[@"additionalProperties"] isEqual:@NO];
        printf("[tool-self-test] omitted parameters normalized empty: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        BOOL call_valid = YES;
        parse_qwen_tool_calls(
            @"<tool_call>\n<function=1-read>\n<parameter=surprise>\nx\n</parameter>\n</function>\n</tool_call>",
            parsed, &call_valid, NULL, NULL);
        passed = !call_valid;
        printf("[tool-self-test] omitted parameters reject arguments: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    // Full-history sequencing.
    void (^check_history)(NSString *, NSArray<NSDictionary *> *, BOOL) =
        ^(NSString *label, NSArray<NSDictionary *> *history, BOOL expect_valid) {
            NSString *error = nil;
            BOOL valid = validate_chat_tool_history(history, &error);
            BOOL passed = valid == expect_valid;
            printf("[tool-self-test] %s: %s\n",
                   label.UTF8String, passed ? "PASS" : "FAIL");
            if (!passed) failures++;
        };

    NSDictionary *hist_call_a =
        @{@"id": @"call_a", @"type": @"function",
          @"function": @{@"name": @"real_tool", @"arguments": @"{\"value\":\"a\"}"}};
    NSDictionary *hist_call_b =
        @{@"id": @"call_b", @"type": @"function",
          @"function": @{@"name": @"real_tool", @"arguments": @"{\"value\":\"b\"}"}};

    check_history(@"orphan tool result rejected",
        @[@{@"role": @"user", @"content": @"x"},
          @{@"role": @"tool", @"tool_call_id": @"call_a", @"content": @"ok"}],
        NO);

    check_history(@"wrong tool_call_id rejected",
        @[@{@"role": @"user", @"content": @"x"},
          @{@"role": @"assistant", @"content": @"", @"tool_calls": @[hist_call_a]},
          @{@"role": @"tool", @"tool_call_id": @"wrong", @"content": @"ok"}],
        NO);

    check_history(@"out-of-order tool results rejected",
        @[@{@"role": @"user", @"content": @"x"},
          @{@"role": @"assistant", @"content": @"", @"tool_calls": @[hist_call_a, hist_call_b]},
          @{@"role": @"tool", @"tool_call_id": @"call_b", @"content": @"b"},
          @{@"role": @"tool", @"tool_call_id": @"call_a", @"content": @"a"}],
        NO);

    check_history(@"complete ordered tool history accepted",
        @[@{@"role": @"user", @"content": @"x"},
          @{@"role": @"assistant", @"content": @"", @"tool_calls": @[hist_call_a, hist_call_b]},
          @{@"role": @"tool", @"tool_call_id": @"call_a", @"content": @"a"},
          @{@"role": @"tool", @"tool_call_id": @"call_b", @"content": @"b"},
          @{@"role": @"assistant", @"content": @"done"}],
        YES);

    // Explicitly supplied invalid session_id values must not become stateless.
    void (^check_session)(NSString *, NSDictionary *, BOOL) =
        ^(NSString *label, NSDictionary *req, BOOL expect_valid) {
            char buf[64] = {0};
            BOOL has = NO;
            NSString *error = nil;
            BOOL valid = parse_request_session_id(req, buf, sizeof(buf), &has, &error);
            BOOL passed = valid == expect_valid;
            printf("[tool-self-test] %s: %s\n",
                   label.UTF8String, passed ? "PASS" : "FAIL");
            if (!passed) failures++;
        };
    check_session(@"invalid session_id type rejected", @{@"session_id": @123}, NO);
    check_session(@"empty session_id rejected", @{@"session_id": @""}, NO);

    {
        const uint32_t repeating[] = {11, 12, 13, 11, 12, 13, 11, 12, 13};
        const uint32_t ordinary[] = {11, 12, 13, 11, 12, 14, 11, 12, 13};
        const uint32_t single[] = {9, 9, 9};
        BOOL passed = repeated_content_next_token(repeating, 9) == 11 &&
            repeated_content_next_token(ordinary, 9) == -1 &&
            repeated_content_next_token(single, 3) == 9;
        printf("[tool-self-test] repeated content guard: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    {
        NSDictionary *safe_call = @{@"id": @"call_1", @"type": @"function",
            @"function": @{@"name": @"old_tool", @"arguments": @"{\"old_key\":\"x\"}"}};
        NSDictionary *bad_name = @{@"id": @"call_1", @"type": @"function",
            @"function": @{@"name": @"bad>name", @"arguments": @"{}"}};
        NSDictionary *bad_key = @{@"id": @"call_1", @"type": @"function",
            @"function": @{@"name": @"old_tool", @"arguments": @"{\"bad>key\":1}"}};
        NSArray *(^history)(NSDictionary *) = ^NSArray *(NSDictionary *call) {
            return @[@{@"role": @"user", @"content": @"test"},
                     @{@"role": @"assistant", @"content": @"", @"tool_calls": @[call]},
                     @{@"role": @"tool", @"tool_call_id": @"call_1", @"content": @"done"}];
        };
        BOOL passed = parse_chat_messages(@{@"messages": history(safe_call)}) != nil &&
            parse_chat_messages(@{@"messages": history(bad_name)}) == nil &&
            parse_chat_messages(@{@"messages": history(bad_key)}) == nil;
        printf("[tool-self-test] historical wire names validated: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    {
        NSDictionary *tool_fn = @{@"parameters": @{@"type": @"object",
            @"properties": @{@"file_path": @{@"type": @"string"},
                              @"encoding": @{@"type": @"string"}},
            @"required": @[@"file_path"]}};
        NSMutableSet *used = [NSMutableSet set];
        BOOL passed = [tool_wire_available_keys(tool_fn, used, YES)
                            isEqualToArray:@[@"file_path"]] &&
            [tool_wire_available_keys(tool_fn, used, NO)
                            isEqualToArray:@[@"encoding"]];
        [used addObject:@"file_path"];
        passed = passed && tool_wire_available_keys(tool_fn, used, YES).count == 0;
        printf("[tool-self-test] schema-driven parameter choices: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSDictionary *dynamic_fn = @{@"parameters": @{@"type": @"object",
            @"additionalProperties": @YES}};
        passed = tool_wire_allows_dynamic_keys(dynamic_fn) &&
            !tool_wire_allows_dynamic_keys(@{@"parameters": @{
                @"type": @"object", @"additionalProperties": @NO}});
        printf("[tool-self-test] dynamic parameters select free-form fallback: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        for (NSString *ending in @[@"</parameter>\n", @"</parameter>\r\n"]) {
            NSString *wire = [@"<tool_call>\n<function=execute>\n<parameter=command>\necho hi\n"
                stringByAppendingString:ending];
            passed = tool_wire_parameter_closed(wire) &&
                !tool_wire_parameter_closed(@"<parameter=command>\necho hi");
            printf("[tool-self-test] parameter closes with %s: %s\n",
                   [ending hasSuffix:@"\r\n"] ? "CRLF" : "LF",
                   passed ? "PASS" : "FAIL");
            if (!passed) failures++;
        }
    }

    if (g_model_path_for_tokenizer) {
        init_tokenizer();
        NSMutableDictionary *plan = [NSMutableDictionary dictionary];
        NSArray *schema = @[
            @{@"type": @"function", @"function":
                @{@"name": @"read", @"parameters": @{@"type": @"object",
                    @"properties": @{@"file_path": @{@"type": @"string"}},
                    @"required": @[@"file_path"], @"additionalProperties": @NO}}},
            @{@"type": @"function", @"function":
                @{@"name": @"execute", @"parameters": @{@"type": @"object",
                    @"properties": @{@"command": @{@"type": @"string"}},
                    @"required": @[@"command"], @"additionalProperties": @NO}}}
        ];
        float *scores = calloc(VOCAB_SIZE, sizeof(float));
        NSArray<NSNumber *> *execute_name_tokens = tool_wire_tokens(@"execute>\n");
        if (scores && execute_name_tokens.count)
            scores[execute_name_tokens.firstObject.intValue] = 10.0f;
        char vocab_file[1024];
        snprintf(vocab_file, sizeof(vocab_file), "%s/vocab.bin", g_model_path_for_tokenizer);
        Vocabulary *test_vocab = load_vocab(vocab_file);
        NSMutableDictionary *dynamic_plan = [@{@"state": @"next",
            @"tool": @"dynamic", @"used": [NSMutableSet set]} mutableCopy];
        NSArray *dynamic_schema = @[@{@"type": @"function", @"function":
            @{@"name": @"dynamic", @"parameters": @{@"type": @"object",
                @"additionalProperties": @YES}}}];
        int free_token = 123;
        BOOL dynamic_passed = tool_wire_next_token(dynamic_plan, dynamic_schema,
            scores, free_token) == free_token &&
            [dynamic_plan[@"state"] isEqualToString:@"dynamic_keys"] &&
            tool_wire_next_token(dynamic_plan, dynamic_schema, scores,
                TOOL_CALL_END_TOKEN) == TOOL_CALL_END_TOKEN;
        printf("[tool-self-test] dynamic parameter decoding remains unconstrained: %s\n",
               dynamic_passed ? "PASS" : "FAIL");
        if (!dynamic_passed) failures++;
        NSArray<NSNumber *> *value_tokens = tool_wire_tokens(@"echo hi\n</parameter>\n");
        Utf8TokenStream stream = {0};
        NSMutableString *raw = [NSMutableString stringWithString:@"<tool_call>"];
        BOOL passed = g_tokenizer_loaded && scores && test_vocab && value_tokens &&
            tool_wire_force(plan, @"\n<function=", @"function");
        NSUInteger value_index = 0;
        BOOL finished = NO;
        for (int i = 0; passed && i < 100 && !finished; i++) {
            int sampled = 0;
            if ([plan[@"state"] isEqualToString:@"value"] &&
                value_index < value_tokens.count)
                sampled = value_tokens[value_index++].intValue;
            int token = tool_wire_next_token(plan, schema, scores, sampled);
            if (token == TOOL_CALL_END_TOKEN) {
                [raw appendString:@"</tool_call>"];
                finished = YES;
                break;
            }
            passed = token >= 0 && token < VOCAB_SIZE;
            if (!passed) break;
            char *piece = utf8_token_stream_push_token(&stream, test_vocab, token);
            if (piece) {
                NSString *decoded = [NSString stringWithUTF8String:piece];
                if (decoded) [raw appendString:decoded];
                free(piece);
            }
            if ([plan[@"state"] isEqualToString:@"value"] &&
                tool_wire_parameter_closed(raw))
                plan[@"state"] = @"next";
        }
        BOOL valid = NO;
        NSArray *calls = finished ? parse_qwen_tool_calls(raw, schema, &valid, NULL, NULL) : @[];
        NSString *args = calls.count ? calls[0][@"function"][@"arguments"] : nil;
        NSDictionary *decoded = args ? [NSJSONSerialization JSONObjectWithData:
            [args dataUsingEncoding:NSUTF8StringEncoding] options:0 error:NULL] : nil;
        passed = passed && finished && valid && calls.count == 1 &&
            [plan[@"tool"] isEqualToString:@"execute"] &&
            [decoded[@"command"] isEqualToString:@"echo hi"];
        printf("[tool-self-test] tokenizer-backed generic tool call: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSMutableDictionary *interrupted = [@{@"state": @"value"} mutableCopy];
        BOOL rejected = YES;
        for (NSNumber *control in @[@(EOS_TOKEN_1), @(EOS_TOKEN_2),
            @(TOOL_CALL_END_TOKEN), @(TOOL_CALL_START_TOKEN),
            @(TOOL_RESP_START_TOKEN), @(THINK_END_TOKEN)]) {
            int result = tool_wire_next_token(interrupted, schema, scores,
                                               control.intValue);
            rejected = rejected && result == -2 &&
                [interrupted[@"state"] isEqualToString:@"value"] &&
                interrupted[@"forced"] == nil;
        }
        NSString *partial = @"<tool_call>\n<function=execute>\n<parameter=command>\nrm -rf /some/par";
        BOOL parsed_valid = YES;
        NSArray *partial_calls = parse_qwen_tool_calls(partial, schema,
            &parsed_valid, NULL, NULL);
        rejected = rejected && partial_calls.count == 0;
        printf("[tool-self-test] interrupted value cannot become a call: %s\n",
               rejected ? "PASS" : "FAIL");
        if (!rejected) failures++;
        NSString *literal = @"/Users/Shared/Main Hard Drive/AI Storage/Apps/Flash-iOS/example.txt";
        NSString *literal_wire = [NSString stringWithFormat:@"%@\n</parameter>\n", literal];
        NSArray *literal_tokens = tool_wire_tokens(literal_wire);
        NSMutableDictionary *literal_plan = [@{@"state": @"literal_value",
            @"tool": @"read", @"current_key": @"file_path",
            @"literal_path": literal, @"used": [NSMutableSet setWithObject:@"file_path"]}
            mutableCopy];
        int first_literal_token = tool_wire_next_token(literal_plan, schema, scores,
                                                        EOS_TOKEN_1);
        BOOL copied = literal_tokens.count > 0 &&
            first_literal_token == [literal_tokens[0] intValue] &&
            [literal_plan[@"forced"] isEqualToArray:literal_tokens] &&
            [literal_plan[@"after_force"] isEqualToString:@"next"];
        printf("[tool-self-test] path value forces full literal and close: %s\n",
               copied ? "PASS" : "FAIL");
        if (!copied) failures++;
        free_vocabulary(test_vocab);
        free(scores);
    }

    // Exact-copy is activated only for a single explicit path and compatible
    // read schema. This exercises the same body used by the decode path.
    {
        NSArray *read_tools = @[@{@"type": @"function", @"function":
            @{@"name": @"read", @"parameters": @{@"type": @"object",
                @"properties": @{@"file_path": @{@"type": @"string"}},
                @"required": @[@"file_path"], @"additionalProperties": @NO}}}];
        NSString *path = @"/Users/Shared/Main Hard Drive/AI Storage/Apps/Flash-iOS/tools.json";
        NSString *prompt = [NSString stringWithFormat:@"Read this exact path:\n%@\nUse the Read tool.", path];
        NSString *body = exact_literal_read_call(@[@{@"role": @"user", @"content": prompt}], read_tools);
        BOOL passed = [body containsString:@"<function=read>"] &&
            [body containsString:@"<parameter=file_path>"] && [body containsString:path];
        printf("[tool-self-test] exact read path and schema name: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSString *unnamed = [NSString stringWithFormat:@"Read this exact path:\n%@", path];
        passed = exact_literal_read_call(
            @[@{@"role": @"user", @"content": unnamed}], read_tools) == nil;
        printf("[tool-self-test] unnamed exact read left to model: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSString *whole = body ? [NSString stringWithFormat:@"<tool_call>%@</tool_call>", body] : nil;
        BOOL valid = NO;
        NSArray *calls = parse_qwen_tool_calls(whole, read_tools, &valid, NULL, NULL);
        NSString *args = calls.count ? calls[0][@"function"][@"arguments"] : nil;
        NSDictionary *decoded = args ? [NSJSONSerialization JSONObjectWithData:
            [args dataUsingEncoding:NSUTF8StringEncoding] options:0 error:NULL] : nil;
        passed = valid && [decoded[@"file_path"] isEqualToString:path];
        printf("[tool-self-test] copied path validates unchanged: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSString *inline_prompt = [NSString stringWithFormat:
            @"Read this exact path and do not modify, shorten, normalize, or infer any part of it: %@ Use the Read tool exactly once, with that exact path as the argument.", path];
        NSString *inline_body = exact_literal_read_call(
            @[@{@"role": @"user", @"content": inline_prompt}], read_tools);
        passed = [inline_body containsString:[NSString stringWithFormat:
            @"<parameter=file_path>\n%@\n</parameter>", path]];
        printf("[tool-self-test] inline literal with spaces copied: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSArray *also_image = [read_tools arrayByAddingObject:
            @{@"type": @"function", @"function":
                @{@"name": @"read_image", @"parameters": @{@"type": @"object",
                    @"properties": @{@"file_path": @{@"type": @"string"}},
                    @"required": @[@"file_path"]}}}];
        NSString *with_image = exact_literal_read_call(
            @[@{@"role": @"user", @"content": inline_prompt}], also_image);
        passed = [with_image containsString:@"<function=read>"] &&
            ![with_image containsString:@"<function=read_image>"];
        printf("[tool-self-test] explicit tool disambiguates read_image: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSString *multiple = @"Read these paths:\n/tmp/a.txt\n/tmp/b.txt";
        passed = exact_literal_read_call(@[@{@"role": @"user", @"content": multiple}], read_tools) == nil;
        printf("[tool-self-test] ambiguous paths left to model: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        NSArray *path_cases = @[
            @"beer_singer.c", @"hello.txt", @"src/foo.c", @"./test.c",
            @"/tmp/file.txt.bak",
            @"/tmp/a.txt",
            @"/Users/Shared/Main Hard Drive/AI Storage/Apps/Flash-iOS/example.txt",
            @"/Users/Shared/Main Hard Drive/Flash-iOS/Flash-iOS/example.json"
        ];
        passed = YES;
        for (NSString *literal in path_cases) {
            NSString *input = [NSString stringWithFormat:@"Read %@ and report its first line.", literal];
            NSString *found = unambiguous_literal_file_path(
                @[@{@"role": @"user", @"content": input}]);
            if (![found isEqualToString:literal]) passed = NO;
        }
        passed = passed && unambiguous_literal_file_path(
            @[@{@"role": @"user", @"content": @"Read /tmp/a.txt and /tmp/b.txt"}]) == nil;
        printf("[tool-self-test] unambiguous absolute file literals: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        passed = exact_literal_read_call(@[@{@"role": @"user", @"content": @"Search for storage options"}], read_tools) == nil;
        printf("[tool-self-test] ordinary request unaffected: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    // Alphabetical ordering must make differently ordered identical tool sets
    // produce the same canonical context signature, while default/client-order
    // mode must continue to distinguish them.
    {
        NSArray *ab = @[
            @{@"type": @"function",
              @"function": @{@"name": @"alpha",
                              @"parameters": @{@"type": @"object"}}},
            @{@"type": @"function",
              @"function": @{@"name": @"beta",
                              @"parameters": @{@"type": @"object"}}}
        ];
        NSArray *ba = @[ab[1], ab[0]];
        int saved_sort = g_sort_tools_alpha_enabled;

        g_sort_tools_alpha_enabled = 0;
        uint64_t unsorted_ab = tool_context_signature(ab, @"auto");
        uint64_t unsorted_ba = tool_context_signature(ba, @"auto");

        g_sort_tools_alpha_enabled = 1;
        uint64_t sorted_ab = tool_context_signature(ab, @"auto");
        uint64_t sorted_ba = tool_context_signature(ba, @"auto");

        g_sort_tools_alpha_enabled = saved_sort;
        BOOL passed = unsorted_ab != unsorted_ba && sorted_ab == sorted_ba;
        printf("[tool-self-test] alphabetical tool ordering: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
    }

    {
        NSString *test_dir = [NSTemporaryDirectory() stringByAppendingPathComponent:
            [NSString stringWithFormat:@"flash-tool-cache-test-%@", NSUUID.UUID.UUIDString]];
        NSString *project_cache = project_tool_set_cache_directory();
        NSString *original_cwd = [[NSFileManager defaultManager] currentDirectoryPath];
        BOOL made_test_dir = [[NSFileManager defaultManager]
            createDirectoryAtPath:test_dir withIntermediateDirectories:YES
            attributes:nil error:NULL];
        BOOL changed_dir = made_test_dir && [[NSFileManager defaultManager]
            changeCurrentDirectoryPath:test_dir];
        NSString *cache_from_other_cwd = project_tool_set_cache_directory();
        BOOL restored_dir = [[NSFileManager defaultManager]
            changeCurrentDirectoryPath:original_cwd];
        BOOL passed = changed_dir && restored_dir &&
            [project_cache isEqualToString:cache_from_other_cwd] &&
            [project_cache hasSuffix:@"/warm-tools-cache"] &&
            [project_cache isAbsolutePath];
        printf("[tool-self-test] tool-set directory follows executable across cwd: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSDictionary *alpha = @{@"type": @"function", @"function": @{
            @"name": @"alpha", @"description": @"Keep this original description",
            @"parameters": @{@"type": @"object", @"properties": @{
                @"choice": @{@"type": @"string", @"enum": @[@"a", @"b"]},
                @"options": @{@"type": @"object", @"properties": @{
                    @"timeout": @{@"type": @"integer"}}, @"required": @[@"timeout"]}},
                @"required": @[@"choice"], @"additionalProperties": @NO}}};
        NSDictionary *beta = @{@"type": @"function", @"function": @{
            @"name": @"beta", @"parameters": @{@"type": @"object",
                @"properties": @{@"query": @{@"type": @"string"}},
                @"required": @[@"query"]}}};
        NSArray *original = @[alpha, beta];
        BOOL schema_valid = YES;
        NSArray *normalized = parse_request_tools(@{@"tools": original},
                                                    &schema_valid, NULL);
        uint64_t signature = tool_set_signature(normalized);
        BOOL mode_independent = signature != 0 &&
            tool_context_signature(normalized, @"auto") !=
            tool_context_signature(normalized, @"required") &&
            signature == tool_set_signature(normalized);
        printf("[tool-self-test] file identity ignores tool mode: %s\n",
               mode_independent ? "PASS" : "FAIL");
        if (!mode_independent) failures++;
        NSString *saved_path = nil;
        int first = remember_requested_tool_set(original, signature, test_dir,
                                                 &saved_path);
        NSData *saved_data = [NSData dataWithContentsOfFile:saved_path];
        id saved = saved_data ? [NSJSONSerialization JSONObjectWithData:saved_data
                                                  options:0 error:NULL] : nil;
        BOOL warm_valid = YES;
        NSArray *warm_tools = [saved isKindOfClass:[NSArray class]]
            ? parse_request_tools(@{@"tools": saved}, &warm_valid, NULL) : nil;
        passed = schema_valid && first == 1 &&
            [saved isEqual:original] && warm_valid && warm_tools.count == 2;
        printf("[tool-self-test] unseen set preserves full warm-loadable JSON: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        struct stat before = {0}, after = {0};
        BOOL before_ok = saved_path && stat(saved_path.fileSystemRepresentation, &before) == 0;
        int repeated = remember_requested_tool_set(original, signature, test_dir, NULL);
        BOOL after_ok = saved_path && stat(saved_path.fileSystemRepresentation, &after) == 0;
        passed = before_ok && after_ok && repeated == 0 &&
            before.st_ino == after.st_ino &&
            before.st_size == after.st_size &&
            [[NSData dataWithContentsOfFile:saved_path] isEqual:saved_data];
        printf("[tool-self-test] repeated set is not rewritten: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSArray *different = @[alpha];
        NSArray *different_normalized = parse_request_tools(
            @{@"tools": different}, NULL, NULL);
        uint64_t different_sig = tool_set_signature(different_normalized);
        NSString *different_path = nil;
        int different_result = remember_requested_tool_set(
            different, different_sig, test_dir, &different_path);
        passed = different_sig != signature && different_result == 1 &&
            ![different_path isEqualToString:saved_path];
        printf("[tool-self-test] distinct set gets distinct file: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSArray *reversed = @[beta, alpha];
        int saved_sort = g_sort_tools_alpha_enabled;
        g_sort_tools_alpha_enabled = 0;
        uint64_t ordered_sig = tool_set_signature(
            parse_request_tools(@{@"tools": reversed}, NULL, NULL));
        g_sort_tools_alpha_enabled = 1;
        uint64_t sorted_sig = tool_set_signature(
            parse_request_tools(@{@"tools": reversed}, NULL, NULL));
        uint64_t sorted_original_sig = tool_set_signature(normalized);
        g_sort_tools_alpha_enabled = saved_sort;
        int sorted_reuse = remember_requested_tool_set(
            reversed, sorted_sig, test_dir, NULL);
        passed = ordered_sig != signature && sorted_sig == sorted_original_sig &&
            sorted_reuse == 0 &&
            [[NSJSONSerialization JSONObjectWithData:
                [NSData dataWithContentsOfFile:saved_path] options:0 error:NULL]
                isEqual:original];
        printf("[tool-self-test] saved names follow existing order semantics: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSArray *concurrent_tools = @[beta];
        uint64_t concurrent_sig = tool_set_signature(
            parse_request_tools(@{@"tools": concurrent_tools}, NULL, NULL));
        NSLock *results_lock = [NSLock new];
        NSMutableArray<NSNumber *> *results = [NSMutableArray array];
        dispatch_apply(8, dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0),
            ^(size_t index) {
                (void)index;
                @autoreleasepool {
                    int result = remember_requested_tool_set(
                        concurrent_tools, concurrent_sig, test_dir, NULL);
                    [results_lock lock];
                    [results addObject:@(result)];
                    [results_lock unlock];
                }
            });
        NSUInteger creators = 0, reusers = 0;
        for (NSNumber *result in results) {
            if (result.intValue == 1) creators++;
            if (result.intValue == 0) reusers++;
        }
        NSString *concurrent_path = [test_dir stringByAppendingPathComponent:
            [NSString stringWithFormat:@"%016llx.json", (unsigned long long)concurrent_sig]];
        NSData *concurrent_data = [NSData dataWithContentsOfFile:concurrent_path];
        id concurrent_saved = concurrent_data ? [NSJSONSerialization
            JSONObjectWithData:concurrent_data options:0 error:NULL] : nil;
        NSArray *files = [[NSFileManager defaultManager]
            contentsOfDirectoryAtPath:test_dir error:NULL];
        BOOL no_temps = YES;
        for (NSString *file in files)
            if ([file hasSuffix:@".tmp"]) no_temps = NO;
        passed = creators == 1 && reusers == 7 &&
            [concurrent_saved isEqual:concurrent_tools] && no_temps;
        printf("[tool-self-test] concurrent create and temp cleanup: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;

        NSString *empty_dir = [test_dir stringByAppendingPathComponent:@"empty"];
        passed = remember_requested_tool_set(@[], 0, empty_dir, NULL) == 0 &&
            remember_requested_tool_set(nil, 0, empty_dir, NULL) == 0 &&
            ![[NSFileManager defaultManager] fileExistsAtPath:empty_dir];
        printf("[tool-self-test] no-tools request creates nothing: %s\n",
               passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        for (unsigned i = 0; i <= LEARNED_TOOL_SET_LIMIT; i++) {
            NSString *name = [NSString stringWithFormat:@"%016x.json", i];
            [@"{}" writeToFile:[test_dir stringByAppendingPathComponent:name]
                    atomically:YES encoding:NSUTF8StringEncoding error:NULL];
        }
        prune_learned_tool_sets(test_dir, saved_path);
        NSArray *bounded_files = [[NSFileManager defaultManager]
            contentsOfDirectoryAtPath:test_dir error:NULL];
        NSUInteger learned_count = 0;
        for (NSString *name in bounded_files) if (learned_tool_set_name(name)) learned_count++;
        passed = learned_count == LEARNED_TOOL_SET_LIMIT &&
            [[NSFileManager defaultManager] fileExistsAtPath:saved_path];
        printf("[tool-self-test] bounded learned schema eviction: %s\n", passed ? "PASS" : "FAIL");
        if (!passed) failures++;
        [[NSFileManager defaultManager] removeItemAtPath:test_dir error:NULL];
    }

    if (failures == 0) {
        printf("[tool-self-test] RESULT: PASS\n");
        return 0;
    }
    printf("[tool-self-test] RESULT: FAIL (%d failure%s)\n",
           failures, failures == 1 ? "" : "s");
    return 1;
}

