// Write a full HTTP response string to fd
#ifdef FLASH_API_FAULT_TEST
static int g_http_write_fail_on_call = 0;
static int g_http_write_call_count = 0;
#endif
static int http_write(int fd, const char *data, int len) {
#ifdef FLASH_API_FAULT_TEST
	if (g_http_write_fail_on_call &&
		++g_http_write_call_count == g_http_write_fail_on_call) return -1;
#endif
	int sent = 0;
	while (sent < len) {
		ssize_t w = write(fd, data + sent, len - sent);
		if (w < 0 && errno == EINTR) continue;
		if (w <= 0) return -1;
		sent += (int)w;
	}
	return 0;
}

static int http_write_str(int fd, const char *s) {
	return http_write(fd, s, (int)strlen(s));
}

// A peer FIN only closes its request-writing direction; it may still be reading
// our response. Treat only socket errors/resets as definitive here. Streaming
// writes and final response writes independently detect failed delivery.
static int http_client_disconnected(int fd) {
	struct pollfd pfd = { .fd = fd, .events = POLLIN, .revents = 0 };
	int ready;
	do { ready = poll(&pfd, 1, 0); } while (ready < 0 && errno == EINTR);
	if (ready < 0) return 1;
	if (ready == 0) return 0;
	if (pfd.revents & (POLLERR | POLLNVAL)) return 1;
	if (pfd.revents & POLLIN) {
		char byte;
		ssize_t n;
		do { n = recv(fd, &byte, 1, MSG_PEEK | MSG_DONTWAIT); }
		while (n < 0 && errno == EINTR);
		if (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK) return 1;
	}
	return 0;
}

// Send an SSE chunk with a reasoning or final-answer token delta.
// Returns 0 on success, -1 if client disconnected
static int sse_send_delta(int fd, const char *request_id, const char *field,
					  const char *token_text) {
	if (!request_id || !field || !token_text) return -1;
	size_t text_len = strlen(token_text);
	if (text_len > (SIZE_MAX - 1u) / 6u) return -1;
	size_t escaped_cap = text_len * 6u + 1u;
	char *escaped = malloc(escaped_cap);
	if (!escaped) return -1;
	char *w = escaped;
	for (const unsigned char *r = (const unsigned char *)token_text; *r; r++) {
		switch (*r) {
			case '"':  *w++ = '\\'; *w++ = '"';  break;
			case '\\': *w++ = '\\'; *w++ = '\\'; break;
			case '\n': *w++ = '\\'; *w++ = 'n';  break;
			case '\r': *w++ = '\\'; *w++ = 'r';  break;
			case '\t': *w++ = '\\'; *w++ = 't';  break;
			default:
				if (*r < 0x20) {
					snprintf(w, 7, "\\u%04x", *r);
					w += 6;
				} else *w++ = (char)*r;
				break;
		}
	}
	*w = '\0';

	const char *fmt =
		"data: {\"id\":\"%s\",\"object\":\"chat.completion.chunk\","
		"\"choices\":[{\"index\":0,\"delta\":{\"%s\":\"%s\"},\"finish_reason\":null}]}\n\n";
	int needed = snprintf(NULL, 0, fmt, request_id, field, escaped);
	if (needed < 0 || (size_t)needed > SIZE_MAX - 1u) { free(escaped); return -1; }
	char *chunk = malloc((size_t)needed + 1u);
	if (!chunk) { free(escaped); return -1; }
	snprintf(chunk, (size_t)needed + 1u, fmt, request_id, field, escaped);
	free(escaped);

	size_t sent = 0;
	while (sent < (size_t)needed) {
		ssize_t wr = write(fd, chunk + sent, (size_t)needed - sent);
		if (wr < 0 && errno == EINTR) continue;
		if (wr <= 0) { free(chunk); return -1; }
		sent += (size_t)wr;
	}
	free(chunk);
	return 0;
}

// Emit a valid, empty Chat Completions chunk during long prefill. Some clients
// do not count SSE comments as stream activity, while an empty delta changes
// neither assistant text nor tool calls.
static int sse_send_keepalive(int fd, const char *request_id) {
    char event[256];
    int length = snprintf(event, sizeof(event),
        "data: {\"id\":\"%s\",\"object\":\"chat.completion.chunk\","
        "\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":null}]}\n\n",
        request_id);
    if (length <= 0 || length >= (int)sizeof(event)) return -1;
    size_t sent = 0;
    while (sent < (size_t)length) {
        ssize_t n = write(fd, event + sent, (size_t)length - sent);
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) return -1;
        sent += (size_t)n;
    }
    return 0;
}

#ifdef FLASH_PREFILL_NROW_PRODUCTION
typedef struct {
    int client_fd;
    int stream_response;
    const char *request_id;
    double *last_keepalive_ms;
    int *client_disconnected;
} ServeNRowPollContext;

static int serve_nrow_poll(void *opaque) {
    ServeNRowPollContext *ctx = (ServeNRowPollContext *)opaque;
    if (!ctx) return 1;
    if (http_client_disconnected(ctx->client_fd)) {
        if (ctx->client_disconnected) *ctx->client_disconnected = 1;
        return 0;
    }
    if (ctx->stream_response && ctx->last_keepalive_ms &&
        now_ms() - *ctx->last_keepalive_ms >= 10000.0) {
        if (sse_send_keepalive(ctx->client_fd, ctx->request_id) < 0) {
            if (ctx->client_disconnected) *ctx->client_disconnected = 1;
            return 0;
        }
        *ctx->last_keepalive_ms = now_ms();
    }
    return 1;
}
#endif

static int sse_send_tool_calls(int fd, const char *request_id,
                               NSArray<NSDictionary *> *tool_calls) {
    for (NSUInteger i = 0; i < tool_calls.count; i++) {
        NSDictionary *tc = tool_calls[i];
        NSDictionary *fn = [tc[@"function"] isKindOfClass:[NSDictionary class]]
            ? tc[@"function"] : @{};
        NSDictionary *delta_call = @{
            @"index": @(i),
            @"id": tc[@"id"] ?: @"",
            @"type": @"function",
            @"function": @{
                @"name": fn[@"name"] ?: @"",
                @"arguments": fn[@"arguments"] ?: @"{}"
            }
        };
        NSDictionary *chunk_obj = @{
            @"id": [NSString stringWithUTF8String:request_id],
            @"object": @"chat.completion.chunk",
            @"choices": @[@{
                @"index": @0,
                @"delta": @{@"tool_calls": @[delta_call]},
                @"finish_reason": [NSNull null]
            }]
        };
        NSData *json = [NSJSONSerialization dataWithJSONObject:chunk_obj options:0 error:NULL];
        if (!json) return -1;
        NSString *line = [[NSString alloc] initWithData:json encoding:NSUTF8StringEncoding];
        NSString *event = [NSString stringWithFormat:@"data: %@\n\n", line];
        const char *bytes = event.UTF8String;
        int len = (int)strlen(bytes);
        int sent = 0;
        while (sent < len) {
            ssize_t wr = write(fd, bytes + sent, (size_t)(len - sent));
            if (wr <= 0) return -1;
            sent += (int)wr;
        }
    }
    return 0;
}

static NSDictionary *completion_usage(int prompt_tokens, int completion_tokens) {
    return @{ @"prompt_tokens": @(prompt_tokens),
              @"completion_tokens": @(completion_tokens),
              @"total_tokens": @(prompt_tokens + completion_tokens) };
}

static NSDictionary *malformed_tool_recovery_response(const char *request_id,
                                                      NSString *reason,
                                                      int prompt_tokens,
                                                      int completion_tokens,
                                                      NSDictionary *flash_timings) {
    NSString *text = [NSString stringWithFormat:
        @"Tool call rejected by the server: %@. The generated tool call was invalid. "
         "Retry using the tool's exact schema and preserve the user's argument values exactly.",
        reason ?: @"malformed tool call"];
    return @{
        @"id": [NSString stringWithUTF8String:request_id],
        @"object": @"chat.completion",
        @"model": @"qwen3.5",
        @"usage": completion_usage(prompt_tokens, completion_tokens),
        @"flash_timings": flash_timings ?: @{},
        @"session_invalidated": @YES,
        @"resend_full_history": @YES,
        @"choices": @[@{ @"index": @0,
            @"message": @{ @"role": @"assistant", @"content": text },
            @"finish_reason": @"stop" }]
    };
}

static int logical_prompt_token_count(int request_tokens, int resident_session_tokens) {
    return request_tokens + resident_session_tokens;
}

static BOOL stream_usage_requested(NSDictionary *request) {
    NSDictionary *options = [request[@"stream_options"] isKindOfClass:[NSDictionary class]]
        ? request[@"stream_options"] : nil;
    return [options[@"include_usage"] isKindOfClass:[NSNumber class]] &&
        [options[@"include_usage"] boolValue];
}

static int sse_send_done(int fd, const char *request_id, const char *finish_reason,
                          int include_usage, int prompt_tokens, int completion_tokens,
                          int session_invalidated, NSDictionary *flash_timings) {
    NSMutableDictionary *finish = [@{
        @"id": [NSString stringWithUTF8String:request_id],
        @"object": @"chat.completion.chunk",
        @"choices": @[@{ @"index": @0, @"delta": @{},
            @"finish_reason": [NSString stringWithUTF8String:
                finish_reason ? finish_reason : "stop"] }],
        @"flash_timings": flash_timings ?: @{}
    } mutableCopy];
    if (session_invalidated) {
        finish[@"session_invalidated"] = @YES;
        finish[@"resend_full_history"] = @YES;
    }
    NSData *finish_data = [NSJSONSerialization dataWithJSONObject:finish options:0 error:NULL];
    if (!finish_data || http_write_str(fd, "data: ") < 0 ||
        http_write(fd, finish_data.bytes, (int)finish_data.length) < 0 ||
        http_write_str(fd, "\n\n") < 0) return -1;
    if (include_usage) {
        char chunk[1024];
        int n = snprintf(chunk, sizeof(chunk),
            "data: {\"id\":\"%s\",\"object\":\"chat.completion.chunk\","
            "\"choices\":[],\"usage\":{\"prompt_tokens\":%d,"
            "\"completion_tokens\":%d,\"total_tokens\":%d}}\n\n",
            request_id, prompt_tokens, completion_tokens,
            prompt_tokens + completion_tokens);
        if (n <= 0 || n >= (int)sizeof(chunk) || http_write(fd, chunk, n) < 0)
            return -1;
    }
    return http_write_str(fd, "data: [DONE]\n\n");
}

static int send_session_invalidated_error(
    int fd, int stream_response, NSString *message);

static int run_api_regression_self_tests(void) {
    int failures = 0;
    NSDictionary *test_timings = @{
        @"context_tokens": @2490, @"cached_prefix_tokens": @2258,
        @"prefill_tokens": @232, @"prefill_ms": @4031.2,
        @"prefill_tokens_per_second": @57.55,
        @"generated_tokens": @7, @"decode_ms": @835.0,
        @"decode_tokens_per_second": @8.38,
        @"session_reused": @NO, @"warm_prefix_reused": @YES
    };
    NSDictionary *usage = completion_usage(logical_prompt_token_count(2490, 0), 7);
    BOOL passed = [usage[@"prompt_tokens"] intValue] == 2490 &&
        [usage[@"completion_tokens"] intValue] == 7 &&
        [usage[@"total_tokens"] intValue] == 2497 &&
        logical_prompt_token_count(232, 2258) == 2490 &&
        logical_prompt_token_count(232, 20) == 252;
    printf("[api-self-test] logical and non-stream usage: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    passed = stream_usage_requested(@{ @"stream_options": @{ @"include_usage": @YES } }) &&
        !stream_usage_requested(@{ @"stream_options": @{ @"include_usage": @NO } }) &&
        !stream_usage_requested(@{}) &&
        !stream_usage_requested(@{ @"stream_options": @{ @"include_usage": @"true" } });
    printf("[api-self-test] stream_options.include_usage selection: %s\n",
           passed ? "PASS" : "FAIL");
    if (!passed) failures++;

    int pipefd[2] = {-1, -1};
    if (pipe(pipefd) == 0) {
        sse_send_done(pipefd[1], "test", "stop", 1, 2490, 7, 0, test_timings);
        close(pipefd[1]);
        char output[2048] = {0};
        ssize_t count = read(pipefd[0], output, sizeof(output) - 1);
        close(pipefd[0]);
        NSString *sse = count > 0 ? [NSString stringWithUTF8String:output] : nil;
        NSRange usage_range = [sse rangeOfString:@"\"choices\":[],\"usage\":{" ];
        NSRange timings_range = [sse rangeOfString:@"\"flash_timings\":{" ];
        NSRange done_range = [sse rangeOfString:@"data: [DONE]"];
        passed = sse && usage_range.location != NSNotFound &&
            timings_range.location != NSNotFound && timings_range.location < usage_range.location &&
            done_range.location != NSNotFound && usage_range.location < done_range.location &&
            [sse containsString:@"\"prompt_tokens\":2490"] &&
            [sse containsString:@"\"completion_tokens\":7"] &&
            [sse containsString:@"\"total_tokens\":2497"];
    } else passed = NO;
    printf("[api-self-test] final stream usage before DONE: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;

    if (pipe(pipefd) == 0) {
        sse_send_done(pipefd[1], "test", "stop", 0, 2490, 7, 0, test_timings);
        close(pipefd[1]);
        char output[1024] = {0};
        ssize_t count = read(pipefd[0], output, sizeof(output) - 1);
        close(pipefd[0]);
        NSString *sse = count > 0 ? [NSString stringWithUTF8String:output] : nil;
        passed = [sse containsString:@"data: [DONE]"] &&
            [sse containsString:@"\"flash_timings\""] &&
            ![sse containsString:@"\"usage\""];
    } else passed = NO;
    printf("[api-self-test] stream usage omitted by default: %s\n",
           passed ? "PASS" : "FAIL");
    if (!passed) failures++;

    if (pipe(pipefd) == 0) {
