	"\r\n";

static PromptTokens *tokenize_rendered_messages_with_tools(NSArray<NSDictionary *> *messages,
                                                           NSArray<NSDictionary *> *tools,
                                                           BOOL generation_prompt,
                                                           BOOL enable_thinking) {
    NSString *rendered = render_chat_prompt_with_tools(messages, tools,
                                                       generation_prompt, enable_thinking);
    return rendered ? encode_prompt_text_to_tokens(rendered.UTF8String) : NULL;
}

static PromptTokens *tokenize_rendered_messages(NSArray<NSDictionary *> *messages,
                                                BOOL generation_prompt,
                                                BOOL enable_thinking) {
    return tokenize_rendered_messages_with_tools(messages, nil,
                                                 generation_prompt, enable_thinking);
}

// Load custom system prompt from ~/.flash-moe/system.md, or use default
static char *load_system_prompt(void) {
	static const size_t MAX_SYSTEM_PROMPT = 1024 * 1024;
	const char *home = getenv("HOME");
	if (home) {
		char path[1024];
		snprintf(path, sizeof(path), "%s/.flash-moe/system.md", home);
		FILE *f = fopen(path, "rb");
		if (f) {
			if (fseek(f, 0, SEEK_END) != 0) {
				fprintf(stderr, "[serve] WARNING: cannot seek custom system prompt %s\n", path);
				fclose(f);
			} else {
				long pos = ftell(f);
				if (pos < 0 || (unsigned long)pos > MAX_SYSTEM_PROMPT || fseek(f, 0, SEEK_SET) != 0) {
					fprintf(stderr, "[serve] WARNING: invalid/oversized custom system prompt %s\n", path);
					fclose(f);
				} else {
					size_t sz = (size_t)pos;
					char *buf = malloc(sz + 1);
					if (!buf) {
						fprintf(stderr, "[serve] WARNING: OOM loading custom system prompt %s\n", path);
						fclose(f);
					} else {
						size_t n = fread(buf, 1, sz, f);
						int read_error = ferror(f);
						fclose(f);
						if (read_error || n != sz) {
							fprintf(stderr, "[serve] WARNING: short read loading custom system prompt %s\n", path);
							free(buf);
						} else {
							buf[sz] = 0;
							NSString *valid = [[NSString alloc] initWithBytes:buf length:sz encoding:NSUTF8StringEncoding];
							if (!valid) {
								fprintf(stderr, "[serve] WARNING: custom system prompt is not valid UTF-8: %s\n", path);
								free(buf);
							} else {
								fprintf(stderr, "[serve] Loaded custom system prompt from %s (%zu bytes)\n", path, sz);
								return buf;
							}
						}
					}
				}
			}
		}
	}
	char *fallback = strdup("You are a helpful assistant. /think");
	if (!fallback) fprintf(stderr, "[serve] ERROR: OOM creating default system prompt\n");
	return fallback;
}

static PromptTokens *tokenize_system_prefix(void) {
    char *configured = load_system_prompt();
    if (!configured) return NULL;
    NSString *configured_ns = [NSString stringWithUTF8String:configured];
    if (!configured_ns) { free(configured); return NULL; }
    NSArray *messages = @[@{@"role": @"system", @"content": configured_ns}];
    PromptTokens *pt = tokenize_rendered_messages(messages, NO, YES);
    free(configured);
    return pt;
}

// Derive the expected cache key from the current source and system prompt.
// Disk header signatures are claims, not proof that the state fits this prefix.
static BOOL warm_source_prefix_key(const char *source_path,
                                   uint64_t *tool_sig, uint64_t *token_sig,
                                   int *token_count) {
    NSData *data = [NSData dataWithContentsOfFile:
        [NSString stringWithUTF8String:source_path]];
    id root = data ? [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL] : nil;
    NSDictionary *request = [root isKindOfClass:[NSArray class]]
        ? @{@"tools": root} : ([root isKindOfClass:[NSDictionary class]] ? root : nil);
    BOOL valid = YES;
    NSArray *tools = request ? parse_request_tools(request, &valid, NULL) : nil;
    id system = [root isKindOfClass:[NSDictionary class]] ? root[@"system_prompt"] : nil;
    if (!request || !valid ||
        ![request[@"tools"] isKindOfClass:[NSArray class]] ||
        (system && ![system isKindOfClass:[NSString class]])) return NO;
    if (!system) {
        char *configured = load_system_prompt();
        if (!configured) return NO;
        system = [NSString stringWithUTF8String:configured];
        free(configured);
    }
    if (!system) return NO;
    PromptTokens *pt = tokenize_rendered_messages_with_tools(
        @[@{@"role": @"system", @"content": system}], tools, NO, NO);
    if (!pt || pt->count <= 0 || pt->count > TOOL_PREFIX_CACHE_MAX_TOKENS) {
        if (pt) { free(pt->ids); free(pt); }
        return NO;
    }
    *tool_sig = tool_context_signature(tools, @"auto");
    *token_sig = prompt_tokens_signature(pt);
    *token_count = pt->count;
    free(pt->ids); free(pt);
    return YES;
}

static BOOL flash_profile_name_valid(NSString *name) {
    if (![name isKindOfClass:[NSString class]] || name.length == 0 || name.length > 64)
        return NO;
    for (NSUInteger i = 0; i < name.length; i++) {
        unichar c = [name characterAtIndex:i];
        if (!((c >= 'a' && c <= 'z') ||
              (c >= '0' && c <= '9') || c == '-' || c == '_')) return NO;
    }
    return YES;
}

static NSString *flash_profile_header(const char *request_bytes) {
    const char *end = strstr(request_bytes, "\r\n\r\n");
    if (!end) return nil;
    const char *line = strstr(request_bytes, "\r\n");
    while (line && line < end) {
        line += 2;
        const char *next = strstr(line, "\r\n");
        if (!next || next > end) break;
        static const char header[] = "X-Flash-Profile:";
        if ((size_t)(next - line) >= sizeof(header) - 1 &&
            strncasecmp(line, header, sizeof(header) - 1) == 0) {
            const char *value = line + sizeof(header) - 1;
            while (value < next && (*value == ' ' || *value == '\t')) value++;
            while (next > value && (next[-1] == ' ' || next[-1] == '\t')) next--;
            return [[NSString alloc] initWithBytes:value length:(size_t)(next - value)
                                          encoding:NSUTF8StringEncoding];
        }
        line = next;
    }
    return nil;
}

static NSString *flash_profile_request_name(NSDictionary *request,
                                             const char *request_bytes,
                                             NSString *default_name,
                                             BOOL *valid) {
    if (valid) *valid = YES;
    id field = request[@"flash_profile"];
    NSString *name = field ? ([field isKindOfClass:[NSString class]] ? field : nil)
                           : flash_profile_header(request_bytes);
    if (!field && !name) name = default_name;
    if ((field || name) && !flash_profile_name_valid(name)) {
        if (valid) *valid = NO;
        return nil;
    }
    return name;
}

static NSString *flash_profile_source_path(NSString *cache_dir, NSString *name) {
    return [cache_dir stringByAppendingPathComponent:
        [NSString stringWithFormat:@"flash-%@-warm.json", name]];
}

#define FLASH_PROFILE_SOURCE_LIMIT 128
#define FLASH_PROFILE_SOURCE_BUDGET_BYTES (UINT64_C(64) << 20)

static BOOL flash_profile_source_name(NSString *name) {
    if (![name hasPrefix:@"flash-"] || ![name hasSuffix:@"-warm.json"] ||
        name.length <= 16) return NO;
    NSString *profile = [name substringWithRange:NSMakeRange(6, name.length - 16)];
    return flash_profile_name_valid(profile);
}

static void flash_profile_cleanup_stale_temps(NSString *directory) {
    NSArray<NSString *> *names = [[NSFileManager defaultManager]
        contentsOfDirectoryAtPath:directory error:NULL];
    time_t now = time(NULL);
    for (NSString *name in names) {
        NSRange marker = [name rangeOfString:@"-warm.json.tmp."];
        if (marker.location == NSNotFound || NSMaxRange(marker) == name.length) continue;
        NSString *source_name = [name substringToIndex:NSMaxRange(marker) - 5];
        if (!flash_profile_source_name(source_name)) continue;
        NSString *path = [directory stringByAppendingPathComponent:name];
        struct stat st;
        if (lstat(path.fileSystemRepresentation, &st) != 0 ||
            !S_ISREG(st.st_mode) || st.st_mtimespec.tv_sec > now ||
            now - st.st_mtimespec.tv_sec < 3600) continue;
        if (unlink(path.fileSystemRepresentation) == 0)
            fprintf(stderr, "[flash-profile] removed stale source temp: %s\n",
                path.fileSystemRepresentation);
    }
}

static void flash_profile_prune_sources(NSString *directory,
                                        NSSet<NSString *> *protected_paths,
                                        NSUInteger max_count,
                                        uint64_t max_bytes) {
    NSArray<NSString *> *names = [[NSFileManager defaultManager]
        contentsOfDirectoryAtPath:directory error:NULL];
    NSMutableArray<NSDictionary *> *files = [NSMutableArray array];
    uint64_t total = 0;
    for (NSString *name in names) {
        if (!flash_profile_source_name(name)) continue;
        NSString *path = [directory stringByAppendingPathComponent:name];
        struct stat st;
        if (lstat(path.fileSystemRepresentation, &st) != 0 ||
            !S_ISREG(st.st_mode) || st.st_size < 0) continue;
        uint64_t bytes = (uint64_t)st.st_size;
        total = bytes > UINT64_MAX - total ? UINT64_MAX : total + bytes;
        [files addObject:@{ @"path": path, @"bytes": @(bytes),
            @"sec": @(st.st_mtimespec.tv_sec),
            @"nsec": @(st.st_mtimespec.tv_nsec) }];
    }
    [files sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
        NSComparisonResult order = [a[@"sec"] compare:b[@"sec"]];
        if (order == NSOrderedSame) order = [a[@"nsec"] compare:b[@"nsec"]];
        return order == NSOrderedSame ? [a[@"path"] compare:b[@"path"]] : order;
    }];
    NSUInteger count = files.count;
    BOOL removed = NO;
    for (NSDictionary *file in files) {
        if (count <= max_count && total <= max_bytes) break;
        NSString *path = file[@"path"];
        if ([protected_paths containsObject:path]) continue;
        struct stat st;
        if (lstat(path.fileSystemRepresentation, &st) != 0 ||
            !S_ISREG(st.st_mode) ||
            (uint64_t)st.st_size != [file[@"bytes"] unsignedLongLongValue]) continue;
        if (unlink(path.fileSystemRepresentation) == 0) {
            uint64_t bytes = [file[@"bytes"] unsignedLongLongValue];
            total = total >= bytes ? total - bytes : 0;
            count--;
            removed = YES;
            fprintf(stderr, "[flash-profile] removed old source for profile limit: %s\n",
                path.fileSystemRepresentation);
        }
    }
    if (removed) {
        int dirfd = open(directory.fileSystemRepresentation, O_RDONLY);
        if (dirfd >= 0) { fsync(dirfd); close(dirfd); }
    }
    if (count > max_count || total > max_bytes)
        fprintf(stderr, "[flash-profile] WARNING: protected sources exceed profile limit: %lu/%lu files, %llu/%llu bytes\n",
            (unsigned long)count, (unsigned long)max_count,
            (unsigned long long)total, (unsigned long long)max_bytes);
}

static NSString *flash_profile_state_path(NSString *cache_dir, NSString *name,
                                           uint64_t token_sig) {
    NSString *filename = [NSString stringWithFormat:@"flash-%@-%016llx.state",
        name, (unsigned long long)token_sig];
    return [[[cache_dir stringByDeletingLastPathComponent]
        stringByAppendingPathComponent:@"warm-state"] stringByAppendingPathComponent:filename];
}

static size_t flash_profile_checkpoint_bytes_at_path(NSString *path) {
    if (!path) return 0;
    int fd = open(path.fileSystemRepresentation, O_RDONLY | O_NOFOLLOW);
    if (fd < 0) return 0;
    WarmStateHeader head = {0};
    struct stat st;
    BOOL ok = fstat(fd, &st) == 0 && S_ISREG(st.st_mode) &&
        warm_read_all(fd, &head, sizeof(head), NULL) &&
        memcmp(head.magic, "FWSTATE1", 8) == 0 &&
        head.payload_bytes > 0 && head.payload_bytes <= WARM_STATE_MAX_BYTES;
    if (ok && head.version == WARM_STATE_ZSTD_VERSION) {
        WarmStateZstdStorage storage = {0};
        ok = head.header_bytes == sizeof(head) + sizeof(storage) &&
            warm_read_all(fd, &storage, sizeof(storage), NULL) &&
            storage.stored_bytes > 0 &&
            storage.stored_bytes <= ZSTD_compressBound((size_t)head.payload_bytes) &&
            storage.stored_bytes <= WARM_STATE_MAX_BYTES &&
            storage.stored_bytes <= UINT64_MAX - head.header_bytes &&
            st.st_size == (off_t)(head.header_bytes + storage.stored_bytes);
    } else if (ok) {
        ok = head.version == WARM_STATE_VERSION &&
            st.st_size == (off_t)(sizeof(head) + head.payload_bytes);
    }
    close(fd);
    return ok ? (size_t)head.payload_bytes : 0;
}

static size_t flash_profile_checkpoint_bytes(NSString *path) {
    NSString *current = warm_state_identity_path(path);
    if (g_warm_state_zstd_enabled) {
        size_t bytes = flash_profile_checkpoint_bytes_at_path(warm_state_zstd_path(current));
        if (bytes) return bytes;
    }
    size_t current_bytes = flash_profile_checkpoint_bytes_at_path(current);
    if (current_bytes) return current_bytes;
    if (!g_warm_state_zstd_enabled) {
        size_t compressed_bytes = flash_profile_checkpoint_bytes_at_path(warm_state_zstd_path(current));
        if (compressed_bytes) return compressed_bytes;
    }
    return flash_profile_checkpoint_bytes_at_path(path);
}

// A profile source is published only after its exact rendered prefix has been
// verified against the live request. Existing sources are immutable unless the
// operator explicitly selected recapture for this profile.
static BOOL flash_profile_write_source(NSString *path, NSString *system_prompt,
                                       NSArray *raw_tools, BOOL overwrite) {
    if (!path || !system_prompt || ![raw_tools isKindOfClass:[NSArray class]]) return NO;
    NSData *json = [NSJSONSerialization dataWithJSONObject:
        @{ @"system_prompt": system_prompt, @"tools": raw_tools }
        options:NSJSONWritingPrettyPrinted | NSJSONWritingSortedKeys error:NULL];
    if (!json) return NO;
    NSString *directory = [path stringByDeletingLastPathComponent];
    if (![[NSFileManager defaultManager] createDirectoryAtPath:directory
        withIntermediateDirectories:YES attributes:nil error:NULL]) return NO;
    NSString *pattern = [path stringByAppendingString:@".tmp.XXXXXX"];
    char *temporary = strdup(pattern.fileSystemRepresentation);
    if (!temporary) return NO;
    int fd = mkstemp(temporary);
    if (fd < 0) { free(temporary); return NO; }
    BOOL ok = warm_write_all(fd, json.bytes, json.length, NULL) && fsync(fd) == 0;
    if (close(fd) != 0) ok = NO;
    if (ok) {
        if (overwrite) ok = rename(temporary, path.fileSystemRepresentation) == 0;
        else ok = link(temporary, path.fileSystemRepresentation) == 0;
    }
    unlink(temporary);
    free(temporary);
    if (ok) {
        int dirfd = open(directory.fileSystemRepresentation, O_RDONLY);
        if (dirfd >= 0) { fsync(dirfd); close(dirfd); }
    }
    return ok;
}

static int flash_profile_self_test(const char *directory, const char *model_path) {
    if (!directory || !model_path) return 1;
    g_model_path_for_tokenizer = model_path;
    init_tokenizer();
    if (!g_tokenizer_loaded) return 1;
    NSString *cache_dir = [NSString stringWithUTF8String:directory];
    if (![[NSFileManager defaultManager] createDirectoryAtPath:cache_dir
        withIntermediateDirectories:YES attributes:nil error:NULL]) return 1;
    NSArray *raw_tools = @[@{ @"type": @"function", @"function": @{
        @"name": @"read", @"parameters": @{ @"type": @"object",
            @"properties": @{ @"path": @{ @"type": @"string" }},
            @"required": @[@"path"], @"additionalProperties": @NO }}}];
    BOOL valid = YES;
    NSArray *tools = parse_request_tools(@{ @"tools": raw_tools }, &valid, NULL);
    if (!valid) return 1;
    NSString *alpha = flash_profile_source_path(cache_dir, @"planner");
    NSString *beta = flash_profile_source_path(cache_dir, @"reviewer");
    NSString *system_a = @"You are the planner.";
    NSString *system_b = @"You are the updated planner.";
    NSString *system_c = @"You are the reviewer.";
    int failures = 0;
    BOOL passed = flash_profile_write_source(alpha, system_a, raw_tools, NO) &&
        flash_profile_write_source(beta, system_c, raw_tools, NO);
    NSData *alpha_original = [NSData dataWithContentsOfFile:alpha];
    PromptTokens *a = tokenize_rendered_messages_with_tools(
        @[@{ @"role": @"system", @"content": system_a }], tools, NO, NO);
    PromptTokens *b = tokenize_rendered_messages_with_tools(
        @[@{ @"role": @"system", @"content": system_b }], tools, NO, NO);
    PromptTokens *c = tokenize_rendered_messages_with_tools(
        @[@{ @"role": @"system", @"content": system_c }], tools, NO, NO);
    uint64_t stored_tool = 0, stored_token = 0;
    int stored_count = 0;
    passed = passed && a && b &&
        warm_source_prefix_key(alpha.fileSystemRepresentation,
            &stored_tool, &stored_token, &stored_count) &&
        stored_tool == tool_context_signature(tools, @"auto") &&
        stored_token == prompt_tokens_signature(a) && stored_count == a->count;
    printf("[profile-test] first capture and exact match: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    passed = a && b && prompt_tokens_signature(a) != prompt_tokens_signature(b) &&
        !flash_profile_write_source(alpha, system_b, raw_tools, NO) &&
        [[NSData dataWithContentsOfFile:alpha] isEqualToData:alpha_original];
    printf("[profile-test] mismatch does not overwrite: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    passed = flash_profile_write_source(alpha, system_b, raw_tools, YES) &&
        warm_source_prefix_key(alpha.fileSystemRepresentation,
            &stored_tool, &stored_token, &stored_count) && b &&
        stored_token == prompt_tokens_signature(b) &&
        ![[NSData dataWithContentsOfFile:alpha] isEqualToData:alpha_original];
    printf("[profile-test] explicit recapture: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    passed = c && [[NSFileManager defaultManager] fileExistsAtPath:beta] &&
        warm_source_prefix_key(beta.fileSystemRepresentation,
            &stored_tool, &stored_token, &stored_count) &&
        stored_token == prompt_tokens_signature(c) &&
        stored_token != prompt_tokens_signature(b) &&
        ![alpha isEqualToString:beta];
    printf("[profile-test] two profiles coexist: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    NSString *dsh_source = flash_profile_source_path(cache_dir, @"dsh-kevin");
    NSString *agent_source = flash_profile_source_path(cache_dir, @"agent-stack-foo");
    NSString *dsh_state = flash_profile_state_path(cache_dir, @"dsh-kevin", 1);
    NSString *agent_state = flash_profile_state_path(cache_dir, @"agent-stack-foo", 1);
    passed = [dsh_source.lastPathComponent isEqualToString:@"flash-dsh-kevin-warm.json"] &&
        [agent_source.lastPathComponent isEqualToString:@"flash-agent-stack-foo-warm.json"] &&
        [dsh_state.lastPathComponent isEqualToString:@"flash-dsh-kevin-0000000000000001.state"] &&
        [agent_state.lastPathComponent isEqualToString:@"flash-agent-stack-foo-0000000000000001.state"];
    printf("[profile-test] Flash paths do not collide with legacy paths: %s\n",
           passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    NSString *empty = flash_profile_source_path(cache_dir, @"empty");
    passed = flash_profile_write_source(empty, @"No tools are available.", @[], NO) &&
        warm_source_prefix_key(empty.fileSystemRepresentation,
            &stored_tool, &stored_token, &stored_count) && stored_count > 0;
    printf("[profile-test] empty-tool static prefix: %s\n", passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    BOOL selector_valid = YES;
    NSString *selected = flash_profile_request_name(@{ @"flash_profile": @"json" },
        "POST / HTTP/1.1\r\nX-Flash-Profile: header\r\n\r\n{}", @"default",
        &selector_valid);
    passed = selector_valid && [selected isEqualToString:@"json"] &&
        [flash_profile_request_name(@{},
            "POST / HTTP/1.1\r\nX-Flash-Profile: header\r\n\r\n{}",
            @"default", &selector_valid) isEqualToString:@"header"] &&
        [flash_profile_request_name(@{}, "POST / HTTP/1.1\r\n\r\n{}",
            @"default", &selector_valid) isEqualToString:@"default"];
    printf("[profile-test] JSON, header, and CLI default selection: %s\n",
        passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    BOOL rejected_uppercase = YES;
    flash_profile_request_name(@{ @"flash_profile": @"Foo" },
        "POST / HTTP/1.1\r\n\r\n{}", nil, &rejected_uppercase);
    passed = flash_profile_name_valid(@"foo") &&
        !flash_profile_name_valid(@"Foo") && !rejected_uppercase;
    printf("[profile-test] case-colliding names rejected: %s\n",
        passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    NSString *source_dir = [cache_dir stringByAppendingPathComponent:@"source-budget-fixture"];
    [[NSFileManager defaultManager] createDirectoryAtPath:source_dir
        withIntermediateDirectories:YES attributes:nil error:NULL];
    NSMutableArray<NSString *> *source_files = [NSMutableArray array];
    NSData *ten_source_bytes = [@"0123456789" dataUsingEncoding:NSUTF8StringEncoding];
    passed = YES;
    for (NSString *name in @[@"old", @"default", @"session", @"current"]) {
        NSString *path = flash_profile_source_path(source_dir, name);
        [source_files addObject:path];
        passed = passed && [ten_source_bytes writeToFile:path atomically:NO];
        struct timeval stamps[2] = {{(long)source_files.count, 0},
                                     {(long)source_files.count, 0}};
        if (utimes(path.fileSystemRepresentation, stamps) != 0) passed = NO;
    }
    NSString *stale_temp = [source_files[0] stringByAppendingString:@".tmp.old"];
    NSString *fresh_temp = [source_files[3] stringByAppendingString:@".tmp.new"];
    [ten_source_bytes writeToFile:stale_temp atomically:NO];
    [ten_source_bytes writeToFile:fresh_temp atomically:NO];
    struct timeval old_temp_time[2] = {{1, 0}, {1, 0}};
    if (utimes(stale_temp.fileSystemRepresentation, old_temp_time) != 0) passed = NO;
    flash_profile_cleanup_stale_temps(source_dir);
    NSSet *protected_sources = [NSSet setWithArray:@[
        source_files[1], source_files[2], source_files[3]]];
    flash_profile_prune_sources(source_dir, protected_sources, 3, 31);
    passed = passed && access(source_files[0].fileSystemRepresentation, F_OK) != 0 &&
        access(source_files[1].fileSystemRepresentation, F_OK) == 0 &&
        access(source_files[2].fileSystemRepresentation, F_OK) == 0 &&
        access(source_files[3].fileSystemRepresentation, F_OK) == 0 &&
        access(stale_temp.fileSystemRepresentation, F_OK) != 0 &&
        access(fresh_temp.fileSystemRepresentation, F_OK) == 0;
    printf("[profile-test] source limit and stale-temp protection: %s\n",
        passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    for (NSString *path in source_files) unlink(path.fileSystemRepresentation);
    unlink(stale_temp.fileSystemRepresentation);
    unlink(fresh_temp.fileSystemRepresentation);
    rmdir(source_dir.fileSystemRepresentation);
    NSString *budget_dir = [cache_dir stringByAppendingPathComponent:@"budget-fixture"];
    [[NSFileManager defaultManager] createDirectoryAtPath:budget_dir
        withIntermediateDirectories:YES attributes:nil error:NULL];
    NSMutableArray<NSString *> *budget_files = [NSMutableArray array];
    NSData *ten_bytes = [@"0123456789" dataUsingEncoding:NSUTF8StringEncoding];
    passed = YES;
    for (int i = 1; i <= 3; i++) {
        NSString *path = [budget_dir stringByAppendingPathComponent:
            [NSString stringWithFormat:@"flash-test%d-%016x.state", i, i]];
        [budget_files addObject:path];
        passed = passed && [ten_bytes writeToFile:path atomically:NO];
        struct timeval stamps[2] = {{i, 0}, {i, 0}};
        if (utimes(path.fileSystemRepresentation, stamps) != 0) passed = NO;
    }
    if (passed) warm_state_prune_to_budget(budget_dir, budget_files[2], 21);
    passed = passed && access(budget_files[0].fileSystemRepresentation, F_OK) != 0 &&
        access(budget_files[1].fileSystemRepresentation, F_OK) == 0 &&
        access(budget_files[2].fileSystemRepresentation, F_OK) == 0;
    printf("[profile-test] global checkpoint disk budget: %s\n",
        passed ? "PASS" : "FAIL");
    if (!passed) failures++;
    for (NSString *path in budget_files) unlink(path.fileSystemRepresentation);
    rmdir(budget_dir.fileSystemRepresentation);
    if (a) { free(a->ids); free(a); }
    if (b) { free(b->ids); free(b); }
    if (c) { free(c->ids); free(c); }
    printf("[profile-test] RESULT: %s\n", failures ? "FAIL" : "PASS");
    return failures ? 1 : 0;
}

// The main serve loop. Model state must already be initialized.
// Sync CPU linear attention state → GPU buffers
static void sync_cpu_to_gpu_delta_state_serve(void **layer_states) {
	if (!snapshot_uses_gpu_linear_state() || !layer_states) return;
	int li = 0;
	for (int i = 0; i < NUM_LAYERS; i++) {
		if ((i + 1) % FULL_ATTN_INTERVAL == 0) continue;
		if (!layer_states[i]) { li++; continue; }
		LinearAttnState *la = (LinearAttnState *)layer_states[i];
		if (li < g_cfg.num_linear_layers) {
			if (g_metal->buf_delta_state[li] && la->ssm_state)
				memcpy([g_metal->buf_delta_state[li] contents], la->ssm_state,
					   LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float));
			if (g_metal->buf_conv_state[li] && la->conv_state)
				memcpy([g_metal->buf_conv_state[li] contents], la->conv_state,
					   (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float));
		}
		li++;
	}
}

static void serve_loop(
	int port,
	WeightFile *wf, Vocabulary *vocab,
	void **layer_states, KVCache **kv_caches,
	void **layer_mmaps, int *layer_fds,
	float *hidden, float *logits,
	uint16_t *final_norm_w, int K,
    const char *warm_tools_path,
    const char *warm_profile,
    const char *default_flash_profile,
    const char *recapture_flash_profile,
    const char *weights_path, const char *manifest_path,
    const char *vocab_path)
{
    NSString *default_profile_name = default_flash_profile
        ? [NSString stringWithUTF8String:default_flash_profile] : nil;
    NSString *recapture_name = recapture_flash_profile
        ? [NSString stringWithUTF8String:recapture_flash_profile] : nil;
    BOOL recapture_pending = recapture_name != nil;
	// Ignore SIGPIPE (client disconnect mid-write)
	signal(SIGPIPE, SIG_IGN);

	int server_fd = socket(AF_INET, SOCK_STREAM, 0);
	if (server_fd < 0) { perror("socket"); return; }

	int opt = 1;
	setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

	struct sockaddr_in addr = {0};
	addr.sin_family = AF_INET;
	addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
	addr.sin_port = htons(port);

	if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
		perror("bind"); close(server_fd); return;
	}
	NSString *tool_set_cache_dir = project_tool_set_cache_directory();
	if (tool_set_cache_dir) {
        flash_profile_cleanup_stale_temps(tool_set_cache_dir);
        NSSet *protected_sources = default_profile_name
            ? [NSSet setWithObject:flash_profile_source_path(tool_set_cache_dir,
                default_profile_name)] : [NSSet set];
        flash_profile_prune_sources(tool_set_cache_dir, protected_sources,
            FLASH_PROFILE_SOURCE_LIMIT, FLASH_PROFILE_SOURCE_BUDGET_BYTES);
    }
	printf("[serve] Preparing on http://127.0.0.1:%d\n", port);
printf("[serve] Tool API revision 9.4 — bounded cache + malformed-tool recovery\n");
	printf("[serve] Endpoints: POST /v1/chat/completions, GET /v1/models, GET /health\n");
    printf("[serve] Malformed-tool handling: %s\n",
           g_malformed_tool_recovery_enabled
               ? "compatibility recovery enabled"
               : "provider error");
    printf("[serve] Tool ordering: %s; prefix cache: %d slots%s\n",
           g_sort_tools_alpha_enabled ? "alphabetical" : "client order",
           TOOL_PREFIX_CACHE_SLOTS,
           warm_tools_path && *warm_tools_path ? " (warm entry pinned)" : "");
    printf("[serve] Requested tool-set cache: %s\n",
           tool_set_cache_dir ? tool_set_cache_dir.fileSystemRepresentation
                              : "unavailable (executable is outside metal_infer)");
	fflush(stdout);

	static uint64_t req_counter = 0;

	// ---- System prompt cache: prefill system prompt once at startup ----
	// Tokenize the system prompt and run it through all transformer layers.
	// Save the resulting KV cache + linear attention state as a snapshot.
	// On each request, restore the snapshot instead of re-prefilling.
	fprintf(stderr, "[serve] Pre-caching system prompt...\n");
	PromptTokens *sys_pt = tokenize_system_prefix();
	int sys_pos = 0;
	if (!sys_pt || sys_pt->count <= 0) {
		fprintf(stderr,
			"[serve] ERROR: system-prompt tokenization returned no tokens; refusing to start server\n");
		if (sys_pt) {
			free(sys_pt->ids);
			free(sys_pt);
		}
		close(server_fd);
		return;
	}
	{
		if (!validate_prompt_tokens(sys_pt, 1, "server system prompt")) {
			free(sys_pt->ids);
			free(sys_pt);
			return;
		}
		if (!context_preflight("server system prompt", 0, sys_pt->count, 0)) {
			free(sys_pt->ids);
			free(sys_pt);
			return;
		}
		if (sys_pt->count > GPU_KV_SEQ) {
			fprintf(stderr,
					"[serve] System prompt is %d tokens; GPU KV mirror is capped at %d. "
					"Full attention will use the CPU path beyond the GPU window.\n",
					sys_pt->count, GPU_KV_SEQ);
		}
		// Pre-embed all system prompt tokens
		float *sys_embed_batch = try_alloc_embedding_batch(sys_pt->count, "system");
		if (sys_embed_batch) {
			for (int i = 0; i < sys_pt->count; i++) {
				embed_lookup(wf, sys_pt->ids[i], sys_embed_batch + (size_t)i * HIDDEN_DIM);
			}
		}
		// Intermediate system prompt tokens: discard last-layer expert output
		for (int i = 0; i < sys_pt->count - 1; i++) {
			cache_telemetry_note_token();
			if (sys_embed_batch) {
				memcpy(hidden, sys_embed_batch + (size_t)i * HIDDEN_DIM,
					   HIDDEN_DIM * sizeof(float));
			} else {
				embed_lookup(wf, sys_pt->ids[i], hidden);
			}
			g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
							(void **)layer_mmaps, layer_fds, sys_pos, K);
			if (g_forward_error) break;
			if (!discard_deferred_experts()) break;
			sys_pos++;
		}
		if (g_forward_error) {
			fprintf(stderr, "ERROR: system-prompt prefill aborted after forward failure\n");
			if (sys_embed_batch) free(sys_embed_batch);
			free(sys_pt->ids);
			free(sys_pt);
			return;
		}
		// Last system prompt token: full completion
		{
			cache_telemetry_note_token();
			if (sys_embed_batch) {
				memcpy(hidden, sys_embed_batch + (size_t)(sys_pt->count - 1) * HIDDEN_DIM,
					   HIDDEN_DIM * sizeof(float));
			} else {
				embed_lookup(wf, sys_pt->ids[sys_pt->count - 1], hidden);
			}
			g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
							(void **)layer_mmaps, layer_fds, sys_pos, K);
			if (g_forward_error) {
				fprintf(stderr, "ERROR: system-prompt final prefill token failed\n");
				if (sys_embed_batch) free(sys_embed_batch);
				free(sys_pt->ids);
				free(sys_pt);
				return;
			}
			if (!complete_deferred_experts()) {
				fprintf(stderr, "ERROR: system-prompt deferred Metal completion failed\n");
				if (sys_embed_batch) free(sys_embed_batch);
				free(sys_pt->ids);
				free(sys_pt);
				return;
			}
			sys_pos++;
		}
		if (sys_embed_batch) { free(sys_embed_batch); sys_embed_batch = NULL; }
		// Sync CPU state → GPU for delta-net
		sync_cpu_to_gpu_delta_state_serve(layer_states);
		fprintf(stderr, "[serve] System prompt cached: %d tokens prefilled\n", sys_pos);
	}
	if (sys_pt) {
		free(sys_pt->ids);
		free(sys_pt);
	}

	// Save snapshot of KV caches + linear attention state after system prompt
	// These are restored at the start of each request instead of resetting to zero
	typedef struct {
		float *k_snapshot;
		float *v_snapshot;
		int len;
	} KVSnapshot;
	KVSnapshot kv_snapshots[NUM_LAYERS];
	memset(kv_snapshots, 0, sizeof(kv_snapshots));

	// Linear attention snapshots
	float *la_conv_snapshots[NUM_LAYERS];
	float *la_ssm_snapshots[NUM_LAYERS];
	memset(la_conv_snapshots, 0, sizeof(la_conv_snapshots));
	memset(la_ssm_snapshots, 0, sizeof(la_ssm_snapshots));

	size_t kv_dim = NUM_KV_HEADS * HEAD_DIM;
	size_t conv_state_size = (CONV_KERNEL_SIZE - 1) * LINEAR_CONV_DIM * sizeof(float);
	size_t ssm_state_size = LINEAR_NUM_V_HEADS * LINEAR_VALUE_DIM * LINEAR_KEY_DIM * sizeof(float);

	int snapshot_alloc_failed = 0;
	for (int i = 0; i < NUM_LAYERS; i++) {
		if (kv_caches[i]) {
			size_t sz = (size_t)sys_pos * kv_dim * sizeof(float);
			if (sz > 0) {
				kv_snapshots[i].k_snapshot = malloc(sz);
				kv_snapshots[i].v_snapshot = malloc(sz);
				if (!kv_snapshots[i].k_snapshot || !kv_snapshots[i].v_snapshot) {
					fprintf(stderr, "[serve] ERROR: KV snapshot allocation failed at layer %d\n", i);
					snapshot_alloc_failed = 1;
					break;
				}
				memcpy(kv_snapshots[i].k_snapshot, kv_caches[i]->k_cache, sz);
				memcpy(kv_snapshots[i].v_snapshot, kv_caches[i]->v_cache, sz);
			}
			kv_snapshots[i].len = kv_caches[i]->len;
		}
		if (layer_states[i]) {
			LinearAttnState *s = (LinearAttnState *)layer_states[i];
			la_conv_snapshots[i] = malloc(conv_state_size);
			la_ssm_snapshots[i] = malloc(ssm_state_size);
			if (!la_conv_snapshots[i] || !la_ssm_snapshots[i]) {
				fprintf(stderr, "[serve] ERROR: linear-state snapshot allocation failed at layer %d\n", i);
				snapshot_alloc_failed = 1;
				break;
			}
			memcpy(la_conv_snapshots[i], s->conv_state, conv_state_size);
			memcpy(la_ssm_snapshots[i], s->ssm_state, ssm_state_size);
		}
	}
	if (snapshot_alloc_failed) {
		for (int i = 0; i < NUM_LAYERS; i++) {
			free(kv_snapshots[i].k_snapshot);
			free(kv_snapshots[i].v_snapshot);
			free(la_conv_snapshots[i]);
			free(la_ssm_snapshots[i]);
		}
		return;
	}
	// Also snapshot GPU delta-net state
	void *gpu_delta_snapshots[48];
	void *gpu_conv_snapshots[48];
	memset(gpu_delta_snapshots, 0, sizeof(gpu_delta_snapshots));
	memset(gpu_conv_snapshots, 0, sizeof(gpu_conv_snapshots));
	if (snapshot_uses_gpu_linear_state()) {
		for (int i = 0; i < g_cfg.num_linear_layers; i++) {
			if (g_metal->buf_delta_state[i]) {
				size_t sz = 64*128*128*sizeof(float);
				gpu_delta_snapshots[i] = malloc(sz);
				if (!gpu_delta_snapshots[i]) {
					fprintf(stderr, "[serve] ERROR: GPU delta-state snapshot allocation failed at layer %d\n", i);
					snapshot_alloc_failed = 1;
					break;
				}
				memcpy(gpu_delta_snapshots[i], [g_metal->buf_delta_state[i] contents], sz);
			}
			if (g_metal->buf_conv_state[i]) {
				size_t sz = 3*12288*sizeof(float);
				gpu_conv_snapshots[i] = malloc(sz);
				if (!gpu_conv_snapshots[i]) {
					fprintf(stderr, "[serve] ERROR: GPU conv-state snapshot allocation failed at layer %d\n", i);
					snapshot_alloc_failed = 1;
					break;
				}
				memcpy(gpu_conv_snapshots[i], [g_metal->buf_conv_state[i] contents], sz);
			}
		}
	}
	if (snapshot_alloc_failed) {
		for (int i = 0; i < NUM_LAYERS; i++) {
			free(kv_snapshots[i].k_snapshot);
			free(kv_snapshots[i].v_snapshot);
			free(la_conv_snapshots[i]);
			free(la_ssm_snapshots[i]);
		}
		for (int i = 0; i < 48; i++) {
			free(gpu_delta_snapshots[i]);
			free(gpu_conv_snapshots[i]);
		}
		return;
	}
	int sys_prompt_len = sys_pos;  // number of tokens in system prompt cache

    // ---- Tool/system prefix KV cache ----
    // Five exact-prefix slots. A --warm-tools entry is pinned in slot 0;
    // dynamic entries share a byte budget and use LRU replacement. Exact
    // matching uses both the canonical tool-context signature and the exact
    // rendered-prefix token signature/count.
    ToolPrefixCacheEntry tool_prefix_cache[TOOL_PREFIX_CACHE_SLOTS] = {0};
    uint64_t tool_prefix_cache_clock = 0;
    NSString *warm_state_path = nil;
    uint64_t warm_compatibility = 0, warm_source_hash = 0, warm_profile_hash = 0;
    BOOL warm_compatibility_valid = NO;
    BOOL warm_state_loaded = NO;
    if (warm_profile && *warm_profile && warm_tools_path && *warm_tools_path) {
        NSString *profile = [NSString stringWithUTF8String:warm_profile];
        warm_profile_hash = warm_hash_string(
            UINT64_C(14695981039346656037), warm_profile);
        NSString *project_dir = [project_tool_set_cache_directory()
            stringByDeletingLastPathComponent];
        if (project_dir)
            warm_state_cleanup_stale_temps(
                [project_dir stringByAppendingPathComponent:@"warm-state"]);
        NSString *stem = [profile hasPrefix:@"flash/"]
            ? [@"flash-" stringByAppendingString:[profile substringFromIndex:6]]
            : [profile hasPrefix:@"dsh/"]
                ? [@"flash-dsh-" stringByAppendingString:[profile substringFromIndex:4]]
                : [profile stringByReplacingOccurrencesOfString:@"/" withString:@"-"];
        warm_compatibility_valid = project_dir &&
            warm_state_compatibility(weights_path, manifest_path, vocab_path,
                                     wf, layer_fds, K, &warm_compatibility);
        BOOL identity_valid = warm_compatibility_valid;
        ToolPrefixCacheEntry expected_prefix = {0};
        identity_valid = identity_valid && warm_source_prefix_key(
            warm_tools_path, &expected_prefix.tool_sig,
            &expected_prefix.token_sig, &expected_prefix.token_count);
        if (identity_valid) {
            // The source identity is the exact rendered token sequence. JSON
            // whitespace or key order changes alone must not force a warmup.
            warm_source_hash = expected_prefix.token_sig;
            NSString *name = [NSString stringWithFormat:@"%@-%016llx.state",
                stem, (unsigned long long)warm_source_hash];
            warm_state_path = [[project_dir stringByAppendingPathComponent:@"warm-state"]
                stringByAppendingPathComponent:name];
            fprintf(stderr, "[warm-state] profile=%s\n[warm-state] checking %s\n",
                    warm_profile, warm_state_path.fileSystemRepresentation);
            struct rusage warm_rss_before = {0}, warm_rss_after = {0};
            int repair_compressed = 0;
            getrusage(RUSAGE_SELF, &warm_rss_before);
            warm_state_loaded = warm_state_load_selected(warm_state_path,
                &tool_prefix_cache[0], kv_caches, layer_states,
                warm_compatibility, warm_source_hash, warm_profile_hash,
                &expected_prefix, &repair_compressed);
            if (!warm_state_loaded)
                warm_state_loaded = warm_state_migrate_legacy(warm_state_path,
                    &tool_prefix_cache[0], kv_caches, layer_states,
                    weights_path, manifest_path, vocab_path, wf, layer_fds, K,
                    warm_source_hash, warm_profile_hash, &expected_prefix);
            if (warm_state_loaded) {
                if (getenv("FLASH_WARM_STATE_RESTORE_PROBE")) {
                    double restore_started = now_ms();
                    int restored = serve_state_snapshot_restore(
                        &tool_prefix_cache[0].snapshot, kv_caches, layer_states);
                    getrusage(RUSAGE_SELF, &warm_rss_after);
                    fprintf(stderr,
                        "[warm-state] startup restore probe: result=%s cpu_metal_copy=%.0fms peak_rss_before=%lld peak_rss_after=%lld\n",
                        restored ? "PASS" : "FAIL", now_ms() - restore_started,
                        (long long)warm_rss_before.ru_maxrss,
                        (long long)warm_rss_after.ru_maxrss);
                    if (!restored) return;
                }
                tool_prefix_cache[0].last_used = ++tool_prefix_cache_clock;
                if ((repair_compressed || !warm_state_selected_exists(warm_state_path)) &&
                    !warm_state_save_selected(warm_state_path, &tool_prefix_cache[0],
                        kv_caches, layer_states, warm_compatibility,
                        warm_source_hash, warm_profile_hash))
                    fprintf(stderr, "[warm-state] WARNING: selected checkpoint save failed\n");
            }
        } else {
            fprintf(stderr, "[warm-state] identity unavailable; rebuilding without persistence\n");
        }
    }

    // Optional startup warm-up. Accept either:
    //   [ {OpenAI tool}, ... ]
    // or
    //   { "tools": [ ... ] }
    if (warm_tools_path && *warm_tools_path && !warm_state_loaded) {
        NSString *warm_path = [NSString stringWithUTF8String:warm_tools_path];
        NSData *warm_data = warm_path ? [NSData dataWithContentsOfFile:warm_path] : nil;
        if (!warm_data) {
            fprintf(stderr, "[serve] ERROR: cannot read --warm-tools file: %s\n", warm_tools_path);
            return;
        }

        NSError *warm_json_error = nil;
        id warm_root = [NSJSONSerialization JSONObjectWithData:warm_data
                                                       options:0
                                                         error:&warm_json_error];
        NSDictionary *warm_request = nil;
        if ([warm_root isKindOfClass:[NSArray class]]) {
            warm_request = @{@"tools": warm_root};
        } else if ([warm_root isKindOfClass:[NSDictionary class]]) {
            warm_request = warm_root;
        }

        BOOL warm_valid = YES;
        NSString *warm_error = nil;
        NSArray<NSDictionary *> *warm_tools =
            warm_request ? parse_request_tools(warm_request, &warm_valid, &warm_error) : nil;
        if (!warm_request || !warm_valid ||
            ![warm_request[@"tools"] isKindOfClass:[NSArray class]]) {
            fprintf(stderr, "[serve] ERROR: invalid --warm-tools JSON%s%s\n",
                    warm_error ? ": " : "",
                    warm_error ? warm_error.UTF8String : "");
            return;
        }

        id warm_system = [warm_root isKindOfClass:[NSDictionary class]]
            ? ((NSDictionary *)warm_root)[@"system_prompt"] : nil;
        if (warm_system && ![warm_system isKindOfClass:[NSString class]]) {
            fprintf(stderr, "[serve] ERROR: --warm-tools system_prompt must be a string\n");
            return;
        }
        NSString *configured_ns = (NSString *)warm_system;
        if (!configured_ns) {
            char *configured = load_system_prompt();
            if (!configured) {
                fprintf(stderr, "[serve] ERROR: cannot load system prompt for --warm-tools\n");
                return;
            }
            configured_ns = [NSString stringWithUTF8String:configured];
            free(configured);
        }
        if (!configured_ns) {
            fprintf(stderr, "[serve] ERROR: invalid configured system prompt for --warm-tools\n");
            return;
        }

        NSArray *warm_messages = @[@{@"role": @"system", @"content": configured_ns}];
        PromptTokens *warm_pt =
            tokenize_rendered_messages_with_tools(warm_messages, warm_tools, NO, NO);
        if (!warm_pt || warm_pt->count <= 0 ||
            !validate_prompt_tokens(warm_pt, 1, "warm tools prefix") ||
            !context_preflight("warm tools prefix", 0, warm_pt ? warm_pt->count : 0, 0)) {
            fprintf(stderr, "[serve] ERROR: failed to tokenize/validate --warm-tools prefix\n");
            if (warm_pt) { free(warm_pt->ids); free(warm_pt); }
            return;
        }
        if (warm_pt->count > TOOL_PREFIX_CACHE_MAX_TOKENS) {
            fprintf(stderr,
                    "[serve] ERROR: --warm-tools prefix is too large (%d > %d tokens)\n",
                    warm_pt->count, TOOL_PREFIX_CACHE_MAX_TOKENS);
            free(warm_pt->ids);
            free(warm_pt);
            return;
        }

        fprintf(stderr, "[serve] Warming tool prefix: %d tokens from %s\n",
                warm_pt->count, warm_tools_path);
        double warm_start_ms = now_ms();

        // Tool-enabled Qwen system blocks start at position zero and replace
        // the ordinary cached system prompt, so warm from a zero state.
        for (int i = 0; i < NUM_LAYERS; i++) {
            if (kv_caches[i]) kv_caches[i]->len = 0;
            if (layer_states[i]) {
                LinearAttnState *la = (LinearAttnState *)layer_states[i];
                memset(la->conv_state, 0, conv_state_size);
                memset(la->ssm_state, 0, ssm_state_size);
            }
        }
        reset_delta_net_state();

        int warm_pos = 0;
        float *warm_embed_batch = try_alloc_embedding_batch(warm_pt->count, "warm-tools");
        if (warm_embed_batch) {
            for (int i = 0; i < warm_pt->count; i++) {
                embed_lookup(wf, warm_pt->ids[i],
                             warm_embed_batch + (size_t)i * HIDDEN_DIM);
            }
        }

        g_forward_error = 0;
        for (int i = 0; i < warm_pt->count; i++) {
            cache_telemetry_note_token();
            if (warm_embed_batch) {
                memcpy(hidden, warm_embed_batch + (size_t)i * HIDDEN_DIM,
                       HIDDEN_DIM * sizeof(float));
            } else {
                embed_lookup(wf, warm_pt->ids[i], hidden);
            }
            g_forward_error = !run_all_layers_checked(
                wf, hidden, kv_caches, layer_states,
                (void **)layer_mmaps, layer_fds, warm_pos, K);
            if (g_forward_error) break;
            if (i + 1 == warm_pt->count) {
                if (!complete_deferred_experts()) break;
            } else {
                if (!discard_deferred_experts()) break;
            }
            warm_pos++;
            if ((warm_pos % 128) == 0 || warm_pos == warm_pt->count) {
                double elapsed_ms = now_ms() - warm_start_ms;
                fprintf(stderr,
                    "[warm] %d/%d (%.1f%%) elapsed=%.1fs rate=%.1f tok/s\n",
                    warm_pos, warm_pt->count,
                    100.0 * warm_pos / warm_pt->count,
                    elapsed_ms / 1000.0,
                    elapsed_ms > 0 ? warm_pos * 1000.0 / elapsed_ms : 0.0);
            }
        }
        if (warm_embed_batch) free(warm_embed_batch);

        if (g_forward_error) {
            fprintf(stderr, "[serve] ERROR: --warm-tools prefix prefill failed\n");
            free(warm_pt->ids); free(warm_pt);
            return;
        }

        // Snapshot the exact CPU + GPU recurrent state produced by the
        // tool-prefix prefill. Do not resynchronize one side over the other:
        // a cache restore should reproduce the normal live prefix boundary.
        ToolPrefixCacheEntry *warm_entry = &tool_prefix_cache[0];
        double warm_snapshot_ms = now_ms();
        if (!serve_state_snapshot_capture(&warm_entry->snapshot,
                                          kv_caches, layer_states, warm_pos)) {
            free(warm_pt->ids); free(warm_pt);
            return;
        }
        warm_entry->tool_sig = tool_context_signature(warm_tools, @"auto");
        warm_entry->token_sig = prompt_tokens_signature(warm_pt);
        warm_entry->token_count = warm_pt->count;
        warm_entry->last_used = ++tool_prefix_cache_clock;
        warm_entry->pinned = 1;

        fprintf(stderr, "[warm] snapshot=%.0fms total=%.1fs\n",
                now_ms() - warm_snapshot_ms,
                (now_ms() - warm_start_ms) / 1000.0);

        fprintf(stderr,
                "[serve] Tool prefix warmed/cached: slot=0 pinned tokens=%d sig=%016llx\n",
                warm_entry->token_count,
                (unsigned long long)warm_entry->tool_sig);
        if (warm_state_path &&
            !warm_state_save_selected(warm_state_path, warm_entry, kv_caches,
                             layer_states, warm_compatibility,
                             warm_source_hash, warm_profile_hash))
            fprintf(stderr, "[warm-state] WARNING: warm state remains available in memory; persistence failed\n");

        free(warm_pt->ids);
        free(warm_pt);

        // Restore the ordinary system snapshot so startup warming does not
        // itself become a live conversation/session.
        for (int i = 0; i < NUM_LAYERS; i++) {
            if (kv_caches[i] && kv_snapshots[i].k_snapshot) {
                size_t sz = (size_t)sys_prompt_len * kv_dim * sizeof(float);
                memcpy(kv_caches[i]->k_cache, kv_snapshots[i].k_snapshot, sz);
                memcpy(kv_caches[i]->v_cache, kv_snapshots[i].v_snapshot, sz);
                kv_caches[i]->len = kv_snapshots[i].len;
                if (g_metal) {
                    int fa_idx = (i + 1) / FULL_ATTN_INTERVAL - 1;
                    if (fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers) {
                        size_t gpu_tokens = (size_t)sys_prompt_len;
                        if (gpu_tokens > GPU_KV_SEQ) gpu_tokens = GPU_KV_SEQ;
                        size_t gpu_sz = gpu_tokens * kv_dim * sizeof(float);
                        memcpy([g_metal->buf_kv_k[fa_idx] contents],
                               kv_snapshots[i].k_snapshot, gpu_sz);
                        memcpy([g_metal->buf_kv_v[fa_idx] contents],
                               kv_snapshots[i].v_snapshot, gpu_sz);
                    }
                }
            }
            if (layer_states[i] && la_conv_snapshots[i] && la_ssm_snapshots[i]) {
                LinearAttnState *la = (LinearAttnState *)layer_states[i];
                memcpy(la->conv_state, la_conv_snapshots[i], conv_state_size);
                memcpy(la->ssm_state, la_ssm_snapshots[i], ssm_state_size);
            }
        }
        if (snapshot_uses_gpu_linear_state()) {
            for (int i = 0; i < g_cfg.num_linear_layers; i++) {
                if (gpu_delta_snapshots[i] && g_metal->buf_delta_state[i])
                    memcpy([g_metal->buf_delta_state[i] contents],
                           gpu_delta_snapshots[i], 64 * 128 * 128 * sizeof(float));
                if (gpu_conv_snapshots[i] && g_metal->buf_conv_state[i])
                    memcpy([g_metal->buf_conv_state[i] contents],
                           gpu_conv_snapshots[i], 3 * 12288 * sizeof(float));
            }
        }
    }

	// ---- Session state: track one active conversation session ----
	// The KV caches + linear attention state ARE the session.
	// We just track whether to restore from snapshot (new session) or continue (same session).
	char active_session_id[64] = {0};
    NSString *active_session_profile = nil;
    uint64_t active_session_tool_sig = 0;
    int active_session_tool_sig_valid = 0;
    NSMutableArray<NSString *> *active_session_pending_tool_ids = [NSMutableArray array];
	int session_pos = 0;  // RoPE position after last generation for the active session
	int session_ended_with_eos = 0;
	if (listen(server_fd, 8) < 0) {
		perror("listen"); close(server_fd); return;
	}
	fprintf(stderr, "[serve] Listening on http://127.0.0.1:%d\n[serve] Ready\n", port);

	for (;;) {
		struct sockaddr_in client_addr;
		socklen_t client_len = sizeof(client_addr);
		int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
		if (client_fd < 0) { perror("accept"); continue; }

		struct timeval recv_timeout = { .tv_sec = 30, .tv_usec = 0 };
		struct timeval send_timeout = { .tv_sec = 30, .tv_usec = 0 };
		setsockopt(client_fd, SOL_SOCKET, SO_RCVTIMEO,
				   &recv_timeout, sizeof(recv_timeout));
		setsockopt(client_fd, SOL_SOCKET, SO_SNDTIMEO,
				   &send_timeout, sizeof(send_timeout));
		double request_deadline_ms = now_ms() + 30000.0;

		// Read HTTP request
		char *reqbuf = malloc(1024 * 1024); // 1MB max request
		if (!reqbuf) {
			fprintf(stderr, "[serve] ERROR: unable to allocate 1MB request buffer\n");
			close(client_fd);
			continue;
		}
		int reqlen = read_http_request(client_fd, reqbuf, 1024 * 1024, request_deadline_ms);
		if (reqlen == -2) {
			http_write_str(client_fd,
				"HTTP/1.1 400 Bad Request\r\n"
				"Content-Type: application/json\r\n"
				"Connection: close\r\n\r\n"
				"{\"error\":\"malformed Content-Length/request headers\"}\n");
			free(reqbuf); close(client_fd); continue;
		}
		if (reqlen == -3) {
			http_write_str(client_fd,
				"HTTP/1.1 413 Payload Too Large\r\n"
				"Content-Type: application/json\r\n"
				"Connection: close\r\n\r\n"
				"{\"error\":\"request exceeds 1 MiB limit\"}\n");
			free(reqbuf); close(client_fd); continue;
		}
		if (reqlen == -4) {
			http_write_str(client_fd,
				"HTTP/1.1 408 Request Timeout\r\n"
				"Content-Type: application/json\r\n"
				"Connection: close\r\n\r\n"
				"{\"error\":\"request deadline exceeded\"}\n");
			free(reqbuf); close(client_fd); continue;
		}
		if (reqlen <= 0) { free(reqbuf); close(client_fd); continue; }

		// Parse method and path from first line
		char method[16] = {0}, path[256] = {0};
		sscanf(reqbuf, "%15s %255s", method, path);

		// Handle CORS preflight
		if (strcmp(method, "OPTIONS") == 0) {
			http_write_str(client_fd, CORS_RESPONSE);
			free(reqbuf); close(client_fd);
			continue;
		}

		// GET /health
		if (strcmp(method, "GET") == 0 && strcmp(path, "/health") == 0) {
			const char *resp =
				"HTTP/1.1 200 OK\r\n"
				"Content-Type: application/json\r\n"
				"Access-Control-Allow-Origin: *\r\n"
				"Connection: close\r\n"
				"\r\n"
				"{\"status\":\"ok\",\"model\":\"qwen3.5\"}\n";
			http_write_str(client_fd, resp);
			free(reqbuf); close(client_fd);
			continue;
		}

		// GET /v1/models
		if (strcmp(method, "GET") == 0 && strcmp(path, "/v1/models") == 0) {
			const char *resp =
				"HTTP/1.1 200 OK\r\n"
				"Content-Type: application/json\r\n"
				"Access-Control-Allow-Origin: *\r\n"
				"Connection: close\r\n"
				"\r\n"
				"{\"object\":\"list\",\"data\":[{\"id\":\"qwen3.5\","
				"\"object\":\"model\",\"owned_by\":\"local\"}]}\n";
			http_write_str(client_fd, resp);
			free(reqbuf); close(client_fd);
			continue;
		}

		// POST /v1/chat/completions
		if (strcmp(method, "POST") == 0 && strcmp(path, "/v1/chat/completions") == 0) {
			// Find body (after \r\n\r\n)
			char *body = strstr(reqbuf, "\r\n\r\n");
			if (!body) {
				http_write_str(client_fd,
					"HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n"
					"{\"error\":\"no body\"}\n");
				free(reqbuf); close(client_fd); continue;
			}
			body += 4;

            NSData *body_data = [NSData dataWithBytes:body length:strlen(body)];
            NSDictionary *request = [NSJSONSerialization JSONObjectWithData:body_data options:0 error:NULL];
            NSArray<NSDictionary *> *messages = [request isKindOfClass:[NSDictionary class]] ? parse_chat_messages(request) : nil;
            NSString *last_role = [messages.lastObject[@"role"] isKindOfClass:[NSString class]]
                ? messages.lastObject[@"role"] : nil;
            if (!messages || !([last_role isEqualToString:@"user"] || [last_role isEqualToString:@"tool"])) {
                http_write_str(client_fd, "HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n{\"error\":\"invalid messages\"}\n");
                free(reqbuf); close(client_fd); continue;
            }
            BOOL profile_name_valid = YES;
            BOOL explicit_profile_selector = request[@"flash_profile"] != nil ||
                flash_profile_header(reqbuf) != nil;
            NSString *request_profile_name = flash_profile_request_name(
                request, reqbuf, default_profile_name, &profile_name_valid);
            if (!profile_name_valid) {
                http_write_str(client_fd,
                    "HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\n"
                    "Connection: close\r\n\r\n{\"error\":\"flash_profile must use 1..64 lowercase ASCII letters, digits, '-' or '_'\"}\n");
                free(reqbuf); close(client_fd); continue;
            }

            BOOL tools_valid = YES;
            NSString *tools_error = nil;
            NSArray<NSDictionary *> *request_tools =
                parse_request_tools(request, &tools_valid, &tools_error);
            if (!tools_valid) {
                if ([tools_error isEqualToString:@"strict tool schemas not yet supported"]) {
                    http_write_str(client_fd,
                        "HTTP/1.1 400 Bad Request\r\n"
                        "Content-Type: application/json\r\n"
                        "Connection: close\r\n\r\n"
                        "{\"error\":\"strict tool schemas not yet supported\"}\n");
                } else {
                    http_write_str(client_fd,
                        "HTTP/1.1 400 Bad Request\r\n"
                        "Content-Type: application/json\r\n"
                        "Connection: close\r\n\r\n"
                        "{\"error\":\"invalid tools\"}\n");
                }
                free(reqbuf); close(client_fd); continue;
            }
            NSString *effective_tool_mode = @"auto";
            id tool_choice = request[@"tool_choice"];
            if (tool_choice && tool_choice != [NSNull null]) {
                if (![tool_choice isKindOfClass:[NSString class]]) {
                    http_write_str(client_fd, "HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n{\"error\":\"unsupported tool_choice; only auto and none are supported\"}\n");
                    free(reqbuf); close(client_fd); continue;
                }
                NSString *choice = (NSString *)tool_choice;
                if ([choice isEqualToString:@"none"]) {
                    effective_tool_mode = @"none";
                    request_tools = nil;
                } else if (![choice isEqualToString:@"auto"]) {
                    http_write_str(client_fd, "HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n{\"error\":\"unsupported tool_choice; required and forced-function modes are not implemented\"}\n");
                    free(reqbuf); close(client_fd); continue;
                }
            }
            id parallel_value = request[@"parallel_tool_calls"];
            if (parallel_value && parallel_value != [NSNull null]) {
                if (![parallel_value isKindOfClass:[NSNumber class]] || ![(NSNumber *)parallel_value boolValue]) {
                    http_write_str(client_fd, "HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n{\"error\":\"parallel_tool_calls:false is not supported\"}\n");
                    free(reqbuf); close(client_fd); continue;
                }
            }
            uint64_t request_tool_sig = tool_context_signature(request_tools,
                request_tools.count ? effective_tool_mode : @"auto");

            NSNumber *stream_value = request[@"stream"];
            BOOL stream_response = [stream_value isKindOfClass:[NSNumber class]] ? stream_value.boolValue : NO;
            BOOL include_stream_usage = stream_usage_requested(request);
            NSNumber *requested_max = request[@"max_completion_tokens"] ?: request[@"max_tokens"];
            int max_gen = [requested_max isKindOfClass:[NSNumber class]] ? requested_max.intValue : 8192;
            if (max_gen < 1) max_gen = 1;
            else if (max_gen > 32768) max_gen = 32768;

            // Respect an explicit reasoning budget supplied by OpenAI-compatible
            // clients before falling back to Flash's automatic max_tokens policy.
            // dsh/pi-ai uses thinking_token_budget for self-hosted Chat
            // Completions gateways; reasoning_budget_tokens is accepted as an
            // alias for compatibility with the existing Flash vision endpoint.
            id requested_budget_value = request[@"thinking_token_budget"];
            if (requested_budget_value == nil || requested_budget_value == [NSNull null])
                requested_budget_value = request[@"reasoning_budget_tokens"];
            NSString *requested_reasoning_effort =
                [request[@"reasoning_effort"] isKindOfClass:[NSString class]]
                    ? request[@"reasoning_effort"] : nil;
            BOOL request_think_budget_explicit = NO;
            int request_think_budget = effective_think_budget(max_gen);
            if ([requested_budget_value isKindOfClass:[NSNumber class]]) {
                long long explicit_budget = [(NSNumber *)requested_budget_value longLongValue];
                if (explicit_budget < 0) explicit_budget = 0;
                if (explicit_budget > max_gen) explicit_budget = max_gen;
                request_think_budget = (int)explicit_budget;
                request_think_budget_explicit = YES;
            }
            if ([requested_reasoning_effort isEqualToString:@"off"]) {
                request_think_budget = -1;
                request_think_budget_explicit = YES;
            }
            BOOL request_enable_thinking = request_think_budget >= 0;

            NSString *debug_max_completion =
                request[@"max_completion_tokens"] ? [request[@"max_completion_tokens"] description] : @"<absent>";
            NSString *debug_max_tokens =
                request[@"max_tokens"] ? [request[@"max_tokens"] description] : @"<absent>";
            NSString *debug_thinking_budget =
                request[@"thinking_token_budget"] ? [request[@"thinking_token_budget"] description] : @"<absent>";
            NSString *debug_reasoning_budget =
                request[@"reasoning_budget_tokens"] ? [request[@"reasoning_budget_tokens"] description] : @"<absent>";
            NSString *debug_reasoning_effort =
                request[@"reasoning_effort"] ? [request[@"reasoning_effort"] description] : @"<absent>";
            fprintf(stderr,
                "[request-debug] max_completion_tokens=%s max_tokens=%s "
                "thinking_token_budget=%s reasoning_budget_tokens=%s reasoning_effort=%s "
                "resolved_max_gen=%d resolved_think_budget=%d explicit=%s\n",
                debug_max_completion.UTF8String, debug_max_tokens.UTF8String,
                debug_thinking_budget.UTF8String, debug_reasoning_budget.UTF8String,
                debug_reasoning_effort.UTF8String, max_gen, request_think_budget,
                request_think_budget_explicit ? "yes" : "no");
            char req_session_id[64] = {0};
            BOOL has_session_bool = NO;
            NSString *session_error = nil;
            if (!parse_request_session_id(request, req_session_id,
                                          sizeof(req_session_id),
                                          &has_session_bool, &session_error)) {
                NSString *body = [NSString stringWithFormat:
                    @"{\"error\":\"%@\"}\n",
                    session_error ?: @"invalid session_id"];
                NSString *response = [NSString stringWithFormat:
                    @"HTTP/1.1 400 Bad Request\r\n"
                     "Content-Type: application/json\r\n"
                     "Connection: close\r\n\r\n%@",
                    body];
                http_write_str(client_fd, response.UTF8String);
                free(reqbuf); close(client_fd); continue;
            }
            int has_session = has_session_bool ? 1 : 0;
            // Cached continuation is valid only when the exact effective tool set
            // matches the one embedded in the resident KV state. A continuation may
            // be one ordinary turn, or a batch of consecutive role:"tool" results
            // corresponding exactly (and in order) to the pending tool calls.
            int same_session = has_session && active_session_id[0] &&
                strcmp(req_session_id, active_session_id) == 0;
            if (same_session && !explicit_profile_selector)
                request_profile_name = active_session_profile;
            if (same_session && !(active_session_profile == request_profile_name ||
                    [active_session_profile isEqualToString:request_profile_name])) {
                http_write_str(client_fd,
                    "HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\n"
                    "Connection: close\r\n\r\n{\"error\":\"session profile changed; resend full message history\"}\n");
                free(reqbuf); close(client_fd); continue;
            }
            int tool_context_matches = active_session_tool_sig_valid &&
                request_tool_sig == active_session_tool_sig;

            BOOL all_tool_messages = messages.count > 0;
            for (NSDictionary *m in messages) {
                if (![m[@"role"] isEqualToString:@"tool"]) {
                    all_tool_messages = NO;
                    break;
                }
            }

            BOOL pending_tool_batch_matches = NO;
            if (all_tool_messages &&
                active_session_pending_tool_ids.count == messages.count &&
                messages.count > 0) {
                pending_tool_batch_matches = YES;
                for (NSUInteger ti = 0; ti < messages.count; ti++) {
                    NSString *got_id = [messages[ti][@"tool_call_id"] isKindOfClass:[NSString class]]
                        ? messages[ti][@"tool_call_id"] : nil;
                    if (!got_id ||
                        ![got_id isEqualToString:active_session_pending_tool_ids[ti]]) {
                        pending_tool_batch_matches = NO;
                        break;
                    }
                }
            }

            BOOL single_ordinary_turn = messages.count == 1 && !all_tool_messages &&
                active_session_pending_tool_ids.count == 0;
            BOOL continuation_shape = single_ordinary_turn || pending_tool_batch_matches;

            if (same_session && messages.count == 1 &&
                active_session_pending_tool_ids.count > 0 && !all_tool_messages) {
                http_write_str(client_fd,
                    "HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n"
                    "{\"error\":\"pending tool calls must be resolved or resend full history\"}\n");
                free(reqbuf); close(client_fd); continue;
            }

            if (same_session && (messages.count == 1 || all_tool_messages) &&
                !tool_context_matches) {
                active_session_id[0] = '\0';
                active_session_tool_sig = 0;
                active_session_tool_sig_valid = 0;
                [active_session_pending_tool_ids removeAllObjects];
                session_pos = 0;
                session_ended_with_eos = 0;
                http_write_str(client_fd,
                    "HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n"
                    "{\"error\":\"session tool context changed; resend full message history\"}\n");
                free(reqbuf); close(client_fd); continue;
            }

            if (same_session && all_tool_messages && !pending_tool_batch_matches) {
                http_write_str(client_fd,
                    "HTTP/1.1 400 Bad Request\r\nContent-Type: application/json\r\nConnection: close\r\n\r\n"
                    "{\"error\":\"tool results do not match pending session tool calls\"}\n");
                free(reqbuf); close(client_fd); continue;
            }

            int is_continuation = same_session && tool_context_matches && continuation_shape;

            if (!is_continuation) {
                NSString *history_error = nil;
                if (!validate_chat_tool_history(messages, &history_error)) {
                    NSString *body = [NSString stringWithFormat:
                        @"{\"error\":\"%@\"}\n",
                        history_error ?: @"invalid tool message history"];
                    NSString *response = [NSString stringWithFormat:
                        @"HTTP/1.1 400 Bad Request\r\n"
                         "Content-Type: application/json\r\n"
                         "Connection: close\r\n\r\n%@",
                        body];
                    http_write_str(client_fd, response.UTF8String);
                    free(reqbuf); close(client_fd); continue;
                }
            }

            BOOL explicit_system = [messages[0][@"role"] isEqualToString:@"system"];
            BOOL has_tools = request_tools.count > 0;

            // A new tool-enabled conversation must render the tools system block from
            // position zero. If the caller supplied no system message, fold the configured
            // Flash-MoE system prompt into that same Qwen system block.
            NSArray<NSDictionary *> *render_messages = messages;
            if (!is_continuation && (has_tools || request_profile_name) && !explicit_system) {
                char *configured = load_system_prompt();
                if (!configured) {
                    http_write_str(client_fd, "HTTP/1.1 500 Internal Server Error\r\nConnection: close\r\n\r\n{\"error\":\"system prompt load failed\"}\n");
                    free(reqbuf); close(client_fd); continue;
                }
                NSString *configured_ns = [NSString stringWithUTF8String:configured];
                free(configured);
                if (!configured_ns) {
                    http_write_str(client_fd, "HTTP/1.1 500 Internal Server Error\r\nConnection: close\r\n\r\n{\"error\":\"invalid system prompt\"}\n");
                    free(reqbuf); close(client_fd); continue;
                }
                NSMutableArray *with_system = [NSMutableArray arrayWithObject:
                    @{@"role": @"system", @"content": configured_ns}];
                [with_system addObjectsFromArray:messages];
                render_messages = with_system;
                explicit_system = YES;
            }

            // DSH appends durable workspace/runtime/skill context after the
            // user's actual turn. Those injected messages can be thousands of
            // tokens long and previously defeated Flash's <500-token automatic
            // no-thinking gate. Recover the latest direct user turn by skipping
            // the known DSH context forms, and apply the existing short-prompt
            // policy to that turn when the client did not explicitly request a
            // reasoning budget.
            int dsh_direct_user_tokens = -1;
            if (!is_continuation && !request_think_budget_explicit &&
                [request_profile_name hasPrefix:@"dsh-"]) {
                for (NSInteger mi = (NSInteger)render_messages.count - 1; mi >= 0; mi--) {
                    NSDictionary *dm = render_messages[(NSUInteger)mi];
                    if (![dm[@"role"] isEqualToString:@"user"]) continue;
                    NSString *content = [dm[@"content"] isKindOfClass:[NSString class]]
                        ? dm[@"content"] : @"";
                    BOOL injected =
                        [content hasPrefix:@"<system-reminder>\nThe following workspace instructions"] ||
                        [content hasPrefix:@"Current runtime context."] ||
                        [content hasPrefix:@"<system-reminder>\nA skill is a reusable set of task-specific instructions."];
                    if (injected) continue;
                    PromptTokens *direct_pt = tokenize_rendered_messages(@[dm], NO, NO);
                    if (direct_pt) {
                        dsh_direct_user_tokens = direct_pt->count;
                        free(direct_pt->ids);
                        free(direct_pt);
                    }
                    break;
                }
                if (dsh_direct_user_tokens >= 0 && dsh_direct_user_tokens < 500) {
                    request_enable_thinking = NO;
                    request_think_budget = -1;
                }
            }

            char request_id[64];
            snprintf(request_id, sizeof(request_id), "chatcmpl-%llu", ++req_counter);
            if ([request_profile_name hasPrefix:@"dsh-"]) {
                fprintf(stderr,
                    "[request-debug] dsh_direct_user_tokens=%d post_context_policy_thinking=%s budget=%d\n",
                    dsh_direct_user_tokens,
                    request_enable_thinking ? "on" : "off",
                    request_enable_thinking ? request_think_budget : 0);
            }
            NSString *retry_kind = [request_profile_name hasPrefix:@"dsh-"]
                ? @"flash/dsh-" : nil;
            BOOL request_retry_guard = tool_retry_guard_for_profile(
                retry_kind.UTF8String, g_tool_retry_guard_explicit,
                g_tool_retry_guard_enabled);
            NSString *retry_error = request_retry_guard && !is_continuation && has_tools
                ? repeated_tool_failure(messages) : nil;
            if (retry_error) {
                fprintf(stderr, "[serve] %s stopped repeated tool failure: %s\n",
                    request_id, retry_error.UTF8String);
                NSDictionary *error_body = @{@"error": @{
                    @"type": @"repeated_tool_failure", @"message": retry_error}};
                NSData *error_data = [NSJSONSerialization dataWithJSONObject:error_body
                    options:0 error:NULL];
            if (stream_response) {
                    http_write_str(client_fd, SSE_HEADERS);
                    NSString *json = error_data
                        ? [[NSString alloc] initWithData:error_data encoding:NSUTF8StringEncoding] : @"{}";
                    NSString *event = [NSString stringWithFormat:@"data: %@\n\ndata: [DONE]\n\n", json];
                    http_write_str(client_fd, event.UTF8String);
                } else if (error_data) {
                    char headers[256];
                    int n = snprintf(headers, sizeof(headers),
                        "HTTP/1.1 409 Conflict\r\nContent-Type: application/json\r\n"
                        "Content-Length: %lu\r\nConnection: close\r\n\r\n",
                        (unsigned long)error_data.length);
                    http_write(client_fd, headers, n);
                    http_write(client_fd, error_data.bytes, (int)error_data.length);
                }
                free(reqbuf); close(client_fd); continue;
            }
            if (has_tools) {
                NSString *saved_path = nil;
                uint64_t tool_set_sig = tool_set_signature(request_tools);
                int saved = remember_requested_tool_set(
                    request[@"tools"], tool_set_sig,
                    tool_set_cache_dir, &saved_path);
                if (saved == 1) {
                    fprintf(stderr,
                        "[serve] Learned requested tool set: tools=%lu sig=%016llx -> %s\n",
                        (unsigned long)[request[@"tools"] count],
                        (unsigned long long)tool_set_sig,
                        saved_path.fileSystemRepresentation);
                } else if (saved < 0) {
                    fprintf(stderr,
                        "[serve] WARNING: could not cache requested tool set sig=%016llx\n",
                        (unsigned long long)tool_set_sig);
                }
            }
            PromptTokens *pt;
            if (is_continuation) {
                // Session state already contains the original tools/system definition.
                // Render only the new user/tool turn, never repeat the tools block.
                NSString *turn = render_chat_prompt_with_tools(messages, nil, YES, YES);
                NSString *prefix = session_ended_with_eos == EOS_TOKEN_1 ? @"\n" : @"<|im_end|>\n";
                pt = turn ? encode_prompt_text_to_tokens([[prefix stringByAppendingString:turn] UTF8String]) : NULL;

                if (pt && !request_think_budget_explicit &&
                    automatic_no_think_for_prompt(pt->count, max_gen)) {
                    free(pt->ids); free(pt);
                    request_enable_thinking = NO;
                    request_think_budget = -1;
                    turn = render_chat_prompt_with_tools(messages, nil, YES, NO);
                    pt = turn ? encode_prompt_text_to_tokens([[prefix stringByAppendingString:turn] UTF8String]) : NULL;
                }
            } else {
                pt = tokenize_rendered_messages_with_tools(render_messages, request_tools, YES, YES);
                if (pt && !request_think_budget_explicit &&
                    automatic_no_think_for_prompt(pt->count, max_gen)) {
                    free(pt->ids); free(pt);
                    request_enable_thinking = NO;
                    request_think_budget = -1;
                    pt = tokenize_rendered_messages_with_tools(render_messages, request_tools, YES, NO);
                }
            }
            if (!pt) {
                http_write_str(client_fd, "HTTP/1.1 500 Internal Server Error\r\nConnection: close\r\n\r\n{\"error\":\"tokenization failed\"}\n");
                free(reqbuf); close(client_fd); continue;
            }

            // Temporary DSH request diagnostics: expose exactly which rendered
            // messages account for the uncached suffix without dumping whole
            // prompts. Cumulative tokenization uses the same renderer and tool
            // set as the real request, minus only the final assistant-generation
            // marker, so each delta identifies the token contribution of one
            // message as rendered on the wire.
            if (!is_continuation && [request_profile_name hasPrefix:@"dsh-"]) {
                fprintf(stderr,
                    "[request-debug] parsed_messages=%lu rendered_messages=%lu tools=%lu final_prompt_tokens=%d\n",
                    (unsigned long)messages.count,
                    (unsigned long)render_messages.count,
                    (unsigned long)request_tools.count, pt->count);
                int previous_debug_tokens = 0;
                for (NSUInteger di = 0; di < render_messages.count; di++) {
                    NSDictionary *dm = render_messages[di];
                    NSString *role = [dm[@"role"] isKindOfClass:[NSString class]]
                        ? dm[@"role"] : @"<invalid>";
                    NSString *content = [dm[@"content"] isKindOfClass:[NSString class]]
                        ? dm[@"content"] : @"";
                    NSMutableString *preview = [[content substringToIndex:MIN((NSUInteger)160, content.length)]
                        mutableCopy];
                    [preview replaceOccurrencesOfString:@"\n" withString:@"\\n"
                        options:0 range:NSMakeRange(0, preview.length)];
                    [preview replaceOccurrencesOfString:@"\r" withString:@"\\r"
                        options:0 range:NSMakeRange(0, preview.length)];
                    NSArray *debug_prefix = [render_messages subarrayWithRange:NSMakeRange(0, di + 1)];
                    PromptTokens *debug_pt = tokenize_rendered_messages_with_tools(
                        debug_prefix, request_tools, NO, request_enable_thinking);
                    int cumulative = debug_pt ? debug_pt->count : -1;
                    int delta = cumulative >= 0 ? cumulative - previous_debug_tokens : -1;
                    NSUInteger tool_call_count =
                        [dm[@"tool_calls"] isKindOfClass:[NSArray class]]
                            ? [(NSArray *)dm[@"tool_calls"] count] : 0;
                    fprintf(stderr,
                        "[request-debug] msg[%lu] role=%s chars=%lu tool_calls=%lu "
                        "tokens_delta=%d tokens_cumulative=%d preview=\"%s\"\n",
                        (unsigned long)di, role.UTF8String,
                        (unsigned long)content.length,
                        (unsigned long)tool_call_count,
                        delta, cumulative, preview.UTF8String);
                    if (debug_pt) {
                        previous_debug_tokens = debug_pt->count;
                        free(debug_pt->ids);
                        free(debug_pt);
                    }
                }
                fprintf(stderr,
                    "[request-debug] generation_marker_tokens=%d rendered_without_generation=%d final_prompt_tokens=%d\n",
                    pt->count - previous_debug_tokens,
                    previous_debug_tokens, pt->count);
            }
			if (!validate_prompt_tokens(pt, 1, "HTTP request")) {
				http_write_str(client_fd, "HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n{\"error\":\"invalid token sequence\"}\n");
				free(pt->ids); free(pt);
				free(reqbuf); close(client_fd); continue;
			}
            // A resident conversation or the configured base-system snapshot
            // contributes prompt tokens even though neither is prefetched again.
            int cached_prefix_tokens = is_continuation ? session_pos :
                (!explicit_system && !has_tools ? sys_prompt_len : 0);
            int logical_prompt_tokens = logical_prompt_token_count(
                pt->count, cached_prefix_tokens);

            BOOL tool_prefix_cache_hit = NO;
            int tool_prefix_cache_hit_slot = -1;
            int tool_prefix_capture_at = 0;
            uint64_t request_prefix_token_sig = 0;
            PromptTokens *request_prefix_pt = NULL;
            NSString *request_profile_state_path = nil;
            uint64_t request_profile_hash = 0;
            BOOL request_profile_matches = NO;

            if (!is_continuation && (has_tools || request_profile_name)) {
                // Render/tokenize only the system+tools prefix. This is cheap and
                // gives us an exact boundary in the already-tokenized full prompt.
                NSDictionary *prefix_system = render_messages.count > 0 &&
                    [render_messages[0][@"role"] isEqualToString:@"system"]
                    ? render_messages[0] : nil;
                if (prefix_system) {
                    request_prefix_pt = tokenize_rendered_messages_with_tools(
                        @[prefix_system], request_tools, NO, NO);
                }

                if (request_prefix_pt && request_prefix_pt->count > 0 &&
                    request_prefix_pt->count < pt->count &&
                    validate_prompt_tokens(request_prefix_pt, 1, "tool prefix")) {
                    request_prefix_token_sig = prompt_tokens_signature(request_prefix_pt);

                    BOOL full_starts_with_prefix =
                        pt->count >= request_prefix_pt->count &&
                        memcmp(pt->ids, request_prefix_pt->ids,
                               (size_t)request_prefix_pt->count * sizeof(uint32_t)) == 0;

                    if (request_profile_name && full_starts_with_prefix &&
                        request_prefix_pt->count <= TOOL_PREFIX_CACHE_MAX_TOKENS) {
                        NSString *cache_dir = project_tool_set_cache_directory();
                        if (!cache_dir) {
                            fprintf(stderr, "[flash-profile] WARNING: project cache directory unavailable for profile=%s\n",
                                request_profile_name.UTF8String);
                        } else {
                        BOOL agent_stack_selected = warm_profile &&
                            strncmp(warm_profile, "agent-stack/", 12) == 0 &&
                            [request_profile_name isEqualToString:default_profile_name];
                        BOOL recapture = recapture_pending &&
                            [request_profile_name isEqualToString:recapture_name];
                        NSString *source = agent_stack_selected
                            ? [NSString stringWithUTF8String:warm_tools_path]
                            : flash_profile_source_path(cache_dir, request_profile_name);
                        BOOL source_exists = [[NSFileManager defaultManager]
                            fileExistsAtPath:source];
                        if (recapture || !source_exists) {
                            NSString *effective_system = prefix_system[@"content"];
                            NSArray *raw_tools = has_tools &&
                                [request[@"tools"] isKindOfClass:[NSArray class]]
                                ? request[@"tools"] : @[];
                            if (flash_profile_write_source(source, effective_system,
                                    raw_tools, recapture)) {
                                fprintf(stderr,
                                    "[flash-profile] %s profile=%s tools=%lu tokens=%d hash=%016llx source=%s\n",
                                    recapture ? "recaptured" : "captured",
                                    request_profile_name.UTF8String,
                                    (unsigned long)raw_tools.count,
                                    request_prefix_pt->count,
                                    (unsigned long long)request_prefix_token_sig,
                                    source.fileSystemRepresentation);
                                source_exists = YES;
                                if (recapture) recapture_pending = NO;
                                flash_profile_cleanup_stale_temps(cache_dir);
                                NSMutableSet<NSString *> *protected_sources =
                                    [NSMutableSet setWithObject:source];
                                if (default_profile_name)
                                    [protected_sources addObject:flash_profile_source_path(
                                        cache_dir, default_profile_name)];
                                if (active_session_profile)
                                    [protected_sources addObject:flash_profile_source_path(
                                        cache_dir, active_session_profile)];
                                flash_profile_prune_sources(cache_dir, protected_sources,
                                    FLASH_PROFILE_SOURCE_LIMIT,
                                    FLASH_PROFILE_SOURCE_BUDGET_BYTES);
                            } else {
                                fprintf(stderr,
                                    "[flash-profile] WARNING: source capture failed for profile=%s\n",
                                    request_profile_name.UTF8String);
                            }
                        }
                        if (source_exists) {
                            uint64_t stored_tool_sig = 0, stored_token_sig = 0;
                            int stored_count = 0;
                            BOOL source_valid = warm_source_prefix_key(
                                source.fileSystemRepresentation, &stored_tool_sig,
                                &stored_token_sig, &stored_count);
                            request_profile_matches = source_valid &&
                                stored_tool_sig == request_tool_sig &&
                                stored_token_sig == request_prefix_token_sig &&
                                stored_count == request_prefix_pt->count;
                            if (request_profile_matches) {
                                NSString *identity = agent_stack_selected
                                    ? [NSString stringWithUTF8String:warm_profile]
                                    : [request_profile_name hasPrefix:@"dsh-"]
                                        ? [NSString stringWithFormat:@"dsh/%@",
                                            [request_profile_name substringFromIndex:4]]
                                        : [NSString stringWithFormat:@"flash/%@", request_profile_name];
                                request_profile_hash = warm_hash_string(
                                    UINT64_C(14695981039346656037), identity.UTF8String);
                                request_profile_state_path = agent_stack_selected
                                    ? warm_state_path : flash_profile_state_path(cache_dir,
                                        request_profile_name, request_prefix_token_sig);
                            } else {
                                fprintf(stderr,
                                    "[flash-profile] prefix mismatch profile=%s incoming_tools=%lu "
                                    "incoming_tokens=%d incoming_hash=%016llx "
                                    "stored_tokens=%d stored_hash=%016llx; source unchanged\n",
                                    request_profile_name.UTF8String,
                                    (unsigned long)request_tools.count,
                                    request_prefix_pt->count,
                                    (unsigned long long)request_prefix_token_sig,
                                    stored_count, (unsigned long long)stored_token_sig);
                            }
                        }
                        }
                    }

                    fprintf(stderr,
                            "[serve] %s tool prefix: tokens=%d sig=%016llx context=%016llx starts_full=%s warm_tokens=%d warm_sig=%016llx warm_context=%016llx\n",
                            request_id, request_prefix_pt->count,
                            (unsigned long long)request_prefix_token_sig,
                            (unsigned long long)request_tool_sig,
                            full_starts_with_prefix ? "yes" : "no",
                            tool_prefix_cache[0].token_count,
                            (unsigned long long)tool_prefix_cache[0].token_sig,
                            (unsigned long long)tool_prefix_cache[0].tool_sig);

                    if (full_starts_with_prefix && request_profile_matches &&
                        request_profile_state_path &&
                        tool_prefix_cache_find(tool_prefix_cache, request_tool_sig,
                            request_prefix_token_sig, request_prefix_pt->count) < 0) {
                        if (!warm_compatibility_valid)
                            warm_compatibility_valid = warm_state_compatibility(
                                weights_path, manifest_path, vocab_path,
                                wf, layer_fds, K, &warm_compatibility);
                        size_t checkpoint_bytes = flash_profile_checkpoint_bytes(
                            request_profile_state_path);
                        if (warm_compatibility_valid && checkpoint_bytes > 0) {
                            int victim = tool_prefix_cache_reserve(tool_prefix_cache,
                                checkpoint_bytes, g_tool_prefix_cache_budget_bytes);
                            ToolPrefixCacheEntry expected = {0};
                            expected.tool_sig = request_tool_sig;
                            expected.token_sig = request_prefix_token_sig;
                            expected.token_count = request_prefix_pt->count;
                            int repair_compressed = 0;
                            if (victim >= 0 &&
                                (warm_state_load_selected(request_profile_state_path,
                                    &tool_prefix_cache[victim], kv_caches, layer_states,
                                    warm_compatibility, request_prefix_token_sig,
                                    request_profile_hash, &expected,
                                    &repair_compressed) ||
                                 warm_state_migrate_legacy(request_profile_state_path,
                                    &tool_prefix_cache[victim], kv_caches, layer_states,
                                    weights_path, manifest_path, vocab_path,
                                    wf, layer_fds, K, request_prefix_token_sig,
                                    request_profile_hash, &expected))) {
                                if (repair_compressed &&
                                    !warm_state_save_selected(request_profile_state_path,
                                        &tool_prefix_cache[victim], kv_caches,
                                        layer_states, warm_compatibility,
                                        request_prefix_token_sig, request_profile_hash))
                                    fprintf(stderr,
                                        "[flash-profile] WARNING: damaged zstd sidecar repair failed\n");
                                tool_prefix_cache[victim].pinned = 0;
                                tool_prefix_cache[victim].last_used = ++tool_prefix_cache_clock;
                                fprintf(stderr,
                                    "[flash-profile] restored profile=%s slot=%d tokens=%d hash=%016llx\n",
                                    request_profile_name.UTF8String, victim,
                                    expected.token_count,
                                    (unsigned long long)expected.token_sig);
                            }
                        }
                    }
                    if (full_starts_with_prefix) {
                        tool_prefix_cache_hit_slot = tool_prefix_cache_find(
                            tool_prefix_cache,
                            request_tool_sig,
                            request_prefix_token_sig,
                            request_prefix_pt->count);
                    }

                    if (full_starts_with_prefix && tool_prefix_cache_hit_slot >= 0) {
                        tool_prefix_cache_hit = YES;
                        cached_prefix_tokens = request_prefix_pt->count;
                        tool_prefix_cache[tool_prefix_cache_hit_slot].last_used =
                            ++tool_prefix_cache_clock;

                        if (request_profile_matches && request_profile_state_path &&
                            !warm_state_selected_exists(request_profile_state_path)) {
                            if (!warm_compatibility_valid)
                                warm_compatibility_valid = warm_state_compatibility(
                                    weights_path, manifest_path, vocab_path,
                                    wf, layer_fds, K, &warm_compatibility);
                            if (warm_compatibility_valid &&
                                !warm_state_save_selected(request_profile_state_path,
                                    &tool_prefix_cache[tool_prefix_cache_hit_slot],
                                    kv_caches, layer_states, warm_compatibility,
                                    request_prefix_token_sig, request_profile_hash))
                                fprintf(stderr, "[flash-profile] WARNING: checkpoint save failed for profile=%s\n",
                                    request_profile_name.UTF8String);
                        }

                        int suffix_count = pt->count - request_prefix_pt->count;
                        memmove(pt->ids,
                                pt->ids + request_prefix_pt->count,
                                (size_t)suffix_count * sizeof(uint32_t));
                        pt->count = suffix_count;
                    } else if (full_starts_with_prefix) {
                        // Capture this exact prefix while processing the first
                        // full request. No second prefill pass is needed.
                        tool_prefix_capture_at = request_prefix_pt->count;
                    }
                }
            }
            int actual_prefill_tokens = pt->count;
            fprintf(stderr,
                    "[serve] %s token usage basis: logical_prompt=%d cached_prefix=%d actual_prefill=%d\n",
                    request_id, logical_prompt_tokens, cached_prefix_tokens,
                    actual_prefill_tokens);

			fprintf(stderr, "[serve] %s prompt=%d tokens%s%s thinking=%s budget=%d\n",
					request_id, pt->count,
					is_continuation ? " (continuation — skipping snapshot restore)" : "",
                    tool_prefix_cache_hit
                        ? [[NSString stringWithFormat:@" (tool-prefix cache hit slot=%d)",
                                                      tool_prefix_cache_hit_slot] UTF8String]
                        : "",
					request_enable_thinking ? "on" : "off",
					request_enable_thinking ? request_think_budget : 0);

			int start_pos = tool_prefix_cache_hit
                ? tool_prefix_cache[tool_prefix_cache_hit_slot].snapshot.pos
                : ((explicit_system || has_tools) ? 0 : sys_prompt_len);
			int preflight_pos = is_continuation ? session_pos : start_pos;

			// Deterministic capacity validation must happen before replacing the
			// resident session or mutating/restoring model state. A rejected new
			// request therefore leaves the previous conversation fully resident.
			if (!context_preflight("HTTP request", preflight_pos, pt->count, max_gen)) {
                if (request_prefix_pt) {
                    free(request_prefix_pt->ids);
                    free(request_prefix_pt);
                    request_prefix_pt = NULL;
                }
				http_write_str(client_fd,
					"HTTP/1.1 400 Bad Request\r\n"
					"Content-Type: application/json\r\n"
					"Connection: close\r\n\r\n"
					"{\"error\":\"context length exceeds engine KV capacity\"}\n");
				free(pt->ids);
				free(pt);
				free(reqbuf);
				close(client_fd);
				continue;
			}

			int pos;
			if (is_continuation) {
				// ---- Continue from existing session state ----
				// The KV caches + linear attention state already contain the full
				// conversation history. Just set pos to where we left off.
				pos = session_pos;
			} else {
				// A non-continuation request replaces the only resident session.
				// Invalidate the old identity before mutating/restoring model state;
				// commit the new session ID only after prefill succeeds.
				active_session_id[0] = '\0';
                active_session_tool_sig = 0;
                active_session_tool_sig_valid = 0;
                [active_session_pending_tool_ids removeAllObjects];
				session_pos = 0;
				session_ended_with_eos = 0;

				// ---- Restore state from a cached prefix ----
                // Tool-prefix cache takes precedence. Otherwise use the ordinary
                // base-system snapshot exactly as before.
                if (tool_prefix_cache_hit) {
                    if (!serve_state_snapshot_restore(
                            &tool_prefix_cache[tool_prefix_cache_hit_slot].snapshot,
                            kv_caches, layer_states)) {
                        fprintf(stderr, "[serve] %s tool-prefix snapshot restore failed\n",
                                request_id);
                        if (request_prefix_pt) {
                            free(request_prefix_pt->ids);
                            free(request_prefix_pt);
                        }
                        free(pt->ids); free(pt);
                        free(reqbuf); close(client_fd);
                        continue;
                    }
                }

				// Instead of resetting to zero, restore to the cached system prompt state.
				// This skips re-prefilling the system prompt tokens (~20 tokens, ~6s saved).
				for (int i = 0; i < NUM_LAYERS; i++) {
					if (!tool_prefix_cache_hit && !explicit_system && !has_tools && kv_caches[i] && kv_snapshots[i].k_snapshot) {
						size_t sz = sys_prompt_len * kv_dim * sizeof(float);
						memcpy(kv_caches[i]->k_cache, kv_snapshots[i].k_snapshot, sz);
						memcpy(kv_caches[i]->v_cache, kv_snapshots[i].v_snapshot, sz);
						kv_caches[i]->len = kv_snapshots[i].len;
						// Also restore GPU KV mirror
						if (g_metal) {
							int fa_idx = (i + 1) / FULL_ATTN_INTERVAL - 1;
							if (fa_idx >= 0 && fa_idx < g_cfg.num_full_attn_layers) {
								size_t gpu_tokens = (size_t)sys_prompt_len;
								if (gpu_tokens > GPU_KV_SEQ) gpu_tokens = GPU_KV_SEQ;
								size_t gpu_sz = gpu_tokens * kv_dim * sizeof(float);
								memcpy([g_metal->buf_kv_k[fa_idx] contents],
									   kv_snapshots[i].k_snapshot, gpu_sz);
								memcpy([g_metal->buf_kv_v[fa_idx] contents],
									   kv_snapshots[i].v_snapshot, gpu_sz);
							}
						}
					} else if (!tool_prefix_cache_hit && kv_caches[i]) {
						kv_caches[i]->len = 0;

					}
					if (!tool_prefix_cache_hit && !explicit_system && !has_tools && layer_states[i] && la_conv_snapshots[i]) {
						LinearAttnState *s = (LinearAttnState *)layer_states[i];
						memcpy(s->conv_state, la_conv_snapshots[i], conv_state_size);
						memcpy(s->ssm_state, la_ssm_snapshots[i], ssm_state_size);
					} else if (!tool_prefix_cache_hit && layer_states[i]) {
						LinearAttnState *s = (LinearAttnState *)layer_states[i];
						memset(s->conv_state, 0, conv_state_size);
						memset(s->ssm_state, 0, ssm_state_size);
					}
				}
				// Restore GPU delta-net state
				if (snapshot_uses_gpu_linear_state()) {
					for (int i = 0; i < g_cfg.num_linear_layers; i++) {
						if (!tool_prefix_cache_hit && explicit_system && g_metal->buf_delta_state[i]) memset([g_metal->buf_delta_state[i] contents], 0, 64*128*128*sizeof(float));
						if (!tool_prefix_cache_hit && !explicit_system && !has_tools && gpu_delta_snapshots[i] && g_metal->buf_delta_state[i])
							memcpy([g_metal->buf_delta_state[i] contents],
								   gpu_delta_snapshots[i], 64*128*128*sizeof(float));
						if (!tool_prefix_cache_hit && explicit_system && g_metal->buf_conv_state[i]) memset([g_metal->buf_conv_state[i] contents], 0, 3*12288*sizeof(float));
						if (!tool_prefix_cache_hit && !explicit_system && !has_tools && gpu_conv_snapshots[i] && g_metal->buf_conv_state[i])
							memcpy([g_metal->buf_conv_state[i] contents],
								   gpu_conv_snapshots[i], 3*12288*sizeof(float));
					}
				} else if (!tool_prefix_cache_hit) {
					reset_delta_net_state();
				}
				pos = start_pos;  // start after cached system prompt
			}
			if (g_cache_telemetry_enabled) cache_telemetry_reset();

			// Streaming requests use SSE. Non-streaming requests defer HTTP output
			// until generation completes so we can return one JSON completion object.
			if (stream_response && http_write_str(client_fd, SSE_HEADERS) < 0) {
				active_session_id[0] = '\0';
				active_session_profile = nil;
				active_session_tool_sig = 0;
				active_session_tool_sig_valid = 0;
				[active_session_pending_tool_ids removeAllObjects];
				session_pos = 0;
				session_ended_with_eos = 0;
				if (request_prefix_pt) { free(request_prefix_pt->ids); free(request_prefix_pt); }
				free(pt->ids); free(pt); free(reqbuf); close(client_fd);
				continue;
			}

			g_forward_error = 0;

			// ---- Batch prefill ----
			double t_prefill = now_ms();
			double prefill_embedding_ms = 0.0;
			double prefill_forward_ms = 0.0;
			double prefill_snapshot_ms = 0.0;
			double prefill_last_keepalive_ms = t_prefill;
			int prefill_completed_tokens = 0;
			int prefill_client_disconnected = 0;
			int prefill_nrow_chunks = 0;
			// Pre-embed all request tokens
			float *serve_embed_batch = try_alloc_embedding_batch(pt->count, "HTTP");
			if (serve_embed_batch) {
				for (int i = 0; i < pt->count; i++) {
					embed_lookup(wf, pt->ids[i], serve_embed_batch + (size_t)i * HIDDEN_DIM);
				}
			}
			prefill_embedding_ms = now_ms() - t_prefill;
			// Intermediate prefill tokens. Production N-row consumes only complete
			// slabs when no tool-prefix snapshot boundary is pending; the remainder
			// retains the established scalar path. Workspace initialization is lazy:
			// short requests that cannot enter N-row do not reserve its ~half-GiB workspace.
#ifdef FLASH_PREFILL_NROW_PRODUCTION
			int serve_nrow_ready = 0;
			int serve_nrow_prepare_attempted = 0;
#endif
			for (int i = 0; i < pt->count - 1; ) {
				if ((i & 7) == 0 && http_client_disconnected(client_fd)) {
					prefill_client_disconnected = 1;
					break;
				}
#ifdef FLASH_PREFILL_NROW_PRODUCTION
				if (g_prefill_nrow_runtime_enabled &&
					prefill_nrow_runtime_cache_range_eligible(kv_caches) &&
					tool_prefix_capture_at == 0 &&
					(pt->count - 1 - i) >= PREFILL_NROW_CAPTURE_ROWS) {
					if (!serve_nrow_prepare_attempted) {
						serve_nrow_ready = prefill_nrow_runtime_prepare(K);
						serve_nrow_prepare_attempted = 1;
						if (!serve_nrow_ready)
							fprintf(stderr, "[prefill-nrow] production runtime unavailable; using scalar prefill\n");
					}
					if (serve_nrow_ready) {
					for (int row = 0; row < PREFILL_NROW_CAPTURE_ROWS; row++)
						cache_telemetry_note_token();
					double forward_started_ms = now_ms();
					const float *embedded_rows = serve_embed_batch
						? serve_embed_batch + (size_t)i * HIDDEN_DIM : NULL;
					ServeNRowPollContext nrow_poll = {
						.client_fd = client_fd,
						.stream_response = stream_response,
						.request_id = request_id,
						.last_keepalive_ms = &prefill_last_keepalive_ms,
						.client_disconnected = &prefill_client_disconnected,
					};
					if (!prefill_nrow_runtime_chunk(
							wf, kv_caches, layer_states, (void **)layer_mmaps,
							layer_fds, K, pos, pt->ids + i, embedded_rows, NULL,
							serve_nrow_poll, &nrow_poll)) {
						if (!prefill_client_disconnected) g_forward_error = 1;
						break;
					}
					prefill_forward_ms += now_ms() - forward_started_ms;
					i += PREFILL_NROW_CAPTURE_ROWS;
					pos += PREFILL_NROW_CAPTURE_ROWS;
					prefill_completed_tokens += PREFILL_NROW_CAPTURE_ROWS;
					prefill_nrow_chunks++;
					if ((prefill_completed_tokens & 127) == 0)
						fprintf(stderr,
							"[serve] %s N-row(%d) prefill progress=%d/%d elapsed=%.0fms forward=%.0fms snapshot=%.0fms\n",
							request_id, PREFILL_NROW_CAPTURE_ROWS, prefill_completed_tokens, pt->count,
							now_ms() - t_prefill, prefill_forward_ms, prefill_snapshot_ms);
					if (stream_response &&
						now_ms() - prefill_last_keepalive_ms >= 10000.0) {
						if (sse_send_keepalive(client_fd, request_id) < 0) {
							prefill_client_disconnected = 1;
							break;
						}
						prefill_last_keepalive_ms = now_ms();
					}
					continue;
					}
				}
#endif
				cache_telemetry_note_token();
				if (serve_embed_batch) {
					memcpy(hidden, serve_embed_batch + (size_t)i * HIDDEN_DIM,
						   HIDDEN_DIM * sizeof(float));
				} else {
					embed_lookup(wf, pt->ids[i], hidden);
				}
				double forward_started_ms = now_ms();
				g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
								(void **)layer_mmaps, layer_fds, pos, K);
				prefill_forward_ms += now_ms() - forward_started_ms;
				if (g_forward_error) break;
				if (!discard_deferred_experts()) break;
				pos++;
				i++;
				prefill_completed_tokens++;

                if (!tool_prefix_cache_hit &&
                    tool_prefix_capture_at > 0 &&
                    tool_prefix_capture_at <= TOOL_PREFIX_CACHE_MAX_TOKENS &&
                    pos == tool_prefix_capture_at) {
                    // The exact tool/system prefix has just been consumed.
                    // Snapshot it before the user turn mutates recurrent state.
                    double snapshot_started_ms = now_ms();
                    size_t expected_bytes = serve_state_snapshot_expected_bytes(
                        kv_caches, layer_states);
                    int victim = tool_prefix_cache_reserve(tool_prefix_cache,
                        expected_bytes, g_tool_prefix_cache_budget_bytes);
                    if (victim >= 0 &&
                        serve_state_snapshot_capture(&tool_prefix_cache[victim].snapshot,
                                                     kv_caches, layer_states, pos)) {
                        size_t captured_bytes = serve_state_snapshot_bytes(
                            &tool_prefix_cache[victim].snapshot);
                        if (captured_bytes > g_tool_prefix_cache_budget_bytes ||
                            tool_prefix_dynamic_bytes(tool_prefix_cache) >
                                g_tool_prefix_cache_budget_bytes) {
                            serve_state_snapshot_free(&tool_prefix_cache[victim].snapshot);
                            fprintf(stderr, "[serve] tool-prefix snapshot exceeded RAM budget; discarded\n");
                            tool_prefix_capture_at = 0;
                            continue;
                        }
                        tool_prefix_cache[victim].tool_sig = request_tool_sig;
                        tool_prefix_cache[victim].token_sig = request_prefix_token_sig;
                        tool_prefix_cache[victim].token_count = tool_prefix_capture_at;
                        tool_prefix_cache[victim].last_used = ++tool_prefix_cache_clock;
                        // Dynamic entries are never pinned.
                        tool_prefix_cache[victim].pinned = 0;
                        fprintf(stderr,
                                "[serve] Tool prefix cached from request: slot=%d tokens=%d bytes=%zu dynamic=%zu/%zu sig=%016llx\n",
                                victim,
                                tool_prefix_cache[victim].token_count,
                                captured_bytes,
                                tool_prefix_dynamic_bytes(tool_prefix_cache),
                                g_tool_prefix_cache_budget_bytes,
                                (unsigned long long)tool_prefix_cache[victim].tool_sig);
                        if (request_profile_matches && request_profile_state_path) {
                            if (!warm_compatibility_valid)
                                warm_compatibility_valid = warm_state_compatibility(
                                    weights_path, manifest_path, vocab_path,
                                    wf, layer_fds, K, &warm_compatibility);
                            if (warm_compatibility_valid &&
                                !warm_state_save_selected(request_profile_state_path,
                                    &tool_prefix_cache[victim], kv_caches, layer_states,
                                    warm_compatibility, request_prefix_token_sig,
                                    request_profile_hash))
                                fprintf(stderr, "[flash-profile] WARNING: checkpoint save failed for profile=%s\n",
                                    request_profile_name.UTF8String);
                        }
                    } else {
                        fprintf(stderr,
                                "[serve] WARNING: tool-prefix cache capture failed; continuing uncached\n");
                    }
                    prefill_snapshot_ms += now_ms() - snapshot_started_ms;
                    tool_prefix_capture_at = 0;
                }
				if ((prefill_completed_tokens & 31) == 0) {
					double progress_ms = now_ms();
					if ((prefill_completed_tokens & 127) == 0)
						fprintf(stderr,
							"[serve] %s prefill progress=%d/%d elapsed=%.0fms forward=%.0fms snapshot=%.0fms\n",
							request_id, prefill_completed_tokens, pt->count,
							progress_ms - t_prefill, prefill_forward_ms, prefill_snapshot_ms);
					if (stream_response &&
						progress_ms - prefill_last_keepalive_ms >= 10000.0) {
						if (sse_send_keepalive(client_fd, request_id) < 0) {
							fprintf(stderr, "[serve] %s client disconnected during prefill\n",
								request_id);
							prefill_client_disconnected = 1;
							break;
						}
						prefill_last_keepalive_ms = progress_ms;
					}
				}
			}
			if (g_forward_error || prefill_client_disconnected) {
				fprintf(stderr, "[serve] %s prefill aborted: %s after %d/%d tokens\n",
					request_id,
					prefill_client_disconnected ? "client disconnected" : "forward failure",
					prefill_completed_tokens, pt->count);
				active_session_id[0] = '\0';
                active_session_tool_sig = 0;
                active_session_tool_sig_valid = 0;
                [active_session_pending_tool_ids removeAllObjects];
				session_pos = 0;
				session_ended_with_eos = 0;
				if (serve_embed_batch) free(serve_embed_batch);
                if (request_prefix_pt) {
                    free(request_prefix_pt->ids);
                    free(request_prefix_pt);
                    request_prefix_pt = NULL;
                }
				if (!prefill_client_disconnected)
					send_session_invalidated_error(
						client_fd, stream_response, @"prefill failed");
				free(pt->ids); free(pt);
				free(reqbuf); close(client_fd);
				continue;
			}
			// Last prefill token: full completion (need hidden for logits)
			{
				if (http_client_disconnected(client_fd)) {
					prefill_client_disconnected = 1;
				} else {
				cache_telemetry_note_token();
				if (serve_embed_batch) {
					memcpy(hidden, serve_embed_batch + (size_t)(pt->count - 1) * HIDDEN_DIM,
						   HIDDEN_DIM * sizeof(float));
				} else {
					embed_lookup(wf, pt->ids[pt->count - 1], hidden);
				}
				double forward_started_ms = now_ms();
				g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
								(void **)layer_mmaps, layer_fds, pos, K);
				prefill_forward_ms += now_ms() - forward_started_ms;
				prefill_completed_tokens++;
				if (!g_forward_error) {
					if (!complete_deferred_experts()) {
						g_forward_error = 1;
					} else {
						pos++;
					}
				}
				}
			}
			if (g_forward_error || prefill_client_disconnected) {
				fprintf(stderr, "[serve] %s final prefill token failed\n", request_id);
				active_session_id[0] = '\0';
                active_session_profile = nil;
                active_session_tool_sig = 0;
                active_session_tool_sig_valid = 0;
                [active_session_pending_tool_ids removeAllObjects];
				session_pos = 0;
				session_ended_with_eos = 0;
				if (serve_embed_batch) free(serve_embed_batch);
                if (request_prefix_pt) {
                    free(request_prefix_pt->ids);
                    free(request_prefix_pt);
                    request_prefix_pt = NULL;
                }
				if (!prefill_client_disconnected)
					send_session_invalidated_error(
						client_fd, stream_response, @"prefill failed");
				free(pt->ids); free(pt);
				free(reqbuf); close(client_fd);
				continue;
			}
			if (serve_embed_batch) { free(serve_embed_batch); serve_embed_batch = NULL; }
            if (request_prefix_pt) {
                free(request_prefix_pt->ids);
                free(request_prefix_pt);
                request_prefix_pt = NULL;
            }

			// Transaction commit: only publish the new session identity after
			// prefill has fully completed.
			if (!is_continuation) {
				if (has_session) {
                    strlcpy(active_session_id, req_session_id, sizeof(active_session_id));
                    active_session_profile = request_profile_name;
                    active_session_tool_sig = request_tool_sig;
                    active_session_tool_sig_valid = 1;
                } else {
                    active_session_id[0] = '\0';
                    active_session_profile = nil;
                    active_session_tool_sig = 0;
                    active_session_tool_sig_valid = 0;
                }
			}

            if (is_continuation && all_tool_messages) {
                [active_session_pending_tool_ids removeAllObjects];
            }

			double prefill_ms = now_ms() - t_prefill;
			fprintf(stderr,
				"[serve] %s prefill=%d tokens in %.0fms (embedding=%.0fms forward=%.0fms snapshot=%.0fms other=%.0fms, %.1f tokens/s, nrow_chunks=%d)\n",
				request_id, prefill_completed_tokens, prefill_ms,
				prefill_embedding_ms, prefill_forward_ms, prefill_snapshot_ms,
				prefill_ms - prefill_embedding_ms - prefill_forward_ms - prefill_snapshot_ms,
				prefill_ms > 0.0 ? prefill_completed_tokens * 1000.0 / prefill_ms : 0.0,
				prefill_nrow_chunks);

			// Full generation wall time includes the first-token LM head and every
            // generated token, but excludes post-generation parsing and response I/O.
            double t_gen = now_ms();
			// ---- Final norm + LM head for first token ----
			if (final_norm_w) {
				apply_final_norm_inplace(hidden, final_norm_w);
			}
			int next_token;
			if (g_temperature <= 0.0f && g_gpu_argmax_enabled)
				next_token = lm_head_forward_greedy(wf, hidden, logits);
			else {
				lm_head_forward(wf, hidden, logits);
				next_token = cpu_sample_token(logits, VOCAB_SIZE);
			}

			// ---- Auto-regressive generation with SSE streaming ----
			if (g_pred_enabled || g_expert_prefetch_enabled) {
				g_pred_generating = g_pred_enabled ? 1 : 0;
				g_expert_prefetch_generating = g_expert_prefetch_enabled ? 1 : 0;
				g_pred_valid = 0;
				if (g_expert_prefetch_enabled) expert_prefetch_history_reset();
			}
			if (g_cmd1_profile_enabled) g_cmd1_profile_decode_active = 1;
			int completion_tokens = 0;
			int request_state_failed = 0;
			int session_reusable = 1;
			int request_client_disconnected = 0;
            session_ended_with_eos = 0;
			int in_think = tokens_end_in_think(pt->ids, pt->count);
			int think_tokens = 0;
			uint32_t *think_stop_seq = NULL;
			int think_stop_count = 0;
			int think_stop_index = 0;
			int think_stop_active = 0;
			int final_content_started = 0;
			Utf8TokenStream serve_utf8 = {0};
			NSMutableString *reasoning_text = stream_response ? nil : [NSMutableString string];
			NSMutableString *content_text = stream_response ? nil : [NSMutableString string];
            NSMutableString *tool_call_text = [NSMutableString string];
            int tool_output_started = 0;
            int tool_call_active = 0;
            NSUInteger tool_complete_blocks = 0;
            int tool_syntax_error = 0;
            int tool_suffix_nonspace = 0;
            NSString *exact_read_body = [last_role isEqualToString:@"tool"]
                ? nil : exact_literal_read_call(messages, request_tools);
            NSString *literal_file_path = literal_file_path_for_generation(messages);
            BOOL request_dsh_mode = [request_profile_name hasPrefix:@"dsh-"];
            NSArray<NSDictionary *> *decoder_tools = dsh_decoder_tools(
                request_tools, messages, request_dsh_mode);
            uint32_t *exact_read_tokens = NULL;
            int exact_read_count = 0, exact_read_index = 0;
            NSMutableDictionary *tool_wire_plan = nil;
            if (exact_read_body && g_tokenizer_loaded) {
                const char *body = exact_read_body.UTF8String;
                int capacity = (int)strlen(body) * 4 + 8;
                exact_read_tokens = malloc((size_t)capacity * sizeof(uint32_t));
                if (exact_read_tokens) {
                    exact_read_count = bpe_encode(&g_tokenizer, body,
                        exact_read_tokens, capacity);
                    if (exact_read_count <= 0) {
                        free(exact_read_tokens);
                        exact_read_tokens = NULL;
                        exact_read_count = 0;
                    }
                }
            }
			for (int gen = 0; gen < max_gen; gen++) {
                if ((gen & 7) == 0 && http_client_disconnected(client_fd)) {
                    fprintf(stderr, "[serve] %s client disconnected during decode\n", request_id);
                    request_client_disconnected = 1;
                    request_state_failed = 1;
                    session_reusable = 0;
                    break;
                }
                if (tool_call_active && !exact_read_tokens && tool_wire_plan) {
                    next_token = tool_wire_next_token(
                        tool_wire_plan, decoder_tools, logits, next_token);
                    if (next_token == -2) {
                        fprintf(stderr,
                            "[serve] %s control token interrupted a tool parameter value\n",
                            request_id);
                        tool_syntax_error = 1;
                        break;
                    }
                    if (next_token < 0) {
                        fprintf(stderr, "[serve] %s schema-constrained tool decoding failed\n",
                                request_id);
                        request_state_failed = 1;
                        break;
                    }
                }
                if (tool_call_active && exact_read_tokens &&
                    exact_read_index <= exact_read_count) {
                    next_token = exact_read_index == exact_read_count
                        ? TOOL_CALL_END_TOKEN : (int)exact_read_tokens[exact_read_index];
                    exact_read_index++;
                }
				if (next_token == EOS_TOKEN_1 || next_token == EOS_TOKEN_2) {
					completion_tokens++; // The emitted stop token belongs to completion usage.
					session_ended_with_eos = next_token;
					if (next_token == EOS_TOKEN_2) session_reusable = 0;
                    // Feed EOS through the model so session state includes it
					cache_telemetry_note_token();
					embed_lookup(wf, next_token, hidden);
					g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
									(void **)layer_mmaps, layer_fds, pos, K);
					if (g_forward_error) {
						fprintf(stderr, "[serve] %s EOS-state forward failed\n", request_id);
						request_state_failed = 1;
						active_session_id[0] = '\0';
                        active_session_tool_sig = 0;
                        active_session_tool_sig_valid = 0;
						session_pos = 0;
						session_ended_with_eos = 0;
						break;
					}
					if (!discard_deferred_experts()) {
						fprintf(stderr, "[serve] %s EOS-state deferred Metal completion failed\n", request_id);
						request_state_failed = 1;
						active_session_id[0] = '\0';
						active_session_tool_sig = 0;
						active_session_tool_sig_valid = 0;
						session_pos = 0;
						session_ended_with_eos = 0;
						break;
					}
					pos++;
					break;
				}

                // A native tool call can begin directly from reasoning without an
                // explicit </think>. Tool start therefore ends reasoning *before* any
                // budget accounting, and tool-call generation never consumes budget.
                if (next_token == TOOL_CALL_START_TOKEN) {
                    if (tool_call_active) tool_syntax_error = 1;
                    in_think = 0;
                    if (think_stop_active) {
                        think_stop_active = 0;
                        think_stop_index = 0;
                    }
                    tool_output_started = 1;
                    tool_call_active = 1;
                    [tool_call_text appendString:@"<tool_call>"];
                    if (!exact_read_tokens && request_tools.count > 0) {
                        tool_wire_plan = [NSMutableDictionary dictionary];
                        if (literal_file_path) {
                            tool_wire_plan[@"literal_path"] = literal_file_path;
                            if (literal_path_is_destination(messages, literal_file_path))
                                tool_wire_plan[@"destination_path"] = literal_file_path;
                        }
                        if (!tool_wire_force(tool_wire_plan, @"\n<function=", @"function")) {
                            request_state_failed = 1;
                            break;
                        }
                    }
                    if (exact_read_tokens && gen + exact_read_count + 2 >= max_gen) {
                        free(exact_read_tokens);
                        exact_read_tokens = NULL;
                    }
                } else if (next_token == TOOL_CALL_END_TOKEN) {
                    if (tool_call_active) {
                        [tool_call_text appendString:@"</tool_call>"];
                        tool_call_active = 0;
                        tool_complete_blocks++;
                    } else {
                        tool_syntax_error = 1;
                    }
                }

				// Qwen thinking-budget handoff. Inject the documented early-stop
				// steering text internally, then </think>\n\n, before resuming sampling.
				int suppress_token_output = 0;
                if (!tool_call_active && next_token != TOOL_CALL_START_TOKEN) {
                    if (think_stop_active && think_stop_index < think_stop_count) {
                        next_token = think_stop_seq[think_stop_index++];
                        suppress_token_output = 1;
                        if (think_stop_index >= think_stop_count) think_stop_active = 0;
                    } else {
                        if (next_token == THINK_START_TOKEN) in_think = 1;
                        if (in_think) {
                            think_tokens++;
                            if (request_think_budget > 0 && think_tokens >= request_think_budget) {
                                think_stop_seq = build_think_stop_sequence(&think_stop_count);
                                if (think_stop_seq && think_stop_count > 0) {
                                    fprintf(stderr, "[serve] %s think budget reached (%d), applying Qwen early-stop handoff (%d tokens)\n", request_id, request_think_budget, think_stop_count);
                                    think_stop_active = 1;
                                    think_stop_index = 1;
                                    next_token = think_stop_seq[0];
                                    suppress_token_output = 1;
                                } else {
                                    next_token = THINK_END_TOKEN;
                                }
                            }
                        }
                    }
                }
				if (next_token == THINK_END_TOKEN) in_think = 0;

				// The tokenizer's added-token range contains Qwen control tokens.
				// They remain in model state, but never appear in normal API text deltas.
				int is_control_token =
                    next_token == TOOL_CALL_START_TOKEN ||
                    next_token == TOOL_CALL_END_TOKEN ||
                    next_token == TOOL_RESP_START_TOKEN ||
                    next_token == TOOL_RESP_END_TOKEN ||
                    next_token == THINK_START_TOKEN ||
                    next_token == THINK_END_TOKEN ||
                    (g_tokenizer_loaded && (uint32_t)next_token >= g_tokenizer.vocab_size);
				char *tok_str = is_control_token ? NULL :
					utf8_token_stream_push_token(&serve_utf8, vocab, next_token);
				char *tok_emit = suppress_token_output ? NULL : tok_str;

                if (tok_emit && *tok_emit && tool_output_started) {
                    if (tool_call_active) {
                        NSString *piece = [NSString stringWithUTF8String:tok_emit];
                        if (piece) {
                            [tool_call_text appendString:piece];
                            if ([tool_wire_plan[@"state"] isEqualToString:@"value"] &&
                                tool_wire_parameter_closed(tool_call_text))
                                tool_wire_plan[@"state"] = @"next";
                        }
                    } else {
                        const char *p = tok_emit;
                        while (*p && strchr(" \t\r\n\f\v", *p)) p++;
                        if (*p) tool_suffix_nonspace = 1;
                    }
                    // Native tool syntax is represented structurally in the API response.
                    tok_emit = NULL;
                }

				if (tok_emit && !in_think && !final_content_started) {
					while (*tok_emit && strchr(" \t\r\n\f\v", *tok_emit)) tok_emit++;
					if (*tok_emit) final_content_started = 1;
					else tok_emit = NULL;
				}
				if (tok_emit && *tok_emit) {
					if (stream_response) {
						if (sse_send_delta(client_fd, request_id,
								in_think ? "reasoning_content" : "content", tok_emit) < 0) {
							fprintf(stderr, "[serve] %s client disconnected, invalidating session\n", request_id);
							free(tok_str);
							request_state_failed = 1;
							session_reusable = 0;
							break;
						}
					} else {
						NSString *piece = [NSString stringWithUTF8String:tok_emit];
						if (piece) [(in_think ? reasoning_text : content_text) appendString:piece];
					}
				}
				free(tok_str);
				completion_tokens++;

				// Generate next
				cache_telemetry_note_token();
				embed_lookup(wf, next_token, hidden);
				g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
								(void **)layer_mmaps, layer_fds, pos, K);
				if (g_forward_error) {
					fprintf(stderr, "[serve] %s generation forward failed\n", request_id);
					request_state_failed = 1;
					active_session_id[0] = '\0';
                    active_session_tool_sig = 0;
                    active_session_tool_sig_valid = 0;
					session_pos = 0;
					session_ended_with_eos = 0;
					break;
				}
				if (!complete_deferred_experts()) {
					fprintf(stderr, "[serve] %s deferred Metal completion failed\n", request_id);
					request_state_failed = 1;
					active_session_id[0] = '\0';
					active_session_tool_sig = 0;
					active_session_tool_sig_valid = 0;
					session_pos = 0;
					session_ended_with_eos = 0;
					break;
				}
				pos++;

				if (final_norm_w) {
					apply_final_norm_inplace(hidden, final_norm_w);
				}
				if (tool_call_active && tool_wire_plan && !exact_read_tokens) {
					lm_head_forward(wf, hidden, logits);
					next_token = cpu_sample_token(logits, VOCAB_SIZE);
				} else if (g_temperature <= 0.0f && g_gpu_argmax_enabled)
					next_token = lm_head_forward_greedy(wf, hidden, logits);
				else {
					lm_head_forward(wf, hidden, logits);
					next_token = cpu_sample_token(logits, VOCAB_SIZE);
				}

			}
			double decode_ms = now_ms() - t_gen;
			g_cmd1_profile_decode_active = 0;
            free(exact_read_tokens);
			free(think_stop_seq);
			think_stop_seq = NULL;

			if (!request_state_failed && serve_utf8.pending_len > 0) {
				char *tail = utf8_token_stream_flush(&serve_utf8);
				if (tail && *tail) {
                    if (tool_output_started) {
                        if (tool_call_active) {
                            NSString *piece = [NSString stringWithUTF8String:tail];
                            if (piece) [tool_call_text appendString:piece];
                        }
                    } else if (stream_response) {
						if (sse_send_delta(client_fd, request_id,
							in_think ? "reasoning_content" : "content", tail) < 0) {
							request_state_failed = 1;
							session_reusable = 0;
						}
					} else {
						NSString *piece = [NSString stringWithUTF8String:tail];
						if (piece) [(in_think ? reasoning_text : content_text) appendString:piece];
					}
				}
				free(tail);
			}

            BOOL tool_parse_valid = YES;
            NSString *tool_parse_error = nil;
            NSUInteger regex_complete_blocks = 0;
            NSArray<NSDictionary *> *parsed_tool_calls = request_state_failed ? @[] :
                parse_qwen_tool_calls(tool_call_text, request_tools, &tool_parse_valid,
                                      &tool_parse_error, &regex_complete_blocks);
            BOOL sanitized_tool_call = NO;
            if (tool_parse_valid && parsed_tool_calls.count)
                parsed_tool_calls = remove_speculative_write_escalation(
                    parsed_tool_calls, messages, request_dsh_mode, &sanitized_tool_call);
            if (sanitized_tool_call) session_reusable = 0;
            BOOL tool_parse_failed = !request_state_failed && tool_output_started &&
                (tool_call_active || tool_syntax_error || tool_suffix_nonspace ||
                 !tool_parse_valid || tool_complete_blocks == 0 ||
                 regex_complete_blocks != tool_complete_blocks ||
                 parsed_tool_calls.count != tool_complete_blocks);
            if (tool_parse_failed && !tool_parse_error) {
                if (tool_call_active) tool_parse_error = @"incomplete native tool call";
                else if (tool_suffix_nonspace) tool_parse_error = @"unexpected text after native tool call";
                else tool_parse_error = @"malformed native tool call";
            }
            BOOL has_tool_calls = !tool_parse_failed && parsed_tool_calls.count > 0;
            BOOL strict_invalid_tool_call = NO;

            if (tool_parse_failed) {
                const char *raw_tool_call = tool_call_text.UTF8String ?: "";
                fprintf(stderr,
                        "[serve] %s malformed tool-call diagnostic: reason=%s "
                        "chars=%lu complete_blocks=%lu parsed_calls=%lu "
                        "active=%d syntax_error=%d suffix_nonspace=%d regex_blocks=%lu\n",
                        request_id,
                        tool_parse_error.UTF8String ?: "unknown error",
                        (unsigned long)tool_call_text.length,
                        (unsigned long)tool_complete_blocks,
                        (unsigned long)parsed_tool_calls.count,
                        tool_call_active,
                        tool_syntax_error,
                        tool_suffix_nonspace,
                        (unsigned long)regex_complete_blocks);
                fprintf(stderr,
                        "[serve] %s malformed tool-call raw BEGIN\n%s\n"
                        "[serve] %s malformed tool-call raw END\n",
                        request_id, raw_tool_call, request_id);

                // Preserve the Rev. 9.3 assistant-content recovery by default.
                // Strict provider errors remain available by explicit flag.
                if (!g_malformed_tool_recovery_enabled) {
                    strict_invalid_tool_call = YES;
                    request_state_failed = 1;
                    tool_parse_failed = NO;
                }
            }

            if (!request_state_failed && !tool_parse_failed && active_session_id[0]) {
                [active_session_pending_tool_ids removeAllObjects];
                if (has_tool_calls) {
                    for (NSDictionary *call in parsed_tool_calls) {
                        NSString *call_id = [call[@"id"] isKindOfClass:[NSString class]]
                            ? call[@"id"] : nil;
                        if (call_id) [active_session_pending_tool_ids addObject:call_id];
                    }
                }
            }

            double prefill_tps = prefill_ms > 0.0
                ? prefill_completed_tokens * 1000.0 / prefill_ms : 0.0;
            double decode_tps = decode_ms > 0.0
                ? completion_tokens * 1000.0 / decode_ms : 0.0;
            NSDictionary *flash_timings = @{
                @"context_tokens": @(logical_prompt_tokens),
                @"cached_prefix_tokens": @(cached_prefix_tokens),
                @"prefill_tokens": @(prefill_completed_tokens),
                @"prefill_ms": @(prefill_ms),
                @"prefill_tokens_per_second": @(prefill_tps),
                @"generated_tokens": @(completion_tokens),
                @"decode_ms": @(decode_ms),
                @"decode_tokens_per_second": @(decode_tps),
                @"session_reused": @(is_continuation),
                @"warm_prefix_reused": @(tool_prefix_cache_hit)
            };

			if (request_client_disconnected) {
				// No response can be delivered; common cleanup below clears session reuse.
			} else if (stream_response) {
                if (request_state_failed) {
                    session_reusable = 0;
                    if (strict_invalid_tool_call) {
                        http_write_str(client_fd,
                            "data: {\"error\":{\"type\":\"invalid_tool_call\","
                            "\"message\":\"malformed model tool call\","
                            "\"session_invalidated\":true,\"resend_full_history\":true}}\n\n"
                            "data: [DONE]\n\n");
                    } else {
                        send_session_invalidated_error(
                            client_fd, 1, @"generation failed");
                    }
                } else if (tool_parse_failed) {
                    session_reusable = 0;

                    // Rev. 9.3 streaming compatibility experiment:
                    // The SSE response headers have already been sent, so a malformed
                    // model-generated tool call cannot be converted into a normal JSON
                    // HTTP response here. Instead, finish the existing stream as a
                    // valid assistant completion: recovery content, finish_reason=stop,
                    // then [DONE].
                    NSString *stream_recovery_text = [NSString stringWithFormat:
                        @"Tool call rejected by the server: %@. "
                         "The generated tool call was invalid. "
                         "Retry using the tool's exact schema and preserve the user's "
                         "argument values exactly.",
                        tool_parse_error ?: @"malformed tool call"];

                    if (sse_send_delta(client_fd, request_id, "content",
                                       stream_recovery_text.UTF8String) < 0) {
                        fprintf(stderr,
                                "[serve] %s client disconnected while sending "
                                "malformed-tool SSE recovery\n",
                                request_id);
                        request_state_failed = 1;
                    } else {
                        if (sse_send_done(client_fd, request_id, "stop", include_stream_usage,
                                          logical_prompt_tokens, completion_tokens, 1,
                                          flash_timings) < 0) request_state_failed = 1;
                        fprintf(stderr,
                                "[serve] %s malformed tool call returned as SSE "
                                "assistant recovery + finish_reason=stop\n",
                                request_id);
                    }

                    /*
                     * PREVIOUS STREAMING ERROR BEHAVIOR — RETAINED FOR FUTURE
                     * HARNESS/AGENT-STACK COMPATIBILITY TESTING:
                     *
                     * sse_send_error(client_fd, tool_parse_error);
                     *
                     * That sends:
                     *   data: {"error": {...}}
                     *   data: [DONE]
                     *
                     * DSH appeared to remain stuck in Running/Think after this form,
                     * but another OpenAI-compatible harness may prefer or require it.
                     */
                } else if (has_tool_calls) {
                    if (sse_send_tool_calls(client_fd, request_id, parsed_tool_calls) < 0) {
                        fprintf(stderr, "[serve] %s client disconnected while sending tool calls\n", request_id);
                        request_state_failed = 1;
                        session_reusable = 0;
                    }
                }
                if (!request_state_failed && !tool_parse_failed) {
                    const char *finish = has_tool_calls ? "tool_calls" :
                        (session_ended_with_eos ? "stop" : "length");
                    if (sse_send_done(client_fd, request_id, finish, include_stream_usage,
                                      logical_prompt_tokens, completion_tokens,
                                      sanitized_tool_call, flash_timings) < 0) {
                        fprintf(stderr, "[serve] %s final SSE delivery failed, invalidating session\n",
                                request_id);
                        request_state_failed = 1;
                        session_reusable = 0;
                    }
                }
			} else if (request_state_failed) {
                if (strict_invalid_tool_call) {
					http_write_str(client_fd,
                        "HTTP/1.1 500 Internal Server Error\r\nContent-Type: application/json\r\n"
                        "Connection: close\r\n\r\n"
                        "{\"error\":{\"type\":\"invalid_tool_call\","
                        "\"message\":\"malformed model tool call\","
                        "\"session_invalidated\":true,\"resend_full_history\":true}}\n");
                } else {
                    send_session_invalidated_error(
                        client_fd, 0, @"generation failed");
                }
            } else if (tool_parse_failed) {
                session_reusable = 0;

                // Rev. 9.2 non-streaming compatibility experiment — intentionally
                // retained in Rev. 9.3 for future harness/agent-stack testing.
                // Return a valid Chat Completions response instead of a provider-level
                // HTTP 500 when the model itself emitted a malformed native tool call.
                // The malformed native text is still logged above verbatim.
                NSDictionary *recovery_response = malformed_tool_recovery_response(
                    request_id, tool_parse_error, logical_prompt_tokens,
                    completion_tokens, flash_timings);

                NSData *recovery_data =
                    [NSJSONSerialization dataWithJSONObject:recovery_response
                                                   options:0
                                                     error:NULL];
                if (recovery_data) {
                    char recovery_headers[512];
                    int recovery_hn = snprintf(
                        recovery_headers, sizeof(recovery_headers),
                        "HTTP/1.1 200 OK\r\n"
                        "Content-Type: application/json; charset=utf-8\r\n"
                        "Content-Length: %lu\r\n"
                        "Access-Control-Allow-Origin: *\r\n"
                        "Connection: close\r\n\r\n",
                        (unsigned long)recovery_data.length);
                    http_write(client_fd, recovery_headers, recovery_hn);
                    http_write(client_fd, recovery_data.bytes,
                               (int)recovery_data.length);
                    fprintf(stderr,
                            "[serve] %s malformed tool call returned as HTTP 200 "
                            "finish_reason=stop for compatibility testing\n",
                            request_id);
                } else {
                    http_write_str(client_fd,
                        "HTTP/1.1 500 Internal Server Error\r\n"
                        "Content-Type: application/json\r\n"
                        "Connection: close\r\n\r\n"
                        "{\"error\":\"failed to serialize malformed-tool recovery response\"}\n");
                }
			} else {
				NSString *finish_reason = has_tool_calls ? @"tool_calls" :
                    (session_ended_with_eos ? @"stop" : @"length");
				NSMutableDictionary *message = [@{
					@"role": @"assistant",
					@"content": (has_tool_calls && content_text.length == 0)
                        ? (id)[NSNull null] : (content_text ?: @"")
				} mutableCopy];
				if (reasoning_text.length > 0)
					message[@"reasoning_content"] = reasoning_text;
                if (has_tool_calls)
                    message[@"tool_calls"] = parsed_tool_calls;
				NSMutableDictionary *response_obj = [@{
					@"id": [NSString stringWithUTF8String:request_id],
					@"object": @"chat.completion",
					@"model": @"qwen3.5",
					@"usage": completion_usage(logical_prompt_tokens, completion_tokens),
					@"flash_timings": flash_timings,
					@"choices": @[@{
						@"index": @0,
						@"message": message,
						@"finish_reason": finish_reason
					}]
				} mutableCopy];
                if (sanitized_tool_call) {
                    response_obj[@"session_invalidated"] = @YES;
                    response_obj[@"resend_full_history"] = @YES;
                }
				NSError *json_error = nil;
				NSData *json_data = [NSJSONSerialization dataWithJSONObject:response_obj options:0 error:&json_error];
				if (json_data) {
					char headers[512];
					int hn = snprintf(headers, sizeof(headers),
						"HTTP/1.1 200 OK\r\n"
						"Content-Type: application/json; charset=utf-8\r\n"
						"Content-Length: %lu\r\n"
						"Access-Control-Allow-Origin: *\r\n"
						"Connection: close\r\n\r\n",
						(unsigned long)json_data.length);
					if (http_write(client_fd, headers, hn) < 0 ||
						http_write(client_fd, json_data.bytes, (int)json_data.length) < 0) {
						fprintf(stderr, "[serve] %s final HTTP delivery failed, invalidating session\n",
							request_id);
						request_state_failed = 1;
						session_reusable = 0;
					}
				} else {
					fprintf(stderr, "[serve] %s JSON serialization failed: %s\n",
						request_id, json_error.localizedDescription.UTF8String);
					http_write_str(client_fd,
						"HTTP/1.1 500 Internal Server Error\r\n"
						"Content-Type: application/json\r\n"
						"Connection: close\r\n\r\n"
						"{\"error\":\"response serialization failed\"}\n");
				}
			}

			// ---- Save session state ----
			if (request_state_failed || !session_reusable) {
				active_session_id[0] = '\0';
                active_session_profile = nil;
                active_session_tool_sig = 0;
                active_session_tool_sig_valid = 0;
                [active_session_pending_tool_ids removeAllObjects];
				session_pos = 0;
				session_ended_with_eos = 0;
			} else {
				session_pos = pos;
			}
			fprintf(stderr, "[serve] %s session_pos=%d (session=%s)\n",
					request_id, session_pos,
					active_session_id[0] ? active_session_id : "(none)");

			fprintf(stderr, "[serve] %s generated=%d tokens in %.0fms (%.2f tok/s)\n",
					request_id, completion_tokens, decode_ms, decode_tps);
			if (g_expert_cache) {
				cache_telemetry_print(g_expert_cache->hits, g_expert_cache->misses);
			} else if (g_malloc_cache) {
				cache_telemetry_print(g_malloc_cache->hits, g_malloc_cache->misses);
			}

			free(pt->ids);
			free(pt);
			free(reqbuf);
			close(client_fd);
			continue;
		}

		// Unknown endpoint
		const char *resp404 =
			"HTTP/1.1 404 Not Found\r\n"
			"Content-Type: application/json\r\n"
			"Access-Control-Allow-Origin: *\r\n"
			"Connection: close\r\n"
			"\r\n"
			"{\"error\":\"not found\"}\n";
		http_write_str(client_fd, resp404);
		free(reqbuf);
		close(client_fd);
	}
}

