static void print_usage(const char *prog) {
	printf("Usage: %s [options]\n", prog);
	printf("  --model PATH         Model path (required; Qwen3.5-35B-A3B)\n");
	printf("  --bench-target-verifier  Isolated serial candidate-verification timing (no batch kernel)\n");
	printf("  --bench-target-verifier-batched  Isolated multi-position LM-head prototype\n");
	printf("  --bench-target-verifier-layer-major  Isolated causal block experiment (N=4 first)\n");
#ifdef FLASH_PREFILL_NROW_PRODUCTION
	printf("  --prefill-nrow       Enable production N-row prompt prefill (N=%d default; scalar remainder fallback)\n", PREFILL_NROW_CAPTURE_ROWS);
	printf("  --no-prefill-nrow    Disable N-row prompt prefill and use scalar prefill\n");
#endif
#ifdef FLASH_PREFILL_NROW_BENCH
	printf("  --bench-prefill-nrow-control  Benchmark-only 16-row full-model control\n");
	printf("  --bench-prefill-nrow-grouped  Benchmark-only 16-row grouped-MoE path\n");
	printf("  --bench-prefill-nrow-1k  Benchmark-only full-model 1008-token comparison\n");
#endif
	printf("  --weights PATH       model_weights.bin path\n");
	printf("  --manifest PATH      model_weights.json path\n");
	printf("  --gguf-lm-head PATH  Optional raw Q6_K LM head blob copied from GGUF\n");
	printf("  --gguf-full-attn-bin PATH  Optional raw Q8_0 full-attention q/k/v/o overlay blob\n");
	printf("  --gguf-full-attn-json PATH Optional full-attention overlay manifest JSON\n");
	printf("  --gguf-qkv-bin PATH  Optional raw Q8_0 qkv family blob copied from GGUF\n");
	printf("  --gguf-qkv-json PATH Optional qkv family manifest JSON\n");
	printf("  --gguf-linear-bin PATH Optional raw Q8_0 linear gate/out overlay blob\n");
	printf("  --gguf-linear-json PATH Optional linear gate/out overlay manifest JSON\n");
	printf("  --gguf-shared-bin PATH Optional raw Q8_0 shared-expert overlay blob\n");
	printf("  --gguf-shared-json PATH Optional shared-expert overlay manifest JSON\n");
	printf("  --vocab PATH         vocab.bin path\n");
	printf("  --prompt-tokens PATH prompt_tokens.bin path\n");
	printf("  --prompt TEXT         Prompt text (requires encode_prompt.py)\n");
	printf("  --tokens N           Max tokens to generate (default: 20)\n");
	printf("  --k N                Active experts per layer (default: model-native K=8)\n");
	printf("  --cache-entries N    Expert LRU cache size (default: 2500, 0 = disabled)\n");
	printf("  --malloc-cache N     Malloc expert cache entries (hot 4-bit only in tiered mode)\n");
	printf("  --malloc-lru MODE    Malloc-cache eviction: auto|scan|list|clock (default: auto)\n");
	printf("  --tiered-cold-nocache Read tiered cold 2-bit experts without OS caching\n");
	printf("  --cpu-linear         Disable fused GPU delta-net and use the older CPU/hybrid linear path\n");
	printf("  --timing             Enable per-layer timing breakdown\n");
	printf("  --freq               Enable expert frequency tracking + analysis\n");
	printf("  --cache-telemetry    Report cold vs eviction misses and reuse distance\n");
	printf("  --cache-io-split N   Experimental: split each routed expert pread into N page-aligned chunks\n");
	printf("  --2bit               Use 2-bit quantized experts (packed_experts_2bit/)\n");
	printf("  --q3-experts         Use hybrid Q3 streamed experts (packed_experts_Q3/)\n");
	printf("  --gpu-linear         Alias for the fused GPU delta-net path (default)\n");
	printf("  --predict            Enable legacy temporal expert prediction (incompatible with CMD12 chaining)\n");
	printf("  --expert-prefetch    Confidence-gated temporal expert prefetch (default on)\n");
	printf("  --expert-prefetch-history N   Route-history depth (default 4, max 8)\n");
	printf("  --expert-prefetch-min-hits N  Minimum appearances in history (default 4)\n");
	printf("  --expert-prefetch-max N       Maximum experts prefetched per layer (default 2)\n");
	printf("  --no-pipeline-profile         Disable pipeline profiling\n");
	printf("  --no-malloc-cache             Disable default 512-entry malloc expert cache\n");
	printf("  --no-gpu-resident-moe         Disable default GPU-resident MoE path\n");
	printf("  --no-oproj-v3                 Disable default o_proj V3 path\n");
	printf("  --no-tiny-matvec-fast         Disable default tiny matvec fast path\n");
	printf("  --no-cmd12-chain              Disable default linear CMD1->CMD2 chaining\n");
	printf("  --no-cmd12-full-chain         Disable default full-attention CMD1->CMD2 chaining\n");
	printf("  --no-expert-prefetch          Disable default expert prefetch\n");
	printf("  --cmd3-io-gate                Gate CMD3 behind async malloc-cache expert I/O (default on)\n");
	printf("  --no-cmd3-io-gate             Disable CMD3/I-O overlap experiment\n");
	printf("  --collect-routing F  Log routing data to binary file F (for predictor training)\n");
	printf("  --think-budget N     Override automatic thinking budget (0=unlimited)\n");
	printf("  --temperature F      Sampling temperature (default: 0 = greedy)\n");
	printf("  --top-p F            Nucleus sampling probability (default: 0.95)\n");
	printf("  --top-k N            Sample from top N tokens (default: 20, max: 256)\n");
	printf("  --seed N             Sampling RNG seed (default: 42)\n");
	printf("  --ppl PATH           Measure perplexity on ground truth token file\n");
	printf("  --stream             Clean streaming output (no progress, no stats)\n");
	printf("  --gguf-embedding P   Use extracted GGUF Q8_0 embedding blob\n");
	printf("  --nax                Enable NAX tensor matmul for LM head (M5+, slower for single-token)\n");
	printf("  --no-nax             Disable NAX (default)\n");
	printf("  --gpu-argmax         Use GPU argmax for greedy LM-head decoding\n");
	printf("  --gpu-resident-moe   Keep fused CMD2/CMD3 MoE handoff buffers on GPU\n");
	printf("  --oproj-v3           Use matvec_v3 for eligible CMD2 o_proj layers\n");
	printf("  --tiny-matvec-fast   Use matvec_fast for MLX4 32x2048 and 1x2048 projections\n");
	printf("  --tiny-matvec-telemetry  Count tiny production dispatches and run post-generation replay A/B\n");
	printf("  --cmd1-profile       Capture real decode CMD1 projection families and replay/profile after generation\n");
	printf("  --cmd12-chain        Experimental: queue GPU-linear CMD2 directly behind CMD1\n");
	printf("  --cmd12-full-chain   Experimental: GPU-prepare full attention and chain CMD1 -> CMD2\n");
	printf("  --pipeline-profile   Decode-only GPU/I/O timeline profiling (default off)\n");
	printf("  --matvec-bench       Benchmark dense MLX4 matvec kernels and exit\n");
	printf("  --matvec-bench-iters N  Measured V3/fast block pairs (default: 100)\n");
	printf("  --serve PORT         Run HTTP server (OpenAI-compatible API)\n");
printf("  --warm-tools PATH    Pre-cache tools JSON at startup; object may include system_prompt\n");
printf("  --flash-profile NAME  Restore or capture a named warm profile (warm-tools-cache/flash-NAME-warm.json)\n");
printf("  --flash-profile-recapture NAME  Replace that profile source from its next matching request\n");
printf("  --warm-state-compression raw|zstd  Checkpoint storage (default: Zstd-1; raw for debugging)\n");
printf("                       DSH profiles use NAME=dsh-<preset>\n");
printf("  --agent-stack NAME   Restore/build named agent warm state from warm-tools-cache/agent-stack-NAME-warm.json\n");
printf("  --sort-tools-alpha   Sort tools alphabetically by function name before rendering/caching\n");
printf("  --no-sort-tools-alpha  Preserve client tool order (default)\n");
printf("  --malformed-tool-recovery  Return assistant recovery content for malformed model tool calls (default)\n");
printf("  --strict-malformed-tool-errors  Return provider errors for malformed model tool calls\n");
printf("  --tool-retry-guard  Stop repeated identical failed tool calls (default for dsh-* profiles)\n");
printf("  --no-tool-retry-guard  Disable the retry guard, including with dsh-* profiles\n");
printf("  --self-test-tools    Run tool/schema validation self-tests and exit\n");
printf("  --self-test-warm-state DIR  Run only synthetic checkpoint tests in a new directory\n");
printf("  --self-test-api      Run isolated usage, Write, and cache-budget checks\n");
printf("  --validate-model-layout  Validate native model manifest and exit before Metal setup\n");
printf("  --self-test-profiles DIR  Run model-free named-profile source tests in DIR\n");
printf("  --tool-prefix-cache-mb N  Dynamic tool-prefix RAM budget in MiB (default: 768; pinned warm state excluded)\n");
	printf("  --help               This message\n");
}

