			{"flash-profile-recapture", required_argument, 0, 1234},
			{"warm-state-compression", required_argument, 0, 1236},
			{"agent-stack", required_argument,         0, 1227},
			{"sort-tools-alpha", no_argument,            0, 1222},
			{"no-sort-tools-alpha", no_argument,         0, 1223},
			{"malformed-tool-recovery", no_argument,      0, 1224},
			{"strict-malformed-tool-errors", no_argument, 0, 1225},
			{"tool-retry-guard", no_argument, 0, 1231},
			{"no-tool-retry-guard", no_argument, 0, 1232},
			{"help",          no_argument,       0, 'h'},
			{0, 0, 0, 0}
		};

		int c;
		while ((c = getopt_long(argc, argv, "m:w:j:I:A:N:J:K:U:V:Y:H:i:v:p:P:t:k:C:M:R:B:LSTFEW:23Gh", long_options, NULL)) != -1) {
			switch (c) {
				case 'm': model_path = optarg; break;
				case 'w': weights_path = optarg; break;
				case 'j': manifest_path = optarg; break;
				case 'I': gguf_embedding_path = optarg; break;
				case 'A': gguf_full_attn_bin_path = optarg; break;
				case 'N': gguf_full_attn_json_path = optarg; break;
				case 'J': gguf_qkv_bin_path = optarg; break;
				case 'K': gguf_qkv_json_path = optarg; break;
				case 'U': gguf_linear_bin_path = optarg; break;
				case 'V': gguf_linear_json_path = optarg; break;
				case 'Y': gguf_lm_head_path = optarg; break;
				case 'H': gguf_shared_bin_path = optarg; break;
				case 'i': gguf_shared_json_path = optarg; break;
				case 'v': vocab_path = optarg; break;
				case 'p': prompt_tokens_path = optarg; break;
				case 'P': prompt_text = optarg; break;
				case 't': max_tokens = atoi(optarg); break;
				case 'k':
					K = atoi(optarg);
					k_explicitly_set = 1;
					break;
				case 'C': cache_entries = atoi(optarg); cache_entries_explicit = 1; break;
				case 'M': malloc_cache_entries = atoi(optarg); malloc_cache_explicit = 1; break;
				case 1100:
					if (!strcmp(optarg, "auto")) malloc_lru_policy = -1;
					else if (!strcmp(optarg, "scan")) malloc_lru_policy = 0;
					else if (!strcmp(optarg, "list")) malloc_lru_policy = 1;
					else if (!strcmp(optarg, "clock")) malloc_lru_policy = 2;
					else { fprintf(stderr, "ERROR: --malloc-lru must be auto, scan, list, or clock\n"); return 1; }
					break;
				case 'L': gpu_linear_attn_enabled = 0; break;
				case 'S': linear_attn_bypass = 1; break;
				case 'T': g_timing_enabled = 1; break;
				case 'F': g_freq_tracking = 1; break;
				case 'E': g_cache_telemetry_enabled = 1; break;
				case 'W': g_cache_io_split = atoi(optarg); break;
				case '2': g_use_2bit = 1; break;
				case '4': g_use_tiered = 1; break;
				case '5': g_tiered_cold_nocache = 1; break;
				case '3': g_use_q3_experts = 1; break;
				case 'G': gpu_linear_attn_enabled = 1; break;
				case 'D': g_pred_enabled = 1; predict_explicit = 1; break;
				case 'Z':
					g_routing_log = fopen(optarg, "wb");
					if (!g_routing_log) {
						fprintf(stderr, "ERROR: cannot open routing log: %s\n", optarg);
						return 1;
					}
					break;

				case 'B':
					g_think_budget = atoi(optarg);
					break;

				case OPT_TEMPERATURE:
					g_temperature = strtof(optarg, NULL);
					break;

				case OPT_TOP_P:
					g_top_p = strtof(optarg, NULL);
					break;

				case OPT_TOP_K:
					g_top_k = atoi(optarg);
					break;

				case OPT_SEED:
					g_seed = (unsigned int)strtoul(optarg, NULL, 10);
					break;

				case 'R':
					serve_port = atoi(optarg);
					break;
				case 'Q': ppl_tokens_path = optarg; break;
				case 'O': g_stream_mode = 1; break;
				case 'X': g_nax_disabled = 0; break;  // --nax: enable
				case 'x': g_nax_disabled = 1; break;  // --no-nax: disable
				case 1101: g_gpu_argmax_enabled = 1; break;
				case 1102: g_gpu_resident_moe_enabled = 1; break;
				case 1103: g_oproj_v3_enabled = 1; break;
				case 1104: matvec_bench = 1; break;
				case 1105: matvec_bench_iters = atoi(optarg); break;
				case 1200: g_tiny_matvec_fast_enabled = 1; break;
				case 1201: g_tiny_matvec_telemetry_enabled = 1; break;
				case 1202: g_cmd1_profile_enabled = 1; break;
				case 1203: g_cmd12_chain_enabled = 1; break;
				case 1204: g_cmd12_full_chain_enabled = 1; break;
				case 1205: g_pipeline_profile_enabled = 1; break;
				case 1206: g_expert_prefetch_enabled = 1; expert_prefetch_explicit = 1; break;
				case 1207: g_expert_prefetch_history = atoi(optarg); break;
				case 1208: g_expert_prefetch_min_hits = atoi(optarg); break;
				case 1209: g_expert_prefetch_max = atoi(optarg); break;
				case 1210: g_pipeline_profile_enabled = 0; break;
				case 1211: malloc_cache_entries = 0; malloc_cache_explicit = 1; break;
				case 1212: g_gpu_resident_moe_enabled = 0; break;
				case 1213: g_oproj_v3_enabled = 0; break;
				case 1214: g_tiny_matvec_fast_enabled = 0; break;
				case 1215: g_cmd12_chain_enabled = 0; break;
				case 1216: g_cmd12_full_chain_enabled = 0; break;
				case 1217: g_expert_prefetch_enabled = 0; expert_prefetch_explicit = 1; break;
				case 1218: g_cmd3_io_gate_enabled = 1; break;
				case 1219: g_cmd3_io_gate_enabled = 0; break;
				case 1220: self_test_tools = 1; break;
				case 1228: self_test_warm_state_dir = optarg; break;
				case 1230: self_test_api = 1; break;
                case 1235: self_test_profiles_dir = optarg; break;
				case 1237: target_verify_bench = 1; break;
				case 1238: target_verify_bench = 1; target_verify_batched = 1; break;
				case 1240: validate_model_layout_only = 1; break;
				case 1239: target_verify_bench = 1; target_verify_batched = 2; break;
#ifdef FLASH_PREFILL_NROW_BENCH
				case 1241: prefill_nrow_control = 1; break;
				case 1242: prefill_nrow_grouped = 1; break;
				case 1243: prefill_nrow_1k = 1; break;
#endif
#ifdef FLASH_PREFILL_NROW_PRODUCTION
				case 1244: g_prefill_nrow_runtime_enabled = 1; break;
				case 1245: g_prefill_nrow_runtime_enabled = 0; break;
#endif
			case 1236:
				if (strcmp(optarg, "zstd") != 0 && strcmp(optarg, "raw") != 0) {
					fprintf(stderr, "ERROR: --warm-state-compression must be raw or zstd\n");
					return 1;
				}
				g_warm_state_zstd_enabled = strcmp(optarg, "zstd") == 0;
				break;
				case 1229: {
					char *end = NULL;
					errno = 0;
					unsigned long long mb = strtoull(optarg, &end, 10);
					if (errno || !optarg[0] || !end || *end || mb > 8192) {
						fprintf(stderr, "ERROR: --tool-prefix-cache-mb must be 0..8192\n");
						return 1;
					}
					g_tool_prefix_cache_budget_bytes = (size_t)mb * 1024 * 1024;
					break;
				}
				case 1221: warm_tools_path = optarg; break;
				case 1233:
					if (warm_profile_kind && strcmp(warm_profile_kind, "flash") != 0) {
						fprintf(stderr, "ERROR: select only one startup profile\n");
						return 1;
					}
					warm_profile = optarg;
					warm_profile_kind = "flash";
					break;
				case 1234:
					recapture_profile = optarg;
					break;
				case 1227:
					if (warm_profile_kind && strcmp(warm_profile_kind, "agent-stack") != 0) {
						fprintf(stderr, "ERROR: select only one startup profile\n");
						return 1;
					}
					warm_profile = optarg;
					warm_profile_kind = "agent-stack";
					break;
				case 1222: g_sort_tools_alpha_enabled = 1; break;
				case 1223: g_sort_tools_alpha_enabled = 0; break;
				case 1224: g_malformed_tool_recovery_enabled = 1; malformed_recovery_explicit = 1; break;
				case 1225: g_malformed_tool_recovery_enabled = 0; malformed_recovery_explicit = 1; break;
				case 1231: g_tool_retry_guard_enabled = 1; g_tool_retry_guard_explicit = 1; break;
				case 1232: g_tool_retry_guard_enabled = 0; g_tool_retry_guard_explicit = 1; break;
				case 'h': print_usage(argv[0]); return 0;
				default:  print_usage(argv[0]); return 1;
			}
		}
		g_malformed_tool_recovery_enabled = malformed_recovery_for_profile(
            warm_profile_kind, malformed_recovery_explicit,
            g_malformed_tool_recovery_enabled);

		if (self_test_tools) {
			g_model_path_for_tokenizer = model_path;
			return run_tool_schema_self_tests();
		}
		if (self_test_api)
			return run_api_regression_self_tests() |
				run_native_tensor_layout_self_tests() |
				run_manifest_lookup_self_tests() |
				run_model_json_container_self_tests() |
				run_gguf_json_self_tests() |
				run_tiered_json_self_tests();
		if (self_test_profiles_dir)
            return flash_profile_self_test(self_test_profiles_dir, model_path);
		// This path exits before model setup; it only exercises checkpoint I/O.
		if (self_test_warm_state_dir)
			return warm_state_self_test(self_test_warm_state_dir);
		NSString *resolved_warm_path = nil;
		NSString *profile_id = nil;
		if (recapture_profile) {
            NSString *recapture_name = [NSString stringWithUTF8String:recapture_profile];
            if (!flash_profile_name_valid(recapture_name) ||
                (warm_profile && strcmp(warm_profile, recapture_profile) != 0) ||
                (warm_profile_kind && strcmp(warm_profile_kind, "flash") != 0)) {
                fprintf(stderr, "ERROR: --flash-profile-recapture requires a valid Flash profile name matching --flash-profile if supplied\n");
                return 1;
            }
            warm_profile = recapture_profile;
            warm_profile_kind = "flash";
        }
		if (warm_profile) {
			if (gguf_full_attn_json_path || gguf_qkv_json_path ||
			    gguf_linear_json_path || gguf_shared_json_path) {
				fprintf(stderr, "ERROR: named warm state does not support custom GGUF JSON overrides yet\n");
				return 1;
			}
			if (warm_tools_path || serve_port <= 0 || !*warm_profile) {
				fprintf(stderr, "ERROR: named warm profiles require --serve and cannot be combined with --warm-tools\n");
				return 1;
			}
			if (!flash_profile_name_valid([NSString stringWithUTF8String:warm_profile])) {
				fprintf(stderr, "ERROR: profile names must use 1..64 lowercase ASCII letters, digits, '-' or '_'\n");
				return 1;
			}
			NSString *cache_dir = project_tool_set_cache_directory();
			if (!cache_dir) {
				fprintf(stderr, "ERROR: cannot resolve project directory for named warm profile\n");
				return 1;
			}
			profile_id = [NSString stringWithFormat:@"%s/%s", warm_profile_kind, warm_profile];
            if (strcmp(warm_profile_kind, "agent-stack") == 0) {
                resolved_warm_path = [cache_dir stringByAppendingPathComponent:
                    [NSString stringWithFormat:@"agent-stack-%s-warm.json", warm_profile]];
            } else if (!recapture_profile) {
                resolved_warm_path = flash_profile_source_path(cache_dir,
                    [NSString stringWithUTF8String:warm_profile]);
                if (strncmp(warm_profile, "dsh-", 4) == 0)
                    profile_id = [NSString stringWithFormat:@"dsh/%s", warm_profile + 4];
                else profile_id = [NSString stringWithFormat:@"flash/%s", warm_profile];
            } else {
                resolved_warm_path = flash_profile_source_path(cache_dir,
                    [NSString stringWithUTF8String:warm_profile]);
                if (strncmp(warm_profile, "dsh-", 4) == 0)
                    profile_id = [NSString stringWithFormat:@"dsh/%s", warm_profile + 4];
            }
			if (!recapture_profile && access(resolved_warm_path.fileSystemRepresentation, R_OK) == 0)
                warm_tools_path = resolved_warm_path.fileSystemRepresentation;
            else if (strcmp(warm_profile_kind, "agent-stack") == 0) {
				fprintf(stderr, "ERROR: profile source not found: %s\n", resolved_warm_path.fileSystemRepresentation);
				return 1;
			}
		}

        // Auto-detected LZ4 must not conflict with built-in defaults. Explicit
        // incompatible user requests still fail below.
        int early_lz4_storage_candidate = 0;
        if (model_path && *model_path && !g_use_2bit && !g_use_q3_experts && !g_use_tiered) {
            char early_lz4_probe[1024];
            snprintf(early_lz4_probe, sizeof(early_lz4_probe),
                     "%s/packed_experts_lz4/layer_00.bin", model_path);
            early_lz4_storage_candidate = (access(early_lz4_probe, R_OK) == 0);
        }
        if (early_lz4_storage_candidate) {
            // Explicit incompatible requests are rejected immediately, before
            // unrelated validation or model-weight checks can mask the real cause.
            if ((cache_entries > 0 && cache_entries_explicit) ||
                (malloc_cache_entries > 0 && malloc_cache_explicit) ||
                (g_pred_enabled && predict_explicit) ||
                (g_expert_prefetch_enabled && expert_prefetch_explicit)) {
                fprintf(stderr,
                        "ERROR: LZ4 expert storage is incompatible with explicitly enabled "
                        "--cache-entries, --malloc-cache, --predict, or --expert-prefetch\n");
                return 1;
            }

            // Built-in defaults may be safely adjusted for LZ4.
            if (malloc_cache_entries > 0 && !malloc_cache_explicit) {
                fprintf(stderr, "[lz4] auto-disabling default malloc cache (%d entries)\n",
                        malloc_cache_entries);
                malloc_cache_entries = 0;
            }
            if (g_expert_prefetch_enabled && !expert_prefetch_explicit) {
                fprintf(stderr, "[lz4] auto-disabling default expert prefetch\n");
                g_expert_prefetch_enabled = 0;
            }
        }

		if (!g_stream_mode) {
			printf("[defaults] profile=%s malloc-cache=%d lru=%s gpu-moe=%s oproj-v3=%s "
				   "tiny-fast=%s cmd12=%s full-cmd12=%s prefetch=%s (%d/%d/%d) cmd3-io-gate=%s\n",
				   g_pipeline_profile_enabled ? "on" : "off",
				   malloc_cache_entries,
				   malloc_lru_policy == -1 ? "auto" :
				   (malloc_lru_policy == 0 ? "scan" :
				   (malloc_lru_policy == 1 ? "list" : "clock")),
				   g_gpu_resident_moe_enabled ? "on" : "off",
				   g_oproj_v3_enabled ? "on" : "off",
				   g_tiny_matvec_fast_enabled ? "on" : "off",
				   g_cmd12_chain_enabled ? "on" : "off",
				   g_cmd12_full_chain_enabled ? "on" : "off",
				   g_expert_prefetch_enabled ? "on" : "off",
				   g_expert_prefetch_history,
				   g_expert_prefetch_min_hits,
				   g_expert_prefetch_max,
				   g_cmd3_io_gate_enabled ? "on" : "off");
		}
		if (g_tiny_matvec_fast_enabled) {
			printf("[tiny-matvec-fast] enabled — MLX4 32x2048 and 1x2048 use matvec_fast\n");
		}
		if (g_tiny_matvec_telemetry_enabled) {
			printf("[tiny-matvec-telemetry] enabled — production counts + post-generation replay A/B\n");
		}
		if (g_cmd1_profile_enabled) {
			printf("[cmd1-profile] enabled — decode-only production capture + post-generation replay\n");
		}
		if (g_cmd12_chain_enabled) {
			printf("[cmd12-chain] enabled — GPU-linear CMD1 -> CMD2 chaining\n");
			if (g_cmd1_profile_enabled || g_tiny_matvec_telemetry_enabled ||
				g_pred_enabled || g_routing_log) {
				fprintf(stderr,
						"ERROR: --cmd12-chain is incompatible with --cmd1-profile, "
						"--tiny-matvec-telemetry, --predict, and --collect-routing "
						"with CMD1/CMD2 chaining enabled\n");
				return 1;
			}
			if (!g_gpu_resident_moe_enabled) {
				fprintf(stderr, "ERROR: --cmd12-chain requires --gpu-resident-moe\n");
				return 1;
			}
			if (!gpu_linear_attn_enabled) {
				fprintf(stderr, "ERROR: --cmd12-chain requires GPU linear attention\n");
				return 1;
			}
		}

		if (g_pipeline_profile_enabled) {
			printf("[pipeline-profile] enabled — decode GPU timeline + expert I/O task timing\n");
		}
		if (g_expert_prefetch_enabled) {
			if (g_expert_prefetch_history < 1 ||
				g_expert_prefetch_history > EXPERT_PREFETCH_HISTORY_MAX) {
				fprintf(stderr, "ERROR: --expert-prefetch-history must be 1..%d\n",
					EXPERT_PREFETCH_HISTORY_MAX);
				return 1;
			}
			if (g_expert_prefetch_min_hits < 1 ||
				g_expert_prefetch_min_hits > g_expert_prefetch_history) {
				fprintf(stderr,
					"ERROR: --expert-prefetch-min-hits must be 1..history (%d)\n",
					g_expert_prefetch_history);
				return 1;
			}
			if (g_expert_prefetch_max < 1 || g_expert_prefetch_max > MAX_K) {
				fprintf(stderr, "ERROR: --expert-prefetch-max must be 1..%d\n", MAX_K);
				return 1;
			}
			printf("[expert-prefetch] enabled — history=%d min-hits=%d max=%d\n",
				g_expert_prefetch_history, g_expert_prefetch_min_hits,
				g_expert_prefetch_max);
			if (g_pred_enabled) {
				fprintf(stderr, "ERROR: --expert-prefetch and legacy --predict cannot be enabled together\n");
				return 1;
			}
			if (malloc_cache_entries <= 0) {
				fprintf(stderr, "ERROR: --expert-prefetch currently requires --malloc-cache N\n");
				return 1;
			}
		}
		if (g_cmd12_full_chain_enabled) {
			printf("[cmd12-full] enabled — full-attention CMD1 -> CMD2 chaining\n");
			if (g_cmd1_profile_enabled || g_tiny_matvec_telemetry_enabled ||
				g_pred_enabled || g_routing_log) {
				fprintf(stderr,
						"ERROR: --cmd12-full-chain is incompatible with --cmd1-profile, "
						"--tiny-matvec-telemetry, --predict, and --collect-routing "
						"with CMD1/CMD2 chaining enabled\n");
				return 1;
			}
			if (!g_gpu_resident_moe_enabled) {
				fprintf(stderr, "ERROR: --cmd12-full-chain requires --gpu-resident-moe\n");
				return 1;
			}
		}

		if (g_temperature < 0.0f) {
			fprintf(stderr, "ERROR: --temperature must be >= 0\n");
			return 1;
		}

		if (g_top_p <= 0.0f || g_top_p > 1.0f) {
			fprintf(stderr, "ERROR: --top-p must be > 0 and <= 1\n");
			return 1;
		}

		if (g_top_k < 1 || g_top_k > 256) {
			fprintf(stderr, "ERROR: --top-k must be between 1 and 256\n");
			return 1;
		}
		if (matvec_bench_iters < 1) {
			fprintf(stderr, "ERROR: --matvec-bench-iters must be >= 1\n");
			return 1;
		}

		srand(g_seed);

		if (!model_path || !*model_path) {
			fprintf(stderr,
					"ERROR: --model PATH is required for this Qwen3.5-35B-A3B build.\n");
			return 1;
		}

if (g_use_tiered) {
    if (cache_entries > 0) {
        fprintf(stderr,
                "ERROR: --cache-entries is not yet tiered-safe\n");
        return 1;
    }

    if (g_pred_enabled) {
        fprintf(stderr,
                "ERROR: --predict is not yet tiered-safe\n");
        return 1;
    }
}


		if (g_use_2bit && g_use_q3_experts) {
			fprintf(stderr, "ERROR: --2bit and --q3-experts are mutually exclusive for now\n");
			return 1;
		}

		// Resolve default artifacts strictly inside the selected model directory.
		// Explicit --weights/--manifest/--vocab paths remain supported.
		char default_weights[1024], default_manifest[1024], default_vocab[1024];

		if (!weights_path) {
			snprintf(default_weights, sizeof(default_weights), "%s/model_weights.bin", model_path);
			weights_path = default_weights;
		}
		if (!manifest_path) {
			snprintf(default_manifest, sizeof(default_manifest), "%s/model_weights.json", model_path);
			manifest_path = default_manifest;
		}
		if (!vocab_path) {
			snprintf(default_vocab, sizeof(default_vocab), "%s/vocab.bin", model_path);
			vocab_path = default_vocab;
		}

		if (access(weights_path, R_OK) != 0) {
			fprintf(stderr, "ERROR: model weights not readable: %s\n", weights_path);
			return 1;
		}
		if (access(manifest_path, R_OK) != 0) {
			fprintf(stderr, "ERROR: model manifest not readable: %s\n", manifest_path);
			return 1;
		}
		if (access(vocab_path, R_OK) != 0) {
			fprintf(stderr, "ERROR: model vocabulary not readable: %s\n", vocab_path);
			return 1;
		}

		// Set model path for tokenizer lookup
		g_model_path_for_tokenizer = model_path;

		// ---- Load model config ----
		// This engine is intentionally target-locked; do not infer architecture
		// from fallback constants if the selected model package lacks config.json.
		char required_config_path[1024];
		snprintf(required_config_path, sizeof(required_config_path), "%s/config.json", model_path);
		if (access(required_config_path, R_OK) != 0) {
			fprintf(stderr, "ERROR: required model config not found: %s\n", required_config_path);
			return 1;
		}
		load_config_from_config_json(model_path);
		if (!g_config_loaded) return 1;
		if (manifest_path) load_config_from_manifest(manifest_path);

		if (!validate_target_architecture()) {
			return 1;
		}
		if (validate_model_layout_only) {
			WeightFile *layout_wf = open_weights(weights_path, manifest_path);
			int layout_ok = layout_wf && validate_native_tensor_layout(layout_wf);
			printf("[model-layout] %s\n", layout_ok ? "PASS" : "FAIL");
			return layout_ok ? 0 : 1;
		}

		// Validate the raw 4-bit layout before Metal/cache allocation. Never let
		// a stale/corrupt packed file redefine the expert stride by floor division.
		{
			char probe[1024];
			snprintf(probe, sizeof(probe), "%s/packed_experts/layer_00.bin", model_path);
			struct stat st;
			if (stat(probe, &st) == 0 && st.st_size > 0 && NUM_EXPERTS > 0) {
				uint64_t file_size = (uint64_t)st.st_size;
				if (file_size % (uint64_t)NUM_EXPERTS != 0) {
					fprintf(stderr,
							"[experts] ERROR: %s size %llu is not divisible by %d experts\n",
							probe, (unsigned long long)file_size, NUM_EXPERTS);
					return 1;
				}
				size_t detected = (size_t)(file_size / (uint64_t)NUM_EXPERTS);
				if (detected != g_cfg.expert_size_computed) {
					fprintf(stderr,
							"[experts] ERROR: %s expert stride %zu != configured layout %zu; refusing stale/corrupt packed file\n",
							probe, detected, g_cfg.expert_size_computed);
					return 1;
				}
				if (!g_stream_mode)
					printf("[experts] Expert size: %zu bytes (%.2f MB)\n",
						   g_cfg.expert_size_computed, g_cfg.expert_size_computed / 1e6);
			}
		}


		if (!k_explicitly_set) {
			K = g_cfg.num_experts_per_tok;
		}

		if (K < 1 || K > MAX_K || K > g_cfg.num_experts) {
			fprintf(stderr,
					"ERROR: invalid expert K=%d "
					"(model-native K=%d, MAX_K=%d, experts=%d)\n",
					K, g_cfg.num_experts_per_tok, MAX_K, g_cfg.num_experts);
			return 1;
		}

		if (K != g_cfg.num_experts_per_tok) {
			fprintf(stderr,
					"WARNING: --k %d differs from model-native K=%d; "
					"inference will be approximate.\n",
					K, g_cfg.num_experts_per_tok);
		}

		// Resolve expert format before cache sizing/compatibility checks.
		if (!resolve_expert_storage_mode(model_path)) return 1;

		int lz4_storage_candidate = 0;
		if (!g_use_2bit && !g_use_q3_experts && !g_use_tiered) {
			char lz4_probe[1024];
			snprintf(lz4_probe, sizeof(lz4_probe),
					 "%s/packed_experts_lz4/layer_00.bin", model_path);
			lz4_storage_candidate = (access(lz4_probe, R_OK) == 0);
		}

		if (lz4_storage_candidate) {
            BOOL explicit_conflict =
                (cache_entries > 0 && cache_entries_explicit) ||
                (malloc_cache_entries > 0 && malloc_cache_explicit) ||
                (g_pred_enabled && predict_explicit) ||
                (g_expert_prefetch_enabled && expert_prefetch_explicit);

            if (explicit_conflict ||
                cache_entries > 0 || malloc_cache_entries > 0 ||
                g_pred_enabled || g_expert_prefetch_enabled) {
                fprintf(stderr,
                        "ERROR: LZ4 expert storage is incompatible with explicitly enabled "
                        "--cache-entries, --malloc-cache, --predict, or --expert-prefetch\n");
                return 1;
            }
		}

		if (g_use_tiered) {
			if (cache_entries > 0) {
				fprintf(stderr, "ERROR: --cache-entries is not yet tiered-safe\n");
				return 1;
			}
			if (g_pred_enabled) {
				fprintf(stderr, "ERROR: --predict is not yet tiered-safe\n");
				return 1;
			}
		}

		// ---- Initialize Metal ----
		g_metal = metal_setup();
		if (!g_metal) {
			if (g_gpu_resident_moe_enabled || g_cmd12_chain_enabled || g_cmd12_full_chain_enabled ||
				g_use_tiered || lz4_storage_candidate) {
				fprintf(stderr,
						"ERROR: Metal initialization failed but the selected mode/storage format requires Metal\n");
				return 1;
			}
			fprintf(stderr, "WARNING: Metal init failed, falling back to CPU\n");
		}

		// ---- Initialize persistent I/O thread pool ----
		if (!io_pool_init()) {
			fprintf(stderr, "ERROR: persistent I/O thread pool initialization failed\n");
			return 1;
		}

		// ---- Initialize malloc expert cache (if requested) ----
		if (malloc_cache_entries > 0) {
			g_malloc_cache = malloc_cache_init(
				malloc_cache_entries,
				g_metal ? g_metal->device : MTLCreateSystemDefaultDevice(),
				malloc_lru_policy);
			if (!g_malloc_cache) {
				fprintf(stderr, "ERROR: requested malloc expert cache could not be initialized\n");
				io_pool_shutdown();
				return 1;
			}
			cache_entries = 0;  // disable Metal LRU cache when malloc cache is active
		}

		// ---- Initialize expert LRU cache ----
		if (cache_entries > 0 && g_metal) {
			g_expert_cache = expert_cache_new(g_metal->device, cache_entries);
			if (!g_expert_cache) {
				fprintf(stderr, "ERROR: requested Metal expert cache could not be initialized\n");
				io_pool_shutdown();
				return 1;
			}
		}

		if (!g_stream_mode) {
			printf("=== Qwen3.5 Metal Inference Engine ===\n");
			printf("hidden=%d layers=%d experts=%d K=%d\n",
				   g_cfg.hidden_dim, g_cfg.num_layers, g_cfg.num_experts, K);
			printf("Model:    %s\n", model_path);
			printf("Weights:  %s\n", weights_path);
			printf("Manifest: %s\n", manifest_path);
			if (gguf_embedding_path) {
				printf("Embedding:%s\n", gguf_embedding_path);
			}
			if (gguf_full_attn_bin_path) {
				printf("FullAttn: %s\n", gguf_full_attn_bin_path);
			}
			if (gguf_qkv_bin_path) {
				printf("QKV:      %s\n", gguf_qkv_bin_path);
			}
			if (gguf_linear_bin_path) {
				printf("LinearOv: %s\n", gguf_linear_bin_path);
			}
			if (gguf_lm_head_path) {
				printf("LM Head:  %s\n", gguf_lm_head_path);
			}
			if (gguf_shared_bin_path) {
				printf("SharedOv: %s\n", gguf_shared_bin_path);
			}
			printf("Vocab:    %s\n", vocab_path);
			printf("K:        %d experts/layer\n", K);
			if (g_use_q3_experts) {
				printf("Quant:    %s experts (59 GGUF IQ3/IQ4 layers + 1 GGUF outlier layer)\n",
					   requested_expert_quant_label());
			} else {
				printf("Quant:    %s experts (%zu bytes each)\n",
					   requested_expert_quant_label(), active_expert_size());
			}
			printf("Linear:   %s\n", linear_attn_bypass ? "bypassed" :
				gpu_linear_state_requested() ? "fused GPU delta-net" : "CPU/hybrid fallback");
			printf("Tokens:   %d\n", max_tokens);
if (g_temperature <= 0.0f) {
    printf("Sampling: greedy\n");
} else {
    printf("Sampling: temp=%.2f, top_p=%.2f, top_k=%d, seed=%u\n",
           g_temperature, g_top_p, g_top_k, g_seed);
}
			if (g_malloc_cache) {
				printf("Cache:    malloc %d entries (%.1f GB)\n",
					   malloc_cache_entries, (double)malloc_cache_entries * max_expert_size_for_current_config() / 1e9);
			} else {
				printf("Cache:    %d entries%s\n", cache_entries,
					   cache_entries > 0 ? "" : " (disabled)");
			}
		}

		double t0 = now_ms();

		// ---- Load weights ----
		WeightFile *wf = open_weights(weights_path, manifest_path);
		if (!wf) {
			fprintf(stderr, "ERROR: Failed to load weights\n");
			return 1;
		}

		if (gguf_embedding_path && !attach_gguf_embedding(wf, gguf_embedding_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF embedding\n");
			return 1;
		}

		if (gguf_full_attn_bin_path &&
			!attach_gguf_full_attn_overlay(wf, gguf_full_attn_bin_path, gguf_full_attn_json_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF full-attn overlay\n");
			return 1;
		}

		if (gguf_qkv_bin_path && !attach_gguf_qkv_overlay(wf, gguf_qkv_bin_path, gguf_qkv_json_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF qkv overlay\n");
			return 1;
		}

		if (gguf_linear_bin_path && !attach_gguf_linear_overlay(wf, gguf_linear_bin_path, gguf_linear_json_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF linear overlay\n");
			return 1;
		}

		if (gguf_lm_head_path && !attach_gguf_lm_head(wf, gguf_lm_head_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF LM head\n");
			return 1;
		}
		if (gguf_shared_bin_path &&
			!attach_gguf_shared_overlay(wf, gguf_shared_bin_path, gguf_shared_json_path)) {
			fprintf(stderr, "ERROR: Failed to attach GGUF shared overlay\n");
			return 1;
		}
		if (!validate_native_tensor_layout(wf)) {
			fprintf(stderr, "ERROR: model tensor layout is incompatible with this target\n");
			return 1;
		}

		if (!validate_required_model_tensors(wf)) {
			fprintf(stderr, "ERROR: selected model package is missing required inference tensors\n");
			return 1;
		}

		// Wrap weight file for Metal GPU access
		if (g_metal) {
			metal_set_weights(g_metal, wf->data, wf->size);
			if (wf->gguf_full_attn_data) {
				metal_set_gguf_full_attn(g_metal, wf->gguf_full_attn_data, wf->gguf_full_attn_size);
			}
			if (wf->gguf_qkv_data) {
				metal_set_gguf_qkv(g_metal, wf->gguf_qkv_data, wf->gguf_qkv_size);
			}
			if (wf->gguf_linear_data) {
				metal_set_gguf_linear(g_metal, wf->gguf_linear_data, wf->gguf_linear_size);
			}
			if (wf->gguf_lm_head_data) {
				metal_set_gguf_lm_head(g_metal, wf->gguf_lm_head_data, wf->gguf_lm_head_size);
			}
			if (wf->gguf_shared_data) {
				metal_set_gguf_shared(g_metal, wf->gguf_shared_data, wf->gguf_shared_size);
			}
		}

		if (matvec_bench) {
			if (!layer_cache_built) build_layer_cache(wf);
			return run_matvec_benchmark(wf, g_metal, matvec_bench_iters);
		}

		// ---- Load vocabulary ----
		Vocabulary *vocab = load_vocab(vocab_path);
		if (!vocab) {
			fprintf(stderr, "ERROR: Failed to load vocabulary\n");
			return 1;
		}

		// ---- Get prompt tokens (skip in serve mode) ----
		PromptTokens *pt = NULL;
		if (serve_port == 0) {
			if (prompt_text) {
				NSArray<NSDictionary *> *cli_messages =
					@[@{@"role": @"system", @"content": @"You are a helpful assistant."},
					  @{@"role": @"user", @"content": [NSString stringWithUTF8String:prompt_text]}];
				pt = tokenize_rendered_messages(cli_messages, YES, YES);
				if (pt && automatic_no_think_for_prompt(pt->count, max_tokens)) {
					free(pt->ids); free(pt);
					pt = tokenize_rendered_messages(cli_messages, YES, NO);
				}
				if (!pt) {
					fprintf(stderr, "ERROR: Failed to encode prompt. Make sure encode_prompt.py exists.\n");
					return 1;
				}
			} else if (!prompt_tokens_path) {
				pt = encode_prompt_text_to_tokens("Hello, what is");
				if (!pt) {
					fprintf(stderr, "ERROR: No prompt tokens and encode_prompt.py not found\n");
					return 1;
				}
			} else {
				pt = load_prompt_tokens(prompt_tokens_path);
			}

			if (!pt) {
				fprintf(stderr, "ERROR: Failed to load prompt tokens%s%s\n",
						prompt_tokens_path ? " from " : "",
						prompt_tokens_path ? prompt_tokens_path : "");
				return 1;
			}
			if (!validate_prompt_tokens(pt, 1, "CLI prompt")) {
				free(pt->ids); free(pt);
				return 1;
			}
			if (!g_stream_mode) {
				printf("[prompt] %d tokens:", pt->count);
				for (int i = 0; i < pt->count && i < 20; i++) {
					printf(" %d", pt->ids[i]);
				}
			}
			printf("\n");
		}

		// Expert storage mode was resolved before Metal/cache initialization.

		// ---- Open + mmap packed expert files ----
		// Tiered I/O: two fds per layer file.
		//   layer_fds[i]      = warm fd (page cached) — for experts seen before
		//   layer_fds_cold[i] = cold fd (F_NOCACHE)   — for first-time expert reads
		// Seen-expert bitset tracks which (layer, expert) pairs have been read before.
		// First read goes through cold fd (no page cache pollution).
		// Subsequent reads go through warm fd (page cache hit = 32 GB/s vs 5.5 GB/s).
		int layer_fds[MAX_LAYERS];
		int layer_fds_cold[MAX_LAYERS];
		void *layer_mmaps[MAX_LAYERS];
		int expert_layers_available = 0;

		// Reset the global seen-expert bitset
		memset(g_expert_seen, 0, sizeof(g_expert_seen));

		int layers_2bit = 0, layers_q3 = 0, layers_q3_outlier = 0, layers_4bit = 0;
		memset(g_layer_is_2bit, 0, sizeof(g_layer_is_2bit));
		memset(g_layer_is_q3_hybrid, 0, sizeof(g_layer_is_q3_hybrid));
		memset(g_layer_is_q3_outlier, 0, sizeof(g_layer_is_q3_outlier));

		for (int i = 0; i < NUM_LAYERS; i++) {
			char path[1024];
			layer_fds[i] = -1;

			if (g_use_tiered) {
				snprintf(path, sizeof(path), "%s/packed_experts_tiered/layer_%02d.bin", model_path, i);
				layer_fds[i] = open(path, O_RDONLY);
				if (layer_fds[i] >= 0 && !validate_tiered_layer_file(i, layer_fds[i], path)) {
					close(layer_fds[i]);
					return 1;
				}
			} else if (g_use_q3_experts) {
				snprintf(path, sizeof(path), "%s/packed_experts_Q3/layer_%02d.bin", model_path, i);
				layer_fds[i] = open(path, O_RDONLY);
				if (layer_fds[i] >= 0) {
					if (i == Q3_OUTLIER_LAYER) {
						g_layer_is_q3_outlier[i] = 1;
						layers_q3_outlier++;
					} else {
						g_layer_is_q3_hybrid[i] = 1;
						layers_q3++;
					}
				} else {
					snprintf(path, sizeof(path), "%s/packed_experts/layer_%02d.bin", model_path, i);
					layer_fds[i] = open(path, O_RDONLY);
					if (layer_fds[i] >= 0) {
						g_layer_is_q3_hybrid[i] = 0;
						layers_4bit++;
					}
				}
			} else if (g_use_2bit) {
				// Try 2-bit first
				snprintf(path, sizeof(path), "%s/packed_experts_2bit/layer_%02d.bin", model_path, i);
				layer_fds[i] = open(path, O_RDONLY);
				if (layer_fds[i] >= 0) {
					g_layer_is_2bit[i] = 1;
					layers_2bit++;
				} else {
					// Fall back to 4-bit for this layer
					snprintf(path, sizeof(path), "%s/packed_experts/layer_%02d.bin", model_path, i);
					layer_fds[i] = open(path, O_RDONLY);
					if (layer_fds[i] >= 0) {
						g_layer_is_2bit[i] = 0;
						layers_4bit++;
					}
				}
			} else {
				snprintf(path, sizeof(path), "%s/packed_experts/layer_%02d.bin", model_path, i);
				layer_fds[i] = open(path, O_RDONLY);
			}

			if (layer_fds[i] >= 0 && !g_use_tiered) {
				size_t expected_layer_expert_size =
					expert_layout_for_kind(layer_expert_quant_kind(i)).expert_size;
				if (!validate_uniform_expert_layer_file(
						i, layer_fds[i], path, expected_layer_expert_size)) {
					close(layer_fds[i]);
					return 1;
				}
			}

			layer_fds_cold[i] = -1;
			layer_mmaps[i] = MAP_FAILED;
			g_layer_mmap_sizes[i] = 0;
			if (layer_fds[i] >= 0) {
				expert_layers_available++;
				if (g_use_tiered && g_tiered_cold_nocache) {
					layer_fds_cold[i] = open(path, O_RDONLY);
					if (layer_fds_cold[i] < 0 ||
						fcntl(layer_fds_cold[i], F_NOCACHE, 1) < 0 ||
						fcntl(layer_fds_cold[i], F_RDAHEAD, 0) < 0) {
						fprintf(stderr, "ERROR: cannot configure uncached tiered layer %d: %s\n", i, strerror(errno));
						if (layer_fds_cold[i] >= 0) close(layer_fds_cold[i]);
						return 1;
					}
				}
				// Disable readahead: expert reads are random (different offsets per token).
				// Read-ahead prefetches adjacent data we won't use, wasting SSD bandwidth.
				fcntl(layer_fds[i], F_RDAHEAD, 0);
				if (g_cache_io_split <= 1) {
					// Only mmap when fanout is disabled — with cache-io-split the
					// pread fanout path is used exclusively and mmap just wastes
					// virtual address space (~163-209 GB) and adds VM overhead.
					struct stat st;
					if (fstat(layer_fds[i], &st) == 0 && st.st_size > 0) {
						layer_mmaps[i] = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, layer_fds[i], 0);
						if (layer_mmaps[i] != MAP_FAILED) {
							g_layer_mmap_sizes[i] = st.st_size;
						}
					}
				}
			}
		}
		printf("[experts] %d/%d packed layer files available (%s)\n",
			   expert_layers_available, NUM_LAYERS,
			   g_cache_io_split > 1 ? "pread fanout" : "mmap'd");
		if (g_use_q3_experts && layers_4bit > 0) {
			if (layers_q3_outlier > 0) {
				printf("[mixed-quant] %d layers at Q3-GGUF, %d layers at Q3-outlier, %d layers at 4-bit\n",
					   layers_q3, layers_q3_outlier, layers_4bit);
			} else {
				printf("[mixed-quant] %d layers at Q3-GGUF, %d layers at 4-bit\n", layers_q3, layers_4bit);
			}
		} else if (g_use_q3_experts && layers_q3_outlier > 0) {
			printf("[mixed-quant] %d layers at Q3-GGUF, %d layers at Q3-outlier\n",
				   layers_q3, layers_q3_outlier);
		} else if (g_use_2bit && layers_4bit > 0) {
			printf("[mixed-quant] %d layers at 2-bit, %d layers at 4-bit\n", layers_2bit, layers_4bit);
		}

		// ---- LZ4 compressed experts: auto-detect and load ----
		{
			char lz4_probe[1024];
			snprintf(lz4_probe, sizeof(lz4_probe), "%s/packed_experts_lz4/layer_00.bin", model_path);
			if (!g_use_2bit && !g_use_q3_experts && !g_use_tiered && access(lz4_probe, R_OK) == 0) {
				int lz4_layers = 0;
				size_t max_lz4_comp = 0;
				size_t expected_raw = active_expert_size();
				const uint64_t index_bytes = (uint64_t)NUM_EXPERTS * sizeof(LZ4IndexEntry);

				for (int i = 0; i < NUM_LAYERS; i++) {
					char lz4_path[1024];
					snprintf(lz4_path, sizeof(lz4_path), "%s/packed_experts_lz4/layer_%02d.bin", model_path, i);
					int lz4_fd = open(lz4_path, O_RDONLY);
					if (lz4_fd < 0) continue;

					struct stat lst;
					if (fstat(lz4_fd, &lst) != 0 || lst.st_size <= 0) {
						fprintf(stderr, "[lz4] WARNING: invalid layer file %s\n", lz4_path);
						close(lz4_fd);
						continue;
					}
					uint64_t file_size = (uint64_t)lst.st_size;
					if (file_size < index_bytes) {
						fprintf(stderr, "[lz4] WARNING: truncated index in %s\n", lz4_path);
						close(lz4_fd);
						continue;
					}

					LZ4IndexEntry *index = malloc(NUM_EXPERTS * sizeof(LZ4IndexEntry));
					if (!index) {
						fprintf(stderr, "ERROR: unable to allocate LZ4 index for layer %d\n", i);
						close(lz4_fd);
						return 1;
					}

					ssize_t nr = pread(lz4_fd, index, NUM_EXPERTS * sizeof(LZ4IndexEntry), 0);
					int valid_index = (nr == NUM_EXPERTS * (ssize_t)sizeof(LZ4IndexEntry));
					size_t layer_max_comp = 0;

					if (valid_index) {
						for (int e = 0; e < NUM_EXPERTS; e++) {
							LZ4IndexEntry *ie = &index[e];
							if (ie->raw_size != expected_raw || ie->comp_size == 0 ||
								(uint64_t)ie->offset < index_bytes ||
								(uint64_t)ie->offset > file_size ||
								(uint64_t)ie->comp_size > file_size - (uint64_t)ie->offset) {
								fprintf(stderr,
										"[lz4] WARNING: rejecting malformed layer %d expert %d "
										"(offset=%llu comp=%u raw=%u file=%llu expected_raw=%zu)\n",
										i, e, (unsigned long long)ie->offset,
										ie->comp_size, ie->raw_size,
										(unsigned long long)file_size, expected_raw);
								valid_index = 0;
								break;
							}
							if ((size_t)ie->comp_size > layer_max_comp)
								layer_max_comp = ie->comp_size;
						}
					}

					if (!valid_index) {
						free(index);
						close(lz4_fd);
						continue;  // retain the raw expert fd for this layer
					}

					g_lz4_index[i] = index;
					g_lz4_file_sizes[i] = (size_t)file_size;
					if (layer_max_comp > max_lz4_comp) max_lz4_comp = layer_max_comp;

					if (layer_mmaps[i] != MAP_FAILED) {
						munmap(layer_mmaps[i], g_layer_mmap_sizes[i]);
						layer_mmaps[i] = MAP_FAILED;
						g_layer_mmap_sizes[i] = 0;
					}
					close(layer_fds[i]);
					layer_fds[i] = lz4_fd;
					fcntl(lz4_fd, F_RDAHEAD, 1);
					lz4_layers++;
				}

				if (lz4_layers > 0) {
					if (max_lz4_comp == 0) {
						fprintf(stderr, "ERROR: validated LZ4 layers have zero compressed capacity\n");
						return 1;
					}
					g_lz4_comp_capacity = max_lz4_comp;
					for (int k = 0; k < MAX_K; k++) {
						g_lz4_comp_bufs[k] = malloc(g_lz4_comp_capacity);
						if (!g_lz4_comp_bufs[k]) {
							fprintf(stderr,
									"ERROR: unable to allocate LZ4 compressed buffer %d (%zu bytes)\n",
									k, g_lz4_comp_capacity);
							return 1;
						}
					}
					g_use_lz4 = 1;
					printf("[lz4] %d/%d layers using validated LZ4 experts "
						   "(max compressed expert %.2f MB)\n",
						   lz4_layers, NUM_LAYERS,
						   g_lz4_comp_capacity / 1048576.0);
				}
			}
		}

		// Exact inference requires every layer's routed-expert file.
		for (int i = 0; i < NUM_LAYERS; i++) {
			if (layer_fds[i] < 0) {
				fprintf(stderr,
						"ERROR: missing packed expert file for layer %d; "
						"refusing degraded shared-only inference\n", i);
				return 1;
			}
		}

		// Wire up tiered I/O globals
		g_layer_fds_cold = layer_fds_cold;
		if (g_use_tiered && g_tiered_cold_nocache)
			printf("[tiered-io] Cold 2-bit experts use F_NOCACHE\n");
		if (g_cache_io_split > 1) {
			printf("[tiered-io] Experimental cache fanout: split routed expert preads into %d page-aligned chunks\n",
				   active_cache_io_split(active_expert_size()));
		}

		// Warm page cache hint
		if (expert_layers_available > 0) {
			double t_warm = now_ms();
			for (int i = 0; i < NUM_LAYERS; i++) {
				if (layer_fds[i] >= 0) {
					char dummy[4096];
					pread(layer_fds[i], dummy, sizeof(dummy), 0);
				}
			}
			printf("[warmup] Page cache hint: %.1f ms\n", now_ms() - t_warm);
		}

		// ---- Allocate per-layer state ----
		void **layer_states = calloc(NUM_LAYERS, sizeof(void *));
		KVCache **kv_caches = calloc(NUM_LAYERS, sizeof(KVCache *));
		if (!layer_states || !kv_caches) {
			fprintf(stderr, "ERROR: unable to allocate per-layer state tables\n");
			free(layer_states);
			free(kv_caches);
			return 1;
		}

		for (int i = 0; i < NUM_LAYERS; i++) {
			int is_full = ((i + 1) % FULL_ATTN_INTERVAL == 0);
			if (is_full) {
				kv_caches[i] = kv_cache_new();
				if (!kv_caches[i]) {
					fprintf(stderr, "ERROR: unable to allocate KV state for layer %d\n", i);
					for (int j = 0; j < NUM_LAYERS; j++) {
						if (kv_caches[j]) kv_cache_free(kv_caches[j]);
						if (layer_states[j]) linear_attn_state_free((LinearAttnState *)layer_states[j]);
					}
					free(layer_states);
					free(kv_caches);
					return 1;
				}
			} else {
				layer_states[i] = linear_attn_state_new();
				if (!layer_states[i]) {
					fprintf(stderr, "ERROR: unable to allocate linear-attention state for layer %d\n", i);
					for (int j = 0; j < NUM_LAYERS; j++) {
						if (kv_caches[j]) kv_cache_free(kv_caches[j]);
						if (layer_states[j]) linear_attn_state_free((LinearAttnState *)layer_states[j]);
					}
					free(layer_states);
					free(kv_caches);
					return 1;
				}
			}
		}

		double t_init = now_ms();
		printf("[init] Setup: %.1f ms\n\n", t_init - t0);

		// ---- Allocate working buffers ----
		float *hidden = calloc(HIDDEN_DIM, sizeof(float));
		float *logits = calloc(VOCAB_SIZE, sizeof(float));
		uint16_t *final_norm_w = get_tensor_ptr(wf, "model.norm.weight");
		if (!hidden || !logits || !final_norm_w) {
			fprintf(stderr, "ERROR: unable to allocate/resolve inference working buffers\n");
			free(hidden);
			free(logits);
			for (int j = 0; j < NUM_LAYERS; j++) {
				if (kv_caches[j]) kv_cache_free(kv_caches[j]);
				if (layer_states[j]) linear_attn_state_free((LinearAttnState *)layer_states[j]);
			}
			free(layer_states);
			free(kv_caches);
			return 1;
		}

		if (target_verify_bench)
			return run_target_verify_benchmark(wf, kv_caches, layer_states,
				(void **)layer_mmaps, layer_fds, K, hidden, logits, final_norm_w,
                target_verify_batched);
#ifdef FLASH_PREFILL_NROW_BENCH
		if (prefill_nrow_1k)
			return run_prefill_nrow_fullbench(wf, pt, kv_caches, layer_states,
				(void **)layer_mmaps, layer_fds, K, final_norm_w);
		if (prefill_nrow_control || prefill_nrow_grouped)
			return run_prefill_nrow_control(wf, pt, kv_caches, layer_states,
				(void **)layer_mmaps, layer_fds, K, final_norm_w,
				prefill_nrow_grouped);
#endif

		// ---- Serve mode: enter HTTP server loop (never returns) ----
		if (serve_port > 0) {
			reset_delta_net_state();
			serve_loop(serve_port, wf, vocab,
					   layer_states, kv_caches,
					   (void **)layer_mmaps, layer_fds,
					   hidden, logits, final_norm_w, K,
                       warm_tools_path, profile_id.UTF8String,
                       warm_profile, recapture_profile,
                       weights_path, manifest_path, vocab_path);
			// A normal server loop is infinite; any return indicates startup/runtime failure.
			free(hidden); free(logits);
			return 1;
		}

		// ---- PPL evaluation mode ----
		if (ppl_tokens_path) {
			PromptTokens *gt = load_prompt_tokens(ppl_tokens_path);
			if (!gt) {
				fprintf(stderr, "ERROR: Failed to load PPL tokens from %s\n", ppl_tokens_path);
				free(hidden); free(logits);
				return 1;
			}
			if (!validate_prompt_tokens(gt, 2, "perplexity evaluation")) {
				free(gt->ids); free(gt);
				free(hidden); free(logits);
				return 1;
			}
			if (!context_preflight("perplexity evaluation", 0, gt->count, 0)) {
				free(gt->ids); free(gt);
				free(hidden); free(logits);
				io_pool_shutdown();
				return 1;
			}
			int num_eval = gt->count - 1;
			printf("=== Perplexity Evaluation ===\n");
			printf("Tokens: %d (scoring %d predictions)\n", gt->count, num_eval);
			printf("Quant:  %s\n", requested_expert_quant_label());

			reset_delta_net_state();
			if (g_cache_telemetry_enabled) cache_telemetry_reset();

			double total_nll = 0.0;
			int tokens_scored = 0;
			int pos = 0;
			double t_ppl_start = now_ms();

			for (int i = 0; i < gt->count; i++) {
				// Embed token[i]
				embed_lookup(wf, gt->ids[i], hidden);

				// Run all transformer layers
				g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
								(void **)layer_mmaps, layer_fds, pos, K);
				if (g_forward_error) {
					fprintf(stderr, "\nERROR: PPL forward failed at token %d\n", i);
					free(gt->ids); free(gt);
					free(hidden); free(logits);
					io_pool_shutdown();
					return 1;
				}
				if (!complete_deferred_experts()) {
					fprintf(stderr, "\nERROR: PPL deferred Metal completion failed at token %d\n", i);
					free(gt->ids); free(gt);
					free(hidden); free(logits);
					io_pool_shutdown();
					return 1;
				}
				pos++;

				// Score: compute cross-entropy for predicting token[i+1]
				if (i < gt->count - 1) {
					apply_final_norm_inplace(hidden, final_norm_w);

					lm_head_forward(wf, hidden, logits);

					float nll = cross_entropy_loss(logits, VOCAB_SIZE, gt->ids[i + 1]);
					total_nll += nll;
					tokens_scored++;

					// Progress every 10 tokens
					if (tokens_scored % 10 == 0 || tokens_scored == num_eval) {
						double elapsed = now_ms() - t_ppl_start;
						double avg_nll = total_nll / tokens_scored;
						double tok_s = tokens_scored * 1000.0 / elapsed;
						double eta_s = tok_s > 0.0 ? (num_eval - tokens_scored) / tok_s : 0.0;
						char eta_buf[16];
						format_eta(eta_s, eta_buf, sizeof(eta_buf));
						fprintf(stderr, "\r[ppl] %d/%d tokens | NLL=%.4f | PPL=%.2f | %.2f tok/s | ETA %s",
								tokens_scored, num_eval, avg_nll, exp(avg_nll), tok_s, eta_buf);
					}
				}
			}

			double elapsed_s = (now_ms() - t_ppl_start) / 1000.0;
			double avg_nll = total_nll / tokens_scored;
			double ppl = exp(avg_nll);

			fprintf(stderr, "\n");
			printf("\n=== Perplexity Results ===\n");
			printf("Tokens evaluated: %d\n", tokens_scored);
			printf("Cross-entropy:    %.4f nats\n", avg_nll);
			printf("Perplexity:       %.2f\n", ppl);
			printf("Time:             %.1f s (%.2f tok/s)\n", elapsed_s,
				   tokens_scored / elapsed_s);
			printf("Quant:            %s\n", requested_expert_quant_label());

			free(gt->ids); free(gt);
			free(hidden); free(logits);
			io_pool_shutdown();
			return 0;
		}

		if (!context_preflight("CLI generation", 0, pt->count, max_tokens)) {
			free(pt->ids); free(pt);
			free(hidden); free(logits);
			io_pool_shutdown();
			return 1;
		}

		// ---- Generate tokens ----
		reset_delta_net_state();  // zero GPU delta-net state before generation
		if (g_cache_telemetry_enabled) cache_telemetry_reset();
		if (!g_stream_mode) printf("--- Generating %d tokens ---\n", max_tokens);
		int pos = 0;  // position counter for RoPE

		// ---- Batch prefill: pre-embed all prompt tokens ----
		// Embedding all tokens upfront into a batch buffer avoids interleaving
		// embed_lookup with GPU work, and enables the optimized prefill loop below.
		float *embed_batch = try_alloc_embedding_batch(pt->count, "CLI");
		if (embed_batch) {
			double t_embed = now_ms();
			for (int i = 0; i < pt->count; i++) {
				embed_lookup(wf, pt->ids[i], embed_batch + (size_t)i * HIDDEN_DIM);
			}
			double embed_ms = now_ms() - t_embed;
			if (!g_stream_mode) printf("  [prefill] batch embed %d tokens: %.1f ms\n", pt->count, embed_ms);
		}

		// ---- Batch prefill loop ----
		// Process all prompt tokens through the model. For intermediate tokens
		// (not the last), we use discard_deferred_experts() which waits for the GPU
		// but skips the CPU readback/combine of the last layer's expert outputs.
		// This is safe because the hidden state from intermediate prefill tokens
		// is immediately overwritten by the next token's embedding — the recurrent
		// state (KV cache, delta-net state) is already updated inside fused_layer_forward.
		if (pt->count > 1) {
			double t_prefill_batch = now_ms();
			double first_tok_ms = 0;

			int token_idx = 0;
#ifdef FLASH_PREFILL_NROW_PRODUCTION
			int cli_nrow_ready = 0;
			int cli_nrow_prepare_attempted = 0;
#endif
			while (token_idx < pt->count - 1) {
				double t_tok = now_ms();
#ifdef FLASH_PREFILL_NROW_PRODUCTION
				if (g_prefill_nrow_runtime_enabled &&
					prefill_nrow_runtime_cache_range_eligible(kv_caches) &&
					(pt->count - 1 - token_idx) >= PREFILL_NROW_CAPTURE_ROWS) {
					if (!cli_nrow_prepare_attempted) {
						cli_nrow_ready = prefill_nrow_runtime_prepare(K);
						cli_nrow_prepare_attempted = 1;
					}
					if (cli_nrow_ready) {
					for (int row = 0; row < PREFILL_NROW_CAPTURE_ROWS; row++)
						cache_telemetry_note_token();
					const float *embedded_rows = embed_batch
						? embed_batch + (size_t)token_idx * HIDDEN_DIM : NULL;
					if (!prefill_nrow_runtime_chunk(
							wf, kv_caches, layer_states, (void **)layer_mmaps,
							layer_fds, K, pos, pt->ids + token_idx,
							embedded_rows, NULL, NULL, NULL)) {
						fprintf(stderr, "ERROR: CLI N-row prefill failed at token %d\n", token_idx);
						free(embed_batch);
						free(pt->ids); free(pt);
						free(hidden); free(logits);
						io_pool_shutdown();
						return 1;
					}
					token_idx += PREFILL_NROW_CAPTURE_ROWS;
					pos += PREFILL_NROW_CAPTURE_ROWS;
					if (first_tok_ms == 0.0) first_tok_ms = now_ms() - t_tok;
					continue;
					}
				}
#endif

				// Load pre-embedded token when available; large/OOM batches
				// transparently fall back to one-token embedding.
				cache_telemetry_note_token();
				if (embed_batch) {
					memcpy(hidden, embed_batch + (size_t)token_idx * HIDDEN_DIM,
						   HIDDEN_DIM * sizeof(float));
				} else {
					embed_lookup(wf, pt->ids[token_idx], hidden);
				}

				// Run through all transformer layers
				g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
								(void **)layer_mmaps, layer_fds, pos, K);
				if (g_forward_error) {
					fprintf(stderr, "ERROR: CLI prefill forward failed at token %d\n", token_idx);
					free(embed_batch);
					free(pt->ids); free(pt);
					free(hidden); free(logits);
					io_pool_shutdown();
					return 1;
				}

				// Discard last layer's expert output — hidden will be overwritten
				// by the next token's embedding. Only wait for GPU (buffer safety).
				if (!discard_deferred_experts()) {
					fprintf(stderr, "ERROR: CLI prefill deferred Metal completion failed at token %d\n", token_idx);
					free(embed_batch);
					free(pt->ids); free(pt);
					free(hidden); free(logits);
					io_pool_shutdown();
					return 1;
				}
				pos++;
				token_idx++;

				if (token_idx == 1) {
					first_tok_ms = now_ms() - t_tok;
				}
			}

			double prefill_batch_ms = now_ms() - t_prefill_batch;
			double avg_ms = (pt->count > 2) ?
				(prefill_batch_ms - first_tok_ms) / (pt->count - 2) : first_tok_ms;
			if (!g_stream_mode) printf("  [prefill] %d/%d tokens: %.0f ms (first: %.0f ms, rest avg: %.0f ms)\n",
				   pt->count - 1, pt->count, prefill_batch_ms, first_tok_ms, avg_ms);
		}

		// ---- Last prefill token (or single-token prompt) ----
		// This one needs full completion since we need hidden state for logits.
		{
			cache_telemetry_note_token();
			if (embed_batch) {
				memcpy(hidden, embed_batch + (size_t)(pt->count - 1) * HIDDEN_DIM,
					   HIDDEN_DIM * sizeof(float));
			} else {
				embed_lookup(wf, pt->ids[pt->count - 1], hidden);
			}

			g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
							(void **)layer_mmaps, layer_fds, pos, K);
			if (g_forward_error) {
				fprintf(stderr, "ERROR: CLI final prefill token failed\n");
				if (embed_batch) free(embed_batch);
				free(pt->ids); free(pt);
				free(hidden); free(logits);
				io_pool_shutdown();
				return 1;
			}
			// Full completion — need hidden state for final norm + lm_head
			if (!complete_deferred_experts()) {
				fprintf(stderr, "ERROR: CLI final prefill deferred Metal completion failed\n");
				if (embed_batch) free(embed_batch);
				free(pt->ids); free(pt);
				free(hidden); free(logits);
				io_pool_shutdown();
				return 1;
			}
			pos++;
		}

		if (embed_batch) { free(embed_batch); embed_batch = NULL; }

		// ---- Final norm ----
		if (final_norm_w) {
			apply_final_norm_inplace(hidden, final_norm_w);
		}

		// ---- LM head ----
		double t_lm = now_ms();
		int next_token;
		if (g_temperature <= 0.0f && g_gpu_argmax_enabled)
			next_token = lm_head_forward_greedy(wf, hidden, logits);
		else
			lm_head_forward(wf, hidden, logits);
		double lm_ms = now_ms() - t_lm;

		// ---- Sample first token ----
		if (!(g_temperature <= 0.0f && g_gpu_argmax_enabled))
			next_token = cpu_sample_token(logits, VOCAB_SIZE);
		double ttft_ms = now_ms() - t0;

		// Debug: show top-5 logits for first token (skip in stream mode)
		if (!g_stream_mode) {
			// Find top 5 manually
			int top5[5] = {0,0,0,0,0};
			float topv[5] = {-1e30f,-1e30f,-1e30f,-1e30f,-1e30f};
			for (int i = 0; i < VOCAB_SIZE; i++) {
				int min_k = 0;
				for (int k = 1; k < 5; k++) if (topv[k] < topv[min_k]) min_k = k;
				if (logits[i] > topv[min_k]) { topv[min_k] = logits[i]; top5[min_k] = i; }
			}
			fprintf(stderr, "[debug] Top 5 logits (next_token=%d):\n", next_token);
			for (int i = 0; i < 5; i++) {
				fprintf(stderr, "  token %d (\"%s\") logit=%.4f\n",
						top5[i], decode_token(vocab, top5[i]), topv[i]);
			}
			fprintf(stderr, "[debug] hidden rms after final_norm=%.4f, logits rms=%.4f\n",
					vec_rms(hidden, HIDDEN_DIM), vec_rms(logits, VOCAB_SIZE));
		}
		if (!g_stream_mode) {
			printf("[ttft] %.0f ms (prefill %d tokens + lm_head %.0f ms)\n",
				   ttft_ms, pt->count, lm_ms);
			printf("\n--- Output ---\n");
		}
		Utf8TokenStream cli_utf8 = {0};
		char *first_text = utf8_token_stream_push_token(&cli_utf8, vocab, next_token);
		if (first_text) { fputs(first_text, stdout); free(first_text); }
		fflush(stdout);

		int total_generated = 1;
		int in_think = tokens_end_in_think(pt->ids, pt->count);
		int think_tokens = 0;
		int cli_think_budget = in_think ? effective_think_budget(max_tokens) : -1;
		uint32_t *think_stop_seq = NULL;
		int think_stop_count = 0;
		int think_stop_index = 0;
		int think_stop_active = 0;

		// ---- Auto-regressive generation ----
		if (g_timing_enabled) timing_reset();
		if (g_pipeline_profile_enabled) { pipeline_profile_reset(); g_pipeline_profile_decode_active = 1; }
		if (g_pred_enabled || g_expert_prefetch_enabled) {
			g_pred_generating = g_pred_enabled ? 1 : 0;
			g_expert_prefetch_generating = g_expert_prefetch_enabled ? 1 : 0;
			g_pred_valid = 0;
			if (g_expert_prefetch_enabled) expert_prefetch_history_reset();
		}
		if (g_cmd1_profile_enabled) g_cmd1_profile_decode_active = 1;
		for (int gen = 1; gen < max_tokens; gen++) {
			double t_gen_start = now_ms();
			double pipeline_tok_embed_ms = 0.0;
			double pipeline_tok_layers_ms = 0.0;
			double pipeline_tok_final_deferred_ms = 0.0;
			double pipeline_tok_final_norm_ms = 0.0;
			double pipeline_tok_lm_total_ms = 0.0;
			double pipeline_tok_sample_cpu_ms = 0.0;
			double pipeline_tok_output_ms = 0.0;

			// Check EOS
			if (next_token == EOS_TOKEN_1 || next_token == EOS_TOKEN_2) {
				if (!g_stream_mode)
					fprintf(stderr, "\n[eos] Token %d at position %d\n", next_token, gen);
				break;
			}

			// Think budget enforcement
			if (next_token == THINK_START_TOKEN) in_think = 1;
			if (next_token == THINK_END_TOKEN) in_think = 0;
			if (in_think) think_tokens++;

			// Embed the just-generated token (next iteration)
			double pipeline_phase_ms = now_ms();
			cache_telemetry_note_token();
			embed_lookup(wf, next_token, hidden);
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active)
				pipeline_tok_embed_ms = now_ms() - pipeline_phase_ms;

			// Run all transformer layers (fused command-buffer pipeline)
			pipeline_phase_ms = now_ms();
			g_forward_error = !run_all_layers_checked(wf, hidden, kv_caches, layer_states,
							(void **)layer_mmaps, layer_fds, pos, K);
			if (g_forward_error) {
				fprintf(stderr, "ERROR: CLI generation forward failed at position %d\n", pos);
				free(pt->ids); free(pt);
				free(hidden); free(logits);
				io_pool_shutdown();
				return 1;
			}
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active)
				pipeline_tok_layers_ms = now_ms() - pipeline_phase_ms;

			// Complete last layer's deferred GPU experts before final norm
			pipeline_phase_ms = now_ms();
			if (!complete_deferred_experts()) {
				fprintf(stderr, "ERROR: CLI deferred Metal completion failed at position %d\n", pos);
				free(pt->ids); free(pt);
				free(hidden); free(logits);
				io_pool_shutdown();
				return 1;
			}
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active)
				pipeline_tok_final_deferred_ms = now_ms() - pipeline_phase_ms;
			pos++;

			// Final norm
			pipeline_phase_ms = now_ms();
			if (final_norm_w) {
				apply_final_norm_inplace(hidden, final_norm_w);
			}
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active)
				pipeline_tok_final_norm_ms = now_ms() - pipeline_phase_ms;

			// LM head + sampling, with actual LM Metal GPU timestamps kept separate.
			double t_lm_gen = now_ms();
			pipeline_profile_reset_lm_capture();
			if (g_temperature <= 0.0f && g_gpu_argmax_enabled) {
				next_token = lm_head_forward_greedy(wf, hidden, logits);
			} else {
				lm_head_forward(wf, hidden, logits);
				double _sample_start = now_ms();
				next_token = cpu_sample_token(logits, VOCAB_SIZE);
				pipeline_tok_sample_cpu_ms = now_ms() - _sample_start;
			}
			double lm_gen_ms = now_ms() - t_lm_gen;
			pipeline_tok_lm_total_ms = lm_gen_ms;
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active &&
				g_profile_lm_gpu_start_s > 0.0 && g_profile_lm_gpu_end_s >= g_profile_lm_gpu_start_s) {
				g_pipeline_profile.lm_gpu_ms += g_profile_lm_gpu_ms;
				if (g_pipeline_profile.pending_last_cmd3_end_s > 0.0 &&
					g_profile_lm_gpu_start_s >= g_pipeline_profile.pending_last_cmd3_end_s) {
					g_pipeline_profile.last_cmd3_to_lm_gap_ms +=
						(g_profile_lm_gpu_start_s - g_pipeline_profile.pending_last_cmd3_end_s) * 1000.0;
					g_pipeline_profile.last_cmd3_to_lm_gap_count++;
				}
				g_pipeline_profile.pending_last_cmd3_end_s = 0.0;
				g_pipeline_profile.pending_lm_end_s = g_profile_lm_gpu_end_s;
			}
			if (g_timing_enabled) {
				g_timing.lm_head += lm_gen_ms;
				g_timing.token_count++;
			}

			// Qwen thinking-budget handoff: inject the documented early-stop
			// steering sequence internally, then resume normal final-answer sampling.
			int suppress_token_output = 0;
			if (think_stop_active && think_stop_index < think_stop_count) {
				next_token = think_stop_seq[think_stop_index++];
				suppress_token_output = 1;
				if (think_stop_index >= think_stop_count) think_stop_active = 0;
			} else if (in_think && cli_think_budget > 0 && think_tokens >= cli_think_budget) {
				think_stop_seq = build_think_stop_sequence(&think_stop_count);
				if (think_stop_seq && think_stop_count > 0) {
					if (!g_stream_mode) fprintf(stderr, "\n[think] budget reached (%d), applying Qwen early-stop handoff (%d tokens)\n", cli_think_budget, think_stop_count);
					think_stop_active = 1;
					think_stop_index = 1;
					next_token = think_stop_seq[0];
					suppress_token_output = 1;
				} else {
					next_token = THINK_END_TOKEN;
				}
			}
			if (next_token == THINK_END_TOKEN) in_think = 0;
			total_generated++;

			// Print only complete UTF-8. Byte-level BPE pieces may span tokens.
			pipeline_phase_ms = now_ms();
			char *decoded_text = suppress_token_output ? NULL : utf8_token_stream_push_token(&cli_utf8, vocab, next_token);
			if (decoded_text) { fputs(decoded_text, stdout); free(decoded_text); }
			fflush(stdout);
			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active)
				pipeline_tok_output_ms = now_ms() - pipeline_phase_ms;

			double t_gen_end = now_ms();
			double tok_time = t_gen_end - t_gen_start;

			if (g_pipeline_profile_enabled && g_pipeline_profile_decode_active) {
				g_pipeline_profile.tokens++;
				g_pipeline_profile.token_wall_ms += tok_time;
				g_pipeline_profile.embed_wall_ms += pipeline_tok_embed_ms;
				g_pipeline_profile.layers_wall_ms += pipeline_tok_layers_ms;
				g_pipeline_profile.final_deferred_wall_ms += pipeline_tok_final_deferred_ms;
				g_pipeline_profile.final_norm_wall_ms += pipeline_tok_final_norm_ms;
				g_pipeline_profile.lm_total_wall_ms += pipeline_tok_lm_total_ms;
				g_pipeline_profile.sample_cpu_ms += pipeline_tok_sample_cpu_ms;
				g_pipeline_profile.output_wall_ms += pipeline_tok_output_ms;
			}

			// Print progress to stderr
			if (!g_stream_mode)
				fprintf(stderr, "  [gen %d/%d] token_id=%d (%.0f ms, %.2f tok/s)\n",
						gen, max_tokens, next_token, tok_time, 1000.0 / tok_time);
		}
		g_cmd1_profile_decode_active = 0;
		g_pipeline_profile_decode_active = 0;
		free(think_stop_seq);
		think_stop_seq = NULL;

		if (cli_utf8.pending_len > 0) {
			char *tail = utf8_token_stream_flush(&cli_utf8);
			if (tail) { fputs(tail, stdout); free(tail); fflush(stdout); }
		}

		if (g_stream_mode) {
			double total_time = now_ms() - t0;
			double gen_time = total_time - ttft_ms;
			double decode_tps = (total_generated > 1) ? (total_generated - 1) * 1000.0 / gen_time : 0;
			double prefill_tps = (pt->count > 0) ? pt->count * 1000.0 / ttft_ms : 0;
			printf("\n\ndecode: %.2f t/s, prefill: %.2f t/s\n", decode_tps, prefill_tps);
		}
		if (g_timing_enabled) timing_print();
		if (g_pipeline_profile_enabled) pipeline_profile_print();
		if (!g_stream_mode) {
			printf("\n\n--- Statistics ---\n");
			double total_time = now_ms() - t0;
			printf("Total time:     %.1f s\n", total_time / 1000.0);
			printf("TTFT:           %.0f ms\n", ttft_ms);
			printf("Tokens:         %d generated\n", total_generated);
			if (total_generated > 1) {
				double gen_time = total_time - ttft_ms;
				printf("Generation:     %.1f s (%.2f tok/s)\n",
					   gen_time / 1000.0, (total_generated - 1) * 1000.0 / gen_time);
			}
			printf("Config:         K=%d experts, %d layers\n", K, NUM_LAYERS);
			if (g_expert_cache) {
				uint64_t total = g_expert_cache->hits + g_expert_cache->misses;
				printf("Expert cache:   %llu hits, %llu misses (%.1f%% hit rate), %d/%d entries used\n",
					   g_expert_cache->hits, g_expert_cache->misses,
					   total > 0 ? 100.0 * g_expert_cache->hits / total : 0.0,
					   g_expert_cache->num_entries, g_expert_cache->max_entries);
				cache_telemetry_print(g_expert_cache->hits, g_expert_cache->misses);
			} else if (g_malloc_cache) {
				uint64_t total = g_malloc_cache->hits + g_malloc_cache->misses;
				printf("Expert cache:   malloc %llu hits, %llu misses (%.1f%% hit rate), %d/%d entries used\n",
					   g_malloc_cache->hits, g_malloc_cache->misses,
					   total > 0 ? 100.0 * g_malloc_cache->hits / total : 0.0,
					   g_malloc_cache->num_entries, g_malloc_cache->max_entries);
				cache_telemetry_print(g_malloc_cache->hits, g_malloc_cache->misses);
			}

			if (g_spec_route_attempts > 0) {
				printf("Spec routing:   %llu attempts, %llu preloads, %llu hits (%.1f%% prediction accuracy)\n",
					   g_spec_route_attempts, g_spec_route_preloads, g_spec_route_hits,
					   g_spec_route_attempts > 0
						   ? 100.0 * g_spec_route_hits / g_spec_route_attempts : 0.0);
			}
			if (g_expert_prefetch_enabled) {
				double useful_pct = g_prefetch_reads_started
					? 100.0 * (double)g_prefetch_useful / (double)g_prefetch_reads_started : 0.0;
				printf("Expert prefetch: history=%d min-hits=%d max=%d candidates=%llu "
					   "reads=%llu cache-skipped=%llu useful=%llu wasted=%llu "
					   "useful-rate=%.1f%% blocking-misses=%llu layers=%llu\n",
					   g_expert_prefetch_history,
					   g_expert_prefetch_min_hits,
					   g_expert_prefetch_max,
					   (unsigned long long)g_prefetch_candidates,
					   (unsigned long long)g_prefetch_reads_started,
					   (unsigned long long)g_prefetch_cache_skipped,
					   (unsigned long long)g_prefetch_useful,
					   (unsigned long long)g_prefetch_wasted,
					   useful_pct,
					   (unsigned long long)g_prefetch_blocking_misses,
					   (unsigned long long)g_prefetch_layers);
			}

			if (g_freq_tracking) freq_print_analysis(K);
		}

		// Diagnostic-only: counts include every production dispatch observed while
		// this run was active (prefill + generation). Replay happens after generation
		// timing/statistics so it cannot affect reported generation tok/s.
		if (g_tiny_matvec_telemetry_enabled) {
			printf("\n[tiny-matvec telemetry]\n");
			printf("Production dispatch counts (prefill + generation):\n");
			printf("  32x2048: v3=%llu fast=%llu\n",
				(unsigned long long)tiny_telem_32x2048.calls_v3,
				(unsigned long long)tiny_telem_32x2048.calls_fast);
			printf("  1x2048:  v3=%llu fast=%llu\n",
				(unsigned long long)tiny_telem_1x2048.calls_v3,
				(unsigned long long)tiny_telem_1x2048.calls_fast);
			tiny_matvec_replay_benchmark(g_metal);
		}
		if (g_cmd1_profile_enabled) {
			cmd1_production_timing_print();
			cmd2_production_timing_print();
			cmd3_production_timing_print();
			cmd1_profile_replay(g_metal);
			cmd1_linear_detail_replay(g_metal);
		}

		if (g_routing_log) {
			fclose(g_routing_log);
			fprintf(stderr, "[routing] Logged %d samples to routing data file\n",
					g_routing_log_samples);
			g_routing_log = NULL;
		}

		// ---- Cleanup ----
		io_pool_shutdown();
		if (g_malloc_cache) {
			malloc_cache_free(g_malloc_cache);
			g_malloc_cache = NULL;
		}
		if (g_expert_cache) {
			expert_cache_free(g_expert_cache);
			g_expert_cache = NULL;
		}
		for (int i = 0; i < NUM_LAYERS; i++) {
			if (kv_caches[i]) kv_cache_free(kv_caches[i]);
			if (layer_states[i]) linear_attn_state_free(layer_states[i]);
			if (layer_mmaps[i] != MAP_FAILED) munmap(layer_mmaps[i], g_layer_mmap_sizes[i]);
			if (layer_fds[i] >= 0) close(layer_fds[i]);
			if (layer_fds_cold[i] >= 0) close(layer_fds_cold[i]);
		}
		free(layer_states);
		free(kv_caches);
		free(hidden);
		free(logits);

		return 0;
	}
}
#endif // CHAT_MODE
